		[7] = {
			title = "La Limpieza del Campamento Kóbold",
			accept = "$N, lo primero que tienes que hacer es limpiar. Un clan de Kóbolds ha invadido los bosques del norte. Ve y liquida a todos los Kóbolds que encuentres. Si reducimos sus filas podremos echarlos de Villanorte.",
			complete = "Buen trabajo. Los Kóbolds son ladrones y cobardes, pero en gran número suponen una amenaza más para los humanos de Ventormenta.$B$BTe agradezco lo que has hecho.",
		},
		[8] = {
			title = "Un trato de pícaro",
			accept = "¡Eh, colega! ¿Le harías un favor a un joven hombre que ha combatido contra más zombis y arañas de los que puede contar?$B$BTengo una carta que tiene que llegar a Rémol... Es para una tabernera llamada Renee no sé qué. No creo que importe cómo se apellida, la verdad.$B$BPero el sitio es muy acogedor y está lleno de víctimas de la Plaga que intentan abrirse paso en el mundo. Es el sitio ideal para descansar... si es que necesitas hacerlo. Anímate... si vas, te pagaré bien.",
			complete = "¿Eh? ¿Una carta? ¡Qué bien! Estaba esperando noticias de mi querida madre, que está en Camposanto. Es una santa, eso es lo que es. Me pregunto qué tal estará.$B$B¿Qué? ¿Qué? ¿Sueno demasiado alegre? No te he engañado, ¿eh?$B$BPues me da igual. Y además, tampoco te importa de quién es la carta. ¡Hala! ¡Aire!$B$BVuelve cuando tengas dinero que gastar, holgazán.$B$BYa volverás, ya, cuando necesites descansar después de unos días de aventuras o de alguna estupidez parecida.",
		},
		[9] = {
