		[3661] = {
			title = "¿Creados por Elune?",
			accept = "Los lechúcicos salvajes son muy impredecibles, $n. Pueden ser muy mansos, pero si se sienten amenazados se vuelven extremadamente feroces.$B$BSe dice que fueron creados por Elune; me gustaría saber si es verdad.$B$BHe oído que hay lechúcicos salvajes en las Tierras del Interior: las lechubestias feroces, primitivas y salvajes. Las encontrarás con el resto de la fauna local. ¿Me traerás unas cuantas plumas?",
			complete = "Gracias, $n.$B$B¿Aprendiste algo de esas criaturas?$B$BCon estas plumas sabremos más de su naturaleza.$B$BVoy a estudiarlas; tú dedícate a tus cosas y vuelve a hablar conmigo en otro momento.",
		},
		[3681] = {
			title = "Escrito sobre divinidad",
			accept = "Perdona por interrumpir tu viaje, $r, pero creí que deberías saber que ha llegado de Ventormenta un aviso que requería que los paladines regresaran para ser instruidos.$B$BSi no supiera que es imposible, diría que estás cerca del momento en el que te tocará estudiar los Libros.$B$BBusca a Duthorian Rall en Ventormenta. Normalmente entrena a los paladines en la Catedral de la Luz.",
			complete = "$gBienvenido:Bienvenida; a la Catedral de la Luz, $c.",
		},
		[3701] = {
			title = "Las humeantes Ruinas de Thaurissan",
			accept = "Intérnate en las ruinas de Thaurissan, en Las Estepas Ardientes, y consigue toda la información que puedas.$B$BDicen que las ruinas están plagadas de tesoros misteriosos. Empieza tu búsqueda por ahí, $n. Ten cuidado con los guardias de Thaurissan: son asesinos que protegen las ruinas y los secretos que hay en ellas.",
			complete = "Esto explica mucho sobre Thaurissan.$B$B¡Qué interesante!",
		},
		[3702] = {
			title = "Las humeantes Ruinas de Thaurissan",
			accept = "¿Te cuento la historia de los enanos Hierro Negro?",
			complete = "¿Proseguimos?",
		},
		[3721] = {
			title = "Tu propio OOX",
			complete = "¡Has recuperado tres de mis robots mensajeros OOX! Has hecho mucho más de lo que tenías que hacer, así que te daré algo especial por toda tu ayuda. Es una versión miniatura del robot que tan bien conoces, ¡el OOX!$B$BNormalmente, no dejaría que nadie tuviese un dispositivo tan potencialmente letal, pero tú has sido de gran ayuda. Además, el mecanismo de combate y las funciones de búsqueda de este robot están desactivados.$B$BPor todo lo demás, ¡es un OOX auténtico!",
		},
		[3741] = {
			title = "El collar de Hilary",
			accept = "Mi amiga Hilary ha perdido su collar. Hemos estado pescando todo el día justo aquí, pero ya hemos mirado. Tiene que haberse caído en el lago. Nuestros padres no nos dejan nadar porque dicen que hay cosas malas en el lago. Pero seguro que tú no tienes miedo de las cosas malas.$B$B¿Puedes buscar su collar, por favor?",
			complete = "Gracias por encontrar mi collar, $gseñor:señora; $c... Mi gatita también dice gracias, ¿a que sí, Effsee?",
		},
		[3761] = {
			title = "Tierra de Un'Goro",
			accept = "Se dice que la tierra del Cráter de Un'Goro ha sido enriquecida con potentes cualidades mágicas por lo que el Círculo Cenarion quiere estudiarla en grandes cantidades; ve a los páramos de Un'Goro y consigue suficientes muestras para que podamos continuar con nuestras investigaciones.$B$BEl suelo enriquecido formará pilas de cuando en cuando y es posible que las bestias que allí habitan posean muestras que te pudieran servir. Simplemente busca las pilas y estate $gatento:atenta; a los tauren, y después llévale todo a Ghede. ¡Él tiene buenas intenciones pero más te vale que no lo cabrees!",
			complete = "Muy bien, soldado $n. ¡Quédate ahí mirando y no me ayudes a descargar la tierra! Si los Grandes Espíritus hubieran querido descargarla por arte de magia, ya lo habrían hecho, ¿no crees?$B$BEl archidruida Tótem de Runa quiere hablar contigo de nuevo pero para su siguiente tarea debes saber que le resultaría útil contar con un oficial herborista. Si no te ajustas al perfil, no te preocupes. Seguro que habrá algo en lo que le puedas ser de utilidad.",
		},
		[3762] = {
			title = "Ayuda al archidruida Tótem de Runa",
			accept = "¿Tienes un minuto, $c?$B$BEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.$B$BSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.",
			complete = "Saludos, $c; Me alegra que estés $ginteresado:interesada; en ayudar en nuestra investigación. Queda mucho por hacer, y te haría un flaco favor si no te informara que el trabajo que esto conlleva es peligroso. Con suerte, esto no te asustará... pero por tu apariencia, supongo que el peligro es algo con lo que has lidiado antes.",
		},
		[3763] = {
			title = "Ayuda al archidruida Corzocelada",
			accept = "Perdona, $c, ¿podrías concederme un momento?$B$BEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.$B$BSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.",
			complete = "Bien, $c, veo que fuiste $ginformado:informada; de que yo encabezaba la investigación en persona, y es evidente que viniste tan rápido como pudiste.$B$BAhora que estás aquí, presta atención, pues te daré los detalles una sola vez, no me gusta repetirme.",
		},
		[3764] = {
			title = "Tierra de Un'Goro",
			accept = "Se dice que el suelo del Cráter de Un'Goro ha sido enriquecido con potentes cualidades mágicas. Quiero saber qué hay de cierto en esto. Ve a los páramos de Un'Goro y consigue muestras fiables del suelo para que podamos estudiarlas.$B$BY si crees que estás muy por encima de tareas de recogida, no conseguirás ni mi respeto ni el del Círculo Cenarion. Lleva las muestras a Jenal que sin duda estará perdiendo el tiempo detrás de este árbol. Busca los montones de tierra. Él se encarga de la logística. No yo.",
			complete = "Aligera aquí tu preciosa carga, noble $c. Ha debido de ser un gran peso... como el que llevo yo por ser un visionario. Aquí tienes un honorario por tu trabajo, tal y como dictó el propio archidruida.$B$BEl archidruida Corzocelada quiere hablar contigo de nuevo, $n. Pero para la siguiente tarea que te encomiende necesitarás tener los conocimientos de botánica de un oficial. Aunque, si no los tienes, también podrás ayudar al Círculo.",
		},
		[3765] = {
			title = "Lejana corrupción",
			accept = "Ventormenta... un centro de mucho movimiento.$B$BVengo desde muy lejos buscando ayuda. A menudo se dice que hay valientes aventureros caminando por las calles de esta ciudad.$B$BMi hermano, Gershala, necesita ayuda en Costa Oscura. Vive en la ciudad costera de Auberdine.$B$BEl viaje es largo y épico. Por esta razón, necesito la ayuda de $gun:una; $c con experiencia como tú.",
			complete = "Así que te ha enviado aquí mi hermano Argos, ¿eh? Supongo que debes de estar $gagotado:agotada; de tanto viaje. Pero tenemos mucho que hablar.",
		},
		[3781] = {
			title = "Investigar la mañagrana",
			accept = "Con lo que llamamos una faltriquera de siempreverde hemos cultivado semillas de Tharlendris en tierra del Cráter de Un'Goro. Estas semillas producen una gran variedad de hierbas potentes de forma aleatoria. Una de esas hierbas es la mañagrana, una hierba misteriosa de la que sabemos poco. Pero yo tengo intención de estudiarla a fondo.$B$BLleva esto a Mathrengyl. Está escaleras abajo. Él te dará algunas semillas para que empieces. Si te quedas sin reservas, puedes comprarle más.",
			complete = "Sí, este vale es para veinte paquetes de semillas. Si se te acaban, podremos proporcionarte más. Aunque, por desgracia, producir grandes números de semillas de Tharlendris resulta bastante costoso. Por eso el Círculo Cenarion pide a quienes nos están ayudando que participen asumiendo parte de su coste.$B$BQuienes traigan mañagrana, encontrarán que la recompensa que ofrece el archidruida compensa con creces ese coste.",
		},
		[3782] = {
			title = "Investigar la mañagrana",
			accept = "Con lo que llamamos una faltriquera de siempreverde hemos cultivado semillas de Tharlendris en tierra del Cráter de Un'Goro. Estas semillas producen una gran variedad de hierbas potentes de forma aleatoria. Una de esas hierbas es la mañagrana, una hierba misteriosa de la que sabemos poco. Pero yo espero poder estudiarla a fondo para el Círculo.$B$BEntrégale este vale a mi hija Bashana y ella te dará algunas semillas para que puedas ayudarnos. Si te quedas sin ellas, tendrás que comprarle más.",
			complete = "Por este vale puedo darte veinte paquetes de semillas. Si te quedas sin ellas, siempre puedes comprarme más.$B$BPor desgracia, $n, resulta muy costoso cultivar semillas de Tharlendris en grandes cantidades. Por eso el Círculo Cenarion pide a quienes nos están ayudando que participen asumiendo parte de su coste. Aquellos que traigan mañagrana recibirán una recompensa del archidruida que compensará con creces los gastos.",
		},
		[3783] = {
			title = "Yeti... ¿ya hemos llegado?",
			accept = "Mis amigos siempre aparecen con grandes ideas. Siempre me ha parecido que no estaba a su altura... ¡hasta hoy! ¡Acabo de trazar el diseño de algo tremendo! Si me prometes no decir nada, te dejaré conocer el secreto...$B$B¡Voy a hacer un yeti mecánico! No solo servirá para asustar a mis amigos... ¡cuando esté listo será realmente impresionante!$B$BPara empezar necesito pelaje de yeti grueso. ¿Me ayudarás? Podrás encontrarla al sureste de aquí.",
			complete = "Estas pieles son perfectas, $n. ¡Vamos a empezar a hacer algo grande!",
		},
		[3784] = {
			title = "Ayuda al archidruida Tótem de Runa",
			accept = "¿Tienes un minuto, $c?$B$BEl Círculo Cenarion de Cima del Trueno está buscando aventureros curtidos para un importante proyecto de investigación. No conozco los detalles, pero has de saber que quien dirige el proyecto es el mismísimo archidruida Hamuul Tótem de Runa.$B$BSi te interesa, habla con él directamente. Lo encontrarás en el Alto de los Ancestros, en Cima del Trueno.",
			complete = "Saludos, $C; Me alegra que esté interesado en ayudar en nuestra investigación. Queda mucho por hacer, y les haría un flaco favor si les informara que el trabajo que esto conlleva no es peligroso. Con suerte, esto no te asustará ... pero por tu apariencia, supongo que el peligro es algo con lo que has lidiado antes.",
		},
		[3785] = {
			title = "Investigar la mañagrana",
			accept = "Aquí tienes la faltriquera de siempreverde que necesitarás para las semillas de Tharlendris. También necesitarás algo de tierra de Un'Goro. Servirá de fertilizante para las semillas. Usa la bolsa cuando tengas todo. La bolsa se encargará de lo demás.$B$BCuando tengas suficiente mañagrana, tráemela aquí, al Enclave. Y por favor, no molestes al archidruida. Es un hombre muy ocupado y no es necesario interrumpirle cada vez que llega alguien con un poco de mañagrana.",
			complete = "Bien hecho, $n. Me aseguraré de dárselas al archidruida cuando las necesite. Mientras tanto, acepta esto como muestra del aprecio del Círculo Cenarion.$B$BNecesitamos mañagrana continuamente. Si quieres seguir ayudándonos, vuelve a mí cuando hayas cultivado más mañagrana.",
		},
		[3786] = {
			title = "Investigar la mañagrana",
			accept = "Aquí tienes la faltriquera de siempreverde que necesitarás para las semillas de Tharlendris. También necesitarás algo de tierra de Un'Goro que servirá de fertilizante para las semillas. Usa la bolsa cuando tengas todo y esta se encargará de lo demás.$B$BCuando tengas suficiente mañagrana, tráemela aquí, al Alto de los Ancestros. Y por favor, no molestes al archidruida. Estará muy ocupado con sus investigaciones y además tiene muchos asuntos más de los que ocuparse.",
			complete = "Bien hecho, $n. Me aseguraré de dárselas al archidruida cuando las necesite. Mientras tanto, acepta esto como muestra del aprecio del Círculo Cenarion.$B$BNecesitamos mañagrana continuamente. Si quieres seguir ayudándonos, vuelve a mí cuando hayas cultivado más mañagrana.",
		},
		[3787] = {
			title = "La petición de Jonguja",
			accept = "Oye, perdona...$B$BTengo un colega que querría hablar contigo sobre la investigación que estás llevando a cabo en colaboración con el Círculo Cenarion. Es un druida y se llama Quintis Jonguja. Vive aquí, en el Bastión Plumaluna, en Feralas. Quiere hablar contigo sobre la mañagrana. Y me ha pedido mucha discreción. No quiere que nada de esto llegue a oídos del archidruida.$B$BSi te interesa, habla con él. Sin duda, aclararemos muchas cosas cuando hayáis hablado.",
			complete = "¡Gracias por venir, $gviajero:viajera;! Permite que me presente: soy Quintis Jonguja, druida y humilde servidor de Malfurión y del Círculo Cenarion. Mis colegas (el general Shandris Plumaluna y el Protectorado, igual has oído hablar de nosotros) y yo, queríamos hablar contigo sobre el trabajo que estás haciendo para Fandral Corzocelada en Darnassus.$B$BAntes de proseguir, quisiera pedirte que esta conversación quede entre nosotros. Si esto no te supone un problema, podemos continuar.",
		},
		[3788] = {
			title = "La petición de Jonguja",
			accept = "Oye, perdona...$B$BTengo un colega que querría hablar contigo sobre la investigación que estás llevando a cabo en colaboración con el Círculo Cenarion. Es un druida y se llama Quintis Jonguja. Vive aquí, en el Bastión Plumaluna. Quiere hablar contigo sobre la mañagrana. Y me ha pedido mucha discreción. No quiere que nada de esto llegue a oídos del archidruida.$B$BSi te interesa, habla con él. Sin duda, aclararemos muchas cosas cuando hayáis hablado.",
			complete = "¡Gracias por venir, $gviajero:viajera;! Permite que me presente: soy Quintis Jonguja, druida y humilde servidor de Malfurión y del Círculo Cenarion. Mis colegas (el general Shandris Plumaluna y el Protectorado, igual has oído hablar de nosotros) y yo, queríamos hablar contigo sobre el trabajo que estás haciendo para Fandral Corzocelada en Darnassus.$B$BAntes de proseguir, quisiera pedirte que esta conversación quede entre nosotros. Si esto no te supone un problema, podemos continuar.",
		},
		[3789] = {
			title = "Ayuda al archidruida Corzocelada",
			accept = "Perdona, $c, ¿podrías concederme un momento?$B$BEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.$B$BSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.",
			complete = "Bien, $c, veo que fuiste $ginformado:informada; de que yo encabezaba la investigación en persona, y es evidente que viniste tan rápido como pudiste.$B$BAhora que estás aquí, presta atención, pues te daré los detalles una sola vez, no me gusta repetirme.",
		},
		[3790] = {
			title = "Ayuda al archidruida Corzocelada",
			accept = "Perdona, $c, ¿podrías concederme un momento?$B$BEl Círculo Cenarion de Darnassus está buscando la ayuda de aventureros curtidos para un importante proyecto de investigación. No tengo muchos detalles pero puedo decirte que es el mismísimo archidruida Fandral Corzocelada quien encabeza esta investigación.$B$BSi la cosa te interesa, habla con él directamente. Lo encontrarás en el Enclave Cenarion, en Darnassus.",
			complete = "Bien, $c, veo que fuiste $ginformado:informada; de que yo encabezaba la investigación en persona, y es evidente que viniste tan rápido como pudiste.$B$BAhora que estás aquí, presta atención, pues te daré los detalles una sola vez, no me gusta repetirme.",
		},
		[3791] = {
			title = "El misterio de mañagrana",
			accept = "Permite que sea sincero contigo, $n. Estoy interesado, no, más bien preocupado por el hecho de que el archidruida de Darnassus esté utilizando el nombre del Círculo Cenarion además de sus recursos para procurarse grandes cantidades de mañagrana. Soy un investigador. Mi especialidad son las maldiciones. He oído que la mañagrana, en determinadas condiciones, exuda las mismas cualidades que las hierbas que se utilizaban en maldiciones primitivas.$B$BQuiero saber más y para eso necesito tu ayuda. Tráeme 10 plantas de mañagrana y yo cuidaré de ti.",
			complete = "Gah, estos granos de mañagrana me hacen sentir... raro. En nombre de Elune, ¿qué está haciendo Staghelm con estas cosas?$B$BDe todos modos, gracias de nuevo por tu ayuda. Aquí hay algo... ya sabes, por el esfuerzo. Mi investigación sobre la mañagrana va a llevar un tiempo y sin duda voy a necesitar más. Mientras estoy en eso, supongo que podría tomarme el tiempo para ver si el grano de mañagrana tiene algunos usos alquímicos pertinentes. Aún así, me siento incómodo incluso estando cerca de ellos.",
		},
		[3792] = {
			title = "Mañagrana a Bastión Plumaluna",
			complete = "Gracias $n; Solo los guardaré fuera de circulación por el momento. Aunque no dispongo de los recursos que tiene Staghelm, puedo darte algo por las molestias. De todos modos, quién sabe qué pasará si Staghelm sigue obteniendo Mañagrana sin parar. Algo sospechoso está sucediendo, recuerda mis palabras.$B$BRecuerda que siempre estoy buscando más Mañagrana. Tráelas de cinco en cinco.",
		},
		[3801] = {
			title = "El legado de los Hierro Negro",
			accept = "Saludos, $n. Me llamo Franclorn Forjador. Sí, el Franclorn Forjador responsable del revolucionario método de arquitectura. Seguro que has cruzado o has estado en alguna de mis obras a lo largo de tus aventuras en este mundo desgarrado por la guerra.$B$BDebes de estar preguntándote qué hago aquí y qué quiero de ti, dos preguntas muy válidas.$B$BNecesito tu ayuda, claro. A cambio de esa ayuda, te concederé la llave de las profundidades de mi execrable ciudad.",
			complete = "Ya sea la codicia lo que te trajo aquí o un acto de entrega altruista, lo que estás a punto de acometer es bueno para todos.",
		},
		[3802] = {
			title = "El legado de los Hierro Negro",
			accept = "Encontrarás a Finoso Virunegro pasado el Círculo de la Ley, en la Sala de los Oficios. Mata al miserable bellaco y recupera a Ferrovil.$B$BLleva a Ferrovil al Santuario de Thaurissan y coloca el martillo en su ubicación legítima: entre las manos de la estatua erigida en mi honor.$B$BCuando lo hayas hecho, el compartimento en el que guardé la llave maestra estará abierto. Y lo que es más importante, Ferrovil permanecerá para siempre jamás en mis manos. Si intentaran extraer el martillo, tanto la estatua como el martillo se harán añicos y se perderán para siempre.",
			complete = "El martillo se desliza firmemente en su lugar, en el puño del colosal monumento Hierro Negro. Un minúsculo compartimento se abre en la base de la estatua. En el interior encuentras...",
		},
		[3803] = {
			title = "Mañagrana para Darnassus",
			complete = "Excelente, esta Mañagrana sin duda complacerá al Archidruida. Sin embargo, debo admitir que... estar cerca de ella me hace sentir un poco incómodo. ¡Solo puedo imaginar lo difícil que es para el Archidruida tolerarlos en cantidades tan grandes!$B$BEsto es para ti, $n. El Círculo Cenarion te agradece tu continuo apoyo.",
		},
		[3804] = {
			title = "Mañagrana para Cima del Trueno",
			complete = "Excelente, llegado el momento esta mañagrana sin duda será de utilidad. Sabemos que los elfos de la noche también están estudiando estas plantas, aunque desconocemos con qué propósito las usarán si llegan a descubrir algo. El archidruida cree que seguiremos necesitando mañagrana hasta que descubramos los misterios que encierra esta planta.$B$BEsto es para ti, $n. El Círculo Cenarion te agradece tu constante apoyo.",
		},
		[3821] = {
			title = "Roca Machacamiedo",
			accept = "Enviaron a Sha'ni para investigar los informes sobre una extraña actividad ritualista procedente de los ogros Pirontraña de Las Estepas Ardientes hace unas tres semanas.$B$BDientegore dice que no ha tenido noticias de nadie de esa sección y que es mejor que siga adelante y me centre en mi tarea actual. ¿Te lo puedes creer? ¡Se trata de mi esposa!$B$BNo puedo abandonar mi puesto, $n, pero necesito saber qué le ha ocurrido a Sha'ni. Ve a Las Estepas Ardientes y búscala.",
			complete = "Pobre Thal'trak.$B$BHabíamos planeado mudarnos a vivir juntos con mi madre y mi padre en las Tierras del Interior al acabar nuestra gira. ¡Ahora todo se ha venido abajo!",
		},
		[3822] = {
			title = "Krom'Grul",
			accept = "Han capturado a toda mi sección, $n. Todos ejecutados, excepto yo.$B$BSu jefe, Krom'Grul, quería reservarme para algún tipo de ritual.$B$BLa bestia me encadenó a este altar y me dio una paliza. Mi ser físico dejó de responder después de una hora de tortura. La bestia me arrancó entonces mi aro de la nariz y se la puso en el dedo. ¡Nunca había visto semejante salvajada!$B$B¡Encuentra a Krom'Grul y mátalo! Después devuélvele mi alianza a Thal'trak.$B$BY, $n, dile que nos volveremos a encontrar... en otra vida.",
			complete = "<Thal'trak se derrumba.>$B$BÍbamos a mudarnos a las Tierras del Interior. ¿Te lo dijo? Esta iba a ser su última misión...$B$B<Thal'trak solloza.>$B$BNo la quiero, $n. Quédatela, deshazte de ella, ¡no me importa! La sortija ahora ya no significa nada para mí. No sin ella...",
		},
		[3823] = {
			title = "El exterminio de los Pirontraña",
			accept = "¡Debemos atacar al enemigo antes de que ellos lo hagan!$B$BSeré breve, soldado.$B$BLos ogros Pirontraña de Las Estepas Ardientes son aliados de los ogros Roca Negra. Colaboran estrechamente con esos malvados orcos, manteniendo la vigilancia sobre la Roca Machacamiedo y sus abundantes minerales, así como garantizando que el suministro sea constante.$B$BQue noten tu presencia, $n. Diezma sus tropas y vuelve aquí cuando hayas hecho tu trabajo.$B$B<Oralius hace un gesto como estrangulando el aire.>$B$B¡TE MATARÉ, WINKY!",
			complete = "¡Fantástico, soldado! Los orcos y los ogros se tambalearán unos minutos tras este ataque, ¡a lo mejor hasta horas!",
		},
		[3824] = {
			title = "Gor'tesh, el Señor de los toscos",
			accept = "Se tambalean, ¡te lo digo yo! Nuestro próximo ataque debe ser decisivo.$B$BHay que matar al señor de los toscos, Gor'tesh. Es más, quiero que me traigan su cabeza para poder preparar la tercera fase de nuestro ataque a los ogros Pirontraña.$B$BPor cierto, soldado, Gor'tesh no gobierna desde la Roca Machacamiedo sino desde un enclave orco Roca Negra al oeste de la Roca Machacamiedo.$B$BPor lo tanto, tus órdenes son sencillas. Encuentra a Gor'tesh y córtale ese cabezón que tiene. Vuelve aquí cuando hayas acabado tu trabajo.$B$B¡CIERRA EL PICO, WINKY!",
			complete = "¡Fíjate en esto, soldado! ¡Asqueroso! Cuando los ogros Ardentrañas vean esta gran jarra clavada en una estaca en la cumbre de su montaña, ¡se desatará la histeria colectiva!$B$B<Oralius rompe en una carcajada desenfrenada.>",
		},
		[3825] = {
			title = "Una cabeza ogro empalada = FIESTA",
			accept = "Solo queda una cosa más pendiente, soldado.$B$BMe he tomado la libertad de poner la cabeza de Gor'tesh en una pica. Solo tienes que llevar esta cabeza a la cima de la Roca Machacamiedo y clavarla en el suelo. Cuando lo hagas, ¡observa cómo esos ogros cobardes ponen pies en polvorosa! Cuando te hayas divertido lo suficiente, vuelve aquí y te recompensaré por esforzarte tanto en tu trabajo.$B$B<Oralius parece perder el contacto con la realidad.>",
			complete = "¡Excelente trabajo, soldado! ¡Simplemente asombroso! Oh, obtendré la medalla de la valentía por esto, eh, ¡quiero decir que serás $grecompensado:recompensada; generosamente por esto!",
		},
		[3841] = {
			title = "Un huérfano que busca un hogar",
			accept = "Oh, hola, $n. Me alegro de volver a verte. ¿Qué tal fue tu viaje a Darnassus?$B$BTe alegrará saber que por aquí hemos hecho muchos progresos en tu ausencia. Incluso logramos salvar un nido lleno de huevos. Por desgracia, la madre murió antes de que llegáramos a ella.$B$BDime, ¿te apetece tener una mascota? Los huevos eclosionarán pronto y las crías necesitarán $Gun buen padre:una buena madre;. ¿Y bien? ¿Qué dices?$B$BSi te interesa, lleva uno de los huevos a Quentin, está en el circuito de El Desierto de Sal. Él te dirá más.",
			complete = "Ah, un huevo de duende dardo. Y uno que está casi a punto de eclosionar, si no me equivoco. Es asombroso que hayas encontrado un espécimen, sobre todo uno en tan buenas condiciones. Se ven pocos en Feralas en estos tiempos. Entiendo que había varios cazadores furtivos por la zona, intentando capturarlos y matarlos por varios motivos. Es una pena... son unas criaturas muy hermosas cuando llegan a la madurez.$B$BY dime, ¿cómo ha llegado a tus manos semejante joya?",
		},
		[3842] = {
			title = "Una corta incubación",
			accept = "Los tejelunas, ¿eh? Intrigante. Muy intrigante. Ojalá los duendes dardo supieran apreciar lo que significa que ellos dos les cuiden. Son muy capaces.$B$BAsí que te regalaron el huevo. Entonces cuídalo durante el tiempo que quieras. Parece que está a punto de eclosionar, pero deberíamos asegurarnos de que está bien y no ha sufrido daños.$B$BSolo necesito dos elixires de entereza para hacer un pequeño hechizo que proteja al huevo. Tengo el resto de los componentes necesarios aquí.",
			complete = "Maravilloso. Esto funcionará muy bien. Dame un momento para mezclar mis componentes y veremos qué tan bien va a estar este huevo.",
		},
		[3843] = {
			title = "Un nuevo miembro en la familia",
			accept = "Un magnífico espécimen, $n. Si esta criatura sobrevive a la gestación, ¡será una mascota muy sana!$B$BHay una cosa más que deberías hacer si quieres seguir con esto. Dirígete al Pico Nidal de las Tierras del Interior. Habla con un enano que encontrarás allí. Se llama Agnar Domabestias y es un gran estudioso de los animales. Él debería poder guiarte en la fase final de incubación.$B$BPero date prisa, $n, este huevo es frágil y no resistirá mucho sin los cuidados adecuados.",
			complete = "Bueno, bueno, bueno ... No he visto uno de estos dragones en años. Dragón de las hadas, si no me equivoco... parece ser de la variedad de duende dardo. Excelente, excelente en verdad.$B$BBueno, si este pequeño va a nacer y vivir para ser fuerte y saludable, entonces deberíamos conseguir algo de comida. Bien, tráela a tiempo.",
		},
		[3844] = {
			title = "Un secreto bien guardado",
			accept = "Descubres una balsa destrozada junto a la orilla. Esto es solo un pequeño estanque así que no puedes hacerte a la idea de cómo terminó aquí. No obstante, cuando miras a los árboles descubres que el nivel del agua puede no ser constante.$B$BQuizás si exploras un poco la zona descubras más pistas...",
			complete = "Encuentras una talega empapada en el fondo del estanque.",
		},
		[3845] = {
			title = "Un secreto bien guardado",
			accept = "Coges la talega y la llevas hasta la orilla. Tal vez examinando los objetos que contiene puedas averiguar a quién perteneció.$B$BHay algunos viajeros en el Refugio de Marshal. Quizás allí averigües algo más.",
			complete = "Oh... sí, esto me resulta familiar... en cierto modo...",
		},
		[3861] = {
			title = "¡CLOQUEA!",
			accept = "\"Coo-co-co-ri-cooo... ¡COOC!$B$BCoo-co-cooo.\"$B$BEl pollo te mira y empieza a rascar el suelo. Te parece que está escribiendo algo, pero no lo lees bien. ¿Podría ser... S-A-L-D-E-A-N? El pollo se marcha antes de que puedas preguntar.",
			complete = "\"¡COO-COOC!\"$B$BEl pollo se pone a engullir la comida.$B$BDe pronto se para, como sorprendido, y se agita incómodo. Vaya, este pollo no el un pollo, es una gallina... Será mejor que mires debajo, a ver.",
		},
		[3881] = {
			title = "Salvar a la expedición",
			accept = "No sé cómo conseguiste llegar hasta aquí, ¡pero eres una auténtica alegría para la vista! Soy Williden Marshal, y dirijo un grupo expedicionario independiente. Nuestro último y mayor esfuerzo se enfrentó a una serie innumerable de desastres, y el mayor de todos ellos fue la subestimada barbarie del Cráter de Un'Goro.$B$BCuando abandonamos nuestros campamentos base en las partes suroeste y noreste del cráter, dejamos atrás suministros de vital importancia. Pareces suficientemente $gcapacitado:capacitada;, ¿puedes ayudarnos a recuperarlos?",
			complete = "¡Conseguiste recuperar nuestros comestibles Y nuestro equipo de investigación! No solo has salvado la expedición, ¡has salvado nuestras vidas! Yo y el resto de mi equipo no podemos agradecértelo lo suficiente. Has hecho posible que podamos quedarnos aquí por un tiempo.$B$BAunque no tenemos mucho, no vamos a permitir que te vayas con las manos vacías después de toda la ayuda que nos has prestado. Gracias, $n, ¡ahora tienes un amigo en las Expediciones Marshal!",
		},
		[3882] = {
			title = "Choca esos huesos",
			accept = "Tal vez viendo que soy el jefe de excavaciones de las Expediciones Marshal, pienses que me gusta excavar. La verdad es que puede haber cosas peores en el mundo... pero no salto de alegría.$B$BSe supone que estábamos excavando en el Camino del Terror (un nombre FANTÁSTICO, por cierto) buscando diemetradones y stegodones muertos. ¡Y todavía quedan muchos vivos! Wil y Hol siguen estudiando este lugar, así que necesitamos huesos de esos dinosaurios. Pero entre tú y yo, también valdrá si traes huesos de ejemplares vivos.",
			complete = "Excelente, estos deberían servirnos. Y ahora, si me lo permites...$B$BGRACIAS POR DESENTERRAR TODOS ESTOS HUESOS PARA NOSOTROS Y NO HACER NI UN SOLO RASGUÑO A LAS BESTIAS NATIVAS.$B$BSi lo hiciste o no, no lo sé ni me importa. Dejémoslo tal y como está, ¿de acuerdo? Toma, quizás con esto mantengas la boca cerrada... ¡Estoy dispuesto a cualquier cosa con tal de salir de aquí con vida, ya te lo dije!",
		},
		[3883] = {
			title = "Ecología alienígena",
			accept = "¡Solo porque hayamos sufrido un contratiempo no debemos detener nuestra investigación! Antes de acabar aquí estábamos estudiando los insectos Gorishi en la parte meridional del Cráter. Su presencia es invasora y extraña en el sistema ecológico de Un'Goro y queremos descubrir por qué están aquí.$B$BEn su red de colmenas debe haber criaderos de larvas. Podrás identificar esos lugares por los huevos de larva que cuelgan por todas partes. Utiliza este vial para recoger muestras de pared de la colmena cerca de cualquier criadero y trae esas muestras para que las estudiemos. ¡Pero ten mucho cuidado!",
			complete = "Sí, esto servirá. Has sido de gran ayuda... Ojalá pudiera darte algo más, pero estando aquí atrapada en medio de la nada no tengo muchas cosas que ofrecerte. Pero descansa tranquilo, ¡esta investigación no hubiera sido posible sin tu ayuda!",
		},
		[3884] = {
			title = "Diario de Williden",
			accept = "Has descubierto un diario destrozado. Algunas partes siguen siendo legibles y, al parecer, el contenido es obra de un tal Williden Marshal. Si el diario no miente, Williden estará en algún lugar en el norte del Cráter. De acuerdo al diario, Williden y sus compañeros huyeron hacia las zonas más elevadas para refugiarse de las bestias salvajes del Cráter cuando sus campamentos base fueron invadidos.",
			complete = "¡Vaya, mira eso! ¡Mi diario! Pensaba que estaba perdido, como casi todo lo que trajimos a Un'Goro. ¡Muchísimas gracias por devolvérmelo!",
		},
		[3901] = {
			title = "Sacudir esqueletos",
			accept = "$n, has demostrado a los Renegados que tienes potencial... en circunstancias normales. Veamos qué tal funcionas bajo presión.$B$BLos esqueletos armadóseos, los esbirros más estúpidos del Rey Exánime, son enemigos más duros que los zombis a los que te has enfrentado hasta ahora. Reduce su número y demuestra a los Renegados lo que vales. No te entretengas: cuando hayas acabado, vuelve a hablar conmigo.",
			complete = "He acabado contigo, $n. Has demostrado ser $gmerecedor:merecedora; de la libertad que te ha sido concedida. Muchos serán los que se alzarán contra ti por lo que eres ahora, pero debes saber que, intenten lo que intenten contra nosotros, somos libres y no volverán a encadenarnos.$B$BCoge esto y ponte en camino. Tienes mucho que lograr, $c.",
		},
		[3902] = {
			title = "Hurgar en Camposanto",
			accept = "¡Eh, tú! Si buscas algo útil que hacer, ¡abre las orejas!$B$BNecesitamos reclutas fresquitos que vayan a Camposanto y busquen cualquier tipo de equipo que pueda sernos útil. Probablemente, estará en pilas de cajas. Dentro de poco se alzarán nuevos reclutas y, si no queremos que vayan por ahí desnudos, ¡más nos vale conseguirles algo que ponerse!$B$B¿Y bien? ¡Muévete, miserable saco de huesos! No habrá recompensa para los vagos.",
			complete = "Buen trabajo, $n, sabía que no eras $gun:una; inútil. Ten, acepta uno de los mejores objetos que he encontrado entre los lotes que hemos reunido hasta ahora.",
		},
		[3903] = {
			title = "Milly Osworth",
			accept = "$n, has demostrado que eres $Gun:una; $c de confianza y que no temes al trabajo duro.$B$BMi amiga Milly Osworth está en apuros. Tiene la carreta al otro lado de la abadía, cerca del establo. Seguro que le va bien que le eches una mano.",
			complete = "¿Que te envía el Ayudante del Alguacil Willem? Es valiente y voluntarioso, pero está en la Abadía de Villanorte...$B$B¿Tú podrías ayudarme?",
		},
		[3904] = {
			title = "La cosecha de Milly",
			accept = "¡Esa panda de bribones de Los Defias se instalaron en Viñedos de Villanorte mientras estaba vendimiando! Los denuncié a los guardias de Villanorte, que me dijeron que ya se encargarían, pero... ¡Temo por mis viñas! Si los Defias no las roban, me temo que entonces nuestros guardias las aplastarán cuando vayan a echarlos.$B$B¡Tienes que ayudarme! Ya tengo casi toda la uva recogida, pero dejé las cajas en los viñedos que hay al sureste.$B$B¡Tráemelas y salva mi cosecha!",
			complete = "¡Gracias, $n! ¡Has salvado mi cosecha! Espero que hayas dada una lección a unos cuantos Defias.$B$B¡Aunque tengamos pocas tropas, tenemos la suerte de contar con valientes como tú!",
		},
		[3905] = {
			title = "Informe de la vendimia",
			accept = "Ahora que has salvado mis uvas, llévale el Informe de la vendimia al hermano Neals. Se encarga del almacén de abastos de Villanorte; se alegrará de saber que la vendimia ha sido buena.$B$BEstá en el campanario de la abadía; le gusta sentarse allí a probar el vino.",
			complete = "Veamos...$B$BOh, has salvado la uva; me preocupé cuando me habló de esos villanos en los viñedos. Por suerte, nunca perdí la fe en la Luz.$B$BY ahora, gracias a tu valor, podremos hacer vino. Que la Luz te acompañe y te proteja, $n.",
		},
		[3906] = {
			title = "La discordia de las llamas",
			accept = "Los miembros del consejo han sentido una perturbación en los elementos. Los enanos Hierro Negro han invocado a un espíritu maligno en nuestro mundo que amenaza con una catástrofe en nuestras tierras en forma de inundación permanente. Hay que investigar la discordancia de las llamas.$B$BVe hasta la Montaña Roca Negra, atraviesa el Abismo de Llama y hasta la cantera. Allí encontrarás al Señor del Fuego: Maestro Supremo Pyron.$B$BPon fin a la perturbación y vuelve aquí.",
			complete = "No puede... no debe ser. La destrucción de Pyron solo ha levantado un velo. En las profundidades de Roca Negra hay una fuente de corrupción mucho más insidiosa.",
		},
		[3907] = {
			title = "La discordia del fuego",
			accept = "Puedo oler que el aire que te rodea está viciado, $n. Hay otro ente, oculto en las profundidades de Roca Negra, que lo controla.$B$BEl viento y la tierra gritan su nombre: Lord Incendius... pero alguien... algo... manda en este ente. Es un mero emisario.$B$B¡Encuéntralo y descubre dónde se oculta su maestro! Vuelve a mí cuando hayas obtenido esta información.|n",
			complete = "<Corazón Atronador se aferra a la tablilla de Kurniya.>$B$BRagnaros... aquí...$B$BLos ancianos tenían razón en temer la corrupción que emanaba de la Montaña Roca Negra. ¡Un general de los antiguos dioses! ¡EN NUESTRO MUNDO! Debemos revisar nuestras posiciones aquí en Kargath. Tenemos que decidir si quedarnos a luchar o escapar ante la posibilidad de un nuevo diluvio.$B$BTen mucho cuidado en cualquier nueva exploración en la Montaña Roca Negra, $n. Un mal mucho mayor que cualquiera concebible en este mundo se encuentra en esas salvajes profundidades.",
		},
		[3908] = {
			title = "Un secreto bien guardado",
			accept = "Verás, no tengo ni idea de cómo terminé aquí. Nadie lo sabe... ¡es un secreto para todos! Es como si no pudiera acordarme de nada...$B$BPero estos objetos que me has traído... Estoy recordando algo.$B$BMi espada. Creo tengo que reforzarla por alguna razón, pero no sé muy bien el motivo. Lo siento, no puedo decirte más, ¡pero es que no puedo recordarlo!$B$BEn cualquier caso, sí que sé adónde puedes llevarla: con Donova Cubilnevado de Cuna del Invierno. La encontrarás junto a las fuentes termales. Ella podrá templar la espada junto a las pozas.",
			complete = "Sí, claro que puedo templar la espada. Mientras trabajo puedes ir explicándome por qué le ha costado tanto tiempo a Linken traérmela. No suele olvidarse de nada...",
		},
		[3909] = {
			title = "El Elixir de Videre",
			accept = "¿Y ahora qué pasa? Linken... ¿SE OLVIDÓ?$B$BOh, entiendo... Ha perdido la memoria...$B$BBueno, aquí está su espada. Pero no está terminada. Sé quién podría hacerlo, pero... hablar con él puede ser difícil.$B$BEscucha, sé de alguien que puede ayudarte. Es una larga historia y no puedo explicártela ahora, pero debes hacerte con un Elixir de Videre. Solo sé de una persona que pueda ayudarte a conseguirlo, Gregan Tirabirras. No es fácil dar con él, pero lo último que supe es que estaba acampado en las tierras salvajes de Feralas.",
			complete = "Necesitaré un vial para asegurarme de que este es de verdad el Elixir... Sí... Esto es.",
		},
		[3912] = {
			title = "Encuentro en la tumba",
			accept = "Con la ayuda de este elixir podrás hablar con el que nunca se dejaría ver...$B$BLleva el Elixir de Videre y la Espada de Linken al cementerio que encontrarás a las puertas de Gadgetzan en Tanaris. Cuando estés allí, bebe la poción. Quizás te sorprendan los resultados, pero no te alarmes.$B$BEn tu \"otra\" forma dirígete hacia el Norte, hasta llegar a las montañas. Encontrarás a aquel con quien debes hablar en una de las grietas rocosas. Su nombre es Gaeriyan.$B$BPero recuerda, solo hablará contigo si adoptas esa forma...\\",
			complete = "Ha pasado mucho tiempo desde que vinieron a hablar conmigo por última vez...",
		},
		[3913] = {
			title = "Una situación mortal",
			accept = "Si vuelves al cementerio, $n, encontrarás una lápida... No será una lápida cualquiera, destacará sobre todas las demás. Los secretos yacen en ella.$B$BEmpuja la lápida y aprenderás de esos secretos...",
			complete = "Empujas la lápida con fuerza, y se desliza a un lado mostrando un pequeño hueco debajo de ella.$B$BCuando colocas la Espada de Linken en el hueco te das cuenta de que encaja a la perfección...",
		},
		[3914] = {
			title = "La Espada de Linken",
			accept = "Tras un fuerte destello de luz puedes volver a coger la espada. ¡Se ha transformado!",
			complete = "Mi espada... ¡está terminada!$B$BSi tan solo pudiera recordar para qué la necesitaba...$B$BToma, deja que al menos te pague algo por tu trabajo.",
		},
		[3921] = {
			title = "Wenikee Tuercasmil",
			accept = "Creo que he metido la pata de verdad: me parece que he metido uno de los fluxores de soporte entre los radios del engranaje desregulador. Podemos arreglarlo sin problemas. Conozco a una experta en pistones de triple expansión que se moriría por echarle el guante a un churumbele. Llévale el churumbele averiado a Wenikee Tuercasmil, al sur de La Empalizada de Mor'shan, y lo reparará en un periquete.$B$BOye, no hace falta que camines. ¡Esta es una oportunidad de oro para probar mi artefacto de teletransporte personal!",
			complete = "¿Qué es esto? ¿Un churumbele? ¿Qué es un churumbele?$B$BAh... pero fíjate cómo se mueve cuando lo manejas. Y se oyen engranajes en el interior. ¡Oh, por todos los...! Quiero arreglarlo y ver qué hace, ¿tú no?",
		},
		[3922] = {
			title = "Engranajes",
			accept = "Quiero arreglar este churumbele pero para eso voy a necesitar algunas cosas. Se me han acabado los engranajes del calibre diecisiete y medio y voy a necesitar un puñado para ese trabajo.$B$BEl lugar más cercano donde puedes conseguirlos es una estación de investigación no muy lejos de aquí y El Fangal, hacia el este. Ventura y Cía. suele tenerlos en sus cubos de herramientas. Mira en los cubos de herramientas que encuentres en cualquiera de las dos zonas y vuelve cuando hayas recolectado suficientes engranajes.",
			complete = "¡Genial, los tienes! Ahora puedo ponerme a trabajar…",
		},
		[3923] = {
			title = "Rilli Gapegajoso",
			accept = "Bueno, eso no funcionó. Puse unos calibres adicionales en el churumbele para medir su integridad estructural y las lecturas dan mínimos históricos. Podría añadir algún dial más y quizás una palanca o dos para intentar repararlo pero... creo que solo empeoraría las cosas.$B$BDeberías llevarle el churumbele a Rilli Gapegajoso. Antes trabajaba para Ventura y Cía., si alguien sabe cómo arreglarlo, ese es Rilli.$B$BLo encontrarás en el Rincón de la Maquinaria de Nogg en Orgrimmar, en el Valle del Honor.",
			complete = "¿Qué es esto? ¡¿Qué?! ¡Es un churumbele! ¿Dónde lo has conseguido? ¿Has estado curioseando por las instalaciones de Ventura y Cía. en Los Baldíos?$B$BDebes de ser muy valiente, o muy $gestúpido:estúpida;.",
		},
		[3924] = {
			title = "El manual del churumbele",
			accept = "Creo que puedo arreglar el churumbele, pero primero voy a necesitar leer el manual. Cuando estaba en la Compañía Ventura y Cía. tenía un rival, el jefe Encobre, que atesoraba los secretos del churumbele, y comentaba algunos detalles solo a quienes tenía plena confianza. Yo no era de los de su confianza...$B$BEl jefe Encobre solía andar por la Mina Pedrusco, en la parte noreste de Los Baldíos. Consigue el manual. Si ves que faltan páginas, seguro que se las ha dado a otros, así que deberás conseguirlas como puedas.",
			complete = "¡Tienes el manual! ¡Me muero por leerlo y averiguar cómo reparar el churumbele! Hablé con Petardol en Trinquete, quería agradecerte tu ayuda y recompensarte por tu trabajo.$B$BTambién yo quiero darte las gracias, y si algún día consigo reparar este artilugio, te lo haré saber...",
		},
		[3941] = {
			title = "La ayuda de una gnoma",
			accept = "Piensa... Piensa... Sé que he venido aquí por algo importante...$B$BTengo una idea, $n. En esa cueva de ahí, encontrarás a una gnomo llamada J.D. que fue muy amable conmigo cuando llegué aquí. Quizás en mi desorientación le dijera algo.$B$B¿Por qué no vas a preguntarle qué es lo que sabe? Ah, pero ten cuidado... siempre anda liada con esos cristales brillantes que he visto por el cráter. No estoy muy seguro de qué es lo que se trae entre manos.",
			complete = "Espera solo un momento... Estoy probando una nueva combinación de cristales...",
		},
		[3942] = {
			title = "Recuerdos de Linken",
			accept = "Oh... ¿Linken? Sí, es muy divertido. Cuando llegó aquí no paraba de mascullar sobre las cosas más extrañas. Seguramente se dio un golpe en la cabeza.$B$BPero dijo algo que se me quedó grabado... que estaba haciendo una especie de tótem y que tenía que hablar con alguien llamado Eridan Vientoazul... en un lugar conocido como Frondavil, me parece.$B$BPero no creo que pueda decirte mucho más. Si quieres más información deberías ir a buscar a Eridan tú $gmismo:misma;.",
			complete = "Hola, $c. ¿Puedo ayudarte en algo?",
		},
		[3961] = {
			title = "La aventura de Linken",
			accept = "Y pensar que el motivo que trajo a Linken hasta aquí fue el librarnos de Correfuego... Parece un muchacho completamente normal, pero ya observé que no estaba muy interesado en mis experimentos e inventos, como lo estaría cualquier otro gnomo. Debe ser un auténtico guerrero.$B$BLlévale el tótem, quizás le ayude a recordar la razón por la que vino aquí.",
			complete = "¿Te ayudó J.D. en algo?",
		},
		[3962] = {
			title = "Ir solo es peligroso",
			accept = "$n, por fin recuerdo... Vine aquí para combatir a Correfuego. Estaba de viaje y este tenía que ser el último paso.$B$BPero he dejado de ser el héroe... ahora lo eres tú. Y por eso eres tú quien debe concluir todo este trabajo, no yo.$B$BCorrefuego cuida de un artefacto llamado la Llama Dorada. Otorga el mayor poder que haya visto nunca y es peligroso en manos de alguien con mal corazón.$B$BTendrás que llevar a otros contigo, es peligroso ir solo. Considéralo como mi consejo.",
			complete = "Gracias, $n.$B$BLa Llama Dorada volverá por fin a mi hogar, allí la protegerán y nunca volverá a caer en manos del mal.$B$B¡Sin tu ayuda todavía seguiría sin saber quién soy! Como has hecho tanto por mí, me gustaría darte algo muy especial...$B$B¡Elige lo que quieras!",
		},
		[3981] = {
			title = "Comandante Gor'shak",
			accept = "Pobre Gargal... no le dio tiempo ni a olerla. ¡BAM! La flecha se le clavó en el mismísimo centro de la cabeza. No es que fuera una lumbrera antes pero ahora...$B$B<Galamav esboza una mueca.>$B$BCuando le extrajimos la flecha, descubrimos una nota enrollada en el asta. En la nota había un dibujo burdo de un orco entre rejas con la firma del comandante Gor'shak adjunta.$B$BSi aún está vivo en las Profundidades, tendrás que encontrarlo.$B$B¿Una trampa? No estoy de broma, ¡pezuñas entumecidas! ¡Por eso vas!|n",
			complete = "No tenemos mucho tiempo. Escucha atentamente, $r. Lo que tengo que decirte es confidencial y solo para tus oídos.",
		},
		[3982] = {
			title = "¿Qué pasa?",
			accept = "Me enviaron aquí bajo los auspicios de Thrall. ¿En serio crees que estos patanes podrían capturarme? Dejé que me apresaran para poder espiarlos.$B$B<Gor'shak habla ahora susurrando.>$B$BEl Emperador Thaurissan ha secuestrado a la Princesa de Forjaz. ¡La Princesa Barbabronce se encuentra aquí mismo en esta ciudad! Apuesto a que a Magni casi le da un infarto cuando lo supo.$B$B<Gor'shak suelta una carcajada.>$B$B¡Chitón! ¿Has oído eso? ¡Se acerca la guardia! ¡DEFIÉNDETE!",
			complete = "Eso ha estado muy cerca. Tu presencia los ha alertado... no tardaremos en ver los efectos.",
		},
		[4001] = {
			title = "¿Qué pasa?",
			accept = "Hasta ahora mi comunicación con Kharan, el enano que está en la celda al otro lado del vestíbulo, ha sido escasa. Sin embargo, he logrado convencerle de que yo, bueno, nosotros, no queremos hacerle ningún daño.$B$BVe a hablar con él y sácale toda la información que puedas sobre la Princesa y sus secuestradores. Después informa de todo ello al Jefe de Guerra.$B$BThrall no quiere que se hiera a la Princesa, por lo que ha elaborado un minucioso plan según el cual podrá volver sana y salva a Forjaz. Kharan ya está al tanto... ¡Vete!|n",
			complete = "Esta es una oportunidad para la Horda para cambiar para siempre el clima político de nuestro mundo desgarrado por la guerra. Escucha atentamente, $n.$B$BEl fracaso en esta misión no es una opción.",
		},
		[4002] = {
			title = "Los Reinos del Este",
			accept = "$n, la información que traes es excelente.$B$BMi deber como Jefe de Guerra es hacer lo que sea mejor para la Horda. Debo asegurar la libertad de las generaciones venideras.$B$BTenemos la oportunidad de formar nuestras futuras alianzas. Si ayudamos a los enanos, se estrecharían las relaciones con los Reinos del Este. ¡Por eso no puedes fallar!$B$B¿Estarás a la altura?",
			complete = "Este es el punto de no retorno, $n.",
		},
		[4003] = {
			title = "El rescate real",
			accept = "Si sale bien, este golpe a los Hierro Negro sacudirá los cimientos de su reino.$B$BLa princesa Barbabronce está bajo el control del emperador Thaurissan; para liberarla, tendrás que matarlo. Ten en cuenta que tu misión es doblemente peligrosa, porque la princesa intentará atacarte mientras esté controlada por el Emperador.$B$B¡¡Asegúrate de que no sufra daños!!",
			complete = "¡¿Qué has hecho, criminal?!",
		},
		[4004] = {
			title = "¿Princesa salvada?",
			accept = "¡Has matado a mi marido, $r! Mi hijo vendrá a este mundo sin un padre.$B$B<La Princesa Moira te señala directamente.>$B$BPuedes tener la certeza de que este niño será el próximo gobernante del Reino de Forjaz. Tú y todos los de tu especie sufriréis implacable persecución hasta el final de los tiempos por esta injusticia.$B$B<Crees que la Princesa Barbabronce aún puede estar sufriendo algún efecto del hechizo de Thaurissan.>$B$BY ahora déjame, $r. Estoy segura de que tu Jefe de Guerra estará impaciente por conocer los frutos de su intromisión.|n",
			complete = "<Thrall se muestra muy afectado por la información que acabas de darle.>$B$BUna nueva amenaza se cierne sobre el horizonte. Se acaban los años de Magni y con ello tendrá vía libre la estirpe no nata de Hierro Negro para gobernar Forjaz.$B$BHas cumplido lo que te había encargado y por ello serás $grecompensado:recompensada;.$B$B¡Márchate, $n! Debo discutir algo con Sylvanas y Cairne.",
		},
		[4005] = {
			title = "Aquamentas",
			accept = "Lleva esta bolsa de suministros a Tanaris. Dirígete a la Cala del Aparejo Perdido y busca un círculo de piedras.$B$BEl secreto reside en la península más oriental...$B$BSolo cuando te encuentres en el círculo, lee el Libro de Aquor e invoca la única criatura que puede transformar los objetos que has reunido en un tótem que te ayudará a combatir a Correfuego.$B$BA Aquamentas no le gustará que lo despierten, pero recuerda, debes permanecer en el círculo para poder transformar los objetos.",
			complete = "Correfuego, dices...$B$BSí, ese poderoso elemental vive en el tórrido centro del cráter. Procuramos mantenernos alejados, nadie ha podido atravesar la potente aura que le rodea. Muchos han salido volando montaña abajo al intentar acercarse a él.",
		},
		[4021] = {
			title = "¡Contraataca!",
			accept = "La Horda elogia tu éxito frente a los Kolkar pero estos están enfurecidos. Según varios informes, un contingente Kolkar ha viajado hasta Los Baldíos desde sus dominios en Desolace en busca de venganza. Las últimas noticias eran que, ahora mismo, ¡se dirigen a estos búnkeres desde el oeste!$B$BHaz frente a los invasores Kolkar y pon fin a esa amenaza en Los Baldíos. Mátalos hasta que aparezca su jefe, el señor de la guerra Krom'zar. Derrótalo y tráeme un pedazo de su estandarte como prueba.$B$BContamos contigo, $n.",
			complete = "¡Lo has logrado! ¡Has derrotado a Kolkar!$B$BMe aseguraré de que Thrall se entere de tus proezas en este lugar, $n.$B$BVe con la cabeza bien alta. Eres motivo de orgullo no solo para ti sino también para la Horda",
		},
		[4022] = {
			title = "Un sabor a llamarada",
			accept = "El Vuelo tiene conocimiento de tu trabajo en La Garganta de Fuego.$B$BEnséñamela, $r. La escama, imbécil.",
			complete = "<Cyrus examina la escama.>$B$BHas demostrado que no eres completamente inútil, mortal.",
		},
		[4023] = {
			title = "Un sabor a llamarada",
			accept = "¿Buscas al Vuelo? Apórtame una prueba de lo que vales, mortal.",
			complete = "<Cyrus examina la escama.>$B$BHas demostrado que no eres completamente inútil, mortal.",
		},
		[4024] = {
			title = "Un sabor a llamarada",
			accept = "Deseo probar las ardientes llamas de la montaña de fuego. Dejar que el calor del magma de Roca Negra recorra todo mi ser. Esa esencia, ese calor abrasador, es lo que ansío.$B$BBael'Gar mora en las Profundidades de Roca Negra: un ser que es llama pura, nacido de los fuegos de Ragnaros. Ejecuta a Bael'Gar y tráeme un poco de su fuego interno de entre sus ardientes restos.$B$BUsa la escama de sus restos para extraer sin peligro la llama interior.$B$BConsíguelo y recibirás tu merecida recompensa.",
			complete = "<Cyrus te arrebata la esencia fiera de las manos.>$B$B¡SÍ!$B$BToma tu recompensa y vete. ¡Desaparece inmediatamente de mi vista!",
		},
		[4041] = {
			title = "El Elixir de Videre",
			complete = "Así que se la has jugado al viejo Miblon, ¿eh?",
		},
		[4061] = {
			title = "La revuelta de las máquinas",
			accept = "Las máquinas se hicieron notar en nuestras primeras incursiones en La Garganta de Fuego. Después de investigar el asunto, descubrimos que las estaban importando de Las Estepas Ardientes, posiblemente desde las Profundidades de Roca Negra. Por eso te necesitamos, $n.$B$BTu tarea consistirá en aventurarte en Las Estepas Ardientes y recuperar los fragmentos de elementales de los robots de piedra y de otras creaciones de piedra menores de la región. Cuando hayas reunido la cantidad suficiente, vuelve aquí y determinaré la fuente de procedencia.|n",
			complete = "<Theodora dispone los fragmentos frente a ella.>$B$B<Theodora examina detenidamente los fragmentos con un enorme monóculo.>$B$BInteresante. En la fundación estructural de cada fragmento hay grabadas... iniciales.",
		},
		[4062] = {
			title = "La revuelta de las máquinas",
			accept = "G.L.A.$B$BEsas son las iniciales impresas en los fragmentos de elementales. Debajo de las iniciales hay algún tipo de rango. Las máquinas que destruiste en Las Estepas Ardientes eran del \"Rango IV\". Supongo que es un rango más bien bajo.$B$BLleva esta muestra de fragmento a Lotwil Veriatus en el campamento del este. Es un erudito de cierto renombre en ciencias elementales. Es posible que sea capaz de ayudarnos en esta investigación.",
			complete = "<Lotwil palidece.>$B$BHe... he visto antes estas marcas.",
		},
		[4063] = {
			title = "La revuelta de las máquinas",
			accept = "¡No puede ser Argelmach! Mataron a Argelmach hace diez años. ¿Que cómo puedo estar seguro? Yo mismo lo maté.$B$BEra un enano despreciable, empeñado en pervertir el trabajo de mi vida para satisfacer sus diabólicas necesidades. Parece que los malvados siempre consiguen escurrirse de la justicia.$B$BSi este es el trabajo de Argelmach, debe ser destruido. Necesitaré muestras de sus creaciones más recientes. Con las muestras adecuadas, puede que consiga detener esta revuelta. Las creaciones protegen a Argelmach en las Profundidades de Roca Negra.",
			complete = "¡¿Qué es esto?! Esta cabeza no es de carne. Esto es algún tipo de creación de hierro negro: una sombra de Argelmach, ¡OTRA máquina! Sospecho que tu destrucción de Argelmach no durará ya que otro surgirá para ocupar su lugar pronto.",
		},
		[4081] = {
			title = "MATAR INMEDIATAMENTE: enanos Hierro Negro",
			accept = "Por orden del señor de la guerra Dientegore, Comandante de la Fuerza Expedicionaria de Kargath:$B$BTodos y cada uno de los efectivos del general Forjainquina en las Profundidades de Roca Negra debe ser aniquilado.$B$BLos hombres de Forjainquina son crueles asesinos, responsables del asesinato masivo de la 109ª división de la Fuerza Expedicionaria de Kargath. Se recomienda a los héroes extremar la precaución al enfrentarse a estos animales.$B$BCualquier persona que destruya la primera línea del general Forjainquina en las Profundidades de Roca Negra recibirá un tributo.",
			complete = "Este primer ataque ha debido de provocarle alguna cana a los Forjainquina. Ahora, andando, soldado. Tengo trabajo que hacer, batallas que planificar, ¡enemigos a los que aplastar!$B$BSigue pendiente de los carteles de \"Se busca\" si quieres más trabajo.",
		},
		[4082] = {
			title = "MATAR INMEDIATAMENTE: oficiales Hierro Negro de alto rango",
			accept = "Por orden del señor de la guerra Dientegore, Comandante de la Fuerza Expedicionaria de Kargath:$B$BEl jefe de la división de reconocimiento de la F.E.K., maestro mayor Lexlort, ha vuelto con noticias sobre el paradero de oficiales Hierro Negro de alto rango. A puerta cerrada, cerca del corazón de la ciudad, entrenan a sus tropas para acabar con nuestros hombres. Ve a las Profundidades de Roca Negra ¡y destrúyelos!$B$BEl éxito en esta misión se traducirá en un tributo.|n",
			complete = "Forjainquina está sin lugar a dudas... furioso. Vuelve aquí cuando recibas un tercer tributo y procederemos con Operación: muerte a Forjainquina. No puedo entrar en detalles pero ten por seguro que alguien muere.",
		},
		[4083] = {
			title = "El cáliz espectral",
			complete = "Las gemas caen silenciosas en lo más hondo del cáliz...",
		},
		[4084] = {
			title = "Corazón de plata",
			accept = "No sé de quién hablas, $n.$B$BPero no te preocupes, si tu amigo quería encontrarme, sé qué estaba buscando.$B$BEn el corazón del Cráter de Un'Goro habita el mal en su forma más pura. Adopta la forma de un elemental llamado Correfuego... protegido por un aura que nadie puede disipar...$B$BNadie...excepto los que tienen suficiente poder para hacerlo. Puedo enseñarte ese poder, $n.$B$BPara empezar, haz lo que te pido. Reúne 11 zarpas plateadas y 1 corazón de Troncoferro, los obtendrás de las criaturas de Frondavil. Cuando tengas todo, vuelve a verme.",
			complete = "Muy bien, $n. Parece que te tomas muy en serio el ayudar a tu amigo.",
		},
		[4101] = {
			title = "Limpiar Frondavil",
			accept = "Las plantas dan vida a Frondavil, pero incluso ellas sufren la mácula de la corrupción. Conozco formas de limpiarlas, pero no puedo confiar tal conocimiento a alguien de quien no me fíe. Demuéstrame que realmente deseas apoyar la causa del Círculo Cenarion.$B$BAl norte están las Cavernas de Troncoferro. Los elementales alabeos que viven en ellas ya no pueden ser salvados. Te pido que me traigas su savia. La llaman ámbar de sangre. Quiero estudiarla para ver si puedo salvar a otras formas de vida de aquí.",
			complete = "Esta sangre ámbar se utilizará para encontrar un medio de acabar con la corrupción de Frondavil. Me has demostrado que estás deseando hacer cualquier cosa por ayudar al Círculo Cenarion. Ahora confío en ti.$B$BPuede parecer extraño que te ganaras mi confianza matando a los elementales, pero cualquier medio está justificado si nos ayuda a lograr un fin mayor: salvar a innumerables seres sensibles. Ahora podemos centrarnos en preservar la vida con los bálsamos que preparo.$B$B$n, ha llegado el momento de limpiar Frondavil.",
		},
		[4102] = {
			title = "Limpiar Frondavil",
			accept = "Las plantas dan vida a Frondavil, pero incluso ellas sufren la mácula de la corrupción. Conozco formas de limpiarlas, pero no puedo confiar tal conocimiento a alguien de quien no me fíe. Demuéstrame que realmente deseas apoyar la causa del Círculo Cenarion.$B$BAl norte están las Cavernas de Troncoferro. Los elementales alabeos que viven en ellas ya no pueden ser salvados. Te pido que me traigas su savia. La llaman ámbar de sangre. Quiero estudiarla para ver si puedo salvar a otras formas de vida de aquí.",
			complete = "Este ámbar de sangre se utilizará para encontrar un medio de acabar con la corrupción de Frondavil. Me has demostrado que estás deseando hacer cualquier cosa por ayudar al Círculo Cenarion. Ahora confío en ti.$B$BPuede parecer extraño que te ganaras mi confianza matando a los elementales, pero cualquier medio está justificado si nos ayuda a lograr un fin mayor: salvar a innumerables seres sensibles. Ahora podemos centrarnos en preservar la vida con los bálsamos que preparo.$B$B$n, ha llegado el momento de limpiar Frondavil.",
		},
		[4103] = {
			title = "Bálsamo por caza",
			complete = "Muy bien. Aquí están tus bálsamos de planta de Cenarion. ¡Explora Frondavil y busca plantas corruptas, $n! Estén donde estén, utiliza el bálsamo que te he dado para purificarlas.",
		},
		[4104] = {
			title = "Bálsamo por minería",
			complete = "Muy bien. Aquí tienes algunos bálsamos de planta de Cenarion. Si encuentras más vitriolo cuando extraigas minerales en Frondavil, ¡acuérdate de reservármelo! Cuanto más encuentres, más bálsamo podré preparar.",
		},
		[4105] = {
			title = "Bálsamo por recolección",
			complete = "Un trabajo excelente, $n. Cada gotita, una vez purificada, nos ayudará a recuperar Frondavil. Ten, llévate algunas dosis de bálsamo de planta de Cenarion y adéntrate en el bosque. Y date prisa: ¡debemos sanar la tierra cuanto antes, $r!",
		},
		[4106] = {
			title = "Bálsamo por desuello",
			complete = "¡Son exactamente lo que necesito! Ten, llévate estos bálsamos de planta y utilízalos para eliminar la corrupción de Frondavil. ¡Debemos perseverar, $n!",
		},
		[4107] = {
			title = "Bálsamo por desencantamiento",
			complete = "Aquí hay algunos ungüentos de plantas Cenarion: solo necesito una esencia inferior menor para esto, $n. La esencia es, con mucho, el elemento más potente que puedo utilizar para convertir espadas en arados, por así decirlo. Si necesitas más bálsamo, ¡búscame aquí!",
