		[4807] = {
			title = "E'ko de lechúcico salvaje",
			complete = "Mau'ari puede crear el Juju para $n... Utiliza el Alijo de Mau'ari para lanzarlo sobre ti o sobre tuh aliadoh.",
		},
		[4808] = {
			title = "Felnok Acerovera",
			accept = "Necesitaría otro favor de ti.$B$BMi estudio inicial de la esencia que has recolectado indica que ¡cabría la posibilidad de congelar huevos de dragón y conservarlos! Quiero probar esta teoría pero antes necesito unos componentes especialmente diseñados para este fin. Mi colega, Felnok Acerovera, puede fabricarlos.$B$BAquí tienes una carta para Felnok. En ella le cuento lo que necesito. Encontrarás a Felnok en la Cuna del Invierno, en la ciudad de Vista Eterna.",
			complete = "¡Eso no es una manta! ¿Pero qué traes ahí? ¿Una carta de Tinkee? Me pregunto qué tendrá que contarme…$B$BAh, está realizando una investigación en Las Estepas Ardientes. Tiene sentido, es un sitio ideal para los dragonantes. ¡Oh, pero mira! Dice que necesita unas piezas para un dispositivo que le gustaría construir. Supongo que por eso has venido a buscarme, ¿no?",
		},
		[4809] = {
			title = "Cuernos de Orvallo",
			accept = "Ya tengo la mayoría de lo que necesita Tinkee, aunque me falta un componente importante: cuernos de quimera. Los podrás encontrar en Cuna del Invierno. Estos cuernos son una fuente concentrada de frío, pero solo sirven los prístinos e intactos. Para completar la orden de Tinkee voy a necesitar algunos.$B$BTráemelos y prepararé el paquete.",
			complete = "Son buenos ejemplares. ¡Vienen en frío! Me pongo unos guantes y te los empaqueto con el resto de cosas que Tinkee necesita...",
		},
		[4810] = {
			title = "Regresa junto a Tinkee",
			accept = "Muy bien, ¡todo está empaquetado y listo para que lo lleves! ¡Suerte en tu viaje y no olvides de decirle a Tinkee que me debe una!",
			complete = "¡Los has traído! ¡Fantástico! ¡Enseguida me pongo a trabajar! ¡Un millón de gracias, $n!$B$BMe has ayudado tanto, podría necesitarte para otras tareas aún más importantes más adelante...",
		},
		[4811] = {
			title = "El cristal rojo",
			accept = "Hay lechúcicos lunares hostiles dirigiéndose hacia el este, cada vez en mayor número. Antes se consideraban criaturas amables, casi místicas. Y aunque hay quien sigue sintiendo veneración por ellos, la seguridad de Auberdine me fuerza a tener una visión más realista.$B$BSegún mis informes, los lechúcicos lunares están siendo conducidos hacia un gran cristal rojo que se encuentra en las montañas del sur de Costa Oscura. Nadie sabe qué es ese cristal. Ni siquiera si existe realmente. Quiero que lo busques y vengas a informarme de lo que encuentres.",
			complete = "Así que el cristal existe, $n. Fascinante... Bien, bien, ¡has hecho un buen trabajo!$B$B¿Y qué es exactamente ese cristal? Esta es solo una pregunta de las muchas que me vienen a la cabeza. Otra sería: ¿por qué los lechúcicos lunares se sienten atraídos por este objeto...? ¿El cristal es de naturaleza benigna o tiene un propósito más siniestro?$B$BY tengo más preguntas, pero será mejor examinar bien el cristal, a ver si las responde.",
		},
		[4812] = {
			title = "Agua en cascada",
			accept = "Utiliza este vial vacío para recoger algo de agua de la Poza de la Luna de Auberdine. Su potente magia debería ayudarnos a averiguar cuál es la composición del cristal. Para hacerlo, vierte el líquido sobre el cristal. Él debería hacer el resto.$B$BNo espero que encuentres ningún peligro, pero quiero que seas prudente por si acaso. Frondavil está al este de aquí. Si ese cristal está vinculado a ese lugar, como yo sospecho, podría resultar muy peligroso.",
			complete = "Has conseguido llegar una vez más al misterioso cristal. Retiras el tapón del tubo de agua de poza de la luna y viertes su contenido sobre el cristal. A medida que el agua se desliza por su entramado, ves que la superficie empieza a volverse transparente...",
		},
		[4813] = {
			title = "Los trozos del interior",
			accept = "El agua de la Poza de la Luna ha revelado que en el interior del cristal hay unos pequeños trozos de hueso y media mandíbula. El hueso maxilar parece ser de un humanoide, pero no hay forma de confirmarlo sin romper el cristal, tarea que incluso la magia más potente encontraría virtualmente imposible.$B$BUna vez completada esta tarea, solo queda ir a Auberdine a informar a la centinela Glynda Nal'Shea.",
			complete = "Vaya, parece que aunque sabemos algo más sobre el cristal, ¡solo hemos conseguido acumular más preguntas sin respuesta!$B$BLlevaré la información que has reunido al Concejo de Auberdine. Quizás ellos sepan qué tenemos que hacer con este cristal. Eso, claro está, suponiendo que tengamos que hacer algo porque, por ahora, es una amenaza muy lejana y no creo que nos alcance.$B$BPor favor, acepta esto. Considéralo una recompensa por un trabajo bien hecho, $n.",
		},
		[4821] = {
			title = "Un huevo extraño",
			accept = "Ha surgido un rumor acerca de un extraño huevo aquí en Las Mil Agujas. Aquellos que afirman haberlo visto ni siquiera han podido acercarse a él para examinarlo al detalle pues está protegido por serpientes que lo defienden como si fuera uno de sus propios huevos.$B$BQuiero que encuentres ese huevo extraño y me lo traigas para poder examinarlo. Parece ser que el huevo está situado en una guarida de serpientes, pero hay varias en la base de los riscos sur y noreste del Poblado Viento Libre.",
			complete = "Bueno, por fin he conseguido el huevo extraño. Ahora, déjame que lo vea bien... Pero... ¿qué es esto?",
		},
		[4822] = {
			title = "¡Quiero un heladooooo!",
			accept = "¡HELADO! Oh, por favor, por favor, por favor, ¡¿me puedo comer un helado?! El que más me gusta es el de fresa, ¡y el mejor helado de fresa del mundo es el helado de fresa de Tigule y Foror! ¡Es mi helado más favorito del mundo!$B$BHace mucho me comí uno, cuando estaba en la pista de carreras de El Desierto de Sal, pero he oído decir que ahora también los venden en la ciudad. ¡Por favor! ¡Muy por favor! ¡¿¡¿¿Me darás un helado de fresa de Tigule y Foror??!?!",
			complete = "Mmmmmmmmm! ¡Me encanta el helado de fresa! Si hay algo que Tigule y Foror saben hacer, ¡es hacer helado!$B$BMuchas gracias $n. ¡Este es el mejor regalo de todos!",
		},
		[4841] = {
			title = "Apaciguar al centauro",
			accept = "$n, te ruego que mates a estos centauros. ¡Que sientan la cólera de nuestra venganza! Ataca el campamento de los centauros situado al norte del Poblado Viento Libre. ¡Que la cólera guíe tu mano!|n",
			complete = "Esto es para ti, $n, como muestra de mi gratitud.",
		},
		[4842] = {
			title = "Fuentes extrañas",
			accept = "Si te soy sincera, aunque no hay volcanes en Cuna del Invierno, creo que estas fuentes termales tienen causas mucho más temibles...$B$BSupongo que querrás verlo por ti $gmismo:misma;. Tendrás que recorrer toda Cuna del Invierno, hasta el Sur. Cuando el aire se torne denso y bochornoso y cuando el cielo oscurezca, habrás encontrado lo que creo es el origen de las fuentes termales...$B$BEcha un vistazo. Estoy segura de que tendrás muchas más preguntas cuando regreses.",
			complete = "Sí, los demonios de Garganta Negro Rumor... creo que su presencia es la que está afectando así a esta tierra. Voy a seguir observando las fuentes termales para ver si averiguo algo más.$B$BSi tienes planes de seguir adentrándote en la Garganta Negro Rumor te convendría esperar a ser un poco más fuerte.",
		},
		[4861] = {
			title = "Lechúcico salvaje iracundo",
			accept = "¡Hola $Gmuchacho:muchacha;! ¡Unos sanguinarios lechúcicos salvajes me persiguieron desde mi campamento, en el sur de Cuna del Invierno! Creo que me acerqué demasiado a algo que estaban protegiendo.$B$BA duras penas conseguí escapar, pero por desgracia un compañero mío no tuvo tanta suerte. ¿Querrías enfrentarte a los lechúcicos salvajes y dirigirte al campamento? Necesito mis suministros y también debería recuperar el amuleto que desenterré ayer en la excavación.",
			complete = "Una caja muy dañada destaca entre el resto de las pertenencias destruidas en el campamento...",
		},
		[4862] = {
			title = "Bestia amaestrada",
			accept = "Lo creas o no, ¡hay gente dispuesta a pagar por la más malvada de las bestias amaestradas!$B$BHabía enviado a Bijou a la Cumbre para tratar de recolectar algunos de esos huevos de araña pero hace semanas que no sé nada de ella. ¿A lo mejor puedes ayudarme?$B$BPues, verás, $n, ve a la Cumbre de Roca Negra y recoge unos huevos de araña para mí. Tráemelos aquí y no solo te daré dinero sino que además ¡amaestraré a uno para ti!",
			complete = "¡Qué cargamento! Vamos, ¡pero fíjate en todos esos huevos! Por ellos deberíamos conseguir unas cuantas piezas de oro.$B$BComo te prometí, aquí tienes tu propio bicho. ¡Ojo, que muerde!",
		},
		[4863] = {
			title = "Lechúcico salvaje iracundo",
			accept = "Echas un vistazo, pero no ves nada que pudiera interesar a Jaron. Sin embargo, te das cuenta de que el cajón que encontraste ha sido forzado, como si fuera lo que estaban buscando los lechúcicos salvajes...$B$BMiras hacia el Este y distingues vagamente un carro abandonado. Quizás puedas encontrar allí las cosas de Jaron. Vale la pena ir a echar un vistazo.",
			complete = "Al acercarte al carro, no parece que aquí haya mucho más para Jaron. Pero, mirando al suelo, notas algunas cajas que parecen intactas, a pesar de estar medio enterradas en la nieve.",
		},
		[4864] = {
			title = "Lechúcico salvaje iracundo",
			accept = "Después de inspeccionar el contenido de la caja decides que Jaron podría aprovechar las herramientas y otros objetos de su interior. Pero no hay ni rastro del amuleto.$B$BParece que los lechúcicos salvajes habitan las tierras al norte y al este de aquí, así que decides que tu siguiente paso será enfrentarte a esas criaturas y recuperar el amuleto.",
			complete = "Bueno, esperaba escuchar lo mismo, $gmuchacho:muchacha;. Pensé que las bestias enloquecidas destruyeron todas mis pertenencias...$B$BPero encontraste mis herramientas y, lo más importante, ¡el amuleto! Me pregunto por qué los salvajes defendieron tan ferozmente este objeto... ¡En cualquier caso, lo pensaré dos veces antes de seguir su camino!",
		},
		[4865] = {
			title = "Venganza",
			accept = "Si no lo hubiera visto con mis propios ojos jamás habría creído que fuera cierto. ¡Venganza ha venido a Las Mil Agujas!$B$B<Hagar se seca la frente.>$B$B¡$n, debes actuar con rapidez! Márchate y busca a Motega Pirocabello. Lo encontrarás en el Campamento del Tramo Blanco, al noroeste del Poblado Viento Libre. ¡Él sabrá lo que hay que hacer!",
			complete = "¡Venganza! Así que la leyenda de Arikara es cierta... Está claro que hay que solucionar este problema de inmediato.",
		},
		[4866] = {
			title = "La leche de la madre",
			accept = "¡Es probablemente uno de los venenos más potentes del mundo, $r!$B$BSorprendí a los Roca Negra hablando sobre cuán letal era en una de mis incursiones en la Cumbre. Lo llaman \"la leche de la madre\" por la madre Telabrasada, la enorme y asquerosa araña de la caverna Arácnida.$B$BBien, esto es lo que necesito de ti: una muestra viva de la leche, fluyendo por TUS venas. ¡No bastará con traerme la glándula! ¡Consigue que te envenene y vuelve aquí!$B$BEntonces... ¡te ordeño!$B$B<Se frota las manos anticipando el éxito.>",
			complete = "¡Esta va a ser la mejor cerveza hasta ahora!$B$BEh, ¿para qué pensaste que iba a usar esto? Veneno o algo?$B$BNiños locos...",
		},
		[4867] = {
			title = "Urok Aullasino",
			accept = "¡Argh! ¡Cuesta tanto hablar!$B$B¡Toma esta nota! ¡Consigue mi mojo!",
			complete = "¡Eso es! Ya siento cómo vuelven mis poderes. Y mi mente ya no sufre el atroz dolor de la maldición de Urok.$B$B¡Gracias, $n! Estoy por encima de la humildad pero debo reconocer tu ayuda.$B$BY te deseo que la Fortuna te acompañe en tus viajes por la Cumbre de Roca Negra. Eres $gun necio:una necia; si crees que vas a alcanzar la cumbre pero tu valor es incuestionable.",
		},
		[4881] = {
			title = "Complot de asesinato",
			accept = "El tauren Kanati Nube Gris ha tenido la osadía de establecer un campamento de caza en Las Mil Agujas. Debemos darle muerte a él y a los que lo apoyan, y acabar así con el campamento de caza. Nos reuniremos en el pequeño campamento situado al suroeste de El Gran Elevador.|n",
			complete = "¿Vienen a matarme? ¡Yo les enseñaré cómo pelea un tauren!",
		},
		[4882] = {
			title = "Guardar un secreto",
			accept = "No estás $gseguro:segura; de la importancia que pueda tener el collar que se desprendió del cuello del lechúcico salvaje recién asesinado. Brilla intensamente, desvaneciéndose y ganando brillo lentamente.$B$BTal vez Trull Fallarruina pueda decirte algo más, su saber sobre los lechúcicos parece enorme. Deberías ir a preguntarle.",
			complete = "¿Algún descubrimiento importante?",
		},
		[4883] = {
			title = "Guardar un secreto",
			accept = "Aunque poseo muchos conocimientos sobre las lechubestias que combatiste en Cuna del Invierno, no estoy muy versado sobre sus formas de magia. No obstante, creo saber de alguien que podría examinar el collar y que seguramente sabrá decirte lo que es.$B$BNara Ferocrín de Cima del Trueno es experta en este campo, ve a verla. Buena suerte, $n.",
			complete = "La energía de este collar, $n... creo que solo tiene una fuente.$B$B<Nara cierra los ojos y se queda en silencio por un momento.> $B$BHubo un día en el que los lechúcicos salvajes, ahora confundidos y desorientados, eran completamente distintos. Tenían un objetivo, y estaban dedicados a servirlo. La diosa de los elfos de la noche, Elune, creó a esas criaturas para guardar sus zonas más sagradas.$B$BAunque pueda parecer un hecho insignificante, te insto a mirar con más detenimiento.$B$BLlegado el momento sabrás reconocer su importancia. Gracias por traerme esto $n.",
		},
		[4901] = {
			title = "Guardianes del altar",
			accept = "En la cumbre de la cresta yace lo que creo que es un altar de la diosa Elune. He deducido que necesitamos iluminar las cinco antorchas de cada cueva y solo entonces podremos acceder al altar.$B$BHe trascrito algunos encantamientos grabados en la piedra de las antiguas ruinas de Kel'Theril, creo que son el secreto para el altar. Necesitaré tu ayuda para iluminar las antorchas mientras yo recito el hechizo.$B$B¡Si tenemos éxito podrás informar a Eralas sobre nuestros hallazgos!",
			complete = "¿Te reuniste con Ranshalla?",
		},
		[4902] = {
			title = "Lechúcico salvaje de Elune",
			accept = "¡Es fascinante!$B$BSiempre me he preguntado cuál sería la verdad... Debes compartir este conocimiento, ¡sin dudarlo! Ve a ver al archidruida Fandral Corzocelada ahora mismo... lo encontrarás en Darnassus, en el Círculo Cenarion. ¡Seguro que estará muy interesado!$B$B¡Es una información muy importante, $n!",
			complete = "No lo dudes; dime por qué has venido.$B$B¿Oh si? Hmm. Bien.$B$BGracias por acudir directamente a mi; siempre es mejor ir directo a la cima... Pero... Sí. Los druidas del Círculo Cenarion conocen a los Lechúcicos desde hace algún tiempo. Saben que son mascotas de Elune y que fueron elegidas para proteger los lugares más sagrados.$B$BSi bien esto no es noticia, definitivamente te felicito por tu esfuerzo. Toma, toma esto: es algo que parece adecuado por ese esfuerzo.",
		},
		[4903] = {
			title = "La orden del Señor de la Guerra",
			accept = "Por orden del señor de la guerra Dientegore, los siguientes habitantes de la Cumbre de Roca Negra deben ser destruidos:$B$BEl orondo y amenazante alto señor Omokk.$B$BEl cruel y malvado trol, maestro de guerra Voone.$B$BY el señor supremo Vermiothalak, maestro de tareas de la ciudad inferior.$B$BSe requerirá asimismo la devolución de cualquier documento importante que se encuentre.$B$BConsíguelo y tuyos serán los honores.$B$BFracasa y caerás en el olvido.",
			complete = "<La verdosa piel del señor de la guerra Dientegore se torna blanquecina por un momento.>",
		},
		[4904] = {
			title = "Al fin libre",
			accept = "Arnak cree que me casaré con él... pero después de rechazar su proposición, él volvió aquella noche y me raptó. Mi hermano intentó impedírselo pero Arnak era demasiado fuerte. Él... asesinó a mi hermano y después me trajo hasta aquí. Mi pobre hermano...$B$B$n, ¿podrías sacarme de Cumbre de la Nube Negra? Por favor... ¡Necesito ver a Thalia! Debe de estar muy preocupada por mí.",
			complete = "Gracias, $n. En el fondo sabía que se las arreglaría para volver a mi lado. Me habló de tu valentía y me explicó cómo le ayudaste a escapar. Estos objetos pertenecían a su hermano y sé que a ella le hubiera gustado que tú los tuvieses.",
		},
		[4906] = {
			title = "Más corrupción",
			accept = "Un segundo campamento de sátiros amenaza la tierra de Frondavil desde el norte. Su líder es el cruel Xavaric. Esos viles traidores y embaucadores se alimentan de la corrupción de las criaturas de Frondavil.$B$BXavathras y sus esbirros eran solo parte de un plan más grande que pretende cultivar una Poza de la Luna corrupta para beneficio de Xavaric.$B$BAhora que Xavathras está fuera del mapa, acaba lo que empezaste, $n. Ve al norte y derrota a Xavaric.",
			complete = "Gracias por todo lo que has hecho, $n. Que Elune te proteja y te guíe en tu camino.",
		},
		[4907] = {
			title = "Tinkee Vaporio",
			accept = "Hola, $n. ¿Te acuerdas de Tinkee Vaporio? ¡Pues ella sí se acuerda de ti! Me ha enviado un mensaje para que te busque porque... necesita de nuevo tu ayuda. Creo que tiene algo que ver con su investigación sobre los dragones.$B$BDeberías ir a Las Estepas Ardientes para hablar con ella, está en el Peñasco Llamarada.",
			complete = "¡Felnok tenía razón! Necesito tu ayuda de nuevo, y esta vez... va a ser realmente peligroso.$B$B¿¿Estás $glisto:lista;??",
		},
		[4921] = {
			title = "Perdida en la batalla",
			accept = "Luchábamos juntos en un pequeño campamento tauren cuando nos separaron, ella solita le estaba plantando cara a tres Erizapúas. Pero la diferencia de efectivos empezó a desbordarnos. Estaba alejando a unos cuantos cuando la vi superada por los refuerzos. Ciego de ira, volví para enfrentarme a mis enemigos pero no tardaron en dominarme fácilmente con sus ingentes efectivos.$B$BCuando me desperté, un druida tauren estaba curando mis heridas, se había topado conmigo en el Camino del Oro donde caí.$B$BTe lo ruego, $c, encuentra alguna pista sobre mi esposa.",
			complete = "Lo entiendo. Gracias, $c.",
		},
		[4941] = {
			title = "La sabiduría de Eitrigg",
			accept = "¿Rend vive?$B$B¡Imposible!$B$BSe pensaba que Rend había sido ejecutado hace décadas.$B$BVe en busca de la sabiduría de Eitrigg, $n. Nadie conoce a los Roca Negra mejor que él y si hay algo de verdad en este escrito, debemos informar a Eitrigg. A nadie se le debería negar el derecho a vengarse.$B$BLo encontrarás en Orgrimmar.$B$BCuando hayas hablado con Eitrigg, consulta con el Jefe de Guerra para ver qué desea hacer para resolver este problema.",
			complete = "<Thrall parece consternado por la noticia que le traes.>",
		},
		[4961] = {
			title = "La purificación del orbe de Orahil",
			accept = "Ah, un orbe de conjuro, la contaminación debe de emanar de él. Debemos exorcizar al demonio de su interior si queremos usarlo. Eso es fácil para mí.$B$BA ti te toca la parte difícil. Tienes que matarlo una vez liberado.$B$BY debes hacerlo rápido. Si tardas demasiado, volverá al orbe ¡y habrá que empezar de nuevo!$B$BAsí que prepárate, $n. Ten a mano tus hechizos más poderosos y tus pociones, y algún amigo si lo tienes. Porque esto se va a poner muy feo.",
			complete = "¡Bravo, $n! Le has dado a ese demonio una lección que tardará en olvidar. Has demostrado gran fortaleza y habilidad. Supongo que es hora de que vuelvas con Menara con tu orbe limpio para poder utilizarlo en algo bueno.$B$BSuerte, $c. Quizás nuestros caminos vuelvan a cruzarse.",
		},
		[4962] = {
			title = "Fragmento de can manáfago",
			accept = "Así que has decidido capturar el alma de un can manáfago, bien.$B$BToma este rubí, con él podrás capturar el alma de la criatura. Funciona de forma muy parecida a los hechizos que ya conoces: Cuando la criatura está agonizando, usa la gema y esta hará el resto del trabajo por ti.$B$BTe recomiendo que vayas a Desolace y pruebes suerte con alguno de los canes manáfagos que por allí andan. Deberían servir.$B$BCuando lo consigas, llévale el espíritu capturado y tu rubí a Menara.",
			complete = "Ah, el espíritu de un can manáfago. Muy bien, $n.$B$BCuando tenga el espíritu y el orbe limpio, los combinaré para ti pero no hasta entonces.",
		},
		[4963] = {
			title = "Fragmento de infernal",
			accept = "Así que has decidido capturar el alma de un infernal, bien.$B$BToma esta esmeralda, con ella podrás capturar el alma de la criatura. Funciona de forma muy parecida a los hechizos que ya conoces: Cuando la criatura está agonizando, usa la gema y esta hará el resto del trabajo por ti.$B$BTe recomiendo que vayas a Desolace y pruebes suerte con alguno de los infernales que por allí andan. Deberían servir.$B$BCuando lo consigas, llévale el espíritu capturado y tu esmeralda a Menara.",
			complete = "Ah, el espíritu de un infernal. Muy bien, $n.$B$BCuando tenga el espíritu y el orbe limpio, los combinaré para ti pero no hasta entonces.",
		},
		[4964] = {
			title = "El orbe completo de Dar'Orahil",
			accept = "Empezaré inmediatamente a hacer tu orbe y lo imbuiré con tu nuevo demonio. Cuando esté listo, podrás elegir entre tenerlo en forma de bastón o de orbe. Siempre he creído que era importante satisfacer el arma elegida de un brujo... No veo por qué no iba a seguir haciéndolo.",
			complete = "Está hecho, $n. Simplemente dime cuál prefieres: un bastón que requiera que uses ambas manos, o un orbe para que puedas usar una daga o espada como arma.$B$BHacer frente a un manáfago fue una gran hazaña de tu parte. Estoy seguro de que tu artículo te servirá bien en el futuro. Continúa trabajando duro en las artes, $n. Estaré esperando detalles de tus hazañas.",
		},
		[4965] = {
			title = "El conocimiento del orbe de Orahil",
			accept = "Vaya, vaya, vaya... cómo me alegra ver que tienes cada vez más poder, $n. Apostaría a que estás a punto para hablar con Menara Nadiz en Los Baldíos. Si nunca la has tratado, te diré que no creo haber conocido nunca a ningún experto en la creación de objetos <sobre todo los orbes> que pueda atrapar a un demonio para que nos sirva con tanta facilidad.$B$BSi te interesa, se encuentra en la torre de Strahad que domina Trinquete en Los Baldíos.",
			complete = "Ah, sí que buscas algo con más... sustancia. En eso te puedo ayudar si estás $gpreparado:preparada; de verdad.$B$BEs un cambio agradable ver que $guno:una; de nuestra clase busca más poder en formas distintas al conocimiento.$B$BAsí que ¿sientes que estás $gpreparado:preparada;, $n?",
		},
		[4966] = {
			title = "Defensa de Kanati Nube Gris",
			accept = "Creo que los centauros son más numerosos de lo que yo pensaba. Te pido que luches conmigo contra estos viles asesinos, $n.",
			complete = "Gracias por tu ayuda, $n. Nunca habría podido derrotarlos sin ti.",
		},
		[4967] = {
			title = "El conocimiento del orbe de Orahil",
			accept = "Sigues siendo $gun necio:una necia; aún persigues los símbolos de los mortales. Así es, te hablo con arrogancia. Te veo ante mí y me río. ¡Eres patético!$B$BAunque lo que piense es lo de menos. ¡Solo importa lo que piensan quienes desean tratar contigo! Y en este caso, contra mi juicio más cualificado, los que deciden consideran que necesitas más.$B$BSi esto es algo por lo que luchas, entonces deberías hablar con Menara Nadiz en la torre que domina Trinquete. Creo que la conociste hace ya algún tiempo.",
			complete = "Ah, sí que buscas algo con más... sustancia. En eso te puedo ayudar si estás $gpreparado:preparada; de verdad.$B$BEs un cambio agradable ver que $guno:una; de nuestra clase busca más poder en formas distintas al conocimiento.$B$BAsí que ¿sientes que estás $gpreparado:preparada;, $n?",
		},
		[4968] = {
			title = "El conocimiento del orbe de Orahil",
			accept = "Ajá, has llegado así de lejos... verdaderamente sorprendente. Creía que la corrupción de la canalización de la magia Arcana te habría calado hasta el alma y te habría hecho perder el juicio a estas alturas. ¿Qué tal si te ponemos algo más al límite?$B$BSi deseas probar tu habilidad, ve en busca de Menara Nadiz en la torre de Strahad que domina Trinquete. Ella te guiará.",
			complete = "Ah, sí que buscas algo con más... sustancia. En eso te puedo ayudar si estás $gpreparado:preparada; de verdad.$B$BEs un cambio agradable ver que $guno:una; de nuestra clase busca más poder en formas distintas al conocimiento.$B$BAsí que ¿sientes que estás $gpreparado:preparada;, $n?",
		},
		[4969] = {
			title = "El conocimiento del orbe de Orahil",
			accept = "¡Ea! No lo estás haciendo nada mal, joven $c.$B$B¡Con un poco de tiempo, las criaturas del infierno y los señores del terror se inclinarán ante ti!$B$BPero hasta que llegue esa hora, aún debes contar con las armas forjadas por manos de razas mortales.$B$BPareces estar $gpreparado:preparada; para otra de estas creaciones y, si lo deseas, ¡Menara Nadiz hablará contigo! Está cerca de la torre de Strahad que domina la ciudad portuaria de Trinquete. Ve cuando estés $glisto:lista;.",
			complete = "Ah, sí que buscas algo con más... sustancia. En eso te puedo ayudar si estás $gpreparado:preparada; de verdad.$B$BEs un cambio agradable ver que $guno:una; de nuestra clase busca más poder en formas distintas al conocimiento.$B$BAsí que ¿sientes que estás $gpreparado:preparada;, $n?",
		},
		[4970] = {
			title = "Provisiones de sable de hielo",
			accept = "Si quieres probar tu valía puedes comenzar con una tarea muy sencilla, pero de vital importancia.$B$BRecoge carne de quimera y de los osos Dentoesquirla de la arena. Tráemela para que dé de comer a los Sables de Hielo que estoy entrenando.",
			complete = "Gracias por ayudarme, $n. Mi opinión sobre ti mejora a medida que pasa el tiempo.",
		},
		[4971] = {
			title = "Una cuestión de tiempo",
			accept = "¡Andorhal ha sufrido una alteración de la línea de tiempo a manos de una fuerza siniestra, seguramente la Plaga! Puedo intentar mantener el paso del tiempo inalterado aquí y reparar lo que ha sido dañado, pero necesitaré tu ayuda para hacerlo sin interrupciones.$B$BLos silos de Andorhal están infestados de parásitos temporales, carroñeros que se alimentan del flujo alterado del devenir del tiempo. Su única marca visual es un pulso azul de distorsión. Ralentizan mis augurios. Por favor, $n, ayúdame: utiliza este desplazador temporal para erradicar a esos parásitos.",
			complete = "Ahora parece más fácil reparar el tiempo, gracias a ti, $n. Aunque quizás nunca llegues a comprender todas las consecuencias de la ruptura de la línea de tiempo, aprecio que comprendieras la urgencia de contrarrestar lo que cada vez se acerca más a una nueva maldad infligida por la Plaga.$B$BNo veo ningún mal en recompensarte por tu ayuda, mortal. Tus mayores hazañas aún están por llegar y esta chuchería no alterará tu futuro destino. Sin embargo, tu leal ayuda, será de lo que quizás nos valgamos yo y el Vuelo...",
		},
		[4972] = {
			title = "Contar el tiempo",
			accept = "Necesito que vayas al mundo que hay más allá de esta habitación, $n. Deja que me explique.$B$BPodrás observar la diferencia entre esta habitación y el resto de Andorhal. Mi Vuelo funciona de muy distintas formas y en muchas líneas temporales diferentes. Para reparar el daño hecho en Andorhal, actúo desde una línea temporal distinta para evitar la contaminación. Eso sí, para continuar con esto necesito abalorios temporales, los que fueron atrapados cuando golpeó la Peste. Los podrás encontrar en cajas fuertes dentro de los edificios en ruinas de esta ciudad antaño gloriosa.",
			complete = "Esto es exactamente lo que necesito, $n. Gracias.$B$BPermíteme recompensarte adecuadamente. Quizás no comprendas para qué podrías necesitar un instrumento así. Puede que ni siquiera sepas qué es. Ay... no puedo decirte cuándo te será de utilidad, pero tienes que saber que llegará un momento en el que lo encontrarás extremadamente útil. Decidas o no conservarlo hasta que llegue ese momento... esto, $gamigo mío:amiga mía;, es tuyo.",
		},
		[4973] = {
			title = "Contar el tiempo",
			accept = "Si quieres ayudarme una vez más, me serás muy útil. Estaría encantada de tener todos los relojes que puedas descubrir en las ruinas de Andorhal. Me ayudan a mantener el equilibrio contra la fuerza maligna que está alterando nuestra línea del tiempo.$B$BA cambio de esos relojes te daré un objeto que sospecho encontrarás bastante útil en el futuro.",
			complete = "Te agradezco de nuevo tu ayuda. Por favor, acepta este regalo. Aunque tal vez no sepas cómo ni cuándo utilizar este objeto, puede que en el futuro la senda del tiempo te revele sus verdaderos propósitos. Podría decirse que he visto que va a ser así, $n.",
		},
		[4974] = {
			title = "¡Por la Horda!",
			accept = "Rend osa actuar así porque cuenta con la protección de Vuelo Negro.$B$BHas de encontrar el modo de cruzar las Salas de la Ascensión, $n. Debes localizar a Rend Puño Negro y acabar con él, ¡por la Horda!$B$B<Thrall da un puñetazo en el trono.>$B$BLa próxima vez que vengas, llevarás su cabeza en la mano. Después irás a enseñársela a tu Jefe de Guerra. La Horda te honrará como te mereces.",
			complete = "Has asestado un golpe mortal a los Roca Negra, $n. Ahora que han perdido a su Jefe de Guerra, están perdidos.$B$B¡La gente de Kalimdor será recompensada por tu hazaña!",
		},
		[4975] = {
			title = "El orbe completo de Noh'Orahil",
			accept = "Empezaré inmediatamente a hacer tu orbe y lo imbuiré con tu nuevo demonio. Cuando esté listo, podrás elegir entre tenerlo en forma de bastón o de orbe. Siempre he creído que era importante satisfacer el arma elegida de un brujo... No veo por qué no iba a seguir haciéndolo.",
			complete = "Ya está, $n. Solo dime qué prefieres: un bastón, que requerirá el uso de ambas manos, o un orbe, de forma que puedas usar una daga o una espada como arma.$B$BDespachar al infernal ha sido una gran proeza por tu parte, proeza digna de esta recompensa. Te deseo éxitos similares en las artes, $n.",
		},
		[4976] = {
			title = "Devolver el orbe purificado",
			accept = "Llévale el orbe limpio a Menara en Trinquete, $n. Salúdala de mi parte y que viajes sin percances. Espero de veras que puedas resistir la tentación y la corrupción que sin duda te asaltarán mientras sigues tu camino.$B$BSuerte.",
			complete = "Muy bien, $n. Esto me servirá.$B$BSolo te falta decidir qué demonio quieres que deje atrapado en el orbe limpio. Hazlo y tendrás un magnífico nuevo objeto que empuñar.",
		},
		[4981] = {
			title = "La espía Bijou",
			accept = "Nunca te fíes de un goblin. De eso se trata, $n.$B$BSe llama Bijou, una de nuestras agentes más escurridizas. Averigüé que estaba trabajando para algún sospechoso vendedor de mascotas exóticas de Las Estepas Ardientes llamado Kibler, en esencia, dos compitiendo con nosotros. Y lo que es peor, estaba usando fondos de la Horda para financiar sus operaciones.$B$BLa quiero de vuelta aquí viva.$B$BLa vieron por última vez entrando en la Cumbre de Roca Negra. Encuéntrala y tráela.$B$BY, $n, que no te engatuse con sus zalamerías.",
			complete = "No te mentiré, $r. ¡Necesitaba el dinero! Kibler paga muy pero que muy bien, mucho mejor de lo que lo haría nunca la F.E.K.$B$B¡Pero no pongas en duda mi lealtad! ¿Por qué crees que estoy aquí abajo? ¿Para conseguirle a algún goblin chalado unas patas de algún animal exótico o algo igualmente estúpido? No, solo alguien realmente tonto vendría a la Cumbre de Roca Negra para conseguir mascotas. Sí, y no creo que haya mucha gente así en este mundo.$B$B<Bijou suelta una carcajada.>$B$BLo último que necesitamos es esa clase de gente reproduciéndose.",
		},
		[4982] = {
			title = "Las pertenencias de Bijou",
			accept = "De noche la vigilancia de este lugar no es muy fuerte, merodeo por la ciudad anotando todo lo que veo y que pueda tener algún valor estratégico para la F.E.K.$B$BSin embargo, anoche todo salió fatal. Tropecé con un cable trampa y se disparó una alarma. ¡Oculté mi equipo de reconocimiento y salí corriendo! Por desgracia, no puedo volver donde dejé el equipo. ¡Han doblado y hasta triplicado las patrullas! Toda esa información se ha perdido.$B$BRecupera mis pertenencias y volveré tranquilamente a la F.E.K.",
			complete = "¡Lo has logrado! Cuando Lexlort tenga estos planos, se olvidará de todas esas cosas desagradables que quería hacerme.$B$B$n, ¡eres $gmi héroe:mi heroína;!",
		},
		[4983] = {
			title = "El informe de reconocimiento de Bijou",
			accept = "Llévale este informe a Lexlort. Limpiará mi nombre mancillado y con toda seguridad le dará una ventaja estratégica a la F.E.K. en su lucha contra estos orcos.$B$B¿Que si te acompaño? Tengo demasiado trabajo pendiente. ¡Andando, que necesitan esos informes cuanto antes!|n",
			complete = "Tengo que reconocerlo, ¡ha logrado escabullirse de otra situación peliaguda! Estos informes serán valiosos cuando tratemos con los orcos Roca Negra.$B$BPor supuesto, se te recompensará por tu duro trabajo.",
		},
		[4984] = {
			title = "La naturaleza también sufre",
			accept = "Aunque podía hacer muy poco para combatir a la Plaga, vine a estas tierras para intentar reparar el daño hecho a la naturaleza. La Peste que sigue azotando estas tierras hace sufrir a los animales, incapaces de encontrar paz ni clemencia. Te pido continuar con lo que no pude terminar.$B$BNo hay ninguna salvación para los animales ni para su sufrimiento, tan solo una liberación dulce y piadosa. Busca lobos malsanos y termina con ellos. Por favor, $n, pon fin a su desgracia... si lo haces también aliviarás la mía.",
			complete = "Sii... siento que las almas de los lobos que mataste han encontrado por fin su descanso. Ellos, y yo, te agradecemos tu piadosa liberación.$B$BLos lobos no son los únicos que sufren en este detestable lugar, $n. Por favor, te necesito una vez más.",
		},
		[4985] = {
			title = "La naturaleza también sufre",
			accept = "Las tierras al este de donde estamos, junto al comienzo de las Tierras de la Peste del Este, fueron un día el territorio de soberbios y majestuosos pardos. La Peste propagada por la Plaga también castigó a estas bestias. Vagan por el campo, agonizantes, con los músculos anquilosados y con la piel y carne en descomposición.$B$BPor favor, pon fin también a su sufrimiento. La única cura es una muerte rápida y esta debe venir de tu propia mano.",
			complete = "\"Sé que los pardos ahora están en paz, y su tormento ha terminado. Yo... tengo algo más para ti. Lo escribí en... en esta rama, porque presentía que mi tiempo en este reino estaba por terminar.$B$BAsí es... mi vida se acaba. Gracias de nuevo, $gamigo:amiga;... Las criaturas de esta tierra maldita pueden descansar... y ahora las acompañaré\".$B$BCon esas últimas palabras, el druida emite una profunda exhalación hasta perder el aliento. Su cuerpo yace inmóvil en el piso de la cabaña.",
		},
		[4986] = {
			title = "Rama de roble con inscripciones",
			accept = "La mano inerte del druida tauren aferra una rama de roble que parece lleno de vida. Cuando examinas la rama descubres unos glifos de naturaleza druídica tallados en la corteza.$B$BAgarras la rama y observas que es cálida al tacto, más de lo que debería ser. A tu mente llega la imagen del árbol de Teldrassil, en Darnassus concretamente, y tienes las palabras \"Círculo Cenarion\" en la punta de la lengua. Es como si la sugestión del lugar al que llevar la rama estuviera grabada en su interior.",
			complete = "Esto... esto es muy extraño. Este druida, un druida tauren nada menos, te ha confiado mucha y valiosa información sobre la extensión de la Peste de la Plaga. Me sorprende que un tauren diera a $gun:una; $r tal información y mucho más si todo lo que dices es cierto. Haremos un buen uso de esto, te lo prometo. Quizás el tauren no cayera tan lejos de Cenarius como Fandral podría pensar...$B$BErrr... de cualquier forma, por favor, acepta esto como muestra de gratitud del Círculo Cenarion.",
		},
		[4987] = {
			title = "Rama de roble con inscripciones",
			accept = "La mano inerte del druida tauren aferra una rama de roble que parece lleno de vida. Cuando examinas la rama descubres unos glifos de naturaleza druídica tallados en la corteza.$B$BAgarras la rama y observas que es cálida al tacto, más de lo que debería ser. A tu mente llega la imagen de Cima del Trueno en Mulgore (del Alto de los Ancestros, concretamente) y tienes las palabras \"Círculo Cenarion\" en la punta de la lengua. Es como si la sugestión del lugar al que llevar la rama estuviera grabada en su interior.",
			complete = "¿Dices que esto es para Mulgris? Oímos que intentaba ayudar a las criaturas sufrientes de las Tierras de la Peste, pero no esperábamos esto... qué tragedia. Mulgris es... era un buen amigo. Lloraré su partida amargamente.$B$BPero sus esfuerzos no han sido en vano, gracias a tu diligencia. En esta rama hay mucha información sobre la peste que propaga la Plaga por el país. La estudiaremos con detalle. En cuanto a ti, por favor, acepta esto. Es lo menos que puedo hacer por tus nobles esfuerzos.",
		},
		[5001] = {
			title = "Las pertenencias de Bijou",
			accept = "No suelo tratar con $gningún:ninguna; $r, pero parece que estoy atrapado entre un trol y un lugar hostil. Verás, mi misión aquí es de la más alta importancia para la Horda. La información que he descubierto, sin embargo, también se aplica al bienestar de la Alianza. Créeme, no simpatizo en absoluto con la Alianza, pero la amenaza de los Roca Negra es mucho mayor que la de un puñado de orcos.$B$BTú me ayudas a recuperar mis pertenencias y yo te facilitaré información que será útil para los de tu especie.$B$B¿Hay trato?",
			complete = "¡Vaya, que me aspen! ¿¿Dónde estaban??",
		},
		[5002] = {
			title = "Un mensaje para Maxwell",
			accept = "Soy un goblin de palabra, $r. Escucha atentamente:$B$B¡Usan a estos orcos principalmente como animales de carga y como carne de cañón para los Vuelo Negro!$B$BSu verdadero jefe no es otro que Nefarian, de la prole de Alamuerte. También he descubierto la ubicación de los subalternos de Nefarian en esta parte de la ciudadela.$B$BLlévale este mapa al mariscal Maxwell en Las Estepas Ardientes. Las posiciones de estos enemigos están marcadas para facilitar la identificación.",
			complete = "Esto encaja con casi todo lo que ya sabíamos. Pero bueno, es interesante y una información más bien triste.$B$BLas marcas de este mapa serán valiosas para atajar la amenaza de los Roca Negra.",
		},
		[5021] = {
			title = "Más vale tarde que nunca",
			accept = "Hay que entregar el paquete... ¡entregarlo antes de quedar aquí atrapada!\"$B$BLos gritos de pánico de una mujer se sienten casi como un susurro a través de toda la casa. Escaleras arriba, acurrucada en la esquina, ves la aparición de una mujer. No parece ser plenamente consciente de lo que la rodea, y solo parece advertirte vagamente.$B$B\"¿Has venido a entregar mi paquete? Por favor, ¡antes de que sea mucho peor! Estaba a punto de salir de aquí. Todavía estará con mi caballo... ¿o ya es demasiado tarde?",
			complete = "En el establo adviertes un paquete que de otra forma hubieras pasado por alto, pero que ahora destaca entre las ruinas y los escombros. Quizás es el paquete que pedía a gritos el fantasma de Janice Piedra Mácula...",
		},
		[5022] = {
			title = "Más vale tarde que nunca",
			accept = "Coges el paquete y limpias la delgada capa de polvo y mugre que lo cubría. Está dirigido a una tal Emma Piedra Mácula de la Ciudad de Ventormenta y parece que fue escrito apresuradamente. El envío está datado hace más de cuatro años.$B$BAunque no está claro si Emma Piedra Mácula sigue siquiera con vida, todo el mundo sabe que el Ayuntamiento de Ventormenta guarda un registro de la población de la ciudad. Se encargan de él los agentes reales del Censo de Ventormenta.",
			complete = "¿Un paquete para una Emma Piedra Mácula, dices? La última dirección conocida fue Ventormenta, ¿hace cuatro años? Bueno, déjame ver aquí...$B$BSegún lo que sabemos, hubo una Emma Piedra Mácula en la ciudad hace unos cuatro años. Bueno, debería decir posiblemente; este censo al que me refiero es de hace cinco años, y no tengo un informe de que ella haya abandonado la ciudad. Sin embargo, esto no significa que ella todavía esté aquí.$B$BEspera un segundo... este paquete no puede ser para la vieja Emma, ¿verdad?",
		},
		[5023] = {
			title = "Más vale tarde que nunca",
			accept = "Coges el paquete y limpias la delgada capa de polvo y mugre que lo cubría. Está dirigido a un tal Jeremiah Piedra Mácula de Lordaeron y parece que fue escrito apresuradamente. El envío está datado hace más de cuatro años.$B$BAunque no está claro si Jeremiah Piedra Mácula sigue siquiera con vida, todo el mundo sabe que Entrañas, antes conocido como Lordaeron, guarda un registro de la población de la ciudad. Se encargan de él los supervisores reales del Censo de Entrañas.",
			complete = "Un paquete para un tal Jeremiah Piedra Mácula cuya última dirección conocida es Lordaeron... debería poder ayudarte.$B$BJeremiah Piedra Mácula estaba en la ciudad antes de la peste. Bueno, más bien debería decir el antiguo Jeremiah Piedra Mácula. Algunos de los Renegados han cambiados sus apellidos para librarse de su antigua vida. Este caso no es ninguna excepción, el antiguo Jeremiah Piedra Mácula es ahora conocido como Jeremiah Payson.$B$BEspera un momento... ¿no es el vendedor de cucarachas?",
		},
		[5041] = {
			title = "Suministros para El Cruce",
			accept = "Sea lo que sea que haya ocurrido en Los Baldíos del Sur está provocando que algunas de las tribus de jabaespines huyan en nuestra dirección. En concreto, los Crines de Acero desplazados empiezan a desesperarse, y sus ataques se envalentonan cada vez más. ¡Solo esta semana he perdido ya dos caravanas!$B$BNuestros guerreros de El Cruce necesitan esos suministros desesperadamente, y no pienso permitir que los jabaespines se ceben en sus fechorías. Encuentra los cajones de suministros perdidos y tráemelos. Yo buscaría en la casucha de los jabaespines al sur de aquí, siguiendo el río.",
			complete = "¡Ea! ¡Gracias, $n! Esto será de gran ayuda. Eres un orgullo para El Cruce y la Horda. Si puedo hacer cualquier cosa por ti, solo tienes que pedirlo.",
		},
		[5042] = {
			title = "La fuerza de Agamaggan",
			complete = "¡Ojalá Quebrantadientes estuviera libre para ver cómo diezmas a los que lo traicionaron! <Gruñe>$B$BTe agradezco que destruyeras a más Erizapúas al reunir estos fragmentos. Te lo ruego, sigue haciéndolo, y yo volveré a ayudarte. <Gruñe>",
		},
		[5043] = {
			title = "La agilidad de Agamaggan",
			complete = "Que no falle tu disparo y la marca de tu arma sea verdadera, $r.$B$BEl espíritu de Agamaggan está contigo. Vuelve aquí si quieres. Quebrantadientes volverá a bendecirte si el gran dios jabalí te considera $gdigno:digna;.",
		},
		[5044] = {
			title = "La sabiduría de Agamaggan",
			complete = "Tus enemigos deberían temerte aún más, $r. $B$BCuéntale a Quebrantadientes los relatos de tu astucia en la batalla la próxima vez que nos veamos, ya sea en esta vida o en la otra.",
		},
		[5045] = {
			title = "Fortaleza de espíritu",
			complete = "Nuestros más gloriosos guerreros y <gruñe> chamanes envidiarían tu determinación, $r.$B$B¡Derrota a más Erizapúas sabiendo que no pueden detenerte!",
		},
		[5046] = {
			title = "Ocultafilo",
			complete = "Ve a la guerra, $r.",
		},
		[5047] = {
			title = "¡Finkle Einhorn, a tu servicio!",
			accept = "Encontrarás a Malyfous Martilloscuro en Vista Eterna, $c. Dile que \"Finkle está muy contento\" y que el traje funciona de perlas.$B$BEntonces entrégale esto:$B$B<Finkle te tiende un trozo de carne resplandeciente.>$B$BEs un pedazo de las entrañas de la bestia en la que pasé mis \"vacaciones\".$B$B¡Apuesto a que Malyfous te dará una idea bastante precisa de lo que puede hacer con una parte de un monstruo como este!$B$BAh, supongo que no sabes dónde está Vista Eterna, ¿verdad? ¡Pon rumbo a la Cuna del Invierno, $gamigo:amiga;!",
			complete = "¿Vivo? ¿El traje bien? ¿Y qué tenemos aquí?",
		},
		[5048] = {
			title = "El buen carácter de Emma",
			accept = "Tiene muy mal genio y, posiblemente, está algo chiflada... pero los registros indican que la vieja Emma se ajusta al perfil de quien podría ser Emma Piedra Mácula.$B$BQuizás hayas visto a la vieja Emma dando vueltas por la ciudad... Habla sola, la mayor parte del tiempo en una jerigonza incomprensible. Pero no hace daño a nadie, así que la suelen dejar tranquila.$B$BConsiderando todos los hechos, yo diría que la vieja Emma es Emma Piedra Mácula. Podrías intentar preguntarle si su apellido es Piedra Mácula.",
			complete = "De hecho, mi nombre es Emma Piedra Mácula, eres la primera persona en años que me llama así. ¿Quién... quién eres tú?$B$B¡¿Dices que sabías... mi hermana ?! ¿Sigue viva? A quién engaño, por supuesto que no. Cuando estalló la plaga en Lordaeron, esperaba lo peor. Muchos miembros de mi familia murieron... o algo peor. Aquí estoy ahora, loca Emma, completamente sola. ¿Qué eres, $gun ladrón:una ladrona; de tumbas o algo así? ¿Estás buscando tu próximo objetivo?$B$B¿Qué... tienes un paquete para mí de mi hermana?",
		},
		[5049] = {
			title = "La depre de Jeremiah",
			accept = "En vista de los hechos puedo decir que la persona que buscas, y la destinataria del paquete, es Jeremiah Payson, el vendedor de cucarachas de Entrañas.$B$BSiempre he pensado que hay que tener un don especial para vender... cucarachas. No hay duda de que estás ante una aventura épica, $gpoderoso:poderosa; $c. A ti corresponderá la empresa de cambiar el mundo. Sin embargo, permíteme que participe de tu obra magna y te diga que se encuentra cerca del banco, postrado cómodamente bajo una de las pasarelas.",
			complete = "Hace años que no uso ese nombre... pero sí, así me llamaba en mi anterior vida.$B$B¿Y dices que conoces a mi hermana? Bueno, que has hablado con ella hace poco...$B$B¿¡La misma hermana que lleva muerta cuatro años!?$B$BMira, si no tuviera los huesos tan frágiles, te patearía el trasero ahora mismo.$B$B¿Eh... cómo... me traes un paquete de su parte...?",
		},
		[5050] = {
			title = "Talismán de buena suerte",
			accept = "Parece que me equivoqué contigo, $n, y te debo mis disculpas. Mi hermana me envió algunos efectos personales, entre ellos, tiene gracia, las escrituras del Campo de Piedramácula. Creo que por ahora no voy a reclamarla.$B$BSi el espíritu de mi hermana sigue atado a la granja y no encuentra descanso, por favor... ¿puedes devolverle esto? Es la mitad de un talismán que ella tenía, su marido tenía la otra mitad.$B$BQuizás si sabe que tengo estas cosas dejará que su alma descanse.",
			complete = "Devuelves la mitad del talismán a la aparecida. Lo mira y luego te mira a ti con expectación.$B$B\"Cariño, ¿dónde dejaste la otra mitad? No podemos estar juntos si no tenemos las dos mitades. Cariño... ¿puedes verme?\"",
		},
		[5051] = {
			title = "Dos mitades hacen una",
			accept = "El pobre espíritu sigue mascullando palabras sin sentido:$B$B\"Tengo mucho frío, John. ¡Dame tu talismán y estaremos juntos! Rápido John, antes de que la Peste venga para convertirnos en horribles bestias! No puedo verte John... pero sé que estás cerca. Te siento junto a mí.\"$B$BTal vez si encontraras la segunda mitad del talismán y reunieras las dos partes, dieras con lo que busca el espíritu de Janice Piedra Mácula.",
			complete = "Entregas el talismán de buena suerte vuelto a reunir al fantasma de Janice Piedra Mácula. En cuanto lo tiene en sus manos observas un cambio casi inmediato. Su forma etérea emite brillos trémulos y te mira con unos ojos claros pero tristes.$B$B\"Me has liberado... ya no necesito este talismán. Por favor, cógelo, quizás te dé el consuelo que me ha dado a mí.\"",
		},
		[5052] = {
			title = "Esquirlas de sangre de Agamaggan",
			accept = "Además de las espinas, la sangre afectó a <gruñe> otros aspectos de la tierra: piedras teñidas de rojo sangre mezcladas con otros minerales. Los Erizapúas excavan en busca de estas esquirlas y las llevan como tótems <gruñe> para que les den fuerza en la batalla y para su magia <gruñe.>$B$BConozco los secretos de esa magia.$B$BLlévale a Quebrantadientes una de estas esquirlas de sangre para demostrarle que entiendes de qué va el asunto. Llévale a Quebrantadientes muchas esquirlas y te bendecirá con la magia de los jabaespines, es decir, ¡la magia de Agamaggan! <gruñe.>",
			complete = "Ah, entiendes. <Gruñe> Mis palabras no cayeron en oídos sordos, $r. Puede que Quebrantadientes esté enjaulado ¡pero no hay jaula que detenga el poder de Agamaggan!$B$BEl contacto con el fragmento, solo tocarlo... ha pasado tanto tiempo, $r.$B$B¿Tienes idea de lo que se siente? ¿Que te aparten de tu poder?$B$BPero ya contaremos esa historia en otra ocasión. Te prometí información. Te prometí el poder de Agamaggan. Mi propio pueblo me dio la espalda, a mí, a Quebrantadientes. Ahora, te envío para que mi furia caiga sobre ellos.",
		},
		[5054] = {
			title = "Ursius de los Dentoesquirla",
			accept = "En las nevadas montañas de Cuna del Invierno, al Noroeste, un diestro cazador acecha a su presa... me refiero a Ursius de los osos Dentoesquirla, una bestia ágil e inteligente.$B$BTe envío a enfrentarte con él. Vaga por las escarpadas colinas al noroeste de Vista Eterna. Da con él y cázalo antes de que advierta tus intenciones.$B$BTodo el que ha tenido un encuentro con Ursius se ha visto convertido en presa y a él en cazador. Mantente en guardia.",
			complete = "No era una tarea fácil, pero has sido sobresaliente. Pero no vayas tan deprisa, no creas que me has impresionado, $n.",
		},
		[5055] = {
			title = "Brumerán de los Orvallo",
			accept = "Rápida e inteligente, Brumerán planea silenciosamente por el nevado paisaje del sur de Cuna del Invierno. Pero no dejes que su grácil figura te haga pensar que es inofensiva. Todo el que se encuentra con ella lo paga muy caro, a menudo con su propia vida.$B$BBusca a Brumerán de los Orvallo entre las quimeras. Acaba con ella y vuelve a verme.",
			complete = "Sí. Has regresado. Ahora creo que eres un auténtico $c por naturaleza. Te has enfrentado a las criaturas más fieras y has regresado, superando todas mis expectativas.$B$BYa estás preparado para mi última petición.",
		},
		[5056] = {
			title = "Shi-Rotam",
			accept = "En la parte norte de Cuna del Invierno, los grandes felinos se reúnen en torno a un lugar conocido como Roca Sable de Hielo. La líder de los felinos responde al nombre de Shi-Rotam. Si derrotaras a la matriarca de los sables de hielo ganarías mucho respeto a ojos de cualquier $r.$B$BVuelve a esas inhóspitas tierras y, cuando estés allí, recoge carne de sable de hielo sacra. Encuentra la Piedra de Shi-Rotam y colócala allí. Cuando pongas la carne de sus prójimos en la piedra, invocarás a Shi-Rotam, estará furiosa.$B$BDebes estar $gpreparado:preparada; para su ira y derrotarla.",
			complete = "Has demostrado tu fuerza y determinación. Te esperan muchos más desafíos, pero ya has probado ser tan capaz como yo mismo puedo serlo.",
		},
		[5057] = {
			title = "Esfuerzos del pasado",
			accept = "Antes de que hablaras conmigo, $n, ya había oído hablar de tus esfuerzos... que tenías un deseo irrefrenable de ponerte a prueba, que tenías un enorme talento como $c y ahora sé que todo era cierto.$B$BQuien sobresale tanto como tú merece reconocimiento. Lleva esta Señal a un amigo mío de Cima del Trueno llamado Melor Pezuña Pétrea. Seguro que se acordará de ti y de lo que hiciste hace ya tanto tiempo. Habla con él de tus logros más recientes, sin olvidar lo que has hecho hoy.",
			complete = "Aprendemos de nuestras experiencias vitales, $n. Estoy seguro de que las tuyas solo conseguirán hacerte más fuerte y $gsabio:sabia;. Has crecido mucho desde la primera vez que hablamos.$B$BToma esto como recuerdo de todas las difíciles tareas que has superado como $r $c, y no olvides que siempre tendrás mi respeto y admiración.",
		},
		[5058] = {
			title = "El diario de la señora Dalson",
			complete = "Un diario de páginas amarillentas se abre en la última anotación:$B$B\"No sé qué va a pasar ahora que Harold cambió. Se llevó todo mientras lo arrastraba al único lugar que podía encontrar donde mantenerlo seguro. Escondí la llave conmigo, y rezo por que nadie la encuentre...$B$BEspero poder escapar de aquí, pero necesito dinero para eso. Creo que todas nuestras cosas están en el armario... y ahora que lo pienso, Harold tenía la llave.$B$BVoy a descansar un poco, ahora estoy muerta de cansancio.\"",
		},
		[5059] = {
			title = "Encierro",
			complete = "Con la llave que encontraste en el esqueleto de la que fue la señora Dalson abres la puerta de la letrina. Un necrófago sanguinario salta fuera de la letrina, debe de haber estado ahí atrapado desde hace mucho tiempo.$B$BEl desgarrador grito del necrófago al advertir tu presencia deja claro que el antiguo granjero Dalson ya no puede ser salvado.",
		},
		[5060] = {
			title = "Encierro",
			complete = "La llave que has cogido de los restos del necrófago que fue el granjero Dalson encaja a la perfección en el candado. Las puertas del armario se abren y muestran varios objetos que siguen intactos y que parecen bastante valiosos.",
		},
		[5061] = {
			title = "Forma acuática",
			accept = "Has completado tu formación para la adopción de una forma acuática. Ve a ver a tu instructor, Mathrengyl Garroso, a Darnassus. Enséñale el colgante y demuéstrale que puedes aprender lo que tenga que enseñarte. Él completará tu formación para que puedas fundirte con el agua.$B$BBuena suerte, joven druida. Volveremos a vernos.",
			complete = "Muy impresionante, $n. Estás $glisto:lista; para aprender tu forma acuática, y es un placer para mí enseñártela.$B$BAdemás, en reconocimiento a tu logro durante las dos pruebas, te entrego este artículo. Espero que lo encuentres util en tu equipamiento como $gprotector:protectora; de la naturaleza y $gguardián:guardiana; del equilibrio.",
		},
		[5062] = {
			title = "El fuego Sagrado",
			accept = "Arikara es una criatura mortífera contra la que hay que actuar con rapidez. Para poder atraparla tendrás que encender el fuego sagrado de la vida, que hará que Arikara aparezca.$B$BVe y recoge pitas incendiarias, una planta poco común. Cuando tengas suficientes pitas, pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno. Ella es una poderosa chamán que puede encantar la planta y obtener así unos polvos con los que encender el fuego.$B$BViaja en dirección noreste hasta Poza Hirviendo y recoge pitas incendiarias.",
			complete = "Bien, has recogido la cantidad necesaria de pitas incendiarias. Esta rara hierba que solo se encuentra en Las Mil Agujas servirá para encender el fuego sagrado de la vida.$B$B<Magatha comienza a encantar las pitas incendiarias.>",
		},
		[5063] = {
			title = "Almete del Sabio Escarlata",
			accept = "No encontrarás un almete más delicado. ¡Con el pellejo de la Bestia prístino, nuestros expertos artesanos crearán el tocado más fantástico con el que podría soñar un prestidigitador!$B$BTráenos cincuenta piezas de oro y los objetos de la lista y tu cabeza será agraciada con el Almete del Sabio Escarlata.$B$B*El pellejo de la Bestia prístino.$B$B*Costuras desgarradas de abominación.$B$B*Cristales Arcanos.$B$B*Hilo escarlata encantado.$B$B¡CONTÉMPLALO!",
			complete = "¡Asombroso! Ha debido tomarte semanas reunir esos componentes... ¿y cómo encontraste un pellejo de Bestia prístino?!?$B$B¡Disfruta la gorra, $n!",
		},
		[5064] = {
			title = "Espiando a los Tótem Siniestro",
			accept = "$n, nos has servido con diligencia en el pasado por lo que ahora te confío una importante misión. El clan Tótem Siniestro está tramando algo. Sabemos que tres agentes de origen desconocido se han estado reuniendo con los Tótem Siniestro durante las últimas semanas. Descubrimos que hay varios cofres en Cumbre de la Nube Negra que contienen mensajes reveladores.$B$B$n, si tienes éxito en esta peligrosa misión, te recompensaré debidamente.|n",
			complete = "¡Gran tótem espiritual! ¡Qué malas noticias! Debo empezar a prepararme para lo que sea que se avecina.$B$B$n, como te prometí, aquí tienes la recompensa por tu valerosa ayuda.",
		},
		[5065] = {
			title = "Las tablillas perdidas Mosh'aru",
			accept = "El trol con el que has hablado no te ha dicho la verdad. Es cierto que las dos tablillas que conseguiste para él explican el modo de retener la esencia de Hakkar, pero la leyenda no acaba ahí. Llevo mucho tiempo investigando y he descubierto que existen seis tablillas Mosh'aru y no dos. ¡Seis!$B$BY mucho me temo que los secretos que albergan no serán de nuestro agrado...$B$BLocaliza la tercera y cuarta tablillas Mosh'aru. Se encuentran en las Tierras de la Peste del Este en posesión de los trols Fustamusgo. Encuéntralas y tráemelas aquí.",
			complete = "¡Los encontraste! ¡Excelente!$B$BGracias, $n. Repasaré estos textos y descifraré su significado.$B$BTú, sin embargo, tienes otra tarea...",
		},
		[5066] = {
			title = "Un llamamiento a las armas: las Tierras de la Peste",
			accept = "¡Atención, atención! ¡Atención todos los héroes!$B$B¡El Reino de Ventormenta ha hecho una llamada a las armas! ¡Tomad las armas para hacer frente a la amenaza de la Plaga en las tierras al norte de los Reinos del Este! ¡Se dice que de las ruinas de las Tierras de la Peste surgen nuevas amenazas!$B$B¡Héroes del reino, presentaos ante el comandante Ashlam Puñovalor en el Campamento del Orvallo, al norte de las Montañas de Alterac!",
			complete = "$gBienvenido:Bienvenida; a las Tierras de la Peste, $ghéroe:heroína;. Esta es una de las fronteras más peligrosas de Azeroth, especialmente con la amenaza inminente de la Plaga en nuestro norte y noreste. ¡Me alegra saber que el clarín del deber y el servicio al bien mayor no cayó en oídos sordos contigo!$B$BSi estás $glisto:lista; para ensuciarte las manos, entonces hay mucho que hacer aquí para $glos héroes dispuestos:las heroínas dispuestas; y capaces en el borde de las Tierras de la Peste.",
		},
		[5067] = {
			title = "Leotardos de Arcana",
			accept = "Nunca se ha logrado elaborar un objeto como este, pero se cree que es posible, con las circunstancias adecuadas.$B$BSi el buscador de lo arcano deseara imbuir los leotardos con un poder inmenso, debería buscar lo siguiente:$B$B*El pellejo de la Bestia prístino.$B$B*Costuras desgarradas de abominación.$B$B*Barras de arcanita.$B$B*Líquido de embalsamar de Murmuhielo.$B$B¡CONTÉMPLALO!",
			complete = "Pocas tareas más improbables que esta he visto completadas por mortales. ¡Disfruta de la gloria de mi obra! ¡Obtén tu recompensa!",
		},
		[5068] = {
			title = "Coraza Sed de Sangre",
			accept = "Se dice que solo se ha creado una coraza Sed de Sangre y que se hizo para Garona, la legendaria asesina. Dudo que vuelva a verse uno igual en este mundo.$B$B¡Pero no importa! Nuestros maestros artesanos pueden reproducir el objeto si tienen los componentes necesarios:$B$B*El pellejo de la Bestia prístino.$B$B*Costuras desgarradas de abominación.$B$B*Barras de arcanita.$B$B*Piel de Sombra.$B$B¡CONTÉMPLALO!",
			complete = "Pensé que estaría muerto y enterrado antes de ver este día.$B$BUn logro de esta magnitud solo puede ser eclipsado por su recompensa.",
		},
		[5081] = {
			title = "La misión de Maxwell",
			accept = "Esta información completa lo que se les había escapado a nuestros sin embargo siempre avezados espías de la Cumbre de Roca Negra.$B$BEl ataque ha de ser contundente, $n.$B$BHay que empezar por destruir a su maestro de guerra, el trol Voone. Sin sus planes de guerra, los orcos Roca Negra se encontrarán inmersos en el caos.$B$BDespués debes liquidar al ogro alto señor Omokk. Esos ogros cobardes de los Roca Negra están indefensos sin su liderazgo.$B$BPor último, el señor supremo de la ciudadela: Vermiothalak. Una vez muerto Vermiothalak, su unidad de mando central está perdida.",
			complete = "Excelente trabajo, $n. Como mínimo, nos has dado más tiempo, un tiempo precioso, precioso.",
		},
		[5082] = {
			title = "La amenaza de los Nevada",
			accept = "Vine a Cuna del Invierno para investigar los Baños Escarchados. He observado que el agua parece tener... cualidades extrañas. Todavía no he podido descubrir la fuente y, para serte sincera, últimamente he tenido algunos problemas a causa de los fúrbolgs Nevada.$B$BParecen sentirse atraídos por las fuentes, igual que yo. Se han vuelto extremadamente protectores con el agua, no permiten que me acerque a los dos manantiales más grandes, al norte de aquí.$B$BMe gustaría seguir con mis estudios, ¿me ayudarás?",
			complete = "¡!Muchas gracias, $n! Ya puedo seguir trabajando aquí$B$B¿Encontraste algo interesante en el campamento Nevada?",
		},
		[5083] = {
			title = "Aguardiente Nevada",
			accept = "El vial que recogiste de los fúrbolgs Nevada está vacío, pero detectas unas gotas de un extraño líquido verdoso en su interior. Casi brilla.$B$B¿Puede ser importante?$B$BSeguramente Donova Cubilnevado podrá decirte algo más ya que lleva un tiempo acampada junto a las fuentes termales de Cuna del Invierno.",
			complete = "¿Lo obtuviste de los Nevada?",
		},
		[5084] = {
			title = "Sucumbir a la corrupción",
			accept = "Este líquido verdoso... me recuerda algo al barro que vi durante mis viajes por Frondavil. He visto algunos corredores Nevada entre los Fauces de Madera... Quizás esto tenga algo que ver con la botella que has encontrado, $n.$B$BHay un grupo grande de fúrbolgs nada más pasar el Bastión Fauces de Madera, en Frondavil. La energía vil ha corrompido y llevado a la locura a esa tribu, los Muertobosque. ¿Por qué no vas a echar un vistazo y a ver si puedes encontrar alguna evidencia de acuerdos entre los Nevada y los Muertobosque?",
			complete = "En la caldera burbujea una sustancia putrefacta y de olor repulsivo...",
		},
		[5085] = {
			title = "Baba misteriosa",
			accept = "La sustancia verdosa de la caldera es parecida a la que encontraste en la botella. Esta extraña sustancia viscosa puede estar tan corrupta como el fúrbolg que la preparó...$B$BSi los fúrbolgs Nevada la están utilizando, ¿significa eso que pronto estarán tan corruptos como la tribu Muertobosque?$B$BLo mejor sería volver a informar a Donova de estos descubrimientos y llevarle una muestra del líquido de la caldera.",
			complete = "Tienes muchos recursos, $n. ¿Crees que los furbolgs Nevada han estado en el campamento Muertobosque?",
		},
		[5086] = {
			title = "Horrores tóxicos",
			accept = "He estudiado la muestra que has traído contigo y aunque no estoy segura a ciencia cierta, creo que contiene restos de elementos tóxicos. Necesito hacer un estudio comparativo, y solo sé de una forma de hacerlo.$B$BCreo que los fúrbolgs Muertobosque están recogiendo estos elementos de otras criaturas corruptas de Frondavil, especialmente de los elementales que viven en el Bosque de Troncoferro, los llamados horrores tóxicos.$B$BReúne algunas muestras para que pueda compararlas, pero ten cuidado... ¡es un lugar muy peligroso!",
			complete = "Tengo que compararlo con la sustancia que encontraste en la caldera, entonces sabremos algo más.",
		},
		[5087] = {
			title = "Corredores Nevada",
			accept = "Muy interesante, $n...$B$BSi se mezcla esta sustancia tóxica con el agua de las fuentes termales, pierde su toxicidad, y solo conserva la capacidad para alterar temporalmente al que la ingiere. Debe ser la razón por la que los Nevada protegen con tanto fervor las fuentes termales... las necesitan para purificar su aguardiente.$B$BTenemos que detenerlo... interrumpir el contacto entre los Nevada y los Muertobosque. Un grupo de corredores recorre el camino que separa su poblado y Frondavil. Encuéntralos, acaba con ellos y róbales su cargamento.",
			complete = "<Donova examina el contenido del cajón.>$B$BMe pregunto si el consumo de esta sustancia hace a los furbolgs más agresivos. Parecen mucho más grandes...",
		},
		[5088] = {
			title = "Arikara",
			accept = "Lleva este refinado y depurado polvo de incendiaria a Las Mil Agujas y échalo sobre el fuego sagrado de la vida. Está situado en Cumbre de la Nube Negra en una aguja aislada en la que entierran a sus muertos.$B$BEl encantamiento que he lanzado sobre el polvo de incendiaria atraerá a Arikara, $n.$B$BTemo que esté persiguiendo a Cairne Pezuña de Sangre; han cambiado mucho las tradiciones de los tauren y eso ha enojado a Arikara. ¡Actúa con rapidez antes de que todo esté perdido, $c!",
			complete = "Esto no tiene sentido. ¿Por qué iba Arikara a andar tras Cairne Pezuña de Sangre? Magatha no puede estar equivocada, es una de nuestras chamanes más poderosas.$B$B<Motega niega con la cabeza.>$B$BSea como sea, tu hazaña en favor de la Horda no pasará inadvertida. Por favor, elige uno de estos como recompensa por tu ayuda.",
		},
