		[5928] = {
			title = "Escucha la llamada",
			accept = "Oye, perdona...$B$BHe sabido que Turak Tótem de Runa quiere hablar contigo. Por lo visto, tu instrucción de druida va a dar un giro, porque te va a entrenar él personalmente. Turak es uno de los ayudantes del archidruida; es sabio y paciente, te enseñará bien.$B$BEstá en Cima del Trueno, dentro de la carpa principal del Círculo Cenarion en el Alto de los Ancestros.",
			complete = "Me alegro de que encontraras el camino hasta aquí, joven $c. Ha llegado el momento de que des un gran paso y te adentres en un mundo más grande.$B$BTodos los hijos de Cenarius servimos a la naturaleza. Los animales y las plantas son nuestros amigos y también nuestros protegidos. Elegimos dedicar nuestra vida a preservar el equilibrio, por su bien, tanto como por el nuestro. Tu primer paso en este mundo será aprender el camino del oso y aprender de la fuerza del cuerpo y del espíritu.$B$B¡Prepárate!",
		},
		[5929] = {
			title = "Espíritu del gran oso",
			accept = "Al noroeste de Claro de la Luna está el hogar del un ser noble y sabio llamado el espíritu del gran oso. Gracias a él todos los druidas han podido captar la esencia natural del oso. Todo druida debe buscar la sabiduría del espíritu. Tú no vas a ser una excepción.$B$BPreséntate ante el espíritu del gran oso y aprende lo que tenga que enseñarte. Cuando hayas terminado, vuelve a verme aquí, a Amparo de la Noche. Entonces sabremos si realmente has aprendido la lección.",
			complete = "Mientras te acercas, Dendrite hace otro gesto. Aparece otra aura de poder sobre él y te sonríe.$B$B\"Hay en ti sabiduría nueva. Tu mirada refleja fuerza y decisión, pero debes aprender a dominarlas. Aprenderás a concentrarte y a adoptar las estrategias del oso.\"",
		},
		[5930] = {
			title = "Espíritu del gran oso",
			accept = "Al noroeste de Claro de la Luna está el hogar del un ser noble y sabio llamado el espíritu del gran oso. Gracias a él todos los druidas han podido captar la esencia natural del oso. Todo druida debe buscar la sabiduría del espíritu. Tú no vas a ser una excepción.$B$BPreséntate ante el espíritu del gran oso y aprende lo que tenga que enseñarte. Cuando hayas terminado, vuelve a verme aquí, a Amparo de la Noche. Entonces sabremos si realmente has aprendido la lección.",
			complete = "Mientras te acercas, Dendrita hace otro gesto. Aparece otra aura de poder sobre él y te sonríe.$B$B\"Hay en ti sabiduría nueva. Tu mirada refleja fuerza y decisión, pero debes aprender a dominarlas. Aprenderás a concentrarte y a adoptar las estrategias del oso.\"",
		},
		[5931] = {
			title = "El regreso a Darnassus",
			accept = "Ha llegado el momento de separarnos, puesto que para poner en práctica lo que has aprendido debes volver a quien te envió a mí. Mathrengyl Garroso vive en armonía con la naturaleza, aunque vive peligrosamente cerca de donde el equilibrio natural se ha roto. Escúchalo bien y pronto habrá terminado tu preparación como $gprotector:protectora; del equilibrio.$B$BVete, joven. Volveremos a vernos.",
			complete = "Saludos, $n. Veo que tu primer encuentro con el Espíritu del gran oso fue, como para todos los druidas, inquietante pero intenso; también lo fue para mí.$B$BEl Espíritu del gran oso ha residido en Azeroth desde el principio de los tiempos; confiamos en su sabiduría y su fuerza para ayudarnos en nuestro propósito. Escucha con atención...",
		},
		[5932] = {
			title = "Vuelve a Cima del Trueno",
			accept = "Ha llegado el momento de separarnos, puesto que para poner en práctica lo que has aprendido debes volver a quien te envió a mí. Aunque se dice que los tauren son inexpertos en la sabiduría de Cenarius, Turak Tótem de Runa vive en armonía con la naturaleza. Escúchalo bien y pronto habrá terminado tu preparación como $gprotector:protectora; del equilibrio.$B$BVete, joven. Volveremos a vernos.",
			complete = "Saludos, $n. Veo que tu primer encuentro con el Espíritu del gran oso fue, como para todos los druidas, inquietante pero intenso; también lo fue para mí.$B$BEl Espíritu del gran oso ha residido en Azeroth desde el principio de los tiempos. Los tauren escuchamos atentamente a esos espíritus, y todos prosperamos de su propósito. Ahora, ha llegado el momento de que pases la primera prueba de ese propósito. Escucha con atención…",
		},
		[5941] = {
			title = "Regresa junto a Cromi",
			accept = "Has reunido muchas reliquias de la Batalla de Villa Darrow. Cada vez que volvías con más, mi corazón añoraba más mi aldea... y ansiaba protegerla de su desgracia.$B$BSé que no puede ser, pero Cromi, esa extraña gnomo de Andorhal, me dice que es posible. ¡Dice que tú puedes salvar Villa Darrow!$B$BElla me pidió que reuniera las reliquias y que hiciera que tú se las llevaras. Dijo que te esperaría en la posada en ruinas de Andorhal.",
			complete = "Ah, sí, aquí están. Juntas conforman un poderoso hechizo, uno que alzará a los espíritus de Villa Darrow.$B$BCon ese hechizo y un poco de suerte, podremos salvar a Joseph Rutagrana.",
		},
		[5942] = {
			title = "Tesoros ocultos",
			accept = "Papá me dijo que te diera esta llave. Dijo que abre un cofre que hay detrás de la casa.$B$BTambién quería que te diera las gracias. ¿Le hiciste un favor? ¿Le dijiste que encontraste a mi muñeca?$B$BBueno, ten la llave. Y gracias, $n. ¡Gracias! ¡Eres $gun hombre muy bueno:una señora muy buena;!",
			complete = "La llave entra en la cerradura y el cofre se abre...",
		},
		[5943] = {
			title = "La caravana Gizelton",
			accept = "Pareces muy competente, $r. ¿Quieres ganar algo de dinero? Cork y yo empezamos con esta caravana para ganar dinero... ¡cómo íbamos a imaginar los peligros que tendríamos que afrontar!$B$BMás adelante está el Aquelarre Mannoroc. Normalmente los demonios nos ignoran pero... algo tiene a los kodos muy agitados últimamente. Te pagaré para que protejas la caravana mientras atravesamos el Aquelarre Mannoroc. Una vez estemos a salvo al otro lado, podrás pedir tu recompensa a nuestro socio Smeed. Está en el Campamento de los Mezclatornillos.",
			complete = "No sé yo si es una propuesta propicia pagar tanto dinero para proteger la caravana Gizelton. Cork y Rigger solo se sacan una moneda de oro a la semana, pero mientras me paguen los kodos, tampoco es que me importe un carajo cómo lleven su negocio.",
		},
		[5944] = {
			title = "En sueños",
			accept = "Durante mucho tiempo he sido una marioneta del Gran Cruzado. ¿Qué razón había para luchar contra aquello en lo que se convirtió la Cruzada Escarlata? Ya han pasado décadas y aun así son los recuerdos de mi padre, esos preciados recuerdos, los que me mantienen con vida.$B$BTengo sueños, $gforastero:forastera;. En esos sueños mi padre está a mi lado. Está conmigo, orgulloso, y soy iniciado en la Orden. Combatimos las legiones de la Plaga, el uno junto al otro. Damos honor a la Alianza, a Lordaeron.$B$BNo quiero seguir soñando.$B$BLlévame con él.",
			complete = "La muerte de mi hijo a manos de esos monstruos no caerá en el olvido. Consuélate pensando en que la Orden ha renacido.$B$BAhora ocuparé mi puesto como Alto Señor de la nueva Orden de la Mano de Plata.$B$BEstas posesiones de mi pasado son todo lo que puedo ofrecerte por todo lo que has hecho por mí. Por favor, acéptalas como símbolo de mi gratitud, me fueron de gran ayuda durante años.$B$BTal vez nos volvamos a encontrar en tiempos mejores y recordaremos los días pasados... las duras batallas... los sueños redimidos.",
		},
		[5961] = {
			title = "Campeón de la Reina alma en pena",
			accept = "Me complace comprobar que $gel experto:la experta; en batallas se une a nuestra causa. Cada día que pasa, somos más numerosos y fuertes. ¿Te sientes $gpreparado:preparada; para poner a prueba tu temple, $c?$B$BEntre mis mejores hombres estaba Nathanos, ahora conocido como el Clamañublo. Pocos hay en nuestras filas con semejante dedicación y vigor.$B$BBúscalo en las Tierras de la Peste del Este. Reside en la Hacienda de Marris y, de cuando en cuando, vaga por las diezmadas inmensidades matando a todo miembro de la Plaga o la Alianza que se cruza en su camino.",
			complete = "Sin duda la Dama Oscura no te cree $gmerecedor:merecedora; de enfrentarte a su Campeón. ¿Has venido para convertirte en la merienda de mis canes? No puede haber otro motivo para esta interrupción.",
		},
		[5981] = {
			title = "Gigantes arrasadores",
			accept = "Hace unos 4000 años, Tyrande Susurravientos salvó la vida de la reina de los Sables de Hielo, de manos de unos gigantes enloquecidos. Desde entonces los Sables de Hielo han estado aliados a los elfos de la noche.$B$BLos mismos gigantes que en su día amenazaron a los Sables de Hielo siguen presentes no lejos de aquí. Son los llamados Machacahielo y se han apoderado del valle del Sur.$B$BDemuestra tu lealtad a los Sables de Hielo. ¡Mata a esos gigantes en nombre de Shi-Rotam, la reina de los Sables de Hielo!",
			complete = "Excelente, $n. Tu determinación ha sido debidamente anotada.",
		},
		[6001] = {
			title = "Cuerpo y corazón",
			accept = "Al este de Auberdine hay muchas cuevas de lechúcicos lunares. La que está más cerca de Auberdine alberga una piedra de lechúcico lunar en su interior. Garraluna, el guardián de la piedra, solo se enfrentará a ti cuando le apliques polvo de luna Cenarion. Garraluna posee una fuerza que debes usar como miembro de la zarpa.$B$BTe has ganado el derecho a usar este polvo de luna Cenarion, $n... ¡Ahora demuéstrame que también te has ganado el derecho a poseer la fuerza física y de corazón que necesitas como druida!",
			complete = "Por fin has dado ese gran paso, $n, te has adentrado en un mundo mucho más grande. Percibo en ti las enseñanzas del espíritu del gran oso y percibo que has recibido la fuerza que poseía Garraluna.$B$BYa no hay obstáculos en tu camino... ¡Deja que te enseñe lo que significa ser un $c de la Zarpa!",
		},
		[6002] = {
			title = "Cuerpo y corazón",
			accept = "Al oeste de Taurajo en Los Baldíos, justo antes de Mulgore, yace una piedra de lechúcico lunar. Los lechúcicos lunares son criaturas muy especiales no nativas de estas tierras. Garraluna, el guardián de la piedra, se enfrentará a ti cuando le apliques a la piedra polvo de luna Cenarion. Garraluna posee una fuerza que debes usar como miembro de la zarpa.$B$BTe has ganado el derecho a usar este polvo de luna Cenarion, $n... ¡Ahora demuéstrame que también te has ganado el derecho a poseer la fuerza física y de corazón que necesitas como druida!",
			complete = "Por fin has dado ese gran paso, $n, te has adentrado en un mundo mucho más grande. Percibo en ti las enseñanzas del espíritu del gran oso y percibo que has recibido la fuerza que poseía Garraluna.$B$BYa no hay obstáculos en tu camino... ¡Deja que te enseñe lo que significa ser un $c de la Zarpa!",
		},
		[6004] = {
			title = "Negocios inconclusos",
			accept = "Fui enviada como exploradora para dañar y calibrar la fuerza de las defensas de la Vega del Amparo. Algunos miembros de la Alianza tenían la sensación de que la pequeña ciudad tenía algo más que importancia histórica. Mi trabajo no consiste en preguntarme cuál pueda ser esa importancia pero no estoy en condiciones de seguir adelante hasta que descanse.$B$BSi lo deseas, pagaría generosamente tu ayuda. Comienza al sur de aquí, en un campamento cercano al pequeño baluarte que han levantado. Si demuestras ser lo suficientemente fuerte, tal vez pueda unir tu ayuda con mi objetivo principal.",
			complete = "Bien hecho, $n. Estoy asombrada de que acabaras con ellos tan rápidamente. Gracias.$B$BTodavía tengo que encontrar a alguien que esté de acuerdo con la Cruzada Escarlata y con sus métodos. Creo en la Luz tanto como cualquier otro en Ventormenta, pero han demostrado que solo quieren matar a todo el que no sea leal a su movimiento... incluidos los inocentes.",
		},
		[6021] = {
			title = "Zaeldarr el Marginado",
			accept = "¿No te parece increíble? Con todos los problemas que tenemos en las Tierras de la Peste... ¡ahora resulta que nos toca ocuparnos también de los ladrones! Y no de ladrones normales, no, ¡ladrones trols!$B$BY tampoco son ladrones trols convencionales... ¡¡Son ladrones trols muertos!!$B$BSu líder es un enorme trol muerto llamado Zaeldarr el Marginado. Vienen de noche, roban los cuerpos del foso de abajo y se los llevan a su maldita madriguera de trols muertos: La Subgranja del oeste.$B$BVe allí y elimina a Zaeldarr, $n. ¡Me he hartado de sus fechorías!",
			complete = "Genial, lo tienes! ¡Y espero que también le hayas dado una lección a su pandilla!",
		},
		[6022] = {
			title = "Matar con un propósito",
			accept = "Mientras trabajes para mí, matarás con un propósito concreto.$B$BTu primera misión es alimentar a mis canes.$B$BCoge este mortero y este majadero y viaja al Cruce de Corin. Allí encontrarás una nutrida selección de miembros de la Plaga que matar. Necesito putrefacción viva de sus cadáveres frescos. Coge esa putrefacción y colócala en el mortero. Deja que repose y se coagule. Y luego, tráeme esa putrefacción coagulada.$B$BY recuerda que esa putrefacción viva de los no-muertos, no dura \"viva\" mucho tiempo. ¡Debes matar con rapidez!",
			complete = "Decepcionante. Esperaba tener que usarte a ti para alimentar a mis canes.$B$B<Nathanos suspira.>$B$BBueno, al menos tienen algo que comer.",
		},
		[6023] = {
			title = "Negocios inconclusos",
			accept = "Mi verdadera misión era debilitar las fuerzas periféricas de la Cruzada Escarlata e infiltrarme en la Vega del Amparo para calibrar su número. Todavía no estoy en condiciones de hacerlo yo misma, así que ¿puedo pedir tu ayuda de nuevo, $n? A partir de la información que reuní antes de ser descubierta, deduje que la Cruzada tiene dos miembros importantes, la columna vertebral de sus fuerzas fuera de la ciudad: el montero Radley y el hidalgo Durgen. Mátalos y daremos un gran paso adelante. Deberías encontrarlos en el Paso de la Vega del Amparo, fuera de la torre propiamente dicha.",
			complete = "Gracias, $n. Has sido de mucha más ayuda de lo que había esperado. El aire de este lugar parece ahogar mi voluntad. Estoy cansada y puedo asegurarte que no me recuperaré mientras siga aquí.$B$BNo estoy segura de cómo lograré infiltrarme en la Vega del Amparo para informar sobre la fuerza de la Cruzada Escarlata en el lugar.$B$BPero eso es otra cuestión, antes de partir coge esto... en pago por tu ayuda. Gracias de nuevo.",
		},
		[6024] = {
			title = "La súplica de Hameya",
			accept = "Mátame. Antes de que sea demasiado tarde.$B$BMe llamo Hameya. Cuando viajábamos hacia Zul'Mashar, mis hermanos y yo comimos carne en mal estado y... cambiamos. Estamos infestados.$B$BAhora puedo oír las palabras del Rey Exánime, instándome a llegar a Zul'Mashar a infectar a mi gente. Sé que no podré resistir mucho... por eso escribí el pergamino... antes de que mi voluntad me abandonara.$B$BEnterré un cofre cerca de un carro que hay detrás de esta cripta, pero solo se abrirá con mi llave. Y yo tengo la llave. Si quieres mi tesoro, tendrás que encontrarme a mí.$B$BMátame... antes de que sea demasiado tarde.",
			complete = "¡¡El cofre de Hameya está abierto!!",
		},
		[6025] = {
			title = "Negocios inconclusos",
			accept = "¿Qué? ¿De verdad? ¿Quieres saber más? Pero ya has hecho mucho por mí, $n, no podría pedirte entrar en la Vega del Amparo en mi nombre.$B$B¿Estás $gseguro:segura;, $n? La Vega del Amparo es mucho más peligrosa que el Paso... no puedo darte ningún tipo de protección, ni siquiera información sobre lo que puedas encontrarte allí.$B$BBien, si de verdad quieres ayudar, entra en la ciudad y busca un lugar elevado para hacerte con una buena perspectiva de la ciudad. Desde allí podrás calcular su número, cuando lo hayas hecho vuelve a informarme. Pero ten cuidado...",
			complete = "¡Lo has conseguido, $n! ¡Gracias!$B$BVolveré con Elling... quiero decir, a Ventormenta, tan pronto como pueda. Toma, coge esta moneda, es lo menos que puedo hacer por ti. Haces honor a tu pueblo, $n. Gracias y buena suerte.",
		},
		[6026] = {
			title = "Eso pide mucho",
			accept = "Unos tipos de El Alba Argenta encargaron al viejo Smokey un pequeño trabajo de demolición. Y la mamá de Smokey no crió a un tonto. Si hay monedas de oro sobre la mesa, los servicios de Smokey están disponibles. ¡Ese es mi lema!$B$BEstaría dispuesto a compartir la comisión contigo si te apetece hacer un poco de trabajo de campo. Este es el trato: yo iré al Bosque de la Peste y marcaré los edificios que tenemos que destruir. Tú reúnes los componentes para las bombas. Y te reúnes aquí conmigo cuando tengas todo. ¿Trato hecho?",
			complete = "Puedo pagarte la mitad por adelantado y la mitad cuando el trabajo esté hecho.",
		},
		[6027] = {
			title = "El Libro de los Ancestros",
			accept = "$n, te confío la gema de la Serpiente. Coloca esta gema en la mano de la estatua de la Serpiente que está en una pequeña isla al noroeste de aquí, la Isla Ranazjar. Cuando la coloques, invocarás a quien protege el Libro de los Ancestros. Ese libro contiene los secretos de los nagas. Secretos que se han guardado durante siglos. Tráeme ese libro. ¡Aprenderemos mucho sobre nuestros escamosos enemigos!",
			complete = "¡El Libro de los Ancestros! ¡El que tanto tiempo llevaba extraviado! Me aseguraré de que este libro llegue al Alto Consejo. Hoy has hecho algo magnífico. Deberíamos agradecértelo, y te lo agradecemos ¡como a $gun:una; $ghéroe:heroína;!",
		},
		[6028] = {
			title = "El informe Vista Eterna",
			accept = "Estoy buscando a un individuo responsable que me ayude en una pequeña pero importante cuestión. Estoy aquí como representante de los intereses de El Alba Argenta en el gobierno local de Vista Eterna. Necesito hacer llegar un informe a la oficial Argenta Purocorazón, en el Campamento del Orvallo; está algo alejado de aquí, en el límite meridional de las Tierras de la Peste del Oeste.$B$BSi se me permite decirlo creo que sería una forma perfecta de presentarte a mi superiora, ¡e incluso puede que tenga algún trabajo para ti!",
			complete = "Gregor es muy ingenioso. Ha estado lidiando con el Cártel Bonvapor desde hace algún tiempo y se ha convertido en un experto en el \"arte\" de las negociaciones con goblins. Aunque es cierto que la principal lealtad de los goblins reside en quienes tienen los monederos más grandes, también conocen y respetan el valor de la diplomacia. En todo caso, les proporciona clientes habituales...$B$BEn cualquier caso, el Alba Argenta te agradece tu esfuerzo. Por favor, toma esto junto con nuestro agradecimiento.",
		},
		[6029] = {
			title = "El informe Vista Eterna",
			accept = "Estoy buscando a un individuo responsable que me ayude en una pequeña pero importante cuestión. Estoy aquí como representante de los intereses de El Alba Argenta en el gobierno local de Vista Eterna. Necesito hacer llegar un informe al oficial Argenta Garush en el Baluarte; está algo alejado de aquí, en el límite occidental de las Tierras de la Peste del Oeste, al este de los Claros de Tirisfal.$B$BSi se me permite decirlo creo que sería una forma perfecta de presentarte a mi superior, ¡e incluso puede que tenga algún trabajo para ti!",
			complete = "Gregor está lleno de recursos para ser humano. Desde hace algún tiempo ha estado ocupándose del Cártel Bonvapor y se ha convertido en un auténtico experto en el \"arte\" de las negociaciones goblin. Si bien es cierto que la primera lealtad de los goblins es hacia los que tienen más liquidez, también conocen y respetan el valor de la diplomacia. Sobre todo les sirve para tener clientes fijos...$B$BEn cualquier caso, El Alba Argenta agradece todo tu esfuerzo. Por favor, toma esto y nuestra gratitud.",
		},
		[6030] = {
			title = "El duque Nicolas Zverenhoff",
			accept = "Un solitario médium que habita esta región y que responde al nombre de Umbranse ha dado a El Alba Argenta una obra maestra de la literatura... posiblemente sea la mayor colección de verborrea que he visto escrita nunca.$B$BUno de los líderes más respetados de El Alba, el duque Nicolas Zverenhoff, es un destacado lingüista. ¿Podrías llevarle esto de mi parte? Por supuesto, a cambio de una recompensa. Podrás encontrarlo en la Capilla de la Esperanza de la Luz, en la parte oriental de las Tierras de la Peste del Este.",
			complete = "\"Me... me has traído un libro muy especial. Me gustaría decirte que, en este caso, \"especial\" significa \"único y muy posiblemente iluminador\", pero todavía hay que verlo.$B$B\"¿Ooooo?\" ¿A quién en su sano juicio se le ocurría esto?$B$BBien, he oído hablar de ese Umbranse del que te habló Gregor, será una ventaja. Haré todo lo que pueda por descifrarlo. En cuanto a ti... por favor, toma esto, cortesía del Alba Argenta. Mientras estés por aquí quizás puedas ayudarnos con alguna otra cosa.",
		},
		[6031] = {
			title = "Paño rúnico",
			accept = "Estamos muy bien en el Bastión Fauces de Madera y no nos gustan los extraños. Esto es bueno para nosotros pero no para el comercio.$B$BNo hace mucho, una singular elfa de la noche vino al Bastión Fauces de Madera vistiendo una capa de paño rúnico. El paño rúnico no es algo muy común entre nosotros pero la capa le gustó tanto a mi gente que me pidieron que les hiciera más ropajes con paño rúnico.$B$B¿Me traerías paño rúnico? Si me traes bastante cantidad, te daré algo a cambio.",
			complete = "Ah, trajiste el paño. ¡Qué material tan fino!$B$BGracias, $n. Eres $gun verdadero amigo:una verdadera amiga;. Acepta esto a cambio.",
		},
		[6032] = {
			title = "Tela sagrada",
			accept = "A pesar de que a las gentes del Bastión Fauces de Madera les encanta el paño rúnico, este no es sagrado para nosotros. Sin embargo, la tela lunar sí lo es.$B$BConsígueme un poco de esta tela sagrada y te enseñaré una técnica de diseño secreta.",
			complete = "Ah, muy bien. Esta tela lunar se utilizará en prendas sagradas para nuestro pueblo. Gracias, <no,mbre>. Ahora te entrenaré.",
		},
		[6041] = {
			title = "Cuando Smokey canta, me pongo violento",
			accept = "Mientras tú reunías los suministros, yo hice que mi gente marcara los edificios de la Plaga que debemos demoler.$B$BEste es el plan: voy a darte diez palos de mi compuesto especial. Tú los llevas al Bosque de la Peste y los plantas dentro de los edificios de la Plaga que he hecho marcar.$B$B<Smokey chasquea los dedos.>$B$B¡Y ya está! Es facilísimo.",
			complete = "Eres mucho más $goscuro:oscura; de lo que recuerdo. Tienes ese look para ti; la mirada que dice: \"Me ha quemado una bomba de alto explosivo\".$B$B<Smokey se ríe.>$B$B¡De todos modos! Aquí está tu parte del botín. Le agregué algo extra para ayudar a aliviar las quemaduras.",
		},
		[6042] = {
			title = "Los pequeños problemas de la no-vida",
			accept = "No se puede uno alejar dos pasos de la granja sin encontrarse con uno de esos repugnantes murciélagos. Quiero poder sacar a los canes y acabar con la Plaga sin que me molesten esos malditos y sucios murciélagos. Obviamente, tengo cosas mejores que hacer con mi tiempo que matar murciélagos un día sí y otro también. Pero tú no.$B$B¿Qué? ¿Tu entrenamiento? ¡Esto es tu entrenamiento! Ahora fuera de mi vista y no vuelvas hasta que no hayas matado a un buen número de esos demonios alados. Procura no decepcionarme.",
			complete = "Es increíble lo que se puede conseguir con un poquito de ira y mala leche.",
		},
		[6061] = {
			title = "Domesticar la bestia",
			accept = "Para los tauren es importante seguir la tradición ancestral de luchar contra criaturas poderosas. Al someterlas absorbemos su espíritu, lo que nos acerca a la Madre Tierra.$B$BDel mismo modo, domar a una bestia para que luche de nuestro lado es una forma de unirse a la naturaleza. Aprenderás a domar criaturas. Pero estas cosas requieren tiempo y práctica. Para empezar, usa esta fusta de doma para domar un zancudo de llanura adulto.",
			complete = "Me han aparecido señales de la Madre Tierra; lo has hecho bien.",
		},
		[6062] = {
			title = "Domesticar la bestia",
			accept = "Someter a la naturaleza a tu autoridad es una habilidad admirable. Como $gcazador:cazadora;, debes esforzarte en aprender a utilizar la fuerza y el poder inherentes a cualquier criatura.$B$BHacerse con el control de un animal no es una tarea sencilla; debes acometerla con gran determinación.$B$BComo primera tarea, coge esta fusta de doma y utilízala para domar a un jabalí jaspeado temible. Podrás encontrar los que quieras cerca de Cerrotajo. Practica tus habilidades de combate con el jabalí a tu lado y luego vuelve a verme.",
			complete = "Has hecho un buen trabajo, $n. Creo que estás $glisto:lista; para tu siguiente tarea.",
		},
		[6063] = {
			title = "Domesticar la bestia",
			accept = "Al ser $gcazador:cazadora; es muy importante que recuerdes la responsabilidad que tienes en tus manos. La naturaleza no es un poder que puedas modificar a tu antojo. Todo al contrario, es un poder que debe respetarse y entenderse como algo mucho más fuerte que tu propia existencia.$B$B$n, debes demostrar que comprendes lo que acabo de decirte para poder adquirir la habilidad de domar a un animal para convertirlo en tu mascota.$B$BEn primer lugar, coge esta fusta de doma con la que podrás domar a un rondador Tejemadera. Dómalo y practica tus habilidades como $gcazador:cazadora;.",
			complete = "¡Excelente, $n! Aprendes rápido.",
		},
		[6064] = {
			title = "Domesticar la bestia",
			accept = "¡Buenas, $Gchaval:chavala;! Supongo que quieres saber cómo conseguir una mascota.$B$BMuy bien, vamos a ello. Para cazar, lo más importante es el equipo, pero ya hablaremos de mi lanzatralla otro día. De momento, hablaremos de lo que te interesa: ¡las mascotas!$B$BLo mejor es que pruebes con varias criaturas, hasta que decidas cuál te gusta más. Busca un jabalí del risco grande y dómalo con la fusta de doma.",
			complete = "Lo sé, lo sé; te estás preguntando qué sigue, ¿no?",
		},
		[6065] = {
			title = "El camino del cazador",
			accept = "Saludos, joven cazador. Tienes cara de ser capaz de domar a una bestia.$B$BVe a ver a Yaw Crinafilada, que está en el Poblado Pezuña de Sangre. Te dirá cómo puedes conseguir una mascota.",
			complete = "Sí, creo que estás $glisto:lista;.",
		},
