		[7506] = {
			title = "El Sueño Esmeralda",
			accept = "El libro lleva la marca de El Athenaeum.",
			complete = "Excelente trabajo, $r. Si encuentra más tomos, no dudes en devolvérnoslos.$B$BA medida que pasa el tiempo, tendemos a cambiar e incluso agregar nuevas recompensas por la devolución de los tomos perdidos.",
		},
		[7507] = {
			title = "Compendio de Foror",
			accept = "Has descubierto algo de gran importancia. Este libro no se parece a nada que hayas visto antes.$B$BParece que alguien o algo ha logrado romper el sello de El Athenaeum. El texto es confuso, apenas se puede leer.",
			complete = "Podrías haber obtenido bastante oro por este libro en el mercado negro, $n. Sobre todo porque el sello protector se ha roto, dejando los secretos de la matanza de dragones visibles para cualquiera que tenga el intelecto necesario para consumir el conocimiento contenido en las páginas sagradas.$B$BQuizás una gran recompensa sea lo correcto... Bueno, una recompensa que requerirá un enorme esfuerzo para obtenerla.$B$B<Lydros sonríe.>",
		},
		[7508] = {
			title = "Forjar Quel'Serrar",
			accept = "Si quieres encargarte de esta tarea, entrega la espada roma a Lydros.",
			complete = "Si logras entrar en la guarida del dragón, calientas la hoja bajo su ardiente aliento y finalmente la templas en su sangre, ligaré la hoja para tu uso.",
		},
		[7509] = {
			title = "Forjar Quel'Serrar",
			accept = "Lleva la hoja antigua sin templar a la guarida de Onyxia y rétala a un duelo.$B$BEs una artimaña que te servirá para templar la espada. Mientras estéis combatiendo, ella intentará incinerarte con su aliento de fuego. Cuando lo haga, planta la espada sin templar cerca de ella y deja que ella la temple con sus llamas. Si sigues $gvivo:viva;, recoge la espada, que ahora estará templada y mata a Onyxia.$B$BHunde la espada templada en su ardiente cadáver para dar forma a la antigua hoja.",
			complete = "<Lydros murmura algo ininteligible.>$B$BComo prometí, $n, la espada de Quel'Serrar.",
		},
		[7541] = {
			title = "Un servicio para la Horda",
			complete = "Nuestros estudiosos tardarán un tiempo en analizar el colgante que nos trajiste. Pero quiero ofrecerte una pequeña recompensa por el trabajo que has hecho para la Horda.$B$BGracias, $n. Tus actos te honran a ti, y también a nosotros.",
		},
		[7562] = {
			title = "Mor'zul Sangredoble",
			accept = "$n, has profundizado mucho en la práctica de las artes oscuras. Tu dominio sobre habitantes de otros mundos se ha consolidado... quizás estés $glisto:lista; para asignarte uno de los infames corceles de la Muerte.$B$BEl ritual para invocar a la bestia desde su hogar requiere gran poder y recursos pero si deseas dominar al épico corcel, habla con Mor'zul Sangredoble. Tiene su campamento en el Altar de la Tempestad, en Las Estepas Ardientes$B$BVete, $n. Esta misión será peligrosa ¡pero un brujo de tu talla no debe retroceder ante el peligro!",
			complete = "Saludos, $n, y $gbienvenido:bienvenida;. ¿Estás aquí para estudiar cerca del Altar de las Tormentas como yo, quizás para aprovechar su energía para algún propósito oculto?$B$BO... ¿estás aquí para hablar conmigo? Sí, creo que es eso.$B$B¿Quieres dominar un corcel temible? No es una tarea fácil. Te costará grandes cantidades de sangre, sudor... y, por supuesto, oro. Pero un corcel temible de Xoroth es un premio que vale la pena ganar, así que si estás $ginteresado:interesada;, escucha...",
		},
		[7563] = {
			title = "La ira de sangre",
			accept = "Los corceles de la Muerte viven en otro mundo, en las abrasadoras Llanuras de Xoroth y para amarrar a una de esas afamadas bestias, debes convocar a poderosos glifos. Puedo escribir los glifos para ti en un papiro pero antes necesitaré una tinta especial.$B$BEn la remota Cuna del Invierno habita una raza de bestias búho. Otrora criaturas puras, enloquecieron debido a unas emanaciones diabólicas de la Garganta Negro Rumor y ahora deambulan histéricos por las nieves.$B$BNecesito su sangre para la tinta de tu papiro. Tráemela.",
			complete = "Ah, muy bien. Haré que destilen esta sangre en tinta y la utilicen para el pergamino que te prometí. Y quizás me guarde un poco para mí, ya que escuché que su sabor es bastante eufórico...",
		},
		[7564] = {
			title = "Ojovago",
			accept = "Mi sirviente, Gorzeeki, es un alquimista bastante bueno. Puede preparar la tinta que necesitaré para tu pergamino. He reunido la tinta que me trajiste, llévasela a Gorzeeki para que pueda empezar su trabajo.",
			complete = "Oh, es sangre. Entonces debe ser del maestro Mor'zul. Está tan enamorado de las cosas y le encanta verlas derramadas. Yo, sin embargo, prefiero que corra por las venas de un pequeño roedor. Se mantiene caliente de esa manera... hasta que lo desee.$B$BEsta es sangre poderosa. ¡Mor'zul debe estar haciendo otro pergamino para convocar a un corcel aterrador! ¡Que interesante!$B$BSi eso es cierto, y vas a realizar el ritual, entonces... vas a necesitar mucho más que sangre, $gamigo:amiga;.",
		},
		[7581] = {
			title = "Las selladuras de la prisión",
			accept = "Debes arrebatarles a los demonios inferiores lo necesario para sellar la prisión para Guardias apocalípticos.$B$BLa sangre del sátiro Mala Hierba que habita en La Masacre servirá. La sangre coagulada pegará los fragmentos de Hederine, formando una prisión de cristal.",
			complete = "Ah, una excelente adquisición. La sangre suprimirá las defensas mágicas de los Guardias apocalípticos.",
		},
		[7582] = {
			title = "El revestimiento de la prisión",
			accept = "Los demonios Hederine que ocupan las estribaciones del Monte Hyjal segregan un poderoso veneno vil que, si se deja madurar, se convierte en un resistente cristal antimagia. Estos cristales se conocen como las Lágrimas de los Hederine.$B$BNi la inmensa fuerza de un Guardia apocalíptico sería suficiente para destruir las paredes de una prisión construida con este material.$B$BViaja a la Garganta Negro Rumor en Cuna del Invierno y recoge lágrimas.",
			complete = "Solo necesito combinar la sangre de los Sátiro Mala Hierba con estos cristales y la prisión estará lista para su uso.",
		},
		[7583] = {
			title = "Supresión",
			accept = "La prisión ya está lista. Ahora pasemos a la parte más difícil de esta tarea.$B$BDebes localizar y capturar a un comandante Guardia apocalíptico en la Escara Impía utilizando esta prisión de cristal.$B$B¡Ten cuidado! Un Guardia apocalíptico es un adversario astuto y letal que intentará acabar contigo cuando comiences el ritual de encarcelamiento. Se agitará con desenfreno en su intento de escapar de la prisión.$B$BTú serás su centro de atención, $n. Por ello, te recomiendo que te acompañe alguien que te ayude a defenderte.",
			complete = "Has hecho lo que te pedí. Estás $glisto:lista; para recibir el conocimiento para conjurar y controlar a la bestia.",
		},
		[7601] = {
			title = "La orden de Niby",
			accept = "Si he de enseñarte los secretos de la invocación de un siervo infernal, tú debes destruir a Kroshius y, de sus restos ardientes, tráeme su núcleo infernal. Y no es tan fácil como suena. Kroshius está lejos de estar extinguido. Debes volver a prender fuego a su cadáver y hacer que se alce de los escombros. Pero para hacerlo, debes reunir algunos componentes de otras entidades demoníacas.$B$BMi diablillo, Diblis, te dará las indicaciones pertinentes.",
			complete = "Oh $gchico:chica;, aquí vamos de nuevo.",
		},
		[7602] = {
			title = "Esencia de energía vil pura",
			accept = "Si quieres reanimar a Kroshius, vas a necesitar fuego vil. Yo puedo hacer fuego vil, pero para eso necesito algunos componentes.$B$BTienes que traerme esencia vil impecable de tres regiones diferentes del mundo.$B$BLos sátiros Legashi de Azshara tienen el primer tipo de esencia. Los Legionarios Jaedenar, de Jaedenar, tienen el segundo y los guardias viles de Las Tierras Devastadas, el tercero.$B$BTráeme una esencia de cada tipo y yo crearé el fuego vil que te permitirá reanimar a Kroshius.",
			complete = "Dame un minuto y combinaré las esencias en fuego vil.",
		},
		[7603] = {
			title = "El núcleo infernal de Kroshius",
			accept = "Kroshius se encuentra en un montoncito, hacia el noreste, en la Cañada Gran Cicatriz. Lleva este fuego vil y utilízalo en sus restos. El fuego debería reanimar a ese infernal caído.$B$BUna vez reanimado, espero, por supuesto, que te mate. A ti y a tu esbirro.$B$BSi por un milagro consigues matar a Kroshius, extráele su núcleo infernal y llévaselo a Niby.",
			complete = "¡Un trato es un trato! Rápido, toma esto y anótalo. ¡No tengo tiempo! ¡Mi mayor conjuro está sobre nosotros!",
		},
		[7604] = {
			title = "Un contrato vinculante",
			accept = "Los abajo firmantes declaran que el lingote de Sulfuron del que hacen entrega a la empresa Hermandad del Torio (HT S.A.) es auténtico y no una falsificación. Los abajo firmantes asimismo declaran que cualquier daño que pudiere resultar del intento de construir, forjar, encontrar, crear, vender, o ingerir a Sulfuras, no podrá ser imputado a HT S.A.$B$BPor la firma del presente contrato, acepta las cláusulas en él estipuladas.$B$B_________________$B$BFirma",
			complete = "¡Ha sido un placer hacer negocios contigo, $n!$B$B¡En nombre de HT, S.A., te deseo suerte en tu búsqueda de Sulfuras!",
		},
		[7621] = {
			title = "Un aviso",
			complete = "$n, estás a punto de pasar por una rigurosa serie de eventos que pondrán a prueba todas tus habilidades.$B$BTe sugiero que escuches la historia que tengo que contar.$B$BTen cuidado, debes completar esta tarea $gsolo:sola;. Se recomienda que tus aliados se mantengan a distancia. La interferencia de agentes externos resultará en un castigo más severo.$B$BEl destino te ha llevado a ti y solo a ti, hasta aquí. Batalla con honor. Aprovecha la luz.",
		},
		[7622] = {
			title = "Equilibrio de Luz y Sombras",
			accept = "Debes hacer tú lo que yo no pude: Salva a los campesinos que fueron atacados cuando huían de Stratholme.$B$BCaminarán hacia la Luz... Tú debes garantizar su supervivencia. Si caen demasiados de ellos, nuestra existencia maldita continuará... y tú habrás fracasado.$B$BToda habilidad, oración y hechizo que hayas aprendido será puesto a prueba. Que la Luz te proteja, $n.",
			complete = "Tu tenacidad y coraje son asombrosos, $gsacerdote:sacerdotisa;. Te has ganado el derecho a poseer la Astilla de Nordrassil. Solo queda una tarea: el Ojo de las Sombras debe recuperarse. Recorre el mundo.",
		},
		[7623] = {
			title = "Lord Pesadilla",
			accept = "Mor'zul dice que quieres abrir un portal a Xoroth. Para ello, necesitarás polvo estelar xorothiano. ¡No es fácil de encontrar en Azeroth!$B$BHay un ser que podría tener algo de este polvo: Lord Pesadilla en Jaedenar, el miembro del Consejo de la Sombra! Habla con él y puede que te dé algo de polvo estelar.$B$BAunque si vas a Jaedenar, tendrás que revestirte del toque maligno del Consejo de la Sombra. Para ello, hará falta alguna de mis pociones enigmáticas y eso te costará...",
			complete = "Mi paciencia se extiende por milenios, $n. Pero no creas que te permite más de un instante de mi tiempo...",
		},
		[7624] = {
			title = "Ulathek el Traidor",
			accept = "¿Deseas caerme en gracia? Entonces mata por mí.$B$BEs patético ver cómo mi sirviente, Ulathek, se arrastra ante mí, mientras conspira a mis espaldas con Lord Hel'nurath sobre Xoroth. Hel'nurath planea usurpar mi poder aquí y Ulathek es su espía...$B$BDemuestra que es a mí a quien sirves y no a mis rivales. Enfréntate a Ulathek en su barrio, en la Guarida Sombría, hacia el oeste. Dile que conozco su secreto y fíjate cómo se encoge del miedo. Entonces, ¡tráeme el corazón de ese traidor!",
			complete = "¡Ah, qué espléndido! Después de pudrirse una semana, ¡este corazón resultará un suculento regalo! Quizás enviaré a buscar la cabeza de Ulathek y la colocaré ante mí mientras como...$B$BMe has prestado un servicio, $n, por lo que mi paciencia ha aumentado. Ligeramente.",
		},
		[7625] = {
			title = "Polvo estelar xorothiano",
			accept = "¿Así que vienes en busca de polvo estelar xorothiano? ¿Deseas abrir un portal a Xoroth, el dominio de mi rival Hel'nurath? ¿Acaso planeas robarle uno de sus queridos corceles de la Muerte?$B$BVale. Mi sirviente Ur'dan tiene polvo estelar xorothiano. Puedes conseguirlo... si puedes pagar el precio.",
			complete = "¡Ahí está! ¡Casi no puedo creer que lo tengas! Debes de haber llegado a un pacto de aúpa con ese señor del terror o habrás pagado una suma indecente, ¡o ambos!$B$BMor'zul tendrá su tinta muy pronto y podrá al fin crear el pergamino con glifos, de forma que puedas abrir un portal a Xoroth ¡y conseguir uno de sus famosos terrorecus!",
		},
		[7626] = {
			title = "La Campana de Dethmoora",
			accept = "Una Campana de Dethmoora, llamada así por la difunta bruja Dethmoora Ojoscuros, es una de las tres herramientas necesarias para crear un Círculo de invocación superior. Cuando está perfectamente en armonía con la Rueda y la Vela, estos objetos son conductores de un enorme poder arcano.$B$BMi sirviente Gorzeeki puede construir una campana de este tipo pero para ello, necesita elixir de poder de las sombras en abundancia. Consigue los elixires de un alquimista y tráeselos a Gorzeeki.",
			complete = "¡Estupendo! Espero que no te costara demasiado conseguir esos elixires. A veces los alquimistas son tan mezquinos con sus creaciones...$B$BCrearé la campana y la guardaré hasta que estés $gpreparado:preparada; para el ritual.",
		},
		[7627] = {
			title = "Rueda de la Marcha Negra",
			accept = "Una Rueda de la Marcha Negra contiene y dirige las intensas energías necesarias para el Círculo de invocación superior. Para que Gorzeeki pueda construir tal rueda, necesitará fragmentos luminosos grandes de un encantador y mena de hierro negro de un maestro minero.$B$BConsíguelos y tráeselos a mi sirviente.",
			complete = "¡Ahí están! He oído que el mineral de hierro negro solo se encuentra en las profundidades de Roca Negra y estoy seguro de que tampoco ha sido fácil encontrar estos fragmentos. Nunca deja de asombrarme la entrega de los brujos. Si decidieras concentrar toda esa energía en la captura de bichos, ¡nadarías en la abundancia!$B$BDisculpa, una pequeña digresión. Crearé la rueda y la guardaré hasta que estés $gpreparado:preparada; para el ritual.",
		},
		[7628] = {
			title = "La Vela del Apocalipsis",
			accept = "Una Vela del Apocalipsis contiene fuego y lo dirige contra quienes intenten interrumpir tu ritual. Si la mantienes encendida cuando crees tu Círculo de invocación superior, cualquier demonio díscolo que se acerque será calcinado por sus llamas.$B$BContener ese fuego no es sencillo. Requiere una esencia de escamas de dragón Negro. Consigue las escamas de un desollador y llévaselas a Gorzeeki Ojovago.",
			complete = "Ah, muy bien. Las necesitaré para contener los fuegos de la vela. Ahora que tengo la balanza, haré la vela y la sostendré hasta que estés $glisto:lista; para comenzar tu ritual para el Círculo de Invocación Mayor.",
		},
		[7629] = {
			title = "Entrega de diablillo",
			accept = "Hay un requisito más para el proceso del papiro de Mor'zul; necesito papel imbuido de polvo estelar xorothiano. Y... me temo que no puedo hacerlo aquí. ¡No tengo el equipo necesario!$B$BSin embargo, hay un laboratorio de alquimia con todo lo que hace falta. Se encuentra en Scholomance, en la isla de Castel Darrow en las Tierras de la Peste.$B$BNo puedo hacer el viaje pero toma este tarro. En su interior hay un diablillo bastante listo. Libéralo en el laboratorio de alquimia y se ocupará de imbuir el papiro.",
			complete = "Ah bueno. J'eevee creó el pergamino. ¿Cómo estuvo Scholomance? Encantador, ¿no crees? Y los bichos allí... ¡Escuché que son deliciosos!$B$BBien hecho, $n, y gracias por devolver mi frasco. Lo tengo desde hace mucho tiempo... ¡y no está a la venta!",
		},
		[7630] = {
			title = "La arcanita",
			accept = "Ahora que ya tengo la campana, la rueda y la vela, debería crear una magnetita. Utiliza la magnetita durante el ritual para alentar a los demás objetos rituales si flaquean.$B$BPara crear la magnetita necesito arcanita. ¿Tienes arcanita? Si no tienes, tendrás que pedírsela a un alquimista.$B$BVuelve a mí cuando tengas la arcanita y yo crearé la magnetita.",
			complete = "¡Lo tienes! ¡Bien hecho! Ahora puedo crear la magnetita. Cuando finalmente estés listo para tu ritual para crear el Círculo de Invocación Mayor, querrás una magnetita para asegurarte de que el ritual no se esfume.",
		},
		[7631] = {
			title = "Corcel nefasto xorothiano",
			accept = "Ya están todos los preparativos. Ahora debes llevar a cabo el ritual para crear un Círculo de invocación superior, después usar el pergamino imbuido de polvo estelar xorothiano... para abrir un portal a Xoroth.$B$BTe he escrito las instrucciones del ritual en un papiro. Estúdialo atentamente, ya que debes seguir al pie de la letra cada paso si quieres que salga bien.$B$BQue la Fortuna te acompañe, $n. Y que las almas de tus enemigos encuentren raudamente su camino hacia tu bolsa de fragmentos.",
			complete = "Has derrotado al espíritu del corcel nefasto de Xoroth. Aunque la furia aún late por sus fantasmales flancos, sabes que el alma de la bestia es tuya...$B$BLe susurra magia oscura a tu mente y te infiere el conocimiento para conjurar un corcel nefasto.",
		},
		[7632] = {
			title = "La hoja antigua",
			accept = "La epidermis de la hoja tiene un luminoso brillo verde. La superficie es muy rugosa, y tiene muchas venas y arrugas.$B$BSi tuvieras que arriesgar una opinión, dirías que esta hoja proviene de algo antiguo y poderoso.$B$BQuizás deberías encontrar al dueño de esta hoja...",
			complete = "Por supuesto que reconozco mis propias hojas. ¡Mira eso! Esta en perfectas condiciones.$B$BQué bueno que lo devuelvas, $n.$B$BQuizás pueda sernos útil y nosotros a ti.",
		},
		[7633] = {
			title = "Una presentación",
			complete = "Se ha observado tu diligencia e integridad, $n.$B$BSomos Ancianos: Protectores de este otrora gran bosque. Nuestras formas físicas fueron destruidas hace 10.000 años cuando Archimonde y la Legión Ardiente marcharon sobre Hyjal. Nuestros espíritus, sin embargo, permanecen intactos.$B$BHay tareas que podemos ofrecer. Tareas que, si se completan, te revelarán los secretos de los Antiguos.$B$BDebes saber esto, si completas estas tareas, simplemente regresa a esta roca y responderemos a la llamada.",
		},
		[7634] = {
			title = "Carcaj antiguo cosido con tendón",
			accept = "Saludos, $c. Soy Hastat, anciano de Conocimiento. Poseo conocimientos que se perdieron hace eones.$B$BCon el tratamiento adecuado, una de mis hojas puede convertirse en un carcaj como no se ha visto en 10000 años. Un carcaj que, cuando se acompaña con un arco de los ancianos puede conceder poderes inimaginables.$B$BVuelve aquí con el tendón de un dragón Azul adulto y este carcaj será tuyo.",
			complete = "Que mis hojas protejan tus flechas del daño. Que tus flechas sean certeras. Que los enemigos de nuestro mundo sean derrotados.",
		},
		[7635] = {
			title = "La cuerda adecuada",
			accept = "Vartrus puede ofrecerte la madera curva que forma el arco de los Ancestros, pero solo yo puedo encantar la cuerda que necesitas para completar el arco.$B$BEs un proceso sencillo, ser insignificante. Mata a un dragón Negro maduro y extrae el tendón de sus huesos. Tráeme ese tendón y yo lo encantaré y lo convertiré en una cuerda de arco casi indestructible.",
			complete = "Este era un dragón de lo más repugnante. El tendón apesta a maldad.$B$BDame un momento para limpiar la suciedad de esta carne y aplicar los encantamientos adecuados.",
		},
		[7636] = {
			title = "El báculo de los Ancestros",
			accept = "Los agentes de la Legión Ardiente aún están activos en nuestro mundo, $c. Esos agentes corrompen todo lo que tocan. La naturaleza tiembla y llora con su sola presencia.$B$BDebes buscar a esos demonios corruptores y destruirlos, $n. Pero cuidado: debes afrontarlos $gsolo:sola;, o huirán. Si te ven $gsolo:sola;, intentarán destruirte. Entonces, ataca, y convierte su arrogancia en miseria.$B$BTe doy un fragmento de mi corteza; las inscripciones te guiarán a tus objetivos. Tráeme sus cabezas.",
			complete = "¡Nos has servido bien, $n! Toma este pentagrama y combínalo con la cuerda de arco que Stoma es capaz de crear. Juntos, forman un arma formidable.",
		},
		[7637] = {
			title = "Énfasis en el sacrificio",
			accept = "Para prepararte para esta tarea, primero debes demostrar tener voluntad de sacrificio y buen juicio... con énfasis en lo del sacrificio.$B$BPara la tarea, debes adquirir el incensario de exorcismos del sumo sacerdote Rohan. Incluso aunque su uso será para hacer el bien y la justicia, hay que dar una compensación a cambio.$B$BVete a Forjaz y habla con el sumo sacerdote. Al llevar suficientes monedas para ayudarle a superar la pérdida de su incensario, estarás demostrando tu sacrificio.$B$BY ahora vete, $n, el tiempo es vital.",
			complete = "¡Bendiciones para ti, $gamigo:amiga; $c! Tu donación va mucho más allá de lo necesario. Tu sacrificio no solo nos ayudará a recuperar lo que hemos perdido, sino que también nos ayudará a ayudar a los más necesitados aquí en Forjaz.$B$BAhora, déjeme asegurarme de haber preparado adecuadamente este incensario para tus necesidades futuras...",
		},
		[7638] = {
			title = "Lord Grisillo Quiebrasombras",
			accept = "$n, ha llegado la hora de que sepas lo que necesitarás para adquirir algo que, sin duda, llevas un tiempo esperando... tu destrero.$B$BHabla con Lord Grisillo Quiebrasombras aquí, en el Distrito de la Catedral de Ventormenta. Te enseñará a cuidar de tu montura y te dirá qué tareas debes completar para conseguir una.$B$BTe deseo lo mejor. ¡Por la Luz, mi noble $ghermano:hermana;!",
			complete = "Me alegro de verte $n. Sé que has esperado noticias sobre cómo adquirir tu montura, y ahora ha llegado el momento.$B$BSeguramente serás probado de muchas formas diferentes, pero lo más importante es tu voluntad de superar los numerosos obstáculos que se te presentan. Estos no se realizan como un ejercicio de aprendizaje: su dificultad va más allá de las simples pruebas educativas. Debes salvar a tu futuro compañero de las garras del mal contra el que te has pasado la vida luchando.$B$B¡Ojo, ha llegado la hora!.",
		},
		[7639] = {
			title = "Mostrarse juicioso",
			accept = "Toma el incensario. Lo he utilizado en varios exorcismos; te ayudará en las arduas tareas que te esperan.$B$BVuelve a hablar con Lord Grisillo Quiebrasombras en Ventormenta, $n. Tu misión sigue con él.",
			complete = "Sí, esto servirá. Se le pedirá más de una vez durante este proceso para realizar actos de sacrificio; Me alegra ver que está dispuesto a hacer precisamente eso. El sacrificio es un componente clave en lo que se necesita para cumplir con los deberes de ser un Paladín ... pero no tengo que sermonearte sobre eso.$B$BAhora $n, deberás mostrar el debido juicio en tus acciones. Con ese fin, este incensario actuará como tu recipiente para emitir tal juicio sobre los espíritus torturados de tierras perdidas para nosotros.",
		},
		[7640] = {
			title = "Exorcismo en Valle del Terror",
			accept = "He añadido al incensario una pizca de suciedad de la tierra manchada del Valle del Terror, en las Tierras de la Peste del Este. Ahora utilizarás el incensario para encontrar zonas que muestren signos de agitación y alteración espiritual. Busca las auras verdes que impregnan la tierra cuando el mundo físico se comba bajo el tormento del reino espiritual y utiliza el incensario para expulsar a los espíritus malvados.$B$BCuando hayas juzgado lo suficiente a los espíritus, estarás $gpreparado:preparada; para continuar.",
			complete = "Bien hecho, $n. Dar el juicio de la Luz sobre los que moran en las tinieblas es una tarea que debemos abordar con entusiasmo y celo; lo has hecho con tu sacrificio en Forjaz y tus juicios sobre los espíritus en el Valle del Terror.$B$BTus próximos pasos requerirán tanto sacrificio como juicio nuevamente mientras luchas por recuperar el espíritu de un caballero caído que ahora sirve a un Caballero de la Muerte conocido como Atracoscuro.",
		},
		[7641] = {
			title = "El trabajo de Grimand Elmore",
			accept = "El destrero de un paladín no es más que una bestia de carga sin una gualdrapa. La gualdrapa de tu destrero no solo necesita estar hecha de los mejores materiales, sino que, debido a las circunstancias, también debe estar muy en sintonía con el reino espiritual.$B$BPero primero lo primero, $n. Tenemos que hacer tu gualdrapa. En el Distrito de los Enanos de Ventormenta, vive uno de los mejores artesanos, Grimand Elmore. Su trabajo no será barato, pero lo que buscamos es calidad. Habla con él.",
			complete = "Hola, Lord Quiebrasombras me envió un mensaje con anticipación de que vendrías por aquí para verme. Estoy dispuesto a hacerte lo que necesitas, pero no será barato ni fácil; saquemos eso a la luz en primer lugar.$B$BDiré todo esto, y Grayson me respaldará cuando haga esta afirmación... no encontrarás mejores bardas hechas en todo Azeroth que aquí.",
		},
		[7642] = {
			title = "Recopilación de artículos",
			accept = "Para la gualdrapa necesitarás cuatro objetos: paño rúnico para las costuras, barras de arcanita para las placas, lágrimas de Arthas para la sintonía espiritual y agua sagrada de Stratholme para la infusión espiritual. En verdad, son cinco cosas... Oro también, para pagarme a mí. El precio incluye la mano de obra así como sillín y estribos artesanales.$B$BUna vez que tengas todo eso podré terminar la montura. Hasta ese momento, hay algunas cosas con las que puedo empezar mientras te haces con lo que te pedí.",
			complete = "Esto... bueno, esto es exactamente lo que necesitaba. Eres bastante $gingenioso:ingeniosa; $n, ¿no?$B$BMuy bien, ¡terminemos esta barda para ti!",
		},
		[7643] = {
			title = "El antiguo espíritu equino",
			accept = "Tu gualdrapa necesita una bendición especial, una del espíritu apropiado. En La Masacre puedes encontrar a ese espíritu, el antiguo espíritu equino. Actualmente lo tiene un treant corrupto, Tendris Alabeo. Haz justicia con esa bestia malvada, $n.$B$BHas de saber esto, la libertad sin más, no es suficiente. Tendrás que calmar al espíritu antes de recibir su bendición. Para eso, necesitarás comida para caballos. Vete a Costasur y habla con Merideth Carlson sobre esto... Y prepárate para más sacrificios.",
			complete = "El Antiguo Espíritu Equino acepta la ofrenda del pienso para caballos enriquecido con maná, acariciando el recipiente mientras se sirve la avena y los cereales especiales. Después de haber comido un poco, mira la barda que posees y se posiciona como si quisiera que la coloques sobre su espalda...",
		},
		[7644] = {
			title = "La gualdrapa de arcanita bendita",
			accept = "La gualdrapa descansa en la parte posterior del antiguo espíritu equino y apenas brilla. Durante un momento, el aire se llena de poder y después, la gualdrapa desaparece para reaparecer a salvo en tu mochila.$B$BParece que la gualdrapa ha sido bendecida. Según las instrucciones de Lord Quiebrasombras, ahora deberías llevarle la gualdrapa a Ventormenta.",
			complete = "Has llegado lejos, $gamigo:amiga;. Tu barda está ahora adecuadamente preparada para la última tarea que tienes entre manos.$B$BUsarás esta barda para aprovechar tu corcel una vez que la tarea de redención esté completa. Antes de eso, sin embargo, tendrás que superar una lucha monumental. Tu tiempo se acerca - ¡huzzah!$B$BHay un último elemento que debe hacerse antes de comenzar esto, $n. Ojalá tu ingenio no te haya abandonado desde que te hiciste la barda...",
		},
		[7645] = {
			title = "Alimento para caballos enriquecido con maná",
			accept = "Los Mano de Plata pensaron que estaba majara cuando les hablé de mi alimento especial para caballos espirituales. ¡Todo el mundo pensó que estaba mal de la cabeza! ¡Ha llegado mi revancha!$B$BTe daré lo que necesitas, paladín... Campeón... Pero te va a costar caro. Necesito unas galletas especiales, las galletas enriquecidas con maná que solo fabrica El Alba Argenta. ¡Y además exijo un pago en oro en compensación por lo mal que lo he pasado!$B$BA ver ese sacrificio, paladín.",
			complete = "SÍ, AHORA QUIÉN - espera - ¿también me estás dando el oro? ¿No fuiste tú quien me llamó loco? (en realidad me llamaron un loco de pastel de frutas)... aún así, ¿estás $gdispuesto:dispuesta; a mostrar sacrificio incluso por los errores que no has cometido?$B$BYo... te juzgué mal, $n. Si necesitas más alimento para caballos, ven a verme. Te lo daré gratis. Gracias... noble $n.$B$BSin embargo, me voy a quedar con el dinero; no estoy tan loco como para renunciar a una fortuna.",
		},
		[7646] = {
			title = "El cristal de adivinación",
			accept = "Ahora tenemos que ensamblar el cristal de adivinación. Con esto se iniciará la prueba que te permitirá redimir al destrero caído. Tu cristal, en verdad, casi está terminado. El incensario de exorcismos de Valle del Terror es el catalizador para finalizarlo, y diseñaré algo para guardarlo.$B$BLos últimos componentes que necesito son dos diamantes. Tienen que estar tan yuxtapuestos en brillo como lo están en propósito... uno de Azeroth y otro Negro prístino. Ambos constituirán la señal con la que llamaremos a las sombras.",
			complete = "Estos son buenos ejemplares, $n; las piezas finales ya están en su lugar. ¡Por fin, ha llegado tu hora!$B$BEn las profundidades del Gran Osario de Scholomance se encuentran los restos óseos de muchos seres. Entre ellos se encuentra un caballero que alguna vez fue noble. El alma hueca de este caballero ahora sirve como corcel para el Caballero de la Muerte Atracoscuro. Es a él a quien te enfrentarás, y es este corcel al que juzgarás. Solo tú, $n, puedes redimir su alma y salvarla del tormento de su servidumbre.",
		},
		[7647] = {
			title = "Juzgar y redimir",
			accept = "Coge este saco, en él están los objetos que necesitarás para tu tarea.$B$BUtiliza el cristal de adivinación que está en el centro del sótano de El Gran Osario para atraer a los espíritus acusados que deben ser juzgados. Utiliza tu juicio sabiamente durante esta prueba, demostrarán ser más poderosos de lo que te puedas imaginar. Después de los espíritus, aparecerá el Caballero de la Muerte. Véncele y reclama el alma perdida del destrero. Solo entonces, $n, podrás redimirlo y colocar tu gualdrapa en tu nueva montura.$B$B¡Buena suerte!",
			complete = "Un destello de vida, largamente ausente de la pobre bestia, brilla en sus ojos mientras le devuelves su alma juzgada. Sientes una oleada de poder sagrado a tu alrededor cuando colocas la barda sobre su espalda, habiendo juzgado al corcel redimido. El corcel acaricia tu mano mientras las cargas del pasado son quitadas de la bestia. Ahora sientes que podrías llamar a esta bestia para que te sirva como tu corcel, en caso de que surja la necesidad.$B$B¡Has reclamado tu corcel épico, $n! ¡Felicidades!",
		},
		[7648] = {
			title = "Un trabajo bien hecho",
			accept = "<Grimand se limpia el sudor de la frente, sonriendo con orgullo.>$B$BAquí tienes, camarada. Una de mis mejores obras, tan buena como la gualdrapa que hice personalmente para Lord Quiebrasombras cuando fue a por su propio destrero. Te agradezco la confianza que has depositado en mí para hacer este trabajo.$B$BSin duda, Grayson también querrá verlo. Llévale la gualdrapa y agradécele de mi parte su honrado trabajo.",
			complete = "Este trabajo es impresionante. Parece que a medida que Grimand envejece, su destreza continúa mejorando. Esa es una gran hazaña cuando su trabajo ya era uno de los mejores que encontrarías en cualquier lugar cuando hizo mi barda en el pasado.$B$BSi bien esta barda sería una excelente adición a cualquier corcel normal, no estamos tratando con una bestia tan mundana. Necesitará esta barda bendecida por una fuente adecuada para que sea digna de descansar sobre la montura de $gun:una; $c. Lo guardaré por ti hasta entonces.",
		},
		[7649] = {
