		[7815] = {
			title = "¡Quijafortes, colega!",
			accept = "¡No te fíes de su jeta! Los quijafortes marinos son peligrosos. Cada cinco minutos viene uno de esos aspiradores acuáticos y me arranca el cebo.$B$BHaz un favor a todo el Poblado Sañadiente y acaba con ellos.$B$B¡No dejes ni uno!",
			complete = "No sabes cuánto te lo agradezco. Espero que esta caña de pescar sea justa recompensa.",
		},
		[7816] = {
			title = "¡Gammerita, colega!",
			accept = "¡Eh! Hay una tortuga que no es como las otras. Es Gammerita, la jefa de los quijafortes marinos; una condenada ladrona también es.$B$BSe llevó mi mejor cebo. ¡Lo mordió y se lo llevó! Desde entonces, pican menos.$B$BBusca a Gammerita y sácale mi cebo del estómago.",
			complete = "¡Genial! Con el cebo y muchos quijafortes muertos, tendré muchos muchos peces.",
		},
