		[7828] = {
			title = "Acechar a los acechadores",
			accept = "Muchos trols han perdido la vida en las duras Tierras del Interior, $r. Los lobos melenargenta son uno de los mayores peligros para nuestros cazadores. Atacan por emboscada, escondiéndose entre la vegetación.$B$B¡No vamos a permitirlo!$B$BVamos a darles su propia medicina. ¡Los acecharemos! ¡Y acabaremos con ellos!",
			complete = "Buen trabajo, $r. Tienes la gratitud de los Sañadiente.",
		},
		[7829] = {
			title = "Cazar a los salvajes",
			accept = "Una de las criaturas más desagradables de las Tierras del Interior son las lechubestias salvajes. Más de un buen guerrero Sañadiente ha caído bajo sus feroces picos y garras.$B$BMata todas las lechubestias salvajes que encuentres, $r. Vuelve cuando te hayas saciado de sangre. Tu contribución se ponderará y juzgará convenientemente.",
			complete = "Has demostrado tu valor ante los Sañadiente, $n. Bien hecho.",
		},
		[7830] = {
			title = "Vengar a los Caídos",
			accept = "Esos desgraciados de los Martillo Salvaje adiestran a los grifos para matar trols. Es horrible, pero pronto se hará justicia.$B$BPor ahora, concéntrate en exterminar a los grifos más viejos de la región. Se los conoce como los Señores del Cielo.$B$BMata uno y tráeme su péndola.",
			complete = "<Markhor observa la péndola.>$B$BMe pregunto a cuántos cazadores habrá devorado esta bestia.",
		},
