		},
		[7838] = {
			title = "El maestro mayor de la arena",
			complete = "¡Has derramado mucha sangre en la Arena, y tengo el honor de nombrarte gran maestro de arena!",
		},
		[7839] = {
			title = "Los vándalos de Vilrama",
			accept = "¡Esos rufianes Vilrama han invadido el poblado y se han llevado mis herramientas! Tengo herramientas de repuesto, pero las que se llevaron eran un regalo de un gnomo bondadoso que me salvó la vida cuando era jovencito.$B$BQuiero recuperarlas, $n; son importantísimas para mí.$B$BMarkhor informó que se han visto cerca de los templos de Agol'watha y Shaol'watha.$B$BEstán en la región norte de las Tierras del Interior.$B$B¡Tráeme mis herramientas!",
			complete = "¡Mis herramientas! ¡Excelente! ¡Gracias, muchas gracias, $n!",
		},
		[7840] = {
			title = "Lard perdió su almuerzo",
			accept = "Lard estaba comiendo en un sitio secreto cuando el feo Vilrama le dio con su porra. Lard fue corriendo a Sañadiente pero se dejó el almuerzo. Lard tiene hambre. ¿Quieres ir al sitio secreto a buscar el almuerzo de Lard? Lard tiene miedo. Ve al norte. El sitio secreto está en la isla del norte.",
			complete = "<Lard coge la carne y empieza a devorarla.>$B$BQué rico. Gracias.$B$BLard te hace un regalo por tu ayuda.",
		},
		[7841] = {
			title = "Un mensaje para los Martillo Salvaje",
			accept = "Los Martillo Salvaje negocian con nuestros enemigos, establecen alianzas. Ahora andan detrás de los elfos nobles.$B$B<Escupe.>$B$BHay que mandar un mensaje a los Martillo Salvaje: un mensaje con sangre de nuestros enemigos. Asesina a todos los elfos nobles de Vallealto que encuentres y deja sus cuerpos como advertencia.$B$B¡Con los trols no se juega!",
			complete = "Parece que los Sañadiente están sellando nuevas alianzas. Buen trabajo.",
		},
		[7842] = {
			title = "Un nuevo mensaje para los Martillo Salvaje",
			accept = "Dicen que los Martillo Salvaje y los grifos se quieren tanto como el trol y su trolita. Qué asco. Pero podemos aprovecharnos de eso. Les mandaremos otro mensaje.$B$B¡Mata a todos los grifos que veas en las Tierras del Interior y recoge una pluma elegante larga! Con eso mandaremos el último mensaje.",
			complete = "¡Solo una cosa más y los Martillo Salvaje aprenderán que con los trols no se juega!",
		},
		[7843] = {
			title = "Un mensaje final para los Martillo Salvaje",
			accept = "<Te da una lanza manchada de sangre y envuelta en plumas de grifo.>$B$BToma. Llévatela a Pico Nidal, en medio del pueblo, junto al pozo. ¡Clávala en el suelo! ¡Con poderío! ¡Así aprenderán los enanos a tomar en serio a los trols! Vuelve después. Esperemos que vuelvas con vida.",
			complete = "Me habría gustado verles las caras. ¿Ya están haciendo las maletas?$B$BMuy buen trabajo, $n. Te has ganado un mojo grande.",
		},
		[7844] = {
			title = "Unos primos caníbales",
			accept = "En las Tierras del Interior viven tres tribus de trols, $n. Solo nos parecemos en eso: en que somos trols y vivimos aquí.$B$BLos Vilrama (mira que les queda bien el nombre) son unos depravados que comen otros trols y humanoides.$B$BSi Zul'jin estuviera aquí, los eliminaría de un solo golpe, pero como aún no ha vuelto, tenemos que apañárnoslas solos.$B$B¡Te toca a ti limpiar la región de chusma!",
			complete = "Buen trabajo, $c. El propio Zul'jin no lo habría hecho mejor.",
		},
		[7845] = {
			title = "El secuestro del anciano Colmillopartido",
			accept = "Esos salvajes Vilrama se llevaron a mi amigo en un ataque nocturno. Nuestros espías me dicen que está vivo y prisionero en Jintha'alor. Se dice que la sacerdotisa vil Hexx lo está preparando para sacrificarlo al ignoto dios de la sangre, Hakkar.$B$B¡Tienes que salvarlo, $n! El pueblo no podría enfrentarse a tan gran pérdida.",
			complete = "Apresúrate, $n. Seguro que los guardias han detectado tu presencia.",
		},
		[7846] = {
			title = "¡Recupera la llave!",
			accept = "Hitah'ya, la guardiana, tiene la llave de mis cadenas. Está en la cueva que está cerca de aquí. Ten cuidado con ella, $c; está bien protegida.$B$BMátala y trae la llave para quitarme los grilletes. Solo entonces podré volver a casa.",
			complete = "¡Al fin libre! Gracias, $n. ¡Sañadiente sabrá de esta proeza!",
		},
		[7847] = {
			title = "Regresa junto a Primigenia Colmillopartido",
			accept = "Ve al Poblado Sañadiente y avisa a mi compañera, Primigenia Colmillopartido. ¡Dile que voy para allá! Seguro que te recompensará.",
			complete = "¡Gracias en nombre de los Sañadiente, $n! Tienes toda nuestra gratitud.",
		},
		[7849] = {
			title = "Una separación angustiosa",
			accept = "Como muchos en el poblado, yo también perdí a un ser querido a manos de los salvajes. Mi gemelo, Malkhor, fue apresado por los Vilrama en el mismo ataque que el compañero de Colmillopartido.$B$BFue ejecutado brutalmente y sus restos arrojados a los lobos y mocos de los Vilrama.$B$BYa es tarde para salvar su vida, pero no para salvar su alma. Recupera sus restos, $n.",
			complete = "Cómo echo de menos a mi hermano...$B$BGracias por tu ayuda, $n. Cuenta con mi gratitud eterna.",
		},
		[7850] = {
			title = "Vasijas oscuras",
			accept = "Los Vilrama luchan con una ferocidad sobrenatural. Se debe a los inmundos trucos mágicos de la sacerdotisa vil Hexx.$B$BEncontrarás vasijas oscuras con sangre corrupta por todo Jintha'alor. Emanan la nauseabunda magia del ignoto dios de la sangre, que da fuerzas y pone frenéticos a los Vilrama.$B$BTráeme las vasijas para que pueda limpiar la corrupción y debilitar el poder del dios de la sangre.",
			complete = "Se ha eliminado la energía maléfica que controlaba a los Vilrama, pero solo por el momento. No podemos bajar la guardia; aunque destruyamos a la sacerdotisa vil Hexx, otra ocupará su lugar.",
		},
		[7861] = {
			title = "Se busca: sacerdotisa vil Hexx y sus esbirros",
			accept = "Por orden de Primigenia Colmillopartido se busca a la sacerdotisa vil Hexx y sus esbirros.$B$BSe ofrece generosa recompensa a quien elimine a Hexx y su guardia de élite Aman'zasi.",
			complete = "Este será un duro golpe para los Vilrama. Te has ganado una recompensa magnífica, $n.",
		},
		[7862] = {
			title = "Oferta de empleo: capitán de la guardia de Poblado Sañadiente",
			accept = "Tras la pérdida de Malkhor, el puesto de capitán de la guardia de Sañadiente está disponible. Si quieres ser capitán de la guardia de Sañadiente, completa las siguientes tareas y envía tu solicitud a Primigenia Colmillopartido:$B$BExterminar a los rabiosos Vilrama.$B$BExterminar a los cazadores de las Sombras Vilrama.$B$BExterminar a los bebesangres Vilrama.$B$BExterminar a los comealmas Vilrama.",
			complete = "Desde luego, tienes muchos méritos para el puesto, $n. Acepta esto como pago por tus servicios; revisaré las candidaturas el año próximo.",
		},
		[7863] = {
			title = "Botiquín básico de centinela",
			complete = "Ciertamente has comenzado a demostrar tu valía ante nosotros, $n. ¡Como recompensa, llévate este botiquín! En su interior encontrarás raciones y vendajes que solo se pueden usar dentro de Garganta Grito de Guerra.$B$BA medida que continúes demostrando tu valía dentro de Garganta, encontrarás que estos artículos estarán disponibles para su compra. Las raciones están disponibles cuando eres Amistoso con nosotros y los vendajes cuando eres Honorable.",
		},
