		[7877] = {
			title = "El tesoro de los Shen'dralar",
			accept = "En la biblioteca, El Athenaeum, encontrarás un baúl antiguo escondido debajo de las escaleras. De lo que veas en él, toma cuanto desees.",
			complete = "Abres el cofre y en su interior encuentras...",
		},
		[7881] = {
			title = "Las botas de los feriantes",
			complete = "Gracias, $n. Estas están bastante bien hechas. ¡La artesanía es de primera! Aquí tienes un boleto para la Feria de la Luna Negra... disfrútelo, $gseñor:señora;.",
		},
		[7882] = {
			title = "Los chalecos de los feriantes",
			complete = "Ah, trajiste los chalecos. Espléndido. ¿Qué piel de animal usaste para hacer estos, puedo preguntar? El trabajo de costura está muy bien hecho y la textura del cuero tiene un estilo rugoso. ¡Puedo decir que eres $gun artesano experto:una artesana experta;!$B$BGracias, $n, aquí están tus boletos.",
		},
		[7883] = {
			title = "¡El gnomo más grande del mundo!",
			complete = "¡Oh, cielos, estos son bastante grandes! No puedo imaginar encontrar un gnomo que se ajuste perfectamente a ellos, pero no te preocupes, si el gnomo que encontramos no es lo suficientemente grande, puedo hacer ajustes en el disfraz.$B$BMuchas gracias, $n. Aquí están los boletos que te prometí.",
		},
		[7884] = {
			title = "El chico crocolisco y el múrloc barbudo",
			complete = "¡Genial, los hiciste! Estos funcionarán muy bien... Solo espero que no sea yo quien limpie la jaula de los crocoliscos cuando llegue el momento. Esas bestias pueden ser bastante bestiales, ¿no crees?$B$BAquí están tus boletos, $n. ¡Disfrútalos y disfruta de tu estancia en la Feria de la Luna Negra!",
		},
		[7885] = {
			title = "Refuerzos para armadura",
			complete = "¡Genial! ¡Esto funcionará muy bien! ¡Acabo de notar una rotura en una tienda de campaña más allá, y uno de estos kits de armadura es justo lo que necesito para arreglarlo!$B$BMuchas gracias, $n. Estos kits de armadura nos ahorrarán una tonelada en costes de reparación. Aquí tienes tus entradas, ¡te las mereces!",
		},
		[7886] = {
			title = "Talismanes del mérito",
			complete = "Gracias, $n. Tus hazañas en Garganta Grito de Guerra resuenan por todo el Bosque de Vallefresno.",
		},
		[7887] = {
			title = "Talismanes del mérito",
			complete = "Gracias, $n. Tus hazañas en Garganta Grito de Guerra resuenan por todo el Bosque de Vallefresno.",
		},
		[7888] = {
			title = "Talismanes del mérito",
			complete = "Gracias, $n. Tus hazañas en Garganta Grito de Guerra resuenan por todo el Bosque de Vallefresno.",
		},
		[7889] = {
			title = "Contrapeso burdo",
			complete = "¡Genial! ¡Estos funcionarán muy bien! No son demasiado pesados, pero tampoco demasiado livianos. ¡Son perfectos para desarrollar masa muscular!$B$BMuchas gracias, $n. ¡Aquí tienes tu boleto para la Feria de la Luna Negra!",
		},
		[7890] = {
			title = "Piedra de pulir pesada",
			complete = "¡Trajiste las piedras! ¡Y son pesados! Ya puedo sentir que mis músculos se agrandan. ¡Gracias $n!$B$BToma, toma estos boletos y asegúrate de no comer demasiados dulces mientras estás en la feria. ¡$gUn:Una; $n grande y fuerte como tú necesita mantenerse en forma para luchar!",
		},
		[7891] = {
			title = "Brazales de hierro verdes",
			complete = "Muchas gracias, $n. ¡Aquí tienes tus entradas para la Feria de la Luna Negra!",
		},
		[7892] = {
			title = "Maza negra grande",
			complete = "Muchas gracias, $n. ¡Aquí tienes tus vales para la Feria de la Luna Negra!",
		},
		[7893] = {
			title = "Ritual de fuerza",
			complete = "Muchas gracias, $n. ¡Aquí tienes tus vales para la Feria de la Luna Negra!",
		},
		[7894] = {
			title = "Modulador de cobre",
			complete = "¡Ajá! ¡Los moduladores! ¡Magnífico!$B$BNo puedo decirte exactamente lo que estamos construyendo, pero son fundamentales para su construcción. Estoy en deuda contigo, $n, pero por favor, toma este boleto de la Feria de la Luna Negra como muestra de mi agradecimiento.",
		},
		[7895] = {
			title = "Cacharros zumbones de bronce",
			complete = "¡Trajiste los Cacharros! ¡Maravilloso! ¡Incluso ahora puedo escuchar su zumbido en mi mente! ¡Oh, cuando este stand esté listo será la maravilla del mundo!$B$BAquí están sus boletos, $n. ¡Y disfruta de tu estancia en la Feria!",
		},
		[7896] = {
			title = "Fuego de artificio verde",
			complete = "Trajiste los fuegos artificiales. ¡Espléndido trabajo, $N! ¡No puedo esperar para encenderlos y decirle a todos que mi puesto está listo! Pero debo esperar, desde hace mucho tiempo tengo miedo, pero... estaré listo cuando esté listo, ¿vale?$B$BAquí están los vales, $N. ¡Disfrútalos!",
		},
		[7897] = {
			title = "Juegos de herramientas mecánicas de reparación",
			complete = "¡Gracias! Ahora puedo arreglar las cosas.$B$BSe necesitarán muchos kits de reparación y muchas horas de la noche para que todo funcione correctamente. A veces pienso que sería mejor volver a mis raíces y reiniciar mi carrera como cazatalentos, pero... la Feria ha sido buena conmigo.$B$B¡Toma estos boletos, $n, y diviértete!",
		},
		[7898] = {
			title = "Trastos de torio",
			complete = "¡Ah, gracias, $n! Yebb disfrutará de estos trastos. No sé qué ha planeado para ellos, pero Yebb es un pequeño gnomo inteligente. Es inteligente, y tal vez un poco tortuoso...$B$BSi tan solo le gustara el sabor de la carne humanoide... ¡sería un gran troll!$B$BAquí, $n. Un trato es un trato, y estos boletos son tuyos.",
		},
		[7899] = {
			title = "Patitas peludas",
			complete = "¡Genial, las tienes! Podemos usarlas para hacer juguetes y chucherías, ¡y atraerán a más personas a la feria!$B$BAquí está tu boleto, $n. ¡Te lo has ganado!",
		},
		[7900] = {
			title = "Pieles de oso",
			complete = "¡Bonitas pieles, $n! Conseguiré que alguien las cosa en un montón de peluches. Con un poco de relleno y pintura, creo que serán la envidia de los niños de todo Azeroth.$B$B¿Boletos? ¡Ah, sí, tu pago!$B$B¡Aquí están!",
		},
		[7901] = {
			title = "Colas peludas blandas",
			complete = "¡Bien hecho, $n! Estas colas serán grandes premios para nuestros visitantes, y eso significa visitantes felices... ¡que hablan con sus amigos y traen más visitantes!$B$B¡Aquí tienes tus boletos! Diviértete en la Feria de la Luna Negra... ¡y no olvides hablarles a tus amigos sobre nosotros!",
		},
		[7902] = {
			title = "Péndolas vibrantes",
			complete = "¡Ah, las plumas! Son increíbles, ¿no te parece? ¡Sería fácil despertar la imaginación con tales bellezas!$B$BHaces un trabajo caritativo, $n. Las sonrisas en los rostros de nuestros visitantes cuando ven el espectáculo es un gran pago, pero por favor toma también estos boletos.",
		},
		[7903] = {
			title = "Ojos de murciélago malignos",
			complete = "¡Genial! ¡Tienes los ojos! Espero que cazar esos murciélagos te haya asustado, porque si asustó a $gun:una; $n valiente como tú, entonces esos ojos ciertamente asustarán a nuestros visitantes de la Feria.$B$BToma estos boletos, $n, y gracias por tu servicio.",
		},
		[7905] = {
			title = "La Feria de la Luna Negra",
			accept = "¡La Feria de la Luna Negra está al caer! ¡No te pierdas nuestros emocionantes juegos, gana premios increíbles y averigua qué te depara el futuro!$B$BSi te decides, ¡puedes canjear este cupón por vales gratuitos y una copia de la mundialmente famosa guía de campo de la Luna Negra para que te ayude a identificar los tesoros que te encuentres en tus viajes!$B$BLlévale el cupón a Gelvas Roñoso dentro de la feria.$B$BAhora mismo, la feria se encuentra a las afueras de Villadorada, en el Bosque de Elwynn.",
			complete = "¡Te doy la bienvenida a la Feria de la Luna Negra! ¡Este vale te da derecho a CINCO, has oído bien, CINCO boletos de tómbola y una copia gratuita de la mundialmente conocida guía de campo de la Luna Negra!$B$BCuando tengas suficientes boletos, ven a verme para cambiarlos por premios. ¡Esta práctica guía de campo te ayudará a localizar e identificar los objetos de valor de los coleccionistas que hay en la feria!",
		},
		[7907] = {
			title = "La baraja de Bestias de la Luna Negra",
			accept = "Ahora que has reunido todos los naipes de la baraja de Bestias, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: \"Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa\". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.",
			complete = "Bueno, esto explica mucho. Si alguna vez encuentra una forma de entrar en Ahn'Qiraj, esté atento al viejo Brann. Me temo que será inútil sin su mono",
		},
		[7921] = {
