		[7927] = {
			title = "La baraja de Portales de la Luna Negra",
			accept = "Ahora que has reunido todos los naipes de la baraja de Portales, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: \"Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa\". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.",
			complete = "Así que has creado una baraja de portales. Tu gesto de devolvérnoslo creará un vínculo entre tu y la Luna Negra que no se olvidará. Permítame presentarte una de las mejores cartas de la Luna Negra como una pequeña muestra de nuestro agradecimiento.",
		},
		[7928] = {
			title = "La baraja de Señores de la Guerra de la Luna Negra",
			accept = "Ahora que has reunido todos los naipes de la baraja de Señores de la Guerra, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: \"Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa\". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.",
			complete = "Así que has armado un mazo de Señores de la Guerra. Tu gesto de devolvérnoslo creará un vínculo entre tu y la Luna Negra que no se olvidará. Permíteme presentarte una de las mejores cartas de la Luna Negra como una pequeña muestra de nuestro agradecimiento.",
		},
		[7929] = {
			title = "La baraja de Elementales de la Luna Negra",
			accept = "Ahora que has reunido todos los naipes de la baraja de Elementales, aparece misteriosamente un noveno naipe con el mismo reverso que los ocho primeros. Ese naipe tiene una inscripción: \"Lleva estos naipes a la Feria de la Luna Negra y recibe tu recompensa\". Has oído que la entrada a esa feria aparece cada mes cerca de Mulgore y Villadorada.",
			complete = "Así que has armado un mazo de Elementales. Su gesto de devolvérnoslo creará un vínculo entre usted y la Luna Negra que no se olvidará pronto. Permíteme presentarte una de las mejores cartas de la Luna Negra como una pequeña muestra de nuestro agradecimiento.",
		},
		[7930] = {
			title = "5 vales: flor de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7931] = {
			title = "5 vales: Lote menor de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7932] = {
