		[8574] = {
			title = "Equipamiento de adepto",
			accept = "Los distintivos que recibes por misiones de combate, logística y táctica para Clamavientos Cuerno Digno, sirven para algo más que para presumir, $n.$B$BTe aconsejo que los guardes bien. Como prueba de tu lealtad con nuestra organización, puedo ofrecerte equipamiento que reservamos para nuestros aliados más cercanos, a cambio de esos distintivos.",
			complete = "Buen trabajo, $n. Acepta esto en nombre del Círculo Cenarion. ¡Seguro que te lo has ganado, $gamigo:amiga;!",
		},
		[8575] = {
			title = "El libro de contabilidad mágico de Azuregos",
			accept = "No entiendes ni una palabra de este libro de contabilidad. ¡Ni siquiera sabes en qué idioma está escrito!",
			complete = "<Narain examina ansiosamente el texto.>$B$B¡Excepcional, $r! ¿Qué es? No puedo leer ni una pizca de Dracónico.",
		},
		[8576] = {
			title = "La traducción del libro de contabilidad",
			complete = "¡Lo primero es lo primero, $n! Necesitamos averiguar qué escribió Azuregos en este libro contable.$B$B¿Dices que te ha dicho que hagas una boya de arcanita y que este es el esquema? Es extraño que escribiera esto en Dracónico. Esa vieja cabra sabe que no puedo leer estas tonterías.$B$BSi esto va a funcionar, voy a necesitar mis gafas de adivinación, un pollo de 500 kilos y el volumen II de \"Dracónico para Torpes\". No necesariamente en ese orden.",
		},
		[8577] = {
			title = "Guisón, ex mejor amigo",
			accept = "Si quieres que te traduzca algo, necesitaré mis gafas de ver. Por desgracia, Guisón, mi ex-mejor amigo de toda la vida me las robó hace un tiempo. Me rompió el corazón por cinco sitios y luego me dejó aquí para que me pudriera.$B$BCon la ayuda de mi bola de cristal, que SÍ es de fiar, he averiguado su paradero. Puede estar o en La Muralla de Cringris de Argénteos o en lo que parece ser un portal en Terrallende que ahora está controlado por la Legión Ardiente. ¡Vas a tener que encontrarlo para recuperar mis gafas, $n!",
			complete = "No puedo creer que me haya encontrado. Estaba seguro de que lo había perdido cuando estaba en Terrallende. ¡No voy a volver allí, $r! ¡De ninguna manera, de ninguna manera! Estoy harto de ser su mejor amigo a tiempo parcial y esclavo a tiempo completo.",
		},
		[8578] = {
			title = "¿Unas gafas? ¡Sin problemas!",
			accept = "<Oyes un suspiro de alivio que proviene de la caja.>$B$B¿Solo quieres sus gafas de ver? ¡Genial! Eso no será un problema... Solo dame un minuto para... ¡Eh! ¿Dónde dem...? ¡Maldita sea!$B$BMira, tengo una mala noticia y una peor. La mala noticia es que perdí las gafas. La peor es que las perdí cuando estaba curioseando por el Núcleo de Magma el mes pasado. Sí, el Núcleo de Magma... ¡Así que, supongo que ya no quieres nada más de mí! ¡Adiós!",
			complete = "¡Sobresaliente! Ahora, ¿dónde puse ese pollo de 500 kilos y el Volumen II de \"Dracónico para Torpes\"??? ¡Ah, y aquí hay algo por todo tu arduo trabajo!",
		},
		[8579] = {
			title = "Campeones mortales",
		},
		[8580] = {
			title = "¡La Horda necesita flores de fuego!",
			accept = "Eh, $c. ¡Que llamar a ti! Montón flor de fuego la Horda pensar necesidad para preparativos de guerra Ahn'Qiraj. ¿Poder servir en cosas majas esas florecillas? ¿Poder servir combustible para tanques de vapor de la Alianza? ¿Quién saber? No Pele'keiki!$B$BAunque Pele'keiki saber esto... él saber tú ayudarlo conseguir montón flores de fuego, ¿eh, colega?",
			complete = "¡Cruza los dedos, amigo! ¡Esperamos que podamos salvar a Noggle!",
		},
		[8581] = {
			title = "¡La Horda necesita más flores de fuego!",
			complete = "¿N'es una broma, $n? ¿Traes flores de fuego tan rápido? ¡Pele'keiki las cuenta ahora mismo, colega! Estás haciendo a Pele'keiki tan feliz, qu'él se lo dirá a todos, $n ¡el mejor coleccionista de flores de fuego! Pele'keiki no puede esperar a que comience la guerra. Ahora realmente iluminamos el cielo sobre Silithus, ¿verdad, colega?",
		},
		[8582] = {
			title = "¡La Horda necesita lotos cárdenos!",
			accept = "El loto cárdeno, $c, es un componente de muchas grandes pociones, elixires y aceites, algunos de los cuales nos serán de utilidad en Ahn'Qiraj. Tendremos que elaborar una ingente cantidad de tales pociones para los preparativos de la guerra. Y además experimentaré con nuevos usos para el loto cárdeno. Pero para empezar voy a necesitar grandes cantidades de esta flor.$B$BAquí es donde entras tú. Sal al campo y recoge tantos lotos cárdenos como puedas. ¿Es algo que estés $gdispuesto:dispuesta; a hacer para nosotros?",
			complete = "Un trabajo digno de elogio, $c. Mediré estos ejemplares para que se usen apropiadamente y tomaré nota de tu contribución. Habrá que guardar debidamente el loto cárdeno hasta que esté listo. En cuanto a ti, si aún estás disponible, aún voy a necesitar más loto cárdeno. Así que pásate de nuevo pronto.",
		},
		[8583] = {
			title = "¡La Horda necesita más lotos cárdenos!",
			complete = "Un trabajo de primera y de lo más preciso, $n. Tu diligencia es digna de elogio, al igual que tu celeridad. Me ocuparé personalmente de que no se desperdicia un ápice de este loto cárdeno.$B$BGracias otra vez y si encuentras más loto cárdeno, no dudes en traérmelo tan $graudo:rauda; como puedas.",
		},
		[8584] = {
			title = "¡Nunca me preguntes por mi negocio!",
			accept = "Mira, hay algo que tienes que saber sobre mí: ¡NUNCA JAMÁS me preguntes por mi negocio! Trabajo con cosas que sencillamente no entenderías. Como, por ejemplo: ¿sabes lo que es un bozalnano psicotrónico? ¡Pues claro que no! Por eso yo me encargo de la planificación y tú de los recaditos.$B$BComo ya te he dicho, si queremos que esto funcione, necesitaremos un pollo de 500 kilos.$B$BVe a Gadgetzan y habla con Dirge Hojágil. Él te dará pistas para que encuentres un espécimen adecuado.|n",
			complete = "<Dirge se rasca la cabeza.>$B$B¿Un pollo de 500 kilos? ¡No hay tal cosa! Ya no, al menos. Sabía de un pollo así... El Pollo Negro de la Muerte...$B$B<La voz de Dirge se apaga.>$B$BPero sí, nadie vio ese pollo y vivió para contarlo. Tengo una idea que podría beneficiarnos a los dos, $gchico:chica;.",
		},
		[8585] = {
			title = "La Isla del Terror",
			accept = "La leyenda cuenta que los quimerok de la Isla del Terror de Feralas tienen los lomitos más tiernos y suculentos del mundo. Y resulta que estos quimerok también tienen un papá que, con la presentación adecuada, puede parecer un pollo de 500 kilos... o no.$B$BVe a la Isla del Terror y mata a Lord Lakmaeran. Tráeme su cadáver fresquito. Eso debería dejar contento al gnomo. Pero para dejarme contento a mí, tendrás que traerme varias costillitas tiernas de quimerok.$B$BSi lo haces, tendrás tu pollo de 500 kilos y un pequeño extra.|n",
			complete = "¡Mira esos solomillos! ¡Fantástico!$B$BAhora sobre ese pollo... Hrmm, déjame ver. Voy a necesitar unos minutos para idear la receta.",
		},
		[8586] = {
			title = "Fabulosas chuletillas de quimerok de Dirge",
			accept = "¡Mi receta está acabada! Lo que necesito ahora es que me traigas combustible de cohete y sal de roca. Yo me encargo de las especias y la carne que me trajiste completará el plato.$B$BCuando me traigas lo que te he pedido, el pollo estará listo para ser llevado a Narain.",
			complete = "¡Está listo! Te presento mi mayor creación: ¡Fabulosas chuletillas de quimerok de Dirge!",
		},
		[8587] = {
			title = "Regresa junto a Narain",
			accept = "Soy un goblin de palabra, $gchico:chica;. Aquí tienes tu pollo de 500 kilos.$B$BLo que no sé es para qué quiere un gnomo un pollo de 500 kilos...$B$B<Dirge rezonga algo ininteligible.>$B$BProbablemente para dormir en él... Gnomos cochinos...",
			complete = "<Narain clava las dos manos en el enorme pollo, llenándose la cara del delicioso manjar de Dirge.>$B$BMMmmm... ¡Esto es increíble! ¡El mejor pollo que he comido!",
		},
		[8588] = {
			title = "¡La Horda necesita cuero pesado!",
			accept = "Ya que nos estamos preparando para la guerra, será mejor que consigamos primero todo lo que necesitamos, ¿no te parece, colega? Uno de los productos del material bélico que producimos es cuero pesado. Lo usamos para casi todo, desde refuerzos para armadura y para clásicas lonas también.$B$BPero primero tenemos que conseguir más cantidad. Ese es tu trabajo, $c. Afila tu navaja y tráeme un paquete. Entonces seguiremos hablando.",
			complete = "Ah, así que ya tienes el cuero pesado que necesitaba. Afilada es tu espada, $c; ¡estas pieles son muy buenas! Ahora que hemos empezado con buen pie, me ocuparé de que se aproveche debidamente tu contribución. Y si encuentras más cuero pesado, tráemelo.",
		},
		[8589] = {
			title = "¡La Horda necesita más cuero pesado!",
			complete = "¡Así me gusta, colega! Muchísimas gracias por el cuero pesado. Cada granito de arena es importante. Voy a dejar estas pieles en una pila para que los demás peleteros puedan trabajarlas.$B$BGracias otra vez, $n, y si te topas con más cuero pesado, ya sabes dónde encontrarme.",
		},
		[8590] = {
			title = "¡La Horda necesita cuero grueso!",
			accept = "¡Cómo me alegra que hayas decidido hablarme de eso, $c! Por lo visto, los preparativos de la Horda para la próxima guerra de Ahn'Qiraj están a toda máquina. Pero aún falta nuestra contribución.$B$BMe han pedido que reúna un gran número de pieles de cuero grueso para usarlas en todo tipo de material bélico; necesito que vayas a buscarlas y las recolectes. Te llevarás honores y la gratitud de la Horda si decides ayudarnos. ¿Lo harás?",
			complete = "Buen trabajo, $c. Estoy segura de que todas estas pieles de cuero grueso servirán para reforzar los zepelines y confeccionar todo tipo de armas y armaduras. Cuentas con mi más sincero agradecimiento, así como con el de la Horda. Vuelve si encuentras más cuero grueso en tus viajes y que la suerte te acompañe.",
		},
		[8591] = {
			title = "¡La Horda necesita más cuero grueso!",
			complete = "¡Lo conseguiste, $n, sabía que lo conseguirías! Una vez más, gracias en nombre de toda la Horda. Se toma buena nota de tu trabajo y se agradece. Y si encuentras más cuero grueso que te gustaría donar, tráemelo aquí.$B$B¡Lok'tar Ogar, $c!",
		},
		[8592] = {
			title = "La tiara del Oráculo",
			accept = "Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.$B$BTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder qiraji en unos más adecuados a nuestras necesidades.$B$BTráeme los componentes que necesito, $n. Te daré una celada de poder único.",
			complete = "¡Lo has logrado! Los susurros de los Emperadores Gemelos han cesado.$B$BToma esto como recompensa. El mero hecho de verlo infundirá miedo en los corazones de los Qiraji... les recordará a sus líderes caídos y $gal:a la; mortal que los mató.",
		},
		[8593] = {
			title = "Las calzas del Oráculo",
			accept = "¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.$B$BEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.$B$BSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.$B$BTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.",
			complete = "Sí... la piel del gusano será una excelente capa protectora. Combinado con las partes más fuertes de los Qiraji que hemos destruido en nuestro camino hacia aquí, esto debería ser una formidable pieza de armadura. ¡Que te ayude a afrontar los horrores indescriptibles que te aguardan en el interior!",
		},
		[8594] = {
			title = "El manto del Oráculo",
			accept = "Se cuenta entre nosotros que el adorno de la armadura de los hombros que llevan las razas mortales se inspiró en un intento de emular las alas de un dragón.$B$BTráeme las esclavas que llevan los más importantes líderes qiraji y con ellas te forjaré unas hombreras ¡más temidas que las alas del mismísimo Nefarian!",
			complete = "De los materiales que traes y de las escamas de nuestros enemigos Qiraji caídos, te hago estas hombreras, mortal. Que te brinden la protección que necesitas y que verlos infunda miedo en nuestros enemigos.",
		},
		[8595] = {
			title = "Campeones mortales",
			complete = "Sigues sirviéndonos bien, $n. Nuestro pacto sigue en pie.",
		},
		[8596] = {
			title = "Los borceguíes del Oráculo",
			accept = "La magia qiraji es poderosa y antigua. Los más poderosos qiraji empuñan objetos de tal potencia que harían vacilar hasta a un dragón.$B$BTráeme las esclavas de mando qiraji y otros componentes menores y crearé un par de poderosas botas para ti.$B$BTe servirán cuando te enfrentes al enemigo.",
			complete = "Lo has hecho muy bien, $n. Has demostrado que no eres $gun:una; mortal cualquiera.$B$BTe entrego estas confiando en que te ayudarán a aplastar a los malvados qiraji.",
		},
		[8597] = {
			title = "Dracónico para torpes",
			accept = "¡Sabía que ese libro acabaría resultando útil un día! Menos mal que tuve la rapidez y la previsión de guardarlo en lugar seguro.$B$BNo te preocupes, ¡está en un sitio en el que nadie podría encontrarlo nunca! ¡Fíjate que necesité un girocóptero para llegar allí la primera vez! Por desgracia, me estrellé en la playa en el camino de regreso. ¡Pero fue precisamente ese accidente lo que me dio mis supergnomo-poderes psíquicos!$B$BBusca mi girocóptero estrellado por la Playa Finisterrae y nada hacia al sur desde allí. ¡Reconocerás el sitio en cuanto lo veas!",
			complete = "¡El libro no está! Encima del montículo de tierra hay una nota.",
		},
		[8598] = {
			title = "ReScaTe",
			accept = "<El texto de esta nota se compone de recortes de letras pegados en la superficie de un papiro.>$B$BTenemos tu precioso libro, gnomo. Si quieres volver a verlo, tendrás que hacer lo que te pidamos.$B$B<Hay una detallada lista de instrucciones que ocupa 3 páginas.>$B$B¡Trae el dinero! ¡Y ven solo!",
			complete = "<La cara de Narain se pone de un rojo brillante.>$B$BTorturar a mi... libro, ¿lo harán? ¡Les enseñaré lo que significa meterse con un gnomo psíquico!",
		},
		[8599] = {
			title = "Una canción de amor para Narain",
			accept = "No recibo muchas visitas. De hecho, la última vez que tuve visita fue cuando rescaté a ese pobre gnomo de una máquina voladora que se estrelló.$B$B<Meridith mira al vacío, perdida en sus recuerdos.>$B$B¿Lo conoces? ¿Narain? ¿Narain Sabelotodo? ¡No sabes lo que significaría para mí que alguien le llevara un mensaje de mi parte! ¡Necesito decirle lo que siento! ¡Sé que es amor! ¡Sencillamente lo sé!$B$B¿No podrías llevar un mensaje a Narain? ¡Estaría en deuda contigo para siempre!",
			complete = "¿¡Qué!?$B$B<Narain comienza a inquietarse.>$B$BBueno, umm... ¿Qué quieres que haga??? ¡Ella es un pez! ¡UN PESCADO, te lo digo! Y soy un gnomo. Nunca podría funcionar.",
		},
		[8600] = {
			title = "¡La Horda necesita pieles de cuero basto!",
			accept = "Considero que es más importante que la navaja se ajuste bien a tu palma que el estado del filo. Hasta la hoja más desgastada puede cortar si se aplica la presión debida, ¿no te parece, $c? Aunque tú y yo no tenemos tal problema ya que mantenemos siempre las hojas más afiladas, ¿cierto?$B$BBueno, da igual, tengo una tarea para ti. Como servicio a la Horda, y para contribuir a los preparativos de la guerra de Ahn'Qiraj, deseo que cuando vuelvas me traigas pieles de cuero basto. ¿Verdad que harás esto por nosotros?",
			complete = "Muy bien, parece que has hecho un buen trabajo, aunque algunas de estas pieles tienen los bordes algo irregulares. No importa, has completado la tarea y te has ganado una recompensa. Si te vuelves a encontrar con más cuero basto, tráemelo inmediatamente.",
		},
		[8601] = {
			title = "¡La Horda necesita más pieles de cuero basto!",
			complete = "Práctica, práctica, práctica. Con un cuchillo bien afilado y la habilidad para usarlo llegarás lejos en este mundo, $n. Parece que los bordes de estas pieles están mejor que las últimas. ¿Compraste un cuchillo nuevo?$B$BSea como fuere, te agradecemos tus esfuerzos. He tomado buena nota de tu donación y se aprovechará bien, te lo aseguro. Si te acabas haciendo con más cuero basto, vuelve por aquí y habla conmigo ya que seguramente me hará falta más.",
		},
		[8602] = {
			title = "Los espaldares de clamatormentas",
			accept = "Se cuenta entre nosotros que el adorno de la armadura de los hombros que llevan las razas mortales se inspiró en un intento de emular las alas de un dragón.$B$BTráeme las esclavas que llevan los más importantes líderes qiraji y con ellas te forjaré unas hombreras ¡más temidas que las alas del mismísimo Nefarian!",
			complete = "De los materiales que traes y de las escamas de nuestros enemigos Qiraji caídos, te hago estas hombreras, mortal. Que te brinden la protección que necesitas y que verlos infunda miedo en nuestros enemigos.",
		},
		[8603] = {
			title = "Las vestimentas del Oráculo",
			accept = "El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.$B$BCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.$B$BHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!",
			complete = "No esperaba que regresaras de tu intento, $n.$B$BHas alcanzado un destino más grande que el de la mayoría de los seres inmortales.$B$BAl matar a C'Thun no solo has salvado a todo Azeroth, también has cambiado el balance de los acontecimientos cósmicos más allá de tu comprensión.$B$BAcepta esta togas como símbolo de la gloria y el peso de las consecuencias que tus acciones acarrearán.$B$BQue su poder te ayude en los retos que te aguardan, ¡$gasesino:asesina; de dioses!",
		},
		[8604] = {
			title = "¡La Horda necesita vendas de lana!",
			accept = "Saludos, $c. Para los preparativos de la guerra de Ahn'Qiraj, estoy coordinando las tareas de la Horda para reunir vendas de lana. Por desgracia, cuando estén ahí fuera, nuestros soldados no pueden depender de la presencia de un sanador para mantenerse vivos. Créeme, he pasado por ahí. Por lo tanto, estamos confeccionando todos estos botiquines de primeros auxilios para ellos.$B$BSi tienes tiempo, necesito muchas vendas de lana. Tráemelas aquí y me ocuparé personalmente de que recibes tu merecida recompensa.",
			complete = "Tienes mi agradecimiento, $c, y el agradecimiento de la Horda. Si encuentras más vendas de lana, tráemelas aquí si deseas contribuir aún más al esfuerzo de guerra. Hasta entonces, ¡que tus antepasados velen por ti!",
		},
		[8605] = {
			title = "¡La Horda necesita más vendas de lana!",
			complete = "¡Como $c, mereces todos mis respetos, $n! Me aseguraré de que esas vendas van a parar a las manos apropiadas. Cuentas con mi más sincero agradecimiento, así como con el de la Horda.$B$BVe en paz y vuelve si te encuentras con que te sobran vendas de lana. Toda contribución nos viene bien.",
		},
		[8606] = {
			title = "¡Señuelo!",
			accept = "¡Lo tengo! Esto es lo que vamos a hacer: voy a llenar un saco de piedras y tú vas a hacer la entrega. Sé que la nota decía que tenía que hacerla yo, pero es lo que voy a hacer... más o menos.$B$B<Narain te mira de arriba a abajo.>$B$BSí, darás el pego. Coge el turbante, la toga y el saco de piedras y ve al punto de entrega, en Cuna del Invierno.$B$BHe incluido todo lo que necesitas en este lote especial. Y cuando vengan a recoger la mercancía... ¡acaba con ellos! ¡Eso les enseñará a no meterse con Narain!|n",
			complete = "Creo que es posible que hayamos subestimado a estos secuestradores de libros.",
		},
		[8607] = {
			title = "¡La Horda necesita vendas de tejido mágico!",
			accept = "Espero que estés hablando conmigo porque vas a echar una mano con la recolección que me han confiado ¡Bien! Por cualquier medio, y digo bien cualquiera, deseo que reúnas un buen número de vendas de tejido mágico. Nuevas estaría bien pero no es absolutamente necesario. Tráemelas aquí, $c, y me ocuparé personalmente de que recibes tu merecida recompensa.",
			complete = "Sorprendente, aunque aceptable. Quizás he subestimado tus facultades, $c. Quizás. Has completado una tarea muy sencilla y por ello recibirás una recompensa aún mayor. Pero que no se te suba a la cabeza. Si realmente quieres demostrar lo que vales, tendrás que volver a salir ahí fuera y traerme otro lote de vendas de tejido mágico.",
		},
		[8608] = {
			title = "¡La Horda necesita más vendas de tejido mágico!",
			complete = "¡Asombroso, $c, lo has vuelto a conseguir! Bueno, cierto es que suelen decir que tengo buen olfato para elegir a mis colaboradores. Muy bien, se anotará tu contribución y recibirás los beneficios sociales que tu trabajo merece. Te sugiero que vuelvas de ronda y recolectes otro lote de vendas de tejido mágico si realmente quieres demostrar lo que vales.",
		},
		[8609] = {
			title = "¡La Horda necesita vendas de paño rúnico!",
			accept = "Al parecer la Horda y la Alianza se encuentran abocadas al enfrentamiento en la guerra de Ahn'Qiraj. Sorprendentemente, no es una guerra entre ellas, sino más bien contra los silítidos y la fuerza que los controla sea lo que sea. Otra cosa curiosa es que ambas partes están reuniendo los recursos necesario para librar una batalla con garantías de victoria.$B$BEstoy recogiendo vendas de paño rúnico para distribuirlas entre los soldados, pero no lo conseguiré sin ayuda, espero que la tuya. ¿Crees que puedes ayudarme con eso, $c?|n",
			complete = "Eres un orgullo para la Horda, $c. Gracias por tus continuos esfuerzos, ¡de corazón! Tendré que envolver estas nuevas vendas y hacer un recuento para ver cuánto nos falta para el objetivo. Si te apetece, puedes recolectar más vendas de paño rúnico y traérmelas aquí.",
		},
		[8610] = {
			title = "¡La Horda necesita más vendas de paño rúnico!",
			complete = "Muestras un gran altruismo en tus actos, $n. Y con ello probablemente se salven muchas vidas de quienes van a combatir en Ahn'Qiraj. Gracias y que sepas que cuentas con el agradecimiento de la Horda por tu donación. Si confeccionas o encuentras más vendas de paño rúnico, te ruego pienses en traérmelas aquí.",
		},
		[8611] = {
			title = "¡La Horda necesita filetes de lobo magro!",
			accept = "No estoy aquí plantado solo para pillar un buen moreno, $c. Hay que preparar cosas para la guerra. Si vamos a aplastar a esos bichos en Ahn'Qiraj, tenemos que estar listos, ¡y eso también incluye la comida!$B$BMe tienen recolectando y salando filetes de lobo magro para la guerra que se avecina. Pero me gustaría que te ocuparas de todo esto. Necesito que salgas a matar a unos cuantos lobos, los cocines en filetes de lobo magro y me los traigas aquí. ¿Lo pillas?",
			complete = "Ok, este montón de carne me parece bien. Los salaré y luego los empaquetaré y, con suerte, se mantendrán lo suficientemente frescos como para ser comestibles cuando llegue el momento.$B$BGracias por la contribución, $c. ¿Crees que podrías traerme otro lote?",
		},
		[8612] = {
			title = "¡La Horda necesita más filetes de lobo magro!",
		},
		[8613] = {
			title = "¡La Horda necesita serviolas moteadas!",
			accept = "Buen día pa' pescar, ¿no crees, colega? Eh'tupendo, porque necesitaré un montón de pescao, claro que sí. Los de la Hordame piden que me encargue de recoleh'tá serviola moteada pa' ellos. Dicen que la necesitan pa' preparar la guerra con Ahn'Qiraj. Yo les dije que haría tó lo posible. Así que voy a necesitá ayuda. ¿$C, me ayudas?",
			complete = "Oh sí, esto es lo bueno. L'empaquetaré muy bien pa'que no se desperdicie. Gracias por ayudarme así. Creo qu'eres $gel pescador:la pescadora; número uno por toda esta serviola moteada. Y si pescas y cocinas aún más, tráemelo aquí; ¡M'aseguraré de que todos sepan que l'hiciste!",
		},
		[8614] = {
			title = "¡La Horda necesita más serviolas moteadas!",
			complete = "¡La pesca más guay, $n! Lo que se dice un trabajo bueno y honesto. ¡Y sin espinas! Gracias por conseguir to'a esa serviola moteada, colega. ¡Vuelve pronto si cocinas más!",
		},
		[8615] = {
			title = "¡La Horda necesita salmón asado!",
			accept = "Los preparativos para la guerra de Ahn'Qiraj es una colosal tarea, $c. Todos los materiales que se están recolectando aquí, ya sea metal para las armas o comida, son todos importantísimos. Porque, si llevas varios días sin comer, no tienes fuerzas para levantar el hacha cuando hace falta.$B$BDe ahí que reunamos tantas provisiones como podamos. Estoy recolectando salmón asado, un plato elegido porque alimenta y se conserva muy bien. ¿Puedes ayudarme con esta tarea, $c?",
			complete = "Gracias por demostrar tu interés en ayudar con el esfuerzo bélico, $c. Muchos simplemente ignorarían nuestras necesidades y optarían por obtener ganancias. Pero no cuentan con la gratitud de la Horda, como tú ahora. Sus corazones no están llenos, ya que el tuyo debe estar lleno del orgullo que proviene de la generosidad desinteresada.$B$BNuevamente, te lo agradezco. Si encuentra tiempo para ayudarnos más, antes de que finalicen nuestros preparativos, estaré aquí esperando.",
		},
		[8616] = {
			title = "¡La Horda necesita más salmón asado!",
		},
		[8619] = {
			title = "Alborhondo el Ancestro",
			complete = "Me alegra saber que la gente de estas tierras sigue prestando homenaje a las antiguas razas. Te deseo todo lo mejor, $n, y te ofrezco esta muestra...",
		},
		[8620] = {
			title = "La única receta",
			accept = "Tenía que haberme dado cuenta. ¡Mi archienemigo, el doctor Weavil ha vuelto a las andadas! Y después de tu fracaso en la Cuna del Invierno, ¡el doctor Weavil ha destruido mi libro! ¿Cómo piensas salvar al mundo ahora?$B$B¡La nota que recibí decía que la única copia conocida de Dracónico para torpes: Volumen II fue dividida en 8 partes y arrojada al viento! Si consigues encontrar los capítulos perdidos, utiliza esta encuadernación para reunirlos y vuelve a mí.",
			complete = "¡Fantástico! ¡No puedo creer que hayas pasado por el lío! ¿Eres una especie de máquina? Si fuera yo, probablemente habría dejado que el mundo se derrumbara.$B$BTe doy mi turbante, $gseñor:señora;. Ninguna buena acción debe quedar sin recompensa.",
		},
		[8621] = {
			title = "Los guardapiés de clamatormentas",
			accept = "La magia qiraji es poderosa y antigua. Los más poderosos qiraji empuñan objetos de tal potencia que harían vacilar hasta a un dragón.$B$BTráeme las ataduras de dominancia qiraji y otros componentes menores y crearé un par de poderosas botas para ti.$B$BTe servirán cuando te enfrentes al enemigo.",
			complete = "Lo has hecho bien, $n. Has probado que no eres $gun:una; mortal $gordinario:ordinaria;.$B$BTe los doy con la confianza de que te ayudarán a aplastar al vil qiraji.",
		},
		[8622] = {
			title = "El camisote de clamatormentas",
			accept = "El inmencionable dios antiguo se despierta despacio de su sueño bajo Ahn'Qiraj. El terrible sino que aguarda a Azeroth podría llegar dentro de unos días o unos años; el tiempo nada significa para seres con su poder.$B$BCuando los astros sean favorables, desatará su ira contra todo ser viviente. Debes hallarlo antes de que ocurra y encontrar la forma de poner fin a su existencia.$B$BHazlo y tráeme un pedazo de sus restos. Te concederé una armadura como ningún mortal ha llevado... ¡una armadura hecha para quien ha acabado con un Dios!",
			complete = "No esperaba que volvieras de tu intento, $n.$B$BHas cumplido un destino más grande que el de la mayoría de los seres inmortales.$B$BAl matar a C'Thun, no solo has salvado todo Azeroth, sino que también has inclinado la balanza de los eventos cósmicos más allá de tu comprensión.$B$BAcepta esta coraza como símbolo de la gloria y la carga que vendrán como consecuencia de tus acciones.$B$B¡Que su poder te ayude en los desafíos que te esperan, asesino de dioses!",
		},
		[8623] = {
			title = "La diadema de clamatormentas",
			accept = "Los Emperadores Gemelos... sus incesantes susurros se cobran lentamente un precio sobre mi sano juicio. Se mofan de mí, a sabiendas de que no puedo dar un paso más en sus dominios para salvar a mi hermano Arygos.$B$BTengo visiones de sus monstruosos rostros y su poderosa corona. Pero me vengaré... Transformaré esos símbolos de poder qiraji en unos más adecuados a nuestras necesidades.$B$BTráeme los componentes que necesito, $n. Te daré una celada de poder único.",
			complete = "¡Lo has logrado! Los susurros de los Emperadores Gemelos han cesado.$B$BToma esto como recompensa. El mero hecho de verlo infundirá miedo en los corazones de los Qiraji... les recordará a sus líderes caídos y $gal:a la; mortal que los mató.",
		},
		[8624] = {
			title = "Los leotardos de clamatormentas",
			accept = "¿Deseas demostrar cuánto vales a los de mi especie, mortal? Vale, quizás podemos ayudarnos mutuamente.$B$BEl antiguo gusano de arena, Ouro, es un ser cuyo poder es legendario. Se rumorea que el propio dios antiguo lo creó como una burla a la vida.$B$BSu piel no es natural... gruesa, casi impenetrable aunque flexible, lo que le permite desplazarse velozmente y con la gracia de criaturas mucho más pequeñas.$B$BTráeme una muestra de su piel y otros componentes menores y te fabricaré unas poderosas mallas.",
		},
		[8625] = {
			title = "Las hombreras enigma",
			accept = "Se cuenta entre nosotros que el adorno de la armadura de los hombros que llevan las razas mortales se inspiró en un intento de emular las alas de un dragón.$B$BTráeme las esclavas que llevan los más importantes líderes qiraji y con ellas te forjaré unas hombreras ¡más temidas que las alas del mismísimo Nefarian!",
			complete = "De los materiales que traes y de las escamas de nuestros enemigos Qiraji caídos, te hago estas hombreras, mortal. Que te brinden la protección que necesitas y que al verte infunda miedo en nuestros enemigos.",
		},
