		[8778] = {
			title = "¡La Brigada de Forjaz necesita explosivos!",
			accept = "La Brigada de Forjaz ha solicitado un extraño pedido de componentes... muy volátiles. Reúnelos y llévaselos al señor Bocafuente de la Brigada de Forjaz.",
			complete = "¡Ah, sí! ¡Estos serán útiles! ¡Muchas gracias, $n!",
		},
		[8779] = {
			title = "Materiales de visión",
			accept = "Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.$B$BPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.",
			complete = "Pues sí... ¡serán de gran ayuda! Estos materiales son muy difíciles de conseguir en el desierto, $n. Gracias.",
		},
		[8780] = {
			title = "Refuerzos para armadura para el campo de batalla",
			accept = "El suministro de refuerzos para armadura de la Brigada de Forjaz en el campo de batalla, está empezando a escasear peligrosamente. Consigue un lote de refuerzos y llévaselo a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, justo fuera de Colmen'Zora.",
			complete = "Gracias, se las daré a los muchachos.",
		},
		[8781] = {
			title = "Armas para el campo de batalla",
			accept = "La Brigada de Forjaz ha sido un poderoso aliado en nuestra batalla en Silithus. Por desgracia, perdieron muchos suministros de camino hacia aquí. Consigue un lote de armas y llévaselo a Janela Martillotenaz, está cerca de Colmen'Zora.",
			complete = "¡Oh, excelente! Ya no tendré que escuchar quejas sobre cuchillas desafiladas. Gracias, $n.",
