		[8782] = {
			title = "Suministros para uniformes",
			accept = "La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.",
			complete = "Ah, los necesitábamos. Se agradece tu trabajo, $n.",
		},
		[8783] = {
