			accept = "Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.",
			complete = "Ah, sí. Estos materiales son de excelente calidad. Gracias, $n.",
		},
		[8784] = {
			title = "Los secretos de los qiraji",
			accept = "¡Has descubierto un antiguo artefacto de Ahn'Qiraj! Esta reliquia quizás sea de utilidad para uno de los dragones que se encuentra cerca de la puerta del templo.",
			complete = "Un hallazgo extraordinario, $n. ¡Sencillamente maravilloso! Con esto seguro que lograremos penetrar en las perversas mentes de nuestro enemigo.",
		},
		[8785] = {
			title = "¡La Legión de Orgrimmar necesita mojo!",
			accept = "La Legión de Orgrimmar ha solicitado varios ingredientes muy poco usuales. Dada su situación actual en Silithus, queremos entregarles los suministros tan pronto como podamos. Reúne los materiales y llévaselos a la trol llamada Shai.",
			complete = "Ah, sí. ¡Justo lo que necesitaba! Haré un brebaje especial con esto. ¡Al silítido no le gustará nada!",
		},
		[8786] = {
			title = "Armas para el campo de batalla",
			accept = "La Legión de Orgrimmar ha solicitado unas armas adicionales que no hemos sido capaces de suministrar. Consigue las armas que nos han pedido y llévaselas a Merok Zancada Larga fuera de Colmen'Regal.",
			complete = "Excelente trabajo. Estábamos escasos de esto, $n.",
		},
		[8787] = {
			title = "Refuerzos para armadura para el campo de batalla",
			accept = "Los valientes voluntarios de la Legión de Orgrimmar han venido a Silithus para ayudarnos en nuestra causa. De alguna forma, perdieron sus refuerzos para armadura durante el viaje. Consigue un lote de armaduras y llévaselas a Merok Zancada Larga al campamento de la Legión de Orgrimmar.",
			complete = "Ah, sí... se los distribuiré a las tropas, $n. ¡La Legión de Orgrimmar te lo agradece!",
		},
		[8788] = {
