		[8874] = {
			title = "El Festival Lunar",
			accept = "¡Ha llegado ese momento del año, $n! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.",
			complete = "Te doy la bienvenida, $n. ¿Vienes a unirte a nuestras celebraciones?",
		},
		[8875] = {
			title = "El Festival Lunar",
			accept = "¡Ha llegado ese momento del año, $n! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.",
			complete = "Te doy la bienvenida, $n. ¿Vienes a unirte a nuestras celebraciones?",
		},
		[8876] = {
			title = "Cohetes pequeños",
			complete = "Ah, muy bien. Aquí están tus recetas, $n, y que Elune te bendiga.",
		},
		[8877] = {
			title = "Lanzador de fuegos artificiales",
			complete = "Aquí tienes, $n. Aquí está el esquema para crear un lanzador de fuegos artificiales. Coloca los lanzadores donde desees celebrar y luego da la bienvenida a tus amigos para que se unan a la fiesta.",
		},
		[8878] = {
			title = "Patrones para las fiestas",
			complete = "Aquí están los patrones, $n. Estoy seguro de que el producto de este conocimiento te resultará bastante hermoso.",
		},
		[8879] = {
			title = "Cohetes grandes",
			complete = "Muy bien, acepto estas monedas de linaje. Aquí están tus recetas, $n. ¡Puedes usarlas para difundir la gloria de Elune!",
		},
		[8880] = {
			title = "Tracas de cohetes",
			complete = "Aquí tienes, $n. Toma estas recetas y aprende sus secretos. Te deseo suerte y espero ver tus magníficas creaciones.",
		},
		[8881] = {
			title = "Tracas de cohetes grandes",
			complete = "Gracias, $n. Aquí está la receta para tracas de cohetes grandes. Que tus productos traigan alegría y suerte a todos los que los miran.",
		},
		[8882] = {
			title = "Lanzatracas",
			complete = "Aquí está tu esquema. Estúdialo de cerca y aprende...$B$BBuena suerte, $n. ¡Que tus celebraciones compitan con las del Festival Lunar!",
		},
		[8883] = {
			title = "Valadar Cantoestelar",
			accept = "Ahora que tienes tu Invitación al Festival Lunar, puedes viajar al Claro de la Luna. Allí encontrarás a muchos juerguistas, además, en el poblado del Amparo de la Noche, Valadar Cantoestelar y su hermana Fariel aguardan a los que desean participar en las celebraciones.$B$BViaja al Claro de la Luna a través de La Gran Luz de Luna y habla con Valadar Cantoestelar; ¡mira qué premios puedes ganar durante el festival!",
			complete = "¡$n, $gbienvenido:bienvenida; al Amparo de la Noche, sede de El Festival Lunar! Aunque nuestro poblado está alejado y remoto para las gentes de Azeroth, durante estos días de celebración abrimos nuestros brazos y corazones a todo el mundo.$B$BDisfruta de tu visita, $n, y vuelve a hablar conmigo o con mi hermana cuando estés $glisto:lista;.",
		},
		[8893] = {
			title = "El Superhuevomático",
			complete = "Colocas el huevo de hipogrifo en la máquina. Se oyen una serie de pitidos y de ruidos mecánicos extraños.$B$BParece que el Superhuevomático ha pesado, medido y empaquetado el huevo. ¡Eso sí que es un servicio rápido!",
		},
		[8897] = {
			title = "Queridísima Colara:",
			accept = "Estoy de guardia, pero me preocupa mucho mi novia, Colara. Nos vemos muy poco y eso con suerte, y mírame. Tengo paga de oficial sin rango y cualquier día me llaman a filas.$B$B¿Crees que se olvidaría de mí? Hay muchos hombres en la ciudad. Muchos y ricos.$B$BEl caso es que le he escrito unas líneas y te agradecería que fueras a dárselas.",
			complete = "¡Oh, es tan dulce! Esta es la primera vez que me envía algo. ¿Crees que se está poniendo serio?$B$BColara Heldric? Supongo que suena... Oh, pero me estoy adelantando. Gracias.",
		},
		[8898] = {
			title = "Queridísima Colara:",
			accept = "La última vez que estuve en Ventormenta por trabajo conocí a una pajarita. Me tiene el corazón robado. ¡No dejo de pensar en ella! Quiero enviarle esta carta; la he reescrito una docena de veces.$B$BDespués de tanto esfuerzo, no me fío del servicio de correos.$B$BSi vas en esa dirección, ¿podrías hacerme el favor?",
			complete = "¿Tormek? Ah, sí, el barbudito simpático.$B$B¡Qué bien que se acuerde de mí!",
		},
		[8899] = {
			title = "Queridísima Colara:",
			accept = "¿Cómo describir su belleza? Hace miles de años que se descubrió el lenguaje y no sé por dónde empezar.$B$BSiento que tengo el cerebro derretido.$B$BMejor dejo de darle vueltas. No, mejor lo envío ahora, no sea que venga otro y me la robe.",
			complete = "Nunca antes había recibido algo como esto. ¡Que adorable!",
		},
		[8900] = {
			title = "Queridísima Elenia:",
			accept = "Estaba disgustada, se le veía. Aunque es normal, ¿no?$B$BPero al hablar con ella vi la conexión. Creí que nadie me entendería, pero ella lo hizo.$B$BCuando se lo dije a los demás, se rieron de mí, así que no volví a hablar con ella. Pero la echo de menos. ¿Te importa llevarle esta carta? Quiero asegurarme de que la recibe.",
			complete = "No esperaba que un orco fuera tan elocuente. Por supuesto, nunca antes había tenido la oportunidad de conocerlos. Gracias por traerme esto.",
		},
		[8901] = {
			title = "Queridísima Elenia:",
			accept = "¿Has amado alguna vez? Yo nunca, hasta que hace poco conocí a Elenia, una chica de Entrañas. Ya es raro que mi gente salga con alguien de fuera, y mucho menos una de los Renegados.$B$BPero ahora pienso en ella noche y día.$B$B¿Te importaría llevarle esta carta? Quiero que venga a Mulgore. Espero que acepte.",
			complete = "Qué amables palabras escribe Temma para mí. Pero, por mucho que me conmuevan sus palabras, no puedo considerar el amor de un tauren. En pensamientos, cuerpo y mente somos demasiado diferentes.$B$BEs bueno que no tenga que recibir estos pensamientos suyos en persona. No pude soportar romperle el corazón.",
		},
		[8902] = {
			title = "Queridísima Elenia:",
			accept = "Hace mucho, mucho tiempo, me prometí a Elenia, mi novia de la infancia. Hacía años que no pensaba en ella, pero últimamente sí que me acuerdo.$B$BPuede que, incluso con todo lo que ha pasado, aún tengamos una oportunidad.$B$BSeguro que ella también ha cambiado. ¿Te importa llevarle esta carta? Me da vergüenza entregarla en persona.",
			complete = "Esto trae recuerdos de hace una vida, $n. Elenia Tor. Ese iba a ser mi nombre, sabes. Tendríamos una hermosa ceremonia a orillas del lago. Cuando se jubilara, encontraríamos una granja donde retirarnos.$B$BSueños simples, entonces.$B$BPero si me viera ahora, dudo que incluso vea a Elenia en mí. Solo carne fría y un corazón muerto...",
		},
		[8903] = {
			title = "Amor peligroso",
			accept = "Esta epidemia de amor no es natural. Aquí hay algo raro, temo que pueda suponer una amenaza para la Alianza.$B$BPiénsalo: podría ser una maniobra para neutralizar a los guardias. Hay que hacer algo.$B$BVe a hablar con uno de los guardias de Ventormenta, a ver si también les afecta esta locura.",
			complete = "De modo que estaba en lo cierto. ¡Esto es terrible! ¿Cómo ha podido pasar? Déjame pensar... Tiene que haber alguna razón.",
		},
		[8904] = {
			title = "Amor peligroso",
			accept = "Esta epidemia de amor no es natural. Es repugnante y debilita nuestras defensas, podría ser peligroso para todos nosotros.$B$BYa es bastante molesto ver cuánta gente se ha contagiado con esta tontería. Creo que afecta incluso a los guardias, que deberían ser inmunes a estas cosas.$B$BHabla con uno de ellos para ver si también ha perdido el oremus.",
			complete = "De modo que estaba en lo cierto. ¡Esto es terrible! ¿Cómo ha podido pasar? Déjame pensar... Tiene que haber alguna razón.",
		},
		[8905] = {
			title = "Una propuesta seria",
			accept = "Saludos, $c. Tengo algo que puede interesarte.$B$BDispongo de una armadura muy parecida a las que se usan en tu profesión, pero de mucha mejor calidad. Te cambiaré los brazales por otros normales a cambio de un favor.$B$BLa sangre de los osos y los sables de hielo que viven en Cuna del Invierno tiene propiedades que necesito. Tráeme un frasco grande de sangre, los brazales y un poco de oro. Tus esfuerzos se verán recompensados.",
			complete = "¡Excelente! Entonces realicemos el intercambio. Es difícil desprenderse de esta excelente armadura, pero me temo que no la necesitaré en un tiempo.$B$BSi estás $ginteresado:interesada; en realizar más trabajos para mí, podría estar dispuesta a renunciar al resto de las piezas.",
		},
