		[9015] = {
			title = "El reto",
			accept = "Préstame mucha atención, $n. Para que el estandarte funcione de la forma deseada, tendrás que introducirte en el Círculo de la Ley en las Profundidades de Roca Negra. Deja que el Alto justiciero Pedrasiniestra te condene y clava firmemente el estandarte en el suelo como desafío.$B$BTu víctima no podrá contenerse y saltará a la palestra con el deseo de pelearse contigo. Una vez obtengas aquello que buscas, vuelve con Anthion.",
			complete = "¿Has recuperado parte del medallón, $n?",
		},
		[9016] = {
			title = "La despedida de Anthion",
			accept = "Este amuleto contiene el alma de Valthalak. Nuestra avaricia nos hizo dividirlo en tres partes, pues no sabíamos nada de la maldición que eso nos depararía.$B$BLa única forma de anular el hechizo de Valthalak es volver a reunir las partes del medallón. Dile a Mokvar que Bodley es su único medio de encontrar las partes que faltan. Si hay alguna recompensa pendiente, háblalo con él.$B$BPor una vez, yo voy a descansar en paz. Suerte. ¡Vas a necesitarla!",
			complete = "Esta maldición nos fue otorgada por un simple medallón. Lord Valthalak ciertamente sabe cómo guardar rencor.$B$BNos esforzaremos por encontrar las piezas restantes, con suerte antes de que me encuentre con una muerte prematura. Pero antes de eso, veamos cuál es tu recompensa.",
		},
		[9017] = {
			title = "La despedida de Anthion",
			accept = "Este amuleto contiene el alma de Valthalak. Nuestra avaricia nos hizo dividirlo en tres partes, pues no sabíamos nada de la maldición que eso nos depararía.$B$BLa única forma de anular el hechizo de Valthalak es volver a reunir las partes del medallón. Dile a Mokvar que Bodley es su único medio de encontrar las partes que faltan. Si hay alguna recompensa pendiente, háblalo con él.$B$BPor una vez, yo voy a descansar en paz. Suerte. ¡Vas a necesitarla!",
