		[9228] = {
			title = "Armamento épico de batalla: exaltado con El Alba",
			accept = "Saludos, $gamigo:amiga;. ¿Tienes alguna insignia de El Alba o la Cruzada que quieras canjear por objetos de gran poder?$B$B¡Aquellos con un nivel de reputación exaltado con El Alba reciben nuestros mayores descuentos! Te animo a que compres algo.",
			complete = "Buen día, $N. Fue un placer hacer negocios contigo.",
		},
		[9229] = {
			title = "El destino de Ramaladni",
			accept = "Ramaladni era un guerrero de la Hermandad. Un pupilo del Gran Señor Mograine cuando El Alba ni siquiera existía. Cuando le llegaron las noticias de la muerte de Mograine, se vio invadido por el odio y la ira.$B$BEntiende esto, $n, cuando la ira y la reprensión dominan su espíritu, un hombre deja de ser un hombre. Y se convierte solo en la personificación de las emociones que lo controlan. Así fue como Ramaladni, el espíritu de la Reprensión, entró en Naxxramas buscando venganza... para no salir jamás.$B$BEntra en Naxxramas y averigua qué fue de Ramaladni.",
			complete = "¡Es su anillo! Pero está destruido. ¿No se encontró ninguna otra evidencia de Ramaladni?$B$B<Korfax hace una mueca.>$B$BEsto no augura nada bueno para Ramaladni. Sin embargo, el anillo... podría ser recuperable.",
		},
		[9230] = {
			title = "La garra helada de Ramaladni",
			accept = "Arreglar este anillo va a ser todo un desafío, $n. Verás, estaba hecho con runas que se forman en el interior de las estructuras de la Plaga, como Naxxramas. Y también necesitaría otros materiales, pero tu mayor preocupación debería ser conseguir esas runas heladas. Tráeme lo que necesito y devolveré al anillo su gloria original.",
			complete = "¡El mismo Ramaladni no podría haberlo hecho mejor! Aquí está el anillo, como prometí.",
		},
		[9232] = {
			title = "La única canción que conozco",
			accept = "Te crees $gun héroe:una heroína; de El Alba, ¿eh? ¡Pues yo he visto a nuestros mejores soldados aplastados por la plebe de Kel'Thuzad! ¿Qué podría hacer alguien tan negado en Naxxramas?$B$B<Wilhelm suspira.>$B$BBueno... tampoco es que tenga elección. Eres lo mejor que tengo, así que mejor será que te ayude.$B$BOmarion me dejó una receta. Es la única que conozco... Puedo hacer algunas variaciones de estos pantalones... pero tendrás que traerme los materiales.",
			complete = "<Wilhelm se seca el sudor de la frente>.$B$B¡Esto es un trabajo duro! Disfruta los pantalones, $n. Al menos ahora morirás con un par limpio.",
		},
		[9233] = {
			title = "Vademécum de Omarion",
			accept = "Wilhelm:$B$Bsi estás leyendo esto, quiere decir que he muerto... por fin. Quiero que sepas que mis últimos pensamientos han girado en torno a ti y a tu inabarcable ineptitud como artesano. Por desgracia, quien te lleva este manual tiene incluso peores dotes artesanales que tú.$B$BRespecto al libro: contiene el resto de mis recetas. Atiende al portador del libro en lo que te solicite. Sé que le cobrarás una considerable suma por tus servicios porque, al fin y al cabo, eres un sinvergüenza.$B$BCon todo mi desdén,$B$BOmarion",
			complete = "¡Debía de estar totalmente ido cuando escribió esto! ¡Omarion y yo estábamos unidos como uña y mugre!$B$BPero mira, en cualquier caso, esto me abre nuevas posibilidades, $n. Ahora podré crear más objetos... a cambio de un pequeño honorario, claro está.",
		},
