			accept = "Esta llama, robada del fuego del hogar de Ventormenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que la Liga de Cuentacuentos tenga más información...",
			complete = "¿Dices que esta llama tan viva viene de Ventormenta? Interesante... Ten, aquí tienes tu recompensa. Si vuelves a encontrar algo así, ven a verme.",
		},
		[9331] = {
			title = "Robar la llama de Forjaz",
			accept = "Esta llama, robada del fuego del hogar de Forjaz, te inunda de calor. No conoces este poder tan primitivo, pero puede que la Liga de Cuentacuentos tenga más información...",
			complete = "Esta llama tan vigorosa tiene que venir de Forjaz; es tan vivaz como los propios enanos. Buen trabajo, $n. Ah, si tuviera las demás llamas... Pero no importa; ten tu recompensa.",
		},
		[9332] = {
