		[9338] = {
			title = "Lealtad al Círculo Cenarion",
			complete = "Nos honras, $n. Con tus continuos esfuerzos superaremos todos los obstáculos.",
		},
		[9339] = {
			title = "Una recompensa de ladrón",
			accept = "Esta llama, robada del fuego del hogar de Ventormenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que (NAME) tenga más información...",
			complete = "Hoy te has probado a ti mismo, $n.$B$BAunque tengo poco más para darte, tengo esta corona; un regalo apropiado para $gun conquistador:una conquistadora;. Que ilumine tu camino.",
		},
		[9341] = {
			title = "Tabardo de El Alba Argenta",
		},
		[9343] = {
