		[9362] = {
			title = "Señor de la guerra Krellian",
			accept = "¡No queda mucho tiempo, $n! Mis hechizos de visión han revelado una poderosa fuente de magia. No puedo abandonar la torre, así que te pediría que mataras a la vil criatura que posee este artefacto.$B$BEse patético cretino es conocido como señor de la guerra Krellian y se oculta tras sus guardias en el Templo de Zin-Malor. Redúcelo a cenizas y llévate la concha centelleante que tanto codicia.",
			complete = "Debo decir que esta concha tiene un aura extraño. Parece apropiado que parte de tu recompensa por recuperarlo sea probar sus capacidades mágicas...",
		},
		[9364] = {
			title = "Magia fragmentada",
			accept = "Gracias a mi investigación, he descubierto un propósito único de la concha centelleante.$B$BLlévatela y lanza tu hechizo polimórfico sobre las sirenas Látigo de Ira de Azshara. Si esperas un poco, el aura caótica de la concha las hará escindirse en varios clones más pequeños durante un rato. Mata a estos clones tan rápidamente como puedas y la concha recogerá su esencia.$B$BCuando esté llena, regresa aquí.",
			complete = "¡Espléndido! ¡Espléndido!$B$BAhora podemos recrear esta magia en un nuevo hechizo. ¡Mira!",
		},
		[9365] = {
			title = "Una recompensa de ladrón",
			accept = "Esta llama, robada del fuego del hogar de Ventormenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que (NAME) tenga más información...",
			complete = "Hoy te has probado a ti mismo, $n.$B$BAunque tengo poco más para darte, tengo esta corona; un regalo apropiado para $gun conquistador:una conquistadora;. Que ilumine tu camino.",
		},
		[9367] = {
			title = "El Festival del Fuego",
			accept = "¡Ya ha llegado el solsticio de verano!$B$BCada año, como manda la tradición, se elige a los vigilantes de la llama, que se ocuparán de las hogueras sagradas en nuestras capitales. Aunque habrá hogueras por todo Azeroth, es imperativo que la nuestra sea la más viva para rendir homenaje a la celebración.$B$BDe hecho, tengo una tarea para ti, si no te importa. Aún no sé si las hogueras arden correctamente en todas las capitales. Ve a calentarte junto a cada una de las hogueras; ¡asegúrate de que calienten mucho!",
			complete = "¡Excelente! Me alegra saber que las hogueras arden correctamente este año. Gracias por ir a inspeccionarlas en mi lugar; acepta esto en prueba de mi gratitud.",
		},
		[9368] = {
			title = "El Festival del Fuego",
			accept = "¡Ya ha llegado el solsticio de verano!$B$BCada año, como manda la tradición, se elige a los vigilantes de la llama, que se ocuparán de las hogueras sagradas en nuestras capitales. Aunque habrá hogueras por todo Azeroth, es imperativo que la nuestra sea la más viva para rendir homenaje a la celebración.$B$BDe hecho, tengo una tarea para ti, si no te importa. Aún no sé si las hogueras arden correctamente en todas las capitales. Ve a calentarte junto a cada una de las hogueras; ¡asegúrate de que calienten mucho!",
			complete = "¡Excelente! Me alegra saber que las hogueras arden correctamente este año. Gracias por ir a inspeccionarlas en mi lugar; acepta esto en prueba de mi gratitud.",
		},
		[9386] = {
			title = "Una luz en la oscuridad",
			accept = "Me agrada tu entusiasmo. Si deseas volver a bajar a las profundidades, te recompensaré con sumo gusto.$B$BBusca las hogueras que arden en Stratholme, Scholomance, La Masacre y los salones de Cumbre de Roca Negra. Esperaré tu regreso, $n.",
			complete = "Has probado que no eres del todo inútil, mortal.",
		},
		[9388] = {
			title = "La oscilación de las llamas de Kalimdor",
			accept = "Hoy hay muchas llamas ardiendo en el mundo, $n. Las hogueras más difíciles de mantener son las verdes; hay que vigilarlas constantemente para que no se apaguen. Comprueba si siguen ardiendo las hogueras esmeraldas en Kalimdor, por favor.$B$BEstán en Los Baldíos cerca de Trinquete, en Costa Oscura cerca de La Espada del Maestro, en el bosque de Vallefresno junto al puente cerca de la Avanzada Ala de Plata y cerca del camino a Risco Cortaviento, siguiendo la ruta principal de Sierra Espolón.",
			complete = "Ahhh, todavía arden. Me alegro; no sería bueno que esos fuegos se apagaran antes de tiempo. Lo has hecho bien, $n. Toma esto con mi bendición.",
		},
		[9389] = {
			title = "La oscilación de las llamas de los Reinos del Este",
			accept = "El Festival de Fuego del Solsticio de Verano ilumina la tierra con una miríada de llamas. Hay quien dice que las hogueras verdes son las mejores, porque son las más difíciles de mantener y tienen un color tan particular.$B$BComprueba que siguen ardiendo en los Reinos del Este. Están cerca de Dun Modr, en Los Humedales, cerca de la Aldea Piroleña en el Bosque de Argénteos, en los precipicios junto al faro en los Páramos de Poniente y junto a la torre en ruinas de Laderas de Trabalomas.",
			complete = "¿Qué te han parecido las hogueras esmeralda? Son una visión magnífica, aunque seguro que esperas una recompensa más tangible; aquí tienes.",
		},
		[9415] = {
			title = "Preséntate ante el alguacil Murazul",
			accept = "¿Eres uno de los nuevos reclutas del alguacil Murazul? ¡Claro que sí!$B$B¿A qué esperas? Soldados muy valientes están muriendo en el desierto. ¿No sientes emoción al pensar que te vas a unir a ellos?$B$BAhora vamos, en marcha, y no te quedes $gseco:seca; por el camino.",
			complete = "La Alianza necesita todos las manos capaces que pueda conseguir. La Horda ha estado recibiendo un suministro constante de refuerzos de la parte norte del continente, y ha sido una lucha mantener el ritmo.$B$BDéjame explicarte la situación.",
		},
		[9416] = {
			title = "Preséntate ante el general Kirika",
			accept = "Tú debes ser uno de los nuevos reclutas del general Kirika. Ya era hora de que llegases. El desierto está plagado de cuerpos.$B$BLos enanos han estado recibiendo refuerzos constantemente y no podemos arriesgarnos a perder posiciones en nuestra lucha por los recursos de Silithus.$B$BEl general tiene unas instrucciones para darte. Mi misión no es instruirte, sino solamente encontrarte.",
			complete = "Es bueno que estés aquí, pero no hay tiempo que perder en charlas triviales. Necesitas instrucciones, y luego necesitas salir.$B$B$gAtento:Atenta;.",
		},
		[9419] = {
			title = "Peinando el desierto",
			accept = "Hace poco nos hemos enterado que la Horda ha estado escarbando el desierto de Silithus en búsqueda de recursos, pero poca atención le prestamos entonces. Pensamos que no valdría la pena establecer muchas tropas en este desierto calcinante.$B$BSin embargo, los recursos encontrados son de magna importancia y ahora tenemos que luchar para hacernos con ellos.$B$BSi contamos con tu ayuda, quizás puedas ir al desierto a recuperar la silitista y regresar aquí con ella.",
			complete = "Gracias a la Luz, tuviste éxito.$B$BAhora bien, si solo hubiéramos podido comenzar esto antes, nuestra necesidad no sería tan desesperada. Debemos evitar que la generosidad del desierto caiga en manos de la Horda.",
		},
		[9422] = {
			title = "Peinando el desierto",
			accept = "Desde hace algún tiempo que venimos extrayendo los recursos cristalíferos del desierto de Silithus. Los únicos peligros que encontramos, además de la arena, el calor y el polvo, provenían de criaturas que habitaban allí.$B$BPero ahora la Alianza parece estar interesada en lo que tenemos aquí. Esto se ha convertido en una carrera por capturar los recursos naturales.$B$BNecesito toda la ayuda disponible. Espero poder contar contigo.",
			complete = "Lo has hecho bien, $n. Estos recursos se agregarán a nuestras reservas, y cada migaja que sea para nuestro beneficio no lo es para nuestro enemigo.",
		},
		[9664] = {
			title = "Nuevas avanzadas",
			accept = "$gBienvenido:Bienvenida; a las Tierras de la Peste, $n. Como ya sabrás, los Renegados y sus aliados controlan las tierras al oeste de aquí, muy a nuestro pesar. Los Comandantes de la Alianza han decidido establecer nuevas fortificaciones aquí en el este con el objetivo de presionar al enemigo.$B$BLas torres, abandonadas desde los días de Lordaeron, han de ser recuperadas y reconstruidas. Estas tierras son peligrosas y tu ayuda será más que bienvenida.",
			complete = "Muy bien, $n. Será importante para nosotros mantener estas torres contra futuros ataques, y para eso es posible que necesitemos tu ayuda hasta que se puedan traer refuerzos para asegurar el área.",
		},
		[9665] = {
			title = "Fortalecimiento de nuestras defensas",
			accept = "Algunos agentes de los Renegados descubrieron un plan de la Alianza para establecer nuevas bases en las Tierras de la Peste del Este utilizando las torres abandonadas de la zona.$B$BEs realmente imperativo que no logren establecerse en nuestra frontera del este, por lo que debemos detener esta incursión de la Alianza. Nuestros planes actuales consisten en expulsarlos de las torres que ya hayan conquistado y en ocupar aquellas que tenemos bajo nuestro control para defenderlas de futuras agresiones.",
			complete = "Estas son buenas noticias, $n. Será una lucha constante aquí en las Tierras de la Peste hasta que hayamos rechazado por completo las fuerzas de la Alianza.$B$BHasta ese día, espero contar con tu asistencia continua.",
		},
	},
	esMX = {
		[2] = {
			title = "La garfa de Garrafilada",
			accept = "El poderoso hipogrifo Garfafilada ha sido asesinado, y la garra de la bestia difunta es la prueba de tu victoria. Sin duda, Senani Corazón Atronador, en Puesto del Hachazo, estará interesada en ver este trofeo de tu hazaña.",
			complete = "De lo más impresionante, $n... ¡no puede haber sido un paseo conseguir la garra de Garrafilada! ¡La Caza de Vallefresno te está yendo bien!$B$BGarrafilada lleva muchos años aterrorizando a los peones de los aserraderos cuando se trasladan a Puesto del Hachazo y se cruzan en su ruta. No lo dudes, cuando se corra la voz de que doblegaste a ese monstruo, ¡se escucharán muchas canciones alabando tu valor en los campamentos y aserraderos de todo Vallefresno!",
		},
		[5] = {
			title = "La hambruna de Alterio",
			accept = "¡Llevo semanas escondiéndome en esta ciudad fantasma y no he comido más que larvas y hierbajos! Necesito algo de comida decente. Estoy en disposición de pagar bien.$B$BSi me traes un festín, te pagaré generosamente.$B$BHe oído que el chef Grual del Mesón del Cuervo Escarlata de Villa Oscura hace unos estupendos pasteles de cangrejo oscuro...",
			complete = "Necesitas croquetas de cangrejo, ¿verdad? Bueno, quizás pueda cocinarte algunas...",
		},
		[6] = {
			title = "La recompensa por Garrick Piesuaves",
			accept = "Garrick Piesuaves es un maleante que lleva semanas acosando a granjeros y mercaderes. Ha sido visto en una choza cerca de los viñedos, cruzando el puente al este de la abadía. Tráeme la cabeza de ese villano y podrás quedarte con su botín.$B$BPero ve con cuidado, $N. Garrick anda con una pandilla de matones. Puede que no te sea fácil llegar hasta él.",
			complete = "¡Lo has conseguido! Elwynn te estará muy agradecido por esto. ¡Acabas de ganarte una hermosa recompensa!",
		},
		[7] = {
			title = "La limpieza del campamento kóbold",
			accept = "$N, lo primero que tienes que hacer es limpiar; un clan de kóbolds ha invadido los bosques del norte. Ve y liquida a todos los kóbolds que encuentres; si reducimos sus filas podremos echarlos de Villanorte.",
			complete = "Buen trabajo. Los Kóbolds son ladrones y cobardes, pero en gran número suponen una amenaza más para los humanos de Ventormenta.$B$BTe agradezco lo que has hecho.",
		},
		[8] = {
			title = "Un trato de pícaro",
			accept = "¡Eh, colega! ¿Le harías un favor a un joven hombre que ha combatido contra más zombis y arañas de los que puede contar?$B$BTengo una carta que tiene que llegar a Rémol... Es para una tabernera llamada Renee no sé qué. No creo que importe cómo se apellida, la verdad.$B$BPero el sitio es muy acogedor y está lleno de víctimas de la Plaga que intentan abrirse paso en el mundo. Es el sitio ideal para descansar... si es que necesitas hacerlo. Anímate... si vas, te pagaré bien.",
			complete = "¿Eh? ¿Una carta? ¡Qué bien! Estaba esperando noticias de mi querida madre, que está en Camposanto. Es una santa, eso es lo que es. Me pregunto qué tal estará.$B$B¿Qué? ¿Qué? ¿Sueno demasiado alegre? No te he engañado, ¿eh?$B$BPues me da igual. Y además, tampoco te importa de quién es la carta. ¡Hala! ¡Aire!$B$BVuelve cuando tengas dinero que gastar, holgazán.$B$BYa volverás, ya, cuando necesites descansar después de unos días de aventuras o de alguna estupidez parecida.",
		},
		[9] = {
			title = "Campos de la muerte",
			accept = "¡Mira lo que le ha ocurrido a este lugar! Estas tierras estaban antes en manos de buenos granjeros. Pero los condenados ladrones los han ahuyentado a todos. ¡Pero no a mí! Eso sí, parece que algunos vigías de la cosecha han invadido los campos.$B$BSi estás $gpreparado:preparada; me gustaría que fueras y mataras a 20 de ellos. Vuelve cuando hayas terminado y te pagaré. Si terminas con los de mi campo, puedes limpiar también los campos vecinos.",
			complete = "Buen trabajo amigo. Te has ganado bien tu sueldo. Quién sabe, quizás los Páramos de Poniente vuelvan a ser prósperos.",
		},
		[10] = {
			title = "La redención de Patagolpe",
			accept = "¡Oh, esto es horrible! Envié a mi mejor ayudante, el perito adjunto Patagolpe, al desierto situado al sudeste de aquí, una zona que se conoce como Sima Abierta. Bien, pues ha desaparecido y su último informe contenía más información acerca de esos extraños bichos que había visto por la zona. ¿Es posible que ya hayan infestado dos grandes regiones del desierto?$B$BPor favor, ¡necesito que vayas a Sima Abierta en busca de Patagolpe! Y si no lo encuentras a él, al menos a ver si aparece su equipo de análisis. Me temo que pueda ser lo único que quede de ese pobre chico.",
			complete = "El joven Patagolpe era un buen goblin. Esperemos que, gracias a los datos registrados en su equipo de análisis, su muerte no haya sido en vano.$B$BParece que ahora el problema con estos bichos está en nuestras manos. Son demasiado astutos y las investigaciones realizadas hasta el momento señalan la posibilidad de que estén controlados por una tercera persona. Si eso es cierto, ¡no le espera nada bueno ni a Gadgetzan ni al desierto en general!",
		},
		[11] = {
			title = "Recompensas por los gnolls Zarparrío",
			accept = "En las fronteras del Bosque de Elwynn se han avistado gnolls, unas criaturas salvajes que seguramente no están allí por trabajo. Un grupo enorme de ellos, uno más numeroso del que podemos contener solos, ha infestado los bosques que hay al sur de la torre de vigilancia. Otro grupo ha infestado las áreas cercanas al Lago del Hito, al este.$B$BEl ejército de Ventormenta elogiará a quienquiera que le ayude a matarlos. Tráeme sus bandas gnoll pintadas como prueba de tu hazaña.",
			complete = "¡Has estado muy ocupado! Muchas gracias, $n.",
		},
		[12] = {
			title = "La Milicia Popular",
			accept = "La Milicia Popular solo tiene un objetivo: defender las tierras de los Páramos de Poniente y traer la paz a nuestro entorno. Por desgracia, el precio de la paz suele pagarse en sangre.$B$BSegún el informe de uno de mis exploradores, una banda de tramperos Defias ha sido vista cerca de la Mina de Jango al noroeste de aquí, en La Granja de Molsen y en la Plantación de Calabazas de Cejade. Si quieres unirte a nuestras filas, acaba con 15 tramperos Defias y con 15 contrabandistas Defias y vuelve a verme.",
			complete = "Bien hecho, $n. Mi explorador ha sido testigo de tus hazañas. Estás dando muy buenas pruebas de tu valía.",
		},
		[13] = {
			title = "La Milicia Popular",
			accept = "Una banda de despiadados saqueadores Defias ha sido vista saqueando la Mina de la Costa del Oro, el Arroyo de la Luna y la Hacienda de Alexston. La Milicia Popular no tolerarán ese comportamiento. Avisa inmediatamente, $n, y haz conocer la presencia de la Luz en los Páramos de Poniente.$B$BLa Mina de la Costa del Oro está cerca de la costa, al oeste de la torre. El siguiente paso de tu instrucción consistirá en acabar con 15 de esos saqueadores Defias y con 15 despojadores Defias.",
			complete = "Hasta ahora tus hazañas no han dejado de probar tu valía para las Milicias del Pueblo.",
		},
		[14] = {
			title = "La Milicia Popular",
			accept = "Algunos Defias nos han esquivado. Según informa mi mejor explorador, los Defias han estado saqueando y expoliando el campo, hasta la parte sureste de los Páramos de Poniente. Creemos que se están ocultando en Las Colinas Afiladas, planeando sus siguientes pasos. Acaba con esos miserables en nombre de La Milicia Popular",
			complete = "Cuando dejé las tierras malditas de Lordaeron, regresé para encontrar mi patria sumida en una situación desalentadora. Pero aún hay esperanza para los Páramos de Poniente. Has demostrado tu valor en la batalla, y es evidente que sirves con honor a nuestra causa. Me es por ello un gran honor ordenarte como miembro de Las Milicias del Pueblo. Que la Luz guíe siempre tu camino.",
		},
		[15] = {
			title = "Investiga la Mina del Eco",
			accept = "$N, mis exploradores me dicen que la infestación kobold es peor de lo que habíamos pensado. Un grupo de trabajadores kóbold ha acampado cerca de la Mina del Eco, al norte.$B$BVe a la mina y expúlsalos. Sabemos que hay al menos 10 de ellos. Mátalos, comprueba si quedan más y ven a verme.",
			complete = "No me gusta que haya kobolds en la mina; eso no puede ser bueno. Bien, acepta esto como pago, y vuelve a hablar conmigo cuando quieras; puede que tengas que volver a la mina...",
		},
		[16] = {
			title = "Dale de beber a Gerard",
			complete = "¡Gracias, $n! Y vuelve si quieres hacer otro intercambio.",
		},
		[17] = {
			title = "Componentes de Uldaman",
			accept = "Me enteré sobre una especie de planta recientemente descubierta llamada setas magenta. Crecen en cúmulos, en las profundidades del sitio de excavación de Uldaman. Puede que estén en otros lados, pero es el único lugar donde sé que están por ahora. Quiero estudiar sus usos potenciales en la alquimia, y ahí es donde entras tú.$B$BEncuentra los cúmulos de setas magenta y tráeme una docena. Ten cuidado, es posible que los cúmulos lancen esporas venenosas si los molestas.$B$BHaz esto por mí, ¡y te prepararé algunos de mis famosos elíxires restauradores!",
			complete = "¡Has hecho un buen trabajo otra vez, $n! Esto va a ser muy interesante.$B$BY como te prometí, aquí tienes uno de mis mejores elixires vigorizantes.$B$BSi te interesa la alquimia, puedo ofrecerte otros trabajos. En todo caso, te agradezco tu ayuda.",
		},
		[18] = {
			title = "Hermandad de ladrones",
			accept = "Hace poco llegó una banda de maleantes a Villanorte. Se hacen llamar la Hermandad Defias; se les ha visto cruzando el río hacia el este.$B$BNo sé qué están haciendo, ¡pero seguro que no es nada bueno! Tráeme sus pañuelos y te daré un arma como recompensa.",
			complete = "De vuelta con algunos pañuelos, ya veo... El Ejército de Ventormenta te agradece tu ayuda.",
		},
		[19] = {
			title = "Tharil'zun",
			accept = "Hay avanzados y renegados Roca Negra tendiendo emboscadas entre aquí y el Fuerte de Petravista. El jefe de los avanzados se llama Tharil'zun y lo queremos muerto. ¡Tráeme su cabeza!",
			complete = "Era fuerte y cruel; seguro que no fue fácil derrotarlo. Gracias; aquí tienes tu recompensa.",
		},
		[20] = {
			title = "La amenaza de los Roca Negra",
			accept = "Los orcos Roca Negra llegaron desde Las Estepas Ardientes y han invadido el Fuerte de Petravista, al norte de aquí. Andan merodeando por el norte de Villa del Lago y tienen a los ciudadanos encerrados como a ganado.$B$BLibra a Villa del Lago de esta amenaza. Mata a los orcos y tráeme 10 hachas desgastadas por la batalla como prueba.$B$BAunque nos amenazan desde el norte, sabemos que hay más al sureste de Crestagrana. Si los encuentras, mátalos también.",
			complete = "Ahora hay muchos menos orcos de los que ocuparse; gracias.",
		},
		[21] = {
			title = "Refriega en el Eco",
			accept = "Ha quedado demostrado que tenemos que purgar la Mina del Eco. Vuelve allí y ayuda a eliminar a los kóbolds.$B$BDate prisa, $N. Cuanto más tiempo dejemos a los kóbolds en la mina, más nos costará expulsarlos de Villanorte.",
			complete = "Has vuelto a ganarte mi respeto y la gratitud del ejército de Ventormenta. Enviaré a otro equipo para ver si quedan kobolds en la mina; para ti tengo otras misiones.",
		},
		[22] = {
			title = "Pastel de hígado de dentosangre",
			accept = "Las cebollas están peladas. El ajo machacado. La corteza está tostada. Las hierbas de eneldo picadas. ¡Lo único que me falta para mi famosa empanada de carne son 8 hígados de dentosangre!",
			complete = "¡Son perfectos, $n! Muchas gracias. El granjero Saldean y yo vamos a darnos un gran festín. Toma, esto es para ti, por todo el trabajo. No pensarías que iba a dejar que un $c como tú se fuera con hambre, ¿eh?",
		},
		[23] = {
			title = "La pata de Ursangous",
			accept = "La pata del imponente oso Ursangous es tu trofeo por esta parte de la Caza de Vallefresno. En la pata tiene una pequeña media luna, cuyo significado es un misterio.$B$BDeberías llevársela a Senani Corazón Atronador en Puesto del Hachazo para demostrarle que has derrotado a la poderosa criatura y completado esta parte de la cacería.",
			complete = "¡Ah, la zarpa de Ursangous! Tu talento me impresiona, $c; muchos han perecido bajo su ira. La media luna de su zarpa no deja lugar a dudas, los elfos de la noche que merodean por Vallefresno lo amaestraron. Ursangous es... era el oso más poderoso que podías encontrarte por estos lares. Derrotar a semejante criatura es toda una muestra de tu empeño y determinación.$B$B¡Tus antepasados estarían orgullosos de ti!",
		},
		[24] = {
			title = "La cabeza de Shadumbra",
			accept = "El otrora ágil Shadumbra ahora yace inmóvil mientras proclamas tu victoria. La cabeza del sable de la noche muerto es un trofeo adecuado para esta batalla de la Caza de Vallefresno. Senani Corazón Atronador en el Puesto del Hachazo seguramente deseará ver este trofeo para otorgarte el crédito correspondiente a esta etapa de la Caza de Vallefresno.",
			complete = "¡Una victoria para $n en la Caza de Vallefresno! Muy bien, la cabeza de Shadumbra es sin lugar a dudas un trofeo apropiado para atribuirse tan impresionante lucha.$B$BLa ferocidad de Shadumbra era de sobras conocida en toda la avanzada. Cualquier viaje hacia el oeste, especialmente a pie para salir de La Ensenada de Zoram, conllevaba mucho riesgo debido a este tigre. Gracias a ti, este peligro ya no existe.",
		},
		[25] = {
			title = "Paralización en Espolón",
			accept = "Si quieres ser de utilidad, ¿por qué no haces algo para solucionar la situación cerca de Paso del Espolón?$B$BLos transportes entre Vallefresno y Espolón no están en funcionamiento porque el lago cobra vida y ataca a todo lo que se acerca... personas incluidas. Lo que sería más práctico que simplemente aporrear a esos elementales de agua sería que alguien explore la glorieta del Lago Mystral, la que tiene una buena vista de la avanzada de la Alianza allí.$B$B¿Quieres hacer algo útil?",
			complete = "Sí, he oído que alguien había abierto el lago como un demonio de polvo por Los Baldíos. Parece que podríamos establecer un punto de observación por allí para mantener un ojo sobre nuestros amigos de la Alianza. Bueno, eso si conseguimos mantenerlo al nivel mínimo...$B$BParece que has resultado ser bastante útil después de todo; ahora el transporte entre este lugar y Espolón deberían ser menos accidentados. Aquí tienes, te lo has ganado.",
		},
		[26] = {
			title = "Una lección que aprender",
			accept = "$N, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $gun valioso protector:una valiosa protectora; de la naturaleza.$B$BHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.",
			complete = "Saludos, joven $c; ha llegado el momento de que conozcas nuestra forma acuática. Es aquella que te permite moverte libre e indefinidamente por el agua. Encontrarás este aspecto como una herramienta útil y una bendición ... pero es algo que debes ganar antes de dominarlo.$B$BTe enfrentarás a dos pruebas que superar. La primera pondrá a prueba tu capacidad para trabajar en el agua y bajo presión. La segunda pondrá a prueba tu determinación para comprender los aspectos de la forma en sí.$B$BEstá $gpreparado:preparada;, ya que ha llegado el momento de la prueba.",
		},
		[27] = {
			title = "Una lección que aprender",
			accept = "$N, he seguido tus progresos con gran gozo. Sin duda te estás convirtiendo en $gun valioso protector:una valiosa protectora; de la naturaleza.$B$BHa llegado el momento de que aprendas más sobre una de las formas animales con las que Cenarius nos ha bendecido. Una forma que podemos adoptar y que nos permite controlar el agua. Tendrás que viajar al poblado Amparo de la Noche, que está en Claro de la Luna, y hablar con Dendrita Rafagaestelar del Círculo Cenarion. Él será tu guía.",
			complete = "Saludos, joven $c, ha llegado el momento de que conozcas nuestra forma acuática. Se trata de una técnica que te permitirá moverte libre e indefinidamente por el agua. Encontrarás muy útil este aspecto y pronto te darás cuenta de que es una bendición. Pero debes ganártelo antes de dominarlo...$B$BDeberás superar dos pruebas. La primera probará tu capacidad para trabajar en el agua bajo presión. La segunda, tu resolución y tu comprensión de los aspectos de la forma acuática.$B$BPrepárate pues el momento de la prueba se acerca.",
		},
		[28] = {
			title = "La prueba del lago",
			accept = "En tu primera prueba, debes ir a las profundidades del Lago Elune'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.$B$BTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.$B$BSuerte, $N.",
			complete = "¡$gOtro:Otra; $c que completa la Prueba del Lago! Buen trabajo.$B$BMe llamo Tajarri y tengo el honor de ser el guardián de este santuario, un tributo a la conservación de la naturaleza y su equilibrio. Este adorno señala la importancia de este lugar para el Círculo Cenarion.",
		},
		[29] = {
			title = "La prueba del lago",
			accept = "En tu primera prueba, debes ir a las profundidades del Lago Elune'ara y encontrar un adorno de altar. Se descompone rápidamente, por lo que deberás ir inmediatamente al Santuario de Remulos. Coloca el adorno en el altar y habla con Tajarri; es una de las celadoras más apreciadas de Claro de la Luna.$B$BTienes un tiempo limitado para completar la tarea y es probable que tengas que competir con otros druidas en busca de adornos. Necesitarás toda tu destreza mental y física.$B$BSuerte, $N.",
			complete = "¡$gOtro:Otra; $c que completa la Prueba del Lago! Buen trabajo.$B$BMe llamo Tajarri y tengo el honor de ser el guardián de este santuario, un tributo a la conservación de la naturaleza y su equilibrio. Este adorno señala la importancia de este lugar para el Círculo Cenarion.",
		},
		[30] = {
			title = "La prueba del león marino",
			accept = "En tu segunda prueba debes encontrar las dos mitades del colgante del león marino. Una obtiene su poder de la agilidad del león marino cuando se desliza en el agua, la otra lo obtiene de su increíble capacidad de resistencia. Los druidas se alimentan de ambos rasgos para asumir su forma acuática.$B$BHabla con la gente de Claro de la Luna para averiguar dónde están las mitades y tráemelas para que las unamos. Luego llevarás el colgante a Dendrita Rafagaestelar.",
			complete = "Enhorabuena por completar la Prueba del León Marino, $n.$B$BHas aprendido que necesitas agilidad y resistencia para moverte en armonía en el agua, y que para ello debes abrazar el aspecto del león marino.$B$BEstas lecciones te serán muy útiles cuando ganes tu forma acuática.",
		},
		[31] = {
			title = "Forma acuática",
			accept = "Has completado tu formación para la adopción de una forma acuática. Ve a ver a tu instructor, Turak Tótem de Runa, a Cima del Trueno. Enséñale el colgante y demuéstrale que puedes aprender lo que tenga que enseñarte. Él completará tu formación para que puedas fundirte con el agua.$B$BBuena suerte, joven druida. Volveremos a vernos.",
			complete = "Impresionante, $n; tus antepasados pueden estar orgullosos. Me llena de alegría poder enseñarte tu Forma acuática.$B$BAcepta esto como premio por tus logros en las dos pruebas; espero que te ayude en tu objetivo de proteger la naturaleza y su equilibrio.",
		},
		[32] = {
			title = "La sublevación de los silítidos",
			accept = "Aquí tienes el informe. Te ruego que se lo entregues a alguien que tenga conocimientos de este tema.$B$BConozco a un trol erudito llamado Zilzibin Tambor Sabio que ha dedicado mucho tiempo al estudio de los seres vivos que solo se encuentran en Azeroth. ¡Es un historiador de los pies a la cabeza! Entrégale este informe si quieres que te ayude a entender a qué te enfrentas y el modo de detener esta amenaza. Vamos a necesitar toda la ayuda que podamos conseguir.$B$BZil vive en una casa en el segundo nivel de La Calle Mayor en Orgrimmar.",
			complete = "Este informe... Yo ya he visto antes a estas criaturas. Picoflojo ha hecho muy bien al enviarte aquí con el informe.$B$BEstas criaturas destruirán el Desierto de Tanaris con rapidez. Se trata de una de las mayores amenazas a la que jamás nos hemos enfrentado. Familiarízate con este nombre, $n: silítidos. Los insectos de los que habla este informe son los silítidos y representan uno de los mayores peligros a los que tanto la Horda como la Alianza se enfrentan.$B$BSi hubiéramos sido capaces de descubrirlo antes...",
		},
		[33] = {
			title = "Lobos en la frontera",
			accept = "¡Detesto a esos asquerosos lobos grises! Pero los filetes de lobo son tan deliciosos...  Tráeme carne de lobo dura y te la cambiaré por algo que te será útil.$B$BPuedes cazar a los lobos grises y los lobos jóvenes que merodean por la región de Villanorte.",
			complete = "Era una tarea amarga, $gamigo:amiga;, pero has cumplido tu parte del trato.$B$BTengo algunas cosas que quizás te interesen, ¡elije lo que quieras!",
		},
		[34] = {
			title = "Una visita poco grata",
			accept = "Han vuelto a arrasar mi jardín, y sé quién es el responsable. Es ese maldito jabalí, ese al que el alguacil Marris llama Panzallena.$B$BYa es demasiado tarde para replantar narcisos. Ese puerco ha devastado mis flores. ¡Acaba con ese bicharraco! Si me traes un colmillo suyo, te recompensaré. Dicen que anda husmeando por los campos que hay al suroeste de Villa del Lago, pero de vez en cuando viene a mi jardín.",
			complete = "¡Por fin! Gracias, $n, me has hecho un favor enorme. ¡Este año el jardín estará precioso!",
		},
		[35] = {
			title = "Más preocupaciones",
			accept = "Si te preocupa que los rumores sobre los múrlocs sean ciertos, hay algo que puedes hacer: viaja al puente oriental de Elwynn y habla con el guardia Thomas. Ha estado emplazado en el puente durante la última semana, así que debe saber cuál es el estado de la situación.$B$BTráeme su informe.",
			complete = "Sí, los múrlocs se han asentado a lo largo de los ríos del este de Elwynn. No sabemos por qué están ahí, pero son agresivos y, además, ¡son hasta un poco inteligentes!",
		},
		[36] = {
			title = "Estofado de los Páramos de Poniente",
			accept = "Nunca pensé que llegaría el día en el que tuviera que dejar la granja. Pero los campos están llenos de ladrones y es demasiado peligroso que sigamos aquí. En cuanto el granjero Cejade consiga arreglar el carro nos pondremos en marcha.$B$B¿Podrías hacerme un favor? Deja que te escriba mi receta del estofado de los Páramos de Poniente. Por favor, llévasela a Salma Saldean, estará en la Finca de Saldean, nada más pasar la bifurcación del camino.",
			complete = "Esa Verna siempre fue una muchacha encantadora. La echaré de menos en los Páramos de Poniente pero, entre tú y yo, es una chica de ciudad y en Ventormenta estará muy a gusto. ¡Pero basta de chácharas! ¡Tenemos que hacer el estofado de los Páramos de Poniente!",
		},
		[37] = {
			title = "Encuentra a los guardias perdidos",
			accept = "Hace unos días mandé a dos guardias, Rolf y Malakai, a investigar el río. Aún no han regresado. Para completar mi informe necesito saber qué les ocurrió a esos hombres.$B$BViaja al norte a lo largo del río y encuentra a mis guardias... o lo que quede de ellos.",
			complete = "Aunque el cuerpo ha sido saqueado, cerca de él hay un medallón que nadie ha recogido. Tiene una inscripción: \"Lacayo Malakai Roca\".",
		},
		[38] = {
			title = "Estofado de los Páramos de Poniente",
			accept = "¡Ayúdame a preparar el estofado de los Páramos de Poniente! Vuelve con estos ingredientes: $B $B 3 piezas de carne fibrosa de buitre $B 3 morros de dentosangre $B 3 ojos de múrloc $B 3 okras",
			complete = "¡Esa okra servirá para dar algo de consistencia al caldo, perfecto! Ahora solo nos falta por añadir carne fibrosa de buitre, unos cuantos ojos de múrloc y esos deliciosos morros de dentosangre... ¡y ya estará listo! Por toda tu ayuda, $n, ¡quiero que te lleves el primer lote de estofado de los Páramos de Poniente!",
		},
		[39] = {
			title = "Entrega el informe de Thomas",
			accept = "Habla al alguacil Dughan de la muerte de Malakai y Rolf, y después infórmale de que no podrá contener a los múrlocs del este de Elwynn con sus tropas.$B$BSé que no tenemos bastantes soldados, quizás Dughan pueda encontrar alguno más.",
			complete = "Mmm, son noticias preocupantes. Nuestras defensas ya están bastante mermadas y, ahora que hemos perdido a Rolf y Malakai a manos de esos murlocs, estamos incluso peor.$B$BSi las cosas no mejoran, para el final de la semana habrá un combate en Villadorada.",
		},
		[40] = {
			title = "Un peligro con olor a pescado",
			accept = "¡Hay una nueva amenaza en el Bosque de Elwynn, $N! ¡Los múrlocs están subiendo por los ríos al este de Elwynn, ahuyentando a los peces y atacando a las buenas gentes de allí!$B$BAvisé al alguacil Dughan, pero le preocupan más los gnolls y los bandidos. No cree que los múrlocs sean una amenaza.$B$B¡Por favor, $N! ¡Habla con Dughan y convéncele de que envíe más tropas al este!",
			complete = "Sí, hablé con Remy. Lo respeto como mercader, aunque los informes de los múrlocs del este han sido, por decirlo suavemente, demasiado superficiales.$B$BTomo nota de tu preocupación pero, si no recibo un informe militar sobre la amenaza múrloc, no puedo enviar más tropas al este.",
		},
		[45] = {
			title = "Descubre el destino de Rolf",
			accept = "En tu exploración del área encuentras huellas palmeadas que llevan al este por la costa del Lago del Hito. Hacia el este, en la distancia, adivinas la silueta de una aldea múrloc.$B$BQuizás Rolf encontró allí su destino...",
			complete = "Alrededor del cuello del cadáver hay un medallón de metal con una inscripción que reza: \"Lacayo Rolf Hartford\".",
		},
		[46] = {
			title = "Recompensas por los múrlocs",
			accept = "El ejército de Ventormenta ha puesto precio a la cabeza de los rondadores y batidores múrloc de Elwynn. Mátalos y tráeme sus aletas. El ejército de Ventormenta te recompensará bien.$B$BLos múrlocs han construido una aldea en el Lago del Hito, al norte de aquí, y otra en el sur, donde se bifurca el río.",
			complete = "¿Tienes las aletas? ¡Genial! El alguacil Dughan está ansioso por recibir noticias del estado de la situación en Elwynn y me gustaría decirle que empezamos a controlar la situación.$B$BTus acciones han contribuido a que sea posible.",
		},
		[47] = {
			title = "Intercambio de polvo de oro",
			accept = "Los kóbolds de esa zona a veces llevan polvo de oro. Me vendría muy bien. Consígueme un montón de polvo de oro y te pagaré el mejor precio de la ciudad, ¡el mejor!$B$BPuedes encontrar kóbolds en la Mina Abisal, al sur, y también alrededor de la Cantera de Jaspe, al noreste.",
			complete = "Gracias por el Polvo de oro, $n. Aquí tienes tu dinero y... este detalle de mis socios. Puede que lo encuentres útil... útil.",
		},
		[48] = {
			title = "Dulce ámbar",
			accept = "Allá en el sur donde las zarzas irritan$BHay un manantial de aguas umbrías$BPura como la sagrada Hija de la Luz$BAgua del manantial sagrado me traerás tú.",
			complete = "¡Hip! ¡Jo jo!",
		},
		[49] = {
