		[621] = {
			title = "El secreto de Zanzil",
			accept = "Zanzil el Desarraigado mora con sus seguidores en las Ruinas de Jubuwal y Aboraz, al noreste de Bahía del Botín. Ha sido exiliado por su tribu. ¿Por qué? Bueno...$B$BZanzil es capaz de doblegar las mentes de otros, y sus líderes le temen. Usa una mezcla de plantas de la selva en sus seguidores para quitarles la voluntad y fortalecer sus cuerpos.$B$BSu mezcla sería muy útil para quienes desean controlar a otros.$B$BTráeme muestras de su mezcla y yo le encontraré un buen uso.",
			complete = "Ah, muy bien. Aquí tienes lo tuyo.$B$BY un poco más... por tu discreción.",
		},
		[622] = {
			title = "Regresa junto al cabo Kaleb",
			accept = "Mientras no estabas arreglé la olla. Incluso añadí un pitorro de vapor extra, ¡y mira! Hay una nueva hoja en el fondo que puede cortar incluso huesos de piernas.$B$BSí, sí, la olla mecánica de Krazek, es una herramienta que satisface al cocinero en un 100%. Seguro que su dueño estará satisfecho.",
			complete = "¡Funciona! Esto es fantástico, ahora podré ponerme a preparar la cena. Muchísimas gracias, $n.$B$BEspero que no tuvieras problemas en la Bahía del Botín. Ese lugar puede ser bastante peliagudo y... he oído rumores que dicen que, algunas veces, los goblins se llevan a marineros borrachos a sus barcos de esclavos... quién sabe dónde... para hacer quién sabe qué...",
		},
		[623] = {
			title = "Tallos de juncos akiris",
			accept = "$N, ya que tás aquí, he recibío un mensaje de Groy cuando no estabas. Dijo que estaba satisfecho con el último cargamento y que tiene un cliente que quiere más de esa cosa ahora mismo.$B$BYo no voy a Theramore hasta dentro de una semana, pero si tú quieres hacer el viaje, podrías llevar los juncos por mí.$B$B¿Te apetece una aventura? Sabes dónde está el Marjal Revolcafango, ¿no? Yo iría con cuidado, Theramore puede ser peligroso dependiendo de quién seas...",
			complete = "¡¿Qué?! Tengo muchas cosas mejores que hacer que hablar con tipos como tú, $c. Haz que merezca la pena, o lárgate de aquí.$B$B¿De acuerdo? Bloads te ha enviado, ¿eh? A ver, ¿qué tienes pa mí?$B$B<El corsario Groy examina el paquete con atención>$B$BNo está mal, nada mal. Con otro de estos, mi cliente estaría mu contento.$B$BSupongo que tu próxima pregunta va a ser sobre el dinero, ¿eh, $c? ¡Pues claro que sí!$B$BToma, te voy a dar unas monedas y un consejo: largo de mi muelle.",
		},
		[624] = {
			title = "El enigma de Cortello",
			accept = "Hay un puente ornamentado y con mucho tránsito$BAl este de Viento Muerto y al sur de Crestagrana$BBajo el puente te espera algo$BAlgunos lo llaman un consejo otros, una pista$BAllí te esperará eternamente$BViendo pasar el tiempo en el Pantano de las Penas",
			complete = "El pergamino húmedo contiene la siguiente pista...",
		},
		[625] = {
			title = "El enigma de Cortello",
			accept = "Te espera una tierra muy lejana, en Kalimdor$BDonde el peligro ha destruido las esperanzas y los destinos$BAl este de Los Baldíos el tiempo es severo$BLa penumbra y el peligro imperan en el Marjal Revolcafango$BPero allí hay una pista, para aquellos dispuestos a aceptar el desafío$BEsperando ser encontrada... en una cueva... al suroeste",
			complete = "Debes encontrar un pergamino mohoso.",
		},
		[626] = {
			title = "El enigma de Cortello",
			accept = "¡A Lordaeron! La gran tierra de confusión$BDonde valientes soldados juegan con la muerte$BEncuentra tu camino a través del gran disturbio$BAllí encontrarás el final de esta misión$BJunto a la costa de las Tierras del Interior, en la base de las cataratas$BDesde las profundidades del agua, te llama tu tesoro.",
			complete = "Abres el cofre y en su interior encuentras...",
		},
		[627] = {
			title = "Un favor a Krazek",
			accept = "Hay una cueva en la montaña, en el Cañón Mostacho Seco, al norte de las Tierras Altas de Arathi. En esa cueva hay un extraño mineral: sangrita. La sangrita de esta cueva no tiene una calidad superior, pero incluso la sangrita de baja calidad es valiosa... para aquellos que sepan usarla.$B$BMe gustaría conseguir sangrita.$B$BArreglaré tu olla mecánica, pero mientras lo hago... tráeme algunas muestras de sangrita. Si me traes las suficientes, te daré una bonificación.$B$BOh, y si no tienes la habilidad necesaria para extraerla... ¡encuentra a alguien que la tenga!",
			complete = "¡Menuda maravilla! Me has hecho un gran favor.$B$BAquí tienes tu pago...",
		},
		[628] = {
			title = "Borceguí",
			accept = "Ahora que hemos terminado el interior, lo único que queda es añadir la capa exterior. Para esto, solo utilizo la mejor piel de crocolisco mayor. Duran más y son un lienzo perfecto para añadir los diseños y dibujos que completan el estilo borceguí de Drizzlik.$B$BPero no es fácil encontrar la piel perfecta, la única que podría servir es la piel de un crocolisco marino mayor. Los crocoliscos mayores solo salen fuera para defender a los otros crocoliscos marinos, así que quizás tengas que matar a unos cuantos para que salgan.",
			complete = "¡Genial! Gracias a tu ayuda, tendré este pedido terminado y se lo enviaré al director Riddlevox en el próximo barco que salga para Villabajo. ¡Incluso antes de la hora prevista!$B$BHe hecho algunas de más, así que, por tus esfuerzos, puedes quedarte con un par. Regalo de Drizzlik.$B$BNo hay nada que supere el estilo borceguí de Drizzlik !",
		},
		[629] = {
			title = "El Arrecife Mortal",
			accept = "Mucho tiempo atrás, un gran temblor de tierra sumergió una antigua ciudad trol bajo las aguas de La Costa Salvaje, al noroeste. Llamamos a ese lugar El Arrecife Mortal, ya que ahora los múrlocs residen en las ruinas de la ciudad, atacando a todo el que se acerca.$B$BEn esas ruinas hay una antigua tablilla que narra la vieja fábula de Gri'lek, un héroe de leyendas trol. La fábula es sagrada para la tribu Lanza Negra y, aunque la tablilla es muy grande como para moverla, quiero un fragmento para consagrarlo en nuestro nuevo hogar de Orgrimmar.",
			complete = "Y eso está bien. Cuando vuelva a Orgrimmar, colocaré este fragmento en un lugar sagrado. Nos recordará el poder y el honor de Gri'lek.$B$BGracias, $n. Tus actos marcan una creciente amistad con la tribu Lanza Negra.",
		},
		[630] = {
			title = "Mensaje en una botella",
			accept = "$N, pongo mi fe en ti y en cualquiera que te ayude a liberarme. Mi secuestrador es el gran Cieloleno rey Mukla. Domina a las bestias de esta isla que me tienen aquí contra mi voluntad con ayuda de una cadena. Si puedes matarle y encuentras la llave de estos grilletes, estaré en deuda contigo eternamente.$B$BA menudo puedo oírle en la parte sureste de la isla, pero ten cuidado. Hay que tomarle muy en serio.",
			complete = "$n, me has salvado de un gran deshonor. Si estuviera en mis manos, te ofrecería un lugar en mi tribu. Pero, por ahora, solo puedo ofrecerte esto por el coraje y la nobleza que has mostrado.",
		},
		[631] = {
			title = "El Puente Thandol",
			accept = "Se oyó el estruendo de una enorme explosión por todas las colinas. '¡Fue horrible, créeme!$B$BLos buenos soldados murieron en la defensa el Puente Thandol. Largatrenza dice que nos vengaremos de los Hierro Negro en un santiamén.$B$BPero estamos en un mundo lleno de dolor y no veo ningún refuerzo. Largatrenza envió a Herrumbra a explorar el puente del Este para ver si podemos ganarlo.$B$BEso fue hace días. Con Dun Modr bajo asedio no tenemos hombres suficientes para ir a buscarlo.$B$BQuizás tú puedas ayudarnos...",
			complete = "Registras el diminuto cadáver enano. Grabado en el yelmo puedes leer claramente: Ebenezer Herrumbra.",
		},
		[632] = {
			title = "El Puente Thandol",
			accept = "Parece que el pobre Herrumba cayó en una emboscada de los Hierro Negro. Descubres un papiro junto a su puño cerrado.$B$BLleva la desalentadora noticia a Rhag Garmason y enséñale lo que has descubierto.",
			complete = "Oh, no puede ser, son malas noticias...",
		},
		[633] = {
			title = "El Puente Thandol",
			accept = "¡¡¡Cielos!!! ¡¡¡No!!! Pobre Herrumbra. Es una tragedia.$B$BNo debemos permitir que su muerte haya sido en vano. El pergamino que has descubierto indica que Kam Furiahonda, el cerebro del ataque, ordenó atesorar un alijo de explosivos al otro lado del Puente Thandol, en las Tierras Altas de Arathi.$B$B¡Si esos explosivos llegan al puente, nuestra principal vía de suministros recibirá un duro golpe! ¡Hay que destruir el alijo, $n! Vuelve a verme cuando hayas terminado tu misión.$B$BEres nuestra única esperanza.",
			complete = "¡Lo que queda del puente está a salvo! Has prestado un gran servicio al rey Magni y a las gentes de Khaz Modan.$B$BSi tan solo pudiéramos resistir hasta la llegada de los refuerzos...",
		},
		[634] = {
			title = "Petición a la Alianza",
			accept = "Voy a pedirte otro pequeño favor, $c. Estamos esperando las reservas de Forjaz. Pero Roggo tiene noticias de un campamento de la Alianza al norte de las Tierras Altas de Arathi, en el Refugio de la Zaga.$B$BViaja hasta allí y busca a la capitana Nials. Pregunta a la buena capitana si la Alianza puede ofrecernos algunos soldados que nos ayuden a recuperar Dun Modr y el Puente Thandol.",
			complete = "Todas mis condolencias para Largatrenza y sus valientes soldados. Las noticias del Puente Thandol y de la caída de Dun Modr son un duro golpe.$B$BPero Stromgarde ha caído, de ahí nuestra presencia aquí, en el Refugio de la Zaga. Nos enfrentamos a la reconquista de nuestra propia ciudad.$B$BEl honor y el sentido del deber nos impiden abandonar las Tierras altas hasta que en Stromgarde vuelva a ondear el estandarte del Rey. Enviaré un mensaje a Largatrenza advirtiéndole de que está solo...",
		},
		[635] = {
			title = "Cristal en las montañas",
			accept = "El fragmento palpita cuando lo agarras...$B$BSientes una especie de súplica saliendo del fragmento, como si alguien estuviera intentando comunicarse contigo, alguien que necesita tu ayuda desesperadamente.$B$BUna visión llena tu mente... son las montañas septentrionales de Arathi, y ves también un cristal brillante sobresaliendo del suelo.$B$BTe sientes $gatraído:atraída; hacia ese lugar.",
			complete = "Este cristal palpita, es como si tuviera una fuerza viva atrapada en su interior.",
		},
		[637] = {
