		[2755] = {
			title = "Las alegrías de los Omosh",
			accept = "Orokk no llora, $N.$B$B<Se seca una lágrima.>$B$BOrokk tiene otro secreto de la familia Omosh que enseñarte. Orokk morirá feliz gracias a $N.$B$BAprende la danza de la alegría de los Omosh y te enseñaré lo que sé de los puños de hierro.|n",
			complete = "<Pantalones Orokk.>$B$BHa pasado mucho tiempo desde que Orokk hizo la danza de la alegría Omosh. ¡Aprende ahora, $n!",
		},
		[2756] = {
			title = "Los viejos hábitos",
			accept = "En las leyendas, Aturk trituraba las calaveras de sus enemigos hasta convertirlas en un polvillo fino. Esos días ya se fueron, $r. El Jefe de Guerra pide la concordia entre los clanes. ¡Ahora solo se vigila a los enemigos de reojo!$B$BEs increíble, pero esta es la voluntad de Thrall.$B$B¡Pero basta de batallitas! Has venido a aprender y eso es lo que harás. Tráeme cuatro corazas de acero y cuatro yelmos de placas de acero y probarás el sabor de la guerra.",
			complete = "Parece que no eres más que otro lemming complaciente del Jefe de Guerra, $n. Que decepcionante.$B$BCuánto anhelo una muerte gloriosa en el campo de batalla. En cambio, estoy atrapado aquí, por orden de Thrall, ¡para enseñar a los bebés cómo hacer manualidades! ¡Mira y aprende, $gniño:niña;!",
		},
		[2757] = {
			title = "¡Bahía del Botín o nada!",
			accept = "Mira, no vas a aprender nada si andas perdiendo el tiempo por aquí.$B$BConozco a un tipo que suele estar por la herrería de Bahía del Botín. Enséñale esta insignia y te enseñará todo lo que hay que saber del mitril.$B$B¿Qué me dices, eh? Ya es hora de que aprendas cosas nuevas, $N.$B$BSi te animas, ve a ver a ese tipo, McGavan. Enséñale esto y así verá que vas en serio.",
			complete = "Por el pelo de la espalda de Pezuña Negra, ¡finalmente, $guno digno:una digna; de la Orden de Mithril!",
		},
		[2758] = {
			title = "El origen de la herrería",
			accept = "Cuando tenía más o menos tu edad, un enano llamado Galvan me acogió y me enseñó a forjar armaduras. Antes de partir a Bahía del Botín, me hizo prometer que instruiría a todos aquellos que sintieran una férrea determinación por aprender el oficio de la herrería. Así que, aquí estoy, muchos años después.$B$BAhora, ha llegado la hora de que aprendas algo. Hazme seis brazales de escamas doradas y aprenderás el significado de la herrería, $N.",
			complete = "¡Muy bien, $n! Escucha y aprende.$B$B¡La herrería nunca viene de aquí! <Hank señala su martillo.>$B$B¡La herrería nunca viene de aquí! <Hank señala el yunque.>$B$B¡La herrería solo viene de aquí! <Hank señala su corazón.>$B$BY ahora conoces el origen de la herrería.",
		},
		[2759] = {
			title = "Buscando a Galvan",
			accept = "Si bien Galvan se marchó de la Bahía del Botín muchos años atrás, todavía quedan en la ciudad otros miembros de la orden esperando encontrar, algún día, a alguien más digno de la tutela de Galvan.$B$BLleva esta insignia y preséntasela a McGavan en la Bahía del Botín.$B$BSi consigues llegar hasta allí, sabrá que eres $gdigno:digna;. ¡Tengo fe en ti, $N!",
			complete = "Por el pelo de la espalda de Pezuña Negra, ¡finalmente, $guno digno:una digna; de la Orden de Mithril!",
		},
		[2760] = {
			title = "La Orden del mitril",
			accept = "La mayoría de nuestros reclutas nunca llegan a la Bahía del Botín, $N. El solo resplandor de la insignia es suficiente para activar el ansia de botín de incluso los herreros más devotos. Son unos necios, la insignia es tan solo una gotita comparada con la riqueza de los objetos que verás.$B$BEncuentra a Galvan el Antiguo y enséñale este alfiler. Vive al norte, entre Zul'Gurub y el Túmulo Ogro Mosh'Ogg.|n",
			complete = "Ah, han pasado muchos años desde el último digno de la iniciación de la orden del mithril. ¡Empezaremos ahora!",
		},
		[2761] = {
			title = "Funde o no funde",
			accept = "Muchos herreros creen que la minería y la herrería van por separado, son trabajos independientes. ¿Pero podría existir la herrería sin la minería? ¡Ajá, es imposible! El buen herrero debe ser también un buen minero.$B$BDemuestra a Galvan de lo que eres capaz, $N. Tráeme cuarenta barras de hierro y cuarenta de mitril. A cambio, Galvan te enseñará el secreto de los pantalones de mitril ornamentado.",
			complete = "¡Tu ética de trabajo es impecable, $n! Estás comenzando a comprender la mineralogía de Galvan. ¡Toma esto y aprende todo lo que puedas!",
		},
		[2762] = {
			title = "La veraplata no es verídica",
			accept = "Dicen que la veraplata es más fuerte y duradera que el mitril. Galvan está de acuerdo con esta valoración de los minerales pero, al contrario de su nombre, ¡la veraplata no es verídica! ¡El mitril es un mineral mucho más noble! ¡JA! A pesar de todo, para esta lección necesitarás encontrar al mentiroso mineral, $N.$B$BTráeme cuarenta barras de mitril y cinco de veraplata. A cambio, aprenderás el secreto de los guantes de mitril ornamentado y, lo más importante, ¡aprenderás que la veraplata no tiene nada de verdad!",
			complete = "Es una amante cruel, ¿no es así, $n? Estoy hablando de veraplata, naturalmente. Sí, Galván pasó más de una década en las montañas de Alterac aprendiendo esta lección. ¡Toma esto y aprende de él todo lo que puedas!",
		},
		[2763] = {
			title = "El arte de imbuir",
			accept = "Recoger gemas preciosas es de gran importancia para nuestro oficio, $N. Y pocas gemas son más preciosas que el citrino. Las propiedades mágicas de las que están imbuidos los objetos se amplifican enormemente con la presencia de citrino.$B$BPara esta lección, fortificaremos cuarenta barras de mitril con cuatro citrinos. El resultado será una mejor comprensión de la gemología mágica y el conocimiento para crear sobrehombros de mitril ornamentado.",
			complete = "Uno apenas puede evitar que sus ojos abandonen su esplendor, $n. Sí, el citrino es una joya gloriosa.$B$B¡Presta atención y aprende lo que tal descubrimiento puede enseñarnos!",
		},
		[2764] = {
			title = "El mejor alumno de Galvan",
			accept = "Si estás $gpreparado:preparada; para finalizar tu instrucción con Galvan, deberías ir a Gadgetzan.$B$BAllí encontrarás a mi mejor alumno: Trenton Mazaligera. Puede enseñarte mucho sobre el mitril ornamentado. ¡Quédate y aprende!$B$BOh, ¡Gadgetzan está en Tanaris, por supuesto!",
			complete = "¿Galván el Antiguo te envió?$B$B<Trenton se inclina.>$B$B¡Es un gran honor conocer a otro de los alumnos del maestro!",
		},
		[2765] = {
			title = "¡Experto herrero!",
			accept = "Cuando viniste por primera vez a verme, sabía que acabarías siendo uno de mis más brillantes alumnos. Le diste un abalorio de bastante poder a McGavan sin dudarlo. Y lo hiciste solo para poder conocerme. Esa fe ciega y devoción debe ser recompensada.$B$BHas conseguido gran pericia en la herrería, $N. ¡Ahora te esperan las recompensas!",
			complete = "Solo es justo que recibas un abalorio de mucho más poder que el que has sacrificado aquí. Utilízalo con buena salud, $n.",
		},
		[2766] = {
			title = "¡Encuentra a OOX-22/FE!",
			accept = "Has descubierto un extraño instrumento metálico con forma de huevo. Jugueteas con uno de los botones del huevo y este cobra vida y se convierte en una especie de artilugio robótico gnomo. Del interior del huevo robótico sale una voz.$B$B\"Mi nombre es Oglethorpe Obnoticus, ¡y mi robot mensajero se ha averiado! Te recompensaré por su rescate. Por favor, lleva este localizador hasta el robot.\"$B$B\"He procesado las coordenadas del robot: se encuentra en una cueva, cerca de la Vega Cicatriz Feral.\"",
			complete = "Colocas el huevo... el localizador de emergencia... dentro del pollo... del robot mensajero.$B$BOyes murmullos y zumbidos dentro del robot mientras se esfuerza por levantarse. Cuando el robot vuelve a la vida, oyes la voz de Oglethorpe una vez más, pero ahora proviene del interior del robot:$B$B\"¡OOX-22/FE está funcionando, pero necesita reparaciones! Pesa demasiado para que cargues con él, pero creo que tengo una idea. ¿Te apetece vigilarlo un poco más?\"",
		},
		[2767] = {
			title = "¡Escolta a OOX-22/FE!",
			accept = "Vuelves a oír la voz del gnomo que sale del robot:$B$B\"Tengo que llevar a OOX-22/FE a un lugar abierto y seguro en el que pueda iniciar el largo proceso de despegue. Tiene un dispositivo de invisibilidad integrado, pero necesito tiempo para que vuelva a estar operativo. ¡Escolta al robot hasta, digamos, el muelle que está en la Costa Olvidada! Ese lugar debería ser perfecto y tendré tiempo para hacer que todo vuelva a funcionar correctamente.\"$B$B\"¡Escóltalo para que llegue sano y salvo al muelle y después ven a verme a Bahía del Botín! Oglethorpe Obnoticus. ¡Cambio y fuera!\"",
			complete = "¡Oh, eres el gran salvador de OOX-22/FE! ¡No sé ni cómo empezar a expresarte mi gratitud por tu ayuda! Aún necesito trabajar más en el desarrollo de mi serie de robots mensajeros, pero de momento, tu ayuda me ha ahorrado innumerables horas de reconstrucción, ¡y mucho dinero en costes de fabricación!$B$BPor favor, elige uno de estos objetos. Gracias de nuevo por tu valiosa ayuda, $n, ¡mis robots y yo estamos en deuda contigo!",
		},
		[2768] = {
			title = "Vara divinomática",
			accept = "¡El sargento Bly me ha robado! Dijo que solo lo cogía prestado, ¡pero me robó mi querida vara divinomática! Sin la vara, ¿cómo puedo saber dónde hacer nuevos pozos?$B$B¡Encuentra a Bly y tráeme mi vara! He oído que condujo a su panda de aventureros a buscar tesoros en Zul'Farrak, al Oeste. Seguro que lo encontrarás allí.$B$BEsperemos que los trols se hayan ocupado de él porque si tuvieras que combatir con él por la vara sería un combate realmente duro.",
			complete = "¡Lo encontraste! ¡Bien hecho, $n! ¿Tuviste que luchar con Bly para conseguirlo? Espero que le dieras bien fuerte a él y a toda su banda.",
		},
		[2769] = {
			title = "Los hermanos Pernolatón",
			accept = "¿Conoces a los hermanos Pernolatón? Están haciendo carreras contra los goblins en su coche cohete en El Desierto de Sal, en Kalimdor. Suelen ganar, lo que es normal: ¡el coche de los goblins es tan malo que apenas llega a cruzar la línea de meta!$B$BAun así, los Pernolatón siempre quieren mejorar su velocidad media y Wizzle me dijo que necesita una pieza muy rara para su próximo experimento.$B$BNecesitará a alguien que vaya a buscarla. Habla con él.",
			complete = "Ah, ¿quieres ayudarme? ¡Excelente!$B$B¡Hay una parte que quiero para un experimento en el que estoy trabajando, y necesito $gun:una; $c valiente como tú para ayudarme a conseguirlo!",
		},
		[2770] = {
			title = "Gahz'rilla",
			accept = "En las profundidades de Zul'Farrak, la ciudad de arena de los trols de Tanaris, se encuentra una poza sagrada en la que los trols invocan a una bestia gigante... ¡Gahz'rilla! Es tan violento que hasta sus escamas crepitan con energía. ¡Esa es la energía que busco para mi coche!$B$B¡Tráeme la escama electrificada de Gahz'rilla!$B$BPara ello tendrás que invocar a Gahz'rilla y ese ritual es un secreto bien guardado por los trols. Para enfrentarte a él, primero tienes que arrebatarles el secreto.",
			complete = "¡Vaya, has conseguido la escama! Gracias, $n. ¡Estoy deseando ponerme manos a la obra con ella!$B$BAsí que has visto a Gahz'rilla... ¿¿Es tan grande como dicen??",
		},
		[2771] = {
			title = "La cabeza sobre los hombros",
			accept = "Parece como si el maestro lo tuviera todo planeado. A mí no me enseñó a crear los objetos que te enseñó a crear a ti, y a ti no te enseñó a crear los objetos que me enseñó a crear a mí.$B$BEl maestro es sabio, $N. ¡Podremos instruirnos el uno al otro!$B$BEnséñame a hacer un almófar de mitril y sobrehombros de mitril ornamentado y yo te enseñaré a crear un yelmo de mitril ornamentado.",
			complete = "¡Excelente! Me parece un trato justo, modestia aparte. ¡Mira y aprende, $n!",
		},
		[2772] = {
			title = "El mundo a tus pies",
			accept = "Durante el Campeonato de herrería del valle del año pasado, todos los que estaban atentos vieron cómo un cobarde de la Fundición de Ventura y Cía. vino directo a mi pierna. Sin embargo, lo que no saben es la razón por la cual pude continuar y finalmente ganar el torneo. ¡Eso es, botas de mitril ornamentado!$B$BSin embargo, tengo que aprender a hacer pantalones de mitril ornamentado para el campeonato de este año pues participa un machacador de Ventura y Cía. ¡Enséñame a hacer los pantalones y yo te enseñaré a hacer las botas!",
			complete = "¡El mundo estará a tus pies, $n! ¡Deja que todos lleguen a tus piernas, porque ahora eres imposible de barrer!",
		},
		[2773] = {
			title = "El chico de mitril",
			accept = "Por aquí me conocen como el chico de mitril. Yo abastezco de mitril ornamentado a todos los aventureros del mundo.$B$B<Trenton susurra.>$B$BPocos saben que desconozco la técnica de creación de guantes de mitril ornamentado. ¡Sh! Este será nuestro pequeño secreto.$B$B$N, enséñame la técnica para crear guantes de mitril ornamentado y, a cambio, yo te mostraré el resultado de la culminación de mi instrucción a las órdenes de Galvan: la coraza de mitril ornamentado.",
			complete = "Gracias por todo lo que me has enseñado, $n. El dominio del conjunto de mithril adornado pronto será tuyo.$B$B¡Mira!",
		},
		[2781] = {
			title = "SE BUSCA: Califa Escorpijón",
			accept = "SE BUSCA: Califa Escorpijón.$B$BLa compañía de aguas de Gadgetzan en Gadgetzan, Tanaris ofrece una generosa recompensa por la cabeza del Califa Escorpijón, el líder de los Vagayermos. Entre los crímenes que se le atribuyen se incluyen:$B$B1. ¡El asesinato de empleados de la compañía de aguas de Gadgetzan!$B2. ¡El robo de recursos de la compañía de aguas de Gadgetzan!$B3. ¡El allanamiento de las instalaciones de la compañía de aguas de Gadgetzan!$B$BEntrega una prueba del fallecimiento del Califa Escorpijón al ingeniero jefe Pasaquillas y recibirás una recompensa al momento.",
			complete = "¡Al fin se ha hecho justicia! ¡Has asestado un duro golpe a esos infames nómadas! La muerte de Escorpijón será clave para expulsar finalmente a los que se están aprovechando de los pozos de agua de Gadgetzan.$B$BPor la autoridad que me confiere la compañía de aguas de Gadgetzan, te hago entrega de tu recompensa. Nos has prestado un gran servicio a todos nosotros.",
		},
		[2782] = {
			title = "El secreto de Rin'ji",
			accept = "En la tablilla se ven grabados de los trols Secacorteza. El secreto de Rin'ji es todo un misterio...$B$BPuede que esto sea muy valioso. Por otra parte, también puede que no lo sea. Un Secacorteza en peligro probablemente haría cualquier cosa con tal de escapar.",
			complete = "Qué tablilla tan peculiar... ¿Dónde la encontraste, $n?",
		},
		[2783] = {
			title = "Peleas mezquinas",
			accept = "Luchamos contra el enemigo equivocado, $N.$B$BEl verdadero poder de estas tierras continúa creciendo en fuerza y número mientras nos peleamos con los orcos por estos terrenos moribundos.$B$B¿No te parece que estamos librando una batalla contra la Horda para un buen día terminar exterminados por los ejércitos de la Legión Ardiente? Es fútil.$B$BDebemos dejar las diferencias de lado, $N, así que habla con el héroe caído de la Horda. Él sabe la verdad que se oculta detrás de Las Tierras Devastadas.",
			complete = "¿La Alianza desea ayudar?$B$BPensé que nunca volvería a ver este día. Un día en el que la Alianza lucha codo con codo con la Horda contra un enemigo común.$B$BSerá... nos uniremos.",
		},
		[2784] = {
			title = "Pérdida de honor",
			accept = "Esta es mi historia, $r.",
			complete = "Como espíritu, soy impotente, $n. Ayúdame. Permíteme que recupere mi honor.",
		},
		[2801] = {
			title = "Una historia triste",
			accept = "Antes de que podamos proseguir, debes oír mi historia.",
			complete = "Ha llegado la hora de actuar, $n.",
		},
		[2821] = {
			title = "La marca de la calidad",
			accept = "Tengo mi filosofía: en peletería, la calidad del trabajo debe ser la mejor posible, sin excusas. Cualquiera que te diga que la calidad no es importante, está intentando venderte un chalé en primera fila de playa en Dun Morogh.$B$BSiempre estoy buscando materiales de primera calidad y los pellejos de yeti son mi gran hallazgo. Los yetis son criaturas de Feralas. Se encuentran muchos en la Vega Cicatriz Feral. Quiero algunos pellejos. Te daré uno de mis artículos de cuero si me traes 10. Si te parece justo, tenemos un trato.",
			complete = "¿Te paraste a examinar la textura de estos pellejos? Con el tratamiento adecuado, estos pellejos podrían ser más fuertes que el hierro. No mucha gente sabe de la existencia de estas pieles. Eso, combinado con los tratamientos que solo yo conozco, me permitirá crear objetos únicos, con un sello de calidad exclusivo y auténtico... ¡gracias a ti, claro!$B$BY ahora, por favor elige algo de lo que puedo ofrecerte por tus servicios.",
		},
		[2822] = {
			title = "La marca de la calidad",
			accept = "Me enorgullezco de mi trabajo de peletería y creo que jamás se debería renunciar a la calidad. Cualquiera que te diga que la calidad no es importante, ¡intentará también convencerte de que la tierra no tiene secretos!$B$BSiempre estoy buscando materiales de primera calidad y en mi búsqueda he descubierto los pellejos de yeti. Los yetis son nativos de Feralas y a menudo se encuentran al oeste de aquí, en la Vega Cicatriz Feral. Te dejaré elegir uno de mis artículos de cuero si me traes 10 pellejos. Si te parece una buena oferta, ¡tenemos un trato!",
			complete = "¡Excelente, excelente! Cuando les dé mi tratamiento especial, estos pellejos serán tan resistentes como el hierro, ¡te lo digo yo! Tendré que hacer muchas pruebas para conseguir la mezcla correcta para curtirlas, pero sé que cuando lo consiga, mis productos tendrán una calidad superior y exclusiva.$B$BY, volviendo a ti, $n... tu ayuda ha sido valiosísima. Por favor, elige uno de estos objetos que he creado.",
		},
		[2841] = {
			title = "Las guerras de la plataforma",
			accept = "Hasta hace dos años, la tecnología gnómica solo servía para echarse unas risas. Las cosas han cambiado mucho; han construido una plataforma mejor que todas las nuestras juntas. ¡Quiero los planos, $N!$B$BEstán en una caja fuerte cerca del mekigeniero Termochufe. Para empeorar las cosas, él es el único que sabe la combinación.$B$BHaz lo que sea por conseguirla, $N. ¡Tienes que abrir la caja y traerme los planos!|n",
			complete = "¡Sabía que lo conseguirías! Sovik tenía sus dudas...$B$B<Nogg carraspea.>$B$BAhora que tenemos los planos, podremos estudiar las innovaciones gnómicas de la plataforma y adaptarlas al estilo goblin.",
		},
		[2842] = {
			title = "Scooty, ingeniero jefe",
			accept = "En cuanto Kernobee nos avisó de lo de la plataforma gnómica, Scooty y yo empezamos a trabajar en el Transpoliportador 6000. Es el medio más seguro y rápido para ir a Gnomeregan.$B$BYa está a punto para despegar. Si quieres probarlo, $n, ve a Bahía del Botín y habla con Scooty en la alcándara de jinete de Viento. Para ir a Bahía del Botín tienes que coger el barco en Trinquete.$B$BPor supuesto, puedes ir a Gnomeregan cruzando las montañas de Dun Morogh, que están infestadas de enanos.",
			complete = "Magnífico, ¿verdad? Es lo mejor de la tecnología goblin, solo ha explotado una docena de veces.$B$BNo te preocupes, $n, ya está areglado y no explotará. Y si lo hace, al menos no te enterarás de nada.",
		},
		[2843] = {
			title = "¡Gnomer-yaaaaa!",
			accept = "Mientras tengas el transpondedor, todo lo que necesitas hacer es colocarte sobre la plataforma y serás $gteletransportado:teletransportada; a Gnomeregan.$B$BQuizás experimentes algunos extraños efectos secundarios, pero ninguno será permanente... al menos ahora.$B$BCasi me olvido de lo más importante, la vuelta. Cuando quieras volver, colócate en la plataforma del Transpoliportador en Gnomeregan.$B$BTienes que calibrar el transpondedor según tu talla y peso.|n",
			complete = "¡Listo! ¡Cuando estés $gpreparado:preparada;, súbete a la plataforma!",
		},
		[2844] = {
			title = "El guardián gigante",
			accept = "No valgo para nada, $N. Se supone que tenía que vigilar a mi amiguita Shay y, no sé cómo, se me perdió. No sé muy bien qué ocurrió, pero la última vez que la vi estábamos andando por las ruinas que hay al norte de aquí.$B$BIba todo bien. Y de repente, me giro... ¡y ella ya no estaba!$B$BNo sé qué hacer... ¿Alguna idea, $N? Estoy terriblemente preocupado.$B$B¡Espera! ¡Tú puedes ir a buscar a Shay! Con tus piernas, irás más rápido que yo.",
			complete = "¡Oh, estoy tan contenta de que me hayas encontrado! Debo admitir que estoy un poco perdida... ¿Pero no es este un lugar hermoso?",
		},
		[2845] = {
			title = "Las andanzas de Shay",
			accept = "¿Puedes ayudarme a encontrar a mi amigo Muerdepiedras? Él me estaba cuidando... Pero tengo la mala costumbre de perderme de vez en cuando. Hay tantas cosas que ver que me distraigo y me pierdo por ahí.$B$BPero hay algo que siempre consigue llamar mi atención.$B$BDentro de este cofre encontrarás una campana que para mí es muy valiosa. Me encanta cómo suena. Te prometo que si me alejo y tú tocas la campana, volveré corriendo.",
			complete = "¿Qué? ¿Dices que la campana funcionará cuando Shay se escape? Bueno, ¿qué tal esto?$B$BYa que hiciste tanto por mí, aquí tienes, $n.",
		},
		[2846] = {
			title = "Tiara de las profundidades",
			accept = "Hace mucho tiempo tenía una bonita joya, la tiara de las profundidades. No solo era hermosa... tenía un gran poder para quien sabía usarlo.$B$BPor eso, cuando la hidromántica Velratha oyó hablar de ella quiso tenerla. Envío a sus agentes a mi hogar y me la robaron cuando estaba fuera. ¡Ladrones!$B$B¡Quiero recuperar mi tiara! Ve a Zul'Farrak, la ciudad trol de Tanaris, encuentra a Velratha y quítale la tiara. Cuando la tengas vuelve a verme y te ganarás mi favor.",
			complete = "¡Maravilloso! ¡La encontraste! Y lo que es más importante... ¡Velratha ya no la tiene! Gracias, $n. ¡Te estaré siempre en deuda!$B$BY si antes te pareció que tenía algo de mal humor... no hagas caso. Verás que soy mucho más agradable con aquellos que no me han robado nada.",
		},
		[2847] = {
			title = "Armadura de cuero salvaje",
			accept = "¡$n, te estás convirtiendo en $gun peletero:una peletera; bastante $gbueno:buena;! Yo conozco algunos patrones que podrían interesarte... Por ejemplo, ¡el de la armadura de cuero salvaje! El cuero salvaje aprovecha las potentes y caóticas propiedades de la atriplex salvaje que se encuentra en áreas de exuberante vegetación y en algunas criaturas de la región. Las armaduras que se forjan con ella son las mejores para alguien de tu habilidad, te lo garantizo.$B$BTe enseñaré el patrón, pero tendrás que trabajar para mí durante un tiempo. Para empezar, tendrás que traerme 10 piezas de cuero pesado. Ya detallaremos algo más después.",
			complete = "Bueno, $n, me alegro de tenerte a bordo. Has tomado una decisión inteligente como $gpeletero:peletera;; los que usan armaduras de cuero te estarán clamando una vez que aprendas a hacer cualquiera de las piezas de armadura de cuero salvaje.$B$BPongámonos manos a la obra. ¿Por dónde quieres empezar?",
		},
		[2848] = {
			title = "Sobrehombros de cuero salvaje",
			accept = "Los sobrehombros de cuero salvaje ofrecen una protección de primera a la parte superior de los brazos y a los hombros de quien las lleva. Como ocurre con la armadura de cuero salvaje, cuando se cose la atriplex salvaje a las hombreras, esta les imbuye una mejora potente aleatoria.$B$BPara este patrón necesitaré 6 refuerzos para armadura gruesos y 1 atriplex salvaje. No deberías tener problemas para conseguirlos.",
			complete = "Estos kits de armadura son de calidad sólida, $n. Si hay algo que exijo no solo en mi trabajo, sino en el trabajo de los que están a mi servicio, es calidad.$B$BHas hecho bien en ganar este patrón; Espero que te traiga las recompensas que me ha traído.",
		},
		[2849] = {
			title = "El Jubón de cuero salvaje",
			accept = "Los jubones de cuero salvaje son la pieza principal de cualquier conjunto de armadura de cuero salvaje. La tela del jubón se amalgama con la atriplex salvaje para crear un producto que ofrece la máxima protección para el torso a la vez que permite que su potente magia se abra paso a través de ella.$B$BPara este patrón, necesitaré dos petos de escamas de tortuga, dos pares de guantes de escamas de tortuga y una atriplex salvaje. Son bastantes cosas, pero no debería resultarte difícil proporcionármelas.",
			complete = "Estas son algunas piezas muy bonitas, $n. La artesanía y el cuidado puesto en su fabricación proporcionará varias monedas de plata más de lo normal.$B$BHas cumplido mi pedido y ahora viene tu recompensa. ¡El conocimiento de la fabricación de jubones de cuero salvaje ahora es suyo!",
		},
		[2850] = {
			title = "Casco de cuero salvaje",
			accept = "Un casco de cuero salvaje ofrece a quien lo lleva una gran protección de las áreas vitales de la cabeza sin sacrificar el confort. Como en todas las partes de las armaduras de cuero salvaje, cuando se integra la atriplex salvaje al casco, esta le imbuye una potente mejora aleatoria. ¡Quienes aprecian el cuero, sin duda desearán tener esta pieza!$B$BPara este patrón necesitaré 2 guerreras Nochefugaz, 2 cintas de pelo Nochefugaz y una atriplex salvaje. ¡Si me traes eso, el patrón será tuyo!",
			complete = "Este equipo Nochefugaz que has traido cumple perfectamente, $n. No espero menos de $gun peletero:una peletera; de tu calibre.$B$BDefinitivamente te has ganado este patrón. Te lo doy gratuitamente y espero que te beneficies de él en consecuencia.",
		},
		[2851] = {
			title = "Botas de cuero salvaje",
			accept = "Has aprendido bastante hasta ahora, $n; pero aún tienes que aprender más. Lo siguiente serán las botas de cuero salvaje, la piedra angular de cualquier conjunto de armadura.$B$BEstas botas se crean para envolver al pie en confort a la vez que lo refuerzan para protegerlo de los peligros de una vida aventurera. Sus suelas blandas son una bendición para quienes necesitan moverse con sigilo.$B$BPara este patrón necesito 2 pantalones Nochefugaz y 2 botas Nochefugaz. Y también necesito 2 atriplex salvajes, no me basta con una. Cuando tengas todo esto, házmelo saber.",
			complete = "Una vez más, has completado un pedido complejo con la habilidad de un profesional experimentado. Te has ganado este patrón, así como mi agradecimiento.",
		},
		[2852] = {
			title = "Leotardos de cuero salvaje",
			accept = "Una vez asentadas las bases, ya puedes aprender algo más complejo, $n. Los leotardos de cuero salvaje son uno de los artículos de cuero de mayor solidez y potencia. Ofrecen una increíble protección a la cintura, las pantorrillas y a otros órganos vitales. Si los combinas con la mejora que proporciona la atriplex salvaje, los aventureros que los vistan te lo agradecerán cada vez que te vean.$B$BPara este patrón necesito 2 cascos de escamas de tortuga, 2 brazales de escamas de tortuga y 2 plantas de atriplex salvaje.",
			complete = "Nuevamente, has completado un pedido sin problemas. Quizás algún día vendré a ti en busca de conocimiento, ¿eh $n?$B$BAquí está el patrón de los leotardos, junto con mi agradecimiento. ¡Aplica este conocimiento y deja que tus productos terminados aprovechen tus impresionantes habilidades!",
		},
		[2853] = {
			title = "Maestro de cuero salvaje",
			accept = "Vaya $n, eres la diligencia personificada. Dominas casi todos los patrones de la armadura de cuero salvaje. Solo te falta uno. Y no te haré trabajar para conseguirlo. Porque ya te lo has ganado, pero... no puedo enseñártelo yo. Mi profesor, el que me inició en la peletería, es quien debe recompensarte.$B$BLleva esta carta a Telonis; enseña peletería en Darnassus. Muéstrale la carta y te tratará como a $gun:una; igual, como hago yo.",
			complete = "Ah, sí, te envió Pratt. Aunque es un humano, a veces me recuerda a los elfos de la noche. Su dedicación y su talento con el cuero son impresionantes. Que él te felicite en esta carta, es una señal de respeto que reconozco.$B$BSoy consciente de que te ha enseñado el arte del cuero salvaje. Permíteme terminar tu entrenamiento con este patrón. Haz un buen uso del mismo; pocos en el mundo conocen los secretos de las capas de cuero salvaje.",
		},
		[2854] = {
			title = "Armadura de cuero salvaje",
			accept = "$n, tu habilidad como $gpeletero:peletera; te precede. Yo poseo un conocimiento de la peletería que harías bien en aprender... Por ejemplo, ¡el de la armadura de cuero salvaje! El cuero salvaje aprovecha las potentes y caóticas propiedades de la atriplex salvaje que se encuentra en áreas de exuberante vegetación y en algunas criaturas de la región. Las armaduras que se forjan con ella son las mejores para $gun artesano:una artesana; de tu habilidad, te lo garantizo.$B$BTe enseñaré a crearla, pero tendrás que trabajar para mí durante un tiempo. Para empezar, tendrás que traerme 10 piezas de cuero pesado. Ya detallaremos algo más después.",
			complete = "Bien, $n, me alegro de tenerte como aprendiz. Has tomado una buena decisión como $gpeletero:peletera;, quienes llevan armaduras de cuero te aclamarán cuando domines el arte del cuero salvaje.$B$BPongámonos a trabajar, ¿por dónde quieres empezar?",
		},
		[2855] = {
			title = "Sobrehombros de cuero salvaje",
			accept = "Los sobrehombros de cuero salvaje ofrecen una gran protección a la parte superior de los brazos y a los hombros de quien las lleva. Como ocurre con la armadura de cuero salvaje, cuando se cose la atriplex salvaje a las hombreras, esta les imbuye una mejora potente aleatoria.$B$BPara este patrón necesitaré seis refuerzos para armadura gruesa y una atriplex salvaje. No deberías tener problemas para conseguirlos.",
			complete = "Estos kits de armadura son de calidad sólida, $n. Si hay algo que exijo no solo en mi trabajo, sino en el trabajo de aquellos a quienes doy tutela, es calidad.$B$BHas hecho bien en ganar este patrón; Espero que te traiga las recompensas que me ha traído.",
		},
		[2856] = {
			title = "El Jubón de cuero salvaje",
			accept = "Los jubones de cuero salvaje son la pieza principal de cualquier conjunto de armadura de cuero salvaje. La tela del jubón se amalgama con la atriplex salvaje para crear un producto que ofrece la máxima protección para el torso a la vez que permite que su potente magia se abra paso a través de ella.$B$BPara este patrón, necesitaré 2 petos de escamas de tortuga, 2 pares de guantes de escamas de tortuga y 1 atriplex salvaje. No es una lección fácil, pero tú tienes sin duda la habilidad necesaria para aprenderla.",
			complete = "Estas son algunas piezas muy bonitas, $n. La artesanía y el cuidado puesto en hacerlos demuestran que has elegido dedicarte de lleno a estas tareas.$B$BHas cumplido mis peticiones y con eso viene tu recompensa. ¡El conocimiento de la fabricación de jubones de cuero salvaje ahora es tuyo!",
		},
		[2857] = {
			title = "Casco de cuero salvaje",
			accept = "Un casco de cuero salvaje ofrece a quien lo lleva una gran protección de las áreas vitales de la cabeza sin sacrificar el confort. Como en todas las partes de las armaduras de cuero salvaje, la atriplex salvaje integrada en el casco, le imbuye una potente mejora mágica aleatoria. ¡Quienes aprecian el cuero, sin duda desearán tener esta pieza!$B$BPara este patrón necesitaré dos guerreras Nochefugaz, 2 cintas de pelo Nochefugaz y una atriplex salvaje. ¡Si me traes eso, el patrón será tuyo!",
			complete = "Este equipo Nochefugaz que me has traido cumple perfectamente con los requisitos, $n. No espero menos de $gun peletero:una peletera; de tu calibre.$B$BTe has ganado el honor de fabricar cascos de cuero salvaje. Te doy este patrón gratuitamente y espero que te beneficies de él en consecuencia.",
		},
		[2858] = {
			title = "Botas de cuero salvaje",
			accept = "Tu conocimiento de la armadura de cuero salvaje crece, $n; pero aún te quedan cosas que aprender.$B$BLas botas de cuero salvaje son la piedra angular de cualquier conjunto de armadura. Estas botas se crean para envolver al pie en confort a la vez que lo refuerzan para protegerlo de los peligros de una vida aventurera. Sus suelas blandas son una bendición para quienes necesitan moverse con sigilo.$B$BPara este patrón necesito 2 pantalones Nochefugaz y 2 botas Nochefugaz. Y también necesito 2 atriplex salvajes, no me basta con una. Cuando tengas estos objetos, procederemos.",
			complete = "Una vez más, has completado un pedido complejo con la habilidad de $gun profesional experimentado:una profesional experimentada;. Te has ganado este patrón, así como mis felicitaciones.",
		},
		[2859] = {
			title = "Leotardos de cuero salvaje",
			accept = "Ya estás $glisto:lista; para lecciones más complejas, $n. Los leotardos de cuero salvaje son uno de los artículos de cuero de mayor solidez y potencia. Ofrecen una increíble protección a la cintura, las pantorrillas y a otros órganos vitales. Si los combinas con la mejora que proporciona la atriplex salvaje, los aventureros que los vistan te lo agradecerán cada vez que te vean.$B$BPara que te enseñe este patrón, tienes que traerme 2 cascos de escamas de tortuga, 2 brazales de escamas de tortuga y 2 plantas de atriplex salvaje.",
			complete = "Nuevamente, has completado mi tarea sin problemas. Quizás algún día vendré a ti en busca de conocimiento, ¿eh $n?$B$BAquí está el patrón de los leotardos, junto con mi agradecimiento. ¡Aplica este conocimiento y deja que tus productos terminados aprovechen tus impresionantes habilidades!",
		},
		[2860] = {
			title = "Maestro de cuero salvaje",
			accept = "$n, ya has aprendido todo lo que yo puedo enseñarte. Pero te queda por aprender un último patrón de la armadura de cuero salvaje. No te pediré que trabajes más, pues ya te has ganado el derecho de aprender este patrón. Pero no es un patrón que sea libre de compartir contigo.$B$BMi profesor, el que me inició en la peletería, es quien debe enseñártelo. Lleva esta nota a Una. Enseña peletería en Cima del Trueno. Muéstrale la carta y te tratará como a $gun:una; igual, como hago yo.",
			complete = "Ah, sí, te envió Jangdor. Me complace ver que uno de mis mejores estudiantes ahora tiene un estudiante propio.$B$BSu dedicación y su talento con el cuero son impresionantes. Que él te felicite en esta carta, es una señal de respeto que reconozco.$B$BSoy consciente de que te ha enseñado el arte del cuero salvaje. Permíteme terminar tu entrenamiento con este patrón. Haz un buen uso del mismo; pocos en el mundo conocen los secretos de las capas de cuero salvaje.",
		},
		[2861] = {
			title = "La tarea de Tabetha",
			accept = "Se rumorea que Tabetha, una compañera maga que vive en las profundidades del Marjal Revolcafango, tiene que arreglar cuentas con un trol de arena de Zul'Farrak. Si hablas con Tabetha te dirá más.$B$BY lleva contigo algunos amigos, $n. Si Tabetha quiere que vayas a Zul'Farrak no querrás ir $gsolo:sola;.$B$BEncontrarás la cabaña de Tabetha al oeste de Theramore, al norte de las Ruinas Quebrantarrocas.",
			complete = "Es cierto. Tengo unas cuentas que arreglar con un trol. Algunas cuentas. ¡Todas!$B$B¿Quieres ayudarme?",
		},
		[2862] = {
			title = "En guerra con los Zarpaleña",
			accept = "Los gnolls... son algo más que una molestia. ¡Son una amenaza constante para este campamento! Que sean o no de Feralas es irrelevante. Si no redoblamos nuestros esfuerzos por controlarlos, acabarán por expulsarnos de la región entera.$B$BLos ataques de los gnolls al campamento se han intensificado últimamente. Necesitamos que nos ayudes a reducir su número. Tráeme 10 de sus cabelleras. Recompensaré generosamente tu esfuerzo.$B$B¡Ve!",
			complete = "Esto es un buen comienzo, $n. Tus habilidades de combate son encomiables.$B$BY no eres $gel primero al:la primera a la; que he asignado esta misión. Muchos antes que tú han combatido contra ellos. Nuestros esfuerzos los han mantenido a raya hasta ahora. Pero últimamente, sus intentos de avanzar hacia el norte por nuestra tierra, se han redoblado. Y sus ataques son cada vez más salvajes... casi como si estuvieran desesperados.$B$BPero yo tengo un plan que podría solucionar esto de una vez por todas.",
		},
		[2863] = {
			title = "Ataca a los Alfas",
			accept = "El plan es para varios líderes de los gnolls, esos que se hacen llamar Alfas. Para acabar con ellos en rápida sucesión. Si logramos ejecutarlo con la rapidez y precisión necesarias, haríamos que cundiera el caos entre sus filas. Y quizás conseguiríamos que en esas estúpidas cabezas piojosas entrara el mensaje de que podemos destruirlos ¡y lo haremos!$B$BQuiero que seas tú $gel mensajero:la mensajera; de mi voluntad, $N. Elimina a 5 de sus Alfas en una hora. ¡Si tardas más, el plan no funcionará y empeorarás nuestra situación!",
			complete = "Tú has hecho lo que te pedí y te aplaudo por ello. Acepta esta pequeña recompensa como premio por tus esfuerzos, $n.$B$BAhora que sus líderes han muerto y hemos diezmado su número, se lo pensarán dos veces antes de irrumpir en el campamento. Pero eso no soluciona el problema.$B$BDebe de haber un motivo para que los gnolls hayan enloquecido. Y antes de que tengan tiempo de reagruparse, tenemos que averiguar qué es lo que causa su locura.",
		},
		[2864] = {
			title = "Tran'rek",
			accept = "Mi primo Tran'rek está en un aprieto. Me prometió un cargamento de caparazones de escarabajo hace semanas y todavía no lo ha traído. Es mi primo, así que odio tener que enviar a alguien a Gadgetzan para que le eche la bronca.$B$B¿Puedes hablar con Tran'rek por mí? Hazle saber que tiene que conseguir ese cargamento antes de que haga algo malo.$B$BGadgetzan está en el norte de Tanaris, en Kalimdor.",
			complete = "¡Hola!$B$BOh, ¿hablaste con mi primo Krazek? ¿Cómo está? Espero que le vaya bien en Bahía del Botín...$B$B¿Caparazones de escarabajo dices? Bien... cuéntame tu historia...",
		},
		[2865] = {
			title = "Caparazones de escarabajo",
			accept = "¡Los escarabajos de Tanaris tienen unos caparazones muy duros! Tan duros que se pueden utilizar para construir muchas cosas. ¡Muchísimas!$B$BDe hecho, esos caparazones son tan útiles y cazamos tantos escarabajos... ¡que casi se han extinguido!$B$BSé dónde hay más escarabajos, y si me prometes traerme sus caparazones te diré dónde están. ¿Prometido?$B$BMuy bien, hay una colonia de escarabajos en Zul'Farrak. Supongo que los trols no los cazan en busca de caparazones.$B$B¡Pero tú sí! ¡Ve a Zul'Farrak y consígueme caparazones sin rajar!",
			complete = "¡Oh, genial! ¡Los conseguiste!$B$BGracias, $n. ¡Eres $gun:una; $gauténtico:auténtica; salvavidas!",
		},
		[2866] = {
			title = "Las Ruinas de Solarsal",
			accept = "Al sur de aquí están las Ruinas de Solarsal, una zona que ya era antigua antes de nuestro tiempo. Exploramos las ruinas en su momento y no encontramos nada relevante, así que no volvimos a enturbiar la paz del lugar.$B$BHace poco, los nagas Crestafuria han ocupado las ruinas en número alarmante. Al principio, lo interpretamos como el anuncio de un ataque. Aún consideramos esa posibilidad, pero además, creemos que podría estar ocurriendo alguna otra cosa.$B$BVe a explorar las ruinas y busca cualquier cosa que te llame la atención. Buena suerte, $n.",
			complete = "Un examen minucioso de la glorieta revela tres cosas interesantes y poco habituales que contrastan con las ruinas que la rodean.$B$BPrimero, la glorieta es evidentemente más reciente que las demás estructuras de las ruinas. Segundo, tiene una serie de glifos pequeños grabados en los lados. Los glifos parecen repetirse, pero su significado y su origen son desconocidos. Tercero, la piedra de la glorieta está caliente al tacto.$B$B¡Esto es sin duda algo que \"llama la atención\"!",
		},
		[2867] = {
			title = "Regresa al Bastión Plumaluna",
			accept = "Tras descubrir la extraña glorieta en el corazón de las Ruinas de Solarsal, sabes que ha llegado el momento de regresar al Bastión Plumaluna e informar a la general Shandris Plumaluna del resultado de tu exploración.",
			complete = "$gBienvenido:Bienvenida;, $n. Tu informe sobre la glorieta es... preocupante. Parece que, aunque los naga no estuvieran planeando un ataque, su presencia es una mala señal para nuestra ofensiva en Feralas. En cualquier caso, aquí tienes tu compensación por tu servicio.$B$BParece que el Bastión Plumaluna necesita desesperadamente ayuda con el problema de los naga Crestafuria. Quisiera ofrecerte a ti la misión, si te parece. Hay mucho que hacer.",
		},
		[2869] = {
			title = "En contra de los Crestafuria",
			accept = "En este momento, lo mejor que podemos hacer es asumir que, independientemente de lo que estén haciendo los nagas, antes o después se moverán para asegurar la isla para los suyos. Necesitamos tomar medidas agresivas para combatir esa amenaza antes de que sea demasiado tarde.$B$BTráeme 10 escamas de Crestafuria que estén en buenas condiciones. No hará falta decirte cómo conseguirlas, supongo. Tú adquirirás experiencia con los nagas y nosotros conseguiremos reducir su presencia en Isla de Sardor. Ambas cosas serán beneficiosas para nosotros.",
			complete = "Sí, sí, estas escamas son más que satisfactorias. De hecho, creo que se las enviaré a Pratt, para que les eche un ojo. Quizás pueda hacer algo útil con ellas.$B$BEn cuanto a ti, tengo otra misión que encomendarte. Pero antes, aquí tienes tu recompensa por las escamas. Tu servicio a la general Plumaluna y al Bastión en su conjunto es una bendición en estos tiempos adversos.",
		},
		[2870] = {
			title = "En contra de Lord Shalzaru",
			accept = "$n, nos han llegado informes de los exploradores que nos han dado una buena idea de cómo es la cadena de mando de los nagas. Entre sus filas hay Regios, que son los que mandan.$B$BEn concreto, hemos identificado a uno de los regios más crueles: Lord Shalzaru. Según mis exploradores, él en persona ha desenterrado una extraña reliquia en una excavación naga de una cueva del sur de las ruinas principales, en la Isla del Terror.$B$BAcaba con él y tráeme esa reliquia para que podamos estudiarla.",
			complete = "¡Bien, $n! La muerte de Lord Shalzaru desconcertará a los naga durante un tiempo, si no para siempre. La amenaza que suponen ahora está más descontrolada que nunca, y eso te lo debemos a ti.$B$BAquí tienes más dinero del tesoro del Bastión. Te has ganado cada pieza. Tú y los tuyos sois siempre bienvenidos en el Bastión Plumaluna, $gamigo:amiga;.$B$BUna cosita más, antes de que te vayas, $n... si pudieras...",
		},
		[2871] = {
			title = "Entrega la reliquia",
			accept = "Si fueras tan amable de entregar la reliquia a mi esposa Vestia, te lo agradecería. No es solo una de las mejores sacerdotisas de nuestra comunidad, además es una de las estudiosas más eruditas que conocerás en tu vida. Yo no podría ni dibujar este instrumento, ¡ni aunque mi vida dependiera de ello! Pero mi mujer... Si alguien puede averiguar qué es esta cosa, esa es ella. ¡Y necesitamos saber qué es!$B$BEstá al otro lado de la curva. Estará estudiando, seguro. Gracias, $n.",
			complete = "Interesante... ¿Y dices que viene de las Ruinas de Solarsal? Pues Latro tiene razón, tengo que mirar esto. A primera vista, no parece pertenecer a las ruinas. Y tampoco es de fabricación naga... no harían algo tan extraño como esto.$B$BMe va a llevar algún tiempo estudiar este objeto. Cuando haya acabado, quizás pueda hacer uso de tus talentos, si andas por aquí.$B$BTen, acepta este objeto. No lo necesitamos, pero espero que tú le des un buen uso.",
		},
		[2872] = {
			title = "La deuda de Stoley",
			accept = "Mi viejo amigo Stoley me debe una botella muy especial de ron. Él atiende el bar del Puerto Bonvapor en Tanaris, Kalimdor, y me aseguró que el ron allí es más fuerte que cualquier cosa que podamos encontrar en Bahía del Botín. Está tan seguro de lo que dice que prometió darme el doble de dinero del que me debe si después de probarlo no opino lo mismo.$B$BBueno, yo creo que ahora ya no está tan seguro como en su día y no quiere que pruebe el ron. Sin embargo, yo nunca me echo atrás ante una apuesta, así que por qué no vas a hablar con él...",
			complete = "Ah, has estado hablando con MacKinley, ¿no es cierto?$B$B¡No es lo que él piensa! No tengo miedo de dejarle probar el ron de la sentina Bonvapor...$B$B¡Simplemente no me queda ni gota!",
		},
		[2873] = {
			title = "El envío de Stoley",
			accept = "Le debo algo de ron a \"Lobo de Mar\" MacKinley de Bahía del Botín por una apuesta, ¡pero no me queda ni gota! El capitán Cuergo robó mi último cargamento y lo escondió en esa ciudad pirata amurallada situada al sur.$B$BSi encuentras mi cargamento de ron y me lo devuelves, quizás pueda demostrarle a MacKinley que el ron de Bahía del Botín no le llega a este ni a la suela del zapato.",
			complete = "¡Genial, gracias por el cargamento! Ahora MacKinley y yo podremos acabar con nuestra apuesta.",
		},
		[2874] = {
			title = "Un envío para MacKinley",
			accept = "Gracias de nuevo por tu ayuda, $N. Aquí tienes una botella de ron de la sentina Bonvapor. Llévasela a MacKinley para que pueda comprobar por fin lo que se dice del ron de Bahía del Botín.",
			complete = "Mm, a ver, déjame probar...$B$B¡No puedo creerlo! ¡Esto es... la bomba! ¡Genial!$B$BSupongo que Stoley puede quedarse el dinero que me debe. Tenía razón en cuanto al ron de la sentina Bonvapor... ¡Cómo rasca!",
		},
		[2875] = {
			title = "SE BUSCA: Andre Barbafuego",
			accept = "Se busca al malvado pirata Andre Barbafuego por crímenes contra Bonvapor y Gadgetzan.$B$BPor decreto del consejo de gobierno, todo el que lea esto tiene autorización expresa para utilizar fuerza letal durante la ejecución del arresto de Andre y sus cómplices.$B$BPor nuevo decreto, de producirse el fallecimiento de Andre o de sufrir este algún tipo de perjuicio durante la sesión de interrogatorio posterior a su detención, su cabeza actuará como prueba irrefutable de este hecho y su entrega ante el jefe de seguridad Pasaquillas constituye contrato vinculante.",
			complete = "¡Ah, la cabeza de Andre! ¡Supongo que al final recibió su merecido!$B$BMuchas gracias, $n. Y ahora si me firmas aquí, te pagaré por los servicios prestados.$B$BNo te preocupes por la letra pequeña, no pone nada interesante y... de todos modos, no creo que exista una lupa lo suficientemente buena como para poder leerla.",
		},
		[2876] = {
			title = "El registro náutico",
			accept = "Este pergamino contiene el registro de envíos realizados entre el Puerto Bonvapor y Bahía del Botín. Están incluidos tanto los envíos ya hechos como los pendientes, así como los nombres de los barcos, algunos con una X al lado y otros con anotaciones del tipo \"GRAN BOTÍN\" y \"DURA LUCHA\".$B$BSeguro que hay alguien en el Puerto Bonvapor interesado en echarle un vistazo a este documento.",
			complete = "No puedo creerlo, ¡es una lista de todas las salidas y llegadas de barcos, con sus respectivas fechas, horas y todo! Si cayera en manos del capitán de un barco pirata, ¡este haría su agosto!$B$B¿Y dices que la conseguiste de un pirata? Vaya...$B$BGracias, $n. Me alegro de que se la hayas quitado y también de que le hicieras morder el polvo.",
		},
		[2877] = {
			title = "La limpieza de Roca Oculta",
			accept = "Los Martillo Salvaje recordamos el pasado mejor que nuestros hermanos de Forjaz. ¡Si quieres hacer amigos aquí, tendrás que ensuciarte las manos!$B$BLa Horda ha abandonado sus puestos de Roca Oculta en las Tierras del Interior; ahora todo está infestado de babosas y mocos. Tenemos planes para la región, pero antes hay que enviar una brigada de limpieza.$B$B¡Ese es tu trabajo, hermosura! Ve allí y elimina 10 lodos verdes y 10 mocos de jade. ¡Andando!",
			complete = "Lo que los Martillo Salvaje valoramos es la acción, $c.$B$BTu misión es mucho más importante de lo que crees. Si reducimos el número de mocos y lodos, podremos expandir nuestra zona de influencia. Ten; además de nuevos amigos, te has ganado una recompensa.",
		},
		[2878] = {
			title = "Melodía corrupta",
			complete = "Aplicas un poco de bálsamo de planta Cenarion a la melodía. Inmediatamente empieza a mudar su forma corrupta y se transforma en una planta rebosante de salud.",
		},
		[2879] = {
			title = "El báculo de Equinex",
			accept = "¡Esta madera curva podría ser el báculo de Equinex! El báculo de Equinex es, en realidad, una llave que abre el Monolito de Equinex de las Ruinas de Viento Azabache, las que están en la península al oeste de Rama Oniria.$B$BEncuentra las cuatro llamas que aún flamean en esas ruinas: Samha, Imbel, Byltan y Lahassa. Recoge sus esencias y luego, cuando estés en el Monolito de Equinex, utilízalas para imbuir su energía a la madera curva. Si este es realmente el báculo de Equinex, podrás abrir el Monolito y sacar un artefacto sagrado de él.",
			complete = "Sostener el bastón energizado es casi imposible. Su poder retumba por tu cuerpo.$B$BExtiendes la mano hacia la fría superficie del Monolito de Equinex...$B$BSe abre una pequeña puerta que te permite sacar el artefacto del interior.$B$BUnos rayos de luz inundan la zona que rodea al Monolito de Equinex.",
		},
		[2880] = {
			title = "Los collares de trols",
			accept = "Que quede claro, $r: ¡NO formamos parte de la Alianza! Los Martillo Salvaje somos independientes, creemos que el valor se tiene que probar con actos y no con bonitos discursos.$B$B¡Si quieres que te aceptemos, tendrás que probar tu valía! Esos inmundos trols que ensucian las Tierras del Interior suelen llevar collares tribales. Tráeme cinco y lo consideraremos un acto de buena voluntad hacia nosotros.",
			complete = "Con estos collares nos demuestras tu valor; los Martillo Salvaje apreciamos el coraje.$B$BSigue así y llegarás lejos.",
		},
		[2881] = {
			title = "Los collares de trols",
			complete = "¡Bien, ya hay menos trols de los que preocuparnos! Buen trabajo, $n. ¡Sigue así!",
		},
		[2882] = {
			title = "El oro de Cuergo",
			accept = "Este mapa muestra un trecho de playa orientado hacia el sur. Debajo del mapa hay unas palabras escritas de manera elegante...$B$BMás al sur de Bonvapor$BAl sur del lar de tu corazón$BEncontrarás huesos, mástil y bandera$BExcava allí si tienes alma aventurera$BExcava y el oro de Cuergo reclama$BUna llave necesitarás y una llave encontrarás$BLos hombres a los que te enfrentarás$Ben sangre pagarás.",
			complete = "¡El tesoro escondido del capitán Cuergo aguarda!",
		},
		[2902] = {
			title = "Investiga a los Zarpaleña",
			accept = "Los gnolls no son los tipos más rápidos del lugar, pero seguramente tendrán algún tipo de documentación sobre sus actividades. Si encontráramos sus planes, podríamos tener una idea más clara de lo que les está agitando tanto.$B$BQuiero que vuelvas a Zarpaleña y busques cualquier cosa que pueda parecer un plan de batalla. Tienen que tener algo: sus ataques han sido demasiado coordinados, han tenido que seguir un plan. Encuentra la documentación de sus planes y vuelve cuando la tengas.",
			complete = "Un examen del mapa revela que es el plan de ataque que quiere Hadoken Zancoveloz. Hay muchas flechas que probablemente representan movimientos de tropas. La mayoría parecen dirigirse hacia el sur, no al norte, que es donde se encuentra el Campamento Mojache.$B$BEn otra sección del mapa hay un dibujo de lo que parece ser una especie de insecto enorme, con varias marcas debajo. Por el aspecto de los gnolls, puede que represente las bajas que esos insectos desconocidos han causado en sus filas...",
		},
		[2903] = {
			title = "Los planes de batalla",
			accept = "Ahora que has descubierto los planes de batalla de los gnolls, solo te queda llevárselos a Hadoken Zanco Veloz al Campamento Mojache. Quizás él o alguien de allí pueda averiguar qué están tramando los gnolls.",
			complete = "Ah, esto es exactamente lo que necesitamos. No se me da muy bien descifrar los garabatos de este mapa, pero he visto suficientes planes de ataque en mi vida para entender lo que está pasando con los gnolls. Parece que están combatiendo en dos frentes. En uno de ellos, combaten contra nosotros... pero parece que han concentrado la mayoría de sus energías en combatir a su enemigo del sur.$B$BEsto podría ser importante. Quizás sea el momento de averiguar quién es ese otro enemigo.",
		},
		[2904] = {
			title = "Un buen lío",
			accept = "<Kernobee gruñe.> ¿Qué...? ¿Qué ha pasado?$B$BSolo recuerdo que me capturó un grupo de enanos Hierro Negro, me dieron una paliza de muerte y me echaron aquí, con estos asquerosos troggs.$B$B¡Sácame de aquí, $n!$B$BEste es el plan: llévame a la salida; si sobrevivimos, tú te vas a la Bahía del Botín y le dices a Scooty que he ido a Trinquete para avisar a Manitas de Oro que los Hierro Negro están metidos en lo de la superplataforma.$B$B¡Andando!",
			complete = "Mereces una recompensa por habernos traído a Kernobee, $n. Esto te ayudará a derrotar a ese traidor miserable que es el mekigeniero Termochufe si vuelves a Gnomeregan.",
		},
		[2922] = {
			title = "¡Salva el cerebro de Tecnobot!",
			accept = "Supongo que mi pobre Tecnobot recibió algún chispazo perdido cuando cayó nuestra amada Gnomeregan. Antes nos era muy útil gracias a sus incontables funciones y su capacidad ilimitada de almacenaje de información, pero su cerebro positrónico se ha polarizado. Ahora es negatrónico y la conducta de Tecnobot se ha invertido. ¡Anda descontrolado por Gnomeregan!$B$BPero quizás podamos recuperarlo. Si me trajeras el procesador central de memoria del Tecnobot, podría descubrir la causa de la polarización y repararlo.$B$B",
			complete = "¡Excelente! ¡Gracias, $n, voy a ponerme a trabajar de inmediato!$B$BPobre tecnobot, vaya susto te has llevado.$B$BEnseguida te arreglo; a ver, dónde estará mi llave inglesa giratoria con gato hidráulico...",
		},
		[2923] = {
			title = "Maestro manitas Sobrechispa",
			accept = "El maestro manitas Sobrechispa está muy disgustado con lo ocurrido a su obra mecánica, Tecnobot. Por lo que sé, Tecnobot era una herramienta muy útil para los gnomos, pero dice que se ha averiado.$B$BLástima. ¡Aunque con suerte se podrá arreglar!$B$BVe a hablar con Sobrechispa a Ciudad Manitas, en Forjaz. Se alegrará de que vayas a ayudarlo.",
			complete = "Sí, hemos perdido el control del tecnobot. ¿Puedes ayudarme?",
		},
		[2924] = {
			title = "Esencias artificiales",
			accept = "Los herreros y manitas de Gnomeregan usaban un componente mecánico casi universal, la esencia artificial, en su trabajo. Pero durante la huida de la ciudad, ¡nadie pensó en coger esencia! Necesitaré mucha para un trabajo que estoy a punto de empezar.$B$BTe ruego que vayas a Gnomeregan a conseguirme esencia artificial. Está en las zonas más profundas de la ciudad, en unos contenedores que se llaman extrapoladores artificiales.$B$B¡Date prisa y muchas gracias, $n!",
			complete = "¡Ahora que tengo las esencias, puedo empezar mi nuevo experimento!$B$B¡No puedo agradecerte lo suficiente, $N! ¡Gracias a tu valentía, la investigación gnómica va a dar un salto cuántico!",
		},
		[2925] = {
			title = "Klockmort Palmalicate",
			accept = "Klockmort Palmalicate, un amigo gnomo, me ha enviado un mensaje desde Forjaz. Dice que necesita ayuda en una misión peligrosa pero crucial en Gnomeregan, la gran ciudad hoy contaminada e invadida por gnomos dementes y sus aparatos.$B$BYo debo quedarme aquí, pero quiero ayudar a mi amigo. Si vas en mi lugar tendrás mi agradecimiento eterno.$B$BEncontrarás a Klockmort en Ciudad Manitas, en Forjaz.",
			complete = "Pues sí, necesito a alguien para una misión en Gnomeregan. ¿Te interesa, $c?",
		},
		[2926] = {
			title = "Gnogaína",
			accept = "Desde el accidente, Gnoarn no piensa en otra cosa que en expulsar a los troggs de Gnomeregan y encontrar una cura para la plaga, $N.$B$BPor suerte, Razzle y yo estamos a punto de conseguirlo; o eso, o hemos destilado un ron muy potente. ¡No lo sabremos hasta que lo probemos! Claro que para poner a prueba nuestra teoría, necesitamos algunas cosas, como restos de los troggs radiactivos en Gnomeregan. ¡Llena esta ampolla de material verdoso radiactivo y tráela de regreso!",
			complete = "¡Excelente! Vamos a probar la nueva fórmula. ¡Si funciona, no solo curaremos a los gnomos leprosos, sino que me volverá a crecer el pelo! ¡Aparta!",
		},
		[2927] = {
			title = "Al día siguiente",
			accept = "¿Crees que siempre he sido calvo? ¡Pues no $gseñor:señorita;! Perdí todo el pelo por culpa de la fuga radiactiva de Gnomeregan. Hasta entonces, tenía una mata de pelognomo única en todo Azeroth.$B$B<Sacude los puños.>$B$B¡Así se pudran esos malditos troggs en las simas del averno!$B$BA lo mejor no es tarde, $N. Aún podemos salvarla. ¡A la ciudad, me refiero! Ve a hablar con Ozzie Voltiflop en Kharanos. Está buscando una solución con su colega Razzle.",
			complete = "Creí que no soportaría la pérdida del pelo, pero ya ves.$B$BEstábamos juntos cuando le cayó la nube radiactiva y se le empezó a caer el pelo a puñados. Fue horroroso. ¡Empezó a tocarse la cabeza, se le pusieron los ojos rojos y juró venganza! Desde entonces la tomó con los troggs.$B$B<Ozzie se estremece.>",
		},
		[2928] = {
			title = "Excavadoras gyroagujereamáticas",
			accept = "Es terrible, $N. No vamos a tener suficientes repuestos para llevar nuestra flota de excavadoras gyroagujereamáticas a Dun Morogh.$B$BLo que necesitamos son repuestos, $N. ¿Y qué mejor lugar que Gnomeregan para conseguir repuestos para nuestros vehículos? He oído que robots y mecazancudos vagan libremente por ese lugar.$B$BNecesito que vayas a Gnomeregan y destruyas a esos robots. Tráeme sus entrañas robot. Con dos docenas tendré suficiente.|n",
			complete = "Esto será perfecto, $n. Una excavadoras gyroagujereamática arreglada, solo quedan 398.",
		},
		[2929] = {
			title = "La gran traición",
			accept = "Yo confiaba en Termochufe, $r. Nunca pensé que me traicionaría a mí y a todos los gnomos. ¿Y por qué? ¿Por el poder? ¿Por el dinero? Habría conseguido todo eso por sí mismo. Ahora nos han echado de nuestro hogar y ese chiflado es el que manda. Rey de pacotilla...$B$BVamos a recuperar Gnomeregan, $n. No cejaremos hasta que la ciudad vuelva a nuestras manos. Si quieres ayudarnos, tengo un trabajito para ti. Mata al traidor. Acaba con el mekigeniero Termochufe.",
			complete = "Cuéntame otra vez cómo le aplastaste el cráneo con la bota, $r. Ahora que ha muerto, estamos más cerca de recuperar Gnomeregan.",
		},
		[2930] = {
			title = "Rescatar los datos",
			accept = "¡Cuando tuvimos que huir de Gnomeregan, dejamos atrás información muy valiosa! ¡Qué digo, valiosa! ¡Vital!$B$BNecesito los datos de la tarjeta perforada prismática de un Perforágrafo Matriz 3005-D de alta seguridad oculto en Gnomeregan. Tienes que acceder a la terminal, pero para eso necesitas un permiso... Y para eso tienes que acceder a una terminal de baja seguridad de los modelos -A, -B y -C. Y para eso, necesitas tarjetas perforadas de seguridad en blanco... y todas se quedaron en la ciudad.$B$B¡Qué desastre! ¿Puedes ayudarme?",
			complete = "¡Has conseguido recuperar los datos! Son importatísimos, vitales.$B$BEste servicio que nos has prestado será recordado mucho tiempo, $n.",
		},
		[2931] = {
			title = "Trabajar para Funditubo",
			accept = "¡El maestro mecánico Funditubo de Forjaz busca gente aventurera! Quiere volver a Gnomeregan para recuperar datos; es una misión muy importante.$B$BAunque no sea miembro de la Asamblea Iluminada de Arcanología, alquimia e Ingeniería como yo, es un gnomo inteligente, así que si piensa que algo es importante, según mis cálculos hay un 48 por ciento de posibilidades de que, en efecto, sea importante.$B$B¡Es una probabilidad muy alta!",
			complete = "Estoy organizando misiones a Gnomeregan. Si estás aquí por eso, escucha con atención.",
		},
		[2932] = {
			title = "Un mensaje siniestro",
			accept = "Los trols Secacorteza fueron aliados de la Horda, ¡pero traicionaron a Thrall y deben ser castigados!$B$BToma mi pica y vete a las Tierras del Interior. Están al noreste de Molino Tarren, que está bajo control de nuestros aliados, los Renegados.$B$BCuando llegues, busca trols Secacorteza. Recoge sus cráneos y clava mi pica en el suelo en uno de sus poblados más pequeños, Hiri'watha o Zun'watha.$B$B¡Que aprendan que sus ruines acciones tienen consecuencias!",
			complete = "Sé que has cumplido tu misión. Esperemos que los Secacorteza capten el mensaje.",
		},
		[2933] = {
			title = "Botellas de veneno",
			accept = "En estas botellas hay un veneno verde e infame.$B$BVista la cantidad de botellas que hay en el poblado, los Secacorteza deben de considerarlo muy importante. A lo mejor algún boticario de Molino Tarren estaría interesado en esto.",
			complete = "¿Qué es esto? Parece veneno de arácnido... ¿De dónde sale?",
		},
		[2934] = {
			title = "Glándula de veneno intacta",
			accept = "Necesito más veneno como el que trajiste. Creo que las arañas de las que se extrae viven en las Tierras del Interior; encuentra una con la glándula de veneno intacta y tráemela. Habrá muchas cerca de la ciudad trol de Shadra'Alor.$B$BNo te entretengas, $N. La glándula tiene que ser fresca.",
			complete = "¡Magnífico! El veneno es fresco y letal... ¡Gracias!",
		},
		[2935] = {
			title = "Consulta al maestro Gadrin",
			accept = "El veneno de las guardias del linaje no era tan potente como el que me trajiste primero. Debía de ser de otra araña.$B$BQuiero que me traigas más de ese veneno. Para averiguar de dónde viene, ve al Poblado Sen'jin y habla con el maestro Gadrin. Es un trol que conoce bien a los Secacorteza. Ve a Durotar y habla con Gadrin. Con un poco de suerte, sabrá de dónde sacan el veneno los Secacorteza.",
			complete = "¿Que quieres veneno de las arañas de los Secacorteza? Bueno, pues siéntate; lo que voy a decir no te va a gustar.",
		},
		[2936] = {
			title = "Diosa araña",
			accept = "Los Secacorteza adoran a una diosa araña, de la cual extraen su veneno más potente. Así que, si quieres el veneno, ¡tienes que invocar a la diosa!$B$BPara ello debes conocer su verdadero nombre, inscrito en una tablilla enterrada en Tanaris, en la ciudad trol de Zul'Farrak, en una tumba custodiada por el Mártir Theka.$B$BDerrótalo y lee el nombre en la tablilla. Después, vuelve.",
			complete = "Ah, Elortha no Shadra... Este nombre solo debe ser susurrado, pues tiene un gran poder en el reino de los espíritus.$B$BVoy a preparar el hechizo de invocación...",
		},
		[2937] = {
			title = "Invocar a Shadra",
			accept = "Lee este papiro en el altar de Shadra'Alor, que está escondido en el reino de los Secacorteza, en las Tierras del Interior. Así invocarás a Shadra, la diosa araña.",
			complete = "¡Excelente!",
		},
		[2938] = {
			title = "Veneno para Entrañas",
			accept = "¡El veneno de la diosa araña de los Secacorteza es extraordinario! Ha bastado una gota para matar a dos docenas de conejos. Es cierto que muchos eran muy pequeños y por tanto poco resistentes a las toxinas, ¡pero no puede negarse que este veneno es de lo más potente!$B$BMe gustaría enviar una muestra a mi superior, el boticario Faranell, del Apothecarium de Entrañas. Seguro que querrá hacer pruebas.",
			complete = "Muy bien; Lydon dijo que es el veneno más potente que conoce y que lo está estudiando.$B$BEspero que le encuentre muchos usos.$B$BGracias por todo, $n.",
		},
		[2939] = {
			title = "La búsqueda del conocimiento",
			accept = "Las ruinas de Feralas pueden ser muy peligrosas, pero tienen mucho que decir acerca de lo que aquí pasó.$B$BEntre los escombros, hace unos días, descubrí lo que parecía ser un báculo normal y corriente. Sin embargo, creo que hay algo en él. Angelas y yo hemos estado leyendo buscando algo al respecto, pero no aparece nada.$B$BTengo una amiga en Darnassus que nos podría decir lo que es, $N. ¿Por qué no vas a verla y le preguntas si nos ayuda?",
			complete = "Ah, ¿así que te envía Troyas Brisaluna?$B$B<murmurando>... Siempre está molestándome con esas exageraciones de que ha encontrado algo importante...$B$BMira, $n, te voy a hablar con franqueza. Troyas siempre cree que ha encontrado algo importante en esas ruinas. Y la verdad es que, cualquier cosa de valor que hubiera en ellas, seguramente ha desaparecido ya. Se la habrán llevado los orcos o las arpías que habitan en ellas ahora.$B$BPuedes echar un vistazo por aquí, pero no sé si encontrarás ningún libro que te ayude.",
		},
		[2940] = {
			title = "Feralas: una historia",
			accept = "Parece que este libro no ha sido abierto en mucho tiempo. Las tapas están bastante desgastadas y sus páginas, amarillentas, pero después de examinarlo, te das cuenta de que puede ser lo que Troyas está buscando.$B$BLo recoges, pero entonces piensas que deberías preguntar antes de tomarlo prestado.",
			complete = "¿Así que quieres llevarte Feralas: Una historia?$B$BDeja que me lo piense...$B$BTe prestaré el libro, $n, pero solo si haces algo por mí antes.",
		},
		[2941] = {
			title = "El préstamo",
			accept = "He estudiado muchos temas en mi tiempo y mi última obsesión son los Quijaforte que ocupan la playa de las Tierras del Interior. Y hay una en concreto a la que me gustaría ver, una Quijaforte gigante llamada Gammerita. Iría yo misma, pero mis investigaciones no me permiten moverme de aquí. Así que me conformaría con tener un dibujo de ella.$B$BLleva esta carta a Curgle Saltamanivela a Tanaris. Ha inventado un dispositivo para mí que puede capturar imágenes. Ella lo llamaba \"instantánea\" creo...",
			complete = "¿Eres otro de los internos de Daryn? Es una gran historiadora, $n. Tienes suerte de estudiar bajo su guía.$B$BAhora deja que coja la Superinstantánea FX. ¡Te va a encantar!",
		},
		[2942] = {
			title = "La Piedra del mañana",
			accept = "En el momento en el que extraes el artefacto del Monolito, sientes que la energía del báculo de Equinex empieza a decaer.",
			complete = "He estado leyendo desde que te fuiste, $n. Esta piedra que encontraste se llama Piedra del mañana. Aún no tengo muy claro para qué sirve, pero sí sé que debe de ser muy importante, si no, no estaría escondida en el Monolito de Equinex.$B$BYo seguiré con mis estudios. Espero poder contar contigo en un futuro, $n. Gracias por tu ayuda.",
		},
		[2943] = {
			title = "Regresa junto a Troyas",
			accept = "Aquí lo tienes, $N. Por favor, cuida de mi libro.$B$BY, ahora, ve. Seguro que Troyas está deseando que regreses.",
			complete = "Has traído un libro. ¡Fantástico!",
		},
		[2944] = {
			title = "La Superinstantánea FX",
			accept = "Echa un vistazo a mi nuevo invento, $n. Lo único que hay que hacer es apuntar a lo que quieras retratar y pulsar el botón.$B$B¿Cuál era esa criatura de las Tierras del Interior que mencionaste? ¿Gammerita? Pues espero que la encuentres. Buena suerte. Estoy segura de que Daryn quedará satisfecha con la instantánea que le llevas.$B$BEn cualquier caso, ¡aquí tienes la Superinstantánea! ¡Diviértete!",
			complete = "¡Bien! El invento de Curgle supera todas mis expectativas.$B$BNo te emociones demasiado pero debes saber que tu trabajo me satisface mucho, $n.$B$BVeamos, ¿dónde dejé el libro?",
		},
		[2945] = {
			title = "Un anillo sucio",
			accept = "Has encontrado algo que parece un anillo en el cadáver de un enano Hierro Negro. Está cubierto de barro y restos secos y endurecidos, por lo que no se puede llevar ni se puede ver qué tipo de anillo es. Entre el barro, te parece entrever el brillo de metal precioso y quizás una gema.$B$BSi quieres ponértelo, tendrás que encontrar la manera de limpiarlo.",
			complete = "Pones el anillo en el Destellamatic 5200 y una moneda de plata en la ranura.$B$BLa máquina hace unos ruidos horribles y se sacude de un lado a otro; a saber qué está pasando ahí dentro...$B$BSe detiene de pronto con un sonoro \"¡ping!\" Aparece una cajita con un lazo rojo. ¡Parece que esta máquina envuelve para regalo!",
		},
		[2946] = {
			title = "A ver qué pasa",
			accept = "Queremos que lleves los discos en miniatura a las puertas selladas de Uldum. No estamos seguros de qué pasará, la verdad.$B$BSabemos que la operación entraña un riesgo. Aunque puede que no ocurra nada. Puede que tengas que usar los discos de algún modo. Es posible que las puertas se desbloqueen porque lleves los discos. Mantén una actitud abierta y prepárate para cualquier cosa.$B$BCuando averigües lo que pasa con los discos, vuelve a Forjaz. ¡Tendremos mucho que analizar!",
			complete = "Al tocar el pedestal, los minidiscos empiezan a zumbar y resplandecer. Te cosquillean las manos mientras surge otro Guarda de piedra frente a las puertas de Uldum.$B$B\"Saludos; soy el guardián de la entrada. Faltan las Placas de Uldum; incorpóralas a la estructura de los minidiscos y repite la secuencia de acceso. Gracias.\"",
		},
		[2947] = {
			title = "La devolución del anillo",
			accept = "Al abrir la caja del Destellamatic 5200 verás lo que estabas esperando: ¡un anillo reluciente! Cuando lo lleves sentirás que te recorre una fuerza mágica.$B$BEn la parte inferior está grabado, pequeño pero legible, el sello de Forjaz. Junto a él hay tres iniciales. \"TdK\". Pueden ser las iniciales del dueño del anillo o las del artesano que lo forjó. Quédate el anillo... o devuélveselo a esta persona. Tú verás...",
			complete = "¿Un anillo, dices? A ver... Sí, lo hice yo.$B$BTenía una tienda en Gnomeregan antes de todo el lío; a lo mejor me lo dejé al huir. El diseño es muy simple, hice varios de estos.$B$B¿Y lo tenían los Hierro Negro? Bueno, eso no sería nada nuevo. Pero eso es cosa de las autoridades, yo no puedo hacer nada.$B$BY respecto al anillo...",
		},
		[2948] = {
			title = "Mejora gnómica",
			accept = "Oye, $n, ¡puedo hacerte un anillo mejor que el que llevas! Como decía, ese diseño es muy sencillo. Ahora soy mucho mejor, así que por 30 monedas de plata de nada mejoraré tu anillo. Bueno, en realidad, es algo más de 30...$B$BAhora mismo estoy sin material. ¡Si me traes una barra de plata y una ágata musgosa, las usaré para añadir detalle a tu anillo y darle otro aire!$B$BConfía en mí.",
			complete = "¡Es justo lo que necesitaba! Algún día, cuando salga de este maldito lugar, haré los mejores abalorios de Azeroth. Hasta entonces, gracias por traerme todo esto. Te he cobrado solo el precio de coste del anillo.$B$BPor cierto, ¡aquí lo tienes!",
		},
		[2949] = {
			title = "La devolución del anillo",
			accept = "¡Al abrir la caja del Destellamatic 5200 verás un anillo reluciente! Cuando te lo pongas sentirás que te recorre una fuerza mágica.$B$BEn la parte interior está grabado, pequeño pero legible, el sello de Orgrimmar. Junto al sello hay algo más, pero incluso después de limpiar el anillo, solo se lee: \"NOG...\"$B$BPueden ser las iniciales del dueño o las del artesano que forjó el anillo. Quédate con el anillo o busca a \"NOG\". Tú verás...",
			complete = "¿Un anillo de Gnomeregan? A ver... No es mío, pero es muy interesante.$B$BLo suyo es muy curioso; durante años y años han sido unos torpes de cuidado y de repente están construyendo plataformas mejores que las nuestras.$B$B¿Que lo tenían los Hierro Negro? ¡Eso es aún más interesante! A lo mejor los gnomos les robaron los planos y los modificaron. Seguro que los enanos querrán vengarse; eso habría que investigarlo.$B$BOye, ese anillo...",
		},
		[2950] = {
			title = "Nogg mejora el anillo",
			accept = "No, no es que de pronto haya decidido que el anillo es mío. Normalmente no hago estas cosas, pero tu información sobre los Hierro Negro me ha sido muy útil. Mejoraré tu anillo de una forma que nunca se le habría ocurrido a su creador. Seguro que era un gnomo...$B$B¡Si me traes una barra de plata y una ágata musgosa, además de 30 monedas de plata, añadiré detalle a tu anillo y reforzaré su magia! ¿Te interesa la cosa?",
			complete = "Aquí tienes tu anillo mejorado, y gracias por la información sobre los Hierro Negro. Parece explicar muy bien cómo los gnomos se inspiraron de pronto con ideas de goblin.",
		},
		[2951] = {
			title = "¡El Destellamatic 5200!",
			accept = "Este aparato destaca entre los gnomos que se mantienen firmes frente a la locura que acecha fuera de la sala. Tiene una plaquita que dice: \"Destellamatic 5200\" y:$B$B\"¿La suciedad arruina sus destellos? ¡El Destellamatic 5200 devuelve el brillo de forma brillante! Inserte el objeto que desea limpiar e introduzca tres monedas de plata en la ranura. Espere unos momentos, ¡y ya está! ¡Sus objetos de valor aparecerán limpios y resplandecientes!\"",
			complete = "Insertas el objeto sucio y 3 monedas de plata en el Destellamatic 5200. Se pone en marcha como si le fuera la vida en limpiar el objeto; hace unos ruidos tremendos y parece que hasta la carcasa de la máquina se queja...",
		},
		[2952] = {
			title = "¡El Destellamatic 5200!",
			complete = "La máquina se para tan bruscamente como había arrancado. Se oye un \"ping\" y se abre la boca de la máquina. Dentro del Destellamatic 5200 hay una cajita con un lazo; parece que envuelve para regalo además de limpiar.$B$BSolo hay una forma de saber si el objeto está bien limpio...",
		},
		[2953] = {
			title = "El Destellamatic en acción",
			complete = "El Destellamatic 5200 se pone en marcha con sacudidas. El limpiador gnómico parece estar pulverizando el objeto del interior de la máquina.$B$BLa máquina se para con un \"¡ping!\" y la boca se abre para revelar una cajita muy bien envuelta.",
		},
		[2954] = {
			title = "El vigía de piedra",
			accept = "\"Saludos, soy un guardián de la entrada. A menos que ya tengas las Placas de Uldum integradas con los discos, no permitiré tu entrada en Uldum.\"$B$BLa aparición del vigía de piedra de Norgannon debe ser el objetivo de haberte enviado al desierto de Tanaris con los discos de platino. Para poder continuar, deberás escuchar lo que el vigía de piedra tenga que contarte.",
			complete = "La voz del guardián de piedra resuena con fuerza y autoridad:$B$B\"Los discos te serán devueltos una vez que accedas al pedestal. Cuando las Placas de Uldum obren en tu poder y estén integradas con el conjunto de discos que tienes, podrás acceder al complejo.\"",
		},
		[2962] = {
			title = "Necesitamos más material verdoso",
			accept = "Tu muestra no solo era insuficiente en cuanto a cantidad, además era impura.$B$BNecesitamos más material verdoso radiactivo. Es evidente que los troggs no han sido suficientemente irradiados. Tendrás que ir a Gnomeregan y traer restos radiactivos, directamente de la fuente. Estoy hablando de babosas, rondadores y horrores irradiados. Y ten cuidado: contener este tipo de restos es difícil. Es posible que tengas que hacer varios intentos hasta que hayas reunido una muestra adecuada.",
			complete = "<Ozzie te examina.> ¡Impresionante! ¡Todavía tienes todos los dedos! Venga, vamos a ver qué puede hacer esta cosa.",
		},
		[2963] = {
			title = "Presagios de Uldum",
			accept = "¡Saludos de nuevo, $n! Lo que descubriste en Uldaman ha interesado muchísimo a la Liga de Expedicionarios. Están intentando descifrar los discos de platino en miniatura que encontraste. ¡Deja que te diga que probablemente sea algo importante!$B$BKarnik el Historiador ha descubierto pistas importantes sobre los verdaderos orígenes del Valle de los Vigías en el Desierto de Tanaris. Quiere hablar contigo lo antes posible.",
			complete = "¡Me alegro de que sigas $ginteresado:interesada; en la exploración, $n! ¡Con tu talento natural y tu energía, podríamos descifrar secretos que nunca pensamos que fueran posibles!$B$BLos discos de Norgannon en Uldaman eran un depósito de vasta información; sólo se te permitió acceder a las capas superiores, por así decirlo, de la información almacenada. Se rumoreaba que los Creadores tenían más depósitos ubicados en todo Azeroth. Lo cual, nos lleva a Uldum...",
		},
		[2964] = {
			title = "Una tarea futura",
			accept = "Bueno $n... parece que hemos llegado a un punto muerto. Sabemos que necesitamos las Placas de Uldum, pero no tenemos ni idea de dónde pueden estar. Tendremos que estudiar un poco la situación para poder elaborar un buen plan de ataque. Yo tengo una ligera idea de por dónde empezar a buscar. Albergo la esperanza de que pronto te pidamos que vayas a recuperarlas.$B$BHay que informar al Alto Expedicionario de esto, $n. Sin duda, él desea una vez más agradecerte personalmente que hayas prestado tu ayuda a la Liga.",
			complete = "Entonces, todos estamos de acuerdo en que lo mejor es esperar hasta que podamos delimitar las áreas en las que es posible que estén las placas. Hemos llegado hasta aquí gracias a ti, $n, y espero que seas tú quien haga frente a los secretos de Uldum.$B$BHasta entonces, permíteme que te entregue este honorario que cubre los gastos que has realizado y un pellizquito más para ti. Vuelve pronto por aquí... Uldum nos espera a todos, joven.",
		},
		[2965] = {
			title = "Presagios de Uldum",
			accept = "Ah, $n, qué casualidad que hayas vuelto a mí. Tus descubrimiento en la excavación de Uldaman nos han dado mucho de qué hablar a los sabios. De hecho, estaba discutiendo con una druida llamada Nara Ferocrín cuando caí en la cuenta de que sus antiguos viajes podrían resultar importantes para el próximo paso que hemos de dar.$B$BMe gustaría que fueras a hablar con ella acerca de sus viajes al Valle de los Vigías en el Desierto de Tanaris. Ella te está esperando en el Alto de los Ancestros.",
			complete = "Hay un lugar, en lo más profundo del Desierto de Tanaris llamado Valle de los Vigías. Los discos que has recuperado... contienen unos glifos que hablan de un lugar llamado Uldum. Muchos creen que este lugar no es más que un mito.$B$BYo sé que no es cierto; Uldum existe. Yo he estado allí. Bueno... por allí cerca.$B$BHe aquí el quid de la cuestión, $n: creemos que hay una conexión entre los discos y Uldum, por eso queremos que vayas allí.",
		},
		[2966] = {
			title = "A ver qué pasa",
			accept = "A Sabio Buscador de la Verdad y a mí nos gustaría que llevaras los discos en miniatura que encontraste a las puertas selladas de Uldum. No estamos seguros de qué pasará, la verdad.$B$BSabemos que la operación entraña un riesgo. Aunque puede que no ocurra nada. Puede que tengas que usar los discos de algún modo. Es posible que las puertas se abran si llevas los discos. Mantén una actitud abierta y prepárate para cualquier cosa.$B$BCuando averigües lo que pasa vuelve a verme. Tendremos mucho de qué hablar.",
			complete = "Cuando tocas el pedestal, los discos en miniatura de Uldaman producen un zumbido y resplandecen en tu mochila. La sensación familiar de cosquilleo se extiende por tus manos mientras otro guardián de piedra cobra vida frente a las puertas de Uldum.$B$B\"Saludos. Soy un guardián de la entrada. Entre los discos utilizados para entrar faltan los discos correctos de entrada: las Placas de Uldum. Por favor, incorpora estas placas a la estructura de los discos y repite el proceso para poder entrar. Gracias.\"",
		},
		[2967] = {
			title = "Regresa a Cima del Trueno",
			accept = "Accedes de nuevo al pedestal y los discos de platino aparecen de repente en tu mochila.$B$BCon lo que te ha enseñado el vigía de piedra y los discos de platino de nuevo en tu poder, ha llegado el momento de regresar a Cima del Trueno e informar a Nara Ferocrín de tu hallazgo.",
			complete = "¿Te faltaban algunos discos? Vaya, es curioso pero parece que los Discos de Norgannon son solo una pieza más del conjunto; como las llaves de un llavero, si prefieres.$B$BSi encontramos las Placas de Uldum, podremos por fin acceder al mismísimo complejo de Uldum. Sin embargo, no sé si alegrarme o preocuparme.$B$BQuizás tengamos que arriesgar todo para asegurar que los secretos que alberga la tierra y que nos destruirían a todos sigan siendo eso, secretos.",
		},
		[2968] = {
			title = "Una tarea futura",
			accept = "Bueno $n... parece que hemos llegado a un punto muerto. Sabemos que necesitamos las Placas de Uldum, pero no tenemos ni idea de dónde pueden estar. Tendremos que estudiar un poco la situación para poder elaborar un buen plan de ataque. Yo tengo una ligera idea de por dónde empezar a buscar. Albergo la esperanza de que pronto te pidamos que vayas a recuperarlas.$B$BHay que informar a Sabio Buscador de la Verdad de esto, $n. Sin duda, él desea una vez más agradecerte personalmente que le hayas prestado tu ayuda.",
			complete = "Entonces, todos estamos de acuerdo en que lo mejor es esperar hasta que podamos delimitar las áreas en las que es posible que estén las placas. Hemos llegado hasta aquí gracias a ti, $n, y espero que seas tú quien haga frente a los secretos de Uldum.$B$BHasta entonces, permíteme que te entregue este honorario que cubre los gastos que has realizado y un pellizquito más para ti. Vuelve pronto por aquí... Uldum nos espera a todos, joven.",
		},
		[2969] = {
			title = "Libertad para todas las criaturas",
			accept = "Esos asquerosos del clan Tótem Siniestro están capturando dragones feéricos, $N Jer'kai y yo no sabemos qué están planeando hacer con ellos, pero está claro que no es nada bueno.$B$BY no podemos entrar en el campamento a liberar a los dragones a brazo partido, pero quizás, con tu ayuda...$B$BSi quieres ayudar y tienes amigos fuertes, libera a las criaturas de sus jaulas con esta llave y asegúrate de que logran escapar. Yo estaré a tu lado todo el tiempo. Jer'kai se quedará aquí.",
			complete = "¡Gracias a Elune, $n! Eres una bendición para todos nosotros y también para los dragones que salvaste. Jer'kai y yo jamás habríamos podido ayudarlos. Tu intervención en los asuntos de los Tótem Siniestro será recordada.$B$BAhora habla con Jer'kai... Tengo que preparar nuestra retribución. Que los dragones feéricos estén libres ahora, no quiere decir que vayan a seguir así. Jer'kai y yo seguiremos adelante con la ofensiva.",
		},
		[2970] = {
			title = "La justicia del castigo",
			accept = "Como ya te ha dicho Kindal, ella y yo llevaremos el conflicto a los Tótem Siniestro. Aún deberíamos ser capaces de eliminar a algunos tauren sin sufrir mucho, pero si te apetece ayudar y eres lo suficientemente capaz, nos encantaría que lo hicieras.$B$BYa habrás visto el campamento que tenemos debajo. Pues hay más hacia el este. Usa tus propias tácticas y causa todo el daño que puedas a los tauren. Podremos reunirnos aquí cuando hayan sentido el dolor de las flechas de Kindal y el de tus armas.",
			complete = "Kindal tenía razón sobre ti, $n. Tienes un don para esto. Tienes más experiencia que cualquiera de nosotros y te estamos agradecidos.$B$BEl clan Tótem Siniestro es mucho más hostil que muchos tauren... Me pregunto si el resto de su raza frunce el ceño antes sus actos. No me sorprendería. Como ya habrás notado, muchas razas de Azeroth están vinculadas a homólogos menos amables.$B$BPero dejaremos ese tema para otro día.",
		},
		[2972] = {
			title = "La justicia del castigo",
			accept = "Kindal y yo no tenemos aquí los medios para recompensar tu ayuda, pero no queremos que sientas que no la apreciamos. Llévate mi sello. Si alguna vez te encuentras en Teldrassil, ve al Templo de la Luna que está en el corazón de Darnassus. Allí encontrarás a la suma sacerdotisa Tyrande Susurravientos. El sello le hará saber que nosotras estamos bien y dará crédito a tu historia.$B$BAmbas te damos las gracias, $N.",
			complete = "Es una historia increíble, $n. Nos reconforta saber que no solo has ayudado a los dragonantes, sino también a una de nuestras sacerdotisas. Jer'kai acertó al enviarte a mí. Yo me aseguraré de que le sea devuelto su anillo. Tengo exploradores de camino a Feralas. Haré que investiguen esto durante su misión.$B$BGracias otra vez. Y, por favor, estás en tu casa.",
		},
		[2973] = {
			title = "El lustre de una nueva capa",
			accept = "Saludos, $c. He viajado con mis compañeros hasta Feralas en una misión de nuestros maestros de Orgrimmar.$B$BMi compañera Korrin adora la ropa nueva, así que voy a hacerle una nueva capa adornada con las ligeras alas de los dragones feéricos. ¿Podrías ayudarme? Los duendes dardo con las mejores alas están al oeste del Campamento Mojache.",
			complete = "¡Estupendo, $c! Estas nos vienen de maravilla. Hay suficientes para hacerle la capa a Korrin, ¡incluso puede que sobren! Gracias.$B$BEspero que tu viaje no fuera demasiado peligroso. Feralas no es conocido por su compasión precisamente, pero está claro que no te ha ido tan mal.$B$BGracias otra vez, $c.",
		},
		[2974] = {
			title = "Un descubrimiento siniestro",
			accept = "¡¿Qué?! ¿Que te has cruzado con tauren en esta zona? ¡Será broma! ¡¿Qué aspecto tenían?!$B$B¡El clan Tótem Siniestro! ¿Te has encontrado con ellos? Belgrom, uno de nuestros maestros, tiene un gran interés por ellos... ¡Hasta ha ofrecido una recompensa!$B$BTienes que volver, $c. Vuelve y tráeme sus cuernos... Tráeme montones de ellos, todos los que puedas. Pero no subestimes a los Tótem Siniestro. Ve con cuidado. Vuelve y mátalos, deja que los ríos de Feralas bajen enrojecidos con su sangre oscura.",
			complete = "Son unos buenos cuernos, $c. Buen trabajo. Dámelos. Y no te preocupes, me aseguraré de hablar con Belgrom en cuanto regresemos a Orgrimmar. Ya me has ayudado dos veces y por eso te doy mi marca. ¡Quizás pueda ayudarte en un futuro! Buena suerte.",
		},
		[2975] = {
			title = "Los ogros de Feralas",
			accept = "Los efectos de la invasión de la tribu Gordunni no pasan desapercibidos en la zona. Mira a tu alrededor, $N; su mera presencia marca esta tierra. Debemos hacerles retroceder antes de que empiecen a extenderse por todo Feralas.$B$BSigue el río hacia el norte y encontrarás su puesto de avanzada. Reduce su número, $N. Debemos hacerles ver que no son bienvenidos aquí.",
			complete = "Excelente, $n. La tierra se curará con el tiempo. No podemos rendirnos.",
		},
		[2976] = {
			title = "Un descubrimiento siniestro",
			accept = "¡¿Qué?!$B$BAh, así que te hablé de la recompensa... Eso me pasa por abrir la bocaza, no aprenderé nunca.$B$BBueno, supongo que, como tú hiciste el trabajo duro, es justo que recibas la recompensa. Llévate los cuernos. Yo haré que te los metan en una caja. Busca a Belgrom Destrozarroca en el Valle del Honor. Querrá saber qué viste y te recompensará por tu duro trabajo.$B$BCuídate, $c, y gracias de nuevo por todo.",
			complete = "¡¿Los Tótem Siniestro?! Esto es interesante. ¿Dices que te los encontraste mientras cazabas en Feralas? ¿De verdad?$B$BLos míos querrán oír tus noticias, $c. Cuéntame más detalles. Yo iré contando tus monedas mientras lo haces.$B$BY antes de irte, debes saber que te agradezco la información que me has proporcionado.",
		},
		[2977] = {
			title = "Regresa a Forjaz",
			accept = "Accedes de nuevo al pedestal y los discos de platino aparecen de repente en tu mochila.$B$BCon lo que te ha enseñado el vigía de piedra y los discos de platino de nuevo en tu poder, ha llegado el momento de regresar a Forjaz e informar a la Liga de Expedicionarios de tu hallazgo.",
			complete = "¿Te faltaban algunos discos? Vaya, es curioso pero parece que los Discos de Norgannon son solo una pieza más del conjunto; como las llaves de un llavero, si prefieres.$B$BSi encontramos las Placas de Uldum, ¡podremos por fin acceder al mismísimo complejo de Uldum! Imagínatelo, explorar el lugar en el que trabajaron los Creadores sin necesidad de utilizar una gran pala!$B$BY con esto no quiero decir que tenga algo de malo utilizar palas, cavar y todo eso.",
		},
		[2978] = {
			title = "El pergamino Gordunni",
			accept = "Cuando recoges el sucio pergamino, notas que parece describir algún tipo de reunión o ceremonia. A Rok Orhan le interesará este pergamino por lo que pueda significar para los Gordunni.",
			complete = "Este pergamino... ¿Dices que lo encontraste en la Avanzada Gordunni?",
		},
		[2979] = {
			title = "Una ceremonia oscura",
			accept = "Parecen ser planes para algún tipo de ceremonia oscura, $N. Por lo que puedo entender, este es un ritual celebrado por los Señores de la Magia Gordunni.$B$BEncuentra a uno de estos Señores de la Magia y quítale su orbe.$B$BEl orbe de un mago encierra un gran poder. Nos ayudará a descubrir más sobre esta ceremonia y sobre la magia de los Gordunni.",
			complete = "Este orbe nos proporcionará más información sobre los Gordunni... información que utilizaremos para planear su caída, $n.",
		},
		[2980] = {
			title = "Los ogros de Feralas",
			accept = "Ahora que has demostrado que eres $gun auténtico guerrero:una auténtica guerrera;, confío en que tengas el valor para continuar tu misión.$B$BViaja a las Altas Tierras Salvajes, al suroeste de aquí. Ahí encontrarás unas estructuras abandonadas cuyos restos yacen en una tierra que antaño perteneciera a los elfos de la noche. Busca esas ruinas y, cuando veas árboles marchitos y tierra profanada, encontrarás a los Gordunni. Hazlos retroceder.$B$BEsos ogros son mucho más fuertes que los que has afrontado hasta ahora, $N, ten cuidado.",
			complete = "Has demostrado que se puede confiar en ti, $n.",
		},
		[2981] = {
			title = "Una amenaza en Feralas",
			accept = "Feralas es el lugar ideal para que cualquier $c ponga a prueba sus cualidades. Allí los ogros Gordunni son los amos y señores y cada día crecen en número. Hay que detenerlos antes de que pongan en peligro nuestra presencia en Feralas.$B$BConozco a una guerrera que vive en el Campamento Mojache, en Feralas. Se llama Rok Orhan. Ve a buscarla. Ella te dará más detalles del estado de la situación.",
			complete = "Así que te envía Belgrom. Pues llegas justo a tiempo, $r.$B$BDeja que te explique la situación y luego decides si estás a la altura del desafío... Claro que si te envía Belgrom, es evidente que valor no te falta.",
		},
		[2982] = {
			title = "Las Altas Tierras Salvajes",
			accept = "Aunque es peligroso, Troyas y yo hemos estado investigando las ruinas que cubren los bosques de Feralas.$B$BPero últimamente, Troyas ha empezado a ir solo a las Altas Tierras Salvajes y eso me preocupa mucho. Los ogros Gordunni han invadido la zona y no son muy simpáticos con los que entran en su territorio.$B$BEsperaba que pudieras viajar a las ruinas, que están al sureste, y que eliminaras a algunos de los ogros. Así el área será más segura para Troyas. Y yo te lo agradecería mucho.",
			complete = "Te agradezco mucho lo que has hecho por mí.$B$BPero, por favor, ni una palabra a Troyas sobre esto.",
		},
		[2983] = {
			title = "La llamada del fuego",
			accept = "Ha pasado algún tiempo desde tu última prueba, $N. Hasta el momento has sido paciente en tus estudios, pero llegó el momento de que adquieras mayores poderes... es hora de que aprendas el auténtico poder. El elemento del fuego será tuyo si estás $gdispuesto:dispuesta; a pagar el precio.$B$BBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las devastadas tierras de los elfos de la noche, habrás ido demasiado lejos.",
			complete = "Así que... te manda Swart, ¿eh?$B$BBien. Siempre he confiado en Swart. Si te envía a mí, es que estás $glisto:lista; para participar en la siguiente sapta... la sapta de fuego.$B$BYa puedo ver esa chispa, esa llama de impaciencia en tus ojos. Has probado el poder y ahora estás listo para adquirir más. Paciencia, $n. Recuerda lo que la tierra te enseñó. El poder y la destrucción llegan fácilmente, pero siempre has de saber cuándo detener tu mano.",
		},
		[2984] = {
			title = "La llamada del fuego",
			accept = "Ha pasado tiempo desde tu última prueba, $N. Hasta ahora has demostrado paciencia en tus estudios, pero ha llegado el momento de que aprendas algo más. Debes aprender de la destrucción... y el caos. De un elemento: el fuego. Podrás comprenderlo, si estás $gdispuesto:dispuesta; a pagar el precio.$B$BBusca a Kranal Fiss en Los Baldíos. Vive en una pequeña casa al norte de El Cruce. Pero cuidado: si llegas hasta las tierras de los elfos de la noche, habrás ido demasiado lejos.",
			complete = "Así que... te manda Narm, ¿eh?$B$BBien. Siempre he confiado en Swart. Si te envía a mí, es que estás $glisto:lista; para participar en la siguiente sapta... la sapta de fuego.$B$BYa puedo ver esa chispa, esa llama de impaciencia en tus ojos. Has probado el poder y ahora estás listo para adquirir más. Paciencia, $n. Recuerda lo que la tierra te enseñó. El poder y la destrucción llegan fácilmente, pero siempre has de saber cuándo detener tu mano.",
		},
		[2985] = {
			title = "La llamada del agua",
			accept = "$gDispuesto:Dispuesta; pareces para la prueba siguiente, $N. Paciencia en tus estudios has mostrado pero de aprender aún más la hora ha llegado. Ha llegado la hora de que aprendas cosas sobre la pureza del agua.$B$BBusca a Islen Vidente del Agua en Los Baldíos. Se encuentra por la costa oriental, al sur del Río Furia del Sur y de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, $N.",
			complete = "El viento se te acerca rápidamente desde el horizonte; la tierra es firme bajo tus pies; y tu espíritu ya está calentado por el fuego, yo diría que es hora de que aprendas sobre la pureza del agua.$B$BTu camino te ha llevado hasta aquí y tu espíritu te dará la fuerza para seguir adelante. Pero el primer paso es tuyo.",
		},
		[2986] = {
			title = "La llamada del agua",
			accept = "Mucho tiempo ha pasado desde que a prueba te pusieron, $N. Paciencia en tus estudios hasta ahora has mostrado pero de aprender aún más la hora ha llegado. Ha llegado la hora de que aprendas cosas sobre la pureza del agua.$B$BBusca a Islen Vidente del Agua en Los Baldíos. Se encuentra por la costa oriental, al sur del Río Furia del Sur y de Trinquete. La encontrarás en su cabaña de pesca. Que la Fortuna te sea favorable, $N.",
		},
		[2987] = {
			title = "El cobalto Gordunni",
			accept = "Acabo de llegar a Feralas y he oído que los ogros Gordunni del norte tienen minerales interesantes. No sé qué estarán tramando, ¡pero protegen sus minerales casi de forma sospechosa! No los dejan por ahí, no, los entierran para que gente como yo no consiga echarles el guante.$B$BSi quieres ayudarme, te daré mi pala. Ve a la Avanzada Gordunni que hay al norte de aquí y desentiérrame un poco de cobalto Gordunni. Cuando veas un brillo azul, ¡empieza a cavar!",
			complete = "¡Son perfectas! Me las llevaré conmigo en mi viaje, $n. Seguro que consigo encontrar a alguien que me pague bien por este cobalto.$B$BTen. Por las molestias.",
		},
		[2988] = {
			title = "Las jaulas de Secacorteza",
			accept = "¡El hijo de nuestro mejor grifo ha desaparecido! El hijo de Alarrápida, Picoafilado, se perdió hace unos días cuando cazaba. Creemos que lo tienen los trols.$B$B¡Ayúdanos! Busca entre las jaulas de los dos poblados Secacorteza, a ver si lo encuentras.",
			complete = "¿Que no has encontrado a Picoafilado? Eso es una mala noticia; es el jefe de la futura generación de grifos. Sin él se perderá gran parte de su fuerza y empuje.",
		},
		[2989] = {
			title = "El Altar de Zul",
			accept = "Los Secacorteza no tienen a Picoafilado. A lo mejor fueron los trols Vilrama. Busca al grifito en el Altar de Zul, en el extremo occidental del territorio Vilrama.",
			complete = "¿No has encontrado a Picoafilado? Eso es malo y bueno.$B$BAl menos no estaba en el altar de los sacrificios.$B$BGracias por tu ayuda, aunque me queda la tarea más difícil por delante.",
		},
		[2990] = {
			title = "Thadius Sombramacabra",
			accept = "Llévale esta pluma al adivino Thadius Sombramacabra. Se fue de Pico Nidal hace años para estudiar ciencias oscuras, pero sigue siendo un Martillo Salvaje.$B$BA lo mejor puede ayudarnos a encontrar a Picoafilado.$B$BEsta pluma estaba en su nido. Con ella y un poco de suerte, Thadius usará sus poderes de adivinación para localizar al grifo.$B$BSuerte, $N. Thadius vive en Las Tierras Devastadas, en la torre de los magos del Castillo de Nethergarde.",
			complete = "Ah, sí. Esta pluma pertenece a un noble grifo destinado a grandes cosas... si llega a la edad adulta.$B$BEscúchame si quieres encontrarlo, $c...",
		},
		[2991] = {
			title = "Medallón de Nekrum",
			accept = "Voy a averiguar en dónde está tu grifo, pero primero haz algo por mí. Hay un trol en Zul'Farrak, Nekrum Cometripas, que tiene un medallón que me gustaría estudiar. Tráeme ese medallón y usaré mis poderes para encontrar a Picoafilado.$B$BZul'Farrak está al otro lado del océano, al oeste, en el desierto de Tanaris.",
			complete = "Se dice que el medallón concede larga vida a los trols, pero a un precio muy alto. Espero poder extraer sus poderes sin sufrir sus desagradables efectos secundarios.$B$BAgradezco tu ayuda, $n. Ahora cumpliré mi promesa.",
		},
		[2992] = {
			title = "El ritual de adivinación",
			accept = "Hazme sitio mientras realizo el ritual de adivinación. Encontraré la conexión entre la pluma y su dueño y la seguiré hasta llegar a Picoafilado.$B$BBueno... si todo sale bien. Si no, pues... Cierra los ojos.",
			complete = "El ritual ha salido bien; he visto a Picoafilado y puedo decirte dónde encontrarlo.",
		},
		[2993] = {
			title = "Regresa a las Tierras del Interior",
			accept = "Picoafilado está enjaulado en un precipicio en la cumbre de Jintha'Alor, en las Tierras del Interior. La llave de la jaula está en poder de la sacerdotisa vil Hexx, suma sacerdotisa de los trols Vilrama.$B$BYa está. He terminado. Te deseo suerte en tu misión, $n.",
			complete = "¿Qué ha dicho Sombramacabra?$B$B¿Cómo que los Vilrama tienen a Picoafilado? ¡Eso es intolerable! ¡Tenemos que rescatarlo!",
		},
		[2994] = {
			title = "Salvar a Picoafilado",
			accept = "¡Tenemos que rescatar a Picoafilado!$B$B¡Debes llegar hasta Jintha'Alor, en el corazón del territorio Vilrama, conseguir la llave que tiene la sacerdotisa vil Hexx, encontrar la jaula y liberar al grifo!",
			complete = "Los padres de Picoafilado acaban de regresar con su hijo... ¿Eh? No lloro, es que se me ha metido algo en el ojo...$B$BTe agradecemos infinitamente lo que has hecho, $n. Los grifos de Pico Nidal y sus jinetes cantarán tus alabanzas durante mucho, mucho tiempo.",
		},
		[2995] = {
			title = "Líneas de comunicación",
			accept = "La Avanzada Quel'Danil es el centro de comunicación de los elfos nobles de las Tierras del Interior. Sus embajadores están trabajando para establecer relaciones con otras razas con las que compartir sus conocimientos sobre los trols Secacorteza que viven en la zona sur de las Tierras del Interior. Todos los documentos relativos a sus comunicaciones se guardan en la avanzada.$B$BTenemos que evitar las alianzas entre Vallealto y otros pueblos, $N.$B$BDestruye los documentos de Vallealto. Tenemos que quemar sus líneas de comunicación... literalmente.",
			complete = "Muy bien, $n. Mientras en Vallealto intentan recuperar la información perdida, nosotros podremos idear más modos de cortar sus comunicaciones.",
		},
		[2996] = {
			title = "Buscando a Strahad",
			accept = "Te he enseñado mucho, pero ha llegado el momento de que cambies de instructor. Se llama Strahad y vive en Trinquete. Es humano, pero no vayas a creer por eso que es débil. Su aspecto no refleja su poder; te enseñará invocaciones más potentes. Lo encontrarás en el puerto de Trinquete, cerca de su torre.",
			complete = "Un día ajetreado en Trinquete, ¿no? Cómo disfruto viendo el trabajo de una ciudad portuaria. Tanto misterio, tanta aventura... tanta ignorancia.$B$B¿Es odio lo que veo en tus ojos, $n? Bien, le daremos un buen uso.",
		},
		[2997] = {
			title = "Escrito sobre divinidad",
			accept = "Hola, $N. Sé que estás $gocupado:ocupada; ayudando a las gentes de Dun Morogh, pero cuando tengas tiempo, deberías ir a Forjaz y hablar con una persona muy respetada por aquí: Tiza Forjabatalla. Los paladines más jóvenes deben acudir a ella cuando llega el momento de que aprendan más sobre la Luz y sobre lo que se espera de ellos.$B$BLa encontrarás escaleras arriba, en la Sala de los Misterios. Por si nunca has estado allí, está en La Sala Mística. Buena suerte, $N.",
			complete = "Saludos, $n. Espero que la Luz te muestre el verdadero camino y te mantenga a salvo del mal.",
		},
		[2998] = {
			title = "Escrito sobre divinidad",
			accept = "Saludos, $Ghermano:hermana;. Duthorian Rall, uno de nuestros paladines más influyentes, estuvo hablando de ti hace poco. Le oí decir que era hora de ponerte a la prueba... Y bueno, también dijo algo sobre lo bien que estás yendo hasta ahora y eso.$B$BSi yo fuera tú, iría a Ventormenta y hablaría con él. Seguramente estará en la Catedral de la Luz. Ahí es donde pasa la mayor parte de su tiempo.",
			complete = "Es hermoso estar en Ventormenta, ¿no?$B$BEl momento no podría haber sido mejor, $n.",
		},
		[2999] = {
			title = "Escrito sobre divinidad",
			accept = "Hola, $N. Sé que estás $gocupado:ocupada; ayudando a las gentes de Dun Morogh, pero cuando tengas tiempo, deberías subir las escaleras y hablar con una persona que es muy respetada por aquí: Tiza Forjabatalla. Los paladines más jóvenes deben acudir a ella cuando llega el momento de que aprendan más sobre la Luz y sobre lo que se espera de ellos.",
			complete = "Saludos, $n. Espero que la Luz te muestre el verdadero camino y te mantenga a salvo del mal.",
		},
		[3000] = {
			title = "Escrito sobre divinidad",
			accept = "Hola, $N. Sé que estás $gocupado:ocupada; ayudando a las gentes de Azeroth, pero cuando tengas tiempo, deberías volver a Forjaz y hablar con una de las personas más respetadas de tu casa: Tiza Forjabatalla. Los paladines enanos más jóvenes deben acudir a ella cuando llega el momento de que aprendan más sobre la Luz y sobre lo que se espera de todos nosotros.$B$BLa encontrarás escaleras arriba, en la Sala de los Misterios, que a su vez se encuentra en La Sala Mística.",
			complete = "Te saludo y te doy la bienvenida, $n.",
		},
		[3001] = {
			title = "Buscando a Strahad",
			accept = "Yo te he instruido hasta ahora pero ha llegado el momento de que cambies de instructor. Se llama Strahad y vive en Trinquete. Es un humano, pero no vayas a creer por eso que es débil ni que ha de ser tu enemigo... al menos de momento... Es muy poderoso y merecedor de respeto, y puede enseñarte hechizos de invocación superior, hechizos que creo que estás $gpreparado:preparada; para conocer. Ve a buscarlo.$B$BLo encontrarás en el puerto de Trinquete, cerca de su torre.",
			complete = "Un día ajetreado en Trinquete, ¿no? Cómo disfruto viendo el trabajo de una ciudad portuaria. Tanto misterio, tanta aventura... tanta ignorancia.$B$B¿Es odio lo que veo en tus ojos, $n? Bien, le daremos un buen uso.",
		},
		[3002] = {
			title = "El orbe Gordunni",
			accept = "Aunque conozco bien a mi enemigo, soy solo un guerrero, $N. No puedo ni empezar a decirte de qué es capaz este orbe.$B$BPero conozco a un mago de Orgrimmar que podrá decirnos más cosas sobre el orbe. Llévaselo a él.",
			complete = "Fascinante, $n.$B$BEste orbe es muy potente, pero también muy peligroso.",
		},
		[3022] = {
			title = "Un envío frágil",
			accept = "$N, veo que ansías dedicarte a mi valerosa causa. ¡Pues claro que puedes hacer algo por mí!$B$BLlévale esta caja de huevos a Erelas Cieloámbar. Él es un druida que los sabe cuidar muy bien pues ayuda a salir del cascarón a los pequeños hipogrifos y después los instruye. Lo encontrarás en Teldrassil, en una pequeña aldea situada al sur que se llama Rut'theran.",
			complete = "Gracias por tu ayuda, $n. La población de hiprogrifos no crecería de no ser por nosotros. Pero seguro que eso ya lo sabes pues has estado en Feralas y has visto con tus propios ojos la devastación causada por los Gordunni.$B$BBien, como puedes observar, tengo mucho trabajo así que será mejor que te vayas.$B$BGracias de nuevo, $n.",
		},
		[3042] = {
			title = "Temple trol",
			accept = "Los trols Furiarena de Zul'Farrak utilizan arenisca para crear sus materiales de temple y yo también puedo utilizarlo para templar mis creaciones. Es muy valorado entre los expertos, así que si me traes un buen suministro de temple, te recompensaré muy bien.$B$BZul'Farrak está al noroeste de Gadgetzan. Buena suerte.",
			complete = "¡Ah, es un temple excelente! ¡Y hay mucho! ¡Podré trabajar muchos días antes de que se acabe!$B$BGracias, $n. Por favor, acepta esto como pago.",
		},
		[3062] = {
			title = "Corazón oscuro",
			accept = "Edana Garfaodio es la reina de las arpías de Nortearroyo que viven en las ruinas del oeste. Es el mal encarnado. He oído que su corazón es de cristal. Carece de sentimientos... aparte del odio que siente por todo lo que no sea ella. Debes enfrentarte a Edana y traerme su corazón oscuro.$B$BHe oído hablar de un cuerno que llevan esas arpías... Si lo tocan en las Piedras Garfaodio, en la parte norte de las ruinas, su reina acude.$B$BImagina su sorpresa cuando vea que no son sus semejantes quienes la llaman, sino la muerte.",
			complete = "Debes saber que Edana está verdaderamente muerta. Guardaré este corazón de recuerdo, por lo que representa. Gracias, $n.",
		},
		[3063] = {
			title = "Venganza contra Nortearroyo",
			accept = "En mis tiempos fui un avezado cazador. No había criatura a la que yo temiera. Hasta que...$B$BUn día estaba en el bosque, afilando mi espada después de una dura batalla y caí en una emboscada. Unas arpías me rodearon y... casi no lo cuento. Tuve que arrastrarme para ponerme a salvo.$B$BTodavía puedo oír el eco de sus gritos...$B$BDespués de aquello, no he vuelto a ser el mismo. Han pasado muchos años, pero el odio sigue hirviéndome en las venas. Debo desquitarme.$B$BPuedes encontrar a las arpías de Nortearroyo al oeste de aquí. Véngame, $N.",
			complete = "Gracias, $n. Has traído mucha paz a la conciencia de un viejo tauren.",
		},
		[3065] = {
			title = "Tablilla simple",
			accept = "Ah, mientras estabas fuera llegó un papiro para ti, $N.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de guerreros, Frang. Querrá tener unas palabras contigo cuando estés $glisto:lista;. Lo encontrarás a las puertas de El Cubil, al abrigo de la sombra.",
			complete = "Cuando sigas instruyéndote en las artes $gdel:de la; $c encontrarás este lugar muy adecuado. Si tienes cualquier duda no temas en preguntar a cualquiera y cuando te sientas preparado vuelve a verme para recibir instrucción. Tengo el mismo dominio que cualquier otro $c del Valle y puedo transmitirte ese conocimiento... por un precio, claro.",
		},
		[3082] = {
			title = "Tablilla con grabados",
			accept = "Ah, mientras estabas fuera llegó una tablilla para ti, $N.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte de la instructora de cazadores, Jen'shan. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Ahora les enseñamos todo eso y ellos nos enseñan otras cosas. Nos hacemos una única raza... o casi. Somos aliados desde hace mucho, así que recuerda ayudarles. Y Jen'shan recordará ayudarte.$B$BJen'shan te instruye en las artes $gdel:de la; $c, te instruye bien. No olvides nunca, <el(la> $c es muy respetado en la tribu. Tú ir a tener un importante papel en el futuro... no olvides nunca.$B$BCuando lo necesites, ven a Jen'shan. Ella te enseña todo lo que pueda cuando crea que estás $gpreparado:preparada;.",
		},
		[3083] = {
			title = "Tablilla encriptada",
			accept = "Ah, mientras estaba fuera llegó una tablilla para ti, $N.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de pícaros, Rwag. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Hasta que llegue ese momento, estarás bajo mi tutela. Te mostraré las cuerdas como dicen algunas personas. Siempre que te sientas $gpreparado:preparada;, ven a verme y me ocuparé de capacitarte más. Hasta entonces, practica tus habilidades y mantenlas perfeccionadas al filo de la navaja. Nunca sabrás cuándo necesitarás incluso la habilidad más insignificante.",
		},
		[3084] = {
			title = "La tablilla con runas grabadas",
			accept = "Ah, mientras estaba fuera llegó una tablilla para ti, $N.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de chamanes, Shikrik. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Como seguramente ya sabrás, los elementos nos confieren nuestro poder. Fuego, tierra, agua y aire... esas son nuestras herramientas.$B$BNuestra fuerza nace de los espíritus de nuestros antepasados. Somos los líderes de nuestro pueblo. Lo que Thrall es para la Horda somos nosotros para los poblados y ciudades que visitamos. Buscan en nosotros sabiduría y protección. Para estar más $gpreparado:preparada; debes entrenar e instruirte a menudo. Cuando sientas que has ganado más poder ven a verme y te enseñaré todo lo que pueda.",
		},
		[3085] = {
			title = "Tablilla sacralizada",
			accept = "Ah, mientras estabas fuera llegó una tablilla para ti, $N.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte del instructor de sacerdotes, Ken'jai. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "A medida que te pruebes a ti $gmismo:misma;, descubrirás que cada vez tienes un mejor control sobre los espíritus; los estarás llamando para grandes y grandiosas cosas... ahí es donde entra el viejo Ken'jai. Ven a hablar con el viejo Ken'jai cuando te sientas $glisto:lista;. Si los espíritus están de acuerdo, entonces veremos como enseñarte habilidades más poderosas... pero solo si los espíritus están de acuerdo.$B$BVe ahora, habla con el resto de la gente del Valle. Háblame de nuevo más tarde.",
		},
		[3086] = {
			title = "Tablilla glífica",
			accept = "Ah, mientras estabas fuera llegó una tablilla para ti, $N.$B$BLéela cuando tengas tiempo, si no me equivoco viene de parte de la instructora de magos, Mai'ah. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Tú estar entre los seres más poderosos del planeta, $n... no hay duda. Y todos lo saben... ¡lo saben bien!$B$BPero debes estar $gcansado:cansada;! No haber orco, ni elfo, ni enano al que tú temas... pero haber cosas que no puedes ver. Magia ser poderosa. Te obliga a hacer cosas que no quieres hacer. Te hace creer que eres más poderoso de lo que ser. Ten paciencia. Sé $glisto:lista;.$B$BCuando creas que estás $gpreparado:preparada; para instruirte vuelve con Mai'ah. Te enseña lo que estás listo para aprender, sin problema.",
		},
		[3087] = {
			title = "Papiro con grabados",
			accept = "Ah, mientras estabas fuera llegó un papiro para ti, $N.$B$BLéelo cuando tengas tiempo. Si no me equivoco, viene de parte de la instructora de cazadores, Jen'shan. Quiere hablar contigo cuando estés $glisto:lista;.",
			complete = "Cuando terminemos de hablar, deberías hablar con el resto de los ciudadanos del Valle. Te piden que hagas cosas por ellos... cosas que pondrán a prueba tu habilidad y te enseñarán algunos de los peligros de esta tierra.$B$BA medida que crezcas en experiencia y sabiduría, necesitarás que Jen'shan te muestre mejores técnicas y habilidades. Vuelve a Jen'shan a menudo. Te haré saber lo que puedo enseñarte.",
		},
		[3088] = {
			title = "Papiro encriptado",
			accept = "Ah, mientras estabas fuera llegó un papiro para ti, $N.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de pícaros, Rwag. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Ahora que sabes dónde estoy, debo avisarte: la Mano Destrozada me pidió que te cuidara. Quieren que te entrene y te mantenga $ginformado:informada; de todo lo que puedan necesitar. Incluso si aún no estás $ginteresado:interesada; en ayudarlos, lo cual sería muy tonto por tu parte, haré lo que pueda para capacitarte... por una pequeña tarifa. Vuelve a verme en cualquier momento que creas estar $glisto:lista; y veremos lo que puedes aprender.",
		},
		[3089] = {
			title = "El papiro con runas grabadas",
			accept = "Ah, mientras estabas fuera llegó un pergamino para ti, $N.$B$BLéelo cuando tengas tiempo, si no me equivoco viene de parte del instructor de chamanes, Shikrik. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Serás el medio que utilizarán nuestros antepasados para comunicarse. Tendrás el poder de los elementos a tu entera disposición. Despedazar a tus enemigos será como un juego de niños y sanar a tus aliados tan fácil como respirar. Recuerda todo esto cuando afrontes nuevos retos y vuelve a verme siempre que quieras. Me quedaré aquí para enseñarte nuevos hechizos y para mostrarte el camino correcto cuando estés $glisto:lista;.",
		},
		[3090] = {
			title = "Papiro corrupto",
			accept = "Ah, mientras estabas fuera llegó un papiro para ti, $N.$B$BSiempre que puedo procuro evitar el trato con brujos, pero creo que deberías leerlo cuando tengas tiempo. Si no me equivoco viene de parte del instructor que te acaba de ser asignado, Nartok. Querrá tener unas palabras contigo cuando estés $glisto:lista;.",
			complete = "Y ahora también te has unido a nuestras filas. No lo malinterpretes, $n. El hecho de que tengas acceso al poder del que muchos estarán celosos no significa que te aceptarán fácilmente. Thrall permite que los de nuestra especie entren en Orgrimmar porque todavía somos sus parientes: no puede darnos la espalda o nos volveríamos tan patéticos como los humanos que lo esclavizaron. Mi punto es: ten cuidado. Puedes ser poderoso, pero si eres tonto, entonces estás muerto.$B$BSi necesitas entrenamiento en hechizos, regresa a mí.",
		},
		[3091] = {
			title = "La nota simple",
			accept = "$N, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de guerreros Harutt. Si la nota es suya, será mejor que la leas pronto.|n",
			complete = "Todos tenemos un papel en la tribu y todos pasamos los mismos ritos; no dejes que tu orgullo te diga lo contrario.$B$BYo me quedo aquí para entrenar a los guerreros que buscan la gloria del combate. Ven a verme cuando quieras, te daré la instrucción que pueda. Cuentas con la bendición de la tribu, $n.",
		},
		[3092] = {
			title = "La nota con grabados",
			accept = "$N, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de cazadores Lanka. Si la nota es suya, será mejor que la leas pronto.$B",
			complete = "Y es mi trabajo asegurarme de que estés $gpreparado:preparada; enseñándote los conceptos básicos de nuestra profesión: cómo domesticar a tu mascota, cómo disparar tu rifle y muchas otras habilidades que serán necesarias.$B$BLos cazadores son una parte importante de nuestra tradición e historia, $n. Harías bien en recordar lo importante que es para la tribu. Serás $grespetado y reverenciado:respetada y reverenciada; si sirves bien a nuestra gente.",
		},
		[3093] = {
			title = "La nota con runas grabadas",
			accept = "$N, hace un momento te vino a buscar una mensajera. Creo que venía de parte de la instructora de chamanes Meela. Si la nota es suya, será mejor que la leas pronto.$B",
			complete = "Nos reuniremos muchas veces en los próximos días. Espero que cada vez dejes mi compañia un poco más $gpoderoso:poderosa;... un poco más $gpreparado:preparada;. Como la Llama Eterna, tu espíritu arderá brillante y caliente.$B$BVete ahora, $n. Ve y ponte a prueba. Estaré aquí para ti cuando lo necesites.",
		},
		[3094] = {
			title = "La nota verdeante",
			accept = "$N, hace un momento te vino a buscar una mensajera. Creo que venía de parte del instructor de druidas Gart. Si la nota es suya, será mejor que la leas pronto.|n",
			complete = "Aunque estamos relacionados, no esperes una buena acogida de los elfos de la noche; su orgullo no les deja ver, aunque eso no es problema nuestro. Preocúpate solo de las enseñanzas de la Madre Tierra y de las lecciones que te daré.$B$BVen a verme a menudo, $n. Descubrirás que la Madre Tierra recompensa a los más aplicados.",
		},
		[3095] = {
			title = "Un pergamino simple",
			accept = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello del instructor de guerreros Dannal. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.",
			complete = "Estaré aquí para entrenarte a medida que crezcas en experiencia... ven tan a menudo como quieras. Cobro una tarifa mínima, pero encontrarás que todo lo que puedo enseñarte vale la pena.$B$BVe ahora y prueba tu habilidad. A medida que ganes experiencia, sabrás muchas más cosas, algunas de las cuales no puedo contarte aquí ni ahora. Solo debes saber que Sylvanas necesitará guerreros con tu tipo de fuerza en el futuro. Serás la columna vertebral de nuestra salvación. No lo olvides.",
		},
		[3096] = {
			title = "Un pergamino codificado",
			accept = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de David Trias, el instructor de pícaros. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.",
			complete = "Paso la mayor parte del tiempo en la posada. Me fijo en las caras nuevas, por si aparece alguien prometedor. Si no te metes en líos, haré lo posible por enseñarte algunas cosas. Vuelve cuando quieras y veremos si estás $glisto:lista; para una o dos habilidades nuevas.",
		},
		[3097] = {
			title = "Un pergamino sacralizado",
			accept = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello del instructor de sacerdotes Duesten. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.",
			complete = "Solo hay una cosa que debes saber: hemos sobrevivido solo con voluntad. Es la fe en nosotros mismos lo que nos separa de los demás y, con nuestros poderes, provocaremos un gran cambio en todo Azeroth. Los débiles acabarán dependiendo de ti. Los leprosos te llamarán señor. Y los ignorantes se volverán a ti en busca de guía. Mi deber es asegurarme de que tienes las herramientas necesarias para que, cuando llegue el momento, estés $gpreparado:preparada;. Cuando adquieras más experiencia, búscame. Si estás $gpreparado:preparada;, te enseñaré poderes mayores.",
		},
		[3098] = {
			title = "Un pergamino glífico",
			accept = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de la instructora de magos Isabella. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.",
			complete = "Debes volver a mí a menudo si quieres adquirir el poder necesario para destruir a quienes se nos oponen. Aún estás $gsometido:sometida; a las reglas de la magia, $n. La corrupción te seguirá como un lobo hambriento en la noche. Te darás cuenta de que su caricia es como una adicción, como $guna antigua:un antiguo; amante que aún quiere estar a tu lado. Pero esas cosas pueden evitarse. Esas cosas solo te controlan si se lo permites.$B$BAhora, vete. Y vuelve a mí cuando seas más fuerte.",
		},
		[3099] = {
			title = "Un pergamino corrupto",
			accept = "Oye, mientras estabas por ahí ocupándote de la Plaga esa, llegó este pergamino para ti. Debe de ser importante porque parece que lleva el sello de Maximillion, el instructor de brujos. Yo me tomaría un momento para leerlo antes de ponerme en marcha otra vez.",
			complete = "Mencioné que un esclavo sigue siendo esclavo, sin importar el amo. ¿Te acuerdas? Ambos sabemos que es ese tipo de control, ese tipo de poder, el que ahora nos impulsa. Buscamos que las criaturas nos sirvan. Sabemos que somos más poderosos y merecemos más respeto del que otros nos dan... y por eso ahora buscamos tomarlo.$B$BSeré tu aliado en esta lucha, la lucha por nuestra propia libertad. Libertad para buscar nuestras propias lealtades. Cuando te sienta $gpreparado:preparada;, vuelve a mí y te enseñaré todo lo que sé.",
		},
		[3100] = {
			title = "Una carta simple",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia de Llane, uno de nuestros instructores de guerreros locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "Ponte en pie, estudia el terreno y vuelve conmigo cuando necesites formación. Estaré aquí de día o de noche.$B$BLos Caballeros de la Mano de Plata han hecho bien en hacer que este lugar sea bastante seguro, pero cuando conozcas a los otros ciudadanos, creo que encontrarás que todos tienen problemas con los que les vendría bien un poco de ayuda: ayuda que un $c puede brindarles. Buena suerte.",
		},
		[3101] = {
			title = "Una carta consagrada",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia del hermano Sammuel, uno de nuestros instructores de paladines locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "Debes saber que eres un símbolo para muchos; no lo olvides nunca. La Luz Sagrada brilla en ti, visible tanto para amigos como para enemigos.$B$BA medida que adquieres sabiduría y poder, tendrás que aprender otras facultades. Cuando quieras continuar tu instrucción, ven a verme de nuevo. ¡Suerte, $c!",
		},
		[3102] = {
			title = "Una carta cifrada",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia de Jorik, uno de nuestros instructores locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "Descubrirás que hay una serie de personajes que codiciarán nuestras habilidades, $n. Aventureros, IV:7... diablos, incluso a la Hermandad Defias no le importaría tener un espía o dos dentro de Ventormenta. Pero recuerda esto, eres tu propio jefe. ¡No dejes que nadie te intimide para que hagas algo que no quieres hacer! Además, tenemos todas las cartas ... al menos, antes de que termine el juego. ¡Tu ya sabes!$B$BDe todos modos, solo quería presentarme y hacerlte saber que estoy aquí si necesitas capacitación. Ven en cualquier momento.",
		},
		[3103] = {
			title = "Una carta sacralizada",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia de la sacerdotisa Anetta, una de nuestras instructoras de sacerdotes locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "A medida que ganas experiencia, ven a verme y te enseñaré lo posible. Hasta entonces, que la sabiduría guíe tus pasos. Recuerda que de ti depende mejorar el mundo.",
		},
		[3104] = {
			title = "Una carta glífica",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia de Khelden, uno de nuestros instructores de magos locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "Sabía que mi carta no te apartaría de tu camino. Bien, ¿vienes a aceptar tu destino y enfrentarte a quienes se oponen a tu búsqueda de sabiduría y poder?$B$BTe temerán tanto como te respetarán, $n. Y yo siempre estaré aquí para instruirte; solo tienes que venir a buscarme.",
		},
		[3105] = {
			title = "Una carta manchada",
			accept = "Me pidieron que te trajera esto en cuanto regresaras de los campamentos kóbold, $N. Parece ser una carta sellada con la insignia de Drusilla, una de nuestras instructoras locales. Deberías leerla antes de continuar con tus tareas en la abadía.",
			complete = "A medida que crezcas en poder, se sentirás $gtentado:tentada;; siempre debes recordar controlarte. No mentiré: la corrupción puede llegar a cualquier practicante de lo arcano; especialmente uno que trata con criaturas de la oscuridad. Ten paciencia y prudencia ... pero no dejes que eso reprima tu ambición.$B$BA medida que te vuelvas más $gpoderoso:poderosa;, vuelve a mí y te enseñaré más sobre nuestros caminos.",
		},
		[3106] = {
			title = "Runa simple",
			accept = "Mientras me estabas ayudando, me fue confiada esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.",
			complete = "Es bueno que sepas que también verás otras cosas, como enanos usando magia en una pelea en lugar de un rifle, a algunos de los nuestros que veneran la Luz sagrada como los humanos, y por último, pero no menos importante, troggs. Ya aprenderás más sobre ellos, pero lo que debes saber es que estoy aquí para ayudarte.$B$BEstoy para enseñarte a ser $gun verdadero:una verdadera; $c. Si crees que necesitas más entrenamiento, ven a verme y veremos qué se puede hacer.",
		},
		[3107] = {
			title = "Runa consagrada",
			accept = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Bromos, el instructor de paladines. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.",
			complete = "Los humanos nos han enseñado mucho sobre la Luz Sagrada y lo importante que es su orden para ellos... y para proteger todo Azeroth. Tenemos un gran respeto por lo arraigada que es la tradición y por cómo una sola figura, un solo sacrificio, puede marcar la diferencia entre el dolor y la salvación.$B$BLos dos trabajaremos juntos por un tiempo. En cualquier momento que creas estár $glisto:lista;, vuelva a verme y veremos cómo obtener un poco de entrenamiento. No puedo permitir que salgas al mundo sin estar $gpreparado:preparada;, ¿verdad?",
		},
		[3108] = {
			title = "Runa con grabados",
			accept = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Thorgas, el instructor de cazadores. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.",
			complete = "Una cosa que siempre debes recordar es que debes respetar el mundo en el que vives. Las bestias que eligen luchar junto a ti; el brillo de tu arma; el peso de tu munición; la sensación de un viento amargo; todas estas cosas que necesitas conocer íntimamente.$B$BHaré lo que pueda para ayudarte, pero la mayor parte del trabajo depende de ti. En cualquier momento que creas que está $glisto:list;, vuelve y habla conmigo. Te entrenaré.",
		},
		[3109] = {
			title = "Runa codificada",
			accept = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.",
			complete = "De todos modos, cuando empieces a echar un vistazo a Crestanevada probablemente necesitarás entrenar en algún momento. Vuelve a mí siempre que lo necesites y te enseñaré lo que sé: un truco aquí, una maniobra allá. Ya sabes, las cosas que te mantienen vivo y hacen una pequeña moneda extra.$B$BEstá $gatento:atenta; también a nuestros amigos gnomos... a ellos les tocó el palito corto cuando Gnomeregan fue... destruido. Necesitarán nuestra ayuda para sentirse bienvenidos.",
		},
		[3110] = {
			title = "Runa sacralizada",
			accept = "Mientras me estabas ayudando, me confiaron esta runa para que te la entregara. Cuando tengas la oportunidad, léela. Creo que es de Branstock, el instructor de sacerdotes. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.",
			complete = "Yo soy quien puede entrenarte cuando comiences a orientarte por Crestanaveda. Cuando te sientas $glisto:lista;, vuelve conmigo y quizás te enseñe uno o dos hechizos nuevos para defenderte de esos malditos troggs.$B$BTienes la Luz de tu lado, junto con todo Forjaz, $n... sin presión para que te conviertas en algo especial.",
		},
		[3112] = {
			title = "Memorándum simple",
			accept = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Thran, el instructor de guerreros. Échale un vistazo y, cuando puedas, ve a buscar a Thran a Yunquemar.",
			complete = "Bueno, viendo que esta es tu directiva principal, o como sea que la llamen estos días, te di mi palabra de que haría todo lo posible para asegurarme de que tú y los tuyos estuvieran listos para recuperar su hogar... y eso es lo que voy a hacer.$B$BEn cualquier momento que te sientas <preparado(preparada>, vuelve con el bueno de Thran y estaré feliz de compartir mis conocimientos. Te costará algo el entrenamiento, pero no será demasiado caro. Buena suerte.",
		},
		[3113] = {
			title = "Memorándum encriptado",
			accept = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Solm, el instructor de pícaros. Échale un vistazo y, cuando puedas, ve a buscar a Solm a Yunquemar.",
			complete = "Suelo mantenerme un poco al margen de todo, para evitar sermones si desaparecen cosas y eso, pero si necesitas algo, entrenamiento o así, vuelve.$B$BTú y yo nos entendemos bien. Ya sabes, a la hora de la verdad, solo puedes fiarte de la familia... Y familia es lo que somos, ¿no? Aparte de eso de que Gnomeregan esté siendo invadido y eso y todo lo demás que se te cruce en el camino, nos tenemos el uno al otro para cubrirnos las espaldas. ¿No estás de acuerdo?",
		},
		[3114] = {
			title = "Memorándum glífico",
			accept = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Marryk, el instructor de magos. Échale un vistazo y, cuando puedas, ve a buscar a Marryk a Yunquemar.",
			complete = "¡Oh si! Artes Arcanas... por supuesto.$B$BEsto es lo que necesitas saber, $n: No te metas en muchos problemas. Ahorra una moneda para comprarme una cerveza... o cualquier hechizo que quieras. Y mantente $galejado:alejada; de Gnomeregan. Aparte de eso, ¡que tengas un buen día! Estaré aquí si me necesitas o quieres entrenar... o lo que sea.",
		},
		[3115] = {
			title = "Memorándum corrupto",
			accept = "Mientras me estabas ayudando, me fue confiado este memorándum para que te lo entregara. Cuando tengas la oportunidad, léelo. Creo que es de Alamar, el instructor de brujos. Échale un vistazo y, cuando puedas, ve a buscarlo a Yunquemar.$B$BY ten cuidado, $N, muchos no confían en los de tu clase por aquí.",
			complete = "Pero nada de eso importa. ¡Lo que importa es que has visto tu propia Luz Sagrada! Sabes de dónde proviene realmente el poder. Te das cuenta de que tener nuestros propios aliados es mucho más... prudente. Aliados especiales. Aliados que, sin importar la tarea, obedecerán hasta el último aliento.$B$BY ahí es donde entro yo, $n. Puedo entrenarte en los inicios de esos poderes especiales. Búscame a menudo y haré lo que pueda para enseñarte más hechizos.",
		},
		[3116] = {
			title = "El sigilo simple",
			accept = "Un mensajero de nuestra instructora de guerreros, Alyissia, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.",
			complete = "Pronto verás a otros de diferentes razas en las ramas de nuestro hogar, no dejes que eso cause ningún prejuicio dentro de ti. Ellos son bienvenidos. Nos ayudarán cuando puedan. No todos serán altruistas, pero se les debe otorgar cierta confianza.$B$BPero nada de esto importa ahora. Ahora debemos centrarnos en ti y en cómo puedes ayudar a nuestra gente. Estoy aquí con ese mismo propósito. Te entrenaré en las formas de $gun:una; $c a medida que te vuelvas más fuerte. Vuelve a mí cuando quieras y haré lo que pueda para ayudarte.",
		},
		[3117] = {
			title = "El sigilo con grabados",
			accept = "Este siglo me lo entregó un mensajero de nuestra instructora de cazadores, Ayanna. Parece que quiere hablar contigo. Léelo y luego llévaselo.",
			complete = "Ven a verme a menudo mientras estés en Cañada Umbría; te ayudaré a entender el rol $gdel:de la; $c y tus capacidades.$B$BNo confíes demasiado en la ayuda de tus mascotas. En estos tiempos hay cosas más peligrosas de lo que puedas imaginar.",
		},
		[3118] = {
			title = "El sigilo cifrado",
			accept = "Un mensajero de nuestro instructor de pícaros, Frahun, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.",
			complete = "Hasta entonces, debes saber que los de nuestra especie son más necesarios que nunca en estos tiempos difíciles. La paz con las otras razas puede fracasar en cualquier momento, y se habla mucho de que los miembros de la Horda buscan sembrar aún más semillas de desconfianza. Recuerda eso.$B$BA medida que ganes en poder y te sientas más $gpreparado:preparada;, vuelve a verme aquí y veré si te entreno un poco. Es importante que sepas cómo manejar el arma que elijas, entre otras cosas.",
		},
		[3119] = {
			title = "Sigilo sacralizado",
			accept = "Un mensajero de nuestra instructora de sacerdotes, Shanda, ha traído este sigilo. Parece que quiere hablar contigo. Léelo y luego llévaselo.",
			complete = "Por ahora no te preocupe por el mundo debajo de Teldrassil. Habrá tiempo para eso más tarde. Ve ahora y habla con los demás en Cañada Umbría; ellos pueden contarte más sobre los eventos que han ocurrido. Ayúdalos de cualquier manera que puedas, y cada vez que sientas que necesitas más capacitación, regresa a mí y te enseñaré lo que pueda.",
		},
		[3120] = {
			title = "El sigilo verdeante",
			accept = "Este sigilo me lo entregó un mensajero de nuestro instructor de druidas, Mardant. Parece que quiere hablar contigo. Léelo y luego llévaselo.",
			complete = "Te voy a instruir en la interpretación de los designios de los espíritus y en los secretos del Sueño Esmeralda.$B$BA medida que ganas poder, aprenderás más de nuestros trances del sueño. Hasta entonces, ven a verme cuando quieras para seguir tu instrucción.",
		},
		[3121] = {
			title = "Una extraña petición",
			accept = "Neeru Hojafuego en Orgrimmar tiene lo que necesito para comenzar. Ha preparado una poción que necesito para mi... Bueno, ya verás.$B$BAhora ve a Orgrimmar. Toma, llévate esto. Es una cabeza reducida que le prometí a Neeru a cambio de las hierbas. Es la cabeza de un pobre enano que me encontré en el bosque. Seguro Neeru estará complacido.$B$BLo encontrarás en el Circo de las Sombras.",
			complete = "He estado esperando a que Uzer'i me entregara esto...$B$BDeja que te dé la mezcla de hierbas que preparé para este... experimento...",
		},
		[3122] = {
			title = "Regresa junto al médico brujo Uzer'i",
			accept = "Aquí tienes las hierbas, $N. Llévaselas al médico brujo Uzer'i.$B$BY dile por favor que estoy muy satisfecho con la cabeza reducida.",
			complete = "Es justo lo que necesito para preparar la vasija de muisek, $n. Pronto veremos si mis últimos hechizos resultan ser tan potentes como espero.$B$BDame un momento, por favor. Debo celebrar el ritual y aplicar las hierbas.",
		},
		[3123] = {
			title = "Probar la vasija",
			accept = "Esto será una prueba: para el ritual que realicé y para tus habilidades. Toma esta vasija, $N. Con ella tendrás el poder de encoger y capturar a una criatura en su interior.$B$BViaja a las Tierras del Interior y busca a las criaturas conocidas como lechúcicos, que otrora fueron mascotas de la diosa de los elfos de la noche Elune. Las lechubestias sañosas, primitivas o salvajes son tu objetivo, $N. Mata a 10 y usa la vasija de muisek para encogerlos y capturarlos antes de que sus espíritus escapen.",
			complete = "Si una criatura sufre una muerte violenta, su muisek puede escapar y buscar venganza. Encogiendo las criaturas como hiciste tú, $n, se impide que el muisek escape. ¡Ahora podemos usarlo para lo que queramos!",
		},
		[3124] = {
			title = "Muisek de hipogrifo",
			accept = "Has demostrado merecer mi confianza y tener facultad suficiente para utilizar a las vasijas de muisek. Ahora quisiera que capturases a otra criatura.$B$BLos hipogrifos han sido compañeros leales de los elfos de la noche durante muchos años; sus espíritus son leales e inquebrantables.$B$BTu tarea consiste en acabar con 10 hipogrifos Plumavieja y, rápidamente, encogerlos y capturarlos usando la vasija, de forma que podamos conservar su muisek. Podrás encontrarlos en las Altas Tierras Salvajes, al sur de aquí.",
			complete = "Si, después de matar a un animal, permitiéramos que su muisek escapara, este podría tomar la forma de algo más grande. Y nunca estaríamos a salvo, pues buscaría venganza.$B$BEl que te he encomendado es un trabajo peligroso, $n, pero lo has hecho bien.",
		},
		[3125] = {
			title = "BAquí tienes la vasija, $N. Mat",
			accept = "8 duendes dardo o duendes dra",
			complete = "Gracias, $n. Ahora tenemos los poderes espirituales del dragón feérico a nuestra disposición.$B$BEspero que aceptes una tarea más.",
		},
		[3126] = {
			title = "Muisek de antárbol",
			accept = "Los caminabosques deambulantes que vagan por el bosque son nuestro siguiente objetivo, $N. Los elfos de la noche se han aliado con los antárboles para combatir a la Horda. Se mueven con lentitud, pero su papel como protectores es innegable.$B$BPronto podrán usar ese poder en nuestro beneficio.$B$BEncuentra a 3 Caminabosques deambulantes, mátalos y utiliza la vasija de muisek para reducirlos y capturarlos.",
			complete = "Gracias, $n. Nuestra colección de muiseks está casi acabada.",
		},
		[3127] = {
			title = "Muisek de gigante montés",
			accept = "La última tarea que te encargaré es que viajes al noroeste y encuentres al enemigo definitivo.$B$BLos gigantes monteses dejaron sus montañas para ir a ayudar a los elfos de la noche cuando la Legión Ardiente apareció en el mundo. Los reconocerás por su descomunal talla y los encontrarás por la forma en la que el suelo temblará cuando viajes por su rocosa tierra.$B$BEstoy deseando controlar ese descomunal poder. Mata a 7 gigantes monteses y luego utiliza la vasija de muisek para capturar su potente muisek.",
			complete = "Imagina las posibilidades que nos da lo que tenemos, $n. Con los materiales que has reunido, podré atrapar para siempre el muisek de estas criaturas y hacer con él lo que me plazca.",
		},
		[3128] = {
			title = "Materiales naturales",
			accept = "Necesitaré algunos materiales para completar mi tarea... Podrías conseguírmelos a la vez que cumples otras tareas que te asignaré.$B$BNecesitaré un tronco astillado de un antárbol de Feralas. Y minerales taraceados. Los llevan los gigantes monteses y los dragones feéricos del oeste. También necesito algún tendón resistente de las lechubestias de las Tierras del Interior o de los hipogrifos de Feralas. Y por último, necesito una gran cantidad de fragmentos metálicos de cualquiera de las criaturas que he mencionado.",
			complete = "¡Fantástico! Estos materiales, combinados con el muisek, deberían procurarnos los resultados que queremos.",
		},
		[3129] = {
			title = "Armas del espíritu",
			accept = "Imbuir el muisek en las armas es un proceso difícil. Ahora que tengo todo el material que necesito y el muisek de las criaturas que has capturado, puedo empezar a trabajar. Por favor, espera. Volveré en un momento.",
			complete = "Tal y como prometí, $n, el muisek de las criaturas ha quedado vinculado para siempre al poder de estas armas.$B$BAhora puedes hacer tuya su energía. Utilízala bien.",
		},
		[3130] = {
			title = "En contra de los Crestafuria",
			accept = "Voy a remitirte a mi segundo, Latronicus. Ha estado vigilando de cerca a las tropas naga hasta hoy. Evaluaré la situación general de esta zona, en lo que a los nagas se refiere; aunque me encantaría enviar a todo un ejército contra ellos, dejar la fortaleza expuesta a un ataque directo de la Horda –o peor– no es una solución deseable.$B$BEn fin, Latronicus espera. Has hecho un buen trabajo hasta ahora, $n. Sigue así.$B$BRetírate.",
			complete = "Excelente, $n. Me gusta que quienes trabajan para mí tengan esa actitud de \"puedo hacerlo\".$B$BLa general Plumaluna me ha encargado que me dirija a los naga de forma directa. Mis planes tienen dos objetivos: uno, debilitar tanto su número como su cadena de mando y, dos, descubrir qué están haciendo en las ruinas. Con tu ayuda, reduciremos la presencia naga sin sacrificar la seguridad del Bastión.",
		},
		[3141] = {
			title = "Loramus",
			accept = "¿Así que quieres enfrentarte a demonios? Harías bien en escuchar mi relato.",
			complete = "Que así sea...",
		},
		[3161] = {
			title = "Gahz'rilo",
			accept = "¡$N, yo soy un científico pero tengo alma de cazador de tesoros!$B$BMucho tiempo atrás, cuando los trols ocupaban estas tierras, crearon gran cantidad de adornos inspirados en Gahz'rilla, una hidra a la que rindieron culto como a una deidad. Estos adornos están tallados en un material que yo denomino \"gahz'rilo\", derivado del propio nombre de la diosa hidra.$B$BYo mismo encontré algunos pero me gustaría tener más para poder estudiarlos a fondo. Quizás tú puedas buscarlos...$B$B¡Incluso he ideado un detector que hace de buscar gahz'rilo un juego de niños! ¡Simplemente enciéndelo y que empiece la búsqueda!",
			complete = "Estos adornos son perfectos, simplemente perfectos. Muchas gracias por tu ayuda, $n.$B$B¡Ah! ¿Me devuelves mi casco?",
		},
		[3181] = {
			title = "El cuerno de la bestia",
			accept = "El enorme cuerno está lleno de arañazos y grietas. Hay un objeto metálico peculiar incrustado.$B$BAl observarlo de cerca, ves que es una cabeza de hacha rota. En el metal están inscritas las palabras:$B$BPropiedad de la montaraz Guijarro.$B$BCuando saques la cabeza de hacha, se romperá en mil pedazos.$B$B¡Qué cosas!",
			complete = "¡Eso es una falsificación!$B$BHe visto a Margol, sé que su cuerno es al menos 8 veces más grande que ese, $n. Será de un morrotormenta de Los Baldíos. ¡A Guijarro no la engaña nadie!",
		},
		[3182] = {
			title = "Certificado de autenticidad",
			accept = "¿Cómo quieres que me crea eso? El cuerno de verdad tendría todavía mi hacha clavada.$B$BLlévale esa falsificación al comisario Torio a Forjaz. Si confirma tu historia, te dará un certificado de autenticidad. Si me lo traes, te daré la llave de La Garganta de Fuego.$B$B¡Andando!",
			complete = "¿Qué es esto?$B$B¡No me lo puedo creer! ¿Te das cuenta de lo que es, $r? ¡Es el cuerno de Margol la Furibunda, el terror de La Garganta de Fuego!$B$B¿Puedo quedármelo?",
		},
		[3201] = {
			title = "¡Al fin!",
			accept = "No puedo creer que Guijarro dude de la autenticidad del cuerno. Entre tú y yo, creo que está celosa; quería matar a la bestia ella misma, por aquello del incidente y tal.$B$BAsí que necesitas un certificado de autenticidad; por supuesto, te lo has ganado.$B$B<El comisario Torio empieza a rellenar un documento.>$B$B¡Aquí lo tienes! Llévaselo a Guijarro.",
			complete = "No entiendo cómo pudiste derrotar a Margol, pero un trato es un trato; toma la llave.$B$BSi te pasa algo, te lo habrás buscado tú.",
		},
		[3221] = {
			title = "Habla con Renferrel",
			accept = "Mientras estabas ahí fuera ayudando a nuestros mortacechadores, el boticario Renferrel te envió un llamamiento. No me dio ningún detalle, pero quería hablar contigo sobre los corazones de lobo que le entregaste.",
			complete = "Ah, muy bien. Hay un problema con los corazones de lobo que requiere nuestra atención.",
		},
		[3261] = {
			title = "Jorn Vidente del Cielo",
			accept = "Tu formación conmigo ha llegado a su fin, $N. Para seguir aprendiendo, debes ir al Campamento Taurajo, hacia el sur, y habla con Jorn Vidente del Cielo. Él seguirá con tu aprendizaje.",
			complete = "Saludos, joven. ¿Has venido para seguir el camino $gdel:de la; $c?$B$BMuy bien. Empecemos.",
		},
		[3281] = {
			title = "Plata robada",
			accept = "Puede que hayas matado a los raptores ¡pero aún hay que recuperar la plata que robaron! Me han informado que los raptores tienen un gran número de nidos al sur de Trinquete, llaman a ese lugar Tierras de los Raptores. Es probable que llevaran allí nuestra plata robada.$B$BVe a ese refugio de raptores y busca la plata robada. Cuando la encuentres, devuélvemela.",
			complete = "¡Eso es! Así que los raptores tenían la plata escondida en su guarida como pensábamos. Cuesta creer que estas bestias codicien la plata. ¡Quizás lo que cuentan de su inteligencia no es tan descabellado como creía!$B$BGracias, $n. Toma esto como recompensa por tus servicios y que sepas que la guardia de El Cruce te debe el próximo mes de paga.",
		},
		[3301] = {
			title = "Mura Tótem de Runa",
			accept = "Mi compañera de clan, Mura Tótem de Runa, se dirigía al Bosque de Argénteos así que podría ayudar a nuestros aliados no-muertos. Este bosque está enfermo, se está muriendo, y Mura tenía la esperanza de devolverle la vida. Quizás la extraña vida que hemos encontrado aquí en Los Baldíos pueda ayudarla en su trabajo en el Bosque de Argénteos.$B$BToma uno de los caparazones que recolectaste y llévaselo a Mura en el Bosque de Argénteos. La encontrarás en El Sepulcro. Con un poco de suerte, el estudio del caparazón le dará una idea de lo que necesita para curar ese lugar agonizante.",
			complete = "¿Qué es esto? Este caparazón tiene un brillo interior, como si aún hubiera vida en su interior. ¡Asombroso! Debo examinarlo más a fondo.$B$BGracias, $n. Con suerte, este caparazón contendrá un secreto que podré usar para ayudar a la pobre tierra del Bosque de Argénteos.",
		},
		[3321] = {
			title = "¿Has perdido esto?",
			accept = "Has hecho mucho por la Orden, $N. La dedicación necesaria para llegar hasta aquí hubiera desalentado a cualquier otro. No me cabe duda, ni a Galvan tampoco, de que eres $guno:una; de los nuestros.$B$BPor eso considero que mereces una recompensa. No es nada de otro mundo, tan solo un pequeño detalle. Puede que conozcas sus propiedades, que creo que es lo que en realidad te ha traído hasta nosotros.",
			complete = "Levántate y sé $greconocido:reconocida;, $n, $gherrero:herrera; de la Orden de Mithril.",
		},
		[3341] = {
			title = "Acaba con la amenaza",
			accept = "En Los Baldíos se encuentra una horrible maraña de vides llamadas Zahúrda Rajacieno. Aunque los primeros estudios de este lugar indicaban que no representaba una seria amenaza, nuestros últimos descubrimientos son un poco más desconcertantes...$B$BLos jabaespines de Zahúrda Rajacieno se han aliado con la Plaga. Un exánime llamado Amnennar el Gélido los gobierna, usando el poder de su vasto conocimiento para controlar cada uno de sus movimientos.$B$B$n, Amnennar tiene un vínculo telepático directo con Ner'zhul que debemos eliminar y, para ello, hay que acabar con el Gélido cuanto antes.",
			complete = "La lealtad de un exánime es inquebrantable, $n. Debes mostrarles que tal lealtad les conducirá a su propia destrucción.",
		},
		[3361] = {
			title = "Las penurias de un refugiado",
			accept = "Expulsamos a los troggs de Gnomeregan, ¡pero luego todo salió terriblemente mal! Ahora nuestro hogar está contaminado por la radiación, y los gnomos estamos dispersos por todo Dun Morogh.$B$BEn el apuro por huir de la radiación, perdí todas mis herramientas y pertenencias personales. Los trols se las llevaron. ¡Robaron mi cofre, mi caja y mi cubo de tornillos! Se los llevaron a sus campamentos al sudoeste de Yunquemar.$B$BYo no soy aventurero. ¿Podrías buscar mis cosas y recuperarlas?",
			complete = "¡Hurra, los has encontrado! Eres todo un salvador. Toma, no es mucho, pero acéptalo por los problemas que te he causado. ¡Gracias!",
		},
		[3362] = {
			title = "El Valle Cardizal",
			accept = "¿Has estado alguna vez en el Valle Cardizal? Es un lugar muy peligroso, $N.$B$BEsas extrañas bestias que hay allí... ¡no me fío ni un pelo de ellas! Creo que se llaman Cardizales nudosos y enraizadores Cardizales, o algo parecido...$B$BDe cualquier forma, quiero ir al valle pero con todos esos Cardizales deambulando por ahí, no creo que consiga volver con vida. Y aquí es donde entras tú. Si pudieras acabar con algunos de ellos, quizás consiga regresar de una pieza. ¿Qué te parece, $N? ¿Me ayudas?",
			complete = "No sabía que eran tan grandes. Creo que tengo que perfeccionar mi plan...$B$BPero tú has cumplido con tu parte, así que aquí tienes lo que te prometí.",
		},
		[3363] = {
			title = "Melodía corrupta",
			complete = "Aplicas un poco de bálsamo de planta Cenarion a la melodía. Inmediatamente empieza a mudar su forma corrupta y se transforma en una planta rebosante de salud.",
		},
		[3364] = {
			title = "Entrega una infusión de albaza hirviendo",
			accept = "¡Ay! Se supone que tenía que llevar esta deliciosa infusión de albaza a Durnan Cortapieles, de Yunquemar, pero antes tengo que entregar una a Grelin. ¡Se enfriará antes de que llegue a Yunquemar!$B$BTú pareces $grápido:rápida;. Seguro que tú lo consigues. Esta taza estará caliente solo unos cinco minutos más y Durnan no pidió infusión fría de albaza, así que, ¡en marcha! Yunquemar está al noreste. Es un emplazamiento excavado en la montaña.$B$BGracias, $N. ¡Y no olvides devolverme la taza!",
			complete = "¡Oh, qué bien me va a sentar esto! Deja que me tome un descansito mientras disfruto esta infusión de albaza hirviendo.",
		},
		[3365] = {
			title = "Devuelve la taza",
			accept = "¡Qué a gusto me he quedado, oye! Nada calienta el alma en un frío día de invierno como una infusión calentita –no, ARDIENTE– de albaza.$B$BTen, $N. Llévale a Nori esta taza vacía de mi parte, ¿quieres?",
			complete = "¡Excelente, $n! Te sorprendería saber la cantidad de mensajeros que conozco que olvidan hacer algo tan simple como devolver una taza. ¡Y las tazas no crecen en los árboles, o eso dicen!$B$BAquí tienes algo para premiar tu esfuerzo. Y gracias de nuevo por tu ayuda.",
		},
		[3367] = {
			title = "Piedras de Suntara",
			accept = "<Dorius gruñe.>$B$BEstoy malherido, $r. Todo me da vueltas... Seguro que tengo hemorragias internas.$B$BTengo que volver a Forjaz. Ayúdame, $N.|n",
			complete = "Dorius dejó caer esta carta cuando le dispararon.",
		},
		[3368] = {
			title = "Piedras de Suntara",
			accept = "Hermano:$B$BSi estás leyendo esta carta, yo ya no estoy en este mundo. Da las gracias en mi nombre a quien te la haya entregado y recompénsale.$B$BEn cuanto a las piedras, te confirmo que existen y las tienen los Hierro Negro. Su jefe, Lathoric el Negro, las usa para tener esclavizado a mi equipo de excavación; se los llevaron a La Caldera. Están obsesionados con algo que llaman Obsidion.$B$BAyúdalos, hermano. Esta es mi última voluntad.$B$BDorius|n",
			complete = "<Thorius se seca la cara.>$B$BPor la Luz que se cumplirá su deseo.",
		},
		[3369] = {
			title = "En las pesadillas",
			accept = "Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.$B$BNo quiero alarmarte, $N, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...$B$BNecesitas encontrar a Hamuul Tótem de Runa del Alto de los Ancestros. Dirígete a Cima del Trueno. No puedo decirte nada más.",
			complete = "¿Vienes de parte de Falla? Bueno, veamos el fragmento del que dices que era tan reacia a hablar...$B$B<Hamuul intenta mirar dentro del fragmento>$B$BOh... yo no.. bien.$B$B$n, Gracias por traérmelo. Pero no es muy inteligente hablar de cosas como esta, te lo advierto. No deberías meterte en este tipo de asuntos.$B$BDigamos que las cosas del Sueño Esmeralda no son como creíamos...$B$BQuizás nuestros caminos se vuelvan a encontrar en el futuro.",
		},
		[3370] = {
			title = "En las pesadillas",
			accept = "Este fragmento alberga grandes secretos, es la esencia pura del Sueño Esmeralda. Sin embargo, lo que veo en él no es un sueño; hay quien llamaría a esta especie de visión una auténtica pesadilla.$B$BNo quiero alarmarte, $N, pero creo que lo mejor será que lleves este fragmento a manos de un sabio druida tan pronto como puedas...$B$BNecesitas encontrar a Mathrengyl Garroso del Círculo Cenarion. Dirígete a Darnassus. No puedo decirte nada más.",
			complete = "¿Vienes de parte de Falla? Bueno, veamos el fragmento del que dices que era tan reacia a hablar...$B$B<Mathrengyl intenta mirar dentro del fragmento>$B$BOh... yo no.. bien.$B$B$n, gracias por traérmelo. Pero no es muy inteligente hablar de cosas como esta, te lo advierto. No deberías meterte en este tipo de asuntos.$B$BDigamos que las cosas del Sueño Esmeralda no son como creíamos...$B$BQuizás nuestros caminos se vuelvan a encontrar en el futuro.",
		},
		[3371] = {
			title = "La justicia de los enanos",
			accept = "Hay un hueco desolador donde solía estar mi corazón, $N. No me será fácil recuperarme de la pérdida de Dorius. Pero debo cumplir con su última voluntad: hay que llevar a la justicia a los culpables de este asesinato a sangre fría.$B$BVuelve a la Garganta de Fuego y cumple con su último pedido: libera a sus hombres.",
			complete = "Déjame, ayuda a los demás.",
		},
		[3372] = {
			title = "Libéralos",
			accept = "Libéralos, $r. Aunque fallen sus cuerpos, el poder de Suntara les empuja a seguir trabajando.$B$BLa clave está en el Altar de Suntara. Ve al noroeste; el Martillo Crepuscular guarda una reliquia en las colinas que hay sobre la cueva. Recógela y colócala en el Altar de Suntara.$B$B<Pierde el conocimiento.>",
			complete = "Colocas el artefacto misterioso en el Altar de Suntara.",
		},
		[3373] = {
			title = "La esencia de Eranikus",
			accept = "Cuando tocas la gema, una voz profunda resuena en tu cabeza.$B$B\"Mortal, escucha esta súplica. Soy Eranikus del Vuelo Verde, guardián de este templo maldito. Mi deber de asegurarme de que los trols nunca jamás vuelvan a traer su abominación de dios, ha fracasado. Mientras esta gema queda imbuida de parte de mi esencia, puedo sentir que mi vínculo con el Sueño se dirige hacia el caos. Por favor, coloca esta gema en la fuente de esencia de mi guarida, y deja que nuestra magia purgue la corrupción de mi psique, para que pueda descansar.\"",
			complete = "Colocas la gema en la fuente de esencia.$B$B\"Gracias, mortal, no tienes... esto, ¡esto no puede ser! ¡No! La corrupción de este dios maldito mancha la santidad de la fuente de esencia del Vuelo Verde! No, por favor, mi esencia... me abandona... EL DOLOR... Siento cómo me inunda una pesadilla eterna...\"$B$B\"Mortal, ¡te lo ruego! Encuentra un miembro del Vuelo Verde para detener esto... ayúdame... Estoy encadenado a la oscuridad... a la agonía eterna... por favor, no me tortures...\"",
		},
		[3374] = {
			title = "La esencia de Eranikus",
			accept = "Coges la piedra de juramento y oyes en tu cabeza la voz de Itharius que te habla a través de ella.$B$B\"Al aceptar la orden que contiene esta piedra de juramento, te comprometes a ayudarme a mí y al Vuelo de Ysera a redimir la corrupta alma de Eranikus. El primero de los muchos sacrificios que con toda seguridad tú y yo haremos consiste en que me entregues la gema que está mermando lo poco de la psique de Eranikus que todavía estaba libre de malvadas influencias.\"$B$B\"$N, hazlo y entonces podremos ofrecerle redención a un alma que bien la merece.\"",
			complete = "Has tomado una decisión. Hasta la fecha, puedo decir que has tomado las decisiones correctas. De ahora en adelante, tus acciones determinarán si esto continúa siendo así.",
		},
		[3375] = {
			title = "Otra ampolla",
			accept = "¿Que necesitas otra ampolla de adivinación? Estás de broma, ¿verdad? ¡¿Qué has hecho con la otra?! Tenemos mucho trabajo, $r. ¡Las ampollas no crecen en los árboles! Y ojalá lo hicieran, porque no tengo ninguna.$B$BTe haré una, pero necesito lo siguiente: una poción de maná, un trozo de carbón y algo de néctar dulce. No preguntes por qué, tú tráeme estas cosas y ya está.",
			complete = "$gEl poderoso aventurero:La poderosa aventurera; cumple. ¡Hurra por mí! Por cierto, mentí, tenía otro frasco. Ungh, tómalo.$B$B¡¿Bueno, que esperabas?! \"¡Oh, toma otro! ¡Soy sólo un tonto que no tiene nada mejor que hacer que entregar dispositivos mágicos de comunicación a los aventureros!\" Sin embargo, ten la seguridad de que lo que me has dado será suficiente para convertirlo en otro frasco cuando vuelvas a perderlo.$B$BPor favor, demuéstrame que estoy equivocado y no pierdas el nuevo, ¿de acuerdo?",
		},
		[3376] = {
			title = "La cabeza de Cornapunta",
			accept = "He oído hablar de ti, $N. Quizás tú puedas ayudarnos donde otros han fallado.$B$BLos tauren hemos hecho un hogar de esta tierra, pero a un precio alto. Los jabaespines Erizapúas del Barranco Cortazarza, liderados por el Jefe Cornapunta Mantospina, nos acosan continuamente. ¡Quiero la cabeza del jefe! ¡Tráemela!$B$BEstará en el barranco que hay al este de su aldea.",
			complete = "Hoy se ha hecho justicia gracias a ti, $n. Que esto sirva de advertencia a todos cuantos amenazan nuestro hogar.$B$BAcepta esta recompensa por tu hazaña, $c.",
		},
		[3377] = {
			title = "El rezo a Elune",
			accept = "¿Quieres ayudarme, mortal? Escucha lo que tengo que decir.",
			complete = "He aceptado mi destino, pero debes encontrar el rezo.",
		},
		[3378] = {
			title = "El rezo a Elune",
			accept = "¿Me ayudarás, mortal? Busca el rezo a Elune.$B$BEstá grabada en una tablilla dorada. Seguro que alguno de esos rufianes idólatras la lleva consigo.$B$BSi consigues recuperarla, llévasela a Astarii Buscaestelar, que está en Darnassus. Poco importa que haya recuperado la fe después de todos los crímenes que he cometido, pero quiero que se oiga mi oración. No espero la absolución.",
			complete = "Elune te sonríe, $n; le has devuelto un alma perdida. Acepta esto en prueba de nuestra gratitud.",
		},
		[3379] = {
			title = "Las tejedoras de sombra",
			accept = "Las arañas de La Garganta de Fuego son una fuente increíble de seda de las Sombras. Como ya sabrás, este elemento tiene mucha demanda.$B$BRecientemente, un grupo de furtivos ha invadido estas tierras, acabando con las arañas de forma masiva y sin pensar en los efectos a largo plazo de sus actos. Lo primero que te voy a pedir es muy sencillo: encuéntralos y acaba con ellos.$B$BComienza tu búsqueda por el norte.$B$BSi necesitas ayuda, habla con Arrasa.",
			complete = "Excelente trabajo, $n.$B$BEstoy segura de que este es un trozo de tejido de sombra que nunca has visto.",
		},
		[3380] = {
			title = "El Templo Sumergido",
			accept = "En este mundo, hay espíritus inquietos, $n. Espíritus marcados por su aislamiento, atados a un mal ancestral...$B$BHe oído hablar de un lugar en el fondo de las profundidades de la tierra. Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.$B$BSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Ha estudiado muchas zonas antiguas del mundo. Se sabe que dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.",
			complete = "Sí, el Templo Sumergido, puedo decir que lo he visto con mis propios ojos. ¿Quizás te gustaría oír más?$B$BParece que te gustan las aventuras... sé que estas cosas podrían interesarte...",
		},
		[3381] = {
			title = "Un encuentro con el maestro",
			accept = "Ah, $gun:una; joven; $r que viene a hablar con Sanath. ¡Qué día tan maravilloso! Es un gran honor el que me concedes visitándome. ¡Gracias!$B$BTe lo ruego... no seas tan arrogante como para pensar que mi sarcasmo era un cumplido. Dejemos esto claro: no me gustas. Pero esta charlita nada tiene que ver con nosotros, tiene que ver con mi maestro.$B$BTráeme un par de plumas de hipogrifo para mis flechas y te daré permiso para verlo. Me ha pedido que le envíe aventureros si demostraban tener arrestos.",
			complete = "Dos plumas, tal como te pedí. Y no son malas plumas.$B$B¿$gListo:Lista; entonces? Solo di la palabra y estarás en camino.$B$BAh, y una vez más, acuerdate... mi maestro no se lleva bien con los imbéciles, pero es muy generoso con los que le agradan.",
		},
		[3382] = {
			title = "Un equipo bajo el fuego enemigo",
			accept = "Estábamos a escasa distancia de la costa buscando un puerto seguro donde echar anclas. El sol se había puesto más de una hora antes cuando atacaron... ¡malditos nagas!$B$BNo estoy seguro de lo que buscaban pero está claro que no lo encontraron, ya han vuelto una vez. Tengo a un par de exploradores vigilando la entrada del valle para que nos puedan avisar con tiempo si ven otro ataque venir.$B$BSiento que hayas venido ahora, $N, pero no depende de mí.$B$B¿Estás $glisto:lista; para el combate de tu vida?",
			complete = "¡Lo has hecho! ¡Gracias! Seguramente esta fue una de las batallas más brutales en las que he participado. No puedo agradecerte lo suficiente.$B$BOjalá más miembros de mi tripulación hubieran vivido esta prueba.$B$BTe pediría que hablara con los pasajeros supervivientes del Explorador del horizonte. Algunos de ellos tenían negocios en el área y es posible que tengan una petición o dos para ti si estás $gdispuesto:dispuesta;. De nuevo, gracias por toda tu ayuda.",
		},
		[3385] = {
			title = "El Mercado Negro",
			accept = "Se autodenominan El Mercado Negro: son mercaderes degolladores que venden, traslada, intercambian o hacen de todo por el precio adecuado.$B$BY es aún peor, $n. Han establecido una base de operaciones aquí en La Garganta de Fuego. El maestro de comercio Kovic encabeza las operaciones y mantiene estrechas relaciones con los enanos Hierro Negro de la región.$B$BTenemos que darles un duro golpe y enviar un mensaje a sus líderes. Mata al maestro de comercio Kovic y a su esbirro Clonk. Trae su cartera de mercader cuando hayas acabado.$B$B¡A La Caldera!",
			complete = "Has asestado un golpe decisivo al Mercado Negro. Sus líderes se lo pensarán dos veces antes de enviar más compinches al desfiladero.$B$BAh, y tampoco encontré nada útil en la cartera del comerciante. Puedes guardar lo que encuentres dentro.",
		},
		[3402] = {
			title = "El Mercado Negro",
			accept = "Quiero que tú des la noticia de la derrota de Kovic a Vizzklick, en Gadgetzan. Se alegrará de saber que Kovic ha muerto; seguro que su recompensa será generosa.",
			complete = "¡¿¿Kovic asesinado??! ¡Este es un día glorioso, $n! Durante años, ese sinvergüenza ha estado llevando a cabo operaciones turbias en el Mercado Negro, socavando a los comerciantes honestos y trabajadores de todo el mundo.$B$B¡Te mereces una excelente recompensa por este logro! ¡Y tendrás una excelente recompensa!",
		},
		[3421] = {
			title = "El viaje de vuelta",
			complete = "Te haré volver al campamento de Sanath ahora.$B$BNo hagas caso de su mala educación, es así con todos a excepción del maestro. Quizás algún día le den una lección.",
		},
		[3441] = {
			title = "Castigo divino",
			accept = "Escúchame bien.",
			complete = "¿Has escuchado lo suficiente como para decidir?",
		},
		[3442] = {
			title = "La llama pura",
			accept = "Has tomado la decisión correcta, $N. $B$BDebemos atacar donde más daño hagamos: en las 4 torres del centinela. $B$BSi las incendiamos, podremos atacar sin darles tiempo a reaccionar. $B$BPara incendiar las torres necesitarás una herramienta. Necesito algunas cosas para fabricarla. $B$BTráeme 4 corazones de llama y 4 aceites de gólem; con eso te haré la antorcha de llama pura. $B$BBusca primero a los gólems y elementales de estas tierras.",
			complete = "Muy bien, $n. Sigue, sigue.",
		},
		[3443] = {
			title = "Forjar el mango",
			accept = "Necesitamos un soporte y un mango para transportar la llama pura. Busca primero el mango.$B$BLos capataces y esclavistas Hierro Negro de La Caldera usan armas de torio encantado, una aleación muy resistente. Si me traes ocho dagas bañadas en torio, fundiré la aleación para fabricar el mango.",
			complete = "Eres excepcional, $n. ¿Has pensado en cambiar de oficio? Podrías ser detective o cazatesoros... Ya sé, puedes hacer como esos gnomos locos que van por Azeroth con detectores de metal. Sí, ese trabajo te iría que ni pintado.",
		},
		[3444] = {
			title = "El círculo de piedra",
			accept = "Una vez entré en las cámaras prohibidas del Templo Sumergido. El mal que yace en ese lugar penetra en todo lo que entra. Casi no consigo salir de allí, vadeando entre el lodo que cubre el suelo. Todo lo que puedo recordar es que pasé a trompicones por una gran sala circular llena de estatuas de la Serpiente...$B$BHace poco, descubrí una piedra redonda que parece tener el mismo símbolo de la Serpiente grabado. Hice que me la enviaran a mi taller en Trinquete. Recupérala y podré decirte más cosas.",
			complete = "Sí... Esta es la piedra.$B$BAhora empiezo a recordarlo todo, $n...",
		},
		[3445] = {
			title = "El Templo Sumergido",
			accept = "He oído hablar de un lugar que yace en la profundidad de la tierra... Ha sido desterrado allí por poderes muy superiores a los que jamás he visto.$B$BSi quieres saber más cosas sobre este lugar, el Templo Sumergido, busca a un goblin llamado Marvon Buscarroblones. Al igual que Troyas y yo, ha estudiado muchas zonas antiguas del mundo. Dejó su hogar en Trinquete para estudiar las ruinas trols en Tanaris.$B$BTe deseo buena suerte para encontrarle, hace mucho tiempo que no se oye nada de él.",
			complete = "Sí, el Templo Sumergido, puedo decir que lo he visto con mis propios ojos. ¿Quizás te gustaría oír más?$B$BParece que te gustan las aventuras... sé que estas cosas podrían interesarte...",
		},
		[3446] = {
			title = "En las profundidades",
			accept = "Dentro del templo, encontré una sala circular con seis balcones. Cada uno de ellos tenía una estatua de la Serpiente en el borde. Curioso, empujé una de ellas para ver lo que pasaba, ¡era una trampa! Casi encuentro la muerte en la explosión que surgió. Allí, en el borde, miré hacia abajo y vi otra estatua en el fondo de la sala, una especie de altar... Creo que se llamaba Hakkar.$B$BMe da la impresión de que ese altar es el secreto. Debes llevar este objeto al altar del Templo Sumergido.",
			complete = "Empujas el Círculo de Piedras y puedes oír cómo encaja en su sitio.$B$BAhora que la piedra está en su lugar, puedes continuar... ¿Pero qué debes hacer ahora?$B$BQuizás deberías examinar el altar con más detenimiento...",
		},
		[3447] = {
			title = "El secreto del círculo",
			accept = "Mis recuerdos son borrosos, pero te diré lo que pueda. Aunque el círculo de estatuas del Templo Sumergido es peligroso, creo que contiene el secreto para encontrar un tesoro mucho mayor.$B$BDesde el altar principal, conseguí activar una serie de luces. Si puedes descubrir el significado de esas luces, quizás puedas revelar el secreto que se esconde en esa sala.$B$BPero te lo advierto, $n. Un gran mal yace en el templo. Lo más probable es, que si hay algo de valor, estará muy protegido...",
			complete = "El ojo del ídolo emite unos destellos brillantes, incluso en la semioscuridad del templo. Su transparencia revela algo detrás de él. Empujándolo a un lado, metes la mano y consigues coger lo que hay en el interior de la estatua.$B$BEl tesoro de los Atal'ai ya es tuyo.",
		},
		[3448] = {
			title = "Encargarse de la investigación",
			accept = "Me han encargado que investigue Azshara, una tierra que fue hermosa y que los elfos llamaban hogar. Eso fue en la época en la que practicaban la magia. Ahora es un lugar más peligroso que hermoso, pero debemos buscar respuestas sobre nuestro pasado.$B$BUn compañero llamado Tymor se interesa por estas cosas y se ofreció a ayudarme.$B$BTiene una pequeña tienda a la derecha de la Sala de los Misterios, aquí en la ciudad.",
			complete = "¿Que vienes de parte de Karnik? Me lo imaginaba; he descubierto cosas asombrosas sobre Azshara. Los elfos de la noche viven muchos años, pero la gente tiende a olvidar los acontecimientos más desagradables de su historia. No lo digo como crítica, solo constato un hecho.$B$BHace mucho tiempo, construyeron ciudades imbuidas de magia y otras artes hoy perdidas. Esos temas me interesan, por eso empecé a investigar y descubrí cosas maravillosas.",
		},
		[3449] = {
			title = "Runas Arcanas",
			accept = "Hubo un tiempo en que algunos elfos veneraban la magia tanto como a Elune. Sus magos más poderosos crearon runas y tablillas con leyes de lo arcano y reflexiones sobre sus descubrimientos. Las dejaban en lugares públicos para quien quisiera estudiarlas.$B$BQuisiera que calcaras las runas de las Ruinas de Eldarath. Te daré el material necesario para calcar, pero las runas tendrás que encontrarlas tú. Pero ten cuidado; la Liga de Expedicionarios no es el único grupo interesado en Eldarath.",
			complete = "Es bueno verte $gsano:sana; y $gsalvo:salva;, $n. Espero que las cosas no hayan sido demasiado difíciles para ti.$B$BSe los llevaré a Tymor de inmediato. Estará encantado de echar un vistazo a estas cosas.$B$BAdelante, tira la pistola de bengalas... probablemente ya no te sirva de nada, y ya tengo una nueva.",
		},
		[3450] = {
			title = "Un simple envío",
			accept = "Quiero que los calcos se entreguen en mi torre, pero no hace falta que vayas hasta allí. Haré que sean transportados por aire desde Azshara.$B$BXiggs Botafuego me debe un par de favores y estará en esta zona en breve; lo han destinado a patrullar la costa. Habla con él antes de irte. Te dará una pistola de bengalas para comunicaros. Cuando tengas los calcos, ve a donde te diga y dáselos para que los envíe a mi torre. Estará en el hangar de la Sala Militar.",
			complete = "¿Qué querías, $n? Tengo mucho que hacer, solo he venido a buscar unas crines de wendigo.$B$BAcabo de mandar a alguien al Almacén de Brasacerada, así que tienes un minuto para contarme lo que sea.",
		},
		[3451] = {
			title = "Una señal para el envío",
			accept = "Así que te envía Tymor, ¿eh? Sí, le debo un par de favores. ¿Qué es esto? Vaya con el ladino de él. Bueno, puedo ocuparme de esto. Necesitas una pistola de bengalas y un punto de encuentro; eso es fácil.$B$BHay una isla pequeña con una zona de aterrizaje junto a la península sur de Azshara. Lanza una bengala cuando llegues. Yo iré a recoger esto, lo que sea que es.",
			complete = "Toma mi pistola de bengalas. Sé paciente después de disparar; solo llevan 2 cartuchos y yo puedo tardar hasta 1 minuto, depende de dónde esté. Tú mira al mar después de lanzar las bengalas.",
		},
		[3452] = {
			title = "El soporte para la llama",
			accept = "Nos falta un elemento para acabar la antorcha.$B$BEn las montañas del noroeste encontrarás un campamento de Martillo Crepuscular. Se dice que llevan símbolos e ídolos en honor a su dios; seguro que tienen suficiente magia para crear un soporte encantado. Tráeme un símbolo de Ragnaros; intentaré extraer su magia.",
			complete = "El símbolo irradia Magia demoníaca; justo lo que queríamos.",
		},
		[3453] = {
			title = "La antorcha de reprensión",
			accept = "Déjame montar el conjunto y pronunciar los encantamientos.",
			complete = "Debes completar una última tarea.",
		},
		[3454] = {
			title = "La antorcha de reprensión",
			accept = "Ahora hay que vincular la antorcha a quien la porta. Cógela, $N.",
			complete = "Coges la antorcha y sientes una corriente de odio e ira correr por tus venas.",
		},
		[3461] = {
			title = "Regresa junto a Tymor",
			accept = "Tymor no me ha dado nada para pagarte, así que háblalo con él cuando vuelvas a Forjaz. Seguro que estará en la Sala Mística. Ve a saludar y no te vayas hasta que pague. Esto que te ha encargado no era fácil.$B$BPero gracias otra vez por ayudarle y buena suerte.$B$BAh, y llévate las cosas de calcar. Dáselas a Tymor cuando lo veas.",
			complete = "¡Maravilloso! Me alegro mucho de escucharlo.$B$BEstoy muy ansioso por llegar a mi torre y repasar esos calcos. Tengo tanta envidia de que... vayas a un lugar como Azshara. Ese es el sueño de cualquier estudiante de lo arcano, supongo.$B$BBueno, nunca hablamos de ningún tipo de recompensa ya que solo trabajabas para la Liga de Exploradores, pero te mereces algo.",
		},
		[3462] = {
			title = "Escudero Maltrake",
			accept = "Habla con mi enviado, el escudero Maltrake; te dirá cómo usar la antorcha de reprensión.",
			complete = "¿Preparado/Preparada?",
		},
		[3463] = {
			title = "¡Préndeles fuego!",
			accept = "Escúchame bien, $n. Aunque no es posible destruir las torres, con la antorcha de reprensión provocarás unos incendios muy difíciles de extinguir, un fuego que no puede apagar ninguna fuerza ni elemento.$B$BMientras ardan no podrá haber centinelas ni guardias; su primera línea de defensa quedará anulada.$B$BTienes que entrar en cada torre y usar la antorcha de reprensión dentro de las fortificaciones. Ten cuidado con los oteadores de los Hierro Negro, $n.",
			complete = "¡Qué vista tan gloriosa!",
		},
		[3481] = {
			title = "Abalorios...",
			accept = "El cofre está cerrado con llave.",
			complete = "El cofre se abre cuando lo tocas. ¿Cuánto queso puede haber aquí? Solo hay un modo de averiguarlo.",
		},
		[3483] = {
			title = "Una señal para el envío",
			complete = "¿Otra pistola de bengalas? Por supuesto.$B$BY recuerda que debes ir a la punta sur de Azshara. Es una islita reconvertida en pista de aterrizaje; seguro que la ves.",
		},
		[3501] = {
			title = "Todo cuenta en grandes cantidades",
			accept = "Aunque probablemente no encuentres nunca una esfera draenetista perfecta, seguro que encontrarás trozos draenetistas imperfectos al explorar estas tierras.$B$BAunque es improbable que Kum'isha pueda usar los trozos imperfectos para volver a su hogar, las piezas podrían ser de utilidad para otros fines de los draenei.$B$BTráeme todos los trozos draenetistas imperfectos que encuentres y te recompensaré.",
			complete = "Me produces asco, $r. ¿$gUn hombre hecho y derecho:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista.",
		},
		[3502] = {
			title = "Un trasto de Draenei...",
			accept = "Vaya, después de semejante despliegue de voraz codicia, siento náuseas.$B$BEn fin, no me detendré en tu materialismo.$B$BPor cada trozo draenetista imperfecto que traigas, te recompensaré con más baratijas. Mi pila de chatarra se reduce mientras la tuya crece. Como se dice en Draenor, no hay nada que perder.|n",
			complete = "Me produces asco, $r. ¿$gUn hombre hecho y derecha:Una mujer hecha y derecha; babeando sobre una pila de baratijas? ¡Qué pena das! Toma tu recompensa y desaparece de mi vista.$B$B¿Te suena? Debería, porque lo digo mil veces al día.$B$B¡Oh, cómo aborrezco este mundo!",
		},
		[3503] = {
			title = "Encuentro con el maestro",
			complete = "Hubo un tiempo en que podía pedirles lo que fuera a los que buscaban a mi maestro. Pero ahora, solo tienes que pedirlo y te haré llegar hasta él.$B$BMe molesta pero no cuestiono sus órdenes. Solo puedo disfrutar de hacer bromas sobre tu ridículo atuendo o esa estúpida mirada que luces. Hasta eso me aburre...$B$B¡Hasta esta divagación me aburre! Bueno, ¿quieres ver a mi maestro o no?",
		},
		[3504] = {
			title = "Traición",
			accept = "¡Elfa ladrona! Es el único nombre por el que merece ser llamada.$B$BHe cometido un gravísimo error, $n. Confié en una elfa de sangre.$B$BAfirmaba que Azshara estaba llena de tesoros, de objetos de poder. Le concedí algunos guerreros como escolta esperando obtener beneficio, y mira lo que obtuve: los mató a todos.$B$BQuiero vengarme, pero no puedo prescindir de nadie más, $n. Ve a ver a Ag'tor a Valormok, al norte del Campamento Haldarr. Te dará más información.",
			complete = "Su ejército es fuerte; no ha regresado nadie de las tropas que enviamos. Supongo que muchos han muerto, pero otros habrán huído.$B$BPero ahora que tenemos refuerzos, quizás podamos darle el castigo que se merece por traicionar a Belgrom.$B$B¿Estás con nosotros?",
		},
		[3505] = {
			title = "Traición",
			accept = "Esperaba algo así.$B$BEmpezaremos la campaña contra su gente en los riscos meridionales de la península norteña de Azshara. Masácralos a todos; que sepan que traicionarnos se paga muy caro.$B$BNo te preocupes por ella de momento; pasa casi todo el tiempo explorando Azshara con sus guardaespaldas. Cuando acabes con los suyos, busca su campamento privado. Explora formas de ataque. Puede que encuentres algo con lo que podamos provocarla.",
			complete = "Lo hojeas un poco y encuentras una página marcada por una cinta de seda negra.$B$BEn otra página ves un diagrama. Miras alrededor y ves que los cristales, el círculo e incluso algunos otros componentes del suelo están dispuestos de modo parecido al diagrama.",
		},
		[3506] = {
			title = "Traición",
			accept = "Piensas un poco y se te ocurre algo que te hace sonreír: puede que destruir los cristales irrite a la responsable de la muerte de tantos orcos y la traición de Belgrom.$B$BSigues descifrando las imágenes y el texto y ves que uno de los cristales está unido al creador del círculo; los demás están unidos a algo mucho más siniestro.$B$BCierras el libro y te pones a pensar en qué cristal vas a destruir.",
			complete = "¡Increíble!$B$B¡Lo has hecho! ¡Belgrom estará muy complacido! Al fin encontrarán la paz los espíritus de nuestros guerreros. Gracias, $n.",
		},
		[3507] = {
			title = "Traición",
			accept = "Ve a ver a Belgrom a Orgrimmar. ¡Seguro que querrá ver la cabeza con sus propios ojos! Nosotros iremos pronto.$B$BAh, qué bien ha ido. Gracias por tu ayuda, $N.",
			complete = "¡Chúpate esa, asquerosa!$B$BGracias de todo corazón, $n. ¡Qué alegría me has dado!$B$BTe daría todo un reino si pudiera, pero tendrás que conformarte con esto.$B$B<Belgrom mira la cabeza de la maga que lo había traicionado.> $B$BQué manera de acabar, con la cabeza en una bolsa... ¡Eso te pasa por traicionarme!",
		},
		[3508] = {
			title = "Romper el amuleto",
			accept = "Eres imprudente, $N. Una cualidad admirable la de acometer una batalla a sabiendas de que apenas tienes posibilidades de salir $gairoso:airosa;. Te ayudaré, aunque solo sea para ver cómo cae uno de los esbirros de Razelikh.$B$BLlevará algún tiempo romper la protección de los subordinados de Razelikh y requerirá además algunos artefactos raros.$B$BNo te muevas, primero realizaré el ritual de ilustración. La información que reúna servirá para forjar armas de gran potencia.",
			complete = "Debes encontrar el nombre de la bestia.",
		},
		[3509] = {
			title = "El nombre de la bestia",
			accept = "Solo hay una forma de causarles daño al señor demoníaco y a sus esbirros. Un arma así de potente debe forjarse con su propio nombre inscrito en ella.$B$BCuando se forje semejante arma, el demonio y todo aquel bajo su mando serán vulnerables.$B$BEn Azshara reside una deidad menor: Lord Arkkoroc. Tienes que encontrarlo pero ándate con ojo, sus esbirros no se detendrán ante nada para destruirte si te descubren.$B$BPor supuesto, tendrás que pagar un precio por tal información.",
			complete = "¿Un señor demoníaco?$B$B<Lord Arkkoroc se ríe.>$B$BQuizás el uno pueda ayudarlo con esta información; pero primero, debes ayudar al uno.",
		},
		[3510] = {
			title = "El nombre de la bestia",
			accept = "Ella mata a mis hijos, mortal. La misma que se atribuye el dominio sobre estos océanos. Una deidad de pacotilla, eso es lo que es. Aplástala y tráeme todas sus cabezas.$B$BA cambio, te daré el nombre que buscas y algo más de igual importancia.$B$BRonda la nidada... La llaman Hetaera.$B$B<Lord Arkkoroc señala hacia el suroeste.>$B$B¡Ve!|n",
			complete = "¡Finalmente, $guno digno:una digna; de la sabiduría de Arkkoroc!",
		},
		[3511] = {
			title = "El nombre de la bestia",
			accept = "Lo prometido es deuda, te revelaré el nombre del señor demoníaco, Razelikh el Rapiñador. No obstante, primero debo preparar algo de vital importancia para tu viaje.$B$BEl arma que vas a crear requiere un temple especial. Dame un segundo para exprimir la sangre de estas cabezas.$B$B<Lord Arkkoroc aplasta las cabezas entre sus colosales puños y exprime la sangre de su interior.>$B$BLlévale el temple a Loramus además del nombre de la bestia: Rakh'likh.",
			complete = "El temple agregará el vitriolo necesario que requerimos para la forja de las armas. Solo queda un paso más en su creación.",
		},
		[3512] = {
			title = "Como diría Eranikus...",
			accept = "$N, lo primero que debemos hacer es encontrar un modo de hablar con Eranikus a través de la gema. Él ahora se encuentra en un estado intermedio entre el sueño y la muerte, sufriendo el acoso de horripilantes pesadillas. A pesar de que la esencia que me has entregado está bastante contaminada, todavía existe una posibilidad de que podamos contactar con él.$B$BViaja a las heladas tierras del este de Cuna del Invierno y encuentra a Umbranse el Hablaalmas, uno de nuestros aliados. Es un médium humano que puede comunicarse con los muertos. Aunque Eranikus no esté muerto, puede que igualmente nos sirva de ayuda.",
			complete = "Ha sido una gran idea de Itharius el enviarte a verme. Dado que Eranikus no está muerto, al menos del modo en el que tú entiendes la muerte, pronto nos hablará él mismo y nos dará algunos consejos. De momento, no puedo ayudarte... al menos, por ahora.$B$BTe cederé mi habilidad para hablar con los muertos pero primero necesito la ayuda de alguien que, al contrario que yo, no sufra los achaques de la edad. Mi más potente dispositivo de augurios me fue arrebatado en contra de mi voluntad y, a menos que lo recupere, no podremos ayudar a Eranikus.",
		},
		[3513] = {
			title = "El pergamino rúnico",
			accept = "El pergamino con aspecto oficial está firmemente atado con un lazo plateado. Seguro que alguien estará interesado en verlo, ¿pero quién?$B$BHay una avanzada cerca de la frontera con Vallefresno hacia el norte y si la información de este pergamino tiene que ver con los elfos de la noche, este es el lugar al que se debe llevar.",
			complete = "Bueno, ahora ... ¿Dónde encontraste esto?",
		},
		[3514] = {
			title = "La presencia de la Horda",
			accept = "Este pergamino es de esa intrigante dríade de Rynthariel, la maestra de llaves de El Cubil del Espolón en la Cima del Espolón.$B$BYa no se pondrá en contacto con el mensajero al que le robaste esto, ja, pero debemos mantener la posición aquí. La Horda no tolerará a sus mensajeros aquí.$B$B$n, dirígete a El Cubil del Espolón. Mata a Rynthariel y deja un símbolo para que todos lo vean. Llévate esta bandera de la Horda, $n. Colócala en El Cubil del Espolón para que se lo piensen dos veces antes de enviar a otro mensajero por nuestro territorio.",
			complete = "¡Eres $gduro:dura;! Librar la Guarida de Rynthariel es un paso importante, $n. Tardarán en reagruparse, por lo que podemos contar con menos corredores de la Alianza en Los Baldíos. Se lo pensarán de nuevo antes de enviar otro.$B$BGracias.",
		},
		[3517] = {
			title = "El robo de conocimientos",
			accept = "Lo reconozco, $N, he sacado provecho de mi situación en Azshara. Del castigo de Belgrom han resultado algunas cosas buenas.$B$BAntes de marcharme, hice algunas pesquisas y te sorprendería saber cuántos objetos valiosos hay por los alrededores.$B$BTe contaré más detalles de mis asuntos y hasta te daré una parte de los beneficios si me ayudas a recolectarlos.$B$BHay unas tablillas esparcidas por las Ruinas de Eldarath hacia el este que necesito. Son cuatro y cada una recibe el nombre de cuatro zahoríes Altonato. Consíguelas y seguiremos hablando.",
			complete = "Perfecto, $n, y además en buen estado. Deberíamos conseguir un buen precio de todas las partes interesadas.$B$BNo nos entretengamos aquí más de lo necesario. Hay un buen dinero que ganar.",
		},
		[3518] = {
			title = "Entrega a Magatha",
			accept = "La primera tablilla es para una tauren... una tauren llamada Magatha. Forma parte de los Ancianos Cima del Trueno y está entre los que han propuesto una alianza entre los tauren y los Renegados. Ella, más que ningún otro Anciano, piensa que los tauren y sus métodos pueden ayudar a que los Renegados encuentren una vía para volver a ser humanos.$B$BLlévale la tablilla de Beth'Amara. Es posible que la tablilla sea lo que le permita encontrar la forma de ayudar a los Renegados... o al menos eso dice.",
			complete = "Ah, por fin, la tablilla de Beth'Amara. Me estaba preguntando si mi asociación con Jediga había fracasado o si la pobre orco había encontrado la muerte en Azshara. Me alegra ver que tuvo éxito.$B$BBeth'Amara era uno de los alquimistas con más influencia entre los altonatos. Se decía que el zahorí en solitario había conseguido dominar la trasmutación de metales entre otras cosas.",
		},
		[3519] = {
			title = "Un amigo en apuros",
			accept = "Uy... Me ha picado una araña llamada Gythyiss la Vil mientras exploraba la cueva de las arañas cerca de aquí. Seguro que me ha envenenado así que tienes que ayudarme.$B$BPor favor, habla con Dirania Brillargente. Ella podrá ayudarme.$B$BDate prisa... me estoy mareando...",
			complete = "¡Oh, no! Me preguntaba por qué no había visto hoy a Iverron. Y eso que siempre le he dicho que tuviera cuidado con esas arañas...",
		},
		[3520] = {
			title = "Los espíritus de los estridadores",
			accept = "Busco espíritus de los estridadores del valle de Feralas. Son primos lejanos de un viejo dios y sus espíritus están unidos al suyo.$B$BCoge esta rama de zarza y ve a Feralas. Busca estridadores del valle en la zona sur y central de Feralas y derrótalos. Después agita mi rama sobre sus cuerpos para que sus espíritus se muestren. Toca el espíritu y recoge su esencia.$B$BRegresa con mi rama y con la esencia que hayas recogido y te contaré más acerca del viejo dios del que te hablé.",
			complete = "Lo has hecho muy bien, $n. Quizás ha llegado el momento de que cuente más cosas...$B$BUna antigua profecía de los trols cuenta que el dios muerto Hakkar, el Cazador de Almas, un día regresará a esta tierra. Algunos dicen que el regreso de Hakkar traerá dicha y gloria a los trols, mientras que otros creen que su resurrección significará el principio del fin.$B$BYo no creo en esta leyenda pero sé que la esencia de Hakkar ostenta gran poder, por lo que no debe caer en manos de aquellos que no harán buen uso de ella...",
		},
		[3521] = {
			title = "El antídoto de Iverron",
			accept = "Tal vez podamos ayudar a Iverron; conozco un antídoto contra ese veneno. Pero necesito algunos ingredientes para poder prepararlo.$B$BNecesitaré champiñones jacintos. Crecen bajo los árboles, o también puedes quitárselos a los grell al sur de aquí; parece que les gustan mucho. También necesito lirios alunados, que solo crecen en estanques.$B$BEl último ingrediente es el más peligroso: icor tejemadera de las arañas que envenenaron a Iverron.",
			complete = "¡Gracias a Elune que has conseguido los ingredientes con tanta rapidez!$B$BEn un momento, tendré el antídoto preparado.",
		},
		[3522] = {
			title = "El antídoto de Iverron",
			accept = "El antídoto está listo, $N. Por favor, encárgate de que Iverron se lo tome.$B$BHay algo más que debes saber; el antídoto solamente será efectivo durante los próximos 5 minutos. Debes llevárselo a tiempo.$B$BEspero que lo logres, $N.",
			complete = "¿Qué es esto, $n?$B$B¡Ah, sabía que Dirania podría ayudarme!$B$B<Iverron bebe el antídoto>$B$BSiempre me estoy metiendo en problemas y Dirania... bueno, ella siempre se las arregla para echarme una mano.$B$BYa me siento mucho mejor pero creo que me quedaré aquí sentado un rato hasta que esté totalmente recuperado. Mientras tanto, esperaba que pudieras despejar un camino de esas nocturácnidas sanguinarias...",
		},
		[3523] = {
			title = "La plaga de la Zahúrda",
			accept = "¡Fantástico! Me llamo Belnistrasz, gracias por rescatarme. Esperaba la muerte o algo peor, como servir de cena a estas alimañas infectadas de Plaga. Sí, la Plaga. Han sellado algún pacto con los jabaespines y el resultado es esta pesadilla.$B$BNo quiero limitarme a huir; quiero cambiar las cosas, por el bien de todos. ¿Quieres ayudarme? Seguro que es peligroso, pero no parece que el peligro te preocupe mucho.",
			complete = "¡Estupendo, lo sabía! Ya lo tenemos todo hecho. Si nos concentramos en lo que tenemos que hacer, todo irá bien.$B$BVoy a ponerte al día de los acontecimientos...",
		},
		[3524] = {
			title = "Varado",
			accept = "Se dice que hay unas majestuosas criaturas que van a las playas de Costa Oscura a morir encalladas. Últimamente, estas criaturas han empezado a llegar cada vez en mayor número a la costa. Yo he venido aquí a petición del Templo de la Luna para investigar el suceso, pero la gran cantidad de múrlocs que he encontrado en el agua dificulta mucho mis estudios.$B$BUna de esas gigantes criaturas llegó a la costa al sur de Auberdine para acabar rodeada de rabiosos múrlocs Bruma Gris. ¿Podrías ir a traerme algunos huesos de la criatura para que los estudie?",
			complete = "¡Espero que el múrloc no te pusiera difícil conseguirnos esto! Me aseguraré de mandar esto a Darnassus en el siguiente hipogrifo. El Templo de la Luna me ha concedido unos fondos para entregar a quien nos ayude. Te entrego una parte con nuestro agradecimiento.$B$BTu éxito me ha animado a ofrecerte la posibilidad de ayudar más al Templo de la Luna, si te interesa...",
		},
		[3525] = {
			title = "Extinguir el ídolo",
			accept = "Cerca de la entrada hay un ídolo que sirve de horno macabro para los jabaespines. Esas bestias consumen literalmente a quienes secuestran en Los Baldíos. Puedo cerrar el ídolo e impedir que vuelvan a usarlo, pero necesito tu ayuda. Llévame hasta el ídolo y ejecutaré mi ritual. Apenas si podré comunicarme contigo, por no hablar de defenderme. Protégeme; si me matan, será el fin para todos nosotros.$B$B¿Estás conmigo?",
			complete = "Belnistrasz ha dejado atrás un blandón ardiente. Miras la llama y tu mente se llena con la imagen de un gran dragón rojo. Oyes la voz de Belnistrasz.$B$B\"Los mortales sois los héroes que estaba esperando. Gracias por detener la matanza. Acepta esto como recompensa por tu heroicidad.\"",
		},
		[3526] = {
			title = "Ingeniería goblin",
			accept = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!$B$B$N, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "Bueno, $n, ¡has sido muy inteligente buscando mi enseñanza! Cualquier pringado puede convertirse en un experto de las bases de ingeniería, no hay más que ver a los gnomos y su irradiado hogar en Gnomeregan. Pero hace falta una mente fuerte y una mano FIRME para dominar la disciplina de la ingeniería goblin.$B$BEscucha con atención, $n, y puede que aprendas algo.",
		},
		[3527] = {
			title = "La profecía de Mosh'aru",
			accept = "La antigua profecía de Mosh'aru cuenta el modo de encerrar la esencia del dios Hakkar. Está escrita en dos tablillas que fueron depositadas en la ciudad trol de Zul'Farrak, al oeste de Gadgetzan.$B$B¡Tráeme las Tablillas Mosh'aru!$B$BLa primera tablilla obra en poder de un trol difunto llamado Theka el Mártir. Se dice que sus perseguidores fueron transformados en escarabajos que ahora vagan por los alrededores de su sepulcro.$B$BLa segunda tablilla está en manos de la hidromántica Velratha, cerca de la poza sagrada de Gahz'rilla.$B$BCuando tengas las tablillas, tráemelas.",
			complete = "¡Ah, qué bien! Puedo fusionar estas dos tablillas y después estudiar los secretos que encierran.$B$BMi deuda contigo va en aumento, $n, y continuará haciéndolo.",
		},
		[3528] = {
			title = "El dios Hakkar",
			accept = "Ha llegado la hora de atrapar la esencia del avatar de Hakkar.$B$BLleva el huevo de Hakkar a El Sagrario del Dios Caído que se encuentra en el Templo Sumergido de Azeroth. Convoca el poder del huevo para agitar al dios muerto.$B$BÉl enviará a sus esbirros a atacarte. Derrota a sus chupasangres y extráeles su sangre Hakkari. A continuación, utiliza la sangre para apagar las llamas eternas que protegen el espíritu de Hakkar. Cuando el fuego haya sido sofocado, el avatar de Hakkar entrará en nuestro mundo.$B$BDerrótalo y coloca su esencia en el interior del huevo de Hakkar.",
			complete = "¡La esencia de Hakkar está encerrada! ¡Aun así, el huevo rezuma vida! ¿Será cierto el mito sobre Hakkar?$B$BEspero que no pues quién sabe qué haría Hakkar si volviera a nacer. Guardaré el huevo en un lugar seguro para que no caiga en malas manos.$B$BTu trabajo conmigo ha concluido, $n. Ahora eres una auténtica leyenda y tus acciones algún día cambiarán nuestro mundo.",
		},
		[3541] = {
			title = "Entrega a Jes'rimon",
			accept = "Tengo un perista en Orgrimmar. Reside en La Calle Mayor. No es fácil dar con él si no sabes dónde buscar pero si miras en uno de los edificios más altos, no deberías tardar en encontrarlo.$B$BAunque hazme un favor, no vayas pregonando por todo Kalimdor que está allí y a qué se dedica, sería perjudicial para ambos.$B$BTe dará un precio más que correcto por la tablilla de Jin'yael. No sé muy bien por qué pero deberías haber visto lo nervioso que se puso cuando supo su paradero.",
			complete = "Ah, Jediga ha mandao su paquete desde Azshara. Bien. Qué ganas tenía de pillarlo.$B$BJediga, toda una mujer... mortal también. ¿Qué más se puede pedir?$B$BFíjate... la tablilla está en perfecto estado. Eres un mensajero daguten, $n.",
		},
		[3542] = {
			title = "Entrega a Andron Gant",
			accept = "Andron Gant es mi siguiente contacto. Suele andar por Entrañas... al ladito de El Apothecarium.$B$BTenía la lengua algo más suelta cuando se trataba de hablar de para qué quería la tablilla. Al parecer, algunos de los magos de Entrañas están estudiando algunos hechizos arcanos que los Altonato usaban. Piensan que esta tablilla los ayudará. Markri era un adepto a los conjuros de criaturas, sobre todo los elementales.$B$BLleva la tablilla de Markri y vuelve aquí para tu parte de la recompensa.",
			complete = "Toma, ahí van unas monedas... pa' que... <hic>... te compres una nueva armadura y tal...$B$BEsto supondrá una pieza o dos de oro pa' la gente... <hic> apropiada.",
		},
		[3561] = {
			title = "Entrega al archimago Xylem",
			accept = "Esta última tablilla es para alguien muy peligroso, $N. Créeme cuando te digo que confío menos en esta persona que en cualquiera de los otros a los que te he pedido que vayas a ver.$B$BEl archimago Xylem tiene una torre en las colinas que se elevan junto a Azshara. Es humano pero no se comporta como los humanos que he conocido... o matado. Exuda poder y no oso preguntarle cuáles son sus intenciones con la tablilla.$B$BVino a mi encuentro pero me dijo que su guardaespaldas Sanath me ayudaría a llegar a la torre cuando estuviera listo para verle. Busca a Sanath hacia el norte.",
			complete = "Ah, la tablilla de Sael'hai... ¡cuánto tiempo llevo esperando para estudiarla!$B$BGracias, $n. Puedes decirle a Jediga que ha hecho un buen trabajo. Esto sin duda vale el pago que pedía.",
		},
		[3562] = {
			title = "El pago de Magatha a Jediga",
			accept = "Llévale esta nota a Jediga. Dile que el pago estará aquí para ella cuando regrese. Y dile que estoy satisfecha con su trabajo.$B$BCorre, $N. Dile a tu maestra que estaré esperándola aquí.",
			complete = "Ah, bien. Fue mucho más razonable de lo que esperaba... al menos contigo. Casi esperaba que te castigara por mi insolencia al enviar a alguien en mi lugar. Debe de tener muchas ganas de hacerse con esa tablilla. Interesante.$B$BAlgo en lo que pensar en otro momento.",
		},
		[3563] = {
			title = "El pago de Jes'rimon a Jediga",
			accept = "Lleva esta carta a Jediga. Dile que nuestro trato ha sido provechoso y que estoy satisfecho con su trabajo.$B$BDile que regrese rápidamente a Orgrimmar y que Jes'rimon se asegurará de cuidar bien de ella.$B$BDile eso, y quizás en el futuro ya no necesitaré tus servicios otra vez, $N.",
			complete = "Veo que estaba más que contento por el aspecto de su nota... un pelín demasiado contento.$B$BQuizás algún día me tome el tiempo para asegurarme de que sepa cuánto aprecio también sus insinuaciones. Bueno, al menos hay una razón para desear pasar más tiempo en Azshara.$B$BAquí tienes tu parte del pago.",
		},
		[3564] = {
			title = "El pago de Andron a Jediga",
			accept = "Ahí va... lleva... (hic) esto a Jediga. ¡Que te vaya daguten!",
			complete = "Perfecto... espera un segundo.$B$B¡Ajá! ¿Qué le dijiste cuando le entregaste la tablilla, $n? ¡Se ha pasado tres pueblos con el pago! No es que me queje. ¿Le dijiste que el trato había cambiado? ¿O acaso estaba borracho para variar?$B$BDa igual... aquí tienes, parte extra para ti también.",
		},
		[3565] = {
			title = "El pago de Xylem a Jediga",
			accept = "¡¿Qué ocurre?! Ah sí, tu pago. Desde luego.$B$BToma esto y hasta luego. Seguro que Jediga aguarda con santa paciencia tu regreso.",
			complete = "¿Ninguna complicación? ¿Para nada? Bueno, eso casi merece quedar en los anales... Esperaba que mostrara algo de reticencia o que al menos traicionara nuestro pacto. Mmm, a lo mejor hasta es de fiar después de todo.$B$BBueno, tampoco hay que pensar tanto en eso. Aquí tienes tu parte Gracias por tu ayuda.",
		},
		[3566] = {
			title = "¡Arriba, Obsidion!",
			accept = "Era una trampa...$B$BPerdóname.$B$BMata a ese traidor. Hazlo por nosotros... Por Thorius.",
			complete = "<La cara de Thorius se pone blanca.>$B$BEsto... esto no puede ser. ¿Mi propio hermano? ¿Él preparó todo esto?$B$B<El rostro de Thorius se contrae de ira.>$B$B¡Me traicionó, traicionó a Forjaz! Parece que la influencia de los Dioses Antiguos sigue siendo fuerte en estas tierras. Me temo que si mi hermano, un hombre que alguna vez fue noble y honorable, se doblegó tan fácilmente a la voluntad de Ragnaros, nadie estará a salvo.",
		},
		[3567] = {
			title = "A la cima",
			complete = "¿Quieres ver la vista desde uno de los colosos gemelos? Porque puedo mandarte allí arriba, $r.$B$BPero tendrás que pensar tú en cómo harás para bajar. Yo te ofrezco solo el viaje de ida.",
		},
		[3568] = {
			title = "La filtración de la corrupción",
			accept = "¿Ves a la tauren que se encuentra detrás de mí, la que parece que va a estirar la pata de un momento a otro? Hace poco estuvo en Azshara. Afirma que unos nagas la hirieron cuando atravesaba las Ruinas de Eldarath.$B$BTras su enfrentamiento con ellos, se tomó un descanso en la playa y bebió de una de las pozas de las mareas. Ahora tiene náuseas... entre otros síntomas.$B$BMe gustaría descubrir qué ha bebido. Coge esta caja que contiene algunos viales vacíos que he etiquetado. Recoge muestras en las distintas pozas y regresa aquí.",
			complete = "Estupendo. Has vuelto y ella aún sigue con vida. Muy bien.$B$BPongámonos manos a la obra.$B$BLlevo un tiempo observando sus síntomas y esto no tiene buena pinta. De hecho, me sorprende que siga en pie. Ha vomitado unas cuantas veces... ¡no veas qué olor!$B$BDame un segundo para prepararlo todo y podremos hacer una prueba con nuestra amiga.",
		},
		[3569] = {
			title = "La filtración de la corrupción",
			accept = "Dale esto a Thersa. Quizás la cure... o quizás no. No lo sabremos hasta que se lo tome.",
			complete = "El químico Cuely está siendo muy amable conmigo... quizás en exceso. Si él dice que me ayudará, no tengo elección. No tengo tiempo para buscar una solución alternativa. Ya he hablado con sacerdotes y chamanes, y ninguno pudo ayudarme.$B$BEsperemos que la Madre Tierra vele por mi espíritu.",
		},
		[3570] = {
			title = "La filtración de la corrupción",
			complete = "Nunca hubiera imaginado que el elixir hiciera efecto tan rápido. Gracias, $n. Ahora me pondré manos a la obra con las demás muestras. Seguro que muy pronto les resultan de utilidad a Lady Sylvanas y a los Renegados.",
		},
		[3601] = {
			title = "¡Kim'jael, claro!",
			accept = "¡¡Kim'jael, claro!! ¿Sabes lo que significa Kim'jael para los elfos de sangre, $N? Ratita... o algo parecido. ¡Abusones!$B$BMe contrataron para que los ayudara a rastrear el área en busca de algún tipo de tesoro perdido. Por supuesto, no me lo pensé un momento cuando mencionaron el \"tesoro\" y el dinero que me iban a pagar pero claro, se volvieron contra mí e intentaron matarme... ¡A MÍ!$B$BToma prueba, un elfo de sangre no es de fiar.$B$BEl problema es que aún tienen mi equipo y no puedo recuperarlo. ¿Me ayudas?",
			complete = "¡Ea! ¡¿A que les has dado su merecido?!$B$B¡Estupendo! Eso enseñará a los elfos de sangre a no traicionar a sus socios... ¡y menos a alguien tan leal como un mercader goblin! ¡Bah, ¡elfos de sangre!$B$BBueno, lo mínimo que puedo hacer es pagarte por tu tiempo... como dije que haría.$B$BAquí tienes... deberían serte útiles.",
		},
		[3602] = {
			title = "Azsharita",
			accept = "Los ancianos gigantes de los acantilados al sur de la región de Azshara se alimentan de las rocas y de las edificaciones. El excremento resultante es un material altamente maleable, un cristal de increíble resistencia conocido como azsharita.$B$BEstas formaciones abundan en el arco sur pero rara vez se recuperan debido a la naturaleza de los gigantes es extremadamente violenta.$B$BHas de dirigirte al sur y recuperar suficiente azsharita para crear el cuerpo de la herramienta. Mis canes manáfagos te ayudarán a conseguir el cristal.",
			complete = "Tus tareas en Azshara están completas, mortal. Ahora debo forjar los componentes necesarios para el siguiente paso en tu aventura.",
		},
		[3621] = {
			title = "La formación de Aterravil",
			accept = "Las armas están listas para ser forjadas. Debes lograr que la azsharita adquiera un temple con potencia para dañar la energía vil.$B$BEn la Vega de Tuercespina encontrarás al herrero a la altura de esta tarea. Galvan el Antiguo, jefe de la Orden del mitril, fabricará las armas como tú se lo encargues. Encontrarás su campamento entre Zul'Gurub y el Túmulo Ogro Mosh'Ogg.$B$BQue tu determinación y fe te acompañen en tu odisea. Si fracasas, ten la certeza de que cuentas con el orgullo de tu dios, mortal.",
			complete = "Dios mío, solo puedo imaginar lo que pasaste para obtener estos materiales. Pocos se aventuran en Azshara y regresan con vida, ¡y mucho menos aquellos que se enfrentan a semidioses y gigantes!",
		},
		[3625] = {
			title = "Armas Fel en Azsharita encantada",
			accept = "$N, llevará un tiempo crear cada arma.$B$BAdemás, solo puedes usar el poder del Vilhechizo un minuto de cada tres. Sus propiedades debilitadoras contra Razelikh el Rapiñador y sus esbirros pueden tener una duración variable. ¡Por eso debes utilizar el Vilhechizo en el momento justo!$B$BAhora dame un momento para fabricarte el arma, $N.|n",
			complete = "<Galván se seca el sudor de la frente>.$B$BNunca ha existido un asesino de demonios mejor, $n.",
		},
		[3626] = {
			title = "Regresa a Las Tierras Devastadas",
			accept = "Se acerca la hora de la redención, $N. Debes regresar a Las Tierras Devastadas con tus nuevas armas y hablar con el héroe caído de la Horda, él te indicará tu objetivo final.|n",
			complete = "Te has curtido en la batalla, $n. ¿Estás $gpreparado:preparada; para enfrentarte a Razelikh y sus secuaces?",
		},
		[3627] = {
			title = "Juntar pedazos del amuleto",
			accept = "Para llegar hasta el Rapiñador, antes debes destruir la tríade de poderes y recuperar las piezas del amuleto. Cuando hayas recuperado las tres piezas, vuelve aquí y te daré el resto de las instrucciones.$B$B¡Vete, $N! ¡A Las Tierras Devastadas! ¡Sevine, Allistarj y Grol deben caer!|n",
			complete = "El amuleto de Razelikh el Rapiñador está una vez más completo, pero siente la interrupción en su cadena de mando. Sabe que vas a por él...",
		},
		[3628] = {
			title = "Eres Rakh'likh, demonio",
			accept = "La guarida de Razelikh está en la cima de la montaña más alta de Las Tierras Devastadas. La única forma de acceder es mediante las runas de teletransporte próximas a la montaña. Siempre que tengas el amuleto, podrás teletransportarte sin problemas hasta la guarida. Cuando llegues allí, debes invocar a la bestia. La clave está en el amuleto, $N. Utilízalo en el Altar de los Rapiñadores.$B$BSi logras derrotar al Rapiñador, tráeme su cuerno. Se convertirá en un símbolo de esperanza para quien lo vea, una prueba de que existen héroes en este mundo desgarrado por la guerra.|n",
			complete = "Hoy es un día que será recordado por toda la eternidad. ¡El señor supremo demoníaco de las Tierras Devastadas finalmente ha caído!",
		},
		[3629] = {
			title = "Ingeniería goblin",
			accept = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Menciono a los goblins puramente porque existen. Les gustan las cosas que explotan y les da igual quién esté en medio, aun ellos mismos.$B$BLéete este manual, $N. Si quieres hacerte saltar por los aires, ve a ver a Nixx Muellepiñón en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "Bueno, $n, ¡has sido muy inteligente buscando mi enseñanza! Cualquier pringado puede convertirse en un experto de las bases de ingeniería, no hay más que ver a los gnomos y su irradiado hogar en Gnomeregan. Pero hace falta una mente fuerte y una mano FIRME para dominar la disciplina de la ingeniería goblin.$B$BEscucha con atención, $n, y puede que aprendas algo.",
		},
		[3630] = {
			title = "Ingeniería gnómica",
			accept = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.$B$BLéete este manual, $n. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "¡Ah, un joven ingeniero interesado en seguir la única y verdadera disciplina de la ingeniería! Bueno, perdona mi melodrama, amigo. Si bien nuestra situación sigue siendo grave, ¡siempre es un buen día para ver a otro ingeniero responder la llamada de la verdadera ingeniería!",
		},
		[3631] = {
			title = "Invoca un corcel vil",
			accept = "Bah. Creo que no estás a punto, pero no soy yo quien decide. Strahad piensa lo contrario, así que haremos lo que quiere... por esta vez.$B$BQuiere hablar contigo lo antes posible. Estará en su torre con sus acólitos, más allá de Trinquete, en Los Baldíos.$B$BNo te entretengas por el camino.",
			complete = "Entonces, has decidido honrar mi presencia nuevamente. Qué amable de tu parte.$B$BMis acólitos se preguntaron si alguna vez aparecerías. Les dije que no había ninguna duda. Cuando se trata de energía, te atrae como una polilla a la llama.",
		},
		[3632] = {
			title = "Ingeniería gnómica",
			accept = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. ¡La ingeniería de los gnomos es mejor con diferencia! Se concentra en la creación de aparatos e instrumentos que hacen la vida más fácil.$B$BLéete este manual, $n. Si quieres saber más sobre el tema, llévaselo aI maestro manitas Sobrechispa, aquí en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "¡Ah, un joven ingeniero interesado en seguir la única y verdadera disciplina de la ingeniería! Bueno, perdona mi melodrama, amigo. Si bien nuestra situación sigue siendo grave, ¡siempre es un buen día para ver a otro ingeniero responder la llamada de la verdadera ingeniería!",
		},
		[3633] = {
			title = "Ingeniería goblin",
			accept = "La ingeniería avanzada se divide en dos disciplinas: la de los gnomos y la de los goblins. Claramente, la ingeniería goblin es la elección de todos los ingenieros brillantes. ¡Aprende a controlar el mundo a través del juicioso uso de potentes explosivos e increíbles aparatos!$B$B$N, lee este manual. Si quieres aprender ingeniería goblin, llévaselo a Nixx Muellepiñón que está en Gadgetzan. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "Bueno, $n, ¡has sido muy inteligente buscando mi enseñanza! Cualquier pringado puede convertirse en un experto de las bases de ingeniería, no hay más que ver a los gnomos y su irradiado hogar en Gnomeregan. Pero hace falta una mente fuerte y una mano FIRME para dominar la disciplina de la ingeniería goblin.$B$BEscucha con atención, $n, y puede que aprendas algo.",
		},
		[3634] = {
			title = "Ingeniería gnómica",
			accept = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.$B$B$n, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual aI maestro manitas Sobrechispa que está en Forjaz. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "¡Ah, un joven ingeniero interesado en seguir la única y verdadera disciplina de la ingeniería! Bueno, perdona mi melodrama, amigo. Si bien nuestra situación sigue siendo grave, ¡siempre es un buen día para ver a otro ingeniero responder la llamada de la verdadera ingeniería!",
		},
		[3635] = {
			title = "Ingeniería gnómica",
			accept = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.$B$B$N, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "Has venido a aprender sobre ingeniería gnómica, ¿eh? Bueno, has venido al gnomo correcto. Si bien la facción gobernante de Gnomeregan puede usar la política para condenar al ostracismo a quienes ven como una amenaza intelectual, saben que el conocimiento es algo que no pueden controlar.$B$BEllos y yo sabemos que cuando dejé Gnomeregan, perdieron a uno de sus mejores ingenieros gnomos con vida. Si eres un estudiante capaz, te enseñaré lo que sé.",
		},
		[3636] = {
			title = "Trae la Luz",
			accept = "La Plaga es una amenaza constante para la Alianza, lo cual no es nada nuevo. Hace poco, nos topamos con unos hallazgos muy peculiares, $n.$B$BEn los Baldíos existe un laberinto de púas llamado Zahúrda Rajacieno. Solía ser el hogar de jabaespines, pero ahora parece ser que han hecho algún tipo de pacto con la Plaga, creando criaturas mucho peores... Las gobierna el exánime Amnennar el Gélido.$B$BÚnete a la Luz, $n, y acaba con tal pacto.",
			complete = "Gracias, $n. La Plaga ahora se lo pensará dos veces antes de intentar incrementar sus ejércitos.$B$BQue la Luz te bendiga.",
		},
		[3637] = {
			title = "Ingeniería gnómica",
			accept = "En ingeniería avanzada te encuentras con dos escuelas: la de los gnomos y la de los goblins. Aunque yo piense que no sirve para nada, deberías de estar al corriente de la especialización de los gnomos. Crean objetos y aparatos que piensan van a cambiar el mundo, pero que raras veces funcionan.$B$B$N, lee este manual. Si deseas aprender a hacer pisapapeles metálicos, lleva el manual a Oglethorpe Obnoticus que está en Bahía del Botín. Recuerda que si te inscribes, no podrás pasarte luego a la otra escuela, ¡así que piénsatelo bien!",
			complete = "Has venido a aprender sobre ingeniería gnómica, ¿eh? Bueno, has venido al gnomo correcto. Si bien la facción gobernante de Gnomeregan puede usar la política para condenar al ostracismo a quienes ven como una amenaza intelectual, saben que el conocimiento es algo que no pueden controlar.$B$BEllos y yo sabemos que cuando dejé Gnomeregan, perdieron a uno de sus mejores ingenieros gnomos con vida. Si eres un estudiante capaz, te enseñaré lo que sé.",
		},
		[3638] = {
			title = "La promesa del secreto",
			accept = "La ingeniería goblin persigue que sus creaciones tengan una aplicación práctica real y un poder explosivo aún mayor. Nuestros esquemas nos permiten fabricar potentes bombas y un poderoso armamento. En el manual que has leído se explica todo.$B$BEn él también se cita el juramento que hace mucho tiempo hicimos de mantener nuestros esquemas en secreto. Si decides dedicarte a la ingeniería goblin, ya está. No tendrás acceso de ningún tipo a la ingeniería de los gnomos.$B$BSi aun así sigues queriendo convertirte en un ingeniero goblin, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $N.",
			complete = "¡Bienvenido a bordo, ingeniero goblin $n! Pronto tendrás acceso a los esquemas de ingeniería más poderosos en cualquier parte de Azeroth.$B$BAhora que te has comprometido a adquirir este conocimiento, veamos cómo se te da la ingeniería goblin. Después diseñaremos un currículo para desarrollar tus habilidades en ingeniería goblin.",
		},
		[3639] = {
			title = "Muestra tu trabajo",
			accept = "Como tu mentor, quiero muestras de tu trabajo. No hay duda de que eres $gun ingeniero hábil:una ingeniera hábil;, $N. Pero me gustaría estudiarlas para mostrarte cómo destacar las técnicas goblin en tus próximos trabajos. Esto es lo que necesito: veinte bombas de hierro grandes, veinte cartuchos de dinamita sólida y cinco ovejas explosivas... ¡y no olvides los seguros!$B$BSi me traes estos objetos te daré una tarjeta de miembro del Club de Ingeniería Goblin; la necesitarás para acceder a todos los instructores de ingeniería goblin.",
			complete = "¡Aquí tienes tu primera tarjeta de miembro del Club de Ingeniería Goblin!$B$BEsta tarjeta tiene pagados los primeros catorce días. Todas las tarjetas expiran después de dos semanas de actividad. Cuando suceda, visita a cualquier instructor goblin de ingeniería para comprar otra. Sin la tarjeta, tu membresía caducará temporalmente y no podrás acceder a los nuevos esquemas.$B$BEsto no afecta a tus conocimientos. Un ingeniero goblin nunca olvida lo que ya sabe.",
		},
		[3640] = {
			title = "La promesa del secreto",
			accept = "La ingeniería de los gnomos pone la teoría de la ingeniería al servicio de nuestras necesidades. Nuestros sistemas nos permiten fabricar instrumentos que controlan el mundo que nos rodea. El manual que has leído habla de eso.$B$BTambién explica que juramos mantener nuestros planos en secreto. Cuando te conviertas en $gun ingeniero:una ingeniera; gnomo, claro está. No podrás leer nada sobre la ingeniería goblin.$B$BSi ya te has decidido, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $n.",
			complete = "¡Bien, $n! Pronto tendrás acceso al mejor plan de estudios avanzado de ingeniería de Azeroth.$B$BVeamos cómo se te da la ingeniería gnómica y después diseñaremos un currículo adaptado a tus habilidades.",
		},
		[3641] = {
			title = "Muestra tu trabajo",
			accept = "Si lo que quieres es crear aparatos fantásticos, has venido al lugar adecuado. Puedo ver tu destreza en ingeniería, pero quiero algunas muestras de tu trabajo. Me gustaría ver si te puedo orientar hacia técnicas más gnómicas para el futuro. Necesito lo siguiente: 6 tubos de mitril, una mira de precisión y 2 muñecos-diana avanzados.$B$B¡Dame todo esto y te convertirás en $gun ingeniero gnómico:una ingeniera gnómica; con acceso a todos los esquemas!",
			complete = "Aquí tienes tu tarjeta de miembro del Club de Ingeniería Gnómica.$B$BCaduca a las 2 semanas; para renovarla, paga la cuota. Si no tienes la tarjeta, no podrás seguir estudiando hasta que la renueves.$B$BPero no olvidarás lo que hayas aprendido; la ingeniería gnómica es como ir en bicicleta.",
		},
		[3642] = {
			title = "La promesa del secreto",
			accept = "La ingeniería de los gnomos pone la teoría de la ingeniería al servicio de nuestras necesidades. Nuestros sistemas nos permiten fabricar instrumentos que controlan el mundo que nos rodea. El manual que has leído habla de eso.$B$BTambién explica que juramos mantener nuestros planos en secreto. Cuando te conviertas en $gun ingeniero:una ingeniera; gnomo, claro está. No podrás leer nada sobre la ingeniería goblin.$B$BSi ya te has decidido, firma este compromiso de secreto perpetuo y vuelve a hablar conmigo. Piénsatelo muy bien, $N.",
			complete = "¡Bienvenido a bordo, $n! Pronto tendrás acceso a los esquemas de ingeniería más avanzados de Azeroth.$B$BAhora que te has comprometido con la búsqueda de este conocimiento, es hora de examinar tu trabajo de ingeniería. A partir de aquí, te ayudaremos a crear un plan para maximizar tus talentos de Ingeniería Gnómica.",
		},
		[3643] = {
			title = "Muestra tu trabajo",
			accept = "Como tu mentor, quiero algunas muestras de tu trabajo. No hay duda de que eres $gun ingeniero hábil:una ingeniera hábil;, $N. Pero me gustaría analizar tu trabajo para mostrarte cómo destacar las técnicas gnómicas en tus próximos trabajos. Esto es lo que necesito: seis tubos de mitril, una mira de precisión y dos muñecos-diana avanzados.$B$BSi me traes estos objetos te daré una tarjeta de miembro del Club de Ingeniería Gnómica; la necesitarás para acceder a todos los instructores de ingeniería gnómica.",
			complete = "Aquí tienes tu tarjeta de miembro del Club de Ingeniería Gnómica.$B$BCaduca a las 2 semanas; para renovarla, paga la cuota. Si no tienes la tarjeta, no podrás seguir estudiando hasta que la renueves.$B$BPero no olvidarás lo que hayas aprendido; la ingeniería gnómica es como ir en bicicleta.",
		},
		[3644] = {
