		[5096] = {
			title = "Distracción Escarlata",
			accept = "Antes de ocuparnos de Andorhal, debemos afrontar el avance de la amenaza de la Cruzada Escarlata desde la Vega del Amparo. Han acampado entre el Campo de Piedramácula y el Llanto de Dalson, haciendo que corramos el riesgo de enfrentarnos a la Plaga y a la Cruzada al mismo tiempo.$B$BMi plan consiste en hacer que ambos se enfrenten, enviándote a destruir su tienda de mando. Utiliza algo de fuego en botella que encontrarás en esta caja de explosivos. Cuando esté arrasada, coloca este estandarte de la Plaga junto a la tienda. Con algo de suerte nos ignorarán y se centrarán en la Plaga en busca de venganza.",
			complete = "Una ejecución perfecta, $n. Tu ataque a la Cruzada Escarlata nos dará algo de tiempo. He enviado a uno de mis mejores exploradores para vigilar el campamento y asegurarnos de que las fuerzas de la Cruzada que vinieron a reforzar la posición se tragarán el anzuelo.$B$BCuando se aligere la presión a la que estamos sometidos deberíamos poder arriesgarnos a adentrarnos en Andorhal, una misión realmente importante. Por todos tus éxitos hasta la fecha, me encantaría que fueras tú quien se encargara también esta vez de la misión.",
		},
		[5097] = {
			title = "Todas las atalayas",
			accept = "Utilizando un instrumento mágico conocido como antorcha de aviso, puedo marcar objetivos a nuestra elección para futuras acciones de nuestras tropas. Para ese fin, pensamos que la Plaga está sirviéndose de las atalayas de Andorhal para controlar sus movimientos de tropas.$B$BTu misión: rompe las defensas de Andorhal y coloca antorchas en sus cuatro atalayas. Tendrás que estar en la entrada de las atalayas para colocar la antorcha, solo entonces quedarán marcadas. La antorcha de aviso solo tiene cinco cargas, así que úsalas con prudencia.",
			complete = "¡Mis sacerdotes informan de que nuestros rastreadores están recibiendo señales muy fuertes de las cuatro torres! No sé si debería decirlo, pero creo que has realizado otra misión con total y completo éxito. ¡Buena jugada de nuevo, $n!$B$BCon las torres marcadas, podemos pasar a los preparativos para el ataque. ¡Ha llegado el momento de combatir a la Plaga!",
		},
		[5098] = {
			title = "Todas las atalayas",
			accept = "Utilizando un instrumento mágico conocido como antorcha de aviso, puedo marcar objetivos a nuestra elección para futuras acciones de nuestras tropas. Para ese fin, pensamos que la Plaga está sirviéndose de las atalayas de Andorhal para controlar sus movimientos de tropas.$B$BTu misión: rompe las defensas de Andorhal y coloca antorchas en sus cuatro atalayas. Tendrás que estar en la entrada de las atalayas para colocar la antorcha, solo entonces quedarán marcadas. La antorcha de aviso solo tiene cinco cargas, así que úsalas con prudencia.",
			complete = "¡Mis brujos informan de que nuestros rastreadores están recibiendo señales muy fuertes de las cuatro torres! No sé si debería decirlo, pero creo que has realizado otra misión con total y completo éxito. ¡Buena jugada de nuevo, $n!$B$BCon las torres marcadas, podemos pasar a los preparativos para el ataque. ¡Ha llegado el momento de combatir a la Plaga!",
		},
		[5102] = {
			title = "Muerte al general Drakkisath",
			accept = "Luchamos contra estos animales en dos frentes: Desde nuestra capital de Ventormenta luchamos desde el interior y aquí, en Las Estepas Ardientes, libramos la batalla en su puerta. Debemos estar atentos, $n. Nadie debe librarse de nuestra ira, como ellos tampoco perdonaron nada en su asalto a nuestros hogares y familias.$B$BEncuentra al general Drakkisath ¡y destrúyelo!$B$BCiertamente la tarea no será sencilla pero la recompensa será extraordinaria.",
			complete = "Claro, ahora atacaremos a sus jefes dragones. ¡Muy bien, valiente soldado de la Alianza! ¡Pero que muy bien!",
		},
		[5103] = {
			title = "Muerte abrasadora",
			accept = "Lo único que queda de este humano son unos huesos carbonizados. Parece haber muerto al alcance de las manos de lo que perseguía, guanteletes de placas sin templar.$B$B¿Quizás debas coger los guanteletes y salir del fuego?",
			complete = "Que...",
		},
		[5121] = {
			title = "Gran Jefe Nevada",
			accept = "Aunque todavía sabemos muy poco de los motivos por los que los fúrbolgs han estado consumiendo esta extraña sustancia, creo que lo mejor será detenerlo antes de que acabe descontrolándose.$B$BLos fúrbolgs Nevada no suelen ser agresivos y este cambio en su comportamiento me obliga a pensar que deben estar bajo las órdenes de su jefe. Seguramente no podemos deshacer el daño ya hecho, pero creo que si su líder es asesinado, no seguirán empeorando.$B$BDirígete al Este, a Poblado Nevada.",
			complete = "Muchas gracias, $n. Espero volver a mis estudios sin tener que preocuparme por nuevas emboscadas. Por favor, acepta esto como recompensa.",
		},
		[5122] = {
			title = "El medallón de Fe",
			complete = "¡Has conseguido el medallón! Ahora podré abandonar por fin la capilla y cumplir con mi deber.$B$BEse deber es matar a la bestia que ayudó en mi corrupción y en la de tantos de mis hermanos y hermanas, ¡el Barón Osahendido!",
		},
		[5123] = {
			title = "La pieza final",
			accept = "El diario que llevaba consigo el gran jefe parece muy extenso, pero echas un vistazo a un par de páginas y descubres que no puedes leer el texto. Los signos son tan toscos y están tan mal escritos que no estás $gseguro:segura; de que nadie pueda leerlo.$B$BPero quizás Donova pueda decirte lo que dice...",
			complete = "Me pregunto qué significa todo esto... No entiendo nada...",
		},
		[5124] = {
			title = "Guanteletes de placas ígneas",
			accept = "¡Por las barbas de Thaurissan!$B$B¿Dónde los has encontrado?$B$BY lo más importante, ¿quieres compartirlos? Por supuesto, sería muy generosa ante un gesto tan noble.$B$BTe diré una cosa, $N. Si me das esos guanteletes de placas sin templar te enseñaré a hacer un juego por ti $gmismo:misma;. Todo lo que tienes que hacer es reunir los componentes para que pueda averiguar cómo se elaboran exactamente.$B$B¿¿Hay trato??$B$BEsta es la lista de todo lo que necesito, como vas a darme los guanteletes yo misma contribuiré con el torio sin encantar.|n",
			complete = "Como prometí, $N, ¡aquí está tu receta! También voy a agregar algo extra por todo tu arduo trabajo y dedicación. ¿¿Qué voy a hacer con esto de todos modos???",
		},
		[5125] = {
			title = "La estimación de Aurius",
			complete = "$n, me estoy muriendo... pero mi alma está salvada. Por eso, te debo más de lo que jamás podré expresar. Por favor, acepta esto, ¡y sigue luchando... valiente $c!",
		},
		[5126] = {
			title = "La historia de Lorax",
			accept = "El sátiro da vueltas y habla consigo mismo. ¿Quieres preguntarle algo?",
			complete = "<Lorax se ríe.>",
		},
		[5127] = {
			title = "La forja demoníaca",
			accept = "Lorax hace tratos, y no los acepta de insignificantes mortales.$B$BPero un trato haré contigo... coge este pico, está imbuido con poderosas energías malditas. Cuando encuentres a Goraluk Yunquegrieta, mátalo y atraviesa su corazón agonizante con este pico. Se hará un intercambio con su alma, su alma yo tendré. Devuelve el pico y devuelve el peto que robó el ladrón y te enseñaré lo que él iba a aprender.",
			complete = "Nuestro pacto no rompiste. El alma que me llevé. La recompensa que haré.",
		},
		[5128] = {
			title = "Palabras del Gran Jefe",
			accept = "Los Nevada han dejado de ser una amenaza para mí, pero si todavía quieres descubrir qué les empujó a crear y consumir esta extraña aguardiente, creo que deberías buscar a Kelek Guardacielo.$B$BEs miembro de un grupo conocido como el Círculo Esmeralda, unos druidas comprometidos a trabajar en Frondavil, sanando a la tierra de la corrupción.$B$BKelek tiene mucha experiencia con los fúrbolgs de Frondavil y tal vez pueda decirte algo más sobre el registro.$B$BGracias de nuevo, $N.",
			complete = "Sí, si me dejas examinarlo un momento quizás pueda traducirlo.$B$B<Kelek hojea las páginas.>$B$BTe avisaré cuando lo haya examinado por completo.$B$BGracias por compartirlo conmigo, $n. Sabemos muy poco de los furbolgs Nevada.",
		},
		[5141] = {
			title = "Peletería dragontina",
			accept = "La peletería dragontina no es fácil pero es muy gratificante. Te enseñaré a hacer estas magníficas mallas de armadura pero solo si aceptas ciertas condiciones.$B$BSi eliges este camino, aceptas no aprender nunca la peletería elemental ni la tribal; solo hay lugar para una de las tres en la cúspide del oficio. Es más, necesitaré muestras de tu mejor trabajo con armaduras de escórpidos. Por último, tendré que comprobar que eres capaz de adquirir la materia prima del negocio: las escamas de dragonante.",
			complete = "Se necesita una voluntad fuerte para tomar una decisión como la que acabas de tomar. Te lo aseguro, la peletería de escamas de dragón demostrará ser un camino rentable y gratificante para que lo sigas.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender como tuyo.",
		},
		[5142] = {
			title = "La pequeña Pamela",
			accept = "¡Cuántas vidas se perdieron en la Batalla de Villa Darrow! Muchos murieron... o peor.$B$BCuando la batalla comenzó, escondí a mi sobrina Pamela... Y no sé qué fue de ella. No soy más que un espíritu errante, pero mi corazón aún ansía conocer la suerte de Pamela.$B$BPor favor, $gbuen:buena; $C, ¿podrías ir a Villa Darrow en su busca? Está al este, más allá de Gangrena de Gahrron.",
			complete = "Hola. Soy Pamela. ¿Y tú cómo te llamas?",
		},
		[5143] = {
			title = "Peletería tribal",
			accept = "Para aprender peletería tribal es necesario entender la verdadera esencia de la naturaleza. Sé que ya has dominado el arte de crear armaduras de cuero salvaje y estoy deseando completar tu instrucción.$B$BHas de saber esto, $c: si eliges este camino, nunca podrás aprender peletería elemental o dragontina; solo hay lugar para la práctica de una de las tres artes. Bien, ahora tráeme las mejores muestras de tu armadura de cuero salvaje. Cuando lo hagas, empezaremos tu instrucción.",
			complete = "Has dado tus mejores ofrendas y la naturaleza pronto te permitirá doblegarla a tu voluntad. Una vez que haya terminado mi tutela, tu trabajo será una fuerza de la naturaleza en sí misma.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender.",
		},
		[5144] = {
			title = "Peletería elemental",
			accept = "Mi especialidad es la peletería elemental. Si quieres abrir tu mente a los poderes mayores de la sustancia, te enseñaré todo lo que sé.$B$BDebes saber, $c, que si aceptas estas lecciones te comprometes a no aprender peletería tribal ni dragontina; solo puedes aprender una de las tres artes. Además, tienes que probarme que estás en armonía con los elementos naturales; tráeme esencia pura de agua, tierra, viento y fuego.",
			complete = "Has echado tu suerte y los elementos te aceptan. Una vez que haya terminado mi tutela, confeccionarás los mejores atuendos de cuero.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender.",
		},
		[5145] = {
			title = "Peletería dragontina",
			accept = "La peletería dragontina no es fácil pero es muy gratificante. Te enseñaré a hacer estas magníficas mallas de armadura pero solo si aceptas ciertas condiciones.$B$BSi eliges este camino, aceptas no aprender nunca la peletería elemental ni la tribal; solo hay lugar para una de las tres en la cúspide del oficio. Es más, necesitaré muestras de tu mejor trabajo con armaduras de escórpidos. Por último, tendré que comprobar que eres capaz de adquirir la materia prima del negocio: las escamas de dragonante.",
			complete = "Se necesita una voluntad fuerte para tomar una decisión como la que acabas de tomar. Te lo aseguro, la peletería de escamas de dragón demostrará ser un camino rentable y gratificante para que lo sigas.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender como tuyo.",
		},
		[5146] = {
			title = "Peletería elemental",
			accept = "Mi especialidad es la peletería elemental. Si quieres abrir tu mente a los poderes mayores de la sustancia, te enseñaré todo lo que sé.$B$BDebes saber, $c, que si aceptas estas lecciones te comprometes a no aprender peletería tribal ni dragontina; solo puedes aprender una de las tres artes. Además, tienes que probarme que estás en armonía con los elementos naturales; tráeme esencia pura de agua, tierra, viento y fuego.",
			complete = "Has echado tu suerte y los elementos te aceptan. Una vez que haya terminado mi tutela, confeccionarás los mejores atuendos de cuero.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender.",
		},
		[5147] = {
			title = "Se busca: Arnak Tótem Siniestro",
			accept = "Se busca: Arnak Tótem Siniestro$B$BSe busca a Arnak el Paria por los atroces crímenes de asesinato y secuestro. Quienes tengan la valentía de traer a este criminal ante la justicia recibirán una generosa recompensa.$B$BArnak fue visto por última vez en los riscos situados al lado de Cumbre de la Nube Negra. Para reclamar tu recompensa enseña una prueba de tus acciones al vigiarrisco Cuerno Largo en Poblado Viento Libre.",
			complete = "¡Ja! ¡Qué noticia tan estupenda! ¡Empezaba a pensar que nunca recibiría su merecido!$B$BAquí tienes, $n... y gracias. Con solo oír hablar de Arnak me hervía la sangre...",
		},
		[5148] = {
			title = "Peletería tribal",
			accept = "Para aprender peletería tribal es necesario entender la verdadera esencia de la naturaleza. Sé que ya has dominado el arte de crear armaduras de cuero salvaje y estoy deseando completar tu instrucción.$B$BHas de saber esto, $c: si eliges este camino, nunca podrás aprender peletería elemental o dragontina; solo hay lugar para la práctica de una de las tres artes. Bien, ahora tráeme las mejores muestras de tu armadura de cuero salvaje. Cuando lo hagas, empezaremos tu instrucción.",
			complete = "Has dado tus mejores ofrendas y la naturaleza pronto te permitirá doblegarla a tu voluntad. Una vez que haya terminado mi tutela, tu trabajo será una fuerza de la naturaleza en sí misma.$B$BPara formarte en este arte, en el futuro, simplemente habla conmigo y pondré a tu disposición cualquier conocimiento que aún puedas aprender.",
		},
		[5149] = {
			title = "La muñeca de Pamela",
			accept = "Mi tía Marlene me dijo que me quedara aquí en casa porque mi padre tenía que ir a luchar. ¡Mi padre es el hombre más valiente del mundo!$B$BPero llevo aquí mucho tiempo y no ha venido a buscarme. A veces viene gente mala y me susurra... y yo quiero que mi papá los eche ¡pero no está aquí!$B$BY a veces, cuando está oscuro, quiero jugar con mi muñeca, pero no puedo porque me la dejé en la aldea.$B$B¿Irás a buscar a mi muñeca?",
			complete = "¡La has encontrado! ¡Has encontrado a mi muñeca! ¡Gracias!",
		},
		[5150] = {
			title = "¡Dadanga tiene hambre!",
			complete = "Parece que a Dadanga le gustan los brotes que le has traído.$B$BA cambio, te entrega un pequeño paquete.",
		},
		[5151] = {
			title = "Hipercondensador",
			accept = "Soy el único superviviente del ataque centauro a nuestra caravana. Una extraña aunque poderosa pantera está custodiando mi mejor invención, y la tiene alrededor del cuello. ¡Ja! Hasta los centauros tiemblan al verla.$B$BAquí tienes la llave de la jaula de pantera. Ya no queda nada allí, solo la pantera. Acaba con esa bestia, tráeme el hipercondensador y te recompensaré.$B$BLos restos de la caravana están al norte de aquí.|n",
			complete = "¡Mi hipercondensador! Esto me mantendrá ocupado hasta que pueda descifrar para qué sirve...",
		},
		[5152] = {
			title = "Tía Marlene",
			accept = "¡Estoy tan sola! ¿Dónde está mi familia? La tía Marlene me dijo que me quedara aquí, ¡pero luego se fue y todavía no ha vuelto! Y mi papá... ¿lo has visto?$B$BIgual la tía Marlene sabe dónde está. Vive cerca de Andorhal, en una casa que hay al sur. Creo que estaba en un monte... bueno, ella dijo que estaba en una colina.$B$BPor favor, $N. ¡Eres mi $gnuevo amigo:nueva amiga;! ¿Irás a hablar con mi tía de mi parte?",
			complete = "¿Has visto a Pamela? ¿Y cómo está? ¿¿Está viva?? ¡Oh, no! ¡Pobre Pamela! Era tan joven y tan alegre...$B$BNo sabe lo que le ocurrió a su padre, ¿verdad? ¿Mi hermano Joseph?$B$BNo... ella no podía entender lo que le ocurrió a Joseph. Y aunque pudiera, no tengo valor para contárselo...",
		},
		[5153] = {
			title = "Una extraña historiadora",
			accept = "Me gustaría que Joseph pudiera reunirse con su hija, pero no puede ser. Su alma fue corrompida por la Plaga y se convirtió en un monstruo. ¡Está condenado!$B$BPero quizás podamos cambiar su suerte.$B$BBusca en las tumbas que hay fuera del monumento a Joseph. Su cuerpo no está ahí, pues fue pisoteado y destruido hace años, pero sí encontrarás otra cosa bajo el monumento: su alianza. Lleva ese anillo a Cromi... Es una gnoma extraña de poderes aún más extraños.$B$BCromi está en la posada en ruinas que hay en la esquina noroeste de Andorhal.",
			complete = "¿Qué es esto? ¿Una alianza? Déjame verla...$B$B¡Aah! Este anillo tenía su lugar en la mano de un gran hombre... pero el pasado de ese hombre está lleno de tragedia.$B$B¿Estás aquí para ayudarle? Es demasiado tarde para él... ¡pero quizás podamos ayudarle desde el pasado!",
		},
		[5154] = {
			title = "Las Crónicas de Villa Darrow",
			accept = "Para salvar a Joseph Rutagrana, primero debemos conocer su pasado. Y en eso nos ayudarán las Crónicas de Villa Darrow, un libro que está en el ayuntamiento de Andorhal.$B$BTráeme ese libro. Así podremos conocer el destino de Joseph y, con suerte, ¡cambiarlo!",
			complete = "¡Bien hecho, lo tienes!$B$B¿Lo has leído? ¿Se menciona a Joseph Rutagrana? Si se habla de él, ¡quizás podamos salvarle!$B$BAh. Las Crómicas de Villa Darrow cuentan una historia tremenda. Dicen que durante la batalla, Joseph Rutagrana fue corrompido y que se unió a las filas de la Plaga. Traicionó a los defensores de Villa Darrow.$B$BQué destino atroz. Deberíamos intentar cambiar ese destino, ¿no te parece?",
		},
		[5155] = {
			title = "Las fuerzas de Jaedenar",
			accept = "Si he de confiar en ti para esto, primero tienes que demostrarme que mereces mi confianza.$B$BHe de saber que eres $gun enemigo:una enemiga; del Consejo de la Sombra que tanta maldad ha causado aquí y al otro lado de nuestras fronteras.$B$BAdéntrate en la profundidad de Frondavil. Al oeste verás un camino que te conducirá a Jaedenar. Ahí es donde el Consejo trama sus complots con la Legión Ardiente.$B$BAdéntrate en la profundidad de uno de los Túmulos corruptos en los que viven y mata a todos. Vuelve a mí cuando hayas acabado. Entonces sabré que de verdad quieres ayudarnos.",
			complete = "¡Bien, $n! Ahora que su número se debilita, podemos presionarles más.$B$B¿Qué tal te supo esa primera cata de su poder? ¿Son tan fuertes como pensaste que serían? ¿Más fuertes? ¿O resultaron no ser un desafío a tu altura? Eso sería fantástico.$B$BPero ya discutiremos los detalles de tus hazañas más tarde. Ahora tenemos que concentrarnos en otras cosas.",
		},
		[5156] = {
			title = "Investigación acerca de la corrupción",
			accept = "Al norte, al lado este del camino, en lo que se llama la Cañada Gran Cicatriz, hay una zona en la que los infernales fueron invocados durante la Gran Guerra... los cráteres aún marcan la tierra... como lo hacen los propios infernales.$B$BSiento curiosidad por dos cosas. Primera: ¿aún vagan los elementales entrópicos por esta área? Y segunda: ¿los cráteres contienen aún el agua corrupta y fétida que se acumuló allí hace años? ¿Me ayudarás a saciar mi curiosidad, $n? Pero ve con cuidado, los infernales destruyen todo lo que encuentran en su camino.",
			complete = "Me alegra que sigas con vida, $n. Pero me preocupa que esa agua aún exista. Esperaba encontrar al menos una fuente de agua pura en Frondavil. Pero parece que mi búsqueda ha sido un fracaso. El proceso de curación de la tierra habría sido mucho más sencillo de haber existido tal fuente.$B$BTendré que centrarme en salvar a las criaturas del bosque que aún puedan salvarse mientras destruyo a las que se han corrompido tanto que son un peligro para sí mismas y para los viajeros que atraviesen este bosque que antaño fuera tan poderoso.",
		},
		[5157] = {
			title = "Recolección de agua corrupta",
			accept = "En lo más profundo de Jaedenar se encuentra la Guarida Sombría, la principal fortaleza de su mal y su corrupción.$B$BEl Consejo de la Sombra ha dispuesto unos blandones alrededor de su guarida que no son sino la forma externa de sus hechizos de protección. Si quiero averiguar algo más sobre nuestro enemigo, es necesario extinguir esos blandones. Una vez extinguidos, debería poder espiar al Consejo y averiguar quién lo lidera.$B$BSi puedes, coge esta cantimplora y llénala en la Poza de la Luna que hay en el centro de Jaedenar. Vuelve a mí después.",
			complete = "Esta agua nos servirá, $n.$B$BAhora solo nos queda purificarla antes de utilizarla en los blandones. No debería ser difícil, pero requiere un viajecito.$B$BEspero que podamos hacerlo rápido.",
		},
		[5158] = {
			title = "En busca de ayuda espiritual",
			accept = "Lleva el agua corrupta a Los Baldíos, $N. Al sur de Trinquete, escondida en la costa, vive una vieja amiga mía, una chamán llamada Islen Vidente del Agua. Es poderosa y nos ayudará. Siempre ha tenido una fuerte relación con los Espíritus del Agua. La nuestra es una noble misión. Eso convencerá a Islen y a los espíritus. Nos ayudarán.$B$BLa encontrarás en un pequeño campamento en la orilla. Y, $N, ignora a los piratas. Son ruidosos y molestos, pero no representan una amenaza para ti.",
			complete = "Ah, necesitas limpiar el agua de esta Poza de la Luna. Detener esta fuente de maldad de Frondavil es una noble acción, pero yo no soy quién para decidir si el agua será purificada. Preguntaré a los espíritus del Agua. Ellos son quienes deciden si la causa es justa.$B$BDame un momento, les hablaré de tu ruego. Espero que simpaticen con tu causa como yo.",
		},
		[5159] = {
			title = "El agua purificada regresa a Frondavil",
			accept = "Da gracias a los espíritus, $N. Son ellos los que han acudido en tu ayuda, no yo.$B$BAhora te doy esta agua purificada. Saluda a Greta de mi parte y transmítele mis mejores deseos. Está enfrentándose a algo que nos supera a muchos de nosotros... Pronto se dará cuenta.$B$BEl Consejo de la Sombra no es una fuerza que pueda subestimarse, $N. Recuérdalo.$B$BAhora ve. Coge el agua y vuelve con Greta.",
			complete = "Esta agua debería ser suficiente para nuestros propósitos.$B$BMe alegra que Islen pudiera ayudarnos. Su fuerza sobre los espíritus del agua ha sido siempre considerable. Y también es sabia. Raras son las veces que los espíritus no están de acuerdo con ella. El hecho de que ambos hayan bendecido nuestra causa me da esperanza: estamos en el buen camino.",
		},
		[5160] = {
			title = "El Protectorado de la matrona",
			accept = "Viaja a Kalimdor, $r. Nuestro Vuelo encuentra su hogar en el gélido paisaje de la Cuna del Invierno. Cuando llegues a la Cuna del Invierno, encuentra las cavernas de Mazthoril.$B$BEn los helados suelos de Mazthoril encontrarás runas de cobalto. Con una de mis escamas en la mano, ponte de pie sobre una runa y te verás transportado hasta Haleh, nuestra madre protectora.$B$BDale la escama para que pueda ver lo que he visto y sentido, aquí en este condenado lugar.",
			complete = "Los Aspectos insisten en que nos mantengamos al margen de los asuntos de los mortales. En este mundo, sin embargo, no siempre es posible tal cosa, especialmente cuando uno de los nuestros ignora una y otra vez esta regla.",
		},
		[5161] = {
			title = "La cólera del Vuelo Azul",
			accept = "Comprendemos lo que intenta hacer el maldito camada de Alamuerte y sabemos que no podemos permitirlo.$B$BLa protección que la Montaña Roca Negra ofrece a Nefarian hace que intervenir sea cada vez más difícil.$B$BPodemos, eso sí, otorgarte poderes mortal... si así lo decidieras.$B$BEl camino que se abre ante ti está lleno de peligros. Debes decidir si aceptas nuestra ayuda. Pondera nuestra oferta y vuelve a hablar conmigo cuando hayas tomado una decisión.",
			complete = "Que así sea...",
		},
		[5162] = {
			title = "La cólera del Vuelo Azul",
			accept = "Es la magia Arcana que controlo y la magia Arcana que te enviará a tu siguiente destino.$B$BCuando estés $glisto:lista; comenzará el viaje. A las Tierras de la Peste irás y con Jeziba hablarás.$B$BEs un mortal tan sabio como los ancestros y tan paciente como la tierra inmóvil. Búscalo en Andorhal.|n",
			complete = "Soy Jeziba, conocido por muchos como el Escultor. Pero lo que esculpo no son estatuas, son héroes.",
		},
		[5163] = {
			title = "Yeti... ¿ya hemos llegado?",
			accept = "¡Ya está todo listo, $N!$B$BYa he escrito a mis amigos diciéndoles que tengo una sorpresa para ellos. ¡Y aquí es donde tú entras en juego!$B$BVoy a darte mi yeti mecánico. Para sorprender a mis amigos, les harás una visita, encenderás el yeti y lo mandarás hacia ellos.$B$BCuando se lo hayas enseñado a Legacki en Vista Eterna, a Roxio en Gadgetzan y a Quixxil en el Refugio de Marshal, ¡vuelve aquí y cuéntame lo que ha pasado!$B$BPor favor, cuando vuelvas devuélveme también mi yeti.",
			complete = "¡Ja! ¡Se lo pensarán dos veces antes de volver a reírse de mis ideas!$B$BGracias por tu ayuda, $n. ¡Sin tu ayuda no habría podido divertirme tanto!",
		},
		[5164] = {
			title = "Catálogo del Díscolo",
			accept = "Mejor instrumento de justicia, Haleh no podría haber encontrado. Lee el Catálogo del Díscolo e ilumínate.$B$BSi persistieras... lo que te pido hacer debieras... si sobrevivieras... en héroe $gconvertido:convertida; te vieras.",
			complete = "El libro parece componerse de cientos y cientos de páginas llenas de texto enrevesado, garabatos y símbolos.",
		},
		[5165] = {
			title = "Sofocar las llamas de protección",
			accept = "Debes regresar a Jaedenar. Los blandones están, casi con toda seguridad, diseminados por la Guarida Sombría. Sofoca sus llamas y las protecciones que el Consejo ha erigido caerán, al menos durante un corto período de tiempo. Yo estaré esperando a que ocurra. Entonces echaré un vistazo a las entrañas de la Guarida e intentaré averiguar quién es la cabeza de esta bestia. Después de eso, y no antes, hablaremos de un ataque directo.",
			complete = "Pude verte con mis hechizos en cuanto murieron las llamas del último blandón. Buen trabajo, $n.$B$BConseguí averiguar algunas cosas antes de que los brujos del Consejo de la Sombra reaccionaran. Espero que sea suficiente.$B$BAhora descansa un poco. Te diré lo que he averiguado en un momento.",
		},
		[5166] = {
			title = ", el que tal vez sea el más difícil de todos los c",
			accept = "La forja de una poderosa coraza que sirva de protección contra los implacables ataques del Vuelo Cromático es obra de la ironía.$B$BLas escamas de las bestias que combatimos deben coserse al caparazón prístino de un draco o dragón cromático. Por el momento no se sabe de su existencia, y esperemos que nunca lleguen a existir.$B$BY por último, el que tal vez sea el más difícil de todos los componentes: la sangre de héroes.$B$BFinalmente es el Escultor el que debe forjar esta creación.",
			complete = "¿Aún no lo entiendes? El viaje fue el destino. ¿No puedes sentir las cicatrices de la batalla? ¿El dolor que sufriste?$B$BHabiendo sobrevivido a la terrible experiencia, eres un ser más poderoso. Mucho más poderoso. Esta coraza es simplemente un reflejo de tus propias habilidades innatas.",
		},
		[5167] = {
			title = "Quijotes del desafiante cromático",
			accept = "Para dar forma al fundamento de los leotardos se necesita el caparazón de un draco cromático adulto. Las escamas cromáticas luminosas se disponen en capas sobre el armazón y se encantan con la Sangre de los héroes. Por último, se aplica la flexible piel de Sombra al interior de las grebas.",
			complete = "Olerán a sus parientes cuando entres en sus pasillos, $n. ¡Aplastarlos con su propio miedo!",
		},
		[5168] = {
			title = "Los héroes de Villa Darrow",
			accept = "Los héroes de Villa Darrow tienen un lugar en mi corazón y el libro que me trajiste, las Crónicas de Villa Darrow, cuenta sus historias.$B$BHabla del paladín Davil Fuegoluz y de cómo la Cruzada se llevó su tratado al concejo de Vega del Amparo.$B$BTambién hay pasajes que hablan de mi hermano, el capitán Rutagrana. Después de su traición, su escudo fue quebrado y desechado y ahora yace en el más improbable de los lugares: cerca del granero de Gangrena de Gahrron.$B$BReúne esas reliquias, $N. La fatalidad y la tragedia las rodea.",
			complete = "¡Tienes el libro y el escudo!$B$BSu historia está entrelazada con la de Villa Darrow y, de alguna forma, sé que el destino volverá a unirlos.",
		},
		[5181] = {
			title = "Los villanos de Villa Darrow",
			accept = "Las Crónicas de Villa Darrow hablan de los villanos de esa batalla. Cuentan cómo el Señor de los necrófagos Horgus el Devastador fue destruido por las fuerzas de la Alianza durante la batalla. Su cuerpo fue arrojado a un lago al noroeste del Cruce de Corin y su calavera aún está allí.$B$BMarduk el Negro nunca fue derrotado, pero su mítica espada se rompió y se perdió. Yace al fondo de una garganta al oeste del Cruce de Corin.$B$BRecupera esos objetos, $N. No sé por qué, pero sé que su destino está en tus manos.",
			complete = "¡Las has encontrado! ¡Bien hecho, $n! Estas reliquias poseen un poder que no entiendo del todo, un poder que un día controlarás.$B$BY también me traen recuerdos oscuros, recuerdos de muerte y traición, y de la última noche de Villa Darrow...",
		},
		[5201] = {
			title = "Intrusión Nevada",
			accept = "La mayoría no advierte mi presencia, $n. Pero hay un problema que parece firmemente arraigado aquí, en Cuna del Invierno: los fúrbolgs Nevada.$B$BAunque nunca he atacado directamente a los fúrbolgs, parecen enloquecidos, y temen todo lo que encuentran a su paso. Los he visto matar incontables criaturas que tuvieron la desgracia de estar en el lugar y en el momento equivocados.$B$BEstoy harto de su intromisión... por favor, ayúdame a combatirlos. Mata a los fúrbolgs y mantenlos alejados de la Roca Sable de Hielo.",
			complete = "Me alivia escuchar que, por un momento, no tendremos que preocuparnos por la intrusión de los Nevada.$B$BEstás empezando a mostrar tu perseverancia, $n.",
		},
		[5202] = {
			title = "Una extraña llave roja",
			accept = "La pequeña llave roja parece estar hecha con algún tipo de hueso. Pesa bastante, pero parece muy frágil. ¿Por qué tendría un miembro del Consejo de la Sombra algo así? Quizás esta llave abra algo que está en Jaedenar.",
			complete = "¡La llave! ¡La has encontrado! ¡Dámela, por favor, para que pueda escapar por fin!",
		},
		[5203] = {
			title = "Rescate de Jaedenar",
			accept = "Pero, por mucho que me duela, he de hacer una cosa antes: tengo que encontrar la espada de Trey, Forjaluz, y escapar de la Guarida Sombría para informar a mis superiores de lo que está ocurriendo aquí. ¿Puedes ayudarme, $N?$B$BNuestro equipamiento no está lejos de aquí. Y tú ya has demostrado que puedes sobrevivir al camino hasta la cima.$B$BCuando escapemos, yo me dirigiré a Darnassus y tú a buscar a mi amiga Jessir cerca de la frontera de Vallefresno. Teníamos que encontrarnos en el campamento del Círculo Esmeralda que hay cerca de allí.$B$B¿Qué dices, $N? ¿Puedes ayudarme una vez más?",
			complete = "¿Eres tú quien ayudó a Arko a escapar? Cómo me alegro de que me hayas encontrado. Ella pasó por aquí hace no mucho, de camino a Darnassus. Forjaluz iba pisándole los talones y no tenía ni tiempo para hablar con los druidas y hacer que le curaran las heridas. Dijo que tenía mucha prisa.$B$BPero sí me contó tu encuentro con el espíritu de Trey. Qué destino tan cruel para un caballero de la Mano de Plata. Ella intentaba ocultarlo, pero era evidente que la pérdida que ha sufrido le está desgarrando las entrañas.",
		},
		[5204] = {
			title = "Reprensión de la Luz",
			accept = "Ella quiere aparentar que está bien. Le encantaría que yo pensara que es fuerte y que puede con todo esto sola, pero sé que no es así. La muerte de Trey, haber oído la tortura a la que fue sometido... son cosas que van a perseguirla mucho tiempo y no hay nada que podamos hacer para impedirlo. Pero sí podemos darle algo de paz.$B$B$N, vuelve a la Guarida Sombría, mata al torturador de Trey y encuentra sus restos. No veo por qué no podemos atar esos cabos sueltos mientras Arko'narin llora por él a su manera.",
			complete = "Reúnes los restos del paladín con tanto cuidado como puedes, recordando que al menos su espíritu ha sido liberado del sufrimiento que pudieran haberle infligido.",
		},
		[5206] = {
			title = "Los merodeadores de Villa Darrow",
			accept = "Cromi dijo que las reliquias que reuniste son componentes de un potente hechizo. Para completarlo se necesita solo una cosa más: calaveras de los miembros de la Plaga que tomaron parte en la Batalla de Villa Darrow.$B$BCoge este cristal y ve a buscar las calaveras de los campeones de la Plaga. El cristal está encantado: si lo pasas cerca de la calavera de un Campeón que participó en la batalla, su calavera resonará. Tráeme las calaveras que resuenen.$B$BVe, $N. Encontrarás campeones de la Plaga en El Claro Ponzoñoso del norte y en la Cuenca Fungal al oeste.",
			complete = "¡Las has encontrado! ¡Estupendo!$B$BAunque no acabo de entender bien cómo pueden ayudarnos, siento su poder y, en mi fuero interno, sé que están relacionadas con mi hogar, con Villa Darrow.",
		},
		[5210] = {
			title = "Carlin, el hermano de Joseph",
			accept = "Con mi magia he añadido páginas al final de las Crónicas de Villa Darrow... ahora su historia llega más allá de la batalla. Uno de los pasajes añadidos habla de otro Rutagrana, Carlin, que sobrevivió a la traición de Joseph. Ahora Carlin está en las Tierras de la Peste, en la Capilla de la Esperanza de la Luz.$B$BLlévale el libro y habla con él.",
			complete = "¿Qué libro es este? ¿Las Crónicas de Villa Darrow? Ese era mi hogar antes de la guerra... ¡antes de que aquella batalla lo destruyera! ¿Por qué me has traído este libro?$B$B¡Mira aquí! ¡Al final hay unas páginas que cuentan los días que siguieron a la batalla! ¡Y este pasaje habla de mí! ¡Y hay otro sobre mi hermano Joseph! ¿Lo que dice este libro es cierto?$B$B¡Hemos de saber la verdad!",
		},
		[5211] = {
			title = "Los defensores de Villa Darrow",
			accept = "Muchos de los defensores perecieron en la Batalla de Villa Darrow. Y muchos de ellos vagan ahora como fantasmas al servicio de la Plaga. Debes encontrar a estas pobres almas y acabar con su miseria.$B$BCaza necrófagos caníbales, necrófagos balbuceantes y despellejadores malsanos. Muchos de estos mefistos antaño eran ciudadanos de Villa Darrow. Si destruyes su forma actual, liberarás sus almas.$B$BLos puedes encontrar en el Bosque de la Peste y en el Cruce de Corin, así como en otros bastiones de la Plaga esparcidos por las Tierras de la Peste del Este.",
			complete = "Me alegra oír que encontraste las almas torturadas de mis hermanos y que las liberaste. Mi corazón sufrirá menos sabiendo que al menos algunos de los defensores de Villa Darrow se han liberado de la tiranía de la Plaga.",
		},
		[5212] = {
			title = "La carne no miente",
			accept = "Los boticarios Renegados no son los únicos seres de este mundo versados en las ciencias.$B$BYo he estudiado la peste de la Plaga durante años, $r. Pensábamos que la potencia de la plaga había mermado, pero lo que he descubierto aquí, en las Tierras de la Peste es alarmante. ¡La plaga está cobrando fuerza!$B$B¡Necesito hacer más pruebas! La fuente más potente de plaga se encuentra en la carne infestada de sus víctimas más recientes. Viaja a Stratholme y tráeme algunas muestras, $n.|n",
			complete = "Algo ha cambiado en la estructura química de los agentes activos de la peste. Necesitamos más datos.",
		},
		[5213] = {
			title = "El agente activo",
			accept = "Tendrás que adentrarte más en Stratholme, $N.$B$BDetrás de las primeras puertas encontrarás a los zigurats. Sabemos que la Plaga extrae un gran poder de esas estructuras. Examina los zigurats y vuelve con cualquier información que consigas.|n",
			complete = "¡Increíble! Llevará meses diseccionar y analizar esto. El Alba Argenta te agradece tus esfuerzos, $n.$B$BElige entre este Sello del Amanecer y esta Runa del Amanecer, con nuestra bendición. Puedes utilizar cualquiera de los dos en lugar de una Comisión del Alba Argenta estándar para recoger piedras de la Peste para nosotros. Si se te pierde, habla conmigo y te conseguiré un reemplazo.",
		},
		[5214] = {
			title = "El gran Ezra Grimm",
			accept = "Es terrible... lo que le ocurrió a Ezra. Verás, saquearon el pueblo y Ezra no quería dejar sus preciados bienes atrás. Lo último que recuerdo es que decía que quemaría hasta la última hoja antes de permitir que ellos les pusieran sus sucias y malditas manos encima.$B$BDisfruto un buen cigarro como el primero, pero no soy tonto. Aquel día dejé atrás a Ezra y a su aromático almacén. Supongo que todo fue pasto de las llamas, pero si hubiera sobrevivido aunque fuera una sola caja de su famoso tabaco...$B$B¿Qué dices, $n? ¿Encontrarás una caja para el viejo Smokey?",
			complete = "Oh, tabaquito, tabaquito dulce, cuánto te he echado de menos...",
		},
		[5215] = {
			title = "Las calderas de la Plaga",
			accept = "En las tierras del antiguo Lordaeron hay ocho calderas, cuatro aquí, en el Oeste, y cuatro más ocultas en el Este. Estas calderas vomitan veneno en el aire, propagando la Peste de la Plaga por todo el país.$B$BEl poder nigromántico de Kel'Thuzad es demasiado fuerte para desactivar por completo esas calderas pero creemos tener un modo de subvertirlas en nuestro provecho. Mi segunda, la suma sacerdotisa MacDonnell, será tu guía en esta misión, ella seguirá dándote información a partir de este momento.",
			complete = "Que el poder de la Luz te ilumine en estos tiempos sombríos, $c. Me complace servirte como coordinadora en nuestro plan para sabotear las calderas de la Plaga.$B$BNuestro objetivo será alterar la composición de la peste que crean los calderos, convirtiéndola en algo que afecte negativamente a la Plaga. Para conseguir este cambio tendrás que acceder a las cuatro calderas de las Tierras de la Peste del Oeste.$B$BHas de estar $gpreparado, héroe:preparada, heroína;, ¡te espera una batalla gloriosa contra la vil Plaga!",
		},
		[5216] = {
			title = "Objetivo: Campo de Piedramácula",
			accept = "De las cuatro calderas que hay aquí, en el Oeste, la localizada en el Campo de Piedramácula puede ser la más fácil de acceder. La Plaga tiene allí las tropas menos experimentadas, aunque no hay que subestimarlas.$B$BVe al Campo de Piedramácula, al noroeste de Andorhal, y ocúpate de su señor de la caldera. Creemos que tendrá una llave que te permitirá acceder a la caldera. Cuando lo hayas conseguido, utiliza esta botella para obtener una muestra de los venenos que hay en su interior. La necesitaremos para estudiar el desarrollo de un contraagente.",
			complete = "La llave que has conseguido del señor de la caldera Garravil encaja perfectamente y abre el panel de acceso. Un hedor nauseabundo emana del panel una vez abierto, al tiempo que una mezcla desconocida de sustancias concentradas se arremolina en el interior de la caldera.$B$BHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la suma sacerdotisa MacDonnell en el Alto del Orvallo.",
		},
		[5217] = {
			title = "Regresa al Campamento del Orvallo",
			accept = "Llenas la botella con brebaje venenoso de la caldera suficiente para obtener una muestra de estudio.$B$BCon el veneno en tus manos, es hora de regresar con la suma sacerdotisa MacDonnell en el Campamento del Orvallo y completar tu misión.",
			complete = "Bien hecho, $n, el alquimista Arbington no debería necesitar mucho tiempo para analizar esto y preparar un contraagente que introducir en la caldera. Si pudiéramos propagar suficiente contraagente en el aire podríamos debilitar la Plaga de este lugar.$B$BSerá sin duda un duro esfuerzo pero no podemos dejar de atentar contra esas calderas ni de introducir nuestros componentes en su mezcla. Sin embargo, si pudiéramos seguir así tendríamos una enorme ventaja sobre la Plaga cuando llegara el momento de la batalla.",
		},
		[5218] = {
			title = "La caldera del Campo de Piedramácula",
			complete = "Al agregar los reactivos a la mezcla del caldero, este comienza a cambiar el color y la textura de la nube que arroja. Los miembros de la Plaga que están cerca del caldero parecen retroceder ante la introducción de los nuevos componentes en el medio ambiente.",
		},
		[5219] = {
			title = "Objetivo: Llanto de Dalson",
			accept = "Una de las calderas de peste está localizada en el campo de una antigua granja, ahora conocida como el Llanto de Dalson. Bien, ¡hoy no deberíamos derramar ni una sola lágrima, el día en el que estamos desbaratando los planes la Plaga y les estamos ahogando en sus propios gases!$B$BVe al Llanto de Dalson, al norte de Andorhal, y elimina al señor de la caldera que encontrarás en él. Como el anterior, debería tener una llave para acceder a la caldera. Utiliza esta botella para obtener una muestra del interior de la caldera. Cada una de ellas tiene su propia mezcla de toxinas.",
			complete = "La macabra llave que encontraste en el señor de la caldera se desliza suavemente en la cerradura y desaparece, permitiéndote acceder permanentemente al panel. Unos icores crudos y viscosos palpitan a través de tubos retorcidos en el interior de la caldera.$B$BHay una pequeña espita en la que encaja la botella y puedes recoger una muestra para la suma sacerdotisa MacDonnell en el Alto del Orvallo.",
		},
		[5220] = {
			title = "Regresa al Campamento del Orvallo",
			accept = "Llenas con cuidado la botella con una cantidad de icor de la caldera que te parece suficiente como muestra de estudio.$B$BCon el veneno en tus manos, es hora de regresar con la suma sacerdotisa MacDonnell en el Campamento del Orvallo y completar tu misión.",
			complete = "Ah, aquí hay mucho que estudiar. ¡Bien hecho, $n!$B$BPor ahora, el siguiente paso está en nuestras manos. Tendremos que producir una lista de componentes que combinados con lo que ya está en la caldera actúen como su contrario.$B$BEl único modo en el que podremos conseguirlo es poniendo los componentes directamente en la caldera. El alquimista Arbington tendrá más información, así que no olvides hablar con él en cuanto te sea posible.",
		},
		[5221] = {
			title = "La caldera del Llanto de Dalson",
			complete = "Al agregar los reactivos a la mezcla del caldero, este comienza a cambiar el color y la textura de la nube que arroja. Los miembros de la Plaga que están cerca del caldero parecen retroceder ante la introducción de los nuevos componentes en el medio ambiente.",
		},
		[5222] = {
			title = "Objetivo: El Tormento",
			accept = "Dos de las calderas han sido abiertas con éxito, puedas acceder a ellas indefinidamente pero todavía queremos que abras las otras dos. ¡Eso nos dará a todos más oportunidades para introducir el contraagente!$B$BEsta vez, te dirigirás contra la caldera de El Tormento. Está al este de Andorhal, bastante cerca de los muros de la ciudad en ruinas. De nuevo, elimina al señor de la caldera y recoge la llave. Utiliza esta botella para obtener la muestra de la caldera.$B$B¡Buena caza, $N!",
			complete = "La llave del señor de la caldera abre el panel de acceso a esta caldera y luego desaparece, al igual que las otras llaves de los dos calderos anteriores. Una sustancia de olor pútrido se agita violentamente debajo de la plataforma del caldero.$B$BHay un pequeño grifo debajo del cual encaja la botella lo suficientemente bien, lo que te permite extraer una muestra para la Suma Sacerdotisa MacDonnell en el Campamento del Orvallo.",
		},
		[5223] = {
			title = "Regresa al Campamento del Orvallo",
			accept = "Llenas con delicadeza la botella vacía. Una muestra de la nauseabunda sustancia que se agita bajo la plataforma de la caldera rezuma ahora en el interior del frágil contenedor de cristal.$B$BCon el veneno en tus manos es hora de regresar con la suma sacerdotisa MacDonnell en el Campamento del Orvallo y completar tu misión.",
			complete = "¡Otra misión finamente ejecutada, $n! Esto pone a nuestra disposición tres calderos para volverlos contra la Plaga. Si el dominio nigromántico de Kel'Thuzad sobre estas tierras no fuera tan fuerte como lo es actualmente, ¡me atrevería a decir que las cerrarías por completo!$B$BEl alquimista Arbington tendrá un informe sobre lo que este caldero, al igual que los otros calderos, requerirá para entregar nuestro contraagente a la plaga. ¡Con eso, ha llegado el momento de traer el último caldero del oeste bajo nuestra influencia!",
		},
		[5224] = {
			title = "La caldera de El Tormento",
			complete = "Al agregar los reactivos a la mezcla del caldero, este comienza a cambiar el color y la textura de la nube que arroja. Los miembros de la Plaga que están cerca del caldero parecen retroceder ante la introducción de los nuevos componentes en el medio ambiente.",
		},
		[5225] = {
			title = "Objetivo: Gangrena de Gahrron",
			accept = "La última de las calderas está situada en una granja ahora conocida como la Gangrena de Gahrron. Está custodiada por algunos de los esbirros más duros de la Plaga, concretamente fantasmas y espectros. No se puede jugar con ellos, $N.$B$BLa Gangrena de Gahrron está al noreste de nuestra posición, cerca del comienzo de las Tierras de la Peste del Este. De nuevo, elimina al señor de la caldera y hazte con la llave. Toma esta botella de muestras y devuélvemela cuando esté llena. Que la Luz te proteja en esta peligrosa misión, $c.",
			complete = "La llave del señor del Caldero se desintegra cuando toca la cerradura en el panel de acceso en la base de la plataforma del caldero. Se escucha un ligero ruido metálico en el interior y el panel de acceso se abre para revelar más toxinas viscosas dentro del marco del caldero.$B$BHay un pequeño grifo debajo del cual encaja la botella lo suficientemente bien, lo que le permite extraer una muestra para la Suma Sacerdotisa MacDonnell en el Campamento del Orvallo.",
		},
		[5226] = {
			title = "Regresa al Campamento del Orvallo",
			accept = "Cierras con cuidado la espita del panel de control, observando cómo los icores pútridos de la caldera van llenando la botella.$B$BCon el veneno en tus manos es hora de regresar con la suma sacerdotisa MacDonnell en el Campamento del Orvallo y completar tu misión.",
			complete = "¡Felicitaciones $n, has desbloqueado el último caldero para nosotros! El alquimista Arbington pronto sabrá los reactivos necesarios para este caldero.$B$BEn cuanto a ti, estoy seguro de que el comandante Valorfist querrá agradecerle personalmente la ayuda que nos has brindado. Sin ti, nuestra lucha contra la Plaga habría sido casi insuperable. ¡Gracias, $ghéroe:heroína;!",
		},
		[5227] = {
			title = "La caldera de la Gangrena de Gahrron",
			complete = "Al agregar los reactivos a la mezcla del caldero, este comienza a cambiar el color y la textura de la nube que arroja. Los miembros de la Plaga que están cerca del caldero parecen retroceder ante la introducción de los nuevos componentes en el aire.",
		},
		[5228] = {
