		},
		[6645] = {
			title = "El favor de la Hermandad, cuero del núcleo",
			complete = "Tu ofrenda ha sido aceptada. El favor has obtenido. Sigue así y se te permitirá el acceso a los negocios ancestrales.",
		},
		[6646] = {
			title = "El favor de la Hermandad, gota de sangre de la montaña",
			complete = "Tu ofrenda ha sido aceptada. El favor has obtenido. Sigue así y se te permitirá el acceso a los negocios ancestrales.",
		},
		[6661] = {
			title = "A por las ratas del tranvía subterráneo",
			accept = "Alto ahí, pillastre. Eeeh... ¿Eeestás buscando curro? Nos tenemos un problemón de ratas aquí abajo y nos faltan manos en la cubierta de popa.$B$B¿Qué respondes? Solo tienes que coger esta flauta atrapa-ratas y tocar la canción alrededor de esas alimañas. ¡Te seguirán al fin del mundo!$B$BCaptúranos cinco de esos bichos y tráenoslos acá. Nos los queremos vivos.$B$BEeeh...",
			complete = "Esto va bien, $gamigo:amiga;. Mi hermano las necesita vivitas y coleando, de lo contrario se ponen amargas... No querrás probar ninguna brocheta de rata agria.",
		},
		[6662] = {
			title = "Mi hermano Niblis",
			accept = "Mi hermano Niblis dirige una operación de kebab de rata al otro lado de la estación de Ventormenta. Tú le llevas este envase de carne misteriosa a él, antes de que se estropeen. ¡Venga, en marcha, tú!$B$BHas viajado antes en tren, ¿no? Es fácil. Cuando llega, te subes a bordo y disfrutas del trayecto. Eso sí, brazos y piernas dentro durante el viaje, si no quieres lisiarte de por vida.",
			complete = "Pobre Monty. Desde el incidente de Gnomeregan, no ha sido el mismo. Ese niño nunca ha visto un océano en su vida, y mucho menos ser una especie de pirata.$B$B<Nipsy suspira.>$B$BAl menos mantiene el flujo de las criaturas retorciéndose.",
		},
		[6681] = {
			title = "Mansión Ravenholdt",
			accept = "$N,$B$BRavenholdt se ha interesado por ti, maleante. Hemos estado observando. Tu estilo es un poco torpe, pero se puede arreglar.$B$BSi deseas aprender del maestro Ravenholdt y ser miembro de la liga de Asesinos, tienes que llevar el Sello de Ravenholdt, incluido en esta carta, a la Mansión Ravenholdt.$B$BTu primera prueba es encontrar la mansión, que está escondida en las colinas de Trabalomas.$B$BSaludos,$B$BFahrad",
			complete = "Excelente.$B$BHa sido duro, pero pareces estar bien.$B$BTe espera un viaje largo y gratificante. ¿Te atreves a aceptar tu destino entre los señores de Ravenholdt?$B$BHabla con los guardias, te explicarán qué debes hacer.",
		},
		[6701] = {
			title = "Emblemas de la Hermandad",
			complete = "¡Buen trabajo! Sigue así y a lo mejor los demás hasta te respetan un poco.",
		},
		[6721] = {
			title = "El camino del cazador",
			accept = "Hola, joven $gcazador:cazadora;. Tienes cara de ser capaz de domar a una bestia.$B$BVe a ver a Dazalar a Dolanaar. Él puede enseñarte a conseguir tu propia mascota.|n",
			complete = "Sí, es el momento, $n.",
		},
		[6722] = {
			title = "El camino del cazador",
			accept = "Hola, joven $gcazador:cazadora;. Tienes cara de ser capaz de domar a una bestia.$B$BVe a ver a Dazalar a Dolanaar. Él puede enseñarte a conseguir tu propia mascota.",
		},
		[6741] = {
			title = "¡Más botines!",
			complete = "Gracias otra vez, $n. Eres motivo de orgullo para la Horda.",
		},
		[6761] = {
			title = "La nueva frontera",
			accept = "He delegado en mi segundo, Mathrengyl Garroso, todo lo relacionado con la llamada de socorro de Claro de la Luna. Habla con él de este asunto. NO conmigo.$B$BY deja que te diga una cosa: fui YO quien nos sacó de la oscuridad cuando no quedaban esperanzas para nuestra raza. NO el Círculo Cenarion de Claro de la Luna. ¡Teldrassil nos da a todos una nueva vida! Intentan hacernos creer lo que quieren, ¡pero solo los tontos se creerían esa propaganda!$B$BTú decides si estás en el grupo de los tontos o no.",
			complete = "Sí, $c, gracias por venir. Siento el malentendido... el aire está saturado de la desconfianza entre el archidruida y el guardián Rémulos de Claro de la Luna. Cada uno acusa al otro de maquinar algo y el hecho de que las extrañas corrupciones de Teldrassil no remitan no contribuye precisamente a relajar este ambiente de desconfianza.$B$BEn cualquier caso, seguimos teniendo un deber para con el Círculo Cenarion, aunque aquellos que lo lideran no estén de acuerdo entre sí.",
		},
		[6762] = {
			title = "Rabine Saturna",
			accept = "El mayordomo del guardián Remulos, Rabine Saturna, está en Claro de la Luna buscando ayuda para explorar los vastos páramos al oeste de Tanaris e incluso más al oeste de Un'Goro. Podrás encontrarlo en Amparo de la Noche, la aldea más grande de Claro de la Luna.$B$BAunque tu trabajo será sin duda un beneficio tremendo para todos, te aconsejo que vayas con cuidado. Entre Darnassus y Claro de la Luna hay ciertas tensiones que... podrían crecer a lo largo del tiempo.",
			complete = "Soy Rabine Saturna. Te doy la bienvenida de parte del guardián Rémulos y de los demás habitantes de este sagrado Claro.$B$BAprecio tu interés y tu deseo de asistir al Círculo Cenarion. Sé también que el archidruida de Darnassus te expresó su desprecio por prestarnos ayuda. Puedes estar seguro de que esto es por un bien mayor y de que estarás a salvo de cualquier represalia malvada de la que puedan hacerte objeto.$B$BAquí estás entre amigos, $n.",
		},
		[6781] = {
			title = "Más restos de armadura",
			complete = "Estas piezas son muy buenas, $n. Puedo usarlas para confeccionar nuevos equipos para nuestros soldados.$B$BSi mi nivel de suministro llega a ser suficientemente alto, ¡a lo mejor nuestras avezadas unidades de combate irán al campo de batalla!",
		},
		[6801] = {
			title = "Lokholar, el Señor del Hielo",
			complete = "Se ha derramado sangre enemiga. Mezclaré esta sangre con el resto de elementos que hemos recolectado. Cuando la ofrenda esté completa, el Señor del Hielo enseñará a esos perros Pico Tormenta ¡toda la ira del clan Lobo Gélido!",
		},
		[6804] = {
			title = "Agua envenenada",
			accept = "Una fuerza de exploradores elementales enviada a las Tierras de la Peste del Este de Lordaeron fue apestada por la corrupción del lugar. ¡Los Señores del Agua no podemos tolerar este insulto a nuestra pureza!$B$BToma este frasco. Contiene un aspecto de Neptulon. Eliminará el veneno de los elementales apestados. Pero el conflicto interno les conducirá a una enajenación transitoria.$B$BDomina a los descontrolados y tráeme sus brazales de vínculo.",
			complete = "Buen trabajo, $c. Esos elementales eran una ofensa a todos los seres del agua. Nuestra fuerza reside en la pureza y la necesitamos para ganar esta guerra.",
		},
		[6805] = {
			title = "Sirocosos y reptarenas",
			accept = "Nosotros, los elementales del agua, estamos en guerra con los seres de los elementos menores. ¡Demuestra que estás de nuestra parte!$B$BMuy lejos hacia el sur, en el desierto de Silithus, viven los siervos del aire y la tierra, en un pedazo de roca llamado La Vega de Cristal. Protegen objetos de poder frente a seres inferiores, mortales, y aunque ignoro por qué lo hacen, deseo contrariarlos.$B$BVe a La Vega de Cristal, en Silithus, y derrota a nuestros enemigos. Después vuelve a verme.",
			complete = "Has demostrado tu valía. Puede que tenga más tareas para ti, dignas de un aliado de los Señores del Agua.",
		},
		[6821] = {
			title = "Ojo del Brasadivino",
			accept = "Has demostrado que puedes derrotar a nuestros enemigos y encargarte de misiones para la causa de los Señores del Agua. Pero hasta ahora solo te has enfrentado a enemigos menores... ¿Podrás vencer a un enemigo más poderoso?$B$BEsa es tu nueva misión.$B$BLos orcos han apresado a un siervo del fuego, el Piroguardián Brasadivino, en Cumbre de Roca Negra. Encuentra dónde lo tienen cautivo, mata a sus captores y luego al piroguardián. Tráeme su ojo; me mostrará tu valor.",
			complete = "Has demostrado que tienes fuerza y astucia.$B$BCreo que ganarás muchos honores en nuestras filas...",
		},
		[6822] = {
			title = "El Núcleo de Magma",
			accept = "$n, ha llegado el momento de ponerte a prueba de verdad. ¿Te atreves?$B$BHay un pasaje al Núcleo de Magma en lo más hondo de las Profundidades de Roca Negra. Es un bastión del enemigo, defendido por los siervos del fuego más fuertes de este mundo.$B$B$N, ve al Núcleo de Magma y demuéstrame que tienes fuerza y determinación para vencer a lo que te encuentres allí.$B$BSi tienes algún aliado, llévalo contigo. Para salir con vida del Núcleo de Magma necesitarás todo un ejército.",
			complete = "Has hecho lo imposible: ¡enfrentarte a los seres del Núcleo de Magma y vivir para contarlo!$B$BTienes muchos recursos pese a tu pequeño tamaño.$B$BEspero que algún día se forme una alianza entre tu raza y los Señores del Agua.",
		},
		[6823] = {
			title = "Agente de Hydraxis",
			accept = "Si deseas aliarte con nosotros, lucha contra nuestros enemigos, los siervos del aire, la tierra y el fuego. Cada derrota que les inflijas les debilitará y probará que eres fiel a nuestra causa.$B$BLa campaña será larga, pero si perseveras recibirás grandes honores y gloria.",
			complete = "Se habla de tus hazañas en todos los salones de los Señores del Agua, $n. Había quien pensaba que tu raza es demasiado pequeña y frágil, pero has conseguido lo imposible: te has ganado nuestro respeto.",
		},
		[6824] = {
			title = "Las manos de los enemigos",
			accept = "$N, te tenemos en alta estima. Por eso nos resistimos a enviarte a esta última misión; no queremos perder a alguien tan útil como tú.$B$BPero si tienes éxito, la ayuda a nuestro esfuerzo de guerra sería tan grande que merece la pena arriesgar tu vida.$B$BDebes ir al Núcleo de Magma y asesinar a estos capitanes: Lucifron, Sulfuron, Gehennas y Shazzrah. ¡Mátalos y tráeme sus manos!$B$BEsta misión exigirá toda tu capacidad, $N, pero si lo consigues asestarás un terrible golpe a los señores del Fuego.",
			complete = "¡Has eliminado a los capitanes! Si no fuera porque sé de lo que eres capaz, no me lo creería.$B$B$n, has demostrado antes tu valor, pero esta hazaña será cantada en los salones de los Señores del Agua. Te vas a convertir en una leyenda.$B$BVuelve a hablar conmigo; puede que tenga otra misión.",
		},
		[6825] = {
			title = "La llamada del aire: flota de Guse",
			complete = "La flota se alimenta de su carne. Consume al enemigo.$B$B¡El vuelo es inminente!",
		},
		[6826] = {
			title = "La llamada del aire: flota de Jeztor",
			complete = "¡Más! ¡Más! ¡Tráeme más, que pronto estarán listos!",
		},
		[6827] = {
			title = "La llamada del aire: flota de Mulverick",
			complete = "¡No hay suficiente! Esperaría este nivel de trabajo de un Iniciado ¡¿pero de ti, $n?! ¡Vamos, soldado! ¡DATE PRISA! ¡Hace falta más carne!",
		},
		[6844] = {
			title = "Umber, el archivista",
			accept = "Todavía queda mucho por hacer aquí, pero creo que es vital llevar esto al Círculo para que lo analicen. Confía en mí... todavía quedará mucho trabajo por aquí cuando termines. Si dentro de este pegajoso esqueleto hay un diario, el Círculo podría tener por fin una ventana al pasado.$B$BLleva esto al archivista del Círculo en Amparo de la Noche. Se llama Umber y es brillante. Está algo tocado, eso seguro, ¡pero brillante de todas formas! Umber ha recuperado libros en mucho peor estado que este. Si se puede salvar, él puede hacerlo.",
			complete = "¡Por las barbas de los sapos! ¿Qué llevas ahí? Tiene forma de libro... Intentaré romper la estructura que lo cubre.$B$B¿Layo te ha enviado a buscarme desde Silithus? Tan solo he oído susurros silenciosos, bueno, no tan silenciosos si los he oído, claro, sobre los horrores que están ocurriendo allí. Une eso a mi aversión por los bichos y tendrás la razón perfecta para que me quede aquí con los libros.",
		},
		[6845] = {
			title = "Desvelar los secretos del pasado",
			accept = "Tendrás que venir a verme pronto, si es que quieres saber lo que había aquí. En cuanto lo averigüe, y desde luego si es un libro, te lo haré saber con sumo gusto.$B$BMientras tanto, iré a consultar a la madre del cubil, Rabine. Seguro que le interesa saber a qué te has estado dedicando. Nunca la hagas esperar, $N, a no ser que quieras que te embadurne de miel.$B$BCréeme, no sería la primera vez.",
			complete = "Me alegro de verte, $n.$B$BTe estaba esperando para comunicarte la gratitud del Círculo Cenarion por tu ayuda. Acepta esto como muestra de agradecimiento.$B$BMuchas gracias, $c.",
		},
		[6846] = {
			title = "¡Al ataque!",
			complete = "¡Ah, las órdenes! Dicen que debo atacar a voluntad, y mi voluntad dice... ¡ahora!",
		},
		[6847] = {
			title = "El ojo que todo lo ve del maestro Ryson",
			accept = "Tu guerra en el corazón de Alterac no significa nada para la Hermandad, $c. Haremos lo que siempre hemos hecho: esperar hasta que un vencedor surja de las cenizas, acabe con toda esta locura y entonces dé el golpe definitivo.$B$BAunque no hemos venido para eso. El Ojo que todo lo ve se ha perdido, lo han arrebatado los trols Hacha Invernal de la región.$B$BRecupera el Ojo y nos pondremos a tu servicio por el tiempo que quede por tu favor.$B$BRegresa cuando consigas el Ojo para que pueda examinarte.$B$B<el maestro Ryson esboza una sonrisa>.",
		},
		[6848] = {
			title = "El ojo que todo lo ve del maestro Ryson",
			accept = "Tu guerra en el corazón de Alterac no significa nada para la Hermandad, $c. Haremos lo que siempre hemos hecho: esperar hasta que un vencedor surja de las cenizas, acabe con toda esta locura y entonces dé el golpe definitivo.$B$BAunque no hemos venido para eso. El Ojo que todo lo ve se ha perdido, lo han arrebatado los trols Hacha Invernal de la región.$B$BRecupera el Ojo y nos pondremos a tu servicio por el tiempo que quede por tu favor.$B$BRegresa cuando consigas el Ojo para que pueda examinarte.$B$B<el maestro Ryson esboza una sonrisa>.",
		},
		[6861] = {
			title = "La unidad trituradora portátil de Zinfizzlex",
			accept = "Estoy tan ansioso como tú por probar mi nueva trituradora, $r, pero antes de que pueda fabricarla, voy a necesitar materiales, ¡muchos materiales!$B$BPara ser exactos, voy a necesitar una montaña de torio, mitril y hierro. También necesitaré una sierra de vapor por unidad. Tendrás que conseguirlas en la serrería.$B$BCuando estaba curioseando por aquí (antes de mi captura) me fijé en una pila de sierras de vapor en el aserradero Pico Tormenta.",
		},
		[6862] = {
			title = "La unidad trituradora portátil de Zinfizzlex",
			accept = "Estoy tan ansioso como tú por probar mi nueva trituradora, $r, pero antes de que pueda fabricarla, voy a necesitar materiales, ¡muchos materiales!$B$BPara ser exactos, voy a necesitar una montaña de torio, mitril y hierro. También necesitaré una sierra de vapor por unidad. Tendrás que conseguirlas en la serrería.$B$BCuando estaba curioseando por aquí (antes de mi captura) me fijé en una pila de sierras de vapor en el aserradero Lobo Gélido.",
		},
		[6881] = {
			title = "Ivus, el Señor del Bosque",
			complete = "Muy bien, $n. Usaré el poder de este talismán para aumentar la magia que ya se ha reunido. Cuando hayas acumulado suficiente poder, concentraré las energías reunidas e invocaré al Señor del Bosque para que nos ayude en nuestra causa.",
		},
		[6901] = {
			title = "Lanzar el ataque",
			complete = "¡Ya es hora! ¡Ahora podemos mostrarle a la Alianza su locura al venir al Valle de Alterac!",
		},
		[6921] = {
			title = "Entre ruinas",
			accept = "El Martillo Crepuscular se ha trasladado a las ruinas del Santuario Lunar de las Cavernas de Brazanegra. Su presencia solo puede servir para forzar a los elementos a actuar contra nosotros. Si no nos ocupamos de ella, esta región caerá en sus manos definitivamente.$B$B$n, dirígete a Brazanegra y encuentra la piedra de las profundidades en las ruinas; debería estar cerca, en el agua. En su interior hay un núcleo de las profundidades, un dispositivo que cuando se lee correctamente, revela la historia de toda actividad elemental. Si lo consigo, y con la ayuda de los miembros del Anillo de la Tierra, ¡quizás podamos detenerlos!",
			complete = "Esto es exactamente lo que necesito. Un núcleo de las profundidades es un pozo de información que nos reportará muchas cosas buenas. Sea lo que sea lo que el Martillo Crepuscular está tramando ahí dentro, y seguro que no puede ser nada bueno, mis camaradas lo descubrirán.$B$BLo has hecho muy bien hoy; el Anillo de la Tierra te mira con cariño por ayudarnos. Además has ayudado al conjunto de la Horda y eso es algo que debería enorgullecerte.",
		},
		[6922] = {
			title = "Barón Aquanis",
			accept = "El elemental de agua derrotado ha dejado tras de sí un extraño globo de agua. Supones que el objeto de alguna forma alimentaba la energía de la bestia. En el interior del globo chapotea masa líquida repulsiva. El propio globo parece impermeable a todo tipo de fuerza física.$B$BSi alguien es capaz de interpretar este artilugio, es Je'neu Sancrea del Anillo de la Tierra.",
			complete = "Esto... esto es un hallazgo, $n.$B$B¿Y dices que lo conseguiste del barón Aquanis en Brazanegra? Hace tiempo que se cree que el barón Aquanis es un poder elemental corrupto; este globo demostrará qué fue exactamente lo que lo corrompió. Aunque no nos sorprendería que resultara ser el Martillo Crepuscular, nuestros estudios revelarán también cómo lo hicieron.$B$BHas hecho bien en traerme esto. Te lo ruego, llévale esto junto con los mejores deseos del Anillo de la Tierra.",
		},
		[6941] = {
			title = "La llamada del aire: la flota de Vipore",
			complete = "El vuelo no tardará en estar preparado. ¡Sigue trabajando duro!",
		},
		[6942] = {
			title = "La llamada del aire: la flota de Slidore",
			complete = "¡Sigue así y trae más, soldado! ¡Los grifos Nidal estarán listos para atacar muy pronto!",
		},
		[6943] = {
			title = "La llamada del aire: la flota de Ichman",
			complete = "¿Lo ves? ¡Fíjate en ellos, soldado! Se acercan... ¡Pronto el Vuelo de Ichman volverá a atacar el corazón del valle! ¡Los Pico Tormenta serán los amos del cielo!",
		},
		[6961] = {
			title = "¡El Gran Padre Invierno está aquí!",
			accept = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!$B$BY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!",
			complete = "Jo jo jo,... hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".$B$BSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?",
		},
		[6962] = {
			title = "Golosinas para el Gran Padre Invierno",
			accept = "¿Puedes hacerle un favor al Gran Padre Invierno, eh, mi $gniño:niña;?$B$BNo es que me guste hablar de mí mismo en tercera persona, pero el Gran Padre Invierno ha trabajado todo el día y se merece un regalito. Unas galletas de jengibre y un vaso de leche fresca me vendrían muy bien. Sé $gun buen amigo:una buena amiga; del Gran Padre y tráele algo para comer, anda.",
			complete = "Muchas gracias, $n. Te deseo un feliz Festival de Invierno.$B$BTen, una cosita para agradecerte el favor.",
		},
		[6963] = {
			title = "El robo de las golosinas del Festival de Invierno",
			accept = "Escucha... no quiero arruinar la magia de la época, pero en Pastos de Bosquehumeante necesitan ayuda... el tipo de ayuda que brindan los aventureros.$B$BNos falta un cargamento de dulces importante que cubriría nuestro inventario para la temporada, ¡y ahora también nos falta un agente de Pastos de Bosquehumeante que enviamos en busca del cargamento! Por favor... la última vez que vieron el cargamento fue en las Montañas de Alterac, y allí enviamos a nuestro agente.$B$B¡Ve a averiguar si ambos están sanos y salvos!",
			complete = "¡Eh! ¿Hay alg-g-guien ahí?$B$BN-no s-s-soy un m-m-muñeco de n-nieve. M-me llamo S-sacks y rep-p-presento a P-pastos de Bosquehum-mmeante en For-j-jaz... ¡M-me han atacado unas c-c-criaturas ext-t-trañas mientras buscaba una c-c-carga p-perdida!$B$BT-t-tengo frrrrrrío...",
		},
		[6964] = {
			title = "El espíritu de esta fiesta",
			accept = "Regalos, golosinas, felicitaciones... ¡Bah!$B$BEsos goblins ensucian el verdadero sentido del festín del Festival de Invierno. Es una época de renovación, en la que la tierra descansa bajo el manto de nieve tendido por el Gran Padre Invierno, ¡que NO es ese idiota del trajecito rojo!$B$BSi quieres saber el verdadero significado de la fiesta, ve a hablar con Sagorne Zanca Cresta. Seguro que le sorprende que alguien se interese por la historia en vez de por los regalos.",
			complete = "¿El Festival de Invierno? Por desgracia, con el tiempo ha ido perdiendo significado para los tauren.$B$BDebo decir que comparto el disgusto de Furmund; para él y su grupo, el pasado es como un pendón de guerra. A mí me parece bien que haya festejos, pero sin olvidar el verdadero espíritu del Festival.",
		},
		[6981] = {
			title = "El fragmento resplandeciente",
			accept = "El fragmento es verde y brillante y, aunque sólido, parece que hubiera humo arremolinándose bajo su superficie. No se puede evitar perder la mirada en las profundidades del cristal y, al mismo tiempo, uno sabe que hay algo muy desconcertante.$B$BQuizás deberías ir a ver si alguien de Trinquete puede decirte algo más sobre este extraño fragmento.",
			complete = "Oh... Nunca había visto algo así...",
		},
		[6982] = {
			title = "Suministros de Dentefrío",
			accept = "Mina Dentefrío es un almacén de la Horda. No puedo tragar la comida que les dan a sus soldados ¡y el estado de sus armas y armaduras es lamentable! Pero... en tiempos como estos cuando los suministros son tan importantes, podemos arreglarnos con lo que tienen.$B$BEntra en Mina Dentefrío y tráeme sus suministros. Eso mantendrá a la Alianza en condiciones para el combate y privará a los guerreros de la Horda de un equipamiento de lo más necesario.$B$BSuerte, $n. La mina está lejos al sur, en lo más profundo del territorio de la Horda.",
			complete = "Ah, los tienes. ¡Buen trabajo, $n! Estos suministros están algo húmedos de estar guardados en esa oscura mina tanto tiempo pero les sacaremos partido igualmente.$B$BGracias, $n. Tus acciones son vitales para el mantenimiento de nuestras tropas.",
		},
		[6983] = {
			title = "¡Qué ruin!",
			accept = "Una criatura llamada \"Grinch el Abominable\" es el que ha robado nuestro envío de regalitos, $n. ¡Y ten cuidado! ¡Es malvado y tiene a un puñado de gnomos verdes a su servicio!$B$BVas a necesitar ayuda para enfrentarte a él. ¡Se rumorea que tiene nuestros regalitos y a nuestro querido Metzen el Reno en la Caverna Estrecha, en las Laderas de Trabalomas! Encuentra los regalitos, $n, ¡tráelos de vuelta antes de que se arruine la fiesta y los niños de Orgrimmar se decepcionen!",
			complete = "¡Lo encontraste! ¡Has salvado el Festival de Invierno de los Pastos de Bosquehumeante!$B$BPobre Sacks... nos aseguraremos de enviar un destacamento a por él y encontrar la forma de descongelarlo. Con suerte, volverá a tiempo para el día del Festival aunque tendrá que compensar el tiempo que no haya podido trabajar. Sin embargo, ¡esto no sería posible si no fuera por ti!",
		},
		[6984] = {
			title = "Un agradecimiento de Pastos de Bosquehumeante",
			accept = "Pastos de Bosquehumeante te agradece que hayas recuperado los dulces robados, $n. Queremos ofrecerte un obsequio muy especial, ¡de manos del propio Gran Padre Invierno!$B$BHabla con él; te dará nuestro obsequio. De la granja a la mesa: ¡deliciosos manjares de Pastos de Bosquehumeante... y todo gracias a ti!",
			complete = "Jo jo... ¡Saludos, $gaventurero:aventurera;!$B$BLos goblins me han dicho que te has ganado un regalito especial. Aquí tienes. ¡Feliz Festival de Invierno!",
		},
		[6985] = {
			title = "Suministros de Ferrohondo",
			accept = "Los enanos Pico Tormenta están usando Mina Ferrohondo como almacén. Quiero que realices una incursión en esa mina y me traigas sus suministros. Esto recortará los recursos de los Pico Tormenta en el Valle de Alterac ¡y nos aportará un equipo de lo más necesario!$B$BPero ándate con ojo, $N. Mina Ferrohondo está en lo más recóndito del territorio de la Alianza y el control de la mina cambia como las nieves de Alterac.",
			complete = "¡Los tienes! ¡Bien hecho, $n! ¡Y espero que hayas visto a algunos enanos durante tu incursión y derrames su sangre por los Lobo Gélido!",
		},
		[7001] = {
			title = "Establos vacíos",
			accept = "La guerra en el valle se ha cobrado un precio sobre nuestros soldados. ¡Debemos dar vitalidad a nuestras tropas!$B$BSi conseguimos llenar el Establo, los Caballeros Lobo volverán a galopar por el campo de batalla.$B$BToma este bozal y encuentra a los Lobo Gélido que pueblan el bosque vecino. Cuando encuentres un lobo, usa el bozal para domarlo. Tráeme a la bestia domada para que pueda acomodarla en el Establo.$B$BCuando tengamos suficientes lobos, los Caballero Lobo se reunirán con las patrullas de la primera línea del frente.",
			complete = "Solo espero que todos los que deben reunir pieles de carnero sean tan aplicados como tú, $n.$B$BA este paso, tendremos el Establo lleno ¡en cuestión de horas!",
		},
		[7002] = {
			title = "Arneses de pellejo de carnero",
			complete = "Muy bien, soldado. Te lo haré saber en cuanto tenga suficientes pieles acumuladas.$B$B¡Sigue así!",
		},
		[7003] = {
			title = "Gigantes reducidos",
			accept = "¡Voy a tener que solucionar esto de los gigantes si quiero quedarme aquí! Porque no son buenos para el negocio, ¿no te parece?$B$BHe estado trabajando en una variante del rayo reductor gnomo, pero estoy utilizando los últimos avances tecnológicos goblin para construirla. Quisiera probarla pero me gustaría evitar esos pequeños inconvenientes que tiene la fase de experimentación, como la muerte, así que me gustaría que la probaras con los gigantes de Feralas. Después de encogerlos deberías encontrar un residuo de miniaturización, ¡tráeme un poco!",
			complete = "¡Espléndidamente espléndido! Me alegra ver que has vuelto con el residuo, ¡y con todos tus apéndices intactos, cabeza y todo! Eso está muy bien... no es que el Ultra-reductor fuera peligroso, pero, oye...$B$BAh, y aprecio mucho tu ayuda, $n. De verdad, eres $gun buen amigo:una buena amiga; de los goblins de todo el mundo. Acepta esto como muestra de mi agradecimiento.",
		},
		[7021] = {
			title = "¡El Gran Padre Invierno está aquí!",
			accept = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno, que ahora mismo está en Orgrimmar! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!$B$BY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!",
			complete = "Jo jo jo,... hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".$B$BSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?",
		},
		[7022] = {
			title = "¡El Gran Padre Invierno está aquí!",
			accept = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!$B$BY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!",
			complete = "Jo jo jo,... hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".$B$BSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?",
		},
		[7023] = {
			title = "¡El Gran Padre Invierno está aquí!",
			accept = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno, que ahora mismo está en Forjaz! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!$B$BY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!",
			complete = "Jo jo jo,... hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".$B$BSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?",
		},
		[7024] = {
			title = "¡El Gran Padre Invierno está aquí!",
			accept = "¡Feliz Festival de Invierno! ¡No dejes de saludar al Gran Padre Invierno, que ahora mismo está en Orgrimmar! Si te has portado bien, recibirás regalos magníficos el día del festín del Festival de Invierno. ¡No te olvides de decirle lo que quieres!$B$BY asegúrate de tener regalitos para los que se han portado bien. Disponemos de una estupenda selección. De la granja a la mesa, ¡todo lo bueno de los Pastos de Bosquehumeante!",
			complete = "Jo jo jo,... hola. Soy el Gran Padre Invierno y quiero desearte un maravilloso Festival de Invierno por cortesía de Pastos de Bosquehumeante... \"De la granja a la mesa, todo lo bueno de los Pastos de Bosquehumeante\".$B$BSi te has portado bien este año, quizás recibas regalos de los Pastos de Bosquehumeante durante el festín del Festival de Invierno. ¿A que es genial?",
		},
		[7025] = {
			title = "Golosinas para el Gran Padre Invierno",
			accept = "¿Puedes hacerle un favor al Gran Padre Invierno, eh, mi $gniño:niña;?$B$BNo es que me guste hablar de mí mismo en tercera persona, pero el Gran Padre Invierno ha trabajado todo el día y se merece un regalito. Unas galletitas de jengibre y un vaso de leche fresquita me irían de perlas. Sé $gun buen amigo:una buena amiga; del Gran Padre y tráele algo para picar, anda.",
			complete = "Muchas gracias, $n. Te deseo un feliz Festival de Invierno.$B$BTen, una cosita para agradecerte el favor.",
		},
		[7026] = {
			title = "Arneses de pellejo de carnero",
			complete = "Bien hecho, soldado. Te avisaré cuando haya almacenado suficientes pieles.",
		},
		[7027] = {
			title = "Establos vacíos",
			accept = "¡Solo tienes que mirar en el Establo, $n! ¡Vacío! La brigada de los Pico Tormenta no tiene carneros que montar, la caballería ha desaparecido.$B$BTienes que ayudarnos, soldado. Llévate esta collera de entrenamiento y adéntrate en la espesura de este valle. Encuentra a los carneros de Alterac que deambulan por esa zona y usa el collar para atrapar a alguno. Cuando hayas capturado un carnero, regresa aquí y lo acomodaré en nuestro Establo.$B$BCuando tengamos suficientes carneros, se notificará al Comandante de los jinetes de carneros. Con tu ayuda, ¡la caballería renacerá!",
			complete = "El Establo estará lleno muy pronto. ¡Sigue con tu buen trabajo!",
		},
		[7028] = {
			title = "Los males de Maraudon",
			accept = "Las cavernas de cristal de Terramok están al oeste, en pleno corazón de Maraudon... Es un lugar antiguo y cargado de historia. Quiero una parte de esa historia, $c. Tras las puertas gigantes hay reliquias de los dioses antiguos.$B$BSi te atreves a enfrentarte a los males de Maraudon, te compensaré generosamente. Tráeme todas las tallas de cristal terádrico que encuentres.$B$BAsí podré... estudiarlas. Los poderes que contienen llevan demasiado tiempo dormidos.",
			complete = "¡Ja, ja! Sabía que volverías.$B$B<Willow habla entre dientes.>$B$BQué fácil de convencer.$B$BLo que sea por una recompensa. Je, je, je...",
		},
		[7029] = {
			title = "La corrupción de Lenguavil",
			accept = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.$B$BToma este vial, $n. Llénalo en el estanque de cristal naranja de las cavernas; el relleno del vial contrarrestará las toxinas y las transformará en agentes sanadores.$B$BEsparce el líquido purificado en la hiedra Tallovil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...",
			complete = "Gracias, $n; seguiré investigando con los restos de líquido.$B$BAunque queda mucho por hacer, has contribuido a limpiar parte de la corrupción de Lenguavil en Maraudon. Toma esto como muestra de mi gratitud.",
		},
		[7041] = {
			title = "La corrupción de Lenguavil",
			accept = "Un sátiro llamado Lenguavil ha corrompido las cavernas de Maraudon y ha detenido el desarrollo de muchas de las plantas.$B$BToma este vial, $n. Llénalo en el estanque de cristal naranja de las cavernas; el relleno del vial contrarrestará las toxinas y las transformará en agentes sanadores.$B$BEsparce el líquido purificado en la hiedravil de las cavernas naranja. Aunque se eliminará la corrupción de la planta, debes saber que seguirá bajo el control de Lenguavil. Puede que intente atacarte...",
			complete = "Gracias, $n; seguiré investigando con los restos de líquido.$B$BAunque queda mucho por hacer, has contribuido a limpiar parte de la corrupción de Lenguavil en Maraudon. Toma esto como muestra de mi gratitud.",
		},
		[7042] = {
			title = "El robo de las golosinas del Festival de Invierno",
			accept = "Oye, no es por fastidiarte la fiesta, pero Pastos de Bosquehumeante necesita la ayuda de alguien con temperamento aventurero.$B$BHemos perdido una importante carga de regalitos para la temporada, ¡y ahora hemos perdido al agente de Pastos de Bosquehumeante que había ido a investigar qué pasa! La última vez que se vio la carga fue en las Montañas de Alterac y allí es donde fue nuestro hombre.$B$B¡Ve a ver si los encuentras sanos y salvos!",
			complete = "¡Eh! ¿Hay alg-g-guien ahí?$B$BN-no s-s-soy un m-m-muñeco de n-nieve. M-me llamo S-sacks y rep-p-presento a P-pastos de Bosquehum-mmeante en For-j-jaz... ¡M-me han atacado unas c-c-criaturas ext-t-trañas mientras buscaba una c-c-carga p-perdida!$B$BT-t-tengo frrrrrrío...",
		},
		[7043] = {
			title = "¡Qué ruin!",
			accept = "Una c-c-criatura llamada \"Grinch el Abominable\" es el q-q-que ha robado nuestro envío de d-d-dulces, $n. ¡Y ten c-c-cuidado! ¡Es m-m-malvado y tiene a un p-p-puñado de gnomos verdes a su s-s-servicio!$B$BVas a n-n-necesitar ayuda p-p-para enfrentarte a él. ¡Se rumorea que t-t-tiene nuestros d-d-dulces y a nuestro q-q-querido Metzen el Reno en la Caverna Estrecha, en las Laderas de Trabalomas! Encuentra los d-d-dulces, $n, ¡tráelos de vuelta antes de q-q-que se arruine la fiesta y los n-n-niños de Ventormenta queden decepcionados!",
			complete = "¡Lo encontraste! ¡Has salvado el Festival de Invierno de los Pastos de Bosquehumeante!$B$BPobre Sacks... nos aseguraremos de enviar un destacamento a por él y encontrar la forma de descongelarlo. Con suerte, volverá a tiempo para el día del Festival aunque tendrá que compensar el tiempo que no haya podido trabajar. Sin embargo, ¡esto no sería posible si no fuera por ti!",
		},
		[7044] = {
			title = "Leyendas de Maraudon",
			accept = "Un siniestro sátiro llamado Lord Lenguavil extiende su maldad por estas cuevas, envenenando las mentes. Sigue viviendo detrás de los cristales morados.$B$BTambién creó un símbolo viviente de su corrupción llamado Noxxion, que vive tras los cristales naranja. Han robado las dos piezas del cetro de mi hermano. Celebras, mi hermano, ha caído víctima de la corrupción y deambula ahí dentro.$B$B¡Tienes que ayudarlo! Busca las piezas y encuentra el modo de hablar con mi hermano.",
			complete = "Ahora que me has traído las piezas del cetro, podremos limpiar Maraudon de la corrupcíón de Lenguavil.",
		},
		[7045] = {
			title = "Un agradecimiento de Pastos de Bosquehumeante",
			accept = "Pastos de Bosquehumeante te agradece que hayas recuperado los dulces robados, $n. Queremos ofrecerte un obsequio muy especial, ¡de manos del propio Gran Padre Invierno!$B$BHabla con él; te dará nuestro obsequio. De la granja a la mesa: ¡deliciosos manjares de Pastos de Bosquehumeante... y todo gracias a ti!",
			complete = "Jo jo... ¡Saludos, $gaventurero:aventurera;!$B$BLos goblins me han dicho que te has ganado un regalito especial. Aquí tienes. ¡Feliz Festival de Invierno!",
		},
		[7046] = {
			title = "El cetro de Celebras",
			accept = "Antes, mi cetro era una fuente de esperanza para mí. Su poder me permitía desplazarme rápidamente por estas cavernas. Quería dar paz al espíritu de mi tío... Te paso a ti esa tarea.$B$BNecesito que me ayudes en el ritual para unir las dos piezas. Sígueme y escucha mis instrucciones mientras canalizo la energía necesaria para unir la vara y el diamante.$B$B¡Reconstruyamos juntos el cetro de Celebras!",
			complete = "Ten; debes usar el poder que te ha sido concedido siempre para hacer el bien. Sigue explorando las cavernas, a ver si encuentras los restos de mi tío. Te esperan grandes peligros, $n.$B$BVuelve a hablar conmigo si lo necesitas.",
		},
		[7061] = {
			title = "El festín del Festival de Invierno",
			accept = "Toma. Si quieres saber más sobre el festín del Festival de Invierno, lee este libro. Opino que nuestro punto de vista sobre esta leyenda es el apropiado, pero como estudioso de las leyendas, comprendo que es mejor que toda la información esté recopilada en una única fuente.$B$BCuando termines, llévale el libro a Cairne Pezuña de Sangre en Cima del Trueno. Sé que le gustará saber que hay otros interesados en las antiguas leyendas de nuestro pueblo.",
			complete = "Las leyendas y la tradición del Festival de Invierno se han ido borrando de la memoria de nuestra gente con el paso de los años. Sí, sé que los goblins ayudan a revivir el Festival en su propio beneficio, pero eso al menos ayuda a que no caiga en el olvido.$B$BAdmiro tu interés en nuestra historia es un hecho admirable, joven $c. Me impresiona tu sabiduría.",
		},
		[7062] = {
			title = "El espíritu de esta fiesta",
			accept = "Regalos, golosinas, felicitaciones... ¡Bah!$B$BEsos goblins ensucian el verdadero sentido del festín del Festival de Invierno. Es una época de renovación, en la que la tierra descansa bajo el manto de nieve tendido por el Gran Padre Invierno, ¡que NO es ese idiota del trajecito rojo!$B$BSi quieres saber el verdadero significado de la fiesta, ve a hablar con Karnik el Historiador en la Liga de Expedicionarios. Seguro que le sorprende que alguien se interese por la historia en vez de por los regalos.",
			complete = "¿El Festival de Invierno? Por desgracia, con el tiempo ha ido perdiendo significado para los enanos.$B$BDebo decir que comparto el disgusto de Furmund; para él y su grupo, el pasado es como un pendón de guerra. A mí me parece bien que haya festejos, pero sin olvidar el verdadero espíritu del Festival.",
		},
		[7063] = {
			title = "El festín del Festival de Invierno",
			accept = "Ten; si quieres saber más sobre el festín del Festival de Invierno, lee este libro. Opino que nuestro punto de vista sobre esta leyenda es el apropiado, pero comprendo que es mejor que toda la información esté recopilada en una única fuente.$B$BCuando termines, llévale el libro a Muradin Barbabronce. Sé bien que le gustará saber que hay otros interesados en las antiguas leyendas.",
			complete = "Las leyendas y la tradición del Festival de Invierno se han ido borrando de la memoria de nuestra gente con el paso de los años. Sí, sé que los goblins ayudan a revivir el Festival en su propio beneficio, pero eso al menos ayuda a que no caiga en el olvido.$B$BEl hecho de que vayas más allá de lo material y te intereses por nuestra historia es algo admirable, joven $c. Me impresiona tu sabiduría.",
		},
		[7064] = {
			title = "Corrupción de la tierra y de la semilla",
			accept = "En las profundidades de Maraudon vive una criatura de gran maldad. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros en Kalimdor. Esas criaturas mataron a Zaetar y se quedaron sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.",
			complete = "¡Estupendo, $n! ¡Gracias!$B$BLe preguntaré a Marandis por los restos de Zaetar, pero al menos has hecho lo más difícil.$B$BElige uno de estos objetos como prueba de nuestra gratitud.",
		},
		[7065] = {
			title = "Corrupción de la tierra y de la semilla",
			accept = "En las profundidades de Maraudon vive una criatura de gran maldad, $n. La princesa Theradras es una fuerza elemental de la tierra relacionada con los dioses antiguos. Hace eones se unió a Zaetar, el primogénito de Cenarius. El fruto de su relación fueron las criaturas llamadas centauros. Esas criaturas mataron a Zaetar y Theradras guardó sus restos. Mi objetivo es encontrar a quien tenga fuerza suficiente para matar a Theradras y recuperar los restos de Zaetar antes de volver a Cima del Espolón.",
			complete = "¡Estas son maravillosas noticias, $n! ¡Gracias!$B$BAunque me preocupa que no pudieras recuperar los restos de Zaetar, ¿quién soy yo para cuestionar la voluntad del primogénito de Cenarius? Quizás ahora la voluntad de los centauros se doblegue y su sed de sangre se aplaque. No podemos hacer más que esperar.$B$BMe habían otorgado estos objetos para recompensar a quien nos ayudara si nuestra misión era exitosa. Puedes elegir uno como muestra de agradecimiento.",
		},
		[7066] = {
			title = "La semilla de vida",
			accept = "Mis hijos e hijas, los desdichados centauros, necesitan a su padre.$B$BMira: este lugar está lleno de esperanza y todas las cosas que venera mi padre, Cenarius. ¡Todo eso salió de mí! Y ahora no voy a quitárselo, ni siquiera por el crimen que cometieron contra mí.$B$BPero voy a pedirte un favor para tranquilizar a mi hermano. Toma; es la primera semilla que nació de la vida alimentada por mis restos. Dile que mi espíritu está aquí y que seguiré viviendo. Lo entenderá.",
			complete = "¿El espíritu de mi hermano ha encontrado al fin la paz? Me alegro de saberlo. Lo creí perdido para siempre, pero esto... Este símbolo de su sacrificio me demuestra que no está perdido sino que ha renacido. Ha hecho lo que debía hacer.$B$BGracias, $n. Me has devuelto la esperanza; presiento que esta semilla será muy importante para las gentes de esta tierra.",
		},
		[7067] = {
			title = "Las instrucciones del Paria",
			accept = "Aunque me exiliaron por hereje, sé que digo la verdad y eso me anima a seguir adelante. Pero para completar mi destino, necesito la ayuda de alguien que no sea centauro.$B$BHay que entrar en las salas sagradas de Maraudon; mi gente protege la tumba y solo los más devotos pueden entrar.$B$BSi aceptas ayudarme, afirma con la cabeza. Te daré un papiro con instrucciones. Léelo y considera mi propuesta.",
			complete = "¡Al fin puedo iniciar la unificación de las tribus, $r! Gracias.$B$BAcepta esto en prueba de mi gratitud. Espero que cuando volvamos a vernos sea en tiempo de paz.",
		},
		[7068] = {
			title = "Trozos Oscuros",
			accept = "En Maraudon, el lugar sagrado de los centauros, se concentra una magia muy fuerte. Los centauros de Desolace protegen el lugar con su vida, pero no podrán impedir que cojamos lo que necesitemos.$B$BVe a Maraudon y encuentra a las criaturas de piedra hechas de fragmentos oscuros. Trae los cristales morados y Uthel'nay te compensará.$B$BEs un sitio peligroso, mejor llévate compañía.",
			complete = "Perfecto... Bueno, toma uno de estos abalorios y lárgate, tengo mucho que hacer.",
		},
		[7070] = {
			title = "Trozos Oscuros",
			accept = "He empezado a hacer pruebas con las propiedades Arcanas de varios cristales. Lady Valiente me ha autorizado a pedir a los viajeros que se dirigen a Desolace que busquen un lugar llamado Maraudon. En el templo en ruinas hay grandes elementales compuestos por unas piedras moradas que llamo fragmentos oscuros.$B$BTe agradecería que te acercaras e intentaras encontrarme algún cristal. Incluso podría fabricarte un adorno con ellos, si quieres.",
			complete = "Estos son perfectos, $n. De hecho, otros aventureros también regresaron de allí y de ellos pude diseñar estos... por favor, siéntetee libre de tomar uno por su arduo trabajo. Y gracias nuevamente por traer más muestras para estudiar.",
		},
		[7081] = {
			title = "Los cementerios del Valle de Alterac",
			accept = "Los cementerios del Valle de Alterac están muy codiciados. Tanto la Horda como la Alianza luchan encarnizadamente por este suelo sagrado. ¿$n, estás $gdispuesto:dispuesta; a unirte a la lucha?$B$BQuiero que asaltes un cementerio enemigo. Encuentra un cementerio con un estandarte de la Horda ¡y arráncalo del suelo! Hazlo y habrás completado tu tarea...$B$BPero si además puedes resistir en el cementerio durante unos minutos, nuestros soldados vendrán pronto a apoyarte.",
			complete = "¡Muy bien! Los cementerios son clave para el control del Valle de Alterac. Cuando capturas uno, contribuyes a asegurar la soberanía de la Alianza en ese lugar.$B$BVete ahora, $n. Vuelve a la batalla y si ves un cementerio bajo control de la Horda... ¡ya sabes qué hacer!",
		},
		[7082] = {
			title = "Los cementerios de Alterac",
			accept = "Las líneas del frente en el Valle de Alterac cambian constantemente. Los límites del territorio avanzan y retroceden conforme nos enfrentamos a nuestros adversarios en combate mortal. Y es en los cementerios, $n, donde se libran las batallas más encarnizadas.$B$B¡Quiero que asaltes un cementerio en manos de la Alianza! Encuentra un cementerio con un estandarte de la Alianza y arráncalo del suelo.$B$BHazlo y habrás completado tu tarea... pero si además puedes resistir en el cementerio durante unos minutos, será nuestro y nuestros soldados vendrán pronto a relevarte.",
			complete = "¡Muy bien, $n! Con cada cementerio que controlemos, el espíritu de nuestros enemigos vagará perdido y sin rumbo.",
		},
		[7101] = {
			title = "Las torres y los búnkeres",
			accept = "Las torres y los búnkeres son posiciones importantes ¡y debemos capturarlas y hacernos con el control de todas! Por eso quiero que captures un búnker controlado por el enemigo.$B$BPara ello, fíjate donde haya un estandarte de la Alianza. En el interior verás otro estandarte. Saca ese estandarte y en su lugar aparecerá uno de la Horda. ¡Muy bien!$B$BEn ese momento habrás completado tu misión, pero si además puedes resistir en la posición lo suficiente sin que la Alianza lo recupere ¡será destruida!",
			complete = "¡He oído hablar de tu éxito en la misión! Me complace tal noticia...$B$BNuestros soldados podrán ahora cargar con impunidad ¡y demostrar a la Alianza que el Valle de Alterac no es lugar para ellos!",
		},
		[7102] = {
			title = "Las torres y los búnkeres",
			accept = "Las torres y los búnkeres son posiciones defensivas clave ¡y debemos controlar tantas como sea posible! Quiero que ataques una torre o un búnker en el Valle de Alterac.$B$BPara ello, entra en una torre donde veas un estandarte de la Horda en la parte superior. En el interior verás otro estandarte enemigo. Saca ese estandarte y en su lugar aparecerá uno de la Alianza. ¡Muy bien!$B$BEn ese momento habrás completado tu misión, si además puedes resistir en la posición lo suficiente sin que la Horda lo recupere ¡será destruida!",
			complete = "He recibido un informe de campo según el cual has contribuido a recuperar un estandarte enemigo. ¡Muy bien, $n! Con sus líneas descolocadas ¡podemos adelantar más el frente!",
		},
		[7121] = {
			title = "El intendente",
			accept = "$n, nuestro intendente me ha encargado que le mande a los nuevos reclutas. Necesita suministros de los alijos ocultos en las minas de Alterac y probablemente te envíe para recuperarlos.$B$BSigue la carretera. Encontrarás a nuestro intendente al oeste.",
			complete = "Es bueno ver a nuevos soldados aquí, $n, pero con un poco de suerte entrarás pronto en combate ¡y no serás $gun novato:una novata; por mucho tiempo!$B$BVuelve a hablar conmigo. Tengo tareas que tratar contigo...",
		},
		[7122] = {
			title = "Capturar una mina",
			accept = "Las minas del Valle de Alterac contienen algo más que minerales. Tanto los Lobo Gélido como los Pico Tormenta tienen alijos con suministros extras en las minas de Ferro Hondo y Mina Dentefrío... una buena idea, ¡ojalá logremos hacernos con su control!$B$BToma posesión de una mina y tráemelos. Para capturar una mina, penetra en una que no controlemos y mata a su líder. Cuando lo hagas la mina será nuestra ¡y mandaremos soldados para proteger la posición!",
			complete = "¡Lo has conseguido! ¡Muy bien, $n!$B$BCuando nos hacemos con el control de una mina y tenemos a soldados estacionados allí, es mucho más fácil recolectar el mineral y los suministros.",
		},
		[7123] = {
			title = "Habla con nuestro intendente",
			accept = "$n, el intendente de los Lobo Gélido está buscando reclutas para tareas que llevan a las minas del Valle de Alterac. Habla con él, te contará más detalles.$B$BSigue la carretera hacia el oeste hasta el búnker, toma entonces la salida del oeste y encontrarás a nuestro intendente.",
			complete = "¡Hola, $n! Me alegra ver que $gun:una; $c como tú está impaciente por aportar su granito de arena a la Horda. Vuelve a hablar conmigo, tengo tareas vitales para ti...",
		},
		[7124] = {
			title = "Capturar una mina",
			accept = "Mientras se libra una encarnizada batalla en el Valle de Alterac, también hay enfrentamientos en Mina Dentefrío y en Mina Ferrohondo. Ambas contienen minerales en abundancia y se utilizan además para almacenar suministros; ¡es normal que se codicien tanto!$B$B¡Únete a nuestro movimiento bélico, $n! ¡Captura una de las minas para la Horda! Para capturar una mina, penetra en una que no controlemos y mata a su líder. Cuando lo hagas la mina será nuestra ¡y mandaremos soldados para proteger la posición!",
			complete = "¡Has capturado una mina! Con nuestros propios guerreros protegiéndola, será mucho más sencillo extraer minerales de sus profundidades y recolectar los suministros que allí hubieran escondido.$B$BMuy bien, $n. Esta acción ha sido una gran contribución a nuestros esfuerzos en la batalla.",
		},
		[7141] = {
			title = "La batalla de Alterac",
			accept = "La Liga de Expedicionarios cree que hay artefactos en el Valle de Alterac pero los orcos Lobo Gélido no nos dejan explorarlo. ¡No podemos permitir que la Horda se interponga en nuestros objetivos de erudición! Derrota al general Lobo Gélido, Drek'Thar. Con él muerto, los orcos perderán su ventaja.$B$BDrek'Thar se encuentra en el Bastión Lobo Gélido, al sur del Valle de Alterac. Véncelo y tráemelo.",
			complete = "¡Muy bien, $n! Con la nariz de la Horda ensangrentada tras la muerte de su general, ¡tendremos margen para explorar!",
		},
		[7142] = {
			title = "La batalla por Alterac",
			accept = "Los enanos Pico Tormenta y sus aliados han invadido el Valle de Alterac ¡y tenemos que expulsarlos! Para ganar la batalla de Alterac, tenemos que derrotar a su general, Vanndar Pico Tormenta!$B$BEncontrarás a Vanndar en Dun Baldar, al norte del Valle de Alterac.$B$BDestrúyelo, $n, y vuelve aquí.",
			complete = "¡Muy bien, $n! Los Pico Tormenta no tienen ninguna posibilidad en esta insensata invasión.$B$B¡Ja! Hasta ahora, ¡solo han conseguido que maten a su general!",
		},
		[7161] = {
			title = "Terreno de pruebas",
			accept = "Salve, $c. Mucho tiempo ha pasado desde que hemos tenido la oportunidad de responder a la llamada de la batalla. Los antiguos sentimientos tardan en emerger pero una vez despiertos, la sangre fluye cual torrente. La furia de la batalla vuelve...$B$BLos recién llegados al valle deben completar primero el rito de la batalla.$B$BEn lo más profundo de la cueva gnoll de Zarpa Salvaje se encuentra un estandarte de Lobo Gélido. Adéntrate hasta ese lugar y recupera el estandarte. Devuélvemelo y te concederé una insignia de Iniciado de los Lobo Gélido.",
			complete = "Ese ardor que sientes es tu alma que se despierta. Tu espíritu ha aceptado la llamada a las armas.$B$BAhora formas parte de los Lobo Gélido, $n. Enhorabuena.$B$BLleva siempre contigo esta insignia. A medida que subes de rango entre los Lobo Gélido, sustituiré tu insignia por otras, otras más poderosas.$B$BQuizás algún día se exalten tus hazañas entre el clan Lobo Gélido. Si tal día llega, se te concederá el Ojo del Orden.",
		},
		[7162] = {
			title = "Terreno de Pruebas",
			accept = "Has llegado justo a tiempo, $c. ¡Estos salvajes Lobo Gélido no se rinden! Tenemos que demostrarles el poder de los Pico Tormenta. Deben inclinarse ante nuestra superioridad.$B$BAntes de que te dirijas al campo de batalla, deberías unirte a las filas de los Pico Tormenta.$B$BAl suroeste de Dun Baldar encontrarás la Cueva Ala Gélida. En lo más profundo de las cavernas hay clavado un estandarte Pico Tormenta. Adéntrate hasta ese lugar y recupera ese estandarte. Devuélvemelo y te ganarás una insignia de Iniciado de los Pico Tormenta.",
			complete = "Toma esta insignia y llévala con orgullo, $n. A medida que subes de rango entre los Pico Tormenta, recibirás la insignia correspondiente. Vuelve aquí conforme adquieres más honores con los Pico Tormenta y sustituiré tu insignia por otras, otras más poderosas.$B$BQuizás algún día llegues a crecer tanto como para convertirte en una leyenda en el campo de batalla. Si tal día llega, se te concederá el Ojo del Orden.",
		},
		[7163] = {
			title = "Ascender y darse a conocer",
			complete = "Esta nueva insignia refleja tu rango entre los Lobo Gélido. Llévala siempre contigo.$B$BY $c... Muere con honor.",
		},
		[7164] = {
			title = "Honorable con el clan",
			complete = "<El maestro de guerra Laggrond hace el saludo.>$B$B¡Vete, $n! Sigue con tu defensa de los Lobo Gélido. ¡Hay que ganar esta guerra! ¡Por Drek'Thar! ¡Por el Jefe de Guerra!",
		},
		[7165] = {
			title = "Ganarse una reverencia",
			complete = "<El maestro de guerra Laggrond emite un rugido.>$B$BYa empieza a correrse la voz sobre tus hazañas, soldado. Los Pico Tormenta se estremecen de miedo con solo oír tu nombre. ¡Sigue así!",
		},
		[7166] = {
			title = "Héroes legendarios",
			complete = "Pronto, todos los que estén en el campo de batalla estarán bajo tu ojo vigilante. ¡Tendrás al valle y a sus soldados a tus órdenes!",
		},
		[7167] = {
			title = "El ojo del orden",
			complete = "Canaliza el poder de la insignia. Deja que los enemigos oigan tus palabras. El poder de la Horda es incuestionable!",
		},
		[7168] = {
			title = "Ascender y darse a conocer",
			complete = "¡Que nuestros enemigos sepan que $gun:una; soldado de rango los ha atacado! ¡Lucha por la gloria de los Pico Tormenta!",
		},
		[7169] = {
			title = "Honorable con la guardia",
			complete = "El Rey está al corriente de tus heroicos actos en el frente, $c. ¡Sigue con tu inquebrantable defensa de la Guardia de Pico Tormenta!",
		},
		[7170] = {
			title = "Ganarse una reverencia",
			complete = "Cuando nos conocimos, nunca hubiera imaginado que se estaba gestando $gun héroe:una heroína;. ¡Continúa, soldado!",
		},
		[7171] = {
			title = "Héroes legendarios",
			complete = "¡Seguramente serás tú quien lleve el Ojo del Orden!",
		},
		[7172] = {
			title = "El ojo del orden",
			complete = "¡Eres tu quien debe llevar a nuestras tropas a la victoria, comandante! Los soldados están bajo tu mando. Seguirán tus órdenes directas. Guíalos... Aplasta al Lobo Gélido.",
		},
		[7181] = {
			title = "La leyenda de Korrak",
			accept = "Los invasores Pico Tormenta no son la única amenaza de la región, soldado. La guerra en el valle se está librando en dos frentes. Los trols caníbales Hacha Invernal también rivalizan por el poder.$B$BSu líder es Korrak el Sanguinario, una cruel y taimada fiera.$B$BUn buen golpe sobre Korrak podría ser aplastante para el clan Hacha Invernal. Ejecuta a la fiera ¡y recibirás tu recompensa!",
		},
		[7201] = {
			title = "El último elemento",
			accept = "Hay trabajo a mansalva para quien se aventure en las profundidades, $n.$B$BLos Hierro Negro han perfeccionado la creación de gólems extremadamente poderosos.$B$BLos primeros informes de nuestros espías indican que los enanos usan una fuente de poder única para conferir a sus creaciones una potencia destructora sin igual.$B$B¡Tan solo imagínate lo que podríamos hacer con nuestras abominaciones si nos hiciéramos con esta esencia de los elementos! No dejes piedra por remover en esa ciudad si es necesario, ¡pero no vuelvas hasta haber encontrado la esencia! Recibirás un justo pago por el riesgo.",
			complete = "¡Estupendo! ¡Haré que las envíen inmediatamente por mensajero a Entrañas!$B$BEn cuanto a ti, aquí tienes el pago, como te prometí. ¡Quédate con el cambio, bestia asquerosa!",
		},
		[7202] = {
			title = "Korrak el Sanguinario",
			accept = "Los trols indígenas Hacha Invernal de esa región son salvajes despiadados a los que nada complacería más que añadir nuestros huesos a su hediondo estofado.$B$B¡Debemos demostrarles nuestro poder!$B$BHemos recuperado unos libros de sus cuevas donde se describe su jerarquía de poder. Los artefactos apuntan a que su líder, Korrak el Sanguinario, tiende a permanecer oculto hasta que surge un motivo para manifestarse.$B$B¡La muerte de Korrak significaría el fin del clan Hacha Invernal! Mátalo y vuelve aquí.",
		},
		[7223] = {
			title = "Los restos de armadura",
			accept = "La batalla es encarnizada en el Valle de Alterac y los suministros que conseguimos de Forjaz no bastan para vestir a nuestros expertos soldados.$B$BSi encuentras restos de armadura en el campo de batalla, ¡contribuye a nuestro esfuerzo bélico y tráemelos!",
			complete = "Estas piezas son muy buenas, $n. Puedo usarlas para confeccionar nuevos equipos para nuestros soldados.$B$BSi mi nivel de suministro llega a ser suficientemente alto, ¡a lo mejor nuestras avezadas unidades de combate irán al campo de batalla!",
		},
		[7224] = {
			title = "Botín enemigo",
			accept = "Cuando te enfrentes al enemigo, reúne los restos de sus armaduras y tráemelos. ¡Los usaré para hacer armaduras para nuestros soldados!",
			complete = "Estos restos nos servirán. Los fundiré y los remendaré ¡y nadie se enterará de que proceden de esos cobardes Pico Tormenta!$B$BGracias, $n. Y permíteme pulir tu armadura...",
		},
		[7241] = {
			title = "En defensa de Lobo Gélido",
			accept = "Retumban los tambores de guerra en una tierra distante, $c. La abominable guardia de los Pico Tormenta de Forjaz está atacando al clan partidario de tu Jefe de Guerra.$B$BSolo con verte, deduzco que tienes resistencia para el combate y que estás $gpreparado:preparada; para hacer tuya la causa de los Lobo Gélido.$B$BTú eres quien debe ahora dar el paso siguiente en tu evolución.$B$BAl norte del Molino Tarren, en Alterac, hallarás la entrada del Valle de Alterac. Allí encontrarás al maestro de guerra Laggrond. ¡Date prisa, $c, que la batalla está próxima!",
			complete = "Para convertirte en $gun:una; soldado Lobo Gélido, hay que ponerte a prueba...",
		},
		[7261] = {
			title = "El imperativo soberano",
			accept = "Estamos librando una brutal batalla en el Valle de Alterac. El salvaje clan Lobo Gélido desafía el poder a los Pico Tormenta. ¡Deben ser exterminados en el nombre del rey Magni Barbabronce! La toma, sacrificio y devolución de esa tierra es un imperativo soberano y territorial para el Reino de Forjaz.$B$B¡Por desgracia, los soldados no crecen en los árboles! Ponte a las órdenes del teniente Haggerdin en las afueras del Valle de Alterac para empezar tu recorrido de deber y honor entre los Pico Tormenta.",
			complete = "¡A trabajar!",
		},
		[7281] = {
			title = "Amor fraternal",
			accept = "Una tragedia... Mi hermano y yo enfrentados en el campo de batalla: un Comandante de los Pico Tormenta.$B$BDe los cuatro Comandantes de los Pico Tormenta, es sin duda alguna el más peligroso. Quizás si lo ejecutan, la reina alma en pena podría convertirlo como hizo conmigo, demostrarle cuán equivocado está...$B$BEn lo más profundo del territorio enemigo encontrarás a mi hermano. Ejecútalo y vuelve aquí. Confío en que serás capaz de cumplir esta misión, soldado.$B$BAh, soldado, no vayas en solitario.",
			complete = "Tus proezas no pasarán desapercibidos, $n.$B$BNo debo perder el tiempo si hay que salvarlo. ¡Hay que ponerse en contacto con Sylvanas!",
		},
		[7282] = {
			title = "Amor fraternal",
			accept = "¡Hay que acabar con su sufrimiento, soldado! No sabe lo que hace Se ha convertido en un sirviente ciego de la temida reina alma en pena.$B$BRealiza una incursión por la Tierra de Disputa y hasta lo más recóndito del territorio de los Lobo Gélido. Encuentra a mi hermano y acaba con él. Hay que poner fin a su tormento.",
			complete = "Te acordaste de incinerar el cuerpo, ¿verdad?",
		},
		[7301] = {
			title = "Señores del Cielo caídos",
			accept = "Los tenemos prisioneros, $r. Me refiero a sus Comandantes del aire. Fue una batalla encarnizada en los cielos pero ¡al final cayeron! Desgraciadamente, abatieron a nuestros mejores pilotos en un contraataque sobre el Bastión Lobo Gélido. Tienes que averiguar qué ha sido de ellos.$B$BBusca al oeste de Torre de la Punta y por el Bastión Lobo Gélido. Allí es donde se les vio por última vez. No dejes piedra por remover en estas zonas.",
			complete = "¡Increíble! Los has liberado, ¿verdad? ¿¿¿No??? Bueno, al menos sabemos dónde están retenidos",
		},
		[7302] = {
			title = "Señores del Cielo caídos",
			accept = "Nuestro apoyo aéreo es un caos, $N. Han abatido a los Comandantes del aire sobre territorio enemigo. ¡Tienes que averiguar qué ha sido de ellos para que podamos intentar rescatarlos!$B$BSe vio por última vez a Guse sobrevolando el Búnker Ala Gélida. Al alas de guerra de Jeztor se le avistó cerca de la Serrería Pico Tormenta. Mulverick... ese chalado temerario se estrelló cerca del Búnker Norte de Dun'Baldar.$B$BEso es todo lo que sé. ¡Vamos! No dejes piedra por remover en estas zonas.",
			complete = "¡Muy bien! La información que has conseguido es muy valiosa para nuestra causa.",
		},
		[7321] = {
			title = "Sopa de tortuga reconfortante",
			accept = "¿Quién dice que los no-muertos no saben nada de cocina? Como mi receta secreta para sopa de tortuga, por ejemplo. ¡He conocido sujetos que vuelven de la muerte solo para disfrutar de un tazón! Je, je...$B$BPor cierto, no he podido preparar nada últimamente. Antes iba al Lago Lordamere para cazar quijafortes, criaturas despreciables, pero no puedo apartarme de mi trabajo aquí.$B$BSi me traes un poco de carne de tortuga de los quijafortes y unas especias calmantes, te enseñaré a prepararla.",
			complete = "Mi sopa de tortuga reconfortante te mantendrá caliente en una noche fría... por si te interesa saberlo.",
		},
		[7341] = {
			title = "Un trato justo",
			complete = "¡Excelente! Soy un tauren de palabra, $r; aquí tienes las flechas.",
		},
		[7342] = {
			title = "Las flechas no valen para nada",
			complete = "¡Un trato hecho si alguna vez vi uno! Las flechas son tuyas.",
		},
		[7361] = {
			title = "Favor entre los Lanza Negra",
			accept = "<Najak gruñe>.$B$BAntes de que los elfos de la noche existieran había trols. Es en los trols donde radica el origen de los elfos de la noche.$B$BNo toleraré sus ataques rebeldes contra mi pueblo. El objetivo de Corzocelada es aniquilarnos para no dejar rastro de los que lo concibieron ni de su clase. ¡No ocurrirá!$B$BPor cada elfo de la noche que mates y decapites, Najak te concederá el favor entre los Lanza Negra. Se correrá la voz de tus actos por todo Kalimdor y los Reinos del Este. ¡Márchate ahora y sirve a la Lanza Negra!",
			complete = "$n, es solo uno entre miles. No obstante, un trabajo bien hecho.",
		},
		[7362] = {
			title = "Aliado de los Tauren",
			accept = "La bruja más anciana me envió a esta zona de guerra para investigar sobre otras razas. Más concretamente, estoy recolectando muestras de gnomo. Lo que más interesa a Magatha es su capacidad de supervivencia. Sí, los gnomos, aunque lamentablemente débiles y minúsculos, exudan gran resistencia en el combate y fuera de él.$B$BPor suerte para ti, ando buscando a rufianes para cumplir ese encargo de Magatha. Regresa con mechones de los gnomos y los tauren reconocerán en ti a un aliado.",
			complete = "Sí, definitivamente esto es un gnomo. Bien hecho, $r, pero hay más trabajo por hacer.",
		},
		[7363] = {
			title = "La condición humana",
			accept = "Los humanos son absolutamente detestables.$B$B<el comandante Philips esboza una mueca>.$B$BAunque es cierto que soy un soldado de los Lobo Gélido, siempre seré un sirviente de Sylvanas.$B$BCuando estoy de servicio, me ocupo de tareas adicionales para los boticarios oscuros de Entrañas.$B$BMe han encargado que recolecte esquirlas de huesos humanos que se usarán para curar a la condición humana.$B$BTengo autorización para delegar esa tarea en mis subordinados.$B$BEncuéntralos. Mátalos. Tráeme sus esquirlas de huesos.",
			complete = "Sería más fácil si aceptaran su enfermedad y se entregaran a tu toque sanador. Probablemente también sería menos divertido. ¡Sigue adelante! Los curaremos, de una forma u otra.",
		},
		[7364] = {
			title = "La recompensa de Gnomeregan",
			accept = "El Gran Manitas en persona me ha enviado a este campo de batalla para defender a mis hermanas y hermanos gnomos. Según nos cuentan, los tauren están señalando y masacrando a los gnomos. Y lo que es peor, están arrebatando gloriosos mechones gnomos de los cadáveres caídos. Estas atrocidades deben cesar. ¡Debemos responder con la misma moneda!$B$BQuiero verlos sin pezuñas, $c. ¡Tráeme sus pezuñas! Demuestra que eres un aliado de los gnomos.",
		},
		[7365] = {
			title = "Réquiem de Corzocelada",
			accept = "Corzocelada ha dado la orden. Hay que exterminar a todos los trols en el campo de batalla. Sus absurdas pretensiones según las cuales dan a luz a elfos de la noche se debe contrarrestar con la fuerza y el debido perjuicio.$B$BAsesínalos y tráeme su mojo. Insisto: quiero que les robes el mojo.",
		},
		[7366] = {
			title = "La misericordia del arzobispo",
			accept = "El arzobispo es tan amable como sabio. Para que un hombre mire con compasión a ese grupo de desgraciados...$B$B<el comandante Philips se sacude la cabeza incrédulo.$B$BDemasiado amable... Sencillamente demasiado amable.$B$BEl arzobispo nos pide que compadezcamos a los no-muertos y les concedamos muertes rápidas y permanentes. Para tal muestra de misericordia, tan solo necesitamos sus ennegrecidos corazones dominados por el mal.$B$BTráeme los corazones de los Renegados para poder incinerarlos con la ceremonia debida en la Catedral de la Luz. ¡Apúrate, $n!",
			complete = "¡Alabado sea Benedictus! ¡Otra alma perdida, que pronto será salvada por las llamas candentes de la Luz!$B$B¡Vete, oh soldado de la Luz! ¡Hay que salvar más!",
		},
		[7367] = {
			title = "Acabar con la amenaza",
			accept = "Las bases y las líneas más avanzadas de los Lobo Gélido han caído en una trampa, $c. Tienes que mirar donde pisas al invadir territorio enemigo.$B$BSi quieres dar un golpe contundente contra ellos, debes destruir su fuente de municiones antipersona, es decir su especialista en explosivos. Si lo matas, estarás a salvo para desarmar las minas. Mientras él esté bajo control, también lo estarán las minas.$B$BEs probable que lo encuentres en una torre en las cercanías del Baluarte Sangrehielo. ¡Suerte!",
		},
		[7368] = {
			title = "Acabar con la amenaza",
			accept = "Conozco bien las minas. Al fin y al cabo, soy el que las coloca todas en primera línea de frente.$B$BSi quieres desactivar los campos de minas de los Pico Tormenta, solo tienes que matar a su especialista en explosivos. Seguro que ese enano cobarde se oculta en la primera torre de la Tierra de Disputa. Sácalo de allí y esas minas no volverán después de haber sido desactivadas.$B$BSi resulta que lo matas, vuelve para hacérmelo saber. Toda buena acción merece su recompensa.",
		},
		[7381] = {
			title = "El regreso de Korrak",
			accept = "Aunque es cierto que Korrak ha sido ejecutado, queda pendiente un asunto: ¿permanecerá muerto? Los trols son famosos por su magia tribal de otro mundo. No me sorprendería que el líder caído resurgiera de entre los muertos para volver a gobernar su clan.$B$BSabes qué hacer si tal cosa ocurriera.$B$B<El maestro de guerra Laggrond se pasa el índice por el cuello como si lo degollaran.>$B$BY esta vez, quiero su calavera. Abre bien los ojos, soldado.$B$B¡Retírese!",
		},
		[7382] = {
			title = "Korrak el Eterno",
			accept = "Hay algo que no encaja en todo esto... ¿Ha pensado alguien en quemar el cadáver de Korrak? Esos trols no se detendrán ante nada para resucitar a su líder caído <como a menudo hacen los paganos semihombres-semibestias.$B$BAbre bien los ojos, $n. No te asustes si Korrak nos sorprende con una reaparición y, si lo hace, quiero que sea ejecutado y que su cuerpo sea reducido a cenizas.$B$BPara mayor seguridad, córtale la cabeza y tráeme su calavera antes de prenderle fuego al cuerpo sin vida.",
		},
		[7383] = {
			title = "La corona de la Tierra",
			accept = "Sin embargo, no todo iba bien en Teldrassil. Corzocelada lo había planeado todo meticulosamente ya que el Árbol del Mundo había brotado según lo previsto, pero ocurrió un pequeño desajuste, desajuste al que se pueden atribuir muchos de los conflictos de Teldrassil.$B$BPero no entraré en detalles por ahora. Debes ir a la última Poza de la Luna, al noroeste de El Claro del Oráculo. Debajo de las ramas del Árbol del Oráculo se encuentra la primera y más poderosa de nuestras pozas. Llena una ampolla con agua de esta poza y tráemela.",
			complete = "Cuando estás en presencia del Árbol del Oráculo... es como sentir la sabiduría tomar forma. Permíteme continuar el relato...$B$BCon Teldrassil en crecimiento, el Archidruida se acercó a los dragones para recibir sus bendiciones, como habían hecho sobre Nordrassil en tiempos antiguos. Sin embargo, Nozdormu, Señor del Tiempo, se negó a dar su bendición, reprendiendo a los druidas su arrogancia. De acuerdo con Nozdormu, Alexstrasza Staghelm también se negó y sin su bendición, el crecimiento de Teldrassil ha sido deficiente e impredecible...",
		},
		[7385] = {
			title = "Un galón de sangre",
			complete = "Se ha derramado sangre enemiga. Mezclaré esta sangre con el resto de elementos que hemos recolectado. Cuando la ofrenda esté completa, el Señor del Hielo enseñará a esos perros Pico Tormenta ¡toda la ira del clan Lobo Gélido!",
		},
		[7386] = {
			title = "Recogida de cristal",
			complete = "Muy bien, $n. Usaré el poder de estos talismanes para aumentar la magia que ya se ha reunido. Cuando hayas acumulado suficiente poder, concentraré las energías reunidas e invocaré al Señor del Bosque para que nos ayude en nuestra causa.",
		},
		[7401] = {
			title = "Se buscan: ¡ENANOS!",
			accept = "Por orden del sargento Yazra Gruñido Sangriento, todos los enanos del campo de batalla han de ser ejecutados en el acto.$B$BSi das muerte a un enano en combate, arráncale la espina dorsal, dejando un putrefacto y hediondo montón sin espina que sirva de advertencia a todo aquel que ose oponerse al poder de los Lobo Gélido.$B$BTráele al sargento Yazra Gruñido Sangriento la prueba de tu hazaña.",
			complete = "¡Ahora tienes licencia para diezmar a los enanos por docenas, $n!$B$B<Yazra mira a lo lejos por un momento.>$B$BNunca olvidas tu primer desespinado...",
		},
		[7402] = {
			title = "Se buscan: ¡ORCOS!",
			accept = "Por orden del cabo Noreg Pico Tormenta, se exige de todos los soldados Pico Tormenta sanos que maten a todo orco que muestre oposición en el campo de batalla.$B$BLos soldados deberán llevarse un colmillo o un diente de las fauces del enemigo y presentar dicho diente como prueba de haber cumplido.$B$BLlevar guantes protectores.",
		},
