		[7429] = {
			title = "¡Libera a Knot!",
			complete = "¡Gracias por liberarme! Tú... eres $gel:la; mejor. Todos los demás no te llegan ni a la rodilla.$B$B¡Sabía que mi destino no era acabar siendo el aperitivo de algún ogro!",
		},
		[7441] = {
			title = "Pusillín y el ancestro Azj'Tordin",
			accept = "Bajé la guardia un solo momento... Intentaba escapar de las garras del príncipe caído y, en la confusión... me robaron. Un ser abominable, el diablillo Pusillín, me robó el libro de Conjuros y la llave de las antaño magníficas salas de Eldre'Thalas.$B$BLa llave ya no me preocupa, pues ya cambié mi inmortalidad por la libertad, pero necesito desesperadamente mi libro de Conjuros.$B$BEncuentra a ese diablillo Pusillín y recupera mi libro.$B$BEmpieza a buscarlo en el Barrio Alabeo de La Masacre.",
			complete = "¡Lo has encontrado! Maldito sea ese miserable diablillo. Aunque mis posesiones materiales no son muchas, puedes elegir la que quieras de entre ellas.",
		},
		[7461] = {
			title = "Locura interior",
			accept = "¿Has oído suficiente? ¿Eres $gun hombre:una mujer; de acción?$B$BEsta locura debe acabar. El tiempo de los inmortales expiró hace mucho tiempo. Destruye a los guardianes que rodean las torres para debilitar el campo de fuerza. Una vez hecho eso, destruye a Immol'thar. Cuando el poder del Príncipe esté muy mermado, ataca y acaba con él. Deja que el espíritu de la ciudad descanse.",
			complete = "Te damos las gracias, $ghéroe:heroína;.",
		},
		[7463] = {
			title = "El refresco arcano",
			accept = "¡Vaya, $gun mago:una maga; $r! Esto es increíble. No he visto a nadie de tu clase en... ¿cuánto? ¡500 años!$B$BTengo algo que saciará tu sed, pero primero tienes que hacer algo por mí.$B$B<Lydros se ríe.>$B$BHay una anomalía en Eldre'Thalas. Un elemental de agua se ha instalado en el ala este. ¡Hay que catalogar su presencia!$B$BVe al Barrio Alabeo y extrae una porción de esencia elemental del Hidromilecio. Devuélvemela y te enseñaré un conjuro útil.",
			complete = "¡Estupendo! ¿Quién decías que eras? Bah, no importa. ¿Qué era lo que te tenía que dar? Mm... bueno, como eres $c, puede que esto te resulte útil.",
		},
		[7481] = {
			title = "Leyendas élficas",
			accept = "Hace muchos años, un maestro élfico solitario llamado Telmius Buscasueños huyó de la devastación de su hogar llevándose varios artefactos élficos antiguos.$B$BNuestra búsqueda de este maestro perdido nos ha llevado desde las ruinas de Quel'Thalas, por las Estepas Ardientes, a través de las grandes extensiones marítimas, y hasta Feralas.$B$BCreemos que el elfo buscó refugio en los salones de Eldre'Thalas (lo que ahora se conoce como La Matanza).$B$BDebes encontrarlo, $gaventurero:aventurera;. Vivo o muerto, ¡debemos recuperar el conocimiento que se llevó!",
			complete = "Una pena... una tragedia. ¿Así que dices que los objetos se han perdido? No hay rastro de ellos, ¿eh?",
		},
		[7482] = {
			title = "Leyendas élficas",
			accept = "Hace varios años, un solitario maestro elfo llamado Kariel Winthalus huyó de la devastación de su tierra con su remolque lleno de antiguos artefactos élficos.$B$BSeguimos su rastro desde las ruinas de Quel'Thalas hasta Feralas, a través de Las Estepas Ardientes y del ancho mar.$B$BSospechamos que buscó refugio en las salas de Eldre'Thalas (que ahora se conocen como La Masacre).$B$BDebes encontrarlo. Esté vivo o muerto, es necesario recuperar los conocimientos que llevaba consigo.",
			complete = "Una pena... una tragedia. ¿Así que dices que los objetos se han perdido? No hay rastro de ellos, ¿eh?",
		},
		[7483] = {
			title = "El tratado sobre rapidez",
			accept = "El maestro Winthalus perdió el tratado sobre rapidez en el ala este. El tratado nos permitirá lanzar un conjuro menor de rapidez a tu equipo. Es más bien un conjurillo de andar por casa...$B$BEn cualquier caso, si la cosa te interesa, tendrás que conseguir el tratado y algunos componentes básicos.$B$BMmm... Y creo que podríamos necesitar también sangre de los héroes, un diamante negro prístino y unos fragmentos luminosos grandes. Pero podría equivocarme.$B$B<Lydros se encoge de hombros.>",
			complete = "<Lydros bosteza.>$B$BComo prometí, el Arcanum de Rapidez. No lo gastes todo en un solo lugar.$B$B<Lydros se ríe.>",
		},
		[7484] = {
			title = "El tratado sobre enfoque",
			accept = "Este tratado casi despertó interés en uno de los familiares más jóvenes del Tradicionalista. La pobre criatura solo tenía unas semanas.$B$BAquellos de entre vosotros que tengan una mayor inclinación hacia la magia, podrían encontrar esto interesante.$B$BEl tratado sobre enfoque se perdió en esta ala. Solo puedo deducir que lo tiene uno de los espíritus de los Altonato.$B$BTrae el tratado con algunos fragmentos luminosos grandes, piel de Sombra y un diamante negro prístino y yo invocaré el arcanum.",
			complete = "No te hagas daño cuando apliques el encantamiento, $r.",
		},
		[7485] = {
			title = "El tratado sobre protección",
			accept = "Lloraba como un bebé por la pérdida de su tratado. Y ojo, yo también he llorado por algún texto, porque no hay mayor pérdida que la del conocimiento y la historia, pero llorar por una caótica recopilación de conjuros inútiles como esta... ¡es absurdo! Cualquiera diría que el Príncipe le estaba haciendo un favor arrancándole la carne de los huesos...$B$BTráeme el Tratado con un diamante negro prístino, fragmentos luminosos grandes y una costura desgarrada de abominación y yo recrearé el arcanum.$B$BAh, comprueba también el ala norte.",
			complete = "Sí, sí... Tranquilízate. Aquí tienes tu arcano, como te prometí.",
		},
		[7486] = {
			title = "Una recompensa de héroe",
			accept = "$N, tus servicios a los Señores del Agua sobrepasan cuanto habríamos esperado de los habitantes de este mundo.$B$BLos conceptos de gratitud y recompensa de tu gente nos son ajenos, pero en este caso haremos una excepción.$B$BEncontrarás un arca bajo la espuma en la base sur de la isla. Dentro está tu... recompensa.$B$BVe a por tu recompensa, $N.",
			complete = "La voz de Hydraxis surge del agua...$B$B\"Elige lo que más te plazca, $n. Que te proteja frente a los enemigos de los Señores del Agua.\"",
		},
		[7488] = {
			title = "La membrana de Lethtendris",
			accept = "La maga Lethtendris, una despiadada elfa sanguinaria cuya brutalidad solo es comparable a su adicción a la magia, se ha refugiado en La Masacre. Ha creado un dispositivo, una red que atrapa la energía mágica de ese lugar y tememos que, si no intervenimos, causará daños irreparables a nuestro mundo.$B$BDetenla, $n. Encuéntrala y arrebátale la red. Probablemente la encontrarás cerca de los sátiros del Barrio Alabeo, en La Masacre. Tráeme la red para que pueda liberar su poder y devolverlo con seguridad a su lugar...",
			complete = "¡Has conseguido la red! ¡Bien hecho, $n! Lethtendris, como muchos elfos de su ralea, no es consciente de los daños que el abuso de la magia puede ocasionar a nuestro mundo. Creen que son los dueños de la magia. No se dan cuenta de que en realidad son esclavos de una adicción. Su muerte me entristece, pero era necesaria.$B$BGracias, $n. Liberaré en un lugar seguro las energías que la red retiene y luego destruiré la red para impedir que vuelva a ser utilizada.",
		},
		[7489] = {
			title = "La membrana de Lethtendris",
			accept = "Lethtendris, la elfa sanguinaria, ha superado sus límites. Tan ansiosa estaba de acumular poder, que desafió a sus hermanos y creó un instrumento de insidioso diseño... una red destinada a recoger las impías energías mágicas de La Masacre. En este momento sigue reuniendo esas energías y planea lanzarlas contra sus enemigos.$B$BLethtendris ha de ser detenida. Encuéntrala. Estará en el Barrio Alabeo de La Masacre. Derrótala y tráeme su red para que pueda entregarla a elfos sanguinarios más cuerdos para que la estudien.",
			complete = "Has hecho un buen trabajo, $n. Esta red contiene enormes cantidades de la magia de La Masacre. El daño que alguien tan irresponsable como Lethtendris podría haber causado si hubiera llegado a controlar sus energías... es inimaginable. Me apenó su muerte, pero sé que ella nunca se habría separado de la red mientras le quedara vida.$B$BGracias, $n. Enviaré la red a unos estudiantes de magia más responsables que Lethtendris. Serán los nuevos custodios de su poder.",
		},
		[7490] = {
			title = "Victoria para la Horda",
			accept = "Has conseguido lo imposible. Has matado a la madre de los Vuelo Negro. Llévale la cabeza a tu Jefe de Guerra.",
			complete = "Qué gran victoria para la Horda, $n. Has honrado muchas veces a tu Jefe de Guerra, ahora él debe honrarte a ti.",
		},
		[7491] = {
			title = "Para que todos lo vean",
			accept = "El Señor supremo Runthak te espera en el Valle de la Fuerza.$B$B<Thrall te saluda.>.$B$BNo hagas esperar a tu público, héroe.",
			complete = "Elige tu recompensa y que empiece los festejos por tu gloriosa victoria.",
		},
		[7492] = {
			title = "Campamento Mojache",
			accept = "Talo Pezuñahendida, un ancestro Tauren de Feralas, envía una petición de ayuda. Dio pocos detalles, pero sí dijo que necesita agentes para un asunto tan delicado como... grave.$B$BSirve a la Horda, $n. Ve al Campamento Mojache de Feralas y habla con Talo.",
			complete = "Ah, me alegra ver que $gun:una; $c acude a mi llamada. Necesito tus servicios, $n. Y temo que lo que te pida te guiará por un camino peligroso...$B$BEl camino a La Masacre.",
		},
		[7493] = {
			title = "El viaje acaba de empezar",
		},
		[7494] = {
			title = "Bastión Plumaluna",
			accept = "¡$n! ¡Necesitan tu ayuda en Feralas!$B$BUna maga proscrita, Lethtendris, ha huido a las antiguas ruinas élficas de Eldre'Thalas que ahora se conocen como La Masacre. Se cree que lleva consigo un peligroso objeto de gran energía mágica. Debemos recuperarlo.$B$BLatronicus Lanzaluna solicita agentes para entrar en La Masacre y arrebatar el objeto a Lethtendris.$B$B¡Sirve a la Alianza! Busca a Latronicus en el Bastión Plumaluna de Feralas.",
			complete = "Saludos, $n. Me alegra verte, aunque me pesa que nuestro encuentro no se dé en circunstancias más agradables.$B$BEscucha con atención, pues tengo una tarea vital que encomendarte...",
		},
		[7495] = {
			title = "Victoria para la Alianza",
			accept = "Has conseguido lo imposible. Has matado a la madre de los Vuelo Negro. Llévale la cabeza a tu alto señor.",
			complete = "Durante muchos años su mirada cautivadora me privó de la libertad. ¡Al fin puedo ver que se hace justicia y se restaura el honor de Ventormenta! Hoy, celebramos esta gloriosa victoria.",
		},
		[7496] = {
			title = "Celebrar los buenos momentos",
			accept = "Busca al mayor Mattingly en el Valle de los Héroes, $N. Te estará esperando...",
			complete = "Pocos son recibidos con tanta ceremonia, $n. Por favor, elige tu recompensa para que podamos comenzar la celebración.",
		},
