		[7666] = {
			title = "El regreso a El Gran Osario",
			complete = "¿Vas de regreso a Scholomance, $n? Ya has pagado un alto precio por el Adivinador Arúspice; tal vez te gustaría llevarte otro. Con él, podrás enfrentarte a los peligros del Gran Osario una vez más.$B$BPor supuesto, tenlo. Ciertamente te lo has ganado.",
		},
		[7667] = {
			title = "Asistencia material",
			accept = "$N, hay un asunto urgente que creo que te interesará material y espiritualmente.$B$BEscondida en Scholomance, en Lordaeron, hay una cámara que se llama El Gran Osario. Quiero ultimar un instrumento que ahuyente las sombras de esa horrible sala. Para eso, necesito dos diamantes: uno de Azeroth y uno negro prístino. Sé que lo que pido no es fácil, pero no puedo hacerlo por mí mismo.$B$B¿Puedes traérmelos tú?",
			complete = "Tu generosidad no tiene rival, $n. Te agradezco tu amabilidad.$B$BAhora podré terminar mi adivinador, y debería ser capaz de hacer más sin necesidad de diamantes... ¿tal vez te interesaría ayudarme en su uso? Es para una tarea muy importante, te lo aseguro... ¡uno que no se controle podría significar un desastre absoluto para el reino de los espíritus!",
		},
		[7668] = {
			title = "La amenaza de Atracoscuro",
			accept = "El caballero de la Muerte Atracoscuro campa por sus respectos en El Gran Osario de Scholomance. Amenaza con pervertir el reino del espíritu para hacer lo que se le antoje, ¡hay que detenerlo! Aquí es donde entra en juego el cristal de adivinación que ayudaste a confeccionar.$B$BÚsalo en el corazón de El Gran Osario para convocar a los esbirros del espíritu de Atracoscuro. Derrota a los espíritus y aparecerá el mismísimo caballero de la Muerte. $n, ¡tráeme su cabeza! ¡Solo su derrota revocará el daño causado al reino de los espíritus!",
		},
		[7669] = {
			title = "El regreso a El Gran Osario",
		},
		[7670] = {
			title = "Lord Grisillo Quiebrasombras",
			accept = "$N, voy a explicarte lo que debes hacer para conseguir una montura.$B$BHabla con Lord Grisillo Quiebrasombras en el Distrito de la Catedral de Ventormenta. Te enseñará a cuidar de tu montura y te dirá qué tareas debes completar para conseguir una.$B$BTe deseo lo mejor. ¡Por la Luz, mi noble $G hermano:hermana;!",
			complete = "Me alegro de verte $n. Sé que has esperado noticias sobre cómo adquirir su montura, y ahora ha llegado el momento.$B$BSeguramente se te pondrá a prueba de muchas maneras diferentes, pero lo más importante es tu voluntad de superar los numerosos obstáculos que se te presentan. Estos no se realizan como un ejercicio de aprendizaje: su dificultad va más allá de las simples pruebas educativas. Debes salvar a tu futuro compañero de las garras del mal contra el que te has pasado la vida luchando.$B$B¡Ojo, ha llegado la hora!",
		},
