		[7701] = {
			title = "SE BUSCA: Sobrestante Maltorius",
			accept = "Por orden de su eminencia el sobrestante Puñaceite: el sobrestante Maltorius, agente pícaro de la Hermandad del Torio y recién ascendido jefe del personal Hierro Negro de La Caldera de La Fosa de la Escoria, debe morir. Trae su cabeza como prueba. $B$BLo de la recompensa háblalo con el capitán de vigía Lolo Zancalarga.",
			complete = "¡Qué cosha más fea!$B$BPues shabes, está mejor así, sin el cuelpo.$B$BToma la recompensa, ¡hip!, $r.",
		},
		[7703] = {
			title = "Asunto Gordok sin finiquitar",
			accept = "Así que tú ser Rey... ¡pues a lo mejor recuperar artefacto Gordok de asqueroso elfo, él ir de \"Príncipe\"! Rey anterior fracasar, como resto reyes antes Tortheldrin, asqueroso elfo robar rey Gordok mucho tiempo!$B$BArtefacto llamarse guante del Poderío de Gordok. Historia muy, muy vieja decir solo rey verdadero de Gordok poder recuperar. Historia muy, muy vieja también decir asqueroso elfo aún estar cerca, tú encontrar, ¡tú llevar poderoso guante siempre jamás! ¡Ea, yo enseñar tú!",
			complete = "Vaya... ¡ERES un verdadero $grey:reina;! ¡Nunca pensé ver este guante en mi vida! Parece que ya no le queda nada de mojo... tal vez ese elfo asqueroso arruinar el guante. Bueno, le digo ¡HAR HAR!$B$BMira, esta marca en guante es vieja marca Mágica, más vieja que Da Gordok, dicen. Bueno, como Capitán de da Gordok, todos aprender una cosa una y otra vez: ¡hacer que la marca cobre vida y devolver el poder al guantelete!$B$B¡Lo hago por ti, $grey:reina;! ¡Aquí, toma el guante y gobierna PARA SIEMPRE!",
		},
		[7704] = {
			title = "¡Mira el tamaño de esto!",
			accept = "Vaya, vaya... La ayudante de cámara tenía una enorme almohada bordada y ahora es tuya. Seguro que Evonis Fumollín estará encantada; llévale la almohada, a ver si te recompensa con algo.",
		},
		[7721] = {
			title = "Combustible para el Ultra-reductor",
			accept = "Si en contra de lo que me dicta el sentido común, me quedo en La Costa Olvidada para montar una tienda de ingeniería, tendré que tratar con esos apestosos elementales. ¡Malditos sean esos descontrolados poderes de elementalismo!$B$BPor suerte para mí —y también para ti, mi $gestimado:estimada; agente provocador— los elementales son una estupenda fuente de alimentación para mi Ultra-reductor. ¡Démosles un propósito en la vida! Eso sí, cuando los reduzcas, ¡guárdame los núcleos de elementales de agua!",
			complete = "¡Fantastiquísimo! Estos núcleos me darán trabajo un buen tiempo. Y si añadimos a eso el hecho de que ya hay menos elementales en la costa, ¡creo que no volveré a tener esa pesadilla en la que me veo obligado a montar mi negocio en el peor sitio que se pueda imaginar!$B$BGracias por tus esfuerzos, $n. Aunque me repatea financieramente, quiero mostrarte mi agradecimiento con algo que seguramente apreciarás: ¡pasta!",
		},
		[7722] = {
			title = "¿Qué pasa con el flujo?",
			accept = "Cuando ese traidor de Maltorius se marchó de nuestro clan, se llevó algo más valioso que un cristal arcano prístino: ¡nuestra receta del flujo ígneo! Apuesto a que pagó con eso su ascenso entre los Hierro Negro.$B$BNecesito que recuperes nuestros diseños secretos, $N. Estarán cerca de Maltorius, en lo más profundo de La Fosa de la Escoria.",
			complete = "Espero que le partieras los dientes, $n. Se lo merecía.$B$BY ahora, a lo nuestro.",
		},
		[7723] = {
			title = "¡Malditos dedos gordos!",
			accept = "Por desgracia, yo no puedo ocuparme del asunto con los dedos así. Es que el clima de aquí y las bajas presiones hacen que se me hinchen. Morcillas de Thelsamar parecen, mira, mira... $B$BVas a tener que hacerlo tú a mis órdenes. $B$BLo primero que hay que hacer: zurrar a los gólems de guerra de la Garganta. Venga, arreando.",
			complete = "Has trabajado muy bien. Mira, te has ganado un regalito.",
		},
		[7724] = {
			title = "Amenaza abrasadora",
			accept = "Está claro: cada vez que el viejo Hansel decide sentarse a descansar, los dioses le envían trabajo. $B$BEso me hace pensar, ¿entiendes? $B$BEn fin, hay unas arañas de lava gigantescas que están dando problemas. Puñaceite dice que echan fuego por el... Bueno, que no es agradable, dice. $B$BSupongo que tenemos que matarlas. Más bien, tú tienes que matarlas.",
			complete = "<Hansel estornuda.>$B$BMe estoy resfriando. ¡Odio este clima!",
		},
		[7725] = {
			title = "Encoge más gigantes",
			accept = "Sé que ya me has traído residuos pero... si te divirtió la experiencia y quieres hacer un bis, yo encantado de que me traigas un poco más.$B$BEsta vez tampoco puedo ofrecerte gran cosa como compensación, pero estaré encantado de hacer correr la voz de que me has ayudado entre todos los goblins que conozca y que tengan orejas.$B$BY puedes creerme, algunos de esos goblins tienen orejas enormes.",
			complete = "¡Inconcebiblemente fantástico, $n! Me has sido de gran ayuda, una vez más. Te lo agradezco mucho.$B$BGracias.$B$BPuede que esta recompensa te parezca un poco menos de lo que te mereces, pero debes saber que tus hazañas en el campo de la goblinización resonarán en todas las salas del Cártel Bonvapor. Si quieres hacer alguna cosa más, ¡habla conmigo!",
		},
		[7726] = {
			title = "Más combustible para el Ultra-reductor",
			accept = "¿Dices que quieres más trabajo? ¿No sacié tu sed de aventura cuando te mandé a extraer restos chorreantes de dentro de los cuerpos de los elementales? Parece que si te envío a hacer más de lo mismo, no conseguiré llenar ese pozo sin fondo que es tu ansia de aventuras...$B$BPero dejémonos de frases bonitas, porque lo que necesito es precisamente eso: más núcleos de elementales de agua. Estoy luchando mucho por sacar el negocio adelante, así que la recompensa no sería gran cosa, pero te prometo que contaré a todos los que me escuchen lo que me has ayudado. ¡Y conozco a mucha gente que escucha en el Cártel!",
			complete = "¡De primera, $n, de primera! Aunque la modesta recompensa que te puedo ofrecer no te pagará este trabajo, debes saber que mis camaradas del Cártel Bonvapor oirán hablar de tu hazaña.$B$BY si estás buscando algo más que hacer, házmelo saber, te lo ruego. Porque siempre estoy buscando núcleos elementales y esas cosas.",
		},
		[7727] = {
			title = "¿Incendosaurio? Loqueseasaurio más bien",
			accept = "¡Buenas, $Gchaval:chavala;! Me han salido sabañones en los pies. ¿Cómo voy a salir por ahí a matar cosas con los pinreles así? Necesito que me eches una mano y unos pies. $B$BScrange y Burninate me encargaron que matara a esos bichos porque quieren mandar una expedición a los lagos de lava de La Fosa de la Escoria. Se ve que ahí abajo hay unos incendosaurios nada amistosos. Vete para allá y no vuelvas hasta que no quede ni uno.",
			complete = "Ay, mis pieses.$B$BPues si no tienes esponja...",
		},
		[7728] = {
			title = "OBJETOS ROBADOS: Tobera y catalejo",
			accept = "Los siguientes objetos han sido robados: $B$B*una tobera Hierro Negro. $B$B*un catalejo.$B$BSe ofrece recompensa a quien devuelva estos objetos.$B$BLa Hermandad del Torio sabe que estos objetos fueron robados por Hierro Negro celosos y faltos de escrúpulos de La Garganta de Fuego.$B$BEl catalejo es un objeto muy útil para los vigías y la tobera es imprescindible en la herrería.$B$BSi recuperas estos objetos, llévaselos a Scrange.",
			complete = "¡Buen trabajo! Y ahora, la recompensa.",
		},
		[7729] = {
			title = "OPORTUNIDAD LABORAL: Acabar con la competencia",
			accept = "El capataz Scrange busca personal para acabar con la competencia en La Garganta de Fuego.$B$BSi te interesa, ve a La Garganta de Fuego y mata a todos los capataces y esclavistas Hierro Negro que veas.$B$BVe a ver al capataz Scrange cuando haya suficiente sangre en tu ropa.$B$BNo preguntes: cuando haya sangre suficiente, lo sabrás.",
			complete = "¡7 kilos! ¡No está mal tener toda esa sangre y tripas en la ropa! ¡Enhorabuena, $c!",
		},
		[7730] = {
			title = "Infestación de Zukk'ash",
			accept = "Por lo que hemos podido deducir de nuestras exploraciones, los enemigos que están al sur de los gnolls son una raza de insectos. Y francamente, me da igual que sean o no conscientes de lo que nos hacen. Si con sus actos empujan a los gnolls contra nosotros, entonces son una amenaza, como lo son los gnolls, si no peor.$B$BAdéntrate en Las Galerías Retorcidas, que es donde viven estos insectos Zukk'ash. Reduce su número y vuelve a informarme de lo que encuentres. Trae contigo sus caparazones como prueba de que has cumplido.",
			complete = "Bien hecho, $c. Aunque los Zukk'ash están muy extendidos y no podremos librarnos de ellos sin una invasión a gran escala, nos has hecho ganar tiempo para elaborar una buena estrategia.$B$BHaré analizar estos caparazones. Tenemos que averiguar todo lo que podamos sobre ellos si queremos erradicar lo que, por desgracia, ha resultado ser un problema mucho mayor de lo que habíamos previsto.",
		},
		[7731] = {
			title = "Latigador con aguijón",
			accept = "Uno de los exploradores que vigilaba Las Galerías Retorcidas avistó un insecto gigante, uno mucho más grande que los otros, deambulando por la zona. No solo es más grande que los demás, además parece secretar una especie de aura, cosa que los demás insectos no hacen. Le hemos dado un nombre: latigador con aguijón.$B$BNos vendría bien estudiar las tripas de esta bestia mientras intentamos averiguar cuál es la mejor manera de afrontar esta nueva amenaza. Corta sus glándulas secretoras y tráemelas de inmediato.",
			complete = "Impresionante, $c... ¡muy impresionante! Latigador con aguijón es una de sus criaturas más fuertes. Lo que averigüemos estudiándola será sin duda, valioso para el futuro. Ahora debo ocuparme de que podamos defendernos el tiempo suficiente para estudiarla bien.$B$BPor favor, acepta esta recompensa como muestra del agradecimiento de todo el campamento, $n. Bien hecho.",
		},
		[7732] = {
			title = "El informe Zukk'ash",
			accept = "Has hecho un buen trabajo señalando la amenaza que los insectos Zukk'ash suponen para el Campamento Mojache. No podemos bajar la guardia con esos bichos. Por eso quiero pedirte que hagas algo más por la Horda.$B$BEn este documento se detalla toda la información que hemos reunido sobre esos insectos Zukk'ash. Quiero que se lo lleves a Zilzibin Tambor Sabio a La Calle Mayor de Orgrimmar. Es un experto en criaturas alienígenas como estas, espero que él pueda hacer algo con el conocimiento que hemos adquirido.",
			complete = "Ah, esto es lo que estaba esperando. Esas criaturas a las que te enfrentaste son una antigua amenaza que la Horda prefiere ignorar. Hadoken ha hecho bien en enviarme esto. Y en enviarte a ti.$B$BLos Zukk'ash son en realidad esas criaturas que llamamos silítidos. Algunos creen que son apenas una descerebrada molestia, pero te puedo asegurar que son una amenaza mucho mayor de lo que la Alianza pueda pensar.$B$BSi quieres ayudar y eres lo suficientemente fuerte, me vendría bien tu colaboración para sacar este asunto a la luz.",
		},
		[7733] = {
			title = "Calidad mejorada",
			accept = "He encontrado una fuente de pieles aún mejor, ¡aunque sea casi imposible de creer! En la región norte de Feralas –en las profundidades de los Dominios de los Cicatriz de Rabia– hay otros yetis. Son más fuertes que los que has conocido hasta ahora, así que, si te apetece aceptar un nuevo desafío, ¡ponte en camino!$B$BTe recompensaré ampliamente por un hatajo de 10 pieles. Tráemelas y cerraremos nuestro trato.",
			complete = "¡Excelente, excelente! Estos pellejos van a quedar estupendos. Cuando estén bien curados serán incluso más resistentes.$B$BGracias de nuevo por tu ayuda, $n. Ten, acepta una de mis últimas creaciones.",
		},
		[7734] = {
			title = "Calidad mejorada",
			accept = "He encontrado una fuente de pieles aún mejor, ¡aunque sea casi imposible de creer! En la región norte de Feralas –en las profundidades de los Dominios de los Cicatriz de Rabia– hay otros yetis. Son más fuertes que los que has conocido hasta ahora, así que, si te apetece aceptar un nuevo desafío, ¡ponte en camino!$B$BTe recompensaré ampliamente por un hatajo de 10 pieles. Tráemelas y cerraremos nuestro trato.",
			complete = "¡Excelente, excelente! Estos pellejos van a quedar estupendos. Cuando estén bien curados serán incluso más resistentes.$B$BGracias de nuevo por tu ayuda, $n. Ten, acepta una de mis últimas creaciones.",
		},
		[7735] = {
			title = "Pellejo de yeti prístino",
			accept = "Has encontrado un pellejo de yeti impecable, increíblemente grueso y robusto. Mucho más que las que has visto en la Cicatriz de Rabia.$B$BSabes que Pratt McGrubben del Bastión Plumaluna busca siempre pellejos de yeti. Seguro que este pellejo le interesa.",
			complete = "¡Increíble! ¡Creo que has encontrado el rey de todos los pellejos de yeti!$B$BEstate $gseguro:segura; de que te pagaré bien por él. No suelo pagar mucho por un solo pellejo, pero sé que con este podré hacer algo muy especial. ¡Gracias por haber pensado en mí, $n!",
		},
		[7736] = {
			title = "Fabricar flujo ígneo con sangrerregia",
			complete = "Siempre hay sitio para el fluido ardiente. Tú sigue trayendo hasta que yo te diga.",
		},
		[7737] = {
			title = "Conseguir más aceptación",
			complete = "Sigue vertiendo el residuo.",
		},
		[7738] = {
			title = "Pellejo de yeti perfecto",
			accept = "Has encontrado algo que podría ser el pellejo de yeti perfecto. Este pellejo es excepcionalmente grueso y robusto. Mucho más que las de los yetis Cicatriz de Rabia.$B$BSabes que Jangdor Zancoveliz del Campamento Mojache busca siempre pellejos de yeti. Este pellejo en concreto le interesará mucho.",
			complete = "¡Qué hallazgo! ¡Creo que es el pellejo de yeti más perfecto que he visto en mi vida!$B$BSin duda merece una buena recompensa. No suelo pagar mucho por un solo pellejo, pero sé que con este podré hacer algo muy especial. ¡Gracias por haber pensado en mí, $n!",
		},
		[7761] = {
			title = "Orden de Puño Negro",
			accept = "¡Imbécil!$B$BTengo muy poca fe en tu capacidad para impedir que los extraños se infiltren en la guarida del maestro. En el muy probable caso de que mueras, este orbe tiene su propio sistema integrado a prueba de fallos para impedir que ningún desconocido se teletransporte directamente a Alanegra.$B$BSolo aquellos con la marca de Drakkisath en la mano pueden usar este orbe. Por suerte, Drakkisath es mucho más competente que tú, intendente. ¡Él mismo guarda la enseña!$B$B-Jefe de Guerra Rend Puño Negro$B$BP.D. Destruye esta carta, idiota.",
			complete = "Ni siquiera pestañeas cuando se te graba la marca a hierro candente sobre la piel. ¡Eres tan fuerte!$B$BAhora llevas la marca de Drakkisath. Que te diviertas arrasando el castillo.",
		},
		[7781] = {
			title = "Señor de Roca Negra",
			accept = "Vuelves a sentir esa vieja sensación. Las punzadas de victoria retumban por todo tu cuerpo. Ante ti está la cabeza monolítica y marcada por la guerra de Nefarian. Llévasela a tu alto señor, $gcampeón:campeona;.",
			complete = "No es necesario que te digan el significado de lo que has hecho, $n. Este día quedará registrado en los anales de la historia. Una victoria de las que la Alianza no conoce desde hace años, ¡si es que alguna vez lo ha hecho!",
		},
		[7782] = {
			title = "Señor de Roca Negra",
			accept = "Vete al Valle de los Héroes y habla con la mariscal de campo Petraponte.",
			complete = "<El mariscal de campo Afrasiabi se inclina.>$B$BElige tu recompensa, ¡que comience la celebración!",
		},
		[7783] = {
			title = "Señor de Roca Negra",
			accept = "Vuelves a sentir esa vieja sensación. Las punzadas de victoria retumban por todo tu cuerpo. Ante ti está la cabeza monolítica y marcada por la guerra de Nefarian. Llévasela a tu Jefe de Guerra, $gcampeón:campeona;.",
			complete = "Has honrado a la Horda una vez más, $n. El hijo de Alamuerte yace muerto. Seguramente, el maligno se agita.",
		},
		[7784] = {
			title = "Señor de Roca Negra",
			accept = "Busca al alto señor supremo Colmillosauro en el Valle de la Fuerza.",
			complete = "Elige tu recompensa para que yo pueda montar la cabeza de la bestia para que todos la vean.",
		},
		[7785] = {
			title = "Examina la vasija",
			accept = "Examina la vasija de su renacimiento, mortal. ¡De aquí renacerá el Hijo del Viento!",
			complete = "Que estés $gprotegido:protegida; en tu cruzada. Que el Maestro bendiga tus esfuerzos.",
		},
		[7786] = {
			title = "Thunderaan el Hijo del Viento",
			accept = "Te he contado todo lo que sé, $N. Eres tú quien debe encontrar elementium y aniquilar la forma corpórea del Señor del Fuego.$B$BSi lo consigues, obtendrás la bendición de Thunderaan.",
			complete = "Nunca imaginé que vería este momento.$B$BAdmírate, mortal.$B$B¡ADMIRA A AQUEL QUE ES MÁS ANTIGUO QUE LA VIDA MISMA!$B$B¡ADMIRA A AQUEL QUE SE HA ENFRENTADO A DIOSES Y TITANES!$B$B¡LIBÉRATE, MAESTRO! ¡ROMPE TUS CADENAS!",
		},
		[7787] = {
			title = "¡Arriba, Trueno Furioso!",
			accept = "Has derrotado al Señor del viento. Toma el acero durmiente y obliga al miserable embustero, Demitrian, a usar los materiales que aportaste para su traición y despertar a Trueno Furioso.",
			complete = "¡Por favor, no me hagas daño! ¡Llévatelo! ¡Llévate el acero! ¡Permite que Demitrian rehaga su miserable vida!",
		},
		[7788] = {
			title = "¡Expulsa al invasor!",
			accept = "Pasado este túnel encontrarás la Tierra de Disputas y desorden, joven $c. La Horda sigue diezmando nuestro sagrado bosque, talando el perenne follaje para alimentar a sus máquinas de guerra.$B$BEntra en la Garganta Grito de Guerra y defiende el Bastión Ala de Plata. ¡Haz retroceder a las fuerzas invasoras de la Horda!$B$BHazlo y obtendrás un talismán de mérito. Tráeme uno de esos talismanes, $n, y serás $grecompensado:recompensada;.",
		},
		[7789] = {
			title = "Acaba con los usurpadores Ala de Plata",
			accept = "Las tierras del Bosque de Vallefresno sucumbirán al poder de la Horda, $r. Nada de lo que haga o diga el Ala de Plata podrá detener nuestro mando soberano. Kalimdor pertenece a la Horda. ¡Con qué osadía intentan evitar que cosechemos lo que nos pertenece por derecho!$B$BDeja que el orgullo hinche tu pecho cuando reduzcas sus débiles intentos por frenar nuestro avance. Destruye a las centinelas Ala de Plata y obtén una marca de Honor Grito de Guerra. Vuelve a verme cuando tengas una de esas marcas, $n, y serás $grecompensado:recompensada;.|n",
			complete = "<El capitán Shatterskull ruge triunfante.>$B$B¿Cuánto más pueden soportar? ¿Cuántas inmundicias más de la Alianza deben perecer a manos de la Horda para que se retiren? Solo el tiempo lo dirá, $r...",
		},
