		[7931] = {
			title = "5 vales: Lote menor de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7932] = {
			title = "12 vales: lote inferior de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7933] = {
			title = "40 vales: lote superior de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7934] = {
			title = "50 vales: caja de almacenamiento de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7935] = {
			title = "10 vales: añojo del mes pasado",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7936] = {
			title = "50 vales: añojo del año pasado",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7937] = {
			title = "La Fortuna te espera...",
			accept = "\"La Fortuna te espera en la Vega del Este.\"$B$BEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen del Aserradero de la Vega del Este, en el Bosque de Elwynn. Te acercas más y ves un almiar junto a un establo.",
			complete = "¡Una búsqueda rápida en el pajar revela una caja de seguridad dentro de él! ¡Parece que has encontrado tu fortuna!",
		},
		[7938] = {
			title = "La Fortuna te espera...",
			accept = "\"La Fortuna te espera en Las Minas de la Muerte.\"$B$BEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de las Minas de la Muerte entre las ruinas de la aldea de Arroyo de la Luna, en los Páramos de Poniente. Te acercas más y te encuentras moviéndote a gran velocidad por unos enrevesados pasadizos hasta que llegas a un resplandeciente portal que lleva al mismísimo corazón de las minas. Cuando lo cruzas, aparece de la nada un extraño cofre.",
			complete = "¡Una búsqueda rápida del cofre revela una caja de seguridad dentro de él! ¡Parece que has encontrado tu fortuna!",
		},
		[7939] = {
			title = "Más piedras de pulir densas",
			complete = "Muchas gracias, $n. ¡Aquí tienes tus vales para la Feria de la Luna Negra!",
		},
		[7940] = {
			title = "1200 vales: orbe de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[7941] = {
			title = "Más refuerzos para armadura",
			complete = "Ahí lo tienes, $n. Un comercio justo. A disfrutar.",
		},
		[7942] = {
			title = "Más trastos de torio",
			complete = "Aquí tienes, $n. Aquí tienes vales para la Feria de la Luna Negra para que disfrutes. ¡No, como dicen, los gastes todos en un solo lugar!",
		},
		[7943] = {
			title = "Más ojos de murciélago vil",
			complete = "Gracias de nuevo, $n. ¡Aquí tienes tus vales!",
		},
		[7944] = {
			title = "La Fortuna te espera...",
			accept = "\"La Fortuna te espera en las Cuevas de los Lamentos.\"$B$BEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de una cueva al suroeste de El Cruce, en Los Baldíos. Te acercas más y te encuentras moviéndote a gran velocidad por unos enrevesados pasadizos hasta que llegas a un resplandeciente portal que lleva al mismísimo corazón de la cueva. Cuando lo cruzas, aparece de la nada un extraño cofre.",
			complete = "¡Una búsqueda rápida del cofre revela una caja de seguridad dentro de él! ¡Parece que has encontrado tu fortuna!",
		},
		[7945] = {
			title = "La Fortuna te espera...",
			accept = "\"La Fortuna te espera fuera de la Roca Crines Pálidas.\"$B$BEl papelito de la Fortuna que te dio Sayge está caliente. Cuando lo aprietas, ves una imagen de la Roca Crines Pálidas de Mulgore. Te acercas más y ves un tocón de árbol al lado de la entrada de la cueva.",
			complete = "¡Una búsqueda rápida del tocón del árbol revela una caja de seguridad dentro de él! ¡Parece que has encontrado tu fortuna!",
		},
		[7946] = {
			title = "Huevo de Jubjub",
			complete = "Gracias, $n. ¡Aquí tienes tu huevo! No estará listo para eclosionar por un tiempo, ¡pero cuando lo haga, tendrás una gran mascota!",
		},
		[7981] = {
			title = "1200 vales: amuleto de la Luna Negra",
			complete = "¡Aquí tienes, aquí tienes! ¡Un premio digno de $gun rey:una reina;! ¡Felicidades, amigo mío!$B$BSi tiene más boletos que te gustaría entregar, ¡házmelo saber! Mientras esté aquí la Feria de la Luna Negra, canjearé tus boletos.",
		},
		[8041] = {
			title = "La fuerza del Monte Mugamba",
			complete = "Saludos, $c. Soy Jin'rokh el Rompedor, trol de Mugamba. Nosotros, la tribu Zandalar, agradecemos todos tus esfuerzos. Saludamos tu tenacidad y fuerza de voluntad.$B$BLleva al cuello este talismán, $c. Deja que la fuerza del Monte Mugamba fluya por todo tu ser. ¡Que tu poder crezca cuando ataques a tus enemigos!",
		},
		[8042] = {
			title = "La fuerza del Monte Mugamba",
			complete = "Nuestros caminos se encuentran de nuevo, $c.",
		},
		[8043] = {
			title = "La fuerza del Monte Mugamba",
			complete = "¡Usa tu nueva fuerza para destruir a Gurubashi!",
		},
		[8044] = {
			title = "La Ira de Mugamba",
			complete = "Zul'jin sentiría envidia, $c. ¡Ve y conquista!",
		},
		[8045] = {
			title = "La Enseña del pagano",
			complete = "Sepan esto, paganos: una catástrofe nos ha unido. Tus costumbres paganas no son comprendidas ni apreciadas por Zandalar, pero somos gente justa. Usa esta marca alrededor de tu cuello. Servirá tanto de advertencia para nuestros enemigos como de símbolo de tu amistad con Zandalar.$B$BSigue sirviendo a nuestra gente y amplificaré el poder de la marca.",
		},
		[8046] = {
			title = "La Enseña del pagano",
			complete = "Haz lo que tengas que hacer para derrotar a nuestros enemigos, $c. Incluso si eso significa canalizar la Luz.$B$B<Jin'rokh se estremece.>",
		},
		[8047] = {
			title = "La Enseña del pagano",
			complete = "Nuestras creencias difieren pero nuestra causa es justa. Derrota a nuestros enemigos, noble $c.",
		},
		[8048] = {
			title = "La Enseña del héroe",
			complete = "Vigilancia, honor, lealtad, valentía... Tú encarnas todos estos rasgos y también lo hará tu marca.",
		},
		[8049] = {
			title = "El ojo de Zuldazar",
			complete = "Acepta este talismán como muestra de nuestro aprecio, $c.$B$BEl Ojo de Zuldazar crecerá en poder a medida que se fortalezca tu vínculo con los trols de Zandalar. Regresa a mí periódicamente y te impregnaré de la joya.",
		},
		[8050] = {
			title = "El ojo de Zuldazar",
			complete = "Sigue con tus esfuerzos, $n. El Cazador de Almas intentará devorar tu deseo de vivir.",
		},
		[8051] = {
			title = "El ojo de Zuldazar",
			complete = "Sigue adelante con tu batalla contra el Cazador de Almas y sus esbirros, $n. Nunca hay que permitir que abandone los confines de Zul'Gurub.",
		},
		[8052] = {
			title = "El Ojo que todo lo ve de Zuldazar",
			complete = "Golpea a todos y deja que Hakkar los resuelva...",
		},
		[8053] = {
			title = "Dechados de Poder: los Guardabrazos de librepensador",
			accept = "Eres $gun pagano:una pagana;. Los paganos tienen su lugar en nuestra tribu. Son los librepensadores de Zandalar. Y no temen la opresión. Los librepensadores mueren por aquello en lo que creen. Sabemos que tú también lo harías. Y eso te hace $gmerecedor:merecedora; de nuestro reconocimiento. Y también una oportunidad para seguir poniéndote a prueba.$B$BDebemos tener los Dechados de Poder. Ve a Zul'Gurub. Mata a los esbirros de Hakkar. Vuelve aquí cuando tengas lo que deseo. Hazte con la primera pieza del atuendo de librepensador Zandalar.$B$BEn marcha.",
			complete = "Haces mucho por honrarnos. Tus manos gotean con la sangre de los secuaces de Hakkar. Eres $gun amigo:una amiga; de la tribu.$B$BUsa estos Guardabrazos. Son los guardabrazos del librepensador. A esto es a lo que me refiero con el poder real.",
		},
		[8054] = {
			title = "Dechados de Poder: el Cinturón de librepensador",
			accept = "Tus creencias nos son extrañas, $gpagano:pagana;. Los ancestros Zandalar fueron un día tildados de herejes. Sucedió cuando el Imperio Gurubashi era fuerte. Los paganos osaron desafiar al sacerdote de Hakkar. Se dio caza a los paganos y fueron ejecutados como alimañas. Los paganos nunca flaquearon en su lucha contra el Dios de la Sangre. Honramos el precio que pagaron. Son los librepensadores.$B$BDestruye a los esbirros de Hakkar en Zul'Gurub. Tráeme los Dechados de Poder que busco. Recompensaré generosamente tu éxito.$B$BEn marcha.",
			complete = "Tu honor está asegurado en la tribu. Reclamas muchas muertes en Zul'Gurub. Los enemigos caen ante tus convicciones. Los enemigos caen ante tu poder.$B$BEste es el cinturón del librepensador. Es un símbolo de honor. Es un mojo poderoso. Ahora es tuyo.",
		},
		[8055] = {
			title = "Dechados de Poder: la coraza de librepensador",
			accept = "El equipo te da poder en la tribu. Así se honra a los librepensadores. Son zelotes. Imbuyen sus corazas con mojo potente. Aunque a ojos de sus enemigos sus creencias vacilan, no lo hacen sus petos.$B$BDebes ser honorable con nuestra tribu para tener una coraza así. Ve a Zul'Gurub. Coge los Dechados de Poder que necesito. Coge los Dechados más terribles. Tráemelos. Demuestra tu valía como $glibrepensador:librepensadora; de una vez por todas.",
			complete = "Has hecho lo que pocos pudieron. Has puesto de rodillas a los esbirros de Hakkar. Les has mostrado lo que puede hacer un librepensador. Nos has mostrado cómo se puede venerar a un hereje en la tribu. Tienes más que poder real. ERES el poder real.$B$BToma la coraza, librepensador. Aplasta a los que se te oponen.",
		},
		[8056] = {
			title = "Dechados de Poder: los Brazales de augur",
			accept = "Los augures de nuestra tribu son venerados por sus dones de visión divina, sí, sí. No son médicos brujos, se pasan el día lanzando huesos o leyendo hojas, no hechizando a gente. Como chamán ya sabes algo sobre el poder del augurio, los Zandalar valoramos el entendimiento que dan a la tribu.$B$BTráeme una ofrenda de los Dechados de Poder de Zul'Gurub y demuéstranos tu valía. ¡Hazlo y te daré los brazales más apreciados de nuestros augures!",
			complete = "Parece que tienes un poco del augur Zandalar en ti. Sabemos de las hazañas que has estado haciendo en Zul'Gurub en nuestro nombre, colega. Estos Dechados de Poder recorrerán un largo camino para ayudar a la tribu Zandalar, una tribu, debo agregar, a la que puedes llamar como amigos. Toma estos brazales, $n; ¡Te los has ganado y algo más!",
		},
		[8057] = {
			title = "Dechados de Poder: los brazales de haruspex",
			accept = "Un haruspex es un miembro clave de nuestra tribu, es sabio escuchar sus augurios. A través de la comunión con los animales y entregándolos a los espíritus cuando es necesario, nos dan su guía divina. En el pasado, la sabiduría y entendimiento de los adivinos nos dieron ventaja en las guerras contra las tribus disidentes del Gurubashi.$B$BTráeme una ofrenda de los Dechados de Poder de Zul'Gurub y demuestra tu valía. Hazlo y te daré unos brazales que desearía tener cualquier haruspex de los Zandalar.",
			complete = "Ah, puedo sentir el poder que viene de estos Dechados del Poder, $n. Demuestras ser alguien a quien en la tribu podemos llamar \"$gamigo:amiga;\". Un trato es un trato, $n... ¡contempla el poder de los brazales del arúspice!",
		},
		[8058] = {
			title = "Dechados de Poder: los Guardabrazos de vindicador",
			accept = "La venganza es poder. El vindicador Zandalar tiene ese poder. La tribu tiene muchos enemigos. El vindicador hace que se cumpla justicia. Ningún crimen queda impune. El vindicador impone ese castigo. Nuestros enemigos temen nuestra venganza. Hacen bien. Y lo harán siempre.$B$BConviértete en uno de nuestros vindicadores. Busca los Dechados de Poder en Zul'Gurub. Derrota a los esbirros de Hakkar y reclama venganza en nombre de la tribu. Serás $grecompensado:recompensada;.",
			complete = "Has sembrado mucha venganza en este día. Has tomado el rostro del vindicador. Has doblegado a los esbirros del Dios de la Sangre.$B$BToma esto. Alimentará tu venganza en el futuro. Ahora eres $gamigo:amiga; de los Zandalar.",
		},
		[8059] = {
			title = "Dechados de Poder: los Brazaletes de endemoniado",
			accept = "Los brujos se mueven por un terreno muy peligroso al tratar con demonios, pero nuestros endemoniados aún dan un paso más. A través de un antiguo ritual arcano, permiten que un demonio se introduzca en su ser. En lugar de dejar que les posea, esclavizan al demonio de su interior, absorbiendo el poder de la bestia a sus propias órdenes. Es una proeza que muy pocos llegan a dominar.$B$BPara que puedas aprender del poder del endemoniado, debo tener Dechados de Poder de Zul'Gurub. Ve allí y obtén lo que buscamos.",
			complete = "Bien hecho... sin duda se les obligó a pagar de forma insoportable antes de que renunciaran a los Dechados de Poder. Toma esto: las envolturas del endemoniado. Hecho de un poderoso mojo utilizado para convocar a la presa del demoníaco, es una herramienta poderosa en la adquisición de poder.",
		},
		[8060] = {
			title = "Dechados de Poder: los Brazaletes de ilusionista",
			accept = "Los magos de nuestra tribu son afamados ilusionistas. Utilizan mojo potente en sus encantamientos, para confundir y desorientar a los enemigos de la tribu.$B$B<Al'tabin ríe perversamente.>$B$BEs maravilloso ver a un poderoso ilusionista trabajando, ¡consiguiendo que nuestros enemigos caigan al suelo atormentados por su propia locura!$B$BSi quieres conocer las artes de nuestros ilusionistas ve a Zul'Gurub y tráeme Dechados de Poder selectos. A cambio te daré los brazaletes que utilizan nuestros ilusionistas en sus hechizos.",
			complete = "Impresionante... ¿podrías sentir el mojo fluyendo a través de ellos? Los Dechados de Poder se utilizaron como moneda de cambio cuando el Imperio Gurubashi gobernaba estas tierras. ¡Ahora nosotros, Zandalar, usaremos el mojo latente dentro de ellos para luchar contra el segundo ascenso del Dios de la Sangre Hakkar!$B$BLo has hecho bien hoy; considera que tienes un amigo en los Zandalar. Para eso, ¡aquí están los brazales de ilusionista que prometí!",
		},
		[8061] = {
			title = "Dechados de Poder: los Brazaletes de confesor",
			accept = "Los Zandalar investimos de poder a quienes hablar con la autoridad de la divinidad. Nuestros sacerdotes son algo más que simples sanadores... son nuestros confesores. El mal viene de amenazas externas, como Hakkar, y del interior de nuestra tribu. Nuestros confesores actúan como jueces entre nosotros, guardándonos del mismo mal que devoró a los Gurubashi desde su interior.$B$BVe a Zul'Gurub y trae de vuelta los Dechados de Poder de los Gurubashi. Aprende qué es ser un confesor y defiéndenos del mal.",
			complete = "¡Excepcional, $n! No fue una hazaña pequeña traerme estos. Sin duda has actuado hoy como confesor de nuestra tribu para protegernos de la amenaza de Hakkar. ¡Estos brazales son apropiados para $gun amigo:una amiga; de la tribu como tú!",
		},
		[8062] = {
			title = "Dechados de Poder: los Brazales de depredador",
			accept = "En los tiempos oscuros tras la caída del Imperio Gurubashi, los depredadores Zandalar utilizaban su valor para garantizar el sustento a la tribu. Los cazadores pretender ser como los depredadores de nuestra tribu... buscar una presa es encarnar la esencia del depredador, sí. Pero tu caza en Zul'Gurub nos mostrará si realmente puedes considerarte uno de nuestros mejores depredadores.$B$BTráeme una muestra de los Dechados de Poder de Zul'Gurub. Hazlo y darás los primeros pasos para convertirte en el penúltimo depredador.",
			complete = "Sí... no necesito una visión para sentir la presencia de los Dechado de Poder. Su éxito en Zul'Gurub ha impresionado a muchos miembros de la tribu. No solo te consideramos $gun amigo:una amiga; de los Zandalar, sino que también te consideramos lo suficientemente $gdigno:digna; para poseer los brazales del depredador: elementos poderosos y un símbolo de lo que significa ser un depredador. Bien hecho, $n.",
		},
		[8063] = {
			title = "Dechados de Poder: los Brazales de sinconcierto",
			accept = "Los sinconcierto de Zandalar son una especie de pícaros, pero por encima de todo abrazan la locura... el caos... la impredecibilidad de la existencia. Un terror a observar en el campo de batalla, sembraron las semillas de la confusión y el caos entre nuestros enemigos en los tiempos salvajes que siguieron a la división de las tribus. No estaríamos hoy aquí sin ellos.$B$BTráeme los Dechados de Poder de Zul'Gurub que busco y te otorgaré la primera de las piezas de armadura de sinconcierto. ¡Abraza la locura!",
			complete = "Bien hecho, $n... tus logros en Zul'Gurub te han ganado el derecho de llamar amigos a la tribu Zandalar. Me ocuparé de la disposición de los Dechados; por tu esfuerzo por favor acepta esta recompensa!",
		},
		[8064] = {
			title = "Dechados de Poder: el Cinturón de haruspex",
			accept = "Nosotros, los Zandalar, no conocemos las artes druídicas, la naturaleza debe amoldarse a nuestras necesidades y no al contrario. Aun así, un haruspex es aquel de entre nosotros que está más en sintonía con la naturaleza, y está bien que así sea. Hacer que un animal expire su último aliento es saber qué es ser uno de ellos. Es el verdadero poder de la naturaleza.$B$BTráeme una ofrenda de los Dechados de Poder de Zul'Gurub para probar tu valía. Hazlo y te daré un poderoso objeto, un cinturón que utilizan muchos de los haruspices de Zandalar.$B$B¡Mojo fuerte, sí, eso es!",
			complete = "Te lo agradezco, el poder latente de estos objetos es todo un tesoro, te lo aseguro. No solo has hecho lo que te pedí, también has demostrado que eres honorable. Como te prometí, ¡aquí tienes tu recompensa!",
		},
		[8065] = {
			title = "Dechados de Poder: la guerrera de haruspex",
			accept = "El máximo símbolo del poder de un haruspex es su vestimenta, $n. En ella, la guerrera simboliza su conexión con la sabiduría divina que pretenden conseguir. Suele llevar entretejidas partes de las bestias que sacrifican, les recuerdan la conexión que tienen con sus dones.$B$BTráeme una ofrenda de los Dechados de Poder de Zul'Gurub y demuéstranos tu valía. Hazlo y será tuya una guerrera imbuida con el auténtico poder de un haruspex.",
			complete = "Impresionante... has conseguido reunir los Dechados de Poder que necesitábamos, $n. Las hazañas que has hecho por los Zandalar en Zul'Gurub son legendarias y por eso serás $gvenerado:venerada; por la tribu. ¡Aquí tienes tu túnica poderosa $c!",
		},
		[8066] = {
			title = "Dechados de Poder: el Cinturón de depredador",
			accept = "Un depredador sabe cómo acechar su presa, pero solo tiene éxito el que sabe darle muerte cuando ya se han acercado. Debes dominar las dos cosas para poder tener éxito en Zul'Gurub... y para tener una oportunidad de parecerte a los depredadores Zandalar.$B$BTráeme partes selectas de los Dechados de Poder de Zul'Gurub. Mi recompensa será el poder de los abalorios y tuyo será el Cinturón de depredador Zandalar... un equipamiento por el que merece la pena el intercambio.",
			complete = "Sentí tu llegada momentos antes, $n, pero no con demasiada facilidad. Lo que se me reveló a mí fueron los Dechados de Poder que trajiste. Puedo sentir el poder sin necesidad de ver los abalorios; su mojo latente, magia pura, por así decirlo, continuará alimentando nuestros esfuerzos por vencer los planes diabólicos del Dios de la Sangre Hakkar.$B$BDebes ser $gfelicitado:felicitada; y $grecompensado:recompensada; por tu éxito. Eres honorable entre la tribu y eres $gdigno:digna; de llevar el cinturón de depredador.",
		},
		[8067] = {
			title = "Dechados de Poder: el Manto de depredador",
			accept = "Nosotros, los Zandalar, valoramos nuestras vestimentas como símbolo de éxito. No necesitas ver lo que uno viste para poder sentir lo que emana de las vestimentas: el poder transciende la visión. Las prendas del depredador Zandalar son así, y la más valorada de todas es el manto. Ayuda a ocultarlos de la vista... y a hacer saber su presencia si lo desean.$B$BLos Dechados de Poder de Zul'Gurub esperan a que los recuperes. Tráeme lo que busco y el Manto de depredador Zandalar será tuyo.",
			complete = "Éxito... debes ser $gvenerado:venerada; entre la tribu, $n. No fue una hazaña pequeña adquirir los Dechados de Poder necesarios para el manto, pero lo manejaste a la manera del más letal de nuestros depredadores. Te has ganado tu lugar entre ellos y ciertamente te has ganado el derecho a usar su manto.",
		},
		[8068] = {
			title = "Dechados de Poder: el Manto de ilusionista",
			accept = "La magia es una fuerza primaria, básica, maleable por aquellos que son lo suficientemente fuertes para dominarla. El mojo es una extensión de este poder, y una de las potentes manipulaciones que se le pueden dar es en forma de ilusión. ¿Cómo puedes ganarle a un enemigo que ni siquiera es real? Los Zandalar conocemos este poder, y como ilusionistas tenemos un lugar en la tribu.$B$BObtén los Dechados de Poder de Zul'Gurub. La tribu te honrará y te regalará un poderoso manto de los que usan los mejores ilusionistas.",
			complete = "¡Éxito! ¡Serás $ghonrado:honrada; en la tribu de aquí en adelante! Sin duda, Zul'Gurub ha probado el poder de los Zandalar hoy, gracias a ti, $n.$B$BCon la bendición de la tribu, toma el manto del ilusionista Zandalar. Que te sirva bien.",
		},
		[8069] = {
			title = "Dechados de Poder: la Toga de ilusionista",
			accept = "Los miembros de la tribu reconocen la posición y el poder a través de sus vestimentas. Están hechas con los mejores materiales y entretejidas con el mojo que utilizamos para hacernos poderosos. Los ilusionistas no son una excepción, se dice que el aspecto de sus togas encarna la esencia de la ilusión. Las leyendas afirman que sus togas nunca tienen el mismo aspecto.$B$BTe daré una Toga de ilusionista, $n... pero antes debes convertirte en $gvenerado:venerada; de la tribu. ¡Tráeme los Dechados de Poder de Zul'Gurub!",
			complete = "¡Al fin, alguien $gdigno:digna; de llevar la túnica de ilusionista! Tu éxito en Zul'Gurub ha asegurado tu reverencia entre la tribu durante siglos. ¡Úselo con orgullo, $n!",
		},
		[8070] = {
			title = "Dechados de Poder: las Ataduras de confesor",
			accept = "Poco después de la caída de los Gurubashi, los Zandalar casi sucumbimos a una derrota final frente al mal dentro de nuestra propia tribu. Entonces surgieron de entre nosotros los confesores, defendiendo a la tribu desterrando a quienes destruirían a los suyos. No solo mantienen nuestra sintonía con los espíritus, también conservan la carne.$B$BAdéntrate en Zul'Gurub y presencia de primera mano la depravación de Hakkar y de los Gurubashi. Arrebátales los Dechados de Poder que buscamos y serás $grecompensado:recompensada;.",
			complete = "¡Éxito! Esto contribuirá en gran medida a fortalecer nuestro poder contra el ascenso de Hakkar. Con tu ayuda, hemos dado un paso importante para asegurarnos de que el Dios de la Sangre no nos destruirá a todos.$B$BHoy te has ganado el honor con la tribu, $n. Toma esto, las ataduras del confesor, como un símbolo de nuestro agradecimiento.",
		},
		[8071] = {
			title = "Dechados de Poder: el Manto de confesor",
			accept = "Los confesores de los Zandalar visten un manto distintivo que los identifica como valedores de la tribu. Esos mantos se elaboran con mojo potente que les ayuda a juzgar a los que amenazan a nuestra tribu. Como $gsacerdote:sacerdotisa; también dedicas tu tiempo a juzgar quién es digno y quién no. Un manto como este sería, sin duda, una bendición para alguien como tú.$B$BA cambio de combatir a los esbirros de Hakkar en Zul'Gurub y de traerme los Dechados de Poder que necesito te daré un manto digno de nuestros mejores confesores.",
			complete = "Bien hecho, $n... Hoy seguramente los esbirros de Hakkar han sentido la retribución de los Zandalar, y todo gracias a ti. Tus actos te han hecho $gmeritorio:meritoria; de nuestra veneración. Con tu bendición, acepta el manto de confesor como ofrenda.",
		},
		[8072] = {
			title = "Dechados de Poder: el Manto de sinconcierto",
			accept = "\"Uno de los sinconcierto legendarios de los Zandalar fue Khar'vaxal el Partido. Las leyendas dicen que cuando se enfrentó por primera vez a los enemigos de la tribu utilizó un manto elaborado con \"el tejido de la locura\". Su figura no solo estaba envuelta con el manto, sino también con la velocidad cegadora de sus dagas gemelas. Los sinconcierto adoran su manto como símbolo de su lugar en la tribu.$B$BTráeme los Dechados de Poder que busco y te daré un manto como ese, para envolver en la locura a tus enemigos.",
			complete = "¡La victoria es nuestra este día, gracias a la locura que has sembrado sobre nuestros enemigos mutuos! ¡Debes ser $ghonrado:honrada; entre los Zandalar, y no hay mejor manera de mostrar gratitud por tus actos que ofreciéndote el manto de sinconcierto!",
		},
		[8073] = {
			title = "Dechados de Poder: la guerrera de sinconcierto",
			accept = "Mis ojos dejaron de funcionar hace mucho tiempo, pero no los echo en falta. Incluso en una tribu como la nuestra (en la que las vestimentas definen la posición y propósitos de quienes las visten) la más poderosa de las vestimentas exuda un poder que los ojos no pueden ver. La preciada guerrera de sinconcierto Zandalar no es una excepción, exudando el poder en bruto del caos y de la locura que los sinconcierto pueden canalizar.$B$BLos Dechados de Poder que necesito se encuentran en Zul'Gurub, tráeme lo que busco y te recompensaré con tu propia guerrera legendaria... una adecuada para un tejedor de locura.",
			complete = "Impresionante... has logrado hoy lo que pocos pensaban que era posible. Tu reverencia en la tribu está asegurada para toda la vida, $n. Te has ganado el derecho a ponerte la túnica de sinconcierto; hazlo con nuestra bendición.",
		},
		[8074] = {
			title = "Dechados de Poder: el Cinturón de augur",
			accept = "Los augures conocen el mojo de los elementos, colega. Lo utilizan como un medio para llevar a la tribu hacia la gloria. En los días oscuros que siguieron al despedazamiento del Imperio Gurubashi, nuestros augures nos condujeron a nuestro refugio en los Mares del Sur. También nos condujeron de vuelta al Valle, al propio corazón del mal que ardía en Zul'Gurub.$B$BTráeme una ofrenda de los Dechados de Poder de Zul'Gurub y demuéstranos tu valía. Hazlo y te daré un cinturón de los que utilizan los augures, ¡con mojo potente en su interior!",
			complete = "Puedo oler el olor del mal vencido en ti, $n. Es un dulce olor colega... uno que creo que conoces bastante bien.$B$BSé que no es poca cosa haberme traído los Dechados de Poder necesarios para el cinturón. Tus obras no solo han honrado a la tribu, sino que también te has honrado a ti $gmismo:misma; entre la tribu. Aquí tienes: ¡toma el cinturón de augur y póntelo como si fuera tuyo!",
		},
		[8075] = {
			title = "Dechados de Poder: el Camisote de augur",
			accept = "Los augures de los Zandalar visten un camisote muy particular. Está confeccionado con la más alta calidad de seda y telas, entretejidas con fuertes anillas. No solo es un símbolo de su divinidad, sino también de su autoridad. No es muy sabio pelearse con una persona que dedica su vida a hablar con los espíritus...$B$BTráeme una muestra de los Dechados de Poder de los adentros de Zul'Gurub y demuéstranos tu valía. Si lo haces, te daré uno de esos camisotes que todo augur desea tener.",
			complete = "Sé por lo que tuviste que pasar para traerme los Dechados de Poder, $n. No fue fácil, colega, derrotar al mal que se filtra de Zul'Gurub como un lodo asqueroso, pero ahora que todo está dicho y hecho, puedo decir que serás $gvenerado:venerada; entre los Zandalar durante siglos.$B$B¡Toma, toma el Camisote de augur y úsalo con orgullo!",
		},
		[8076] = {
			title = "Dechados de Poder: el Manto de endemoniado",
			accept = "El endemoniado ansía encarnar el poder, no solo poseerlo. Más de uno de nuestros endemoniados ha perdido en la lucha con un demonio. Con nuestros enemigos amenazándonos, especialmente en Zul'Gurub, el poder que puede desatar un endemoniado merece el sacrificio. Nuestra supervivencia depende de la destrucción de los que nos destruirían a nosotros. La caída del Imperio Gurubashi nos lo enseñó.$B$BViaja a Zul'Gurub y obtén los Dechados de Poder que necesitamos. Hazlo y será tuyo un valioso objeto de endemoniado.",
			complete = "Bien hecho, $n. Los Dechados de Poder de Zul'Gurub deberían actuar como un recordatorio del poder desperdiciado. Los Gurubashi eran fuertes en su apogeo, pero se dejaron consumir por él. Un endemoniado sabe que el juego que juega es muy similar, pero el poder desatado es a menudo lo que se necesita para sobrevivir.$B$BUsa este manto como un aliado de honor de los Zandalar... te servirá bien.",
		},
		[8077] = {
			title = "Dechados de Poder: la Toga de endemoniado",
			accept = "El símbolo máximo de poder en la tribu es el atuendo que vestimos en batalla. La toga de un endemoniado funde el delicado paño rúnico y el devastador mojo potente en un único tejido. Se dice que el aspecto de la toga aterroriza a todo el que lo ve... Especialmente a los demonios que el endemoniado puede llegar a dominar.$B$BDe Zul'Gurub debes traerme un grupo determinado de Dechados de Poder. Será difícil... pero si tienes éxito obtendrás una toga.",
			complete = "Impresionante: tu victoria en Zul'Gurub nos ha asegurado, no, al mundo, que Hakkar no prevalecerá. Puede llegar el momento en que te enfrentes directamente al Dios de la Sangre... y si esto sucede, debes saber que tu reverencia está asegurada entre la tribu Zandalar.$B$BOh, y creo que esta sencilla toga también debería ayudar.$B$B<Al'tabim te guiña un ojo con complicidad.>",
		},
		[8078] = {
			title = ": el Cinturón de vindicador",
			accept = "La última venganza aguarda en Zul'Gurub. Hakkar no debe levantarse nunca más. Hakkar destruyó al Imperio Gurubashi desde su interior. No bastó ningún sacrificio. Los trols son una sombra de antiguas glorias. Y sé que es culpa de Hakkar.$B$BConviértete en el vindicador que debías ser. Siembra el caos entre los esbirros del mal. Zul'Gurub debe saborear la venganza de Zandalar. Tráeme una prueba con los Dechados de Poder. A cambio recibirás el Cinturón de vindicador. Recibirás auténtico poder.$B$BEn marcha.",
			complete = "Ya conoces las artes del vindicador. Has honrado a la tribu. Te has honrado a ti $gmismo:misma;. Has sembrado el horror entre tus enemigos.$B$BEl Cinturón de vindicador es tuyo. Algún día serás $guno:una; con las artes del vindicador.",
		},
		[8079] = {
			title = "Dechados de Poder: la coraza de vindicador",
			accept = "El símbolo de poder de un vindicador es su coraza. Está forjado con mojo potente. Solo es entregado a los que son nuestros venerados. Es el símbolo Zandalar de la venganza.$B$BConvertirte en vindicador es convertirte en venganza. Coge los Dechados de Poder que necesitamos de Zul'Gurub. Tráenoslos. Recuperaremos el mojo que nos robaron. Haremos que los esbirros de Hakkar lo paguen caro. Te recompensaremos con la coraza de vindicador Zandalar.$B$BEn marcha. Sé nuestra venganza, $n.",
			complete = "Debes ser $greverenciado:reverenciada; por tus actos. La tribu premia a sus $ghéroes:heroínas;. Zul'Gurub ha probado la venganza de Zandalar como nunca antes.$B$BTus actos anunciarán los de otros por venir. Te verán como un signo de poder real. ¡Te verán como la venganza personificada!",
		},
		[8080] = {
			title = "Los recursos de la Cuenca de Arathi",
			accept = "Hacen falta soldados para combatir en una guerra, cualquier soldado te lo dirá. También dicen que una guerra librada con equipamiento en malas condiciones o con el estómago vacío ¡está perdida antes de empezar!$B$BPor eso la Cuenca de Arathi es importante. Hay zonas clave en la cuenca donde se encuentran recursos esenciales. Metales, armas, comida, madera... todo lo que necesitamos, y todo se puede conseguir allí.$B$BEso es lo que quiero de ti, $n. Adéntrate en la Cuenca de Arathi, consigue la victoria tomando posesión de más bases que el enemigo y vuelve aquí con una caja de recursos.",
			complete = "¡Tienes los suministros! ¡Gran trabajo! Enviaré los recursos a nuestros intendentes, que pueden distribuirlos rápidamente entre nuestras tropas.$B$BGracias, $n. De hecho, realizar misiones exitosas como la que has logrado es la forma en que realmente se ganan las guerras.",
		},
		[8081] = {
			title = "Más cajas de suministros",
			complete = "Muy bueno. Se los llevaré a nuestros intendentes de inmediato, y se enviará un elogio por tus acciones a mis superiores.$B$BUna vez más, gracias $n. Desde el soldado al mariscal de campo, todos notan tus contribuciones a nuestra lucha.",
		},
		[8101] = {
			title = "El guijarro de Kajaro",
			complete = "$r, el guijarro que se encuentra en del marco de este talismán proviene del Monte Kajaro en los Mares del Sur. El monte Kajaro es un área plagada de volatilidad, marcada por erupciones volcánicas violentas y, a menudo, mágicas.$B$BA medida que crece tu vínculo con los trols de Zandalar, también lo hará el poder de este guijarro. Aprovecha el poder del guijarro para derrotar a nuestros enemigos. Sé como la montaña: $gRápido, explosivo:Rápida, explosiva;, mortal...",
		},
		[8102] = {
			title = "El guijarro de Kajaro",
			complete = "Sé imparable, como los frentes fundidos de Kajaro.",
		},
		[8103] = {
			title = "El guijarro de Kajaro",
			complete = "Continúa diezmando a los trols de Zul'Gurub. Debemos asegurarnos que el mundo no se doblegue ante la indomable voluntad de Hakkar.",
		},
		[8104] = {
			title = "La Joya de Kajaro",
			complete = "<Al'tabim rompe el guijarro con una poderosa fuerza invisible>.$B$B¿Lo ves? El guijarro es lo que llamamos geoda. Dentro del guijarro hay cristales poderosos que se han empapado de las energías latentes de nuestro mundo. Al cortar el guijarro por la mitad, finalmente he permitido que se desarrolle todo su potencial. Úselo para arrasar con nuestros enemigos.",
		},
		[8105] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "$n, la batalla por la Cuenca de Arathi se libra por los recursos y el territorio. Hay que mantener y dirigir los puntos clave de esa región para que nuestras fuerzas tengan asegurado el suministro de materias primas. Te encargo que asaltes los puntos más alejados de nuestra base en la Cuenca de Arathi.$B$BAsalta la granja, la mina, el aserradero y la herrería cuando estén en poder del enemigo. Encuentra el estandarte enemigo ¡y arráncalo del poste donde ondee!$B$BCuando lo hayas hecho en las cuatro posiciones vuelve aquí.",
			complete = "He recibido informes de tus hazañas en La Cuenca de Arathi, $n. ¡Bien hecho! Con otros como tú uniéndose a la lucha, tengo fe en que algún día recuperaremos nuestra tierra natal.",
		},
		[8106] = {
			title = "Ocaso de Kezan",
			complete = "Acepta este talismán, $c. Acéptalo y usa su poder para derrotar a nuestros enemigos mutuos.$B$BAlrededor de tu cuello llevas un pedazo de historia. Kezan fue una vez un gran territorio del Imperio Zandalar. Por desgracia, la mancha de los príncipes mercantes goblin expulsaría a mis orgullosos hermanos y hermanas.$B$BKezan es ahora el hogar de la capital goblin de Minahonda; pero debes saber que antes de la mancha, tenía grandeza. Aún hasta el día de hoy, Kezan se considera tierra sagrada para mi pueblo.",
		},
		[8107] = {
			title = "Ocaso de Kezan",
			complete = "Ven a la oscuridad, $c. Abraza las sombras. Deja que la Mancha de Kezan complete tu llegada en la oscuridad.",
		},
		[8108] = {
			title = "Ocaso de Kezan",
			complete = "Es solo a través de nuestros esfuerzos combinados que detendremos al Rompealmas.",
		},
		[8109] = {
			title = "Mancha imparable de Kezan",
			complete = "Arranca la carne de sus cadáveres. Observa cómo las sombras consumen al Hakkari. Saca poder de su miedo, $c. Deja que la Mancha de Kezan aumente este poder...",
		},
		[8110] = {
			title = "Algas de los Mares del Sur encantadas",
			complete = "¿Ves estas algas de aquí, colega? Es de los mares del sur. Solo le agregamos un poco de mojo y un poco de magia y adquiere las propiedades más adecuadas para su dueño.$B$BEres $gun:una; $c, así que será fácil, colega. Simplemente lialo alrededor de tu cuello y piensa en la naturaleza o las ardillas o lo que sea que le guste a la gente.",
		},
		[8111] = {
			title = "Algas de los Mares del Sur encantadas",
			complete = "¡La pieza del cuello no es para fumar, colega! Tienes que usarlo para luchar contra el mal.",
		},
		[8112] = {
			title = "Algas de los Mares del Sur encantadas",
			complete = "¡Ahora coge a los trols malvados de Zul'Gurub y enséñales lo que pueden hacer tus poderes naturales, colega!",
		},
		[8113] = {
			title = "Algas de los Mares del Sur encantadas prístinas",
			complete = "$n colega, ha sido un buen viaje. Continúa matando y eliminando a Hakkar y sus secuaces.",
		},
		[8114] = {
			title = "Controla cuatro bases",
			accept = "$n, has librado la batalla de la Cuenca de Arathi frente a nuestros enemigos y te has ganado grandes honores en ese campo de batalla. Nos has demostrado cuánto vales como $c ¡y les has dejado claro a nuestros enemigos que no nos someteremos a su tiranía!$B$BPor esos valores demostrados, tengo una tarea compleja para ti. Quiero que tomes cuatro de las bases de la Cuenca de Arathi y mantengas esas posiciones. Si lo logras, no solo aseguraremos recursos críticos, sino que ¡les mostraremos a la Horda quién domina!$B$BMárchate, $n, y que la Fortuna te sea favorable.",
			complete = "¡Muy buen trabajo, $n! Un explorador emocionado se acercó a mí con un informe de tus hazañas. ¡En la Liga de Arathor estamos muy contentos!$B$BRápidamente te estás convirtiendo en $gun héroe:una heroína; local entre los soldados de la Liga, y la hazaña de hoy demuestra una vez más tu excelente reputación.",
		},
		[8115] = {
			title = "Controla cinco bases",
			accept = "$n, en la batalla por los recursos de la Cuenca de Arathi se derramará mucha sangre. Tus servicios a la Liga de Arathor son tan necesarios como apreciados.$B$BTengo otra tarea para ti.$B$BLa Liga desea que des un golpe contundente contra la ocupación de los Rapiñadores de la Cuenca de Arathi. ¡No conseguimos expulsarlos de los puntos estratégicos del campo de batalla!$B$BNo será fácil, pero si alguien puede hacerlo, eres tú.",
			complete = "¡Lo hiciste! ¡Te llevaste todas las bases! ¡Bien hecho, $n!$B$BHabía quienes dudaban de tus posibilidades, pero sabía que podías hacerlo. Gracias, y debes saber que la Liga de Arathor te tiene en alta estima, al igual que los Rapiñadores de los Renegados deben temer la sola mención de tu nombre.",
		},
		[8116] = {
			title = "Visión de Voodress",
			complete = "Tú y Maywiki tenéis algo en común, colega. ¡Los dos seremos $c! Aunque, Maywiki es más un místico y tú eres más un matorral. Aún así, ambos sabemos lo que traen los grandes espíritus.$B$BComo regalo te doy este orbe para que lo lleves alrededor del cuello. ¡Mira dentro y ve el pueblo de Voodress en los mares del sur! ¡Deja que te levante el ánimo!",
		},
		[8117] = {
			title = "Visión de Voodress",
			complete = "Cuidado con los espíritus malignos de Hakkari, colega. Honestamente, son espeluznantes.",
		},
		[8118] = {
			title = "Visión de Voodress",
			complete = "Échale un vistazo ahora, $n. Voodress entra aún más claro ahora, ¿sí? Deja que el poder primordial fluya a través de ti, colega.",
		},
		[8119] = {
			title = "Visión inmaculada de Voodress",
			complete = "Un día, $n, podrás usar este orbe para comunicarte directamente conmigo. Siempre que esta batalla con Hakkar termine y Maywiki se vaya a casa. Llamemos a los espíritus y pidamos que ese día llegue pronto.",
		},
		[8120] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "Como sin duda habrás oído, la Liga de Arathor está enviando un gran número de soldados a la Cuenca de Arathi. Ansiosos por conseguir comida y suministros, estos necios de la Alianza intentarán controlar los abundantes recursos de esa región. Debemos enseñarles que Arathi ¡nunca volverá a ser un hogar de humanos!$B$BVe a la Cuenca de Arathi y asalta la mina, el aserradero, la herrería y el establo. Arría los estandartes enemigos y declara esos territorios dominio de la Horda.$B$BVe, $n. Vuelve para informarme cuando hayas completado esta tarea.",
			complete = "Un explorador de los Rapiñadores vino a mí con un informe de tu éxito, $n. Bien hecho.$B$BComo aprenderás, para ganar la batalla por la Cuenca de Arathi, debemos estar siempre atentos y aplastar cualquier intento de expansión de la Alianza. Haz esto, y nuestra victoria aquí está asegurada.",
		},
		[8121] = {
			title = "Toma el control de cuatro bases",
			accept = "$n, con el recrudecimiento de las hostilidades en la Cuenca de Arathi, muchos han oído hablar de tus hazañas. Te tenemos en la más alta estima, por lo que confío en que podrás cumplir la misión que tengo para ti.$B$BEs hora de mandar un mensaje a la Liga de Arathor. Debemos demostrarles que sus posiciones en la Cuenca de Arathi son endebles y que las perderán rápidamente. Se lo demostraremos capturando, de una sola vez, cuatro puntos estratégicos de la Cuenca de Arathi.$B$BLogra este objetivo, $n, y te granjearás el mayor de los respetos entre los Rapiñadores.",
			complete = "¡Buen trabajo, $n! Tus últimas acciones en la Cuenca de Arathi fueron bastante difíciles, por lo que tus éxitos son dignos de elogio. La Liga de Arathor debe estar recuperándose de las últimas escaramuzas en la cuenca, lamiendo sus heridas y, esperemos, reconsiderando su decisión de luchar aquí.",
		},
		[8122] = {
			title = "Toma el control de cinco bases",
			accept = "Cuesta verlo, de lo inmersos que estamos en el conflicto, pero nuestros espías informan de un debilitamiento en la determinación de la Liga de Arathor. ¡Debemos aprovechar esa grieta para asestarles un golpe definitivo! Vuelve a la Cuenca de Arathi y lánzate contra nuestros enemigos. ¡Maldícelos, mátalos y toma el control de las cinco bases estratégicas! Haz que sus soldados salgan despavoridos y desangrándose del frente, con relatos sobre tu crueldad que contarán entre sollozos.$B$BHazlo y apúntales una gran victoria a los Rapiñadores.",
			complete = "Los gritos de la Alianza mientras tú y tus compatriotas los atacaban se podían escuchar incluso desde aquí, $n. Casi puedo sentir lástima de ellos por el dolor y el miedo que le has causado a sus filas. Casi, pero no del todo.$B$BTu valor para los Rapiñadores es indudable. Tus hazañas en la Cuenca de Arathi han sido de lo más impresionantes y han resonado entre las cámaras de Varimathras... y la misma Dama Oscura.",
		},
		[8123] = {
			title = "Córtale el suministro a la Liga de Arathor",
			accept = "La Liga de Arathor no repara en gastos en su avance para recuperar Arathi. Ellos, y todas las razas de la Alianza, se dirigen ahora hacia esa distante región con la intención de extender su dominio desde el Refugio de la Zaga. Debemos detenerlos y la mejor manera es arrebatarles los suministros.$B$BPuedes ayudarnos, $n. Adéntrate en la Cuenca de Arathi, famosa por sus abundantes minas, fértiles tierras y los más finos artesanos. Captura y hazte con el control de todas las bases que puedas, gana la batalla y vuelve con los recursos que hayas obtenido.",
		},
		[8124] = {
			title = "Más cajas de suministros",
			complete = "Muy bueno. Se los llevaré a nuestros intendentes de inmediato, y se enviará un elogio por tus acciones a mis superiores.$B$BUna vez más, gracias $n. Desde el bruto al Alto señor de la Guerra, todos notan tus contribuciones a nuestra lucha.",
		},
		[8141] = {
			title = "Dije Zandalar de las Sombras",
			complete = "Avanzas rápidamente, joven $c. Quizás sea el momento de iniciarte en el Shera Ali'kh - Zandalari de la Mano de la Muerte. Durante miles de años hemos desempeñado el papel de asesinos del Imperio Zandalar. Durante demasiado tiempo nos hemos sentado de brazos cruzados, permitiendo que el Hakkari crezca en fuerza. Una vez más nos enfrentamos a Hakkar, pero esta vez sin el apoyo de un frente $r unido. ¡Eres tu y tus aliados quienes deben ayudar a vencer al Dios de la Sangre y sus secuaces!$B$BUsa este talismán y deja que te ayude en tus viajes.",
		},
		[8142] = {
			title = "Dije Zandalar de las Sombras",
			complete = "Solo queda una mejora que se puede colocar en el talismán, $c. Cuando sea el momento adecuado, aplicaré esa mejora.",
		},
		[8143] = {
			title = "Dije Zandalar de las Sombras",
			complete = "$gUn asesino:Una asesina; de tu calibre debería tener un amplio margen. ¡Tus enemigos deben aprender a respetar! Obtendrás exactamente eso cuando el enemigo vea el destello de la Mano de la Muerte, y sea demasiado tarde...",
		},
		[8144] = {
			title = "Dije Zandalar de maestría de las Sombras",
			complete = "Esta es la última vez que hablaremos bajo los auspicios de Shera Ali'kh. Sabes todo lo que debes. Toma el talismán y continúa matando. No se debe permitir que Hakkar abandone Zul'Gurub.",
		},
		[8145] = {
			title = "Zarcillo de La Vorágine",
			complete = "Entre los Zandalar, la profesión de $c es venerada. Nuestros mejores cazadores viajan al borde de la Vorágine para demostrar su resolución.$B$BDel corazón del mar extraen hebras de algas conocidas como Zarcillos de La Vorágine. Luego, las algas marinas se tejen en un talismán que está encantado para mejorar su precisión y poder.$B$BAhora te concedo un solo tejido del Zarcillo de La Vorágine. A medida que crezca tu vínculo con Zandalar, tejeré más poder en el talismán.",
		},
		[8146] = {
			title = "Zarcillo de La Vorágine",
			complete = "Solo hay un tejido más que podré agregar a tu talismán, $c",
		},
		[8147] = {
			title = "Zarcillo de La Vorágine",
			complete = "Que busquen expiación al final de tus municiones.",
		},
		[8148] = {
			title = "Cólera de La Vorágine",
			complete = "Tu viaje apenas ha comenzado, joven $c. Quizás algún día visites la Vorágine y eches un vistazo al corazón del mundo.$B$B¡Te deseo poder y fortaleza!",
		},
		[8149] = {
			title = "En honor a un héroe",
			accept = "Durante el Festival de la Cosecha de Azeroth, agradecemos a los héroes todos los sacrificios, a veces máximos, que han hecho por nosotros. La Alianza muestra su gratitud y reconocimiento a muchos héroes, pero ninguno tiene una historia más trágica que Uther el Iluminado.$B$BAyúdanos a honrar a Uther llevando esta ofrenda a su tumba, en las Tierras de la Peste del Oeste. Colócala en su estatua y luego vuelve a verme. Solo estaré aquí hasta que termine el festival, así que no pierdas tiempo en darle a Uther su tributo.",
			complete = "Era un héroe de héroes, el gran Uther. No puedo ni imaginar la angustia que sintió cuando Arthas, su mejor alumno y alguien a quien Uther amaba como a su propio hijo, traicionó a toda la humanidad. Aun así intentó detener a Arthas y por ello siempre será recordado como un auténtico paladín. Luchó hasta el final, pensando solo en aquellos a los que podría salvar.$B$BGracias, $n. Hoy has prestado tributo a un gran héroe, honrando su espíritu y el espíritu del Festival de la Cosecha.",
		},
		[8150] = {
			title = "En honor a un héroe",
			accept = "Durante el Festival de la Cosecha de Azeroth, agradecemos a los héroes todos los sacrificios, a veces máximos, que han hecho por nosotros. La Horda muestra su gratitud y reconocimiento a muchos héroes, pero no hay mejor ejemplo de fuerza y sacrificio que Grom Grito Infernal.$B$BAyúdanos a honrar a Grom llevando esta ofrenda a su monumento en el Barranco del Demonio de Vallefresno. Colócala en la base y luego vuelve a verme. Solo estaré aquí hasta que termine el festival, así que no pierdas tiempo en darle a Grom su tributo.",
			complete = "El nombre completo de Grom, Grommash, significa \"El corazón de gigante\"; necesitó eso y algo más para enfrentarse solo a Mannoroth. Creo que el Jefe de Guerra lo expresó mejor: la maldición de los orcos comenzó y terminó con Grom. Es apropiado que el sacrificio (y tal vez la redención) de Grom sea la fuente de la que fluye hoy la Horda.$B$BGracias, $n. Hoy has prestado tributo a un gran héroe, honrando su espíritu y el espíritu del Festival de la Cosecha.",
		},
		[8151] = {
			title = "El talismán del cazador",
			accept = "Ogtinc de Azshara ha hecho un llamamiento buscando cazadores avezados como tú. Es un cazador fúrbolg que abandonó su tribu para ayudar al Círculo Cenarion. Sus enseñanzas pretenden enriquecer la sabiduría de los que comparten su arte y guiarlos en la conservación del equilibrio. Harás bien en hablar con él.$B$BOgtinc reside en la cumbre de los precipicios de Azshara, al noreste de las Ruinas de Eldarath.",
			complete = "Ya no es mi propósito cazar, sino enseñar $gal:a la; $n. Eso es lo que me ha entregado el destino.$B$BCrea conmigo un amuleto de $n: una colección de trofeos de presas caídas que te recordarán tus pruebas y triunfos pasados. Al final me quedaré con lo encantado, pero te recompensaré con algo más.",
		},
		[8153] = {
			title = "Cornamenta de trotador",
			accept = "El trotador porta la cornamenta más potente de toda tierra conocida. La usa para defenderse, corneando a sus atacantes y a menudo dañando los extremos. Perfecto, una cornamenta natural es un signo de un espíritu animal con una seguridad absoluta.$B$BResistir a tal cornamenta requerirá la misma seguridad en ti mismo.$B$BCaza al trotador Pezuñamusgo, encuentra la cornamenta perfecta y tráemela.",
			complete = "Debes poseer una vista aguda y una gran paciencia para haberlos obtenido. Bien hecho.",
		},
		[8154] = {
			title = "Los recursos de la Cuenca de Arathi",
			accept = "Hacen falta soldados para combatir en una guerra, cualquier soldado te lo dirá. También dicen que una guerra librada con equipamiento en malas condiciones o con el estómago vacío ¡está perdida antes de empezar!$B$BPor eso la Cuenca de Arathi es importante. Hay zonas clave en la cuenca donde se encuentran recursos esenciales. Metales, armas, comida, madera... todo lo que necesitamos, y todo se puede conseguir allí.$B$BEso es lo que quiero de ti, $n. Adéntrate en la Cuenca de Arathi, consigue la victoria tomando posesión de más bases que el enemigo y vuelve aquí con una caja de recursos.",
			complete = "¡Tienes los suministros! ¡Gran trabajo! Enviaré los recursos a nuestros intendentes, que pueden distribuirlos rápidamente entre nuestras tropas.$B$BGracias, $n. De hecho, realizar misiones exitosas como la que has logrado es la forma en que realmente se ganan las guerras.",
		},
		[8155] = {
			title = "Los recursos de la Cuenca de Arathi",
