		},
		[8166] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "$n, la batalla por la Cuenca de Arathi se libra por los recursos y el territorio. Hay que mantener y dirigir los puntos clave de esa región para que nuestras fuerzas tengan asegurado el suministro de materias primas. Te encargo que asaltes los puntos más alejados de nuestra base en la Cuenca de Arathi.$B$BAsalta la granja, la mina, el aserradero y la herrería cuando estén en poder del enemigo. Encuentra el estandarte enemigo ¡y arráncalo del poste donde ondee!$B$BCuando lo hayas hecho en las cuatro posiciones vuelve aquí.",
			complete = "He recibido informes de tus hazañas en La Cuenca de Arathi, $n. ¡Bien hecho! Con otros como tú uniéndose a la lucha, tengo fe en que algún día recuperaremos nuestra tierra natal.",
		},
		[8167] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "$n, la batalla por la Cuenca de Arathi se libra por los recursos y el territorio. Hay que mantener y dirigir los puntos clave de esa región para que nuestras fuerzas tengan asegurado el suministro de materias primas. Te encargo que asaltes los puntos más alejados de nuestra base en la Cuenca de Arathi.$B$BAsalta la granja, la mina, el aserradero y la herrería cuando estén en poder del enemigo. Encuentra el estandarte enemigo ¡y arráncalo del poste donde ondee!$B$BCuando lo hayas hecho en las cuatro posiciones vuelve aquí.",
			complete = "He recibido informes de tus hazañas en La Cuenca de Arathi, $n. ¡Bien hecho! Con otros como tú uniéndose a la lucha, tengo fe en que algún día recuperaremos nuestra tierra natal.",
		},
		[8168] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "$n, la batalla por la Cuenca de Arathi se libra por los recursos y el territorio. Hay que mantener y dirigir los puntos clave de esa región para que nuestras fuerzas tengan asegurado el suministro de materias primas. Te encargo que asaltes los puntos más alejados de nuestra base en la Cuenca de Arathi.$B$BAsalta la granja, la mina, el aserradero y la herrería cuando estén en poder del enemigo. Encuentra el estandarte enemigo ¡y arráncalo del poste donde ondee!$B$BCuando lo hayas hecho en las cuatro posiciones vuelve aquí.",
			complete = "He recibido informes de tus hazañas en La Cuenca de Arathi, $n. ¡Bien hecho! Con otros como tú uniéndose a la lucha, tengo fe en que algún día recuperaremos nuestra tierra natal.",
		},
		[8169] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "Como sin duda habrás oído, la Liga de Arathor está enviando un gran número de soldados a la Cuenca de Arathi. Ansiosos por conseguir comida y suministros, estos necios de la Alianza intentarán controlar los abundantes recursos de esa región. Debemos enseñarles que Arathi ¡nunca volverá a ser un hogar de humanos!$B$BVe a la Cuenca de Arathi y asalta la mina, el aserradero, la herrería y el establo. Arría los estandartes enemigos y declara esos territorios dominio de la Horda.$B$BVe, $n. Vuelve para informarme cuando hayas completado esta tarea.",
			complete = "Un explorador de los Rapiñadores vino a mí con un informe de tu éxito, $n. Bien hecho.$B$BComo aprenderás, para ganar la batalla por la Cuenca de Arathi, debemos estar siempre atentos y aplastar cualquier intento de expansión de la Alianza. Haz esto, y nuestra victoria aquí está asegurada.",
		},
		[8170] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "Como sin duda habrás oído, la Liga de Arathor está enviando un gran número de soldados a la Cuenca de Arathi. Ansiosos por conseguir comida y suministros, estos necios de la Alianza intentarán controlar los abundantes recursos de esa región. Debemos enseñarles que Arathi ¡nunca volverá a ser un hogar de humanos!$B$BVe a la Cuenca de Arathi y asalta la mina, el aserradero, la herrería y el establo. Arría los estandartes enemigos y declara esos territorios dominio de la Horda.$B$BVe, $n. Vuelve para informarme cuando hayas completado esta tarea.",
			complete = "Un explorador de los Rapiñadores vino a mí con un informe de tu éxito, $n. Bien hecho.$B$BComo aprenderás, para ganar la batalla por la Cuenca de Arathi, debemos estar siempre atentos y aplastar cualquier intento de expansión de la Alianza. Haz esto, y nuestra victoria aquí está asegurada.",
		},
		[8171] = {
			title = "La batalla por la Cuenca de Arathi",
			accept = "Como sin duda habrás oído, la Liga de Arathor está enviando un gran número de soldados a la Cuenca de Arathi. Ansiosos por conseguir comida y suministros, estos necios de la Alianza intentarán controlar los abundantes recursos de esa región. Debemos enseñarles que Arathi ¡nunca volverá a ser un hogar de humanos!$B$BVe a la Cuenca de Arathi y asalta la mina, el aserradero, la herrería y el establo. Arría los estandartes enemigos y declara esos territorios dominio de la Horda.$B$BVe, $n. Vuelve para informarme cuando hayas completado esta tarea.",
			complete = "Un explorador de los Rapiñadores vino a mí con un informe de tu éxito, $n. Bien hecho.$B$BComo aprenderás, para ganar la batalla por la Cuenca de Arathi, debemos estar siempre atentos y aplastar cualquier intento de expansión de la Alianza. Haz esto, y nuestra victoria aquí está asegurada.",
		},
		[8181] = {
			title = "La confrontación con Yeh'kinya",
			accept = "Mi exhaustivo estudio de las Tablillas Mosh'aru revela resultados desalentadores, $n. La verdadera forma de Hakkar, el dios en sí mismo, puede volver a nacer a través del huevo en el que lo has encerrado. Yeh'kinya te dijo que el huevo se utilizaba para encerrar el mal, ¡pero en realidad es para crearlo de nuevo! ¡El trol te ha engañado!$B$BVe a ver a Yeh'kinya y pídele el huevo. ¡Reza para que no sea demasiado tarde para detener el regreso de Hakkar!",
			complete = "Entonces, has estado hablando con ese viejo enano Ferrobota y has descubierto las Tablillas Mosh'aru perdidas, ¿verdad? Ese buscador entrometido...$B$BNo importa. Es demasiado tarde para salvar este mundo. Hakkar ha renacido, e incluso ahora crece en poder... ¡en lo profundo del antiguo reino trol de Zul'Gurub! ¡Él ha venido! ¡Y gobernará con sangre y terror!$B$BGracias, $n. ¡Tu ayuda ha acelerado el regreso del Cazador de Almas!",
		},
		[8182] = {
			title = "La mano de Rastakhan",
			accept = "$n, se han cumplido nuestros peores temores. La leyenda cuenta que el Cazador de Almas, cuyo poder es absoluto, gobernará el antiguo mundo trol, instaurando un régimen de terror y maldad. ¡Si no lo impedimos su nuevo reino se extenderá por todo Azeroth!$B$BHay un contingente de trols Zandalar que podría ayudarnos a contener el avance de las tinieblas. Están acampados en la Isla Yojamba, a poca distancia de la costa de Tuercespina, al oeste de las ruinas de Zul'Kunda. Habla con su jefe, Molthor, y reza para que él sepa cómo combatir a Hakkar.",
			complete = "¿Fuiste enviado por el Prospector Ferrobota? Los de su clase son sabios, y más sabios aún para traerte a mí, porque yo y los trols Zandalari podemos conocer la forma de derrotar al Cazador de Almas.$B$BHabla con los trols de esta isla, presta atención a sus palabras y prepárate, $n, para la tarea que tienes ante ti $gempapado:empapada; en sangre.",
		},
		[8183] = {
			title = "El corazón de Hakkar",
			accept = "El corazón de Hakkar arde desde su interior. Aunque el Cazador de Almas ha sido derrotado, la semilla de su poder sigue en este órgano maldito.",
			complete = "Ah, el corazón de Hakkar. ¡Así que el Cazador de Almas ha sido asesinado! ¡Nuestro mundo está salvado!$B$B$n, tu servicio para nosotros no puede ser exagerado. ¡Realmente eres $gun héroe:una heroína; de este reino!",
		},
		[8184] = {
			title = "Presencia de poderío",
			complete = "Úsalo bien, $n. ¡No muestres piedad al Hakkari!",
		},
