		[8271] = {
			title = "Héroe Pico Tormenta",
			complete = "Como $ghéroe:heroína; de los Pico Tormenta, puedes elegir uno de los objetos del tesoro recientemente saqu... ejem, recuperado.",
		},
		[8272] = {
			title = "Héroe de Lobo Gélido",
			complete = "¿Qué se siente, $n? ¿Qué se siente al aplastar a los enemigos y ver cómo sus líneas se diseminan? Sienta bien, ¿eh?$B$BSe te recompensará por este acto heroico, soldado.",
		},
		[8273] = {
			title = "La gratitud Oran",
			complete = "¿No te parece interesante? ¿Y dices que encontraste esta tablilla en una pequeña isla desierta en Los Acantilados Dominantes de las Tierras del Interior, $c? En verdad resulta interesante. $B$BTe agradezco tus esfuerzos. Nuestra Dama Oscura se alegrará mucho con este hallazgo. Aquí tienes una recompensa a la altura.",
		},
		[8275] = {
			title = "La reconquista de Silithus",
			accept = "¡Atención, héroes de la Alianza! Llevamos mucho tiempo sin comprobar la amenaza de los silítidos. Libres de las restricciones de una oposición real, llevan todo este tiempo preparándose para una expansión a gran escala.$B$BLas tropas del Círculo Cenarion se están reuniendo en Silithus para enfrentarse a esas malvadas criaturas. ¡Todos los aventureros que no estén heridos deben unirse a nosotros!$B$B¡No esperen hasta que sea demasiado tarde! ¡Ayúdennos a defender Azeroth! ¡Preséntense a Clamavientos Cuerno Digno en el Fuerte Cenarion para recibir instrucciones específicas!",
			complete = "Excelente, $gun nuevo:una nueva; recluta respondiendo a la llamada a las armas contra el silítido. $gBienvenido:Birenvenida; a Fuerte Cenarion, $n. Me complace ver que las palabras de nuestros emisarios están llegando a $ghéroes:heroínas; de tu calibre. No encontrarás escasez de oportunidades para ayudarnos en nuestros esfuerzos aquí y espero que pronto demuestres ser $gun valioso aliado:una valiosa aliada; para nuestra causa.",
		},
		[8276] = {
			title = "La reconquista de Silithus",
			accept = "¡Atención, campeones de la Horda! Hay una amenaza que llevamos mucho tiempo sin atender. Los temblores de la tierra cerca de las colmenas de silítidos por todo Azeroth, nos han alertado de grandes movimientos en sus números. Se preparan para la expansión.$B$BLas tropas del Círculo Cenarion se están reuniendo en Silithus para atacar a los silítidos antes de que sea demasiado tarde. ¡Nunca más profanarán nuestras tierras!$B$B¡Todos los combatientes que estén en buena forma tienen que presentarse ante Clamavientos Cuerno Digno en el Fuerte Cenarion! ¡Será el fin de los silítidos!",
			complete = "Excelente, $gun nuevo:una nueva; recluta respondiendo a la llamada a las armas contra el silítido. $gBienvenido:Birenvenida; a Fuerte Cenarion, $n. Me complace ver que las palabras de nuestros emisarios están llegando a $ghéroes:heroínas; de tu calibre. No encontrarás escasez de oportunidades para ayudarnos en nuestros esfuerzos aquí y espero que pronto demuestres ser $gun valioso aliado:una valiosa aliada; para nuestra causa.",
		},
		[8277] = {
			title = "Veneno mortal del desierto",
			accept = "¡Beetix Castañeta a tu servicio! Mi primo Noggle se dedica a buscar hierbas exóticas para los alquimistas del Fuerte Cenarion. O, al menos, solía dedicarse a eso. Volvió de su último viaje con un fuerte veneno corriendo por sus venas.$B$BHe conseguido ralentizar el veneno, pero para neutralizarlo completamente, necesito muestras del veneno de lo que fuera que le picó.$B$BNoggle vino del norte, así que me apuesto la camisa a que fue un escórpido Latipiedra o un arácnido de arena. Tráeme algún aguijón y colmillos e intentaré preparar un antídoto para él.",
			complete = "¡Cruza los dedos! ¡Esperemos que podamos salvar a Noggle!",
		},
		[8278] = {
			title = "La última esperanza de Noggle",
			accept = "¡Maldita sea! El antídoto no ha funcionado. Noggle debe de haber sido atacado por una de las criaturas más fuertes del sur.$B$BNecesito que vayas allí y me traigas más muestras, $N. La buena noticia es que como su veneno es más fuerte, no necesitaré tantas. La mala, es que hay más tipos de criaturas venenosas reptando por la zona del sur, así que tendrás que sacar las muestras de más fuentes.",
			complete = "¡Sí! Parece que funciona, Noggle se está despertando. ¡Te lo agradezco un montón!",
		},
		[8279] = {
			title = "El Lexicón Crepuscular",
			accept = "Los Martillo Crepuscular no son muy amables que digamos con aquellos que dejan sus filas. Me han intentado atrapar todos los días como si fuera una bestia. No hace falta decir que, cualquier enemigo suyo es amigo mío.$B$BPara descifrar esta tablilla necesitaré el libro utilizado por sus escribas para encriptar los mensajes secretos: el Lexicón Crepuscular. Es una herramienta tan importante que guardan los tres capítulos en ubicaciones diferentes. Los oficiales encargados de proteger el Lexicón son conocidos como los Guardianes Crepusculares. Búscalos en los campamentos del Martillo Crepuscular.",
			complete = "¡Sí! ¡Tienes las partes del libro! Comencemos, $n.$B$BCambia cada tercera palabra por palabras del segundo capítulo... y después cambia una palabra sí y otra no por palabras del primer capítulo... Espera, ¿he dicho eso al revés?",
		},
		[8280] = {
			title = "Asegurar las rutas de suministros",
			accept = "El Fuerte Cenarion es una ubicación de importancia estratégica crítica. Sé que, mientras lo mantengamos, nuestra victoria sobre los silítidos estará asegurada. Siempre y cuando podamos mantener la llegada de suministros, claro está.$B$BLos gusanos del desierto han demostrado ser una amenaza mucho mayor para nuestras caravanas de suministros, que los mismísimos silítidos. Justo esta mañana, un gran cargamento de mañagrana fue robado por un grupo de golpeadores deslizantes. Necesito que disminuyas sus números para asegurarnos de que nuestros suministros no corren peligro.",
			complete = "Tienes mi más sincera gratitud. Tus esfuerzos para ayudar al Fuerte Cenarion han demostrado tu valentía.",
		},
		[8281] = {
			title = "Intensificar la seguridad",
			accept = "Hasta ahora, tu comportamiento ha sido realmente ejemplar, $N. Sin embargo, nuestras líneas de suministros todavía no están completamente a salvo. En ausencia de golpeadores deslizantes, sus parientes más grandes del sur, se desplazarán para ocupar su lugar en el norte.$B$BTendrás que matar a bastantes trituradores deslizantes para mantenerlos a raya, pero no podemos dejar la seguridad de nuestras líneas de suministros al azar.",
			complete = "¡Excelente! Demostraste ser $gun valioso aliado:una valiosa aliada; en la guerra contra los silítidos.",
		},
		[8282] = {
			title = "La cartera perdida de Noggle",
			accept = "¿Dónde estoy? ¿Dónde está mi bolsa? *grito ahogado* Debo de haberla perdido cuando escapaba de Pinzamorten, la escórpida gigante. Cuando me escapaba corriendo, pasé justo por el medio de un nido de despellejadores Latipiedra.$B$BLa cartera que llevaba contenía todo tipo de exóticos componentes. Sin ellos, Beetix y yo no podremos crear las pociones que el Fuerte Cenarion necesita. Todavía estoy demasiado débil para levantarme, pero te compensaré si puedes traerme los componentes.$B$BMe encontré con Pinzamorten en las montañas del sur, detrás del Campamento Barbabronce.",
			complete = "¡Sí! Has recuperado mi bolsa. ¡Y están todos mis componentes exóticos! Estaré eternamente en deuda contigo.",
		},
		[8283] = {
			title = "Se busca: Pinzamorten el Terror de las arenas",
			accept = "Se cree que la terrible escórpida, Pinzamorten, se ha retirado a las montañas del sur debido a un aumento de presencia de silítidos. Supone una gran amenaza para las patrullas y expediciones de las regiones del sur. Los individuos que participen en su destrucción, recibirán una gran recompensa. Habla con el capitán Vish Kozus, en la parte de arriba de la Atalaya del Fuerte Cenarion, sobre las recompensas.",
			complete = "¡Excelente! Con Pinzamorten fuera del mapa, somos libres para utilizar las montañas del sur como camino estratégico para sortear las colmenas de silítidos. Apreciamos mucho lo que has hecho.",
		},
		[8284] = {
			title = "El misterio Crepuscular",
			accept = "Antiguamente, había un campamento de adeptos del Martillo Crepuscular al noroeste de aquí. Si fueras allí ahora, encontrarías la zona llena de elementales y trozos de madera y lonas donde solía estar el campamento.$B$BHe recuperado algunos fragmentos de una tablilla de arcilla del campamento, pero me faltan muchos para poder recomponer algo útil. Intenta encontrar los fragmentos de la tablilla restantes para que podamos obtener algo de información sobre la presencia del Martillo Crepuscular aquí, en Silithus.",
			complete = "Justo como sospechaba. Puedo descifrar palabras sueltas en las tablillas, pero parecen tener algún tipo de lógica o significado. Es bastante típico de las sectas del Martillo Crepuscular utilizar un código para ocultar el significado de sus textos. Tendremos que encontrar a alguien que sepa más de este tipo de cosas.",
		},
		[8285] = {
			title = "El desertor",
			accept = "Corren rumores sobre un miembro del Martillo Crepuscular llamado Ortell, que ha desertado de su secta. Dicen que se escondió en las montañas al sur de la Aldea del Viento del Sur, donde ahora vive como ermitaño. Quizás podrías convencerle para que nos ayudara a descifrar la tablilla.$B$BLlévate la tablilla restaurada y busca a Ortell.",
			complete = "Ya veo que conoces mi vieja organización. Debes de estar con los del Fuerte Cenarion.$B$B¿Buscas información para usarla contra ellos? Acércate, quizás podamos ayudarnos mutuamente.",
		},
		[8286] = {
			title = "Lo que nos depara el futuro",
			accept = "Ya estaba en brazos de la muerte cuando él intervino. Respiró una vez sobre mi cuerpo maltrecho y esperó pacientemente que las arenas del tiempo curasen mis heridas. $B$B\"Por siempre vivirás si tal es tu deber,\" dijo, y con esas palabras me convertí en guardia. $B$BVe al desierto. La Segunda Guerra está a punto de empezar. Debes encontrar el lugar de reposo eterno de los Barbabronce. Ve a las Cavernas del Tiempo para ver si el maestro ha regresado. Tengo que asegurarme antes de seguir.",
			complete = "Por fin ha vuelto. Ha terminado la espera.",
		},
		[8287] = {
			title = "Un propósito terrible",
			accept = "Muy bien, aquí estamos... ¡Diría que se trata de un montón de información! He visto a las tropas del Círculo Cenarion llegando a Silithus. Planean expulsar al Martillo Crepuscular, ¿no? Esto ayudará.$B$BLleva esta trascripción a su líder, el comandante Mar'alith. Pronto, el Martillo Crepuscular habrá sido derrotado y yo estaré libre de ellos para siempre.",
			complete = "Una información muy interesante, $n. Esto nos aclara algo la presencia del Martillo Crepuscular en Silithus y, sin duda, nos ayudará en la lucha contra ellos. Tus esfuerzos serán generosamente recompensados, $c.",
		},
		[8288] = {
			title = "Solo uno puede alzarse",
			accept = "¡No hay tiempo que perder! La misión que te encomiendo es propia de un ejército, pero entre los futuros campeones solo puede emerger uno. Solo tú puedes aceptar la responsabilidad que conlleva ser $Galiado:aliada; del Linaje. $B$BEn la guarida del Señor de Roca Negra vive una bestia cruel; el Señor de linaje Capazote vigila las Salas de los Conflictos e impide el paso al Sagrario Interior de Nefarian. Acaba con esa aberración y tráeme su cabeza. Después podrás seguir con tu viaje.",
			complete = "¿Podrías ser $gel primero:la primera; en ganar el favor entre el Vuelo de Bronce en mil años?",
		},
		[8291] = {
			title = "¡Expulsa al invasor!",
			accept = "Pasado este túnel encontrarás la Tierra de Disputas y desorden, joven $c. La Horda sigue diezmando nuestro sagrado bosque, talando el perenne follaje para alimentar a sus máquinas de guerra.$B$BEntra en la Garganta Grito de Guerra y defiende el Bastión Ala de Plata. ¡Haz retroceder a las fuerzas invasoras de la Horda!$B$BHazlo y obtendrás un talismán de mérito. Tráeme uno de esos talismanes, $n, y serás $grecompensado:recompensada;.",
		},
		[8292] = {
			title = "Talismanes del mérito",
			complete = "Gracias, $n. Tus hazañas en Garganta Grito de Guerra resuenan por todo el Bosque de Vallefresno.",
		},
		[8293] = {
			title = "Marca de Honor",
			complete = "¡Los elfos de la noche y sus aliados deben temblar incluso ante el susurro de tu nombre! ¡Por la horda!",
		},
		[8294] = {
			title = "Acaba con los usurpadores Ala de Plata",
			accept = "Las tierras del Bosque de Vallefresno sucumbirán al poder de la Horda, $r. Nada de lo que haga o diga el Ala de Plata podrá detener nuestro mando soberano. Kalimdor pertenece a la Horda. ¡Con qué osadía intentan evitar que cosechemos lo que nos pertenece por derecho!$B$BDeja que el orgullo hinche tu pecho cuando reduzcas sus débiles intentos por frenar nuestro avance. Destruye a las centinelas Ala de Plata y obtén una marca de Honor Grito de Guerra. Vuelve a verme cuando tengas una de esas marcas, $n, y serás $grecompensado:recompensada;.",
			complete = "<El capitán Shatterskull ruge triunfante.>$B$B¿Cuánto más pueden soportar? ¿Cuántas inmundicias más de la Alianza deben perecer a manos de la Horda para que se retiren? Solo el tiempo lo dirá, $r...",
		},
		[8297] = {
			title = "Los recursos de la Cuenca de Arathi",
			accept = "Hacen falta soldados para combatir en una guerra, cualquier soldado te lo dirá. También dicen que una guerra librada con equipamiento en malas condiciones o con el estómago vacío ¡está perdida antes de empezar!$B$BPor eso la Cuenca de Arathi es importante. Hay zonas clave en la cuenca donde se encuentran recursos esenciales. Metales, armas, comida, madera... todo lo que necesitamos, y todo se puede conseguir allí.$B$BEso es lo que quiero de ti, $n. Adéntrate en la Cuenca de Arathi, consigue la victoria tomando posesión de más bases que el enemigo y vuelve aquí con una caja de recursos.",
			complete = "¡Tienes los suministros! ¡Gran trabajo! Enviaré los recursos a nuestros intendentes, que pueden distribuirlos rápidamente entre nuestras tropas.$B$BGracias, $n. De hecho, realizar misiones exitosas como la que has logrado es la forma en que realmente se ganan las guerras.",
		},
		[8298] = {
			title = "Más cajas de suministros",
			complete = "Muy bueno. Se los llevaré a nuestros intendentes de inmediato, y se enviará un elogio por tus acciones a mis superiores.$B$BUna vez más, gracias $n. Desde el soldado al mariscal de campo, todos notan tus contribuciones a nuestra lucha.",
		},
		[8299] = {
			title = "Córtale el suministro a la Liga de Arathor",
			accept = "La Liga de Arathor no repara en gastos en su avance para recuperar Arathi. Ellos, y todas las razas de la Alianza, se dirigen ahora hacia esa distante región con la intención de extender su dominio desde el Refugio de la Zaga. Debemos detenerlos y la mejor manera es arrebatarles los suministros.$B$BPuedes ayudarnos, $n. Adéntrate en la Cuenca de Arathi, famosa por sus abundantes minas, fértiles tierras y los más finos artesanos. Captura y hazte con el control de todas las bases que puedas, gana la batalla y vuelve con los recursos que hayas obtenido.",
		},
		[8300] = {
			title = "Más cajas de suministros",
			complete = "Muy bueno. Se los llevaré a nuestros intendentes de inmediato, y se enviará un elogio por tus acciones a mis superiores.$B$BUna vez más, gracias $n. Desde el bruto al Alto señor de la Guerra, todos notan tus contribuciones a nuestra lucha.",
		},
		[8301] = {
			title = "El camino del honrado",
			accept = "El Linaje de Nozdormu desconfía por naturaleza de las razas inferiores. Aunque me has demostrado tener gran capacidad, ahora debes probarlo ante mi maestro.$B$BColmen'Ashi, Colmen'Zora y Colmen'Regal rebosan de actividad y son una amenaza para nosotros. Aniquila a los silítidos que encuentres allí y tráeme trozos de caparazón. Vuelve con todos los que puedas traer y yo reforzaré tu voluntad.",
			complete = "Voy a darte la facultad de nombrar ayudantes para tu misión. $gUn campeón:Una campeona; necesita ayuda para cumplir con su deber.",
		},
		[8302] = {
			title = "La mano del honrado",
			accept = "Elige a tus ayudantes con cuidado, mortal. Cada vez que completes una tarea, podrás elegir uno.$B$BNecesito más trozos de caparazón. ¡No pierdas el tiempo!",
			complete = "Bien hecho, $ghéroe:heroína;. Ahora se te otorgará la capacidad de sustituir a otro Agente de Nozdormu.",
		},
		[8303] = {
			title = "Anacronos",
			accept = "Te debo una disculpa, $N.$B$BSiento haber mantenido tantas cosas en secreto; hay muchos enemigos, incluso entre nosotros. Lee este libro y aprende; acepta el conocimiento que te doy y busca a nuestro maestro.",
			complete = "Eres la esperanza de Kalimdor, $n.",
		},
		[8304] = {
			title = "Queridísima Natalia",
			accept = "Mi querida Natalia ha desaparecido.$B$BLa verdad es que llevaba unas semanas muy rara; la pillé hablando sola más de una vez. Pero decía que estaba bien y que quería seguir investigando.$B$BFue vista por última vez de camino al campamento Barbabronce, al sur de aquí.$B$BMis soldados están dispersos, $N. Tienes que ir al campamento e interrogar a los enanos.",
			complete = "<El comandante Mar'alith medita un momento.>$B$BTengo que cumplir mi deber, tanto si está viva como si no. La encontraremos, pero yo no puedo dejar la avanzada. ¿Puedo contar contigo de nuevo, $n?",
		},
		[8305] = {
			title = "Recuerdos olvidados",
			accept = "En el desierto meridional de Silithus, cerca de la barrera sagrada, hay una lágrima cristalina. Es un símbolo de las terribles pérdidas de la guerra del Mar de Dunas. Encuéntrala y mira en sus profundidades para recibir la iluminación.|n",
			complete = "Puedes sentir un gran dolor girando alrededor de este cristal. La fuerza es tan poderosa que sientes como si pudieras colapsar y morir de tristeza.",
		},
		[8306] = {
			title = "En las fauces de la locura",
			accept = "Necesito que vayas a Colmen'Regal y averigües qué pasó con mi querida Natalia, $N. No será una tarea sencilla sin ayuda. Te recomiendo que lleves a algunos amigos. Antes de que te lances de cabeza a las fauces de la demencia, ve a hablar con esos enanos. Tal vez tengan algunos consejos para lidiar con los silítidos que moran en la colmena.$B$BY, $N, si realmente está tan loca como dicen... haz lo que sea necesario.$B$B<El comandante Mar'alith se aleja de ti.>$B",
			complete = "<El comandante Mar'alith se lleva una mano al pecho.>$B$B¿C'Thun? ¿Qué es C'Thun? ¿Cómo puede haber convertido a mi Natalia en ese monstruo que describes?",
		},
		[8307] = {
			title = "Receta del desierto",
			accept = "La adaptación a la vida del desierto ha sido difícil, por decir algo. No solo echo de menos los pájaros y los árboles de Auberdine, sino que nuestra comida está muy limitada debido a este entorno tan árido. Estoy intentando estudiar las hierbas del desierto, pero no hay demasiadas.$B$BHe visto grupos del Martillo Crepuscular del campamento al oeste de aquí, cazando gusanos de arena para comérselos. Sin embargo, la carne de los gusanos de arena es tan amarga, que no sé cómo consiguen comérsela. Mantén los ojos abiertos si vas a su campamento y avísame si descubres algo.",
			complete = "Este libro contiene varias recetas comunes y algunas bastante exóticas. Después de ojearlo durante unos segundos, ves una receta con carne de gusano de arena.",
		},
		[8308] = {
			title = "La carta perdida de Brann Barbabronce",
			accept = "A quien pueda interesar:$B$Bsi lees esto, yo estoy muerto o agonizante. No sabría decir; en todo caso, casi todos mis compañeros han muerto.$B$BEncontramos información sobre un titán. Gran combate entre él y un dios antiguo de verdad. Encontramos un antiguo túnel que lleva a Ahn'Qiraj. Lo seguimos.$B$BLleva esta carta a mi campamento. Asegúrate de que mi monito recibe comida, agua y abrazos.$B$BBrann Barbabronce, explorador extremo$B$BP.D: cuidado con los elfos de la noche adoradores de dioses antiguos.",
			complete = "Esto explica mucho. Si alguna vez entras en Ahn'Qiraj, busca al pobre Brann. Seguro que echa de menos al monito.",
		},
		[8309] = {
			title = "Los grabados de los glifos",
			accept = "Después de nuestra incursión inicial y la subsiguiente enajenación de la maestra Mar'alith, ¡no dejan de salir insectos de las tres colmenas! Parece que esta actividad frenética está relacionada con los glifos de estos cristales tan extraños.$B$BTenemos que conseguir calcos de los cristales de las tres colmenas. Si los conseguimos, podremos darle sentido a esta locura.$B$BToma este conjunto de transcripción y busca algunos amigos que te acompañen a las colmenas, $N. ¡No vuelvan hasta que hayan conseguido copias de todas!",
			complete = "Nunca había visto nada igual, no entiendo estos glifos. Espero que los estudios de Frankal nos iluminen un poco.",
		},
		[8310] = {
			title = "Descifrar el código",
			accept = "Creo que puedo preparar un elixir que nos ayudará a descifrar los glifos y el idioma de los silítidos y los qiraji.$B$B¿Que qué necesito? Buena pregunta: ¡necesito cerebros!$B$BNormalmente necesitaría un cerebro de cada tipo de silítido de las colmenas, pero otro aventurero me trajo estos dos... y nunca regresó de Colmen'Regal.$B$BTráeme un cerebro de silítido de Colmen'Regal... ¡y cuídate de acabar como el otro!",
			complete = "¡Magnífico! No te alejes mucho; seguro que tenemos más misiones para ti.",
		},
		[8311] = {
			title = "Golosinas de Halloween para Jesper",
			accept = "Quiero ir a pedir dulces, pero no puedo porque estoy enfermo. Si vas por mí, te cambiaré las golosinas que me traigas por unas que ya tengo. Te gustarán, ¡te transforman en cosas que dan risa y temor a la vez!$B$BTodos los taberneros de las ciudades dan golosinas por Halloween. Habla con ellos y haz lo que te pidan a cambio de las golosinas. Y el gnomo Talvash de Forjaz también da golosinas. ¡Vuelve cuando tengas todas las golosinas!",
			complete = "¡Genial, lo has conseguido todo! ¡Eres increíble!$B$BGracias por ir de truco o trato por mí. Ten, regalitos de calabaza, ¡ya verás cómo te gustan!$B$B¡Feliz Halloween, $n!",
		},
		[8312] = {
			title = "Golosinas de Halloween para Pupas",
			accept = "Quiero ir a buscar regalitos, pero no puedo porque estoy enferma. Si vas por mí, te cambiaré las golosinas que traigas por unas que ya tengo. Te gustarán, ¡te transforman en cosas que dan risa y temor a la vez!$B$BTodos los taberneros de las grandes ciudades dan golosinas por Halloween. Habla con ellos y haz lo que te pidan a cambio de las golosinas. Y el trol Kali Remik, que vive en Poblado Sen'jin, también da golosinas. ¡Vuelve cuando tengas todas las golosinas!",
			complete = "¡Genial, lo has conseguido todo! ¡Eres increíble!$B$BGracias por ir de truco o trato por mí. Ten, regalitos de calabaza, ¡ya verás cómo te gustan!$B$B¡Feliz Halloween, $n!",
		},
		[8313] = {
			title = "Compartir el conocimiento",
			accept = "La receta para cocinar gusanos de arena es bastante legible, pero contiene referencias a hierbas y especias de las que nunca has oído hablar. Quizás Calandrath tenga suficiente conocimiento de las plantas que crecen en el desierto para poder entenderlo.",
			complete = "Echemos un vistazo a eso...$B$BParece bastante simple. Tienen sus propios nombres para algunas de las hierbas, pero es fácil descifrarlos. Mira, te lo mostraré.",
		},
		[8314] = {
			title = "Desentrañar el misterio",
			accept = "¡Estamos a punto de conseguirlo, $n! He recreado los glifos en este prisma cristalino con los calcos que trajiste. Parece que los qiraji y otros entes desconocidos los usan para enviar mensajes a los silítidos.$B$BPor desgracia, esto es todo lo que hemos averiguado. Ahora tenemos que desbloquear los mensajes de los cristales.$B$BLlévale el prisma a la geóloga Trotuina, que está en el Fuerte Cenarion; quizás pueda ayudarnos.",
			complete = "Los enanos no pudieron descifrarlo porque no hay nada que descifrar. La capa externa fluida tiene que alinearse con los grabados del interior para transmitir el mensaje. Interesante...$B$BPodemos traducir los datos, pero antes hay que desbloquear el código. En el prisma solo hay una pista y no es muy esperanzadora.",
		},
		[8315] = {
			title = "La llamada",
			accept = "Los glifos muestran a un emisario de los qiraji reunido con tres silítidos entre los huesos de un gran dragón. Por encima hay una especie de código, que podría ser la clave para invocar al emisario.$B$BVoy a hacer una copia del código para que lo uses en la arena de Huesos de Grakkarond. Si mi deducción es correcta, los Señores Supremos creerán que hay datos nuevos que transmitir. Aniquílalos y enfréntate al emisario; es quien tiene la clave de los cristales.",
			complete = "¡Tengo 20.000 años de historia en las manos, $n!",
		},
		[8316] = {
			title = "Armamentos de guerra",
			complete = "Viene la guerra, $n, y con ella vienen horrores incalculables. Has hecho todo lo que se te puede pedir y por eso debes ser $grecompensado:recompensada;.$B$BSi esta... esta profecía alguna vez se cumpliera...$B$B<El geólogo Larksbane se pone pálido.>$B$BEl futuro de todos nosotros podría llegar a su fin.$B$BEste armamento resultará indispensable para la campaña en este desierto.",
		},
		[8317] = {
			title = "Echar una mano en la cocina",
			accept = "Esa receta nos vendrá muy bien. Será mejor que me ponga a trabajar para tener algunas albóndigas del desierto ahumadas para hoy. Me vendría bien que me echaras una mano, te lo compensaré.",
			complete = "¡Excelente! Me has salvado la vida. Las albóndigas salieron bastante bien. No esperaba que algo del Martillo Crepuscular tuviera tan buen sabor.",
		},
		[8318] = {
			title = "Mensajes secretos",
			accept = "Algunos de los adeptos del Martillo Crepuscular llevan papelitos con cosas extrañas escritas. Quiero que me traigas algunos, $c.$B$BNo puedo imaginarme lo que todo eso significa, ¡pero tampoco se trata de eso! Esos papeles son la forma de comunicación secreta entre los diferentes grupos. Cuantos más textos saquemos de la circulación, ¡menos se podrán comunicar!",
			complete = "¡Excelente! Guardaré esto, quizás sea útil más tarde.",
		},
		[8319] = {
			title = "Textos Crepusculares codificados",
			complete = "¡Excelente trabajo! Hablaré bien de ti.",
		},
		[8320] = {
			title = "Geoseñores Crepusculares",
			accept = "El Martillo Crepuscular, un culto demente que persigue la destrucción, ha establecido campamentos en Silithus y realiza rituales día y noche. Todavía no sabemos sus planes, pero creemos que tienen algo que ver con los cristales de color rojo intenso que están esparcidos por el desierto.$B$BEsperamos poder resolver algún día el misterio pero, por el momento, tenemos que encargarnos de la amenaza inmediata. Dirígete al oeste, hacia sus campamentos y busca a los geoseñores Crepusculares. Son los líderes de esas serpientes; ¡Ahí es donde debemos atacar!",
			complete = "Un trabajo bien hecho, $n. Matar a los geoseñores Crepusculares debe de haber causado un duro golpe al culto. Esperemos haber frustrado sus planes...",
		},
		[8321] = {
			title = "Vyral el Vil",
			accept = "Hemos descubierto otra base de operaciones del Martillo Crepuscular. Se llama Paseo Crepúsculo. Es una cueva que está justo en el extremo noreste de Silithus. El líder local del culto, Vyral el Vil, está en esa cueva. Tienes que acabar con él. Cuando lo hayas hecho, tráeme su sello.$B$BQue la fortuna esté contigo, $N. Los horrores a los que tendrás que enfrentarte en el Paseo Crepúsculo son formidables.",
			complete = "¡Lo has conseguido! ¡Vyral está muerto! Eso solo puede significar el fin de las operaciones del Martillo Crepuscular en Silithus. Es posible que haya más por ahí, pero el golpe que le has dado al culto hoy, es uno del que no se recuperarán fácilmente.",
		},
		[8322] = {
			title = "Huevos podridos",
			accept = "Los humanos de Costasur adoran su cerveza y tienen en alta estima la que sirven en la Taberna Costasur. Con el caos que se crea durante Halloween, podemos aprovechar para sabotear sus reservas de cerveza de semanas... ¡e incluso de meses!$B$BCoge estos huevos podridos e introdúcelos en los barriles que encontrarás en la Taberna Costasur. ¡Tu sola presencia causará estragos así que estate alerta!$B$BCuando hayan experimentado en Costasur ese sabor que nunca olvidarán, ven a verme al festival.",
			complete = "El barril está lleno de cerveza.$B$BDespués de abrirte paso con éxito dentro de la posada, ahora colocas los huevos dentro del barril. Puedes oler el mal olor que impregna el aire...",
		},
		[8323] = {
			title = "El creyente verdadero",
			accept = "Ahora que tengo el Lexicón Crepuscular, necesito pedirte un pequeño favor.$B$BMi antigua organización tiene un boletín secreto cifrado que hacen circular mensualmente.$B$BSi realizan algún avance en mi búsqueda, o dejan de buscarme, todo se publicará en El creyente verdadero.$B$BAunque esta información es, obviamente, importante para mí, la publicación contiene otra información que necesito. Tráeme cualquier texto encriptado que encuentres en los miembros del Martillo Crepuscular.",
			complete = "¡Excelente! Me pondré a descifrar esto en cuanto pueda. Si descubro algo interesante, encontraré la forma de hacerte llegar la información.",
		},
		[8324] = {
			title = "Seguir creyendo",
			complete = "¡Excelente! Me muero por leerlos. Por favor, sigue trayéndome textos encriptados si los encuentras.",
		},
		[8331] = {
			title = "Aurel Hojaurea",
			accept = "$n, si bien pensábamos que las operaciones del Martillo Crepuscular en Silithus iban despacio... estábamos terriblemente equivocados. Gracias a las continuas incursiones en territorio del culto, hemos descubierto que un poder mucho más oscuro, el Consejo Abisal, controla al Martillo mediante las piedras de viento Arcanas esparcidas por los campamentos del culto. $n, tu próxima misión será contra el Consejo Abisal.$B$BHabla con la artesana Aurel Hojaurea, en la sección este del Fuerte Cenarion. Vamos a necesitar sus habilidades para esta operación.",
			complete = "$n, buenos días. ¿Me han dicho que te vas a presentar ante el Consejo Abisal? Si es así, escucha mis palabras atentamente...",
		},
		[8332] = {
			title = "Los Duques del Consejo",
			accept = "Creemos que es posible utilizar una piedra de viento para emboscar a un Duque del Consejo Abisal. Sin embargo para hacerlo, alguien debe lograr comulgar con la piedra de viento y convencer al Consejo de que es un líder de rango medio del Martillo Crepuscular.$B$BPara hacer esto, necesitamos una réplica del medallón de estatus del culto. Yo puedo crear el medallón, pero necesitaré un fragmento luminoso grande y blasones de Templario Abisal.$B$BTráeme los objetos y yo me encargaré del resto.",
			complete = "Ah, muy bien. He estado trabajando en el medallón. Ahora, con estos últimos ingredientes, acabaré en un abrir y cerrar de ojos...$B$BYa estamos. Aquí tienes el medallón, $n.$B$BTendrás que llevarlo cuando actives una de las piedras de viento del Martillo Crepuscular. Póntelo junto con el resto de los símbolos del Martillo y el Consejo Abisal te verá como uno de sus subordinados.",
		},
		[8333] = {
			title = "Medallón de estatus",
			complete = "Aquí tienes, $n. Un medallón más de estatus del culto Crepuscular. ¡Úsalo bien y te deseo suerte contra el Consejo Abisal!",
		},
		[8341] = {
			title = "Señores del Consejo",
			accept = "Solo es posible invocar a los Señores del Consejo Abisal mediante las piedras de viento superiores, y solo los miembros de mayor rango del Martillo Crepuscular pueden hablar con ellos. Pero... he encontrado la forma de mejorar tu disfraz y engañar a los Señores Abisales.$B$BPara completar el disfraz necesitamos un anillo de nobleza, que solo adorna las manos de los miembros de más alto prestigio del culto. Puedo hacerte uno si me traes fragmentos luminosos grandes y sellos abisales.",
			complete = "Gracias. Un momento y tendré ese anillo listo para ti...$B$BAhí está. Ahora estás $glisto:lista;.$B$BAsegúrate de usar este anillo, junto con un medallón de estatus y el resto de los adornos crepusculares, cuando actives una piedra de viento mayor. Hazlo y el Consejo Abisal te considerará uno de sus sirvientes. Entonces, ¡quizás puedas atraer a uno a una emboscada!",
		},
		[8342] = {
			title = "Anillo de nobleza Crepuscular",
			complete = "Ah, veo que tus convicciones son fuertes. ¡No muchos le plantarían cara a ese consejo de demonios!$B$BAquí está tu anillo, $n. Que tu voluntad y tu fortuna se mantengan firmes.",
		},
		[8343] = {
			title = "El descubrimiento de Hojaurea",
			accept = "¡$N, Aurel Hojaurea cree haber encontrado la forma de invocar y derrotar a un miembro dirigente del Consejo Abisal! Hacerlo será peligroso, pero has ganado un gran respeto entre el Círculo Cenarion. Sabemos que, si hay alguien capaz de hacerlo, eres tú.$B$BQue la suerte te acompañe, $N. Habla con Aurel cuando estés $gpreparado:preparada;.",
			complete = "Lo que dice Huum es cierto. ¡Creo que sé cómo convocar a un señor del Consejo Abisal! Escucha y te explicaré...",
		},
		[8348] = {
			title = "Sellos de los Duques",
			accept = "¡Huum me ha dicho que has descubierto cómo invocar a los duques Abisales! Es un gran logro.$B$B¿Sabes qué más sería un gran logro? Aplastar a una de esas cosas. Eso causaría una fuerte impresión a sus subordinados, ya sabes lo que quiero decir. Tráeme su sello como prueba.",
			complete = "Sabía que eras $gun:una; $n $gduro:dura; en el momento en que te vi entrar en Fuerte Cenarion. ¡Sigue así!",
		},
		[8349] = {
			title = "Bor Ferocrín",
			accept = "Ahora que tienes un medallón y puedes invocar a un duque Abisal, habla con Bor Ferocrín. Te encargará una misión contra el Consejo Abisal.$B$BBuena suerte, $n. Y, si alguna vez necesitas más medallones, ya sabes dónde estoy.",
			complete = "¡Qué alegría volver a verte, $c! ¿Te han hecho un medallón? Bien... lo necesitarás para tu próxima misión...",
		},
		[8351] = {
			title = "Bor quiere hablar contigo",
			accept = "Ahora que puedes disfrazarte como un miembro dirigente del Consejo Crepuscular, seguro que Bor Ferocrín querrá hablar contigo. Vete a verle y prepárate para una misión de gran complejidad...",
			complete = "Sí, es cierto, $n. Tengo una tarea muy dura por delante...",
		},
		[8352] = {
			title = "Cetro del Consejo",
			accept = "Huum y yo estábamos hablando de ti. Me contaba que estás a punto de intentar luchar contra un Señor Abisal.$B$BDebo decirte que se trata de algo muy peligroso. Será mejor que te lleves refuerzos. Y no me refiero a un par de amigos, sino a un regimiento de primera listo para la batalla. Si tus amigos son tan buenos como tú, ¡quizás puedas vencerle!$B$BSi lo haces y, como siempre, querré pruebas de ello, te daré una recompensa increíble.",
			complete = "¡Tú... lo hiciste! ¡Lo hiciste, $n! ¡Aquí! Toma esto. Es el cofre más grande que teníamos y lo llené con algunas de las mejores cosas que encontramos.",
		},
		[8353] = {
			title = "Una menta por cacarear como un pollo",
			accept = "Ajá, ¿jugando a truco o trato por un niño enfermo? Iba a decir que ya eres mayor para andar buscando caramelos por ahí...$B$BPues bien, para que te dé mi golosina, una menta de Forjaz, tienes que... ¡cacarear como un pollo! Sí, a los pollos les encanta la menta... Bueno, quizás no, ¡pero tienes que cacarear si quieres la menta!$B$BY bien, $c, ¡¿te atreves con el desafío o no?! ¡Es hora de ganarte la golosina!",
			complete = "¡Qué divertido! ¡Lo has hecho muy bien, $n! Aquí tienes tu regalo.$B$B¡Feliz Halloween!",
		},
		[8354] = {
			title = "Una menta por cacarear como un pollo",
			accept = "Ajá, ¿jugando a truco o trato por un niño enfermo? Iba a decir que ya eres mayor para andar buscando caramelos por ahí...$B$BPues bien, para que te dé mi golosina, una menta de Entrañas, tienes que... ¡cacarear como un pollo! Sí, a los pollos les encanta la menta... Bueno, quizás no, ¡pero tienes que cacarear si quieres la menta!$B$BY bien, $c, ¡¿te atreves con el desafío o no?! ¡Es hora de ganarte la golosina!$B",
			complete = "¡Qué divertido! ¡Lo has hecho muy bien, $n! Aquí tienes tu regalo.$B$B¡Feliz Halloween!",
		},
		[8355] = {
			title = "¡Truco o trato!",
			accept = "Buscando regalitos, ¿eh? ¡Genial!$B$BBueno, aunque hagas algo noble como buscar golosinas para una criatura enferma, no te dejaré ir tan fácilmente. Te daré una deliciosa gominola de Gnomeregan para el niño... ¡si haces ruidos de tren para mí! ¡Ja, ja, sí, ese será el trato! ¡Una gominola a cambio de imitar un tren!$B$B¡Pasajeros al tren, $c!",
			complete = "¡Chú, chú! ¡Bien hecho, $n! Aquí tienes tu premio.$B$B¡Feliz día de Halloween!",
		},
		[8356] = {
			title = "Saca músculo a cambio de almendrados",
			accept = "Qué disfraz tan... interesante. Aunque es muy agradable que ayudes a un niño enfermo a jugar a truco o trato este año, ¡me temo que tendré que pedirte que hagas un truco para mí!$B$BPareces tan fuerte con ese... disfraz... ¡Veamos cómo sacas músculos! Sí, ¡empieza a sacar músculos para mí, $gfortachón:fortachona;!$B$BCuando hayas acabado, te daré un sabroso almendrado de Ventormenta. Típico de Halloween.",
			complete = "¡Ja, ja, eres muy $gpoderoso:poderosa;! Bien hecho, gracias por tener tan buen talante. Aquí tienes tus caramelos.$B$B¡Feliz Halloween, $n!",
		},
		[8357] = {
			title = "Bailando por mazapanes",
			accept = "Aunque estés haciendo lo de truco o trato por un niño enfermo, ¡no te libras de hacer un truco para conseguir el trato! No podemos cambiar la tradición así como así, ¿no te parece?$B$BCreo que el precio de una pieza de mazapán, hoy en día, es... ¡un BAILE! ¡Eso es! ¡Déjame ver tus movimientos! ¡Si bailas para mí, te daré un poco de delicioso mazapán!",
			complete = "¡Vaya, $n! ¡Eres $gun bailarín nato:una bailarina nata;!$B$BAquí tienes tu recompensa por haber participado. ¡Feliz Halloween! ¡Saluda a tu amiguito enfermo! Espero que se recupere pronto.",
		},
		[8358] = {
			title = "¡Truco o trato!",
			accept = "Buscando regalitos, ¿eh? ¡Genial!$B$BBueno, aunque hagas algo noble como buscar golosinas para una criatura enferma, no te dejaré ir tan fácilmente. Te daré una deliciosa gominola Lanza Negra para el niño... ¡si haces ruidos de tren para mí! ¡Ja, ja, sí, ese será el trato! ¡Una gominola a cambio de imitar un tren!$B$B¡Pasajeros al tren, $c!$B",
			complete = "¡Chú, chú! ¡Bien hecho, $n! Aquí tienes tu premio.$B$B¡Feliz día de Halloween!",
		},
		[8359] = {
			title = "Saca músculo a cambio de almendrados",
			accept = "Qué disfraz tan… interesante. Aunque es muy agradable que ayudes a un niño enfermo a jugar a truco o trato este año, ¡me temo que tendré que pedirte que hagas un truco para mí!$B$BPareces tan fuerte con ese… disfraz… ¡Veamos cómo sacas músculos! Sí, ¡empieza a sacar músculos para mí, $gfortachón:fortachona;!$B$BCuando hayas acabado, te daré un sabroso almendrado de Orgrimmar. Típico de Halloween.$B",
			complete = "¡Ja, ja, eres muy $gpoderoso:poderosa;! Bien hecho, gracias por tener tan buen talante. Aquí tienes tus caramelos.$B$B¡Feliz Halloween, $n!",
		},
		[8360] = {
			title = "Bailando por mazapanes",
			accept = "Aunque estés haciendo lo de truco o trato por un niño enfermo, ¡no te libras de hacer un truco para conseguir el trato! No podemos cambiar la tradición así como así, ¿no te parece?$B$BCreo que el precio de una pieza de mazapán, hoy en día, es... ¡un BAILE! ¡Eso es! ¡Déjame ver tus movimientos! ¡Si bailas para mí, te daré un poco de delicioso mazapán!",
			complete = "¡Vaya, $n! ¡Eres $gun bailarín nato:una bailarina nata;!$B$BAquí tienes tu recompensa por haber participado. ¡Feliz Halloween! ¡Saluda a tu amiguito enfermo! Espero que se recupere pronto.",
		},
		[8361] = {
			title = "Contactos Abisales",
			accept = "Hemos visto adeptos del Martillo Crepuscular realizando rituales para invocar a poderosos nobles elementales. No sabemos si se trata de los seres a quienes adoran los adeptos, o si actúan como intermediarios de fuerzas mucho más poderosas. Pero algo está claro. Están recibiendo órdenes de esos elementales.$B$BQuiero que encuentres la forma de contactar con un Templario Abisal y le des una buena paliza. No hay nada mejor que cargarse la cadena de mando para que las tropas salgan corriendo despavoridas. Tráeme una prueba de tu hazaña.",
			complete = "¡Ja! ¡Lo has conseguido, $n! ¡Pronto aplastaremos al Martillo Crepuscular!",
		},
		[8362] = {
			title = "Blasones Abisales",
			complete = "¡Lo has hecho bien! Eso es menos Templarios de los que preocuparme.$B$BAquí tienes, $n. Espero que haya algo útil para ti.",
		},
		[8363] = {
			title = "Sellos abisales",
			complete = "¡Excelente, $n! Derrotar a esos duques dejará al Martillo Crepuscular tambaleándose por un tiempo. Como prometí, aquí tienes tu recompensa. Es una de las mejores cosas que Huum y yo hemos encontrado.",
		},
		[8364] = {
			title = "Cetros Abisales",
			complete = "¡Sabía que vendrías, $n! Aquí tienes tu recompensa.",
		},
		[8365] = {
			title = "¡Sombreros de pirata a babor!",
			accept = "¿Tú eres la ayuda que envía el Cártel? Supongo que bastará. Escucha atentamente, $c. Como ya sabrás, yo soy quien se encarga de que la alta sociedad de Azeroth vista a la última moda. Reyes y reinas, jefes de guerra y... como sea que se llaman las reinas de la Horda, todos visten lo que yo digo que se lleva. Y lo mejor es que todos pagan un ojo de la cara.$B$BAhora te diré lo que tienes que hacer. Dirígete a la Cala del Aparejo Perdido y consigue gran cantidad de sombreros de pirata por cualquier medio. ¿Crees que podrás hacerlo?",
			complete = "Oh, eres un cielo, aunque hayas tardado más de lo que esperaba. Cuando estos sombreros estén limpios y les haya dado mi toque personal, sacaré un buen pellizco por ellos. Y dado que siempre suelo recompensar un trabajo bien hecho, aquí tienes algo para ti. Te recomiendo que reserves algo para darte un buen baño, encanto.",
		},
		[8366] = {
			title = "Mamporros en los Mares del Sur",
			accept = "¡Argh! ¡Me piden imposibles!$B$BEl Cártel Bonvapor quiere que les dé a los piratas de los Mares del Sur una lección. El problema es que no puedo estar en dos sitios a la vez. Yo he de quedarme aquí para mantener el orden.$B$BÚltimamente, los piratas han estado haciendo caso omiso del dinero que el cártel desembolsa con regularidad para evitar problemas con ellos. Así que me gustaría que fueras allí en mi lugar y les enseñaras lo que es bueno.$B$BLos encontrarás en la Cala del Aparejo Perdido, que no está muy lejos en dirección sur. Gracias, $N. ¡Te debo una!",
			complete = "¡$n! ¡Tú sí que vales!$B$BEstoy seguro de que el cártel dejará de presionarme ahora que has acabado con esa escoria del Mar del Sur. Veamos, ¿qué puedo darte como recompensa? ¿Qué te parece si me das una pieza y te dejo elegir uno de estos por tus esfuerzos?",
		},
		[8367] = {
			title = "Cuestión de honor",
			accept = "¡Servir a la Horda en una de las grandes batallas contra la Alianza es fuente de gran honor! Pero los pocos que han servido a la Horda en TODOS los frentes de batalla activos son los más grandes de nuestros combatientes. Debemos derrotar a nuestros oponentes, pero no luchando en escaramuzas aisladas sino en una guerra bien coordinada.$B$B¡Adelante, derrota a la Alianza en todos los frentes! ¡Por el honor! ¡Por la Horda!",
			complete = "Tus pruebas no han sido fáciles, pero tu valor no se te escapó y tus fuerzas no fallaron. Parte con marcas de victoria anteriores, $n. Nadie los necesitará como recordatorio de su valía. Ponte de pie, $n. ¡Hoy caminarás con mucho orgullo porque eres $gun héroe:una heroína;!",
		},
		[8368] = {
			title = "La batalla por Garganta Grito de Guerra",
			accept = "La batalla de la Garganta Grito de Guerra contra las centinelas Ala de Plata tiene una importancia vital. Con la excusa de estar protegiendo un bosque que no les pertenece, la Alianza intenta negar a la Horda una de sus principales fuentes de recursos madereros.$B$B¡No debemos permitirlo, $n! ¡Vuelve a verme cuando puedas demostrar que has servido a la Horda dignamente!",
			complete = "¡Excelente! ¡Has demostrado tu valía defendiendo nuestras operaciones en Garganta Grito de Guerra! Que la palabra de tu honor se extienda por todas partes en nuestras tierras.",
		},
		[8369] = {
			title = "Invasores del Valle de Alterac",
			accept = "Escucha, $n. No importa lo que hayas podido oír sobre la batalla del Valle de Alterac, una cosa es cierta: la expedición Pico Tormenta invadió el territorio de Lobo Gélido. El día en que permitamos a la Alianza invadir tierras de la Horda sin una respuesta enérgica, será el día en el que deje mi hacha y viva en la deshonra el resto de mis días. ¡Adelante y expulsa a los invasores!",
			complete = "¡Has mostrado una gran valentía al proteger nuestras tierras del Valle de Alterac! Hablaré a mis superiores de tus hazañas.",
		},
		[8370] = {
			title = "La conquista de la Cuenca de Arathi",
			accept = "Nuestro conflicto con la Alianza se ha convertido en una auténtica guerra. En este momento ya no valen falsas excusas para entrar en la batalla.$B$BLa batalla por la Cuenca de Arathi es por los recursos, llana y simplemente. Si la Alianza se hace con ellos y los utiliza contra nosotros o si somos nosotros los que los obtenemos y los utilizamos para mantener nuestro esfuerzo bélico. ¡Ayuda a Los Rapiñadores a mantener el flujo de recursos que necesitamos, $n!",
		},
		[8371] = {
			title = "Esfuerzos concertados",
			accept = "Ya no estamos combatiendo en batallas aisladas contra la Horda, $gmuchacho:muchacha;.$B$BLa victoria en uno de los frentes supone negar a la Horda recursos que utilizarían contra nosotros en otra batalla. Por eso mismo, perder una batalla daría ventaja a nuestros adversarios en algún otro lugar del mundo.$B$BLa Alianza necesita más combatientes que comprendan esta realidad... ¡veteranos realmente avezados! $n, vuelve a verme cuando hayas servido contra la Horda en todos nuestros campos de batalla activos.",
			complete = "¡No eres de los que decepcionan, $n! Lo que has aprendido va más allá de insignificantes medallas y elogios. Lo que has aprendido es lo que solo se obtiene con la experiencia y el endurecimiento del temperamento en el campo de batalla.$B$BLo has hecho bien, $c. ¡Eres $gun:una; $gverdadero:verdadera; $ghéroe:heroína; de la Alianza!",
		},
		[8372] = {
			title = "Lucha por Garganta Grito de Guerra",
			accept = "Las centinelas Ala de Plata están en guerra con los escoltas Grito de Guerra por la destrucción que los orcos están provocando en el bosque. Pero hay más razones para defender este bosque y que van más allá del amor por la naturaleza.$B$BEl bosque forma una barrera estratégica que permite defender Vallefresno contra un ataque a gran escala. Sin él perderíamos Astranaar en un solo día y pasaría a integrarse en Los Baldíos.$B$B¡Colabora en la lucha contra los escoltas Grito de Guerra, $n! ¡Por la Alianza!",
		},
		[8373] = {
			title = "El poder del pino",
			accept = "Lo que más odio de Halloween son las bombas fétidas que lanzan los Renegados en Costasur. ¿Quién iba a pensar que la celebración de la liberación acabaría oliendo tan mal?$B$BUsa este limpiador para eliminar las bombas fétidas que tire la Horda durante las celebraciones. Elimina los malos olores gracias a su extracto de pino.$B$BColabora en la limpieza de Costasur y te daré unos regalitos de Halloween que te van a encantar. ¿Trato?",
			complete = "Ah, ya casi huele mejor por aquí. Casi.$B$BGracias a ti, $n, Costa Sur podría pasar por otro Halloween. ¡Aquí están sus golosinas, con mi agradecimiento! Si te quedas sin caramelos, creo que hay una gnoma llamado Katrina Shimmerstar en Forjaz que puede venderte más; ella solo está presente durante Halloween, creo.",
		},
		[8374] = {
			title = "Reclamo por la Cuenca de Arathi",
			accept = "Ganar una guerra es algo más que ser más astuto y mejor guerrero que tu oponente. A menudo la victoria llega cuando produces más que tu enemigo.$B$BLo que tenemos en la Cuenca de Arathi es un considerable suministro de recursos a disposición del bando que primero los reclame.$B$BSi la Alianza se alza con la victoria, tendremos más espadas y picos para nuestras tropas. Si ganara la Horda, ¡esas espadas y picos pasarían a amenazarnos! Ha llegado el momento de ayudar a la Alianza en la Cuenca de Arathi, $N.",
		},
		[8375] = {
			title = "¡Recuerda el Valle de Alterac!",
			accept = "No te confundas, $n. La Horda tiene razón al afirmar que el Valle de Alterac es el territorio de Lobo Gélido.$B$BPero verás, la expedición Pico Tormenta llegó a la zona en busca de minerales y reliquias, se trataba de una visita pacífica. Los Lobo Gélido respondieron con el acto más brutal e incivilizado que nunca ha vivido la Alianza.$B$BNo podemos olvidar nunca a los valientes enanos que perecieron en ese cobarde ataque sin previo aviso. Ahora vete, $c, únete a la batalla por el Valle de Alterac. ¡Por la Alianza!",
			complete = "¡Has demostrado una gran valentía al proteger nuestras tierras en el Valle de Alterac! Les contaré a mis superiores tus actos.",
		},
		[8376] = {
			title = "Armamentos de guerra",
			complete = "Viene la guerra, $n, y con ella vienen horrores incalculables. Has hecho todo lo que se te puede pedir y por eso debes ser $grecompensado:recompensada;.$B$BSi esta... esta profecía alguna vez se cumpliera...$B$B<El geólogo Larksbane se pone pálido.>$B$BEl futuro de todos nosotros podría llegar a su fin.$B$BEste armamento resultará indispensable para la campaña en este desierto.",
		},
