		[8409] = {
			title = "Los barriles dañados",
			accept = "Has conseguido meter los huevos podridos en los barriles. ¡Sin duda se arruinarán muchas partidas de cerveza en la Taberna Costasur!$B$BAhora debes ir a ver a la clamasombras Yanka al Festival del Hombre de Mimbre en los Claros de Tirisfal e informarle de tu éxito.",
			complete = "¡Ah, bien! Has mostrado el verdadero espíritu de Halloween, ¡espíritu Renegado, debería decir!$B$B<La clamasombras Yanka se ríe y se frota las manos.>$B$BMe deleito en el hecho de que Costa Sur ahora debe darse un festín con cerveza mala o prescindir de ella. En cuanto a ti, toma estas golosinas. ¡Creo que les encontrarás un buen uso!",
		},
		[8410] = {
			title = "Maestría elemental",
			accept = "Bath'rah el Vigía del viento ha reclamado un chamán de tu sabiduría. Pide que lleves contigo una muestra de cada uno de los elementos para mostrar que estás $gpreparado:preparada;.$B$BPara encontrar a Bath'rah dirígete al río al este del Molino Tarren. Sigue el río hacia el Norte, hasta que des con las ruinas en las que vive Bath'rah.",
			complete = "Excelente, colega. Ahora nos entendemos.",
		},
		[8411] = {
			title = "Dominar los elementos",
			accept = "$gBienvenido:Bienvenida;, colega. Tráeme los elemento' y después hablaremos.",
			complete = "Estos son los elementos que necesito. Ahora hablamos.",
		},
		[8412] = {
			title = "Tótem de espíritu",
			accept = "Ya no les gusto a los espíritus elementales de este lugar.$B$BTú sabes de los tótems más que nadie y yo necesito un tótem de espíritu que me proteja. Ya tenemos los elementos y necesitamos algo más de Naturaleza. Más primigenio.$B$BEn las Tierras de la Peste del Oeste podrás encontrar osos para quitarles las garras y arañas para quitarles los ojos. Los pájaros carroñeros comen de todo, así que seguro que también tendrán algo de eso adentro.",
			complete = "¡Genial, colega! Probémoslo...",
		},
		[8413] = {
			title = "Vudú",
			accept = "El tótem de espíritu no alcanza. Vamos a necesitar un poco de magia vudú.$B$BLos trols del Templo Sumergido tienen plumas mágicas muy poderosas. Debes ir allí y matar a Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Entonces tendremos suficiente magia para un verdadero tótem de espíritu.",
			complete = "¡Ya es hora de que este trol descanse toda la noche! El tótem espiritual velará por mí.$B$BLlevo mucho tiempo coleccionando cosas, ¿tal vez quieres algo por todos tus problemas?",
		},
		[8414] = {
			title = "Expulsión de los demonios",
			accept = "Saludos, $c. Los cruzados como tú siempre son bienvenidos en esta tierra desolada.$B$BTu sagrada fuerza es necesaria para combatir al número infinito de no-muertos. Necesitamos que reúnas un gran número de piedras de la Plaga y que las entregues al sumo sacerdote Thel'danis. Podrás encontrarlo custodiando la Tumba de Uther en la Colina de las Penas, no lejos de aquí.$B$BSolo quien lleve una Comisión de El Alba Argenta podrá encontrar piedras de la Plaga, así que habla con la oficial Purocorazón si aún no tienes ninguna.",
			complete = "Existe el riesgo de disipar el mal de un azote, ya que atrae la atención de los muertos vivientes a lo largo de incontables millas. Pero eres fuerte en la Luz, $n, y no temo por ti...",
		},
		[8415] = {
			title = "Alto del Orvallo",
			accept = "El comandante Ashlam Puñovalor ha hecho un pedido por un paladín de tu valor y pureza, $n. Puedes encontrarlo en Alto del Orvallo en la parte sur de Tierras de la Peste del Oeste. ¡Búscalo y ayúdalo en su causa por la Luz!",
			complete = "¡Muy bien, $n! Veamos de qué estás $ghecho:hecha;.",
		},
		[8416] = {
			title = "$",
			accept = "Las piedras han purgado el mal, $n.$B$BConozco los planes del comandante Ashlam y solo necesitará una piedra inerte. Llévasela y podremos purificar a la Plaga en el fuego de los justos.",
			complete = "Has hecho lo que te pedí sin dudarlo, $n.$B$BLa confianza se gana, parece. Quizás ahora pueda revelarte nuestro plan con más detalle.",
		},
		[8417] = {
			title = "Un espíritu afligido",
			accept = "En Las Tierras Devastadas habita un espíritu preocupado que fue un día un gran héroe de la Horda. El honor de un guerrero no perece con su cuerpo, debería serte de ayuda hablar con él.",
			complete = "Entonces, has venido a aliviar mi dolor. Ojalá pudieras simplemente derribarme, pero no es tan simple...",
		},
		[8418] = {
			title = "La forja de la piedra de poderío",
			accept = "Ahora tenemos que combinar las piedras de la Plaga inertes y crear un arma que destroce las filas de no-muertos. No es una tarea sencilla, $n. Solo los trols del Templo Sumergido son portadores del tipo de extraña magia que puede convertir el mal en algo contrario a sí mismo.$B$BLos trols del Templo son conocidos como Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. No sientas ningún remordimiento por sus corruptas almas... no están libres de mal.",
			complete = "Esto es excelente, $n. Diría que estoy sorprendido, pero sabía sin lugar a dudas que no nos decepcionarías.$B$BEs un honor para mí concederte una de las Sagradas Piedras de Poder. Úsala bien.",
		},
		[8419] = {
			title = "Pedido de un diablillo",
			accept = "$n, un diablillo de Frondavil, llamado Diblis, ha pedido tu presencia. Es algo extraño, pidió que llevaras contiguo una pieza de tela vil como símbolo de tu buena fe. Teniendo en cuenta tu poder como brujo supongo que ya sabrás que los sátiros de Frondavil llevan consigo telas viles.$B$BEncontrarás a Diblis al norte de las Cascadas del Veneno, un lugar realmente encantador en esta época del año.",
			complete = "¡Qué $gespléndido:espléndida; $n eres!$B$B<Impsy se lleva la tela vil a la cara.>$B$BOh, cómo me encanta sentirlo, la forma en que quema tu piel y teje pensamientos malvados en la mente...",
		},
		[8420] = {
			title = "Caliente y picante",
			accept = "Puede que suene extraño viniendo de un diablillo, pero quiero tener una mascota. Me encantaría tener una. ¡No es justo que Niby me tenga a mí y yo no tenga nada!$B$BNi siquiera tiene que ser una mascota viva. Solo necesito algo para empezar a hacer una, como una tela vil. Los sátiros de Frondavil a veces tienen tela vil. Solo tendrás que ir matando a los que encuentres hasta que consigas una. No está mal el plan, ¿verdad?",
			complete = "¡Guau! Eres demasiado $gbueno:buena;. ¡Especialmente para $gun:una; $n! $B$B<Impsy se lleva la tela vil a la cara.>$B$BOh, cómo me encanta sentirlo, la forma en que quema tu piel y teje pensamientos malvados en la mente...",
		},
		[8421] = {
			title = "La mercancía equivocada",
			accept = "Ahora que tengo mi tela vil, puedo empezar a hacer mi mascota.$B$BPero va a necesitar unos ojos... Quizás puedas robar un poco de madera podrida de los Troncoferro, para que pueda tallarle unos bonitos ojos. Están al norte, en el Bosque de Troncoferro.$B$BY también necesitaré un poco de esencia de veneno para que tenga olorcillo a demonio. Los mocos corruptos tienen esa esencia. Suelen estar por aquí, cerquita de Niby y de mí.",
			complete = "Esto funcionará muy bien.",
		},
		[8422] = {
			title = "Plumas de trol",
			accept = "Casi he acabado mi mascota. Ahora necesito algo para rellenarla.$B$BY solo pueden ser plumas vudú de los trols del Templo Sumergido. Se llaman Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Mátalos. Mátalos a todos.$B$BNo será tarea fácil, $n, pero haré que te merezca la pena correr el riesgo. Te daré una cosa de Niby... no creo que vaya a necesitarla de todas formas.",
			complete = "¡Maravilloso, ahora mi mascota está completa!$B$B<Impsy rápidamente mete la muñeca y le da un abrazo demoníaco.>$B$BOh, qué efecto secundario tan extraño tienen estas plumas de vudú...",
		},
		[8423] = {
			title = "Parentesco guerrero",
			accept = "<El Héroe te mira detenidamente.>$B$BEres $gun:una; $c, vaya si lo eres. Te encargaría una tarea honorable pero primero debo poner a prueba tu fuerza.$B$BDicen que Rexxar mide el filo de sus espadas matando a un jabinferno de un solo sablazo. Así que mediré la fuerza que tienes por cómo los matas.",
			complete = "No necesito pruebas para saber lo que ha hecho, $n. Puedo ver la determinación grabada en tu expresión.",
		},
		[8424] = {
			title = "La guerra contra los Sombra Jurada",
			accept = "La continuada presencia de los Sombra Jurada en Las Tierras Devastadas me entristece sobremanera. Sus oscuros rituales y hechizos causan agonía como nada que yo sufriera en vida.$B$BA través de ti puedo enviar mi mensaje de dolor. Adelante y transmíteles mi ira.",
			complete = "Ya has mitigado mi dolor y me has honrado. Gracias, $n.",
		},
		[8425] = {
			title = "Plumas Vudú",
			accept = "Tu honor me ha devuelto algo de paz. Es de justicia que te entregue algo a cambio.$B$BMis armas y armadura eran espléndidas en vida pero ahora ya no me sirven. Cumplirán mejor su función en tu posesión.$B$BVe al Templo Sumergido y destruye a los trols guardianes Gasher, Mijan, Zolo, Hukku, Zul'lor y Loh'ro. Llevan plumas mágicas que pueden recrear mi cuerpo físico lo suficiente para que te pueda dar tu premio.",
			complete = "Por fin puedo volver a sentir el frío toque del acero, aunque sea sólo por un momento.",
		},
		[8426] = {
			title = "La batalla por Garganta Grito de Guerra",
			accept = "La batalla de la Garganta Grito de Guerra contra las centinelas Ala de Plata tiene una importancia vital. Con la excusa de estar protegiendo un bosque que no les pertenece, la Alianza intenta negar a la Horda una de sus principales fuentes de recursos madereros.$B$B¡No debemos permitirlo, $n! ¡Vuelve a verme cuando puedas demostrar que has servido a la Horda dignamente!",
			complete = "¡Excelente! ¡Has demostrado tu valía defendiendo nuestras operaciones en Garganta Grito de Guerra! Que la palabra de tu honor se extienda por todas partes en nuestras tierras.",
		},
