		[8728] = {
			title = "Buenas y malas noticias",
			accept = "Vaya, ha llevado más tiempo del que esperaba. Ahora deja que vea qué dice este libro de contabilidad.$B$B<Narain lee el libro en silencio y murmura de vez en cuando.>$B$BLa buena noticia es que estoy seguro al 99% de que podré crear una boya de arcanita que funcionará como tú quieres. Eso, claro está, depende de la mala noticia...$B$BLa mala noticia es que voy a necesitar mucha arcanita, elementium y unas gemas raras.$B$BTráeme lo que necesito y te haré la boya.",
			complete = "Un trato es un trato. Espero que sepas en lo que te estás metiendo, $n. Esto es un gran problema de pesca.",
		},
		[8729] = {
			title = "La cólera de Neptulon",
			accept = "¿Te he dado ya la mala noticia? Se llama Fauces: 30 metros de muerte y destrucción. Supongo que me he olvidado esa menudencia.$B$BMi superior clarividencia psico-psiónica me indica que el mejor lugar para lanzar esta boya está en la costa de Azshara: la Bahía de la Tempestad.$B$BBusca un remolino lleno de restos de naufragios.$B$BPor cierto, espero que tengas amigos.$B$BY, si por algún milagro, tienes éxito, lleva el fragmento de cetro a Anacronos.",
			complete = "Bien hecho, $n. Pronto podré reformar el cetro de las arenas movedizas.",
		},
		[8730] = {
			title = "La corrupción de Nefarius",
			accept = "¿Eres tú, Campeón? Mil años hace que me fue confiado este fragmento, y en triste hora vienen a arrebatármelo... Pero ¿qué sería una tragedia sin crueldad?$B$B<Vaelastrasz tose débilmente.>$B$BEl... El fragmento de cetro está en poder de Nefarius.$B$BEl tiempo corre en nuestra contra. Nefarius planea destruirlo. ¡Apresúrate!",
			complete = "El alma de Vaelastrasz está en paz, $gcampeón:campeona;. Todos los Aspectos observan tu progreso con gran interés. Debes saber que tiene aliados poderosos.$B$BSe me ordenó que te conceda algo que te ayude en esta lucha. Úsalo bien...",
		},
		[8731] = {
			title = "Servicio de campo",
			accept = "Hola, $N. Antes de poder asignarte tareas más complicadas en la guerra, tendrás que hacer tu parte en el campo de batalla.$B$BEncontrarás al capitán Machacacráneos de la Legión de Orgrimmar fuera de Colmen'Regal.$B$BPreséntate ante él y vuelve a verme con alguna prueba de tu servicio. Tendré una misión más avanzada lista para ti.$B$BOh y, por favor, no te acerques a la Brigada de Forjaz. Hay mucha tensión entre nuestros voluntarios de la Alianza y la Horda.",
			complete = "Puedo decir que Krug tiene poca habilidad para el papeleo. ¡Lo firmó con sangre silítida!$B$BMuy bien, $n. He preparado un conjunto de tareas que deberían hacer un buen uso de tus habilidades como $c.$B$BCon tus continuos esfuerzos los de otros como tú, ¡nuestro enemigo pronto será aplastado!",
		},
		[8732] = {
			title = "Documentación de instrucción de campo",
			complete = "Sí, supongo que esa pequeña escaramuza pasará a ser un deber de campo hoy en día. Llévalos de regreso a Fuerte Cenarion, estoy seguro de que tendrán un trabajo a tu medida.$B$B¡Márchate!",
		},
		[8733] = {
			title = "Eranikus, el Tirano del Sueño",
			accept = "Este es un viaje de redención, $ghéroe:heroína;. Si la muerte viniera a buscarme hoy, habría muerto por una causa justa. Debes recuperar el fragmento de cetro verde. Debes librar a Eranikus de la mácula con la que los dioses antiguos le han mancillado.$B$BViaja a Darnassus. Fuera de la ciudad encontrarás a uno de mis agentes. Este agente pondrá el mecanismo en marcha e informará a Tyrande de nuestros planes sin alertar a Corzocelada.$B$B<Malfurion suspira.>$B$BUna caída en desgracia que lleva fraguándose mil años...",
			complete = "La brizna está en silencio excepto por un suave zumbido. Curiosamente, es capaz de comunicarse contigo a través de pensamientos.",
		},
		[8734] = {
			title = "Tyrande y Remulos",
			accept = "Tyrande sabrá de esto, mortal. Shan'do Tempestira me ha preparado para esta contingencia.$B$BAhora debes ir a Claro de la Luna a hablar con Remulos. Él tendrá más instrucciones para invocar a Eranikus.$B$BBuena suerte.",
			complete = "Sería imposible sacar a Eranikus del Sueño si se negaba. Sin embargo, sus intenciones requieren que entre en nuestro mundo. Busca destruir la manifestación viviente de Malfurion. Hacer esto significaría el fin de uno de los aliados más poderosos del Sueño. La Pesadilla consumiría por completo todo lo que queda si Malfurion cayera...",
		},
		[8735] = {
			title = "La corrupción de Pesadilla",
			accept = "Debes ir a los cuatro portales del Sueño de Azeroth. Debes conseguir un fragmento de Corrupción de Pesadilla en cada uno de ellos. Están en poder de los dragonantes que viven allí. Regresa cuando hayas conseguido los fragmentos.",
			complete = "¿Estas $gpreparado:preparada;? ¿Está el mundo preparado para lo que vamos a invocar? No lo sé... estoy obligado por el deber hacia Malfurion. Deber y honor...",
		},
		[8736] = {
			title = "La Pesadilla se manifiesta",
			accept = "Debemos restringir el uso de la fuerza contra Eranikus. Queremos redimirlo, no aniquilarlo.$B$BTyrande está de camino para ayudarnos. Hemos de resistir las embestidas del dragón y salvar Amparo de la Noche.$B$B¡No bajes la guardia! Tú y tus aliados sois nuestra única esperanza.|n",
			complete = "Está redimido, $n. Ahora regresa al Sueño para corregir lo que solo él ha hecho mal. Eranikus será un poderoso aliado para Malfurion y mi padre.$B$BEste armamento que me dio la propia Ysera es para ti, $n. Harías bien en utilizarlo en tus batallas contra los qiraji.",
		},
		[8737] = {
			title = "Templario azur",
			accept = "El Martillo Crepuscular y los nobles elementales a quienes adoran, suponen una amenaza formidable para nuestras operaciones en Silithus. Con los nuevos enemigos a los que nos enfrentamos dentro de Ahn'Qiraj, no podemos permitirnos bajar la guardia con nuestros enemigos del exterior.$B$BEncuentra la forma de invocar y destruir a un Templario azur y vete a informar a Bor Ferocrín.",
			complete = "Buen trabajo, $n. Aquí está tu próxima tarea.",
		},
		[8738] = {
			title = "Informe de exploración de Colmen'Regal",
			accept = "Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. El explorador Landion lleva varios días observando los movimientos de los silítidos en Colmen'Regal. Encuéntrale y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, $n.",
			complete = "Apreciamos mucho tus esfuerzos, $n. Leeré estos informes de exploración de inmediato, siéntete libre de repasar tu próxima tarea.",
		},
		[8739] = {
			title = "Informe de exploración de Colmen'Ashi",
			accept = "Hemos enviado a nuestros mejores exploradores a las colmenas de silítidos para reunir información. La exploradora Jalia lleva varios días observando los movimientos de los silítidos en Colmen'Ashi. Encuéntrala y consigue un informe por escrito. Necesitamos esa información lo antes posible para saber cómo actuar, $n.",
			complete = "Apreciamos mucho tus esfuerzos, $n. Leeré estos informes de exploración de inmediato, siéntete libre de repasar tu próxima tarea.",
		},
		[8740] = {
			title = "Los merodeadores Crepusculares",
			accept = "Hemos avistado bandas de adeptos montados del Martillo Crepuscular asaltando a nuestras patrullas y caravanas más pequeñas, pero quedan fuera del alcance de nuestras tropas en el Fuerte Cenarion.$B$BEncuentra y derrota a los forajidos y a su líder, un terrible guerrero llamado Morna. Vete a informar a Clamavientos Cuerno Digno cuando completes la misión.",
			complete = "Bien hecho, $n. Los merodeadores crepusculares estaban causando un número inaceptable de bajas en nuestras patrullas. Aquí está su próxima tarea.",
		},
		[8741] = {
			title = "El regreso del Campeón",
			accept = "El guardián te espera, $n. Lleva el fragmento de cetro verde a Anacronos, que está en las Cavernas del Tiempo.|n",
			complete = "Tus obras serán conocidas por todos, $gcampeón:campeona;. Cantarán tus alabanzas desde Orgrimmar hasta los confines de los Mares del Sur. Todos sabrán $gdel campeón:de la campeona; del Vuelo de Bronce, $n.",
		},
		[8742] = {
			title = "El poder de Kalimdor",
			complete = "Han pasado mil años y, tal como estaba predestinado, $guno:una; está frente a mí. $gUno:Una; que guiará a su pueblo a una nueva era.$B$BEl Dios Antiguo tiembla, $n. Oh, sí, teme tu fe. Rompe la profecía de C'Thun.$B$BSabe que vienes, $gcampeón:campeona;, y que contigo viene el poder de Kalimdor. Solo tienes que avisarme cuando estés $gpreparado:preparada; y te concederé el Cetro de las arenas movedizas.",
		},
		[8743] = {
			title = "Golpear el gong",
			complete = "Del suelo cerca del gong brota un cristal especial. Quizás el favor de la Prole.",
		},
		[8744] = {
			title = "Un presente envuelto con cuidado",
			complete = "La etiqueta de este regalo dice:$B$BPara $n:$B$B¡Que pases unas dulces y felices fiestas del Gran Invierno!",
		},
		[8745] = {
			title = "El tesoro del Atemporal",
		},
		[8746] = {
			title = "Metzen el reno",
			accept = "¡Qué TRAGEDIA! ¡Han secuestrado a Metzen el Reno!$B$BMetzen el Reno es uno de los ocho renos del Gran Padre Invierno (y propiedad de Pastos de Bosquehumeante). Hemos recibido no una, sino DOS cartas de rescate de grupos que afirman tener a Metzen. La temporada de fiestas ya está en marcha, ¡y nuestros bolsillos están casi vacíos! Por favor, ¡encuentra a Metzen y tráenoslo de vuelta!$B$BBusca pistas en las cartas de rescate, y échale este polvo de reno, ¡lo liberará de todas sus ataduras!$B$B¡Por favor, apresúrate!",
			complete = "¡Bravo!$B$BMetzen ya está a salvo en los establos de Papá Invierno. ¡Sabía que el polvo funcionaría! Has salvado el Festival de Invierno y a Pastos de Bosquehumeante, $n.$B$BAcepta esto como prueba de gratitud; te gustará. ¡Feliz Festival de Invierno!",
		},
		[8747] = {
