		[8778] = {
			title = "¡La Brigada de Forjaz necesita explosivos!",
			accept = "La Brigada de Forjaz ha solicitado un extraño pedido de componentes... muy volátiles. Reúnelos y llévaselos al señor Bocafuente de la Brigada de Forjaz.",
			complete = "¡Ah, sí! ¡Estos serán útiles! ¡Muchas gracias, $n!",
		},
		[8779] = {
			title = "Materiales de visión",
			accept = "Los estudios de la Geóloga Trotuina han demostrado ser de gran valor para nuestras operaciones en Silithus. Recientemente, ha solicitado materiales de visión para utilizar en su investigación.$B$BPor favor, consigue esos materiales y llévaselos directamente a ella para que pueda continuar con su investigación.",
			complete = "Pues sí... ¡serán de gran ayuda! Estos materiales son muy difíciles de conseguir en el desierto, $n. Gracias.",
		},
		[8780] = {
			title = "Refuerzos para armadura para el campo de batalla",
			accept = "El suministro de refuerzos para armadura de la Brigada de Forjaz en el campo de batalla, está empezando a escasear peligrosamente. Consigue un lote de refuerzos y llévaselo a Janela Martillotenaz en la Avanzada de la Brigada de Forjaz, justo fuera de Colmen'Zora.",
			complete = "Gracias, se las daré a los muchachos.",
		},
		[8781] = {
			title = "Armas para el campo de batalla",
			accept = "La Brigada de Forjaz ha sido un poderoso aliado en nuestra batalla en Silithus. Por desgracia, perdieron muchos suministros de camino hacia aquí. Consigue un lote de armas y llévaselo a Janela Martillotenaz, está cerca de Colmen'Zora.",
			complete = "¡Oh, excelente! Ya no tendré que escuchar quejas sobre cuchillas desafiladas. Gracias, $n.",
		},
		[8782] = {
			title = "Suministros para uniformes",
			accept = "La última entrada de voluntarios ha provocado escasez de uniformes. Consigue un lote de materiales de uniforme y llévaselo a Clamavientos Cuerno Digno.",
			complete = "Ah, los necesitábamos. Se agradece tu trabajo, $n.",
		},
		[8783] = {
			title = "Materiales encantados",
			accept = "Vargus, el herrero del Fuerte Cenarion, ha solicitado materiales encantados para crear poderosas armas para nuestras tropas. Consíguelos y llévaselos directamente a Vargus para que las tropas del Fuerte Cenarion puedan seguir estando bien equipadas.",
			complete = "Ah, sí. Estos materiales son de excelente calidad. Gracias, $n.",
		},
		[8784] = {
			title = "Los secretos de los qiraji",
			accept = "¡Has descubierto un antiguo artefacto de Ahn'Qiraj! Esta reliquia quizás sea de utilidad para uno de los dragones que se encuentra cerca de la puerta del templo.",
			complete = "Un hallazgo extraordinario, $n. ¡Sencillamente maravilloso! Con esto seguro que lograremos penetrar en las perversas mentes de nuestro enemigo.",
		},
		[8785] = {
			title = "¡La Legión de Orgrimmar necesita mojo!",
			accept = "La Legión de Orgrimmar ha solicitado varios ingredientes muy poco usuales. Dada su situación actual en Silithus, queremos entregarles los suministros tan pronto como podamos. Reúne los materiales y llévaselos a la trol llamada Shai.",
			complete = "Ah, sí. ¡Justo lo que necesitaba! Haré un brebaje especial con esto. ¡Al silítido no le gustará nada!",
		},
		[8786] = {
			title = "Armas para el campo de batalla",
			accept = "La Legión de Orgrimmar ha solicitado unas armas adicionales que no hemos sido capaces de suministrar. Consigue las armas que nos han pedido y llévaselas a Merok Zancada Larga fuera de Colmen'Regal.",
			complete = "Excelente trabajo. Estábamos escasos de esto, $n.",
		},
		[8787] = {
			title = "Refuerzos para armadura para el campo de batalla",
			accept = "Los valientes voluntarios de la Legión de Orgrimmar han venido a Silithus para ayudarnos en nuestra causa. De alguna forma, perdieron sus refuerzos para armadura durante el viaje. Consigue un lote de armaduras y llévaselas a Merok Zancada Larga al campamento de la Legión de Orgrimmar.",
			complete = "Ah, sí... se los distribuiré a las tropas, $n. ¡La Legión de Orgrimmar te lo agradece!",
		},
		[8788] = {
			title = "Un obsequio ligeramente agitado",
			complete = "Parece que han agitado este regalo un par de veces. Su etiqueta dice:$B$BPara $gun:una; $r $c muy especial.",
		},
		[8789] = {
			title = "Armamentos imperiales qiraji",
			accept = "No hemos estado ociosos durante un milenio, $N.$B$BHemos observado a estas bestias alimentarse de los suyos cuando pierden su utilidad. Hemos escuchado cómo tramaban y se confabulaban para destruir nuestro mundo. Y nos hemos enterado de sus propias traiciones internas.$B$BExisten puntos débiles y sabemos cómo usarlos a nuestro favor.$B$BEncuentra sus armamentos ceremoniales y tráemelos. Combinados con el elemento creado a partir de la volatilidad de su propio Dios, se convertirán en una fuerza considerable.",
			complete = "Imbuidas de elementium, estas armas atravesarán a los qiraji y a su dios con increíble facilidad.",
		},
		[8790] = {
			title = "Atavío imperial qiraji",
			accept = "Según una teoría de Arygos el elemento nacido de conflictos entre los dioses antiguos y sus esbirros también es extremadamente fatal para ellos si se dan las condiciones adecuadas. Me refiero al elementium, mortal.$B$BEncuentra un atavío imperial qiraji y tráemelo junto con el elemento tóxico para infundir con ellos armas de gran poder.|n",
			complete = "Usa bien el objeto, $n. Haz que sientan el dolor que tanto les gusta infligir a los demás.",
		},
		[8791] = {
			title = "La caída de Osirio",
			accept = "Se acabó esa terrible amenaza. El cruel Osirio ha sido derrotado.$B$BLos vecinos de Kalimdor sentirán gran alivio cuando conozcan la noticia. Coge la cabeza de Osirio y llévasela al comandante Mar'alith de Fuerte Cenarion.",
			complete = "Recibe mis más elevados elogios y el objeto de poder que prefieras, $n. Le has prestado un gran servicio al pueblo de Kalimdor.",
		},
		[8792] = {
			title = "¡La Horda te necesita!",
			accept = "Hola, ¡qué bien que hayas decidido escucharme! La Horda necesita toda la ayuda posible para preparar la guerra de Ahn'Qiraj ¡y eso significa que te necesitamos a ti también! En este mismo instante, los recolectores oficiales están reuniendo el material necesario para la guerra que se avecina, pero no lograremos nuestro objetivo sin tu ayuda, $N!$B$BDeberías hablar con quien está al mando, el señor de la guerra Gorchuk. ¿Qué me dices, $c? ¿Nos ayudarás con estos preparativos vitales?",
			complete = "¡Throm'ka, $c! Es bueno ver a tantos miembros de la Horda, como tú, $n, salir a prestar tu apoyo para sentar las bases de la próxima Guerra de Ahn'Qiraj. El esfuerzo aquí garantizará la victoria contra los silítidos y sus malvados amos escondidos dentro de Ahn'Qiraj.$B$BAhora que estás aquí, asegúrese de hablar con los diversos recolectores y ofrecer tu ayuda para reunir los materiales que necesitan.",
		},
		[8795] = {
			title = "¡La Alianza te necesita!",
