		[8857] = {
			title = "Los secretos de los Colosos: Ashi",
			accept = "Busco gente osada con experiencia para llevar una muestra de la coraza del coloso de Ashi muerto a Oglethorpe a Bahía del Botín. No, no tienes que acercarte al cadáver, tengo un fragmento aquí. Pero date prisa, ¡la coraza no le servirá si está podrida!",
			complete = "¡Qué magnífica coraza! ¡Buen trabajo!",
		},
		[8858] = {
			title = "Los secretos de los Colosos: Regal",
			accept = "Nada me gustaría más que estampar esta coraza de bicho en la cara de Puñaceite... Pero aquí estoy, recogiendo muestras para esa cucaracha hipertrofiada. Con lo grande que es el bicho, estaré aquí hasta que cante el gallo.$B$BLlévale la muestra a Puñaceite, $c, y date prisa: ¡paga muy bien!$B$BVe a Puesto del Torio, en La Garganta de Fuego.",
			complete = "Magnífico; con esto se podría crear una armadura excelente. Ten, la recompensa prometida.",
		},
		[8859] = {
			title = "Los secretos de los Colosos: Zora",
			accept = "Mis sirvientes por poco pierden la vida intentando recuperar esta muestra. ¡Debes darte prisa! Lord Maxwell Neófitus la necesita. ¡Opina que los secretos de este coloso nos ayudarán en la guerra contra la Plaga!$B$B¡¿Qué haces todavía por aquí?! ¡Ve a Esperanza de la Luz! Y recibirás una sabrosa recompensa por tus servicios...|n",
			complete = "¡Justo a tiempo! ¡Buen trabajo!",
		},
		[8860] = {
			title = "¡Las fiestas de Año Nuevo!",
			accept = "¡Ventormenta celebra un festival por año nuevo! ¡Habrá bebidas gratis todo el día y fuegos artificiales por la noche! Seguro que está muy bien, pero también hay fiesta en la Bahía del Botín y apuesto a que es mejor.$B$BEn todo caso, Allison, la tabernera de Ventormenta, necesita comida de Pastos de Bosquehumeante para los juerguistas. ¿Puedes llevársela tú?$B$B¡Gracias, $n! La tabernera Allison está en La Rosa Áurea, en el Distrito de Mercaderes de Ventormenta.",
			complete = "¡Ah, la comida de Pastos de Bosquehumeante! ¡Estupendo!$B$BGracias, $n. Acepta esto como recompensa; y ahora, ¡sal a beber y a divertirte!",
		},
		[8861] = {
			title = "¡Las fiestas de Año Nuevo!",
			accept = "¡Cima del Trueno va a celebrar el Año Nuevo! ¡Habrá bebidas durante todo el día, y por la noche tirarán fuegos artificiales!$B$BSeguro que está muy bien, pero también hay fiesta en la Bahía del Botín y seguro que es mejor.$B$BEn todo caso, Pala, la tabernera de Cima del Trueno, necesita provisiones de Pastos de Bosquehumeante para los juerguistas. ¿Puedes ir tú a llevársela?$B$B¡Gracias, $N! La tabernera Pala está en la posada cerca del puente a Alto de los Cazadores.",
			complete = "¡Oh muy bien! ¡Estos suministros ayudarán a alimentar a nuestra gente para celebrar el año nuevo!$B$BGracias, $n. Estoy en deuda contigo. Por favor, toma estas monedas... y sigue mi consejo: bebe con entusiasmo de los barriles de afuera y únete a nuestros juerguistas en un baile de celebración.",
		},
		[8862] = {
			title = "Vela de Elune",
			complete = "Muy bien, acepto estas monedas de linaje. Por favor, llévate la vela de Elune con mi bendición. Además, disfruta de estos fuegos artificiales de cortesía.$B$BQue tu Festival Lunar sea jubiloso y lleno de alegría, $n.$B$BY si eliges enfrentarte a Omen y sus secuaces, encontrarás la vela de Elune bastante útil...",
		},
		[8863] = {
			title = "Albóndigas festivas",
			complete = "Excelente, disfruta de estas albóndigas con mis cumplidos. Si bien no son más que una pequeña muestra de agradecimiento por el honor que te has traído a ti $gmismo:misma; a través de tus acciones, creo que las disfrutarás de todos modos.$B$BSi tienes más monedas de linaje, estoy listo para ofrecerte una amplia gama de artículos a cambio.",
		},
		[8864] = {
			title = "Vestidos para el Festival Lunar",
			complete = "Muy bien, acepto estas monedas de linaje. Por favor, llévate tu vestido con mi bendición. Además, disfruta de estos fuegos artificiales de cortesía.$B$BComo has honrado a tus mayores, me honras a mí con tu mera presencia. Gracias, y que tu Festival Lunar sea feliz.",
		},
		[8865] = {
			title = "Trajes pantalón para el Festival Lunar",
			complete = "Muy bien, acepto estas monedas de linaje. Por favor, llévate tu pantalón con mi bendición. Además, disfruta de estos fuegos artificiales de cortesía.$B$BSi tienes más monedas de linaje para comerciar, vuelve a hablar conmigo. Ofreceré varios artículos durante todo el Festival Lunar.",
		},
		[8866] = {
			title = "Barbabronce el Ancestro",
			complete = "Me alegra saber que la gente de estas tierras sigue prestando homenaje a las antiguas razas. Te deseo todo lo mejor, $n, y te ofrezco esta muestra...",
		},
		[8867] = {
			title = "Fuegos artificiales lunares",
			accept = "Todos los años los druidas del Claro de la Luna celebran la gran victoria de nuestra ciudad sobre un antiguo mal.$B$BCelebramos la sabiduría de nuestros ancestros, participamos en magníficas fiestas y, por supuesto... ¡disparamos fuegos artificiales!$B$BA cambio de una pequeña donación puedes adquirir cohetes de colores de nuestro vendedor. Prueba a usarlos en uno de los lanzacohetes que hay por aquí, $N.",
			complete = "Bien hecho, $n.$B$BAhora que ya estás metido en el ambiente, ¿por qué no aceptas esta invitación al Festival Lunar?$B$BEs una celebración fantástica si tienes algo de tiempo. Hay comida, bebida, se cuentan cuentos y... claro, ¡hay más fuegos artificiales!$B$BAbre la invitación cuando estés dentro del círculo de La Gran Luz de Luna y serás transportado directamente al Claro de la Luna.",
		},
		[8868] = {
			title = "La bendición de Elune",
			accept = "La bestia Augurio fue un héroe de este mundo en otros tiempos. Era un lobo de gran fuerza y fortuna que luchó junto a los héroes de la Guerra de los Ancestros hasta que cayó víctima de una magia demoníaca. Se volvió contra sus aliados y arrasó Azeroth dejando una estela de terror y muerte a su paso.$B$BFue derrotado aquí, en Claro de la Luna, y descansa en el cieno del Lago Elune'ara. Pero cada año nuevo, durante el festival, se agita en su sueño eterno...$B$BRecluta un ejército, $n, y junto a él invoca y derrota a la bestia. ¡Merecerás la bendición de Elune!",
			complete = "Buen trabajo, $n. Augurio no puede morir porque tiene la bendición de Elune, pero al menos reposará tranquilo un año más.$B$BBrindemos por el poder de Augurio, por el tuyo, $n, y porque has dado un poco de paz al héroe.",
		},
		[8870] = {
			title = "El Festival Lunar",
			accept = "¡Ha llegado ese momento del año, $n! El Círculo Cenarion invita a todos los ciudadanos de Azeroth a participar en la celebración del Festival Lunar. Encontrarás a la presagista del Festival Lunar en esta misma ciudad. Busca el lugar marcado por un círculo sagrado de Luz de Luna. Ella podrá decirte más cosas sobre el Festival.",
			complete = "Te doy la bienvenida, $n. ¿Vienes a unirte a nuestras celebraciones?",
		},
