		[9022] = {
			title = "La despedida de Anthion",
			accept = "Este amuleto contiene el alma de Valthalak. Nuestra avaricia nos hizo dividirlo en tres partes, pues no sabíamos nada de la maldición que eso nos depararía.$B$BLa única forma de anular el hechizo de Valthalak es volver a reunir las partes del medallón. Dile a Mokvar que Bodley es su único medio de encontrar las partes que faltan. Si hay alguna recompensa pendiente, háblalo con él.$B$BPor una vez, yo voy a descansar en paz. Suerte. ¡Vas a necesitarla!",
			complete = "Esta maldición nos fue otorgada por un simple medallón. Lord Valthalak ciertamente sabe cómo guardar rencor.$B$BNos esforzaremos por encontrar las piezas restantes, con suerte antes de que me encuentre con una muerte prematura. Pero antes de eso, veamos cuál es tu recompensa.",
		},
		[9023] = {
			title = "El veneno perfecto",
			accept = "Mi hermano y yo nos ocupamos del transporte de veneno desde la mansión Ravenholdt.$B$BLord Ravenholdt me encargó que localizara un compuesto venenoso nuevo y muy efectivo que se puede producir con las glándulas de veneno de las arañas de Zul'Gurub y las Ruinas de Ahn'Qiraj.$B$BEn las ruinas hay dos arañas especialmente venenosas que tienen lo que estoy buscando, $c. Tráeme glándulas de veneno de Kurinnaxx y Venoxis y tendrás nuestro agradecimiento eterno.",
			complete = "¡Tienes la gratitud de Ravenholdt! ¡Elige lo que quieras!",
		},
		[9024] = {
			title = "El presentimiento de Aristan",
			accept = "¡Ya lo tengo! ¿Te has fijado en la fragancia que lleva el viento? Se han puesto de moda una serie de perfumes y colonias. Nuestros guardias no descuidarían sus obligaciones así como así.$B$BA no ser que estén dominados por alguna alquimia maléfica.$B$BSolo hay un modo de averiguarlo: llévale una botella de colonia y una de perfume a Morgan Mortero y cuéntale lo que te he dicho. Te pagaré lo que te hayan costado las fragancias cuando vuelvas.",
			complete = "Entiendo a Aristan, pero creo que exagera. Me parece que ha olvidado lo que es ser joven y ardiente.$B$BPero no se lo vayas a decir; no creo que se lo tomara bien.",
		},
		[9025] = {
			title = "El descubrimiento de Morgan",
			accept = "Vaya, vaya. Puede que Aristan tenga razón. He encontrado restos de sustancias que se usan en elixires amorosos y jarabes para manipular la mente.$B$BNo es la primera vez que se usan en perfumería, pero algunos de los ingredientes que he detectado... huelen raro.",
			complete = "Me inquieta sobremanera comprobar que mis sospechas eran correctas. Debemos ser cautos.$B$BTen, por el perfume y la colonia.",
		},
		[9026] = {
			title = "Rastrear la fuente",
			accept = "Tenemos que encontrar el origen. He visto a más gente de lo normal, guardias incluidos, entrando y saliendo de La Rosa Áurea. Habla con Allison. Si es ella la que vende los perfumes, podrá decirte dónde los consigue.",
			complete = "Sí, acabo de recibir el perfume y la colonia y se venden muy bien; vamos, me los quitan de las manos.$B$BLa verdad es que es un poco aburrido, ahora todo el mundo huele igual.",
		},
		[9027] = {
			title = "Rastrear la fuente",
			accept = "¿Si he notado algo raro en la colonia? Puede ser, nunca había visto a la gente entusiasmarse tanto con un producto.$B$BOye, si pasa algo con el perfume, quiero saberlo. Se lo compré a un comerciante que se llama Evert Sorisam. Acaba de mudarse.$B$BDijo que tenía que hacer una entrega en El Paño Fino.",
			complete = "Sí, estas fragancias son el éxito de la temporada; no deja de venir gente preguntando por ellas.$B$BAquí se han agotado las existencias; prueba con Allison, la posadera de La Rosa Áurea.$B$BPero date prisa; te digo que esas fragancias son irresistibles.",
		},
		[9028] = {
			title = "El descubrimiento de la fuente",
			accept = "¿Qué? ¿Traición? No, no. Te aseguro que mis intenciones son buenas.$B$B¿Qué tiene de malo ayudar a los tímidos en el difícil arte del cortejo? Eso no tiene nada de malo.$B$BY para que veas que no tengo nada que esconder, te voy a decir quién me provee.$B$BLos perfumes me los envía Staffron Lerent, una especie de boticario. No he hablado con él directamente.$B$BEl intermediario goblin me dijo que trabaja en las Laderas de Trabalomas, más allá de la misteriosa Mansión Ravenholdt. Espero que consigas localizarlo.",
			complete = "Sí, yo creé esas fragancias. ¿A que son magníficas?$B$BLos soldados de la Alianza y de la Horda estarán tan distraídos con sus amoríos que no podrán detener el avance del Consejo de la Sombra.$B$BEstarán debilitados y desprevenidos.$B$BEs un truco tan sencillo que no comprendo cómo no se me ocurrió antes. Y tú no puedes hacer nada para evitarlo.",
		},
		[9029] = {
			title = "Una caldera burbujeante",
			complete = "Del caldero emana un aroma agradable.",
		},
		[9032] = {
			title = "El triste destino de Bodley",
			accept = "¡¿Que el medallón contenía el alma de Valthalak?! No me extraña que tan poderosa maldición lo custodiara.$B$BPara encontrar a Bodley hay un pequeño inconveniente. Lo último que supe de él es que se estaba preparando para aventurarse de nuevo en la Cumbre de Roca Negra. Nunca más se supo de él.$B$BBúscalo en la Montaña Roca Negra, aunque mucho me temo que probablemente haya muerto. Te sugiero que te lleves contigo el dispositivo de los goblins, $gamigo:amiga;.",
			complete = "Estoy tan contento de que puedas verme. ¡Finalmente alguien con quien hablar!$B$B¿Nos ayudarás, $n? ¿Ayudarás a reparar el mal que perpetramos y arreglarás las cosas? Si es cierto que ya tienes la Pieza Superior del Amuleto de Lord Valthalak, entonces creo que puedo ponerte en la dirección correcta para conseguir las otras dos partes, reunirlas y acabar con todo esto.$B$BAh, por cierto, hola, mi nombre es Bodley. ¡Un placer conocerte!",
		},
		[9033] = {
			title = "Ecos de Guerra",
			accept = "Hace cinco años que terminó la última guerra...$B$BDecenas de miles de vidas perdidas, ¿y para qué? La amenaza no fue exterminada.$B$BEl Rey Exánime vuelve a la vida... Su lugarteniente, Kel'Thuzad, prepara otro ataque a nuestras tierras.$B$B¡No podemos permitirlo! Demuéstranos que lo arriesgarás todo para detener esta locura y tendrás a las fuerzas de la Cruzada y de El Alba a tu disposición.$B$BVe a Naxxramas y elimina la Plaga.",
			complete = "¡Buen trabajo! Recibirás tu recompensa mediante los servicios de los habitantes de la Capilla de la Esperanza de la Luz.",
		},
		[9034] = {
			title = "La coraza acorator",
			accept = "Si mientras luchas contra la Plaga en Naxxramas encuentras restos de corazas y de almenas profanadas, tráemelos y te haré una armadura digna de un héroe.",
			complete = "¡Excelente $n! obtuviste todo tal como te pedí y ahora puedo hacer una coraza acorator.",
		},
