		[9248] = {
			title = "Una humilde ofrenda",
			accept = "Ishnu-alah, $r. Dame una prueba de la muerte de un Señor del Consejo Abisal y te recompensaré con un objeto que te ayudará a luchar contra los qiraji.",
			complete = "Ande'thoras-ethil. en mi lengua materna significa; 'Que tus problemas disminuyan'.$B$BUse la banda con orgullo y con buena salud, $n.",
		},
		[9250] = {
			title = "Cuerpo de Atiesh",
			accept = "Con la formación del cuerpo, Atiesh ya está casi completo. Solo falta la cabeza y la base del báculo. Y está el problema menor de que el bastón es un conducto de la maldad de Sargeron.$B$BBusca a alguien que te ayude a buscar las piezas que faltan y a exorcizar el bastón.",
			complete = "Los archimagos han muerto.$B$BNo lamentes su muerte, $n. Todas esas cosas están predestinadas. Así como estaba destinado a sostener el bastón del Guardián...",
		},
		[9251] = {
			title = "Atiesh, el gran báculo maligno",
			accept = "Te preguntas cómo es que sigues con vida. Después de todo, tienes en tu poder un objeto de gran maldad. No hay una respuesta clara, $n. Yo solo hago lo que debo hacer.$B$BKel'Thuzad está sentado sobre su trono en Naxxramas, conspirando... Quiere lo que tú tienes y tiene lo que tú quieres.$B$BEl enano Brann Barbabronce llevaba la base del báculo cuando entró en Ahn'Qiraj. Se ha marchado, pero la base de Atiesh sigue en Ahn'Qiraj.$B$BSi consigues recuperar las piezas, ven a verme.",
			complete = "Hay un ser dentro... un ser que no es de este mundo.",
		},
		[9257] = {
			title = "Atiesh, el gran báculo del guardián",
			accept = "Esta última tarea es la más difícil, $n. Ya te has enfrentado a un dios antiguo y al Gran general del Rey Exánime, pero ahora debes enfrentarte al mismísimo Sargeron.$B$BLlévate el báculo a Stratholme, donde hay un lugar sagrado: el lugar en el que fueron masacrados los mejores caballeros de Lordaeron. Coloca el báculo en el suelo sagrado y prepárate para enfrentarte a un ente de inmenso poder... Derrota al ser diabólico que ha poseído el báculo y vuelve aquí.",
		},
		[9259] = {
			title = "Un traidor de Velasangre",
			complete = "Guardemos un minuto de silencio por nuestros compañeros caídos, $n.$B$B<El traidor Velasangre te sonríe y te guiña un ojo>.$B$BSer un traidor es una cosa, asesinar a tus propios compañeros... ¡eso sería absolutamente despreciable, sí!",
		},
		[9260] = {
			title = "Investigar la Plaga de Ventormenta",
			accept = "La Plaga ha erigido un campamento frente a nuestras puertas. ¡No podemos quedarnos de brazos cruzados! ¿Verdad que nos ayudarás a defender Ventormenta de estos malditos invasores? $B $BAfuera hay unos extraños círculos rúnicos que brillan con la misma energía que rodea a los no-muertos y la Necrópolis. Seguramente tienen algún significado; quiero que vayas a averiguarlo. Aprovecha para liquidar a unas cuantas de esas aberraciones. Tráeme pruebas de las muertes, además de respuestas, y te recompensaré. ¡Ve!",
			complete = "Hmm. Por lo que me dices, las voces dentro de los círculos... deben usarse como comunicación de algún tipo. Me estremezco al pensar en qué mentes antinaturales se contactan a través de tal magia. Independientemente, parece que has salido $gsano:sana; y $gsalvo:salva;. El Alba Argenta agradece tu servicio.",
		},
		[9261] = {
			title = "Investigar la Plaga de Forjaz",
			accept = "La Plaga ha erigido un campamento frente a nuestras puertas, ¡no podemos quedarnos de brazos cruzados! ¿Verdad que nos ayudarás a defender Forjaz de estos malditos invasores? $B $BFuera hay unos extraños círculos rúnicos que brillan con la misma energía que rodea a los no-muertos y la Necrópolis. Seguro que tienen algún significado; quiero que vayas a averiguarlo. Aprovecha para liquidar a unas cuantas de esas aberraciones. Tráeme pruebas de las muertes, además de respuestas, y te recompensaré. ¡Ve!",
		},
