		[9322] = {
			title = "Los fuegos salvajes de Kalimdor",
			accept = "El Festival de Fuego del Solsticio de Verano se celebra en todo Azeroth y las ricas tierras de Kalimdor no son una excepción. Parece que te gusta viajar; voy a darte un motivo para hacerlo.$B$BNo apreciarás realmente el solsticio de verano hasta que hayas visto las hogueras azules que arden por todas partes. Se han encendido hogueras en la helada Cuna del Invierno, al noreste de Azshara, cerca de Sosiego del Valor en los eriales de Silithus y junto a la entrada del exuberante Un'Goro. Regresa cuando hayas completado tu viaje.",
			complete = "Tu espíritu brilla con el calor de los fuegos de Kalimdor, $gamigo:amiga;. ¿El calor no es vigorizante? Una vez que el poder se desvanezca, tal vez esto ayude a reavivar el sentimiento.",
		},
		[9323] = {
			title = "Los fuegos salvajes de los Reinos del Este",
			accept = "Esta celebración de la llama se extiende por toda la tierra, $c. No hay un solo lugar que no sienta el calor de esta fiesta y las hogueras más brillantes resplandecen en azul. Búscalas.$B$BEncontrarás una justo al norte de Cumbre de Roca Negra. Las demás están en las Tierras de la Peste del Este cerca de una ciudad decrépita, en el camino a los precipicios en las Tierras del Interior y en el camino a El Portal Oscuro en Las Tierras Devastadas.$B$BVuelve cuando las hayas visto todas.",
			complete = "¡Te veo resplandeciente pese al polvo del camino y la fatiga! La llama nos une a todos; todo tu ser reluce con el poder de las hogueras que has tocado.$B$BPero imagino que también ansías una recompensa de tipo más material; aquí la tienes.",
		},
		[9324] = {
			title = "Robar la llama de Orgrimmar",
			accept = "Esta llama, robada del fuego del hogar de Orgrimmar, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",
			complete = "¡Oh! ¡O mucho me equivoco o esta llama viene del hogar de Orgrimmar! La fiereza de los orcos y los trols se refleja en su ardiente calor. ¡Has demostrado mucho valor al robar la llama sacra del enemigo!$B$BMe pregunto qué poderes acechan en las otras ciudades...",
		},
		[9325] = {
			title = "Robar la llama de Cima del Trueno",
			accept = "Esta llama, robada del fuego del chamán de Cima del Trueno, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",
			complete = "¡Esta llama ha sido tomada en Cima del Trueno! ¡Oye cómo canta con el poder de los espíritus! Tienes dedos ligeros, $n. Acepta esto en pago por tus servicios. Ah, si tuviera las llamas de las cuatro ciudades...",
		},
		[9326] = {
			title = "Robar la llama de Entrañas",
			accept = "Esta llama, robada de las ruinas que cubren Entrañas, te inunda de calor. No conoces este poder tan primitivo, pero puede que el maestro del Conocimiento tenga más información...",
			complete = "Qué llama tan peculiar... Está casi extinguida, pero sigue muy caliente. ¿Dices que viene de Entrañas? Fascinante. ¿Qué no podremos conseguir con las llamas de las cuatro ciudades?",
		},
