		[9362] = {
			title = "Señor de la guerra Krellian",
			accept = "¡No queda mucho tiempo, $n! Mis hechizos de visión han revelado una poderosa fuente de magia. No puedo abandonar la torre, así que te pediría que mataras a la vil criatura que posee este artefacto.$B$BEse patético cretino es conocido como señor de la guerra Krellian y se oculta tras sus guardias en el Templo de Zin-Malor. Redúcelo a cenizas y llévate la concha centelleante que tanto codicia.",
			complete = "Debo decir que esta concha tiene un aura extraño. Parece apropiado que parte de tu recompensa por recuperarlo sea probar sus capacidades mágicas...",
		},
		[9364] = {
			title = "Magia fragmentada",
			accept = "Gracias a mi investigación, he descubierto un propósito único de la concha centelleante.$B$BLlévatela y lanza tu hechizo polimórfico sobre las sirenas Látigo de Ira de Azshara. Si esperas un poco, el aura caótica de la concha las hará escindirse en varios clones más pequeños durante un rato. Mata a estos clones tan rápidamente como puedas y la concha recogerá su esencia.$B$BCuando esté llena, regresa aquí.",
			complete = "¡Espléndido! ¡Espléndido!$B$BAhora podemos recrear esta magia en un nuevo hechizo. ¡Mira!",
		},
		[9365] = {
			title = "Una recompensa de ladrón",
			accept = "Esta llama, robada del fuego del hogar de Ventormenta, te inunda de calor. No conoces este poder tan primitivo, pero puede que (NAME) tenga más información...",
			complete = "Hoy te has probado a ti mismo, $n.$B$BAunque tengo poco más para darte, tengo esta corona; un regalo apropiado para $gun conquistador:una conquistadora;. Que ilumine tu camino.",
		},
		[9367] = {
			title = "El Festival del Fuego",
			accept = "¡Ya ha llegado el solsticio de verano!$B$BCada año, como manda la tradición, se elige a los vigilantes de la llama, que se ocuparán de las hogueras sagradas en nuestras capitales. Aunque habrá hogueras por todo Azeroth, es imperativo que la nuestra sea la más viva para rendir homenaje a la celebración.$B$BDe hecho, tengo una tarea para ti, si no te importa. Aún no sé si las hogueras arden correctamente en todas las capitales. Ve a calentarte junto a cada una de las hogueras; ¡asegúrate de que calienten mucho!",
			complete = "¡Excelente! Me alegra saber que las hogueras arden correctamente este año. Gracias por ir a inspeccionarlas en mi lugar; acepta esto en prueba de mi gratitud.",
		},
		[9368] = {
			title = "El Festival del Fuego",
			accept = "¡Ya ha llegado el solsticio de verano!$B$BCada año, como manda la tradición, se elige a los vigilantes de la llama, que se ocuparán de las hogueras sagradas en nuestras capitales. Aunque habrá hogueras por todo Azeroth, es imperativo que la nuestra sea la más viva para rendir homenaje a la celebración.$B$BDe hecho, tengo una tarea para ti, si no te importa. Aún no sé si las hogueras arden correctamente en todas las capitales. Ve a calentarte junto a cada una de las hogueras; ¡asegúrate de que calienten mucho!",
			complete = "¡Excelente! Me alegra saber que las hogueras arden correctamente este año. Gracias por ir a inspeccionarlas en mi lugar; acepta esto en prueba de mi gratitud.",
		},
		[9386] = {
			title = "Una luz en la oscuridad",
			accept = "Me agrada tu entusiasmo. Si deseas volver a bajar a las profundidades, te recompensaré con sumo gusto.$B$BBusca las hogueras que arden en Stratholme, Scholomance, La Masacre y los salones de Cumbre de Roca Negra. Esperaré tu regreso, $n.",
			complete = "Has probado que no eres del todo inútil, mortal.",
		},
		[9388] = {
			title = "La oscilación de las llamas de Kalimdor",
			accept = "Hoy hay muchas llamas ardiendo en el mundo, $n. Las hogueras más difíciles de mantener son las verdes; hay que vigilarlas constantemente para que no se apaguen. Comprueba si siguen ardiendo las hogueras esmeraldas en Kalimdor, por favor.$B$BEstán en Los Baldíos cerca de Trinquete, en Costa Oscura cerca de La Espada del Maestro, en el bosque de Vallefresno junto al puente cerca de la Avanzada Ala de Plata y cerca del camino a Risco Cortaviento, siguiendo la ruta principal de Sierra Espolón.",
			complete = "Ahhh, todavía arden. Me alegro; no sería bueno que esos fuegos se apagaran antes de tiempo. Lo has hecho bien, $n. Toma esto con mi bendición.",
		},
		[9389] = {
			title = "La oscilación de las llamas de los Reinos del Este",
			accept = "El Festival de Fuego del Solsticio de Verano ilumina la tierra con una miríada de llamas. Hay quien dice que las hogueras verdes son las mejores, porque son las más difíciles de mantener y tienen un color tan particular.$B$BComprueba que siguen ardiendo en los Reinos del Este. Están cerca de Dun Modr, en Los Humedales, cerca de la Aldea Piroleña en el Bosque de Argénteos, en los precipicios junto al faro en los Páramos de Poniente y junto a la torre en ruinas de Laderas de Trabalomas.",
			complete = "¿Qué te han parecido las hogueras esmeralda? Son una visión magnífica, aunque seguro que esperas una recompensa más tangible; aquí tienes.",
		},
		[9415] = {
			title = "Preséntate ante el alguacil Murazul",
			accept = "¿Eres uno de los nuevos reclutas del alguacil Murazul? ¡Claro que sí!$B$B¿A qué esperas? Soldados muy valientes están muriendo en el desierto. ¿No sientes emoción al pensar que te vas a unir a ellos?$B$BAhora vamos, en marcha, y no te quedes $gseco:seca; por el camino.",
			complete = "La Alianza necesita todos las manos capaces que pueda conseguir. La Horda ha estado recibiendo un suministro constante de refuerzos de la parte norte del continente, y ha sido una lucha mantener el ritmo.$B$BDéjame explicarte la situación.",
		},
		[9416] = {
			title = "Preséntate ante el general Kirika",
			accept = "Tú debes ser uno de los nuevos reclutas del general Kirika. Ya era hora de que llegases. El desierto está plagado de cuerpos.$B$BLos enanos han estado recibiendo refuerzos constantemente y no podemos arriesgarnos a perder posiciones en nuestra lucha por los recursos de Silithus.$B$BEl general tiene unas instrucciones para darte. Mi misión no es instruirte, sino solamente encontrarte.",
			complete = "Es bueno que estés aquí, pero no hay tiempo que perder en charlas triviales. Necesitas instrucciones, y luego necesitas salir.$B$B$gAtento:Atenta;.",
		},
		[9419] = {
			title = "Peinando el desierto",
			accept = "Hace poco nos hemos enterado que la Horda ha estado escarbando el desierto de Silithus en búsqueda de recursos, pero poca atención le prestamos entonces. Pensamos que no valdría la pena establecer muchas tropas en este desierto calcinante.$B$BSin embargo, los recursos encontrados son de magna importancia y ahora tenemos que luchar para hacernos con ellos.$B$BSi contamos con tu ayuda, quizás puedas ir al desierto a recuperar la silitista y regresar aquí con ella.",
			complete = "Gracias a la Luz, tuviste éxito.$B$BAhora bien, si solo hubiéramos podido comenzar esto antes, nuestra necesidad no sería tan desesperada. Debemos evitar que la generosidad del desierto caiga en manos de la Horda.",
		},
		[9422] = {
			title = "Peinando el desierto",
			accept = "Desde hace algún tiempo que venimos extrayendo los recursos cristalíferos del desierto de Silithus. Los únicos peligros que encontramos, además de la arena, el calor y el polvo, provenían de criaturas que habitaban allí.$B$BPero ahora la Alianza parece estar interesada en lo que tenemos aquí. Esto se ha convertido en una carrera por capturar los recursos naturales.$B$BNecesito toda la ayuda disponible. Espero poder contar contigo.",
			complete = "Lo has hecho bien, $n. Estos recursos se agregarán a nuestras reservas, y cada migaja que sea para nuestro beneficio no lo es para nuestro enemigo.",
		},
		[9664] = {
			title = "Nuevas avanzadas",
			accept = "$gBienvenido:Bienvenida; a las Tierras de la Peste, $n. Como ya sabrás, los Renegados y sus aliados controlan las tierras al oeste de aquí, muy a nuestro pesar. Los Comandantes de la Alianza han decidido establecer nuevas fortificaciones aquí en el este con el objetivo de presionar al enemigo.$B$BLas torres, abandonadas desde los días de Lordaeron, han de ser recuperadas y reconstruidas. Estas tierras son peligrosas y tu ayuda será más que bienvenida.",
			complete = "Muy bien, $n. Será importante para nosotros mantener estas torres contra futuros ataques, y para eso es posible que necesitemos tu ayuda hasta que se puedan traer refuerzos para asegurar el área.",
		},
		[9665] = {
			title = "Fortalecimiento de nuestras defensas",
			accept = "Algunos agentes de los Renegados descubrieron un plan de la Alianza para establecer nuevas bases en las Tierras de la Peste del Este utilizando las torres abandonadas de la zona.$B$BEs realmente imperativo que no logren establecerse en nuestra frontera del este, por lo que debemos detener esta incursión de la Alianza. Nuestros planes actuales consisten en expulsarlos de las torres que ya hayan conquistado y en ocupar aquellas que tenemos bajo nuestro control para defenderlas de futuras agresiones.",
			complete = "Estas son buenas noticias, $n. Será una lucha constante aquí en las Tierras de la Peste hasta que hayamos rechazado por completo las fuerzas de la Alianza.$B$BHasta ese día, espero contar con tu asistencia continua.",
		},
		[65601] = {
			title = "El amor duele",
			accept = "Los sayaad machos son conocidos como íncubos. Son criaturas de mente particular e inmensa maldad.$B$BPara atraer al demonio a nuestro mundo, se necesita un objeto que lo tiente... un objeto que represente el amor y la devoción.$B$BSi confías en que un hombre ciego te guíe, $n, escucha. Al este del Circo de las Sombras, por la calle principal de Orgrimmar, vive Magar. Ansía el regreso de su compañero, Krilge.$B$BVe a buscarlo. Te pedirá que busques algo preciado. Eso es lo que debes llevarle a Gan'rul.",
		},
		[65602] = {
			title = "¿Qué es el amor?",
			accept = "Necesitarás un componente poderoso para tentar a un íncubo, un objeto que represente gran devoción y amor.$B$BGracias a mis habilidades de videncia, he encontrado una pequeña figurilla que debería servirte para tu ritual.$B$BHace miles de años, la figurilla le perteneció a una pareja joven. Los dueños originales ya no están entre nosotros, pero su reliquia ha sobrevivido hasta nuestros días.$B$BSigue el camino del norte hacia Vallefresno, y luego al oeste pasando la Atalaya de Maestra. Verás una casa entre los árboles. Ahí encontrarás lo que necesitas.",
		},
		[65603] = {
			title = "El vínculo",
			accept = "Llegó la hora. Toma la figurilla y baja a las criptas. Hay un círculo de invocación preparado, debes colocar la figurilla en el centro.$B$BEso abrirá el portal para que el íncubo cruce a nuestro mundo.$B$BNo hay que subestimar a un sayaad. El demonio no dudará en atacar cuando se dé cuenta de lo que planeas. Necesitarás de todos tus recursos para derrotarlo.$B$BSi triunfas, vuelve a verme y someteré a la criatura a tu voluntad. Si fallas, no habrá salvación para tu alma.",
		},
		[65610] = {
			title = "Ojalá estuvieras aquí",
			accept = "Conocí a Krilge fabricando tela lunar en Vallefresno. Estaba ahí para proteger a los civiles del peligro, hasta que despareció...$B$BDejaron de buscarlo y lo consideraron desertor, pero yo no creo eso.$B$BTeníamos la costumbre de encontrarnos en el Lago Cielo Estrellado antes de que lo invadieran esas bestias de ciénaga agresivas.$B$BNo suelo pedir favores, pero si pudieras ir a Vallefresno y buscar algún rastro suyo, te lo agradecería.",
		},
	},
